\section{Pseudo code}
We summarize our framework in Algorithm~\ref{alg:pretrain} and \ref{alg:finetune}.
\begin{algorithm}[ht]
\caption{Graph Contrastive Pretraining}
\label{alg:pretrain}
\begin{algorithmic}[1]
\State \textbf{Input:} Protein-ligand complexes $\mathcal{S}$, a GNN encoder $f_\theta$
\State \textbf{Output:} Pretrained parameters $\theta$ of encoder $f_\theta$

\For{each unlabeled protein-ligand complex in $\mathcal{S}$}
    \State Identify positive and two-category negative pairs
    \State Compute latent representation $\mathbf{z}=f_\theta(s)$ for them
    \State Compute contrastive loss $L_1$ (Equation 3)
    \State Sample gaussian noise $\epsilon$
    \State Apply noise to ligand coordinates: $\mathbf{x}' = \mathbf{x} + \epsilon$
    \State Compute denoising loss $L_2$ (Equation 4)
    \State Compute total loss: $\mathcal{L}$ (Equation 5)
    \State Update encoder parameters: $\theta \leftarrow \theta - \eta \nabla_\theta \mathcal{L}$
\EndFor

\end{algorithmic}
\end{algorithm}
\begin{algorithm}[ht]
\caption{Finetuning}
\label{alg:finetune}
\begin{algorithmic}[1]
\State \textbf{Input:} Pretrained encoder $f_\theta$, labeled protein-ligand complexes $S_l$ and a new regression head $g_\phi$ s.t. $\hat{y_k} = g_\phi (f_\theta({s_k}))$
\State \textbf{Output:} Fine-tuned parameters $\theta$ and $\phi$ 

\State Replace regression head $g_\phi$
\For{each labeled protein-ligand complex $s_k$ in $S_l$}
    \State Predict binding affinity: $\hat{y} = g_\phi(f_\theta(s_k))$
    \State Compute loss: $\mathcal{L}_{\text{finetune}} = \frac{1}{N} \sum_{i=1}^N (\hat{y}_i - y_i)^2$
    \State Update parameters: $[\theta, \phi] \leftarrow [\theta, \phi] - \eta \nabla_{\theta, \phi} \mathcal{L}_{\text{finetune}}$
\EndFor
\end{algorithmic}
\end{algorithm}



