\section{Preliminaries}\label{2}

This section describes some auxiliary results that we will need in the following sections.

\subsection{Local and global existence} Under \eqref{Conds0}-\eqref{Conds2}, in the flat bottom case one has that local and global well-posedness for the case of small data is direct \cite{BCS1}, thanks to the conservation of the energy \eqref{Energy}. In the case of variable bottom, the situation is not direct at all. However, given the hypotheses on $h$ \eqref{hyp_h}, which consider smallness and boundedness of derivatives, and seen this as a forcing term, one can easily see that local well-posedness is satisfied. As for the global well-posedness, we assume the validity of \eqref{hyp_h} for all nonnegative times, leading to the following first estimates.


\begin{lemma}
Recall the modified energy in \eqref{Energy_new}. Assume \eqref{hyp_h}. Then one has
\begin{enumerate}
\item There exists $c_0>0$ such that if for some $t$ one has $\| (\eta,u)(t)\|_{H^1\times H^1} <C_0 \varepsilon$, then
\be\label{coercividad}
\begin{aligned}
& c_0 (1- C\varepsilon -C_0\varepsilon)\| (\eta,u)(t)\|_{H^1\times H^1}^2 \\
& \qquad \leq H_h[\eta,u ](t) \leq \frac1{c_0}(1+ C\varepsilon  +C_0\varepsilon) \| (\eta,u)(t)\|_{H^1\times H^1}^2.
\end{aligned}
\ee
\item Variation of energy:
\be\label{Energy_new_1}
\begin{aligned}
\frac{d}{dt} H_h[u ,\eta ](t) = &~{} -a c_1 \int  u  \partial_t^2 \partial_x h \\
&~{} +c_1 \int \left( 1+a    +   \eta + h  \right)u (1- \partial_x^2)^{-1}  \partial_t^2 \partial_x h \\
&~{}  + c\int \eta  \partial_th + c a_1 \int \partial_x \eta \partial_x \partial_th \\
&~{}   +(a_1- 1) \int \left(  (1+c) \eta  + \frac12 u^2 \right)(1- \partial_x^2)^{-1}  \partial_th  \\
&~{}  -a_1 \int \left(  (1+c) \eta  + \frac12 u^2 \right) \partial_th  + \frac12 \int u^2  \partial_t h.
\end{aligned}
\ee
\end{enumerate}
\end{lemma}

\begin{proof}
First of all, \eqref{coercividad} is direct from the definition of $H_h$ in \eqref{Energy_new} and the smallness conditions for $h$ \eqref{hyp_h} and $\| (\eta,u)(t)\|_{H^1\times H^1} <C_0 \varepsilon$ (implying $L^\infty$ smallness as well). The proof of \eqref{Energy_new_1} is direct: one has from \eqref{Energy_new},
\[
\begin{aligned}
\frac{d}{dt} H_h[\eta,u ](t) = &~{} \int \left( -a \partial_{x} u \partial_{x} \partial_{t} u  -c  \partial_x \eta \partial_{x} \partial_{t} \eta  + u \partial_t u + \eta \partial_t \eta  +  \frac12 \partial_t(u^2(\eta+ h)) \right)\\
= &~{} \int \left( a   \partial_{x}^2 u  + u   +  u  (\eta+ h)  \right) \partial_t u \\
&~{} + \int \left( c \partial_{x}^2  \eta  +  \eta  + \frac12 u^2 \right)\partial_{t} \eta   + \frac12 \int u^2  \partial_t h.
\end{aligned}
\]
Using \eqref{boussinesq},
\[
\begin{aligned}
\frac{d}{dt} H_h[\eta,u ](t) = &~{} -\int \left( a   \partial_{x}^2 u  + u   +  u  (\eta+ h)  \right) (1- \partial_x^2)^{-1} \partial_x \! \left( c\, \partial_x^2 \eta + \eta  + \frac12 u^2 \right) \\
&~{} + c_1 \int \left( a   \partial_{x}^2 u  + u   +  u  (\eta +h)  \right) (1- \partial_x^2)^{-1}  \partial_t^2 \partial_x h \\
&~{} - \int \left( c \partial_{x}^2  \eta  +  \eta  + \frac12 u^2 \right) (1- \partial_x^2)^{-1} \partial_x \! \left( a\, \partial_x^2 u +u + u (\eta +h) \right) \\
&~{} + \int \left( c \partial_{x}^2  \eta  +  \eta  + \frac12 u^2 \right)(1- \partial_x^2)^{-1} (-1 +a_1 \partial_x^2) \partial_th   + \frac12 \int u^2  \partial_t h.
\end{aligned}
\]
Simplifying, we obtain
\[
\begin{aligned}
\frac{d}{dt} H_h[\eta,u ](t) = &~{} c_1 \int \left( a   \partial_{x}^2 u  + u   +  u  (\eta + h)  \right) (1- \partial_x^2)^{-1}  \partial_t^2 \partial_x h \\
&~{} + \int \left( c \partial_{x}^2  \eta  +  \eta  + \frac12 u^2 \right)(1- \partial_x^2)^{-1} (-1 +a_1 \partial_x^2) \partial_th  \\
&~{}  + \frac12 \int u^2  \partial_t h.
\end{aligned}
\] 
A further simplification gives
\[
\begin{aligned}
\frac{d}{dt} H_h[\eta,u ](t) = &~{} -a c_1 \int  u  \partial_t^2 \partial_x h \\
&~{} +c_1 \int \left( 1+a    +   \eta + h  \right)u (1- \partial_x^2)^{-1}  \partial_t^2 \partial_x h \\
&~{}  -c\int \eta (-1 +a_1 \partial_x^2) \partial_th \\
&~{}   +(a_1- 1) \int \left(  (1+c) \eta  + \frac12 u^2 \right)(1- \partial_x^2)^{-1}  \partial_th  \\
&~{}  -a_1 \int \left(  (1+c) \eta  + \frac12 u^2 \right) \partial_th  + \frac12 \int u^2  \partial_t h.
\end{aligned}
\] 
Now we integrate by parts to get
\[
\begin{aligned}
\frac{d}{dt} H_h[\eta,u ](t) = &~{} -a c_1 \int  u  \partial_t^2 \partial_x h \\
&~{} +c_1 \int \left( 1+a    +   \eta + h  \right)u (1- \partial_x^2)^{-1}  \partial_t^2 \partial_x h \\
&~{}  + c\int \eta  \partial_th + c a_1 \int \partial_x \eta \partial_x \partial_th \\
&~{}   +(a_1- 1) \int \left(  (1+c) \eta  + \frac12 u^2 \right)(1- \partial_x^2)^{-1}  \partial_th  \\
&~{}  -a_1 \int \left(  (1+c) \eta  + \frac12 u^2 \right) \partial_th  + \frac12 \int u^2  \partial_t h.
\end{aligned}
\]
This proves \eqref{Energy_new_1}, as desired.
\end{proof}

\subsection{Proof of global existence} In this subsection, we prove the first part of Theorem \ref{MT1}, namely \eqref{global}.

\begin{lemma}\label{Lem2p3}
One has
\be\label{est_E}
\begin{aligned}
\left| \frac{d}{dt} H_h[\eta,u ](t) \right| \lesssim  
&~{}  (\| (\eta,u)(t)\|_{H^1\times H^1} + \| (\eta,u)(t)\|_{H^1\times H^1}^2 ) \| \partial_t h (t) \|_{H^1} \\
&~{} + ( \| (\eta,u)(t)\|_{H^1\times H^1}  + \|(\eta,u)(t)\|_{H^1\times H^1}^2 ) \| \partial_t^2 h (t) \|_{L^2},
\end{aligned}
\ee
and
\be\label{est_E_2}
\begin{aligned}
& (1 -C\varepsilon -C_0\varepsilon) \|(\eta,u)(t)\|_{H^1\times H^1}^2 \\
&~{} \le C \|(\eta,u)(0)\|_{H^1\times H^1}^2 \\
&~{} \quad + C\int_0^t  (\| (\eta,u)(s)\|_{H^1\times H^1} + \| (\eta,u)(s)\|_{H^1\times H^1}^2 ) ( \| \partial_t h (s) \|_{H^1} +\| \partial_t^2 h (s) \|_{L^2} )ds.
\end{aligned}
\ee
\end{lemma}

\begin{proof}
From \eqref{Energy_new_1} and \eqref{hyp_h},
\[
\begin{aligned}
& \left| -a c_1 \int  u  \partial_t^2 \partial_x h  + c\int \eta  \partial_th + c a_1 \int \partial_x \eta \partial_x \partial_th \right| 
\\
&\quad  \lesssim \| \partial_x u(t)\|_{L^2} \| \partial_t^2 h (t) \|_{L^2} +\| \eta(t)\|_{L^2} \| \partial_t h (t) \|_{L^2} +\| \partial_x \eta (t)\|_{L^2} \| \partial_x \partial_t h (t) \|_{L^2} \\
&\quad  \lesssim \| (\eta,u)(t)\|_{H^1\times H^1} \left( \| \partial_t h (t) \|_{H^1} + \| \partial_t^2 h (t) \|_{L^2} \right).
\end{aligned}
\]
Similarly,
\[
\begin{aligned}
& \left| -a_1 \int \left(  (1+c) \eta  + \frac12 u^2 \right) \partial_th  + \frac12 \int u^2  \partial_t h\right| \\
& \quad \lesssim \| (\eta,u)(t)\|_{H^1\times H^1}  \| \partial_t h (t) \|_{L^2} +\| (\eta,u)(t)\|_{H^1\times H^1}^2  \| \partial_t h (t) \|_{L^2}.
\end{aligned}
\]
Now, using that $\| (1-\partial_x^2)^{-1} f \|_{L^2} \leq \|f\|_{L^2}$,
\[
\begin{aligned}
&\left| c_1 \int \left( 1+a    +   \eta + h  \right)u (1- \partial_x^2)^{-1}  \partial_t^2 \partial_x h \right| \\
&\quad \lesssim (1+ \|h(t)\|_{L^\infty} + \|\eta(t)\|_{L^\infty}) \| \partial_x u(t)\|_{L^2} \|(1- \partial_x^2)^{-1} \partial_t^2 h (t) \|_{L^2} \\
&\quad \lesssim (1+ \|h(t)\|_{H^1} +\|(\eta,u)(t)\|_{H^1\times H^1}  ) \|(\eta,u)(t)\|_{H^1\times H^1} \| \partial_t^2 h (t) \|_{L^2} .
\end{aligned}
\]
Finally,
\[
\begin{aligned}
&\left|  (a_1- 1) \int \left(  (1+c) \eta  + \frac12 u^2 \right)(1- \partial_x^2)^{-1}  \partial_th \right| \\
& \quad \lesssim \| (\eta,u)(t)\|_{H^1\times H^1}  \| \partial_t h (t) \|_{L^2} +\| (\eta,u)(t)\|_{H^1\times H^1}^2  \| \partial_t h (t) \|_{L^2}.  
\end{aligned}
\]
Gathering the previous estimates and using \eqref{hyp_h}, we get
\[
\begin{aligned}
\left| \frac{d}{dt} H_h[\eta,u ](t) \right| \lesssim  
&~{}  (\| (\eta,u)(t)\|_{H^1\times H^1} + \| (\eta,u)(t)\|_{H^1\times H^1}^2 ) \| \partial_t h (t) \|_{H^1} \\
&~{} + ( \| (\eta,u)(t)\|_{H^1\times H^1}  + \|(\eta,u)(t)\|_{H^1\times H^1}^2 ) \| \partial_t^2 h (t) \|_{L^2} \\
&~{}  + \|h(t)\|_{H^1} \|(\eta,u)(t)\|_{H^1\times H^1} \| \partial_t^2 h (t) \|_{L^2} .
\end{aligned}
\]
Using \eqref{hyp_h}, this proves \eqref{est_E}. Then \eqref{est_E_2} follows directly from \eqref{est_E}, \eqref{coercividad} and integration in time.  and ends the proof of Lemma \ref{Lem2p3}.
\end{proof}
Now we conclude the global well-posedness result in the case of small data, in the positive time case. The negative time case is completely analogous. Let $\varepsilon_0>0$ be a small parameter and assume $0<\varepsilon<\varepsilon_0$. Take initial data $\| (\eta,u)(t=0)\|_{H^1\times H^1} < \varepsilon$, assume \eqref{hyp_h} for such $\varepsilon$ and define, for $C_0>1$,
\begin{equation}\label{TC}
T_*(C_0):= \sup\left\{ T \in (0, +\infty) ~ : ~ \hbox{ for all $t\in [0,T]$, } ~  \| (\eta,u)(t)\|_{H^1\times H^1} <C_0 \varepsilon \right\}.
\end{equation}
Let us prove that if $C_0$ is large enough but fixed, and $\varepsilon_0$ is sufficiently small, then $T_*=+\infty$ in \eqref{TC}. Indeed, let us assume $T_* <+\infty$. Then, assuming that the solution is not trivial, we have from \eqref{est_E_2}
\[%be\label{est_E_3}
\begin{aligned}
& (1-C\varepsilon -C_0\varepsilon) \|(\eta,u)(t)\|_{H^1\times H^1}^2 \\
&~{} \le C \varepsilon^2  + C( C_0 \varepsilon +C_0^2 \varepsilon^2)  \int_0^{T_*}  ( \| \partial_t h (s) \|_{H^1} +\| \partial_t^2 h (s) \|_{L^2} )ds.
\end{aligned}
\]%ee
and then, using \eqref{hyp_h}, $C\varepsilon <\frac14$ and $C_0\varepsilon<\frac14$,
\[%be\label{est_E_3}
\begin{aligned}
& \sup_{t\in [0,T_*]} \|(\eta,u)(t)\|_{H^1\times H^1}^2  \le C \varepsilon^2 + C(C_0 \varepsilon + C_0^2 \varepsilon^2) \varepsilon \leq \frac14 C_0^2 \varepsilon^2.
\end{aligned}
\]%ee 
This contradicts the maximality of $T_*$ and proves the global well-posedness under small data. This proves \eqref{global}.

\subsection{Review on canonical variables} We mention now previous results by El Dika and Martel \cite{ElDika2005-2,ElDika_Martel}, and further estimates proved in \cite{KMPP} on the BBM \cite{BBM} character of $b=d>0$ abcd waves. These are based on the fact that virial estimates are not well-suited for the variables $(u,\eta)$, but instead better suited for natural canonical variables that appear in models strongly involving the nonlocal operator $(1-\px^2)^{-1}$.

\begin{definition}[Canonical variable]\label{Can_Var}
Let $u=u(x) \in L^2$ be a fixed function. We say that $f$ is canonical variable for $u$ if $f$ uniquely solves the equation
\be\label{Canonical}
f- \partial_x^2 f  = u, \quad f\in H^2(\R).
\ee
In this case, we simply denote $f=  (1-\partial_x^2)^{-1} u.$
\end{definition}

Canonical variables are standard in equations where the operator $(1-\partial_x^2)^{-1}$ appears; one of the well-known example is given by the Benjamin-Bona-Mahoney BBM equation, see e.g. \cite{ElDika2005-2,ElDika_Martel}.

\begin{lemma}
One has
\begin{equation}\label{eq:L2}
\int \vp' u^2 = \int\vp'\left(f^2 + 2(\partial_x f )^2 + (\partial_x^2 f )^2\right) - \int \vp'''f^2,
\end{equation}
and
\begin{equation}\label{eq:nonlocal}
\int \vp' u \nlop u = \int\vp'\left(f^2 + (\partial_x f )^2\right) - \frac12\int \vp'''f^2.
\end{equation}
\end{lemma}

\begin{lemma}[Equivalence of local $L^2$ and $H^1$ norms, \cite{KMPP}]\label{lem:L2 comparable}
Let $\phi$ be a smooth, bounded positive weight satisfying $|\phi''| \le \lambda \phi$ for some small but fixed $0 < \lambda \ll1$.  Let $f$ be a canonical variable for $u$, as introduced in Definition \ref{Can_Var} and \eqref{Canonical}.  The following are satisfied:

\begin{itemize}
\item If $u\in L^2$, then for any $a_1,a_2,a_3 > 0$, there  exist $c_1, C_1 >0$, depending on $a_j$ ($j=1,2,3$) and $\lambda >0$, such that
\begin{equation}\label{eq:L2_est}
c_1  \int \phi \, u^2 \le \int \phi\left(a_1f^2+a_2(\partial_x f )^2+a_3(\partial_x^2 f )^2\right) \le C_1 \int \phi \, u^2.
\end{equation}
\item If $u\in H^1$, then for any $d_1,d_2,d_3 > 0$, there  exist $c_1, C_1 >0$ depending on $d_j$, $j=1,2,3$, and $\lambda >0$ such that
\begin{equation}\label{eq:H1_est}
c_2 \int \phi (\partial_x u )^2 \le  \int \phi\left(d_1(\partial_x f )^2+d_2(\partial_x^2 f )^2+d_3(\partial_x^3 f)^2\right) \le C_2 \int \phi (\partial_x u)^2.
\end{equation}
\end{itemize}
\end{lemma}

The following results are well-known in the literature, see El Dika \cite{ElDika2005-2} for further details and proofs.

\begin{lemma}[\cite{ElDika2005-2,KMPP}]%\label{Dika1}
The operator $ (1-\px^2)^{-1}$ satisfies the following properties:
\begin{itemize}
\item Suppose that $\phi =\phi(x)$ is such that
\[%begin{equation}\label{eq:inverse op2}
(1-\px^2)^{-1}\phi(x) \lesssim \phi(x), \quad x\in \R,
\]%end{equation}
for $\phi(x) > 0$ satisfying $|\phi^{(n)}(x)| \lesssim \phi(x)$, $n \ge 0$. Then, for $v,w,h \in H^1$, we have
\begin{equation}\label{eq:nonlinear1-1}
\int \phi^{(n)} v (1-\px^2)^{-1} \partial_x (wh) ~\lesssim ~ \norm{v}_{H^1} \int \phi (w^2 + ( \partial_x w)^2 +h^2 + ( \partial_x h)^2),
\end{equation}
and
\begin{equation}\label{eq:nonlinear1-2}
\int\phi^{(n)} v (1-\px^2)^{-1}(wh) ~\lesssim ~\norm{v}_{H^1} \int \phi(w^2 +h^2).
\end{equation}
\item Under the previous conditions, we have
\begin{equation}\label{eq:nonlinear1-3}
\int  \partial_x (\phi  ~{}\partial_x v) (1-\px^2)^{-1}(wh) \lesssim \norm{v}_{H^1} \int \phi (w^2 + ( \partial_x w)^2 +h^2 + ( \partial_x h)^2).
\end{equation}
and
\begin{equation}\label{eq:nonlinear1-4}
\int \phi  \partial_x v (1-\px^2)^{-1}  \partial_x(wh) \lesssim \norm{v}_{H^1} \int \phi (w^2 + ( \partial_x w)^2 +h^2 + ( \partial_x h)^2).
\end{equation}
\end{itemize}
\end{lemma}

The following lemmas, proved in \cite{KMM}, will be useful to estimates the terms on \eqref{eq:gvirial} which involves  the influence of the bottom $h$  and the nonlocal operator  $(1-\  \partial_x^2)^{-1}$.
This operator satisfies:
\begin{lemma}[\cite{KMM}]\label{lem:est_IOp}
	Let $f\in L^2(\R)$ and $0<\ <1$ fixed. We have the following estimates:
	\begin{enumerate}%[$(i)$]
		\item $\| (1-\  \partial_x^2)^{-1}f\|_{L^2(\R)}\leq \|f \|_{L^2(\R)}$,
		\vspace{0.1cm}
		\item $\| (1-\  \partial_x^2)^{-1}\partial_x f\|_{L^2(\R)}\leq \|f \|_{L^2(\R)}$,
		\vspace{0.1cm}
		\item $\| (1-\  \partial_x^2)^{-1}f\|_{H^2(\R)}\leq \|f \|_{L^2(\R)}$.
	\end{enumerate}
\end{lemma}
We also enunciate the following results that appeared in \cite{KMMV20,Mau}. Notice that now the variable in the weights will be $K=1/\lambda(t)$, with $\lambda(t)$ time dependent and increasing, but this shift will not affect the final outcome.
\begin{lemma}
	There exist $C>0$ such that for $0<K\leq 1$ and $g\in L^2$, 
%	\vspace{0.1cm}
	\begin{align}
	\label{eq:sech_Opg}
	\left\| \sech\left( K \cdot\right) (1-\ \partial_x^2)^{-1} g\right\|_{L^2}
	\leq{}~ C &\left\| (1-\ \partial_x^2)^{-1}\left[ \sech\left( K  \cdot \right)  g\right]\right\|_{L^2},
	\\
\label{eq:sech_Opg_p}
	\left\| \sech(K \cdot)(1-\  \partial_x^2)^{-1}\partial_x g \right\|_{L^2} 
	\leq&{}~ C  \left\| \sech(K \cdot) g \right\|_{L^2},
	\end{align}
and
\begin{equation}\label{eq:sech_Opg_1pp}
	\left\| \sech(K\cdot)(1-\  \partial_x^2)^{-1}(1-\partial_x^2)g \right\|_{L^2} \leq {}~ C  \| \sech(K\cdot ) g \|_{L^2}.
	\end{equation}
\end{lemma}



\section{Modified virial functionals}\label{3}

This Section is devoted to the introduction and study of three virial functionals adapted to the uneven bottom, and their behavior under the $H^1\times H^1$ flow.  Let $\vp=\vp(x)$ be a smooth, bounded weight function, to be chosen later. For each $t\in\R$, we consider the following functionals for some $\vp$ (to be chosen later):
\be\label{I}
\mathcal I(t) := \int \vp(x)(u\eta + \px u \px\eta)(t,x)dx,
\ee
and
\be\label{J}
\mathcal J(t) := \int \vp'(x)(\eta \px u)(t,x)dx.
\ee
Clearly each functional above is well-defined for $H^1\times H^1$ functions, as long as the pair $(u,\eta)(t=0)$ is small in the energy space.

\subsection{Virial functional $\mathcal I(t)$} Using \eqref{boussinesq} and integration by parts, we have the following result.

\begin{lemma}\label{Virial_bous}
Consider $\mathcal I(t)$ in \eqref{I}. Then for any $t\geq0$,
\be\label{Virial0}
\begin{aligned}
\frac{d}{dt} \mathcal I(t) = &~  {}   -\frac{a}2 \int  \varphi' (\partial_x u)^2-\frac{c}2 \int  \varphi' (\partial_x \eta)^2 \\
&~{}   - \left(a+\frac12\right)   \int  \varphi' u^2 -\left( c+ \frac12 \right)  \int  \varphi' \eta^2 \\
& ~ {} + (1+ a)\int \varphi' u (1-\partial_x^2)^{-1} u  + (1+ c)\int \varphi' \eta (1-\partial_x^2)^{-1} \eta  \\
&~ {}     -\frac12 \int  \varphi' u^2 \eta   + \int \varphi' u (1-\partial_x^2)^{-1}\left(u \eta \right)  + \frac12\int \varphi' \eta (1-\partial_x^2)^{-1}\left(u^2\right)\\
&~{} - \frac12 \int  \partial_x (\varphi h) u^2  + \int \varphi' u (1-\partial_x^2)^{-1}\left( u h \right) \\
&~ -  c_1 \int \varphi' \eta (1-\partial_x^2)^{-1}  \partial_t^2 \partial^2_x h  +  \int  \varphi' u(1-\partial^2_x)^{-1}(1- a_1\partial_x^2)\partial_t\partial_{x}h\\
&~{} +c_1  \int \varphi \eta \partial_t^2 \partial_x h + \int \varphi u (-1+  a_1 \partial_x^2)\partial_t h.
\end{aligned}
\ee
\end{lemma}


\begin{proof}
We compute:
\[
\begin{aligned}
\frac{d}{dt} \mathcal I(t) =&~  \int \varphi (\partial_t \eta u + \eta \partial_t u+ \partial_t\partial_xu \partial_x \eta +\partial_xu  \partial_t\partial_x \eta )\\
=&~ {} \int \varphi (\partial_t \eta -\partial_t \partial_x^2 \eta) u + \int  \varphi (\partial_t u  - \partial_t \partial_x^2 u) \eta -\int \varphi' \eta \partial_t \partial_x u -\int \varphi' u \partial_t \partial_x\eta \\
=:&~{} I_1+I_2+I_3+I_4.
\end{aligned}
\]
Replacing \eqref{boussinesq}, and integrating by parts, we get
\[
\begin{aligned}
I_1 =&~  \int \partial_x(\varphi  u ) (a \partial_x^2 u +u +u(\eta+ h) ) + \int \varphi u (-1+  a_1 \partial_x^2)\partial_t h,
\end{aligned}
\]
and
\[
\begin{aligned}
I_2 =&~   \int  \partial_x(\varphi \eta) \left(c\partial_x^2 \eta +\eta + \frac12 u^2\right)+c_1  \int \varphi \eta  \partial_t^2\partial_xh.
\end{aligned}
\]
First of all, using \eqref{boussinesq},
\[
\begin{aligned}
I_3= &~  \int \partial_x (\varphi' \eta) \partial_t u =  \int \partial_x^2 (\varphi' \eta) (1-\partial_x^2)^{-1}\left(c\partial_x^2 \eta +\eta +\frac12 u^2\right)\\
&+ c_1 \int \partial_x (\varphi' \eta) (1-\partial_x^2)^{-1}  \partial_t^2 \partial_x h\\
=&~   \int \left( \partial_x^2  (\varphi' \eta) - \varphi' \eta \right) (1-\partial_x^2)^{-1}\left(c \partial_x^2 \eta +\eta +\frac12 u^2\right) \\
&~ {}  + \int \varphi' \eta (1-\partial_x^2)^{-1}\left(c \partial_x^2 \eta +\eta +\frac12 u^2\right) + c_1 \int \partial_x (\varphi' \eta) (1-\partial_x^2)^{-1}  \partial_t^2 \partial_x h \\
=&~  - \int  \varphi' \eta\left(c\partial_x^2 \eta +\eta +\frac12 u^2\right) \\
&~ {}  + \int \varphi' \eta (1-\partial_x^2)^{-1}\left(c\partial_x^2  \eta +\eta +\frac12 u^2\right) +  c_1 \int \partial_x (\varphi' \eta) (1-\partial_x^2)^{-1}  \partial_t^2 \partial_x h .\\ 
\end{aligned}
\]
Therefore,
\begin{equation}\label{I2+I3}
\begin{aligned}
I_2 + I_3 =& \int  \varphi \partial_x \eta \left(c \partial_x^2  \eta +\eta + \frac12 u^2\right)+ \int \varphi' \eta (1-\partial_x^2)^{-1}\left(c\partial_x^2 \eta +\eta +\frac12 u^2\right)\\
&+c_1  \int \varphi \eta \partial_t^2 \partial_x h  + c_1 \int \partial_x (\varphi' \eta) (1-\partial_x^2)^{-1}   \partial_t^2 \partial_x h .
\end{aligned}
\end{equation}
Similarly,
\[
\begin{aligned}
I_4  =&~ -\int \varphi' u \partial_t \partial_x\eta\\
=&~ \int \varphi' u (1- \partial_x^2)^{-1} \partial_x^2\! \left( a\, \partial_x^2 u +u + (\eta+h) u  \right)- \int \varphi' u (1- \partial_x^2)^{-1} \partial_x (-1 + a_1 \partial_x^2) \partial_th   \\
= &~{}  - \int  \varphi' u \left(a \partial_x^2 u +u +u (\eta+ h) \right)   + \int \varphi' u (1-\partial_x^2)^{-1}\left(a \partial_x^2 u + u + u (\eta+ h)\right) \\
&~{}  - \int  \varphi' u(1-\partial^2_x)^{-1}(-1+ a_1\partial^2_x)\partial_{x}\partial_{t} h,
\end{aligned}
\]
and
\begin{equation}\label{I1+I4}
\begin{aligned}
I_1 + I_4 =& \int  \varphi \partial_x u \left(a \partial_x^2 u  +u + u (\eta +h) \right) \\
&~{} + \int \varphi' u (1-\partial_x^2)^{-1}\left(a \partial_x^2 u +u + u (\eta+ h) \right)\\
&~ {} - \int  \varphi' u(1-\partial^2_x)^{-1}(-1+ a_1\partial^2_x)\partial_{x}\partial_{t} h+ \int \varphi u (-1+  a_1 \partial_x^2)\partial_t h.
\end{aligned}
\end{equation}
Gathering \eqref{I2+I3} and \eqref{I1+I4}, we have
\[
\begin{aligned}
\frac{d}{dt}\mathcal I(t) = &~ \int  \varphi \partial_x u \left(a \partial_x^2  u +u +  u (\eta+ h) \right)\\
&~{} + \int \varphi' u (1-\partial_x^2)^{-1}\left(a \partial_x^2  u +u +u (\eta+ h) \right)\\
&~ {} + \int  \varphi \partial_x \eta \left(c\partial_x^2  \eta +\eta + \frac12 u^2\right)+ \int \varphi' \eta (1-\partial_x^2)^{-1}\left(c \partial_x^2 \eta +\eta +\frac12 u^2\right) \\
&~ {}+  c_1 \int \partial_x (\varphi' \eta) (1-\partial_x^2)^{-1}   \partial_t^2 \partial_x h  - \int  \varphi' u(1-\partial^2_x)^{-1}(-1+ a_1\partial_x^2)\partial_t\partial_{x}h \\
&~{} +c_1  \int \varphi \eta \partial_t^2 \partial_x h + \int \varphi u (-1+  a_1 \partial_x^2)\partial_t h\\
= &~ \int  \varphi \partial_x u \left(a \partial_x^2 u +u + u \eta \right)+ \int \varphi' u (1-\partial_x^2)^{-1}\left(a \partial_x^2 u +u + u \eta \right)\\
&~ {} + \int  \varphi \partial_x \eta \left(c \partial_x^2 \eta +\eta + \frac12 u^2\right)+ \int \varphi' \eta (1-\partial_x^2)^{-1}\left(c \partial_x^2 \eta +\eta +\frac12 u^2\right) \\
 &~ + \int  \varphi \partial_x u \left( uh \right)  +  \int \varphi' u (1-\partial_x^2)^{-1}\left( u h \right) \\
&~ + c_1  \int \partial_x (\varphi' \eta) (1-\partial_x^2)^{-1}  \partial_t^2 \partial_x h - \int  \varphi' u(1-\partial^2_x)^{-1}(-1+ a_1\partial_x^2)\partial_t\partial_{x}h\\
&~{} +c_1  \int \varphi \eta \partial_t^2 \partial_x h + \int \varphi u (-1+  a_1 \partial_x^2)\partial_t h\\
= : &~ \tilde I_1 + \tilde I_2 + \tilde I_3 +\tilde I_4+ \tilde I_5 (h).
\end{aligned}
\]
Now we compute each $\tilde I_j$. First,
\[
\tilde I_1 =  -\frac{a}2 \int  \varphi'  (\partial_x u)^2  -\frac12  \int  \varphi' u^2  -\frac12 \int  \varphi' u^2 \eta - \frac12 \int \varphi u^2 \partial_x \eta.
\]
Second,
\[
\tilde I_3=  -\frac{c}2 \int  \varphi' ( \partial_x  \eta)^2 -\frac12 \int  \varphi' \eta^2 + \frac12 \int  \varphi  \partial_x \eta u^2.
\]
Consequently,
\[
\tilde I_1+ \tilde I_3 = -\frac{a}2 \int  \varphi' ( \partial_x u)^2-\frac{c}2 \int  \varphi' ( \partial_x \eta)^2   -\frac12  \int  \varphi' (u^2 +\eta^2)  -\frac12 \int  \varphi' u^2 \eta.
\]
On the other hand,
\[
\begin{aligned}
\tilde I_2 =  &~  \int \varphi' u (1-\partial_x^2)^{-1}\left(a  \partial_x^2  u +u +u \eta \right) \\
= &~ {} a\int \varphi' u (1-\partial_x^2)^{-1} ( \partial_x^2 u -u) \\
&~ {}+ (1+ a)\int \varphi' u (1-\partial_x^2)^{-1} u   + \int \varphi' u (1-\partial_x^2)^{-1}\left(u \eta \right) \\
= &~ {}  - a\int \varphi' u^2 + (1+ a)\int \varphi' u (1-\partial_x^2)^{-1} u   + \int \varphi' u (1-\partial_x^2)^{-1}\left(u \eta \right).
\end{aligned}
\]
Similarly,
\[
\begin{aligned}
\tilde I_4 =  &~  \int \varphi' \eta (1-\partial_x^2)^{-1}\left(c \partial_x^2 \eta +\eta +\frac12 u^2\right) \\
= &~ {} c \int \varphi' \eta (1-\partial_x^2)^{-1} ( \partial_x^2 \eta -\eta ) \\
&~ {}+ (1+ c)\int \varphi' \eta (1-\partial_x^2)^{-1} \eta   +\frac12 \int \varphi' \eta (1-\partial_x^2)^{-1}\left(u^2\right) \\
= &~ {}  - c\int \varphi' \eta^2 + (1+ c)\int \varphi' \eta (1-\partial_x^2)^{-1} \eta   + \frac12\int \varphi' \eta (1-\partial_x^2)^{-1}\left(u^2\right).
\end{aligned}
\]
Finally,
\begin{align*}
  \tilde I_5= &~  \int  \varphi  \partial_x u \left( uh \right) +  \int \varphi' u (1-\partial_x^2)^{-1}\left( u h \right)\\
&~ + c_1 \int  \partial_x (\varphi' \eta) (1-\partial_x^2)^{-1}  \partial_t^2 \partial_x h  - \int  \varphi' u(1-\partial^2_x)^{-1}(-1+ a_1\partial_x^2)\partial_t\partial_{x}h \\
&~{} +c_1  \int \varphi \eta \partial_t^2 \partial_x h + \int \varphi u (-1+  a_1 \partial_x^2)\partial_t h\\
=&~ - \frac12  \int   \partial_x (\varphi h) u^2  +  \int \varphi' u (1-\partial_x^2)^{-1}\left( u h \right) \\
&~ - c_1 \int \varphi' \eta (1-\partial_x^2)^{-1}   \partial_t^2 \partial^2_x h -  \int  \varphi' u(1-\partial^2_x)^{-1}(-1+  a_1\partial_x^2)\partial_t\partial_{x}h\\
&~{} +c_1  \int \varphi \eta \partial_t^2 \partial_x h + \int \varphi u (-1+  a_1 \partial_x^2)\partial_t h .
\end{align*}
We conclude that
\[
\begin{aligned}
\frac{d}{dt} \mathcal I(t) = &~ \tilde I_1 + \tilde I_2 + \tilde I_3 +\tilde I_4+ \tilde I_5\\
=&~  {}  -\frac{a}2 \int  \varphi' ( \partial_x  u)^2-\frac{c}2 \int  \varphi' ( \partial_x \eta)^2   -\frac12  \int  \varphi' (u^2 +\eta^2)  -\frac12 \int  \varphi' u^2 \eta \\
& ~ {} - a\int \varphi' u^2 + (1+ a)\int \varphi' u (1-\partial_x^2)^{-1} u   + \int \varphi' u (1-\partial_x^2)^{-1}\left(u \eta \right) \\
&~ {} - c\int \varphi' \eta^2 + (1+ c)\int \varphi' \eta (1-\partial_x^2)^{-1} \eta   + \frac12\int \varphi' \eta (1-\partial_x^2)^{-1}\left(u^2\right) \\
&~ - \frac12 \int   \partial_x  (\varphi h) u^2  + \int \varphi' u (1-\partial_x^2)^{-1}\left( u h \right) \\
&~ -  c_1 \int \varphi' \eta (1-\partial_x^2)^{-1}   \partial_t^2 \partial^2_x h  - \int  \varphi' u(1-\partial^2_x)^{-1}(-1+ a_1\partial_x^2)\partial_t\partial_{x}h \\
&~{} +c_1  \int \varphi \eta \partial_t^2 \partial_x h + \int \varphi u (-1+  a_1 \partial_x^2)\partial_t h.
\end{aligned}
\]
Finally, rearranging terms,
\[
\begin{aligned}
\frac{d}{dt} \mathcal I(t)=&~  {}  -\frac{a}2 \int  \varphi' ( \partial_x  u)^2-\frac{c}2 \int  \varphi' ( \partial_x \eta)^2   - \left(a+\frac12\right)   \int  \varphi' u^2 -\left( c+ \frac12 \right)  \int  \varphi' \eta^2 \\
& ~ {} + (1+ a)\int \varphi' u (1-\partial_x^2)^{-1} u  + (1+ c)\int \varphi' \eta (1-\partial_x^2)^{-1} \eta  \\
&~ {}     -\frac12 \int  \varphi' u^2 \eta   + \int \varphi' u (1-\partial_x^2)^{-1}\left(u \eta \right)  + \frac12\int \varphi' \eta (1-\partial_x^2)^{-1}\left(u^2\right)\\
&~{}  - \frac12 \int   \partial_x (\varphi h) u^2   +  \int \varphi' u (1-\partial_x^2)^{-1}\left( u h \right) \\
&~ -  c_1 \int \varphi' \eta (1-\partial_x^2)^{-1}   \partial_t^2 \partial^2_x h  - \int  \varphi' u(1-\partial^2_x)^{-1}(-1+ a_1\partial_x^2)\partial_t\partial_{x}h\\
&~{} +c_1  \int \varphi \eta \partial_t^2 \partial_x h + \int \varphi u (-1+  a_1 \partial_x^2)\partial_t h.
\end{aligned}
\]
This last equality proves \eqref{Virial0}.
\end{proof}

\subsection{Virial functional $\mathcal J(t)$}


In what follows, we recall the system \eqref{boussinesq}-\eqref{Conds} written in the equivalent form
\begin{equation}\label{eq:abcd}
\begin{aligned}
\pt \eta  = &~{} a \px u -(1+a)(1-\partial_x^2)^{-1}\px u - (1-\partial_x^2)^{-1}\px(u(\eta + h)) \\
& ~{} +(1-\partial^2_x)^{-1}\left(-1+ a_1 \partial_x^2\right) \partial_t h \\
\pt u  =  &~{} c \px \eta -(1+c)(1-\partial_x^2)^{-1}\px \eta - \frac12(1-\partial_x^2)^{-1}\px(u^2)\\
& ~{}+ c_1 (1-\partial^2_x)^{-1}  \partial_t^2 \partial_x h.
\end{aligned}
\end{equation}

\begin{lemma}\label{lem:J}
Consider the functional $\mathcal J$ from \eqref{J}. Then for any $t \geq0$,
\begin{equation}\label{eq:J-1}
\begin{aligned}
\frac{d}{dt} \mathcal J(t)=&~  (1+c)\int\vp'\eta^2 - c\int\vp' ( \partial_x \eta)^2  -(1+a)\int\vp' u^2 + a \int\vp' ( \partial_x u)^2\\
&-(1+c)\int\vp'\eta\nlop\eta + (1+a)\int\vp' u \nlop u\\
&+(1+a) \int \vp''u \nlop  \partial_x u + \frac{c}{2}\int\vp''' \eta^2\\
&-\frac12\int\vp' u^2\eta -\frac12\int\vp' \eta\nlop \left( u^2 \right)  \\
&+ \int \vp' u\nlop \left( u\eta \right) +\int \vp'' u\nlop  \partial_x ( u\eta )\\
&- \int\vp'u^2 h + \int\vp'u\nlop(u h) + \int \vp''u\nlop  \partial_x(u h)\\
&+ \int\vp'  \partial_x u (1-\partial^2_x)^{-1}\left(-1+ a_1 \partial_x^2\right) \partial_t h+ c_1   \int\varphi'\eta (1-\partial^2_x)^{-1} \partial_t^2 \partial_x^2 h.
\end{aligned}
\end{equation}
\end{lemma}

\begin{proof}
We compute, using \eqref{eq:abcd},
\[\begin{aligned}
\frac{d}{dt} \mathcal J(t) =&\int\vp'\left( \partial_t \eta  \partial_x u +  \partial_x  \partial_t \eta u \right)\\
=&\int \vp'  \partial_x u \bigg(a  \partial_x u - (1+a)(1-\px^2)^{-1}  \partial_x u - (1-\px^2)^{-1} \partial_x (u(\eta-h)) \\
& \qquad \qquad +(1-\partial^2_x)^{-1}\left(-1+ a_1 \partial_x^2\right) \partial_t h \bigg)\\
&+\int\vp' \eta \bigg(c  \partial_x^2 \eta - (1+c)(1-\px^2)^{-1} \partial_x^2 \eta \\
&  \qquad \qquad - \frac12(1-\px^2)^{-1} \partial_x^2( u^2 )+ c_1(1-\partial^2_x)^{-1} \partial_t^2 \partial_x^2 h \bigg)\\
=: & ~J_1 +J_2.
\end{aligned}\]
We first deal with $J_1$. The integration by parts yields
\begin{equation}\label{eq:J1-1}
\begin{aligned}
J_1=& ~{} a \int \vp' ( \partial_x u)^2 - (1+a)\int\vp'  \partial_x u \nlop  \partial_x u\\
&~{}  - \int\vp'  \partial_x u \nlop  \partial_x (u (\eta + h))+ \int \vp'  \partial_x u (1-\partial^2_x)^{-1}\left(-1+ a_1 \partial_x^2\right) \partial_t h.
\end{aligned}
\end{equation}
We use the identity
\begin{equation}\label{eq:trick1}
\int \psi w \nlop  \partial_x ^2 z = -\int \psi  wz + \int \psi  w \nlop z
\end{equation}
for the second and fourth terms, in the right-hand side of \eqref{eq:J1-1}, to obtain
\[%begin{equation}\label{eq:J1-2}
\begin{aligned}
J_1=&~{}-(1+a)\int \vp' u^2 + a \int \vp' ( \partial_x u)^2\\
&+ (1+a)\int\vp' u \nlop u +(1+a)\int\vp''u\nlop  \partial_x u \\
&-\int\vp'u^2 (\eta+ h) + \int\vp'u\nlop(u (\eta + h)) \\
& +\int \vp''u\nlop  \partial_x (u( \eta+ h)) + \int \vp'  \partial_x u (1-\partial^2_x)^{-1}\left(-1+a_1 \partial_x^2\right) \partial_t h.
\end{aligned}
\]%end{equation}
Arranging terms,
\begin{equation}\label{eq:J1-2}
\begin{aligned}
J_1=&~{}-(1+a)\int \vp' u^2 + a \int \vp' ( \partial_x u )^2\\
&+ (1+a)\int\vp' u \nlop u +(1+a)\int\vp''u\nlop  \partial_x u \\
&-\int\vp'u^2\eta + \int\vp'u\nlop(u\eta) +\int \vp''u\nlop  \partial_x (u\eta)\\
& - \int\vp'u^2 h +  \int\vp'u\nlop(uh) + \int \vp''u\nlop  \partial_x (u h) \\
&+ \int \vp'  \partial_x u(1-\partial^2_x)^{-1}\left(-1+ {a}_1 \partial_x^2\right) \partial_t h.
\end{aligned}
\end{equation}
For $J_2$, using the integration by parts and \eqref{eq:trick1} with the identity
$%begin{equation}\label{eq:trick2}
f\partial_x^2 f  = \frac12 \partial_x^2 (f^2) - (\partial_x f)^2,
$ %end{equation}
 yields
\begin{equation}\label{eq:J2}
\begin{aligned}
J_2=&~ c\int \vp'\eta \partial_x^2 \eta - (1+c)\int \vp' \eta \nlop \partial_x^2 \eta \\
&-\frac12\int\vp'\eta \nlop \partial_x^2 (u^2) + {c}_1 \int\varphi' \eta (1-\partial^2_x)^{-1} \partial_t^2 \partial_x^2 h\\
=&~ (1+c)\int\vp'\eta^2 - c\int\vp' (\partial_x \eta)^2 + \frac{c}{2}\int\vp'''\eta^2\\
&-(1+c)\int\vp'\eta\nlop\eta\\
&+\frac12\int\vp'u^2\eta-\frac12\int\vp'\eta\nlop(u^2) +  {c}_1 \int\varphi'\eta (1-\partial^2_x)^{-1} \partial_t^2 \partial_x^2 h.
\end{aligned}
\end{equation}
By collecting all \eqref{eq:J1-2} and \eqref{eq:J2}, we have \eqref{eq:J-1}.
\end{proof}

Now we construct a global virial from a linear combination of $\mathcal I(t)$ and $\mathcal  J(t)$. Let $\alpha$ be a real number. We define the modified virial
\be\label{H}
\mathcal H(t):= \mathcal I(t) + \alpha \mathcal J(t).
\ee
Thanks to Lemmas \ref{Virial_bous} and \ref{lem:J}, we obtain the following direct consequence:

\begin{proposition}[Decomposition of $\frac{d}{dt}\mathcal H(t)$, \cite{KMPP}]\label{prop:general virial}
Let $u$ and $\eta$ satisfy \eqref{boussinesq} and $\mathcal H$ as in \eqref{H}. For any $\alpha\in \R$ and any $t \in \R$, we have the decomposition
\begin{equation}\label{eq:gvirial}
\frac{d}{dt}\mathcal H(t) = \mathcal Q(t) + \mathcal{SQ}(t) + \mathcal{NQ}(t) + \mathcal{NH}(t),
\end{equation}
where $\mathcal Q(t) =\mathcal Q[u,\eta](t) $ is the quadratic form
\begin{equation}\label{eq:leading}
\begin{aligned}
\mathcal Q(t) :=& ~\left(\left(1+ c \right)(\alpha-1) + \frac{1}2\right)\int \vp' \eta^2 -c \Big( \alpha + \frac12\Big)\int \vp' (\partial_x \eta)^2 \\
&+\left(\left(1+ a \right)( -\alpha-1) + \frac{1}2\right)\int \vp' u^2 +a \Big(\alpha-\frac12\Big)\int \vp' (\partial_x u)^2 \\
&+\left(1+ c \right)( - \alpha + 1)\int \vp' \eta \nlop \eta\\
&+\left(1+ a\right)(\alpha  +1)\int \vp' u \nlop u ,
\end{aligned}
\end{equation}
$ \mathcal{SQ}(t)$ represents lower order quadratic terms not included in $\mathcal Q(t)$:
\begin{equation}\label{eq:small linear}
\begin{aligned}
 \mathcal{SQ}(t) :=& ~ %\left(1+c \right)\int\vp'' \eta \nlop \partial_x \eta +
  \alpha\left(1+ a\right)\int\vp'' u \nlop  \partial_x u
%\\&
+\frac{\alpha c}{2} \int \vp''' \eta^2 ,
%+ \frac{ a}{2} \int \vp'''  u^2,
\end{aligned}
\end{equation}
$\mathcal{NQ}(t)$ are truly cubic order terms or higher:
\begin{equation}\label{eq:nonlinear}
\begin{aligned}
 \mathcal{NQ}(t) :=& ~ - \frac12(  \alpha + 1)\int\vp' u^2\eta + \frac12( -\alpha + 1)\int \vp' \eta \nlop (u^2)\\
&+ (\alpha +1)\int \vp'  u \nlop (u\eta) + \alpha\int \vp'' u \nlop \partial_x (u\eta),
\end{aligned}
\end{equation}
and $\mathcal{NH}(t)$ are the new terms appearing from the influence of the bottom $h$ in the dynamics:
\begin{equation}\label{eq:H}
\begin{aligned}
 \mathcal{NH}(t) :=& ~ {}  - \frac12 \int  \partial_x (\varphi h) u^2  + (1+\alpha) \int \varphi' u (1-\partial_x^2)^{-1}\left( u h \right)  \\
 &~{}  - \alpha \int\vp'u^2 h %+ \alpha  \int\vp'u\nlop(uh)} \\
  +  \alpha  \int \vp'' u\nlop \partial_x (u h) \\
&~ {} + (\alpha- 1) c_1 \int \varphi' \eta (1-\partial_x^2)^{-1}  \partial_t^2 \partial^2_x h  \\
&~{}  +  \int  \varphi' u(1-\partial^2_x)^{-1}(1- a_1\partial_x^2)\partial_t\partial_{x}h \\
&~{}  +   \alpha  \int\vp' \partial_x u (1-\partial^2_x)^{-1}\left(-1+ a_1 \partial_x^2\right) \partial_t h \\
&~{} + c_1  \int \varphi \eta \partial_t^2 \partial_x h + \int \varphi u (-1+  a_1 \partial_x^2)\partial_t h  . %\\
%&~{} + c_1   \alpha  {\color{black}  \int\varphi'\eta (1-\partial^2_x)^{-1} \partial_t^2 \partial_x^2 h}.
\end{aligned}
\end{equation}
\end{proposition}

Proposition \ref{prop:general virial} decomposes the evolution of $abcd$ solutions in four different terms. Recall that the terms \eqref{eq:small linear} are usually absorbed by the terms in $\mathcal Q(t)$. The terms in \eqref{eq:nonlinear} are large unless one consider small data, and may lead to either the existence of solitary waves or blow up. Consequently, they must be taken with care. Finally, the new terms \eqref{eq:H} are different to the previous ones and have a strong influence in the dynamics. 

\subsection{Passage to canonical variables}


We focus on the quadratic form $\mathcal{Q}(t)$ in \eqref{eq:leading}. We introduce canonical variables for $u$ and $\eta$ (see Definition \ref{Can_Var}) as follows:
\begin{equation}\label{eq:fg}
f := \nlop u \quad \mbox{and} \quad g := \nlop \eta.
\end{equation}
Note that, for $u, \eta \in H^1$, one has $f$ and $g$ in $H^3$. A direct calculation shows the following key relationships between $f$ and $u$ (resp. $g$ and $\eta$), see also Lemma \ref{lem:L2 comparable} for a similar statement. Using \eqref{eq:L2}-\eqref{eq:nonlocal}, we can rewrite the quadratic form $\mathcal{Q}(t)$ as follows:
\begin{lemma}\label{lem:leading}
Let $f$ and $g$ be canonical variables of $u$ and $\eta$ as in \eqref{eq:fg}. Consider the quadratic form $\mathcal Q(t)$ given in \eqref{eq:leading}. Then we have
\begin{equation}\label{eq:leading-1}
\begin{aligned}
\mathcal Q(t) =& \int \vp' \Big( A_1 f^2 + A_2 (\partial_x f )^2 + A_3 (\partial_x^2 f )^2 + A_4 (\partial_x^3 f)^2\Big)\\
&+\int \vp' \Big( B_1 g^2 + B_2 (\partial_x g )^2 + B_3 (\partial_x^2 g)^2 + B_4 (\partial_x^3 g)^2\Big)\\
&+\int \vp''' \Big(D_{11}f^2 + D_{12}(\partial_x f )^2 + D_{21}g^2 + D_{22}(\partial_x g )^2\Big),
\end{aligned}
\end{equation}
where
\[%begin{equation}\label{eq:A1B1}
A_1 = B_1 = \frac12>0,
\]%end{equation}
\[%begin{equation}\label{eq:A2B2}
A_2 =  - \alpha -\frac{3a}{2}, \qquad B_2 = \alpha -  - \frac{3c}{2},
\]%end{equation}
\[%begin{equation}\label{eq:A3B3}
A_3 = -(1-a) \alpha  -2a - \frac12, \qquad B_3 = (1-c) \alpha -2c - \frac12,
\]%end{equation}
\[%begin{equation}\label{eq:A4B4}
A_4= a\left(\alpha   - \frac12\right), \qquad B_4= - c\left(  \alpha + \frac12\right),
\]%end{equation}
and
\[%begin{equation}\label{eq:D1D2}
\begin{aligned}
&D_{11} = \frac12(1+a)(  \alpha  + 1) - \frac12 , \qquad D_{12}=-a\left(\alpha   - \frac12\right),\\
&D_{21}= \frac12(1+c)(1-\alpha  ) - \frac12,\qquad D_{22}= c\left(  \alpha + \frac12\right).
\end{aligned}
\]%end{equation}
\end{lemma}

Lemma \ref{lem:leading} was proved in \cite{KMPP,KM19}. The quadratic form \eqref{eq:leading-1} has different values depending on the sign of $\alpha.$ Precisely, the following lemma, proved in \cite{KM19}, shows that $\mathcal Q(t)$ is bounded below by the $H^1\times H^1$ norm of $(\eta,u)$.

\begin{lemma}[Refined positivity of the quadratic form $\mathcal{Q}(t)$]%\label{lem:Q}
Let $a, c <0$ satisfy Definition \ref{New Dis_Par}. Then, we have 
\be\label{Q_new_new}
\mathcal Q(t) \gtrsim \frac{1}{\lambda(t)}\int \sech^2\left( \frac{x}{\lambda(t)} \right)  \left(u^2 + \eta^2 + (\partial_x u)^2 + (\partial_x \eta)^2 \right).
\ee
\end{lemma}

Estimate \eqref{Q_new_new} must be confronted now with the influence of the bottom $h$, specified in the term $\mathcal{NH}(t)$ \eqref{eq:H}. 

Let $\varphi$ be a smooth bounded weight function such that  $\varphi'>0$ and $\la=\lambda(t)$ be the time-dependent weight given by
\begin{equation}\label{eq:lambda}
\lambda(t) := \frac{t}{\log t \log^2 (\log t)}, \quad t\geq 11,
\end{equation}
precisely corresponding to the upper limit of the space interval $I(t)$ \eqref{I(t)}. The following result is stated for times $t\geq 11$, but it can be easily stated and proved for corresponding negative times by correspondely changing \eqref{eq:lambda}.

\begin{lemma}
There exists $C>0$ such that one has
\begin{equation}\label{cota_NH}
\begin{aligned}
 \left|  \mathcal{NH}(t)  \right| 
& \le   (4\delta + C\varepsilon ) \int  \varphi'  u^2 +4 \delta  \int  \varphi'  (\partial_x u)^2  +4\delta \int \varphi' \eta^2 +4\delta \int \varphi' (\partial_x \eta)^2\\
&~{} \quad   + C_\delta \|  \partial_t   h  \|_{L^2}^2 + C_\delta \|  \partial_t \partial_x  h  \|_{L^2}^2  + C_\delta \|  \partial_t^2  h  \|_{L^2}^2 + C\| \partial_x h \|_{L^\infty}\\
&~{} \quad + C  \|\partial_t^2  h \|_{L^2} + C  \| \partial_x \partial_t h \|_{L^2} + \frac{C}{t^{3/2}}.
\end{aligned}
\end{equation}
\end{lemma}

\begin{proof}
From \eqref{eq:H} and \eqref{hyp_h} we compute:  
\[
\begin{aligned}
 \left| \frac12 \int  \partial_x (\varphi h) u^2  \right| \lesssim & ~{} \left| \int  \varphi  \partial_x h u^2  \right|  +\left|  \int  \varphi' h u^2  \right|  \\
 \lesssim &~{} \left| \int  \varphi  \partial_x h u^2  \right|  + \varepsilon  \int  \varphi'  u^2\\
  \lesssim &~{} \| \partial_x h \|_{L^\infty}  + \varepsilon  \int  \varphi'  u^2.
\end{aligned}
\]
Similarly,
\[
\begin{aligned}
& \left|  \alpha \int\vp'u^2 h \right| \lesssim \varepsilon \int \varphi' u^2.
\end{aligned}
\]
Second, we use the bound $\| \varphi' (1-\partial_x^2)^{-1} f\|_{L^2} \lesssim \| \varphi' f\|_{L^2}$,
\[
\begin{aligned}
& \left|   \int \varphi' u (1-\partial_x^2)^{-1}\left( u h \right) \right| \\
& \quad \le \delta \int \varphi' u^2 + C_\delta \int  \varphi' |(1-\partial_x^2)^{-1}\left( u h \right)|^2\\
& \quad \le \delta \int \varphi' u^2 + C_\delta \int  \varphi'  ( u h )^2  \le  (\delta +C_\delta  \varepsilon )\int \varphi' u^2. 
\end{aligned}
\]
Now, using the value of $\lambda$ in \eqref{eq:lambda} along with \eqref{eq:sech_Opg} and \eqref{eq:sech_Opg_p},
\[
\begin{aligned}
&  \left|   \alpha  \int \vp''u\nlop \partial_x (u h)  \right| \\
& \lesssim \left|  \int \vp'''u\nlop uh \right| +\left|  \int \vp'' \partial_x u\nlop \partial_x (uh)  \right| \\
& \lesssim \frac1{\lambda^3} \int \vp' |u| |\nlop uh | + \frac1{\lambda^2(t)} \int \vp' |\partial_x u| |\nlop \partial_x (u h)| \\
& \lesssim \frac1{\lambda^3} \left( \int \vp' u^2 + \int \varphi'  u^2 h^2 \right) + \frac1{\lambda^2(t)}\left(  \int \vp'  (\partial_x u)^2 + \int \varphi' (u h)^2 \right)\\
& \lesssim \frac1{ t^{3/2}}.
\end{aligned}
\]
Similar to previous estimates, the bound $\|(1-\partial_x^2)^{-1} f\|_{L^2}\leq \|f\|_{L^2}$ (Lemma \ref{lem:est_IOp}), we get for $\delta>0$ small,
\[
\begin{aligned}
&   \left| \int \varphi' \eta (1-\partial_x^2)^{-1}  \partial_t^2 \partial^2_x h  \right|  \\
& \quad \lesssim    \left| \int \varphi' \eta   \partial_t^2  h  \right| +  \left| \int \varphi' \eta (1-\partial_x^2)^{-1}  \partial_t^2  h  \right| \le    \delta \int \varphi' \eta^2 + C_\delta \|  \partial_t^2  h  \|_{L^2}^2  . %+  \left| \int \varphi' \eta (1-\partial_x^2)^{-1}  \partial_t^2  h  \right| \\
\end{aligned}
\]
Using again the bound $\|(1-\partial_x^2)^{-1} f\|_{L^2}\leq \|f\|_{L^2}$,
\[
\begin{aligned}
&   \left|  \int  \varphi' u(1-\partial^2_x)^{-1}(1- a_1\partial_x^2)\partial_t\partial_{x}h   \right|  \\
& \quad \lesssim  \left|  \int  \varphi' u(1-\partial^2_x)^{-1}\partial_t\partial_{x}h   \right|  +  \left|  \int  \varphi' u \partial_t\partial_{x}h   \right|  \\
& \quad \le    \delta \int \varphi' u^2 + C_\delta \|  \partial_t \partial_x  h  \|_{L^2}^2  . 
\end{aligned}
\]
Also, by \eqref{eq:sech_Opg_1pp}, we obtain
\[
\begin{aligned}
&  \left|   \alpha  \int\vp' \partial_x u  (1-\partial^2_x)^{-1}\left(-1+ a_1 \partial_x^2\right) \partial_t h \right|   \le   \delta \int \varphi' (\partial_x u)^2 + C_\delta \|  \partial_t  h  \|_{L^2}^2  .
\end{aligned}
\]
Finally,
\[
\begin{aligned}
& \left| c_1  \int \varphi \eta \partial_t^2 \partial_x h + \int \varphi u (-1+  a_1 \partial_x^2)\partial_t h \right| 
\\
& \quad \lesssim  \left|  \int  \partial_x(\varphi \eta) \partial_t^2 h \right| + \left| \int \varphi u \partial_t h \right|  +\left|  \int \partial_x(\varphi u)\partial_x \partial_t h \right| 
\\
& \quad \le  \delta \int \varphi' \eta^2 +\delta \int \varphi' u^2 + C_\delta  \|  \partial_t^2  h  \|_{L^2}^2 +C_\delta  \|  \partial_t\partial_x  h  \|_{L^2}^2 + C\| u\|_{L^2} \|\partial_t h \|_{L^2} 
\\
& \quad + C\| \partial_x \eta \|_{L^2} \|\partial_t^2  h \|_{L^2} + C\| \partial_x u \|_{L^2} \| \partial_x \partial_t h \|_{L^2}  . 
\end{aligned}.
\]
Gathering the previous estimates, we get \eqref{cota_NH}.
\end{proof}

Using \eqref{Q_new_new} and \eqref{cota_NH}, and the smallness of $\varepsilon,$ we obtain for some $C_0>0,$
\be\label{Q_new_new_new}
\begin{aligned}
\mathcal Q(t) \ge &~{}  \frac{1}{C_0\lambda(t)}\int \sech^2\left( \frac{x}{\lambda(t)} \right) \left(u^2 + \eta^2 + (\partial_x u)^2 + (\partial_x \eta)^2 \right)- \frac{C}{t^{3/2}} \\
&~{}  -  C_0 \left( \|  \partial_t   h  \|_{L^2}^2  +  \|  \partial_x \partial_t  h  \|_{L^2}^2    \right)\\
&~{}  -  C_0 \left(  \|  \partial_t^2  h  \|_{L^2}^2 + \| \partial_x h \|_{L^\infty} + \|\partial_t^2  h \|_{L^2} +\| \partial_x \partial_t h \|_{L^2}  \right) .
\end{aligned}
\ee

\begin{proposition}[Decay in time-dependent intervals]\label{prop:virial2}
Let $(a,b,c)$ be \emph{dispersion-like} parameters defined as in Definition \ref{New Dis_Par}. Let $(u,\eta)(t)$ be $H^1 \times H^1$ global solutions to \eqref{boussinesq} such that \eqref{Smallness} holds. Then, we have
\begin{equation}\label{eq:virial2-1}
\int_2^{\infty}\frac{1}{\lambda(t)}\int \sech^2 \left(\frac{x}{\lambda(t)}\right) \left(u^2 + (\px u)^2 + \eta^2 + (\px \eta)^2\right)(t,x) \, dx \,dt\lesssim 1.
\end{equation}
As an immediate consequence, there exists an increasing sequence of time $\{t_n\}$ $(t_n \to \infty$ as $n \to \infty)$ such that
\begin{equation}\label{eq:virial2-2}
\int \sech^2 \left(\frac{x}{\lambda(t_n)}\right) \left(u^2 + (\px u)^2 + \eta^2 + (\px \eta)^2\right)(t_n,x) \; dx \longrightarrow 0 \mbox{ as } n \to \infty.
\end{equation}
\end{proposition}

\begin{proof}
The proof is standard, but we write it for the sake of completeness. We choose, in functionals $\mathcal{I}$ and $\mathcal{J}$ (see \eqref{I}-\eqref{J}),  the time-dependent weight
\begin{equation}\label{eq:vp}
\vp (t,x):= \tanh \left(\frac{x}{\lambda(t)}\right) \quad \mbox{and} \quad \partial_x\vp(t,x) := \frac{1}{\lambda(t)} \sech^2\left(\frac{x}{\lambda(t)}\right),
\end{equation}
with $\la(t)$ given by \eqref{eq:lambda}. Note that
\[
\begin{aligned}
\lambda'(t)= \frac1{\log t \log^2(\log t)} \left( 1 -\frac{1}{\log t}  -\frac{2}{\log t \log(\log t)} \right),
\end{aligned}
\]
then
\[%begin{equation}\label{eq:lambda1}
\frac{\lambda'(t)}{\lambda(t)} = \frac{1}{t}\left(1-\frac{1}{\log t} -\frac{2}{\log t \log(\log t)} \right) \not\in L^1[11,+\infty),
\]%end{equation}
and
\begin{equation}\label{eq:lambda2}
\frac{\lambda'^2(t)}{\lambda(t)} = \frac1{t \log t \log^2(\log t)} \left( 1 -\frac{1}{\log t}  -\frac{2}{\log t \log(\log t)} \right)^2 \le  \frac1{t \log t \log^2(\log t)}.
\end{equation}
From \eqref{eq:lambda2} one realizes that $\lambda'^2(t)/\lambda(t)$ is integrable in $[11,+\infty)$. Indeed, notice that 
\[
\left( \frac{1}{\log(\log t)}\right)'  = -\frac{1}{t \log t \log^2(\log t)}. 
\]
Then, we compute \eqref{eq:gvirial}, but in addition from \eqref{I} and \eqref{J} we will obtain from \eqref{eq:vp} the following three new terms:
\begin{equation}\label{eq:gvirial-I}
-\frac{\lambda'(t)}{\lambda(t)} \int \frac{x}{\lambda(t)}\sech^2\left( \frac{x}{\lambda(t)}\right) \left(u\eta + \px u \px \eta\right),
\end{equation}
and
\begin{equation}\label{eq:gvirial-J}
-\alpha\frac{\lambda'(t)}{\lambda^2(t)} \int\left(1- \frac{2x}{\lambda(t)}\tanh\left( \frac{x}{\lambda(t)}\right)\right)\sech^2\left( \frac{x}{\lambda(t)} \right) \eta \px u.
\end{equation}
Now we use a similar computation as the one performed in \cite{KMPP}, but $\lambda(t)$ now is slightly better. First, thanks to the global well-posedness, 
\[
\begin{aligned}
& \left|\frac{\lambda'(t)}{\lambda(t)} \int \frac{x}{\lambda(t)} \sech^2\left( \frac{x}{\lambda(t)}\right) \left(u\eta + \px u \px \eta\right) \right|
\\
& \lesssim \frac1{4\lambda(t)} \int \sech^2\left( \frac{x}{\lambda(t)}\right) (\eta^2 +(\partial_x \eta)^2 ) + \frac{C \lambda'^2(t)}{\lambda(t)} \sup_{y \in\mathbb R} y^2 \sech^2 y \int (u^2 +(\partial_x u)^2 ) \\
& \lesssim \frac1{4\lambda(t)} \int \sech^2\left( \frac{x}{\lambda(t)}\right) (\eta^2 +(\partial_x \eta)^2 ) + \frac{C \lambda'^2(t)}{\lambda(t)}\\
& \lesssim \frac1{4\lambda(t)} \int \sech^2\left( \frac{x}{\lambda(t)}\right) (\eta^2 +(\partial_x \eta)^2 ) + \frac{C}{t \log t \log^2(\log t)}.
\end{aligned}
\]
Also,
\[
\left| \alpha\frac{\lambda'(t)}{\lambda^2(t)} \int\left(1- \frac{2x}{\lambda(t)}\tanh\left( \frac{x}{\lambda(t)}\right)\right)\sech^2\left( \frac{x}{\lambda(t)} \right) \eta \px u \right| \lesssim \frac1{t^2} \int (\eta^2 + (\px u)^2).
\]
We conclude,
\begin{equation}\label{eq:virial2-3}
\begin{aligned}
|\eqref{eq:gvirial-I}| &+| \eqref{eq:gvirial-J} | \\
\le&~{} \frac{c_0}{\lambda(t)} \int \sech^2\Big( \frac{x}{\lambda(t)}\Big) \left(u^2 + (\px u)^2 + \eta^2 + (\px \eta)^2\right) + \frac{\wt{C}}{t \log t \log^2(\log t)},
\end{aligned}
\end{equation}
for a fixed constant $\wt{C} > 0$. Using this last estimate \eqref{eq:virial2-3} and \eqref{Q_new_new_new}, we obtain % a new estimate for $\frac{d}{dt} \mathcal H(t)$ of the form
\begin{equation}\label{eq:virial2-3.1}
\begin{aligned}
& \frac{1}{\lambda(t)}\int \sech^2\Big(\frac{x}{\lambda(t)}\Big) (u^2 +\eta^2 +(\partial_x u)^2 +(\partial_x \eta)^2 ) \\
& \leq C \frac{d}{dt} \mathcal H(t) + \frac{C}{t \log t \log^2(\log t)} \\
& \quad +C \left( \|  \partial_t   h  \|_{L^2}^2  +  \|  \partial_t \partial_x  h  \|_{L^2}^2  + \|  \partial_t^2  h  \|_{L^2}^2 + \| \partial_x h \|_{L^\infty} \right).
\end{aligned}
\end{equation}
Since from \eqref{hyp_h} the left-hand side of \eqref{eq:virial2-3.1} is integrable in $t$ on $[11,\infty)$, but $\la^{-1}$ does not integrate on $[11,\infty)$, one concludes \eqref{eq:virial2-1} in Proposition \ref{prop:virial2}.
\end{proof}


\section{Energy estimates}\label{ENERGY}


The proof of estimate \eqref{Conclusion_0} requires to show that the local $H^1$ norms of $(u,\eta)(t)$ converge to zero for all sequences $t_n\to +\infty$, and not only a particular one. In order to prove such a result, we will use a new energy estimate. A key element will be \eqref{coercividad}, which states that for small solutions, the $H^1\times H^1$ norm of $(u,\eta)(t)$ squared and the hamiltonian $H_h[u,\eta]$ in \eqref{Energy_new} are equivalent.

 Let $\psi = \psi(x)$ be a smooth, nonnegative and bounded function, to be chosen in the sequel. We consider the localized energy functional defined by
\begin{equation}\label{eq:local energy}
E_\text{loc}(t) = \frac12 \int \psi(t,x) \left( - a(\px u)^2 - c(\px \eta)^2 + u^2 + \eta^2 + u^2(\eta+h)\right)(t,x)dx.
\end{equation}
(Compare with \eqref{Energy_new}.) For the sake of simplicity, we introduce the following notations:
\be\label{ABFG}
\begin{aligned}
&A := a \partial_x^2u+ u +u(\eta+h), \hspace{2em} B: = c\partial_x^2 \eta + \eta + \frac12u^2,\\
&F := (1-\px^2)^{-1} A, \hspace{2.9em} G: = (1-\px^2)^{-1}B.
\end{aligned}
\ee
(In other words, $F$ and $G$ are the canonical variables of $A$ and $B$, respectively.) Notice that \eqref{boussinesq} now becomes
\begin{equation}\label{boussinesqABFG}
\begin{cases}
\partial_t \eta  + \partial_x F = (1-\px^2)^{-1} (-1 + a_1 \partial_x^2) \partial_th  , \\
\partial_t u  + \partial_xG= c_1  (1-\px^2)^{-1} \partial_t^2 \partial_x h.
\end{cases}
\end{equation}
We will also use canonical variables $f$ and $g$ for $u$ and $\eta$, and the following identities:
\begin{equation}\label{eq:E34-2}
\partial_x^3 f \partial_x g = \partial_x( \partial_x^2 f \partial_xg)  - \partial_x^2 f \partial_x^2 g \hspace{1em} \mbox{and} \hspace{1em} \partial_xf \partial_x^3 g = \partial_x (\partial_x f \partial_x^2 g) - \partial_x^2 f \partial_x^2 g,
\end{equation}
and
\be\label{Aux_00}
\partial_x^2 f g = \partial_x(\partial_x f g) - \partial_xf \partial_xg  \hspace{1em} \mbox{and} \hspace{1em} f \partial_x^2 g = \partial_x(f \partial_xg ) - \partial_x f \partial_xg.
\ee
We have

\begin{lemma}[Variation of local energy $E_\text{loc}$]\label{lem:energy1}
Let $u$ and $\eta$ satisfy \eqref{boussinesq}. Let $f$ and $g$ be canonical variables of $u$ and $\eta$ as in \eqref{eq:fg}. Then, the following holds:
\begin{enumerate}
\item Time derivative. We have in \eqref{eq:local energy},
\begin{equation}\label{eq:energy1}
\begin{aligned}
\frac{d}{dt} E_\emph{loc}(t) =&~{} \int \psi' fg + (1-2(a+c)) \int \psi' \partial_x f \partial_x g  \\
&+ (3ac-2(a+c))\int \psi'  \partial_x^2 f \partial_x^2 g + 3ac\int \psi'  \partial_x^3 f\partial_x^3 g\\
&+ \emph{SNL}_0(t) +\emph{SNL}_1(t)+\emph{SNL}_{h}(t) .
\end{aligned}
\end{equation}
\item The small nonlinear parts $\emph{SNL}_j(t)$ are given by
\begin{equation}\label{eq:SNL0}
\emph{SNL}_0(t) := \frac12 \int \partial_t \psi \left( - a(\px u)^2 - c(\px \eta)^2 + u^2 + \eta^2 + u^2(\eta+h)\right),
\end{equation}
and $\text{SNL}_1(t)$ is given in \eqref{eq:E1E2E3E4_new2}

\item The strong (and weak) interaction terms with the bottom $h$ are given by
\begin{equation}\label{eq:SNLh}
\begin{aligned}
\emph{SNL}_h(t) := & ~{}
 \frac12 \int \psi u^2 \partial_t h 
+c_1  \int \psi  F \partial_t^2\partial_x h +   \int \psi  G (-1+a_1\partial_x^2)\partial_t h 
\\&
-c_1  \int  (\psi'' F (1-\partial_x^2)^{-1}\partial_t^2\partial_x h +2\psi'  F (1-\partial_x^2)^{-1}\partial_t^2\partial_x^2 h  ) 
\\&
-  \int  \psi'' G (1-\partial_x^2)^{-1}(-1+a_1\partial_x^2)\partial_t h
\\&
-  2\int \psi'  G (1-\partial_x^2)^{-1}(-1+a_1\partial_x^2)\partial_x\partial_t h 
.
\end{aligned}
\end{equation}
\end{enumerate}
\end{lemma}

\begin{proof}
We take the time derivative to $E_\text{loc}(t)$. The change of variable with notations $A, B, F$ and $G$ and the definition of $\text{SNL}_0(t)$ in \eqref{eq:SNL0} yields
\[
\begin{aligned}
& \frac{d}{dt} E_\text{loc}(t) 
\\
&~{} =\frac12 \int \partial_t \psi \left( - a(\px u)^2 - c(\px \eta)^2 + u^2 + \eta^2 + u^2(\eta+h)\right)\\
&~{} \quad + \int \psi \left(-a \partial_x  u \partial_x \partial_t u + u \partial_t u -c\partial_x \eta \partial_x \partial_t \eta + \eta \partial_t \eta +u(\eta +h) \partial_t u + \frac12 u^2  (\partial_t \eta +\partial_t h)\right)\\
&~{} = %\text{SNL}_0(t) 
\frac12 \int \partial_t \psi \left( - a(\px u)^2 - c(\px \eta)^2 + u^2 + \eta^2 + u^2(\eta+h)\right)
\\&\qquad \quad+ \int \psi\left(\partial_t u A + \partial_t \eta B\right) + a\int \psi' \partial_t u  \partial_x  u + c\int \psi' \partial_t \eta \partial_x \eta +\frac12 \int \psi u^2 \partial_t h.
\end{aligned}
\]
Using \eqref{boussinesqABFG},
\[
\begin{aligned}
& \frac{d}{dt} E_\text{loc}(t) \\
& = %\text{SNL}_0(t) 
\frac12 \int \partial_t \psi \left( - a(\px u)^2 - c(\px \eta)^2 + u^2 + \eta^2 + u^2(\eta+h)\right)
\\&~{}
 -\int \psi \left(\partial_x G  (F-\partial_x^2 F ) + \partial_x F  (G-\partial_x^2 G ) \right)
\\&~{}
+  \int \psi \left(  c_1(F-\partial_x^2 F ) (1-\partial_x^2)^{-1}\partial_t^2\partial_x h +   (G-\partial_x^2 G )(1-\partial_x^2)^{-1}(-1+a_1\partial_x^2)\partial_t h \right)
\\
&~{} + a\int \psi' \partial_t u  \partial_x  u + c\int \psi' \partial_t \eta \partial_x \eta +\frac12 \int \psi u^2 \partial_t h \\
& =
\frac12 \int \partial_t \psi \left( - a(\px u)^2 - c(\px \eta)^2 + u^2 + \eta^2 + u^2(\eta+h)\right)
\\&~{}
+\int \psi' FG - \int \psi'\partial_x F \partial_x G  + a\int \psi' \partial_t u \partial_x u + c\int \psi' \partial_t \eta  \partial_x \eta
~{}
+\frac12 \int \psi u^2 \partial_t h
\\&~{}
+  \int \psi \left(  c_1(F-\partial_x^2 F ) (1-\partial_x^2)^{-1}\partial_t^2\partial_x h +   (G-\partial_x^2 G )(1-\partial_x^2)^{-1}(-1+a_1\partial_x^2)\partial_t h \right)
\\
& =: \text{SNL}_0(t) + E_1+E_2+E_3+E_4 +
E_5+E_6
.
\end{aligned}
\]
We first deal with $E_1$ and $E_2$. From \eqref{ABFG} we have
\[
F = a\, \partial_x^2 f + f + (1-\px^2)^{-1}(u(\eta+h)) \quad \mbox{and} \quad G = c\, \partial_x^2 g + g + \frac12(1-\px^2)^{-1}(u^2).
\]
Using \eqref{eq:E34-2} and \eqref{Aux_00}, then a direct calculation  gives
\begin{equation}\label{eq:E1}
\begin{aligned}
& E_1=\int \psi' FG 
\\
&\quad  =  ac \int \psi' \partial_x^2 f \partial_x^2 g -(a+c) \int \psi'\partial_x f \partial_x g   + \int \psi'fg\\
&\qquad -a\int \psi''\partial_x f  g -c\int \psi'' f \partial_x g \\
&\qquad +\frac{a}{2} \int \psi'\partial_x^2 f  (1-\px^2)^{-1}(u^2) +\frac12\int \psi'f(1-\px^2)^{-1}(u^2)\\
&\qquad +c\int \psi'\partial_x^2 g(1-\px^2)^{-1}(u(\eta+h)) + \int \psi'g(1-\px^2)^{-1}(u(\eta+h)) \\
&\qquad +\frac12\int \psi'(1-\px^2)^{-1}(u(\eta+h))(1-\px^2)^{-1}(u^2).
\end{aligned}
\end{equation}
Similarly, 
\begin{equation}\label{eq:E2}
\begin{aligned}
& E_2=\int \psi' \partial_x F \partial_x G  \\
&\quad  = ac \int \psi'\partial_x^3 f\partial_x^3 g -(a+c) \int \psi'\partial_x^2 f  \partial_x^2 g  + \int \psi'\partial_x f \partial_x g \\
&\qquad -a\int \psi''\partial_x^2 f \partial_x g  -c\int \psi''\partial_x f \partial_x^2 g \\
&\qquad +\frac{a}{2} \int \psi'\partial_x^3 f (1-\px^2)^{-1}\partial_x (u^2) +\frac12\int \psi'\partial_x f (1-\px^2)^{-1}\partial_x (u^2)\\
&\qquad +c\int \psi'\partial_x^3 g(1-\px^2)^{-1}\partial_x (u(\eta+h)) + \int \psi'\partial_x g (1-\px^2)^{-1}\partial_x (u(\eta+h)) \\
&\qquad +\frac12\int \psi'(1-\px^2)^{-1}\partial_x (u(\eta+h)) (1-\px^2)^{-1}\partial_x (u^2).
\end{aligned}
\end{equation}
Now we focus on $E_3$ and $E_4$. Using \eqref{eq:abcd} and integration by parts,
\begin{equation}\label{eq:E3}
\begin{aligned}
E_3 =&~{} a\int \psi' \partial_t u \partial_x u\\
=& ~{}  a\int \psi'  \partial_xu \left( c \px \eta -(1+c)(1-\partial_x^2)^{-1}\px \eta \right)\\
& ~{} + a\int \psi'  \partial_xu \left( - \frac12(1-\partial_x^2)^{-1}\px(u^2) +c_1 (1-\partial^2_x)^{-1}  \partial_t^2 \partial_x h\right)\\
=& ~{} ac\int \psi' \partial_xu\partial_x\eta - a(c+1)\int \psi' \partial_x u (1-\px^2)^{-1}\partial_x\eta\\
&+\frac12 a\int \partial_x(\psi' \partial_xu)(1-\px^2)^{-1}(u^2) + ac_1 \int \psi' \partial_xu  (1-\partial^2_x)^{-1}  \partial_t^2 \partial_x h.
\end{aligned}
\end{equation}
Following a similar approach,
\begin{equation}\label{eq:E4}
\begin{aligned}
E_4 =&~{} c\int \psi' \partial_t \eta \partial_x \eta \\
=&~{} c\int \psi'   \partial_x\eta \left( a \px u -(1+a)(1-\partial_x^2)^{-1}\px u \right) \\
&~{} + c\int \psi'   \partial_x\eta \left(  - (1-\partial_x^2)^{-1}\px(u(\eta+h))  + (1-\partial^2_x)^{-1}\left(-1+ a_1 \partial_x^2\right) \partial_t h\right) \\
=& ~{} ac\int \psi' \partial_x\eta \partial_x u - c(a+1) \int \psi' \partial_x \eta (1-\px^2)^{-1} \partial_x u\\
&~{}+ c\int \partial_x(\psi' \partial_x\eta)(1-\px^2)^{-1}(u(\eta+h))  \\
&~{} + c\int \psi'   \partial_x \eta (1-\partial^2_x)^{-1}\left(-1+ a_1 \partial_x^2\right) \partial_t h .
\end{aligned}
\end{equation}
Therefore, considering \eqref{eq:E3}-\eqref{eq:E4} and adding $E_3$ and $E_4$, we get
\begin{equation}\label{eq:E3E4}
\begin{aligned}
E_3+ E_4 =& ~{} 2ac\int \psi' \partial_x\eta \partial_x u\\
&~{} - a(c+1)\int \psi' \partial_x u (1-\px^2)^{-1}\partial_x\eta - c(a+1) \int \psi' \partial_x \eta (1-\px^2)^{-1} \partial_x u\\
&~{} +\frac12 a\int \partial_x(\psi' \partial_xu)(1-\px^2)^{-1}(u^2) \\
&~{}+ c\int \partial_x(\psi' \partial_x\eta)(1-\px^2)^{-1}(u(\eta+h))  \\
&~{} + ac_1 \int \psi' \partial_xu  (1-\partial^2_x)^{-1}  \partial_t^2 \partial_x h\\
&~{} + c\int \psi'   \partial_x \eta (1-\partial^2_x)^{-1}\left(-1+ a_1 \partial_x^2\right) \partial_t h .
\end{aligned}
\end{equation}
We use now canonical variables $f$ and $g$ for $u$ and $\eta$, and the identities \eqref{eq:E34-2}. We get after integration by parts,
\begin{equation}\label{eq:E34-1.1}
\begin{aligned}
& 2ac  \int \psi' \partial_x u \partial_x \eta  \\
&~ {}\quad= 2ac\int\psi'(\partial_x f \partial_x g  + \partial_x^3 f\partial_x^3 g)  -2ac\int\psi'(\partial_x^3 f\partial_x g  + \partial_x f \partial_x^3 g) \\
&~ {}\quad=2ac\int\psi'(\partial_x f \partial_x g  + \partial_x^3 f\partial_x^3 g)   + 4ac\int\psi' \partial_x^2 f\partial_x^2 g \\
&~ {}\quad\quad + 2ac\int \psi'' ( \partial_x^2 f \partial_xg +\partial_x f \partial_x^2 g).
\end{aligned}
\end{equation}
Similarly,
\begin{equation}\label{eq:E34-1.2}
\begin{aligned}
&- a(c+1)\int \psi' \partial_x u (1-\px^2)^{-1}\partial_x \eta
\\
&~{} \quad = -a(c+1)\int\psi'\partial_x f \partial_x g   +a(c+1)\int\psi'\partial_x^3 f\partial_x g \\
&~{} \quad = -a(c+1)\int\psi'\partial_x f \partial_x g  - a(c+1)\int\psi'\partial_x^2 f\partial_x^2 g - a(c+1)\int\psi''\partial_x^2 f\partial_x g.
\end{aligned}
\end{equation}
Finally,
\begin{equation}\label{eq:E34-1.3}
\begin{aligned}
& - c(a+1) \int \psi' \partial_x \eta(1-\px^2)^{-1}\partial_x u 
\\
&~ {} \quad= -c(a+1)\int\psi'\partial_x f \partial_x g  +c(a+1)\int\psi'\partial_x f \partial_x^3 g \\
&~ {} \quad= -c(a+1)\int\psi'\partial_x f \partial_x g -c(a+1)\int\psi'\partial_x^2 f \partial_x^2 g-c(a+1)\int\psi''\partial_x f \partial_x^2 g.
\end{aligned}
\end{equation}
Replacing \eqref{eq:E34-1.1}-\eqref{eq:E34-1.2}-\eqref{eq:E34-1.3} in \eqref{eq:E3E4},
\begin{equation}\label{eq:E34-3}
\begin{aligned}
E_3+ E_4 =&~{} -(a+c)\int \psi'\partial_x f \partial_x g  + (2ac-(a+c))\int\psi'\partial_x^2 f \partial_x^2 g \\
&~{}+ 2ac\int\psi'\partial_x^3 f\partial_x^3 g\\
&~{}+a(c-1)\int\psi''\partial_x^2 f \partial_x g +c(a-1)\int\psi''\partial_x f \partial_x^2 g\\
&~{} +\frac12 a\int \partial_x(\psi' \partial_xu)(1-\px^2)^{-1}(u^2) \\
&~{}+ c\int \partial_x(\psi' \partial_x\eta)(1-\px^2)^{-1}(u(\eta+h))  \\
&~{} + ac_1 \int \psi' \partial_xu  (1-\partial^2_x)^{-1}  \partial_t^2 \partial_x h\\
&~{} + c\int \psi'   \partial_x \eta (1-\partial^2_x)^{-1}\left(-1+ a_1 \partial_x^2\right) \partial_t h .
%&+\text{SNL}_1(t).
\end{aligned}
\end{equation}
Now, from \eqref{eq:E1}, \eqref{eq:E2} and  \eqref{eq:E34-3}, we get
\begin{equation}\label{eq:E1E2E3E4}
\begin{aligned}
& E_1+E_2+E_3+E_4\\
%E1
&~{}  =  ac \int \psi' \partial_x^2 f \partial_x^2 g -(a+c) \int \psi'\partial_x f \partial_x g   + \int \psi'fg\\
&\qquad -a\int \psi''\partial_x f  g -c\int \psi'' f \partial_x g \\
&\qquad +\frac{a}{2} \int \psi'\partial_x^2 f  (1-\px^2)^{-1}(u^2) +\frac12\int \psi'f(1-\px^2)^{-1}(u^2)\\
&\qquad +c\int \psi'\partial_x^2 g(1-\px^2)^{-1}(u(\eta+h)) + \int \psi'g(1-\px^2)^{-1}(u(\eta+h)) \\
&\qquad +\frac12\int \psi'(1-\px^2)^{-1}(u(\eta+h))(1-\px^2)^{-1}(u^2)\\
%E2
&\qquad + ac \int \psi'\partial_x^3 f\partial_x^3 g -(a+c) \int \psi'\partial_x^2 f  \partial_x^2 g  + \int \psi'\partial_x f \partial_x g \\
&\qquad -a\int \psi''\partial_x^2 f \partial_x g  -c\int \psi''\partial_x f \partial_x^2 g \\
&\qquad +\frac{a}{2} \int \psi'\partial_x^3 f (1-\px^2)^{-1}\partial_x (u^2) +\frac12\int \psi'\partial_x f (1-\px^2)^{-1}\partial_x (u^2)\\
&\qquad +c\int \psi'\partial_x^3 g(1-\px^2)^{-1}\partial_x (u(\eta+h)) + \int \psi'\partial_x g (1-\px^2)^{-1}\partial_x (u(\eta+h)) \\
&\qquad +\frac12\int \psi'(1-\px^2)^{-1}\partial_x (u(\eta+h)) (1-\px^2)^{-1}\partial_x (u^2)\\
%E3+E4
&\qquad  -(a+c)\int \psi'\partial_x f \partial_x g  + (2ac-(a+c))\int\psi'\partial_x^2 f \partial_x^2 g \\
&\qquad + 2ac\int\psi'\partial_x^3 f\partial_x^3 g+a(c-1)\int\psi''\partial_x^2 f \partial_x g +c(a-1)\int\psi''\partial_x f \partial_x^2 g\\
&\qquad  +\frac12 a\int \partial_x(\psi' \partial_xu)(1-\px^2)^{-1}(u^2)   + c\int \partial_x(\psi' \partial_x\eta)(1-\px^2)^{-1}(u(\eta+h))  \\
&\qquad  + ac_1 \int \psi' \partial_xu  (1-\partial^2_x)^{-1}  \partial_t^2 \partial_x h  + c\int \psi'   \partial_x \eta (1-\partial^2_x)^{-1}\left(-1+ a_1 \partial_x^2\right) \partial_t h .
\end{aligned}
\end{equation}
After some simplifications, \eqref{eq:E1E2E3E4} becomes
\begin{equation}\label{eq:E1E2E3E4_new}
\begin{aligned}
& E_1+E_2+E_3+E_4\\
&~{}  =  (3ac -2(a+c))\int \psi' \partial_x^2 f \partial_x^2 g +(1-2(a+c)) \int \psi'\partial_x f \partial_x g   + \int \psi'fg\\
&\qquad + 3ac \int \psi'\partial_x^3 f\partial_x^3 g    +  \text{SNL}_1(t),
\end{aligned}
\end{equation}
where
\begin{equation}\label{eq:E1E2E3E4_new2}
\begin{aligned}
& \text{SNL}_1(t)\\
&~{}  := a(c-1)\int\psi''\partial_x^2 f \partial_x g +c(a-1)\int\psi''\partial_x f \partial_x^2 g\\
&\qquad -a\int \psi''\partial_x f  g -c\int \psi'' f \partial_x g  -a\int \psi''\partial_x^2 f \partial_x g  -c\int \psi''\partial_x f \partial_x^2 g \\
&\qquad +\frac{a}{2} \int \psi'\partial_x^2 f  (1-\px^2)^{-1}(u^2) +\frac12\int \psi'f(1-\px^2)^{-1}(u^2)\\
&\qquad +c\int \psi'\partial_x^2 g(1-\px^2)^{-1}(u(\eta+h)) + \int \psi'g(1-\px^2)^{-1}(u(\eta+h)) \\
&\qquad +\frac12\int \psi'(1-\px^2)^{-1}(u(\eta+h))(1-\px^2)^{-1}(u^2)\\
%E2
&\qquad +\frac{a}{2} \int \psi'\partial_x^3 f (1-\px^2)^{-1}\partial_x (u^2) +\frac12\int \psi'\partial_x f (1-\px^2)^{-1}\partial_x (u^2)\\
&\qquad +c\int \psi'\partial_x^3 g(1-\px^2)^{-1}\partial_x (u(\eta+h)) + \int \psi'\partial_x g (1-\px^2)^{-1}\partial_x (u(\eta+h)) \\
&\qquad +\frac12\int \psi'(1-\px^2)^{-1}\partial_x (u(\eta+h)) (1-\px^2)^{-1}\partial_x (u^2)\\
%E3+E4
&\qquad  +\frac12 a\int \partial_x(\psi' \partial_xu)(1-\px^2)^{-1}(u^2)   + c\int \partial_x(\psi' \partial_x\eta)(1-\px^2)^{-1}(u(\eta+h))  \\
&\qquad  + ac_1 \int \psi' \partial_xu  (1-\partial^2_x)^{-1}  \partial_t^2 \partial_x h  + c\int \psi'   \partial_x \eta (1-\partial^2_x)^{-1}\left(-1+ a_1 \partial_x^2\right) \partial_t h .
\end{aligned}
\end{equation}
Now, let us focus on $E_6$. Integrating by parts and rearranging the terms, we have
\[
\begin{aligned}
E_6
=&~{} c_1  \int \psi  F (1-\partial_x^2)^{-1}\partial_t^2\partial_x h 
-c_1  \int F \partial_x^2(\psi  (1-\partial_x^2)^{-1}\partial_t^2\partial_x h ) 
\\&
+   \int \psi  G (1-\partial_x^2)^{-1}(-1+a_1\partial_x^2)\partial_t h 
-  \int G \partial_x^2(\psi  (1-\partial_x^2)^{-1}(-1+a_1\partial_x^2)\partial_t h )
\\
=&~{} c_1  \int \psi  F \partial_t^2\partial_x h +   \int \psi  G (-1+a_1\partial_x^2)\partial_t h 
\\&
-c_1  \int  (\psi'' F (1-\partial_x^2)^{-1}\partial_t^2\partial_x h +2\psi'  F (1-\partial_x^2)^{-1}\partial_t^2\partial_x^2 h  ) 
\\&
-  \int  (\psi'' G (1-\partial_x^2)^{-1}(-1+a_1\partial_x^2)\partial_t h +2\psi'  G (1-\partial_x^2)^{-1}(-1+a_1\partial_x^2)\partial_x\partial_t h )
\end{aligned}
\]
Letting $\text{SNL}_{h}:=E_5+E_6$, we obtain
\begin{equation}\label{E56}
\begin{aligned}
\mbox{SNL}_{h}(t):=&~{} \frac12 \int \psi u^2 \partial_t h 
+c_1  \int \psi  F \partial_t^2\partial_x h +   \int \psi  G (-1+a_1\partial_x^2)\partial_t h 
\\&
-c_1  \int  (\psi'' F (1-\partial_x^2)^{-1}\partial_t^2\partial_x h +2\psi'  F (1-\partial_x^2)^{-1}\partial_t^2\partial_x^2 h  ) 
\\&
-  \int  \psi'' G (1-\partial_x^2)^{-1}(-1+a_1\partial_x^2)\partial_t h 
\\&
-2  \int  \psi'  G (1-\partial_x^2)^{-1}(-1+a_1\partial_x^2)\partial_x\partial_t h 
.
\end{aligned}
\end{equation}
Thus, from \eqref{eq:E1E2E3E4_new}, \eqref{eq:E1E2E3E4_new2}  and \eqref{E56} we have proved \eqref{eq:energy1}. This ends the proof of Lemma \ref{lem:energy1}. % with \eqref{eq:SNL1}-\eqref{eq:SNL4}.
\end{proof}



\section{Proof of the Theorem \ref{MT1}}\label{7}


Now we finally prove Theorem \ref{MT1}. Let $\la(t)$ be given by \eqref{eq:lambda}. First, we take in \eqref{eq:energy1}:
\be\label{psi_psi}
\psi (t,x):= \sech^4 \left(\frac{x}{\lambda(t)}\right).
\ee
Note that \eqref{psi_psi} satisfies %, where $\vp'$ is chosen as in the proof of Proposition \ref{prop:virial}. Note that
\begin{equation}\label{eq:weight3}
|\partial_x \psi(t,x)| \le \frac{4}{\lambda(t)}\psi (t,x) \qquad \mbox{and} \qquad |\partial_x^2 \psi(t,x)| \le \frac{20}{\lambda(t)} |\partial_x \psi(t,x)|.
\end{equation}

\begin{proposition}\label{prop:energy2}
Let $(a,b,c)$ be parameters defined as in Definition \ref{New Dis_Par}. Let $(u,\eta)(t)$ be a small $H^1 \times H^1$ global solution to \eqref{boussinesq} such that \eqref{Smallness} holds. Then, we have
\begin{equation}\label{eq:energy2.1}
\lim_{t \to \infty} \int \sech^4 \left(\frac{x}{\lambda(t)}\right) \left(u^2 + (\px u)^2 + \eta^2 + (\px \eta)^2\right)(t,x) \; dx = 0.
\end{equation}
\end{proposition}

Notice that this result proves Theorem \ref{MT1}.

\begin{proof}[Proof of Proposition \ref{prop:energy2}]
We shall use Lemma \ref{lem:energy1}. From \eqref{eq:energy1} one has
\begin{equation}\label{eq:energy1_new}
\begin{aligned}
\frac{d}{dt} E_\text{loc}(t) =&~{} \int \psi' fg + (1-2(a+c)) \int \psi' \partial_x f \partial_x g  \\
&+ (3ac-2(a+c))\int \psi'  \partial_x^2 f \partial_x^2 g + 3ac\int \psi'  \partial_x^3 f\partial_x^3 g\\
&+ \text{SNL}_0(t) +\text{SNL}_1(t) +\text{SNL}_h(t).
\end{aligned}
\end{equation}
with
\[%begin{equation}%\label{eq:SNL0}
\text{SNL}_0(t) := \frac12 \int \partial_t \psi \left( - a(\px u)^2 - c(\px \eta)^2 + u^2 + \eta^2 + u^2(\eta+h)\right),
\]%end{equation}
and $\text{SNL}_1(t)$ is given in \eqref{eq:E1E2E3E4_new2}. Bounding \eqref{eq:SNL0} is easy following \eqref{psi_psi}: one has
\begin{equation}\label{eq:E1E2E3E4_new2_m1}
\begin{aligned}
& |\text{SNL}_0(t)|   \lesssim {\color{red} \frac1{\lambda(t)} } %{\color{red} \frac1{t \lambda} }
\int \psi (|\eta|^2 +|\partial_x \eta|^2 +|u|^2 +|\partial_x u|^2 +|h|^2 ).
\end{aligned}
\end{equation} 
Following \eqref{eq:L2_est}-\eqref{eq:H1_est}, and estimates \eqref{eq:nonlinear1-1}, \eqref{eq:nonlinear1-2}, \eqref{eq:nonlinear1-3} and \eqref{eq:nonlinear1-4}, we bound $|\text{SNL}_1(t)|$ in \eqref{eq:E1E2E3E4_new2} as follows:
\begin{equation}\label{eq:E1E2E3E4_new2_0}
\begin{aligned}
& |\text{SNL}_1(t)| \\
& \quad  \lesssim \frac1{\lambda(t)}\int \psi (|\eta|^2 +|\partial_x \eta|^2 +|u|^2 +|\partial_x u|^2 +|h|^2 +|\partial_t h|^2 +|\partial_x h|^2 +|\partial_t^2 \partial_xh|^2).
\end{aligned}
\end{equation}
Indeed, one has from \eqref{eq:weight3} and \eqref{eq:L2_est},
\begin{equation}\label{eq:E1E2E3E4_new2_1}
\begin{aligned}
&~{}  \Big| a(c-1)\int\psi''\partial_x^2 f \partial_x g +c(a-1)\int\psi''\partial_x f \partial_x^2 g \Big|  \\
& \qquad \lesssim   \frac1{\lambda^2(t)}\int \psi (|\eta|^2  +|u|^2 ).
\end{aligned}
\end{equation}
Second, using again \eqref{eq:weight3} and \eqref{eq:H1_est},
\begin{equation}\label{eq:E1E2E3E4_new2_2}
\begin{aligned}
&~{}  \Big|  -a\int \psi''\partial_x f  g -c\int \psi'' f \partial_x g  -a\int \psi''\partial_x^2 f \partial_x g  -c\int \psi''\partial_x f \partial_x^2 g \Big|  \\
& \qquad \lesssim  \frac1{\lambda^2(t)}\int \psi (|\eta|^2  +|u|^2 ).
\end{aligned}
\end{equation}
Third, using \eqref{eq:nonlinear1-2},
\begin{equation}\label{eq:E1E2E3E4_new2_3}
\begin{aligned}
&~{}  \Big|\frac{a}{2} \int \psi'\partial_x^2 f  (1-\px^2)^{-1}(u^2) +\frac12\int \psi'f(1-\px^2)^{-1}(u^2) \Big|   \lesssim \frac1{\lambda(t)} \|\eta\|_{H^1}\int \psi |u|^2.
\end{aligned}
\end{equation}
Fourth, using again \eqref{eq:nonlinear1-2},
\begin{equation}\label{eq:E1E2E3E4_new2_4}
\begin{aligned}
&~{}  \Big|c\int \psi'\partial_x^2 g(1-\px^2)^{-1}(u(\eta+h)) + \int \psi'g(1-\px^2)^{-1}(u(\eta+h))  \Big|  \\
& \qquad \lesssim \frac1{\lambda(t)} \| u \|_{H^1}\int \psi (|u|^2 +|\eta|^2 + |h|^2). %\Big|c\int \psi'\partial_x^2 g(1-\px^2)^{-1}(u(\eta+h)) + \int \psi'g(1-\px^2)^{-1}(u(\eta+h))  \Big| 
\end{aligned}
\end{equation}
Fifth, using again \eqref{eq:nonlinear1-2},
\begin{equation}\label{eq:E1E2E3E4_new2_5}
\begin{aligned}
&~{}  \Big| \frac12\int \psi'(1-\px^2)^{-1}(u(\eta+h))(1-\px^2)^{-1}(u^2) \Big|  \\
& \qquad \lesssim  \frac1{\lambda(t)} \| (1-\px^2)^{-1}(u^2) \|_{H^1}\int \psi (|u|^2 +|\eta|^2 +|h|^2)\\
& \qquad \lesssim  \frac1{\lambda(t)} \| u \|_{L^2}^2 \int \psi (|u|^2 +|\eta|^2 +|h|^2).
\end{aligned}
\end{equation}
Now, using \eqref{eq:nonlinear1-4},
\begin{equation}\label{eq:E1E2E3E4_new2_6}
\begin{aligned}
&~{}  \Big| \frac{a}{2} \int \psi'\partial_x^3 f (1-\px^2)^{-1}\partial_x (u^2) +\frac12\int \psi'\partial_x f (1-\px^2)^{-1}\partial_x (u^2) \Big| \\
& \qquad \lesssim \frac1{\lambda(t)} \| \eta \|_{H^1}\int \psi (|u|^2  + |\partial_x u |^2).
\end{aligned}
\end{equation}
Similarly,
\begin{equation}\label{eq:E1E2E3E4_new2_7}
\begin{aligned}
&~{}  \Big| c\int \psi'\partial_x^3 g(1-\px^2)^{-1}\partial_x (u(\eta+h)) + \int \psi'\partial_x g (1-\px^2)^{-1}\partial_x (u(\eta+h))\Big| \\
& \qquad \lesssim \frac1{\lambda(t)} \| u \|_{H^1}\int \psi (|u|^2  + |\partial_x u |^2 + |\eta |^2  + |\partial_x \eta |^2 +|h|^2  + |\partial_x h |^2).
\end{aligned}
\end{equation}
Similar to \eqref{eq:E1E2E3E4_new2_5}, and using estimates from \cite{KMM} (see Lemma \ref{lem:est_IOp}),
\begin{equation}\label{eq:E1E2E3E4_new2_8}
\begin{aligned}
&~{}  \Big|\frac12\int \psi'(1-\px^2)^{-1}\partial_x (u(\eta+h)) (1-\px^2)^{-1}\partial_x (u^2) \Big| \\
& \qquad \lesssim  \frac1{\lambda(t)} \| (1-\px^2)^{-1} \partial_x (u^2) \|_{H^1}\\
& \qquad \quad \times \int \psi (|u|^2 +|\partial_xu|^2 +|\eta|^2 +|\partial_x\eta |^2+|h|^2+|\partial_xh|^2)\\
& \qquad \lesssim  \frac1{\lambda(t)} \| u \|_{H^1}^2 \int \psi (|u|^2 +|\partial_xu|^2 +|\eta|^2 +|\partial_x\eta |^2+|h|^2+|\partial_xh|^2).
\end{aligned}
\end{equation}
Similar as in \eqref{eq:E1E2E3E4_new2_7},
\begin{equation}\label{eq:E1E2E3E4_new2_9}
\begin{aligned}
&~{}  \Big| c\int \psi'\partial_x^3 g(1-\px^2)^{-1}\partial_x (u(\eta+h)) + \int \psi'\partial_x g (1-\px^2)^{-1}\partial_x (u(\eta+h)) \Big| \\
& \qquad \lesssim \frac1{\lambda(t)} \| u \|_{H^1}\int \psi (|u|^2  + |\partial_x u |^2 + |\eta |^2  + |\partial_x \eta |^2 +|h|^2  + |\partial_x h |^2).
\end{aligned}
\end{equation}
Now we use \eqref{eq:nonlinear1-3},
\begin{equation}\label{eq:E1E2E3E4_new2_10}
\begin{aligned}
&~{}  \Big|\frac12 a\int \partial_x(\psi' \partial_xu)(1-\px^2)^{-1}(u^2)   + c\int \partial_x(\psi' \partial_x\eta)(1-\px^2)^{-1}(u(\eta+h))   \Big| \\
& \qquad \lesssim \frac{1}{\lambda(t)}  (\|u\|_{H^1} +\|\eta\|_{H^1}) \int \psi (|u|^2  + |\partial_x u |^2 +|\eta|^2  + |\partial_x \eta |^2 + |h|^2  + |\partial_x h |^2).
\end{aligned}
\end{equation}
Finally, using H\"older and \cite{KMM}, %\eqref{eq:nonlinear1-1},
\begin{equation}\label{eq:E1E2E3E4_new2_11}
\begin{aligned}
&~{}  \Big| ac_1 \int \psi' \partial_xu  (1-\partial^2_x)^{-1}  \partial_t^2 \partial_x h  + c\int \psi'   \partial_x \eta (1-\partial^2_x)^{-1}\left(-1+ a_1 \partial_x^2\right) \partial_t h\Big| \\
& \quad \lesssim \frac{1}{\lambda(t)} \int \psi ( |\partial_x u |^2  + |\partial_x \eta |^2 )\\
& \quad \quad+ \frac{1}{\lambda(t)} \int \psi ( |(1-\partial^2_x)^{-1}  \partial_t^2 \partial_xh|^2  + |\partial_t h |^2 + | (1-\partial^2_x)^{-1}\partial_t h|^2)\\
& \quad \lesssim \frac{1}{\lambda(t)}  \int \psi ( |\partial_x u |^2  + |\partial_x \eta |^2 +  |\partial_t^2 \partial_xh|^2  + |\partial_t h |^2 ).
\end{aligned}
\end{equation}
Now, let us deal with bottom's interaction. Recalling $\text{SNL}_h(t)$ given in \eqref{eq:SNLh} along with \eqref{psi_psi}, the terms on the first line satisfy
\[
\begin{aligned}
&\left\vert  \frac12 \int \psi u^2 \partial_t h 
+c_1  \int \psi  F \partial_t^2\partial_x h +   \int \psi  G (-1+a_1\partial_x^2)\partial_t h \right\vert 
\\
&~{} \leq
\|u\|_{H^1}^4 \|\partial_t h \|_{L^2} +\|F\|_{L^2} \|\partial_t^2\partial_x h  \|_{L^2} +\|G\|_{L^2} \|(-1+a_1\partial_x^2)\partial_t h \|_{L^2} 
\\
&~{} \leq
\|u\|_{H^1}^4 \|\partial_t h \|_{L^2} +\|F\|_{L^2} \|\partial_t^2\partial_x h  \|_{L^2} +\|G\|_{L^2} \|\partial_t h \|_{H^1} 
\\
&~{} \lesssim
 \|\partial_t h \|_{L^2} +\|\partial_t^2\partial_x h  \|_{L^2} + \|\partial_t h \|_{H^1} .
\end{aligned}
\]
Then, following the same ideas applied to $\text{SNL}_0$ and $\text{SNL}_1$, we obtain that 
\begin{equation}\label{eq:SNLh_b}
\begin{aligned}
|\text{SNL}_h(t)| \lesssim  & ~{}
 \|\partial_t h \|_{L^2} +\|\partial_t^2\partial_x h  \|_{L^2} + \|\partial_t h \|_{H^1} 
 \\&+\frac{1}{\lambda(t)}  \int \psi (|u|^2+ |\partial_x u |^2+|\eta|  + |\partial_x \eta |^2 +  |\partial_t^2 \partial_xh|^2  + |\partial_t h |^2 ).
%\\&
%-c_1  \int  (\psi'' F (1-\partial_x^2)^{-1}\partial_t^2\partial_x h +2\psi'  F (1-\partial_x^2)^{-1}\partial_t^2\partial_x^2 h  ) 
%\\&
%-  \int  (\psi'' G (1-\partial_x^2)^{-1}(-1+a_1\partial_x^2)\partial_t h +2\psi'  G (1-\partial_x^2)^{-1}(-1+a_1\partial_x^2)\partial_x\partial_t h ).
\end{aligned}
\end{equation}
Gathering \eqref{eq:E1E2E3E4_new2_1}, \eqref{eq:E1E2E3E4_new2_2}, \eqref{eq:E1E2E3E4_new2_3}, \eqref{eq:E1E2E3E4_new2_4}, \eqref{eq:E1E2E3E4_new2_5}, \eqref{eq:E1E2E3E4_new2_6}, \eqref{eq:E1E2E3E4_new2_7}, \eqref{eq:E1E2E3E4_new2_8}, \eqref{eq:E1E2E3E4_new2_9}, \eqref{eq:E1E2E3E4_new2_10}, \eqref{eq:E1E2E3E4_new2_11} and \eqref{eq:SNLh_b}, we obtain \eqref{eq:E1E2E3E4_new2_0}.


Thanks to \eqref{eq:E1E2E3E4_new2_0} and \eqref{eq:E1E2E3E4_new2_m1}, we conclude in \eqref{eq:energy1_new},
\begin{equation}\label{eq:energy1_2}
\begin{aligned}
&\left| \frac{d}{dt} E_\text{loc}(t)\right| 
\\
& \quad  \lesssim  \frac1{\lambda(t)}\int   \psi  (|\eta|^2 +|\partial_x \eta|^2 +|u|^2 +|\partial_x u|^2 +|h|^2 +|\partial_t h|^2 +|\partial_x h|^2 +|\partial_t^2 \partial_xh|^2)
\\&
\qquad \qquad +\|\partial_t h \|_{L^2} +\|\partial_t^2\partial_x h  \|_{L^2} + \|\partial_t h \|_{H^1} .
\end{aligned}
\end{equation}
Integrating \eqref{eq:energy1_2} on $[t, t_n]$, for $t < t_n$ as in \eqref{eq:virial2-2}, \eqref{hyp_h} and Proposition \ref{prop:virial2} yield
\[
\begin{aligned}
& \left|E_\text{loc}(t_n) - E_\text{loc}(t) \right| \\
& \quad \lesssim \int_t^{\infty}\!\!   \frac{1}{\lambda(t)}  \int \sech^2 \left(\frac{x}{\lambda(t)}\right) (u^2 + (\px u)^2 + \eta^2 + (\px \eta)^2)(t,x) \; dxdt 
\\
& \quad \quad + \int_t^{\infty}\!\!   \frac{1}{\lambda(t)}  \int \sech^2 \left(\frac{x}{\lambda(t)}\right) (h^2 + (\partial_t h)^2 +(\partial_x h)^2 +(\partial_t^2 \partial_xh)^2)(t,x) \; dxdt 
\\
&\qquad \quad +\int_{t}^{\infty} (\|\partial_t h \|_{L^2} +\|\partial_t^2\partial_x h  \|_{L^2} + \|\partial_t h \|_{H^1} ) 
 < \infty.
\end{aligned}
\]
Note that, from the Sobolev embedding (with $\norm{\eta}_{H^1} \lesssim \ve$ and $\| h\|_{H^1}\lesssim \varepsilon$), we have
\[
|E_\text{loc}(t_n)| \lesssim \int \psi(u^2 + (\px u)^2 + \eta^2 + (\px \eta)^2) (t_n) \longrightarrow 0, \quad \mbox{ as } n \to \infty,
\]
thanks to \eqref{eq:virial2-2}. Thus, by sending $t_n \to \infty$, we have
\[\begin{aligned}
\int \sech^4\left( \frac{x}{\lambda(t)} \right)& (u^2 + (\px u)^2 + \eta^2 + (\px \eta)^2 + \eta u^2) (t) \\
&\lesssim \int_t^{\infty}  \frac{1}{\lambda(t)}  ~{}
\!\!\int \sech^2 \left(\frac{x}{\lambda(t)}\right) (u^2 + (\px u)^2 + \eta^2 + (\px \eta)^2)
\\&\qquad \quad+\int_{t}^{\infty} (\|\partial_t h \|_{L^2} +\|\partial_t^2\partial_x h  \|_{L^2} + \|\partial_t h \|_{H^1} ) .
\end{aligned}\]
Once again, the Sobolev embedding (with $\norm{\eta}_{H^1} \lesssim \ve$) guarantees that
\[
\begin{aligned}
& \lim_{t \to \infty}\int_{-\lambda(t)}^{\lambda(t)} (u^2 + (\px u)^2 + \eta^2 + (\px \eta)^2) (t)\\
& \quad \lesssim  \lim_{t \to \infty}\int \sech^4\left( \frac{x}{\lambda(t)} \right) (u^2 + (\px u)^2 + \eta^2 + (\px \eta)^2) (t) = 0,
\end{aligned}
\]
which proves \eqref{eq:energy2.1}, and completes the proof of Theorem \ref{MT1}, part \eqref{Conclusion_0}.
\end{proof}


