\section{Kubo and Kitaev trace pairings}
\label{KuboKitaevPairings}

In this paper, we work with \emph{proper} metric spaces $M$, meaning that bounded sets are precompact.
The distance function will be denoted by $d$.
Throughout, we will use the following notations.

\begin{notation}[Indicator functions]
\label{IndicatorFunction}
For a subset $Y\subseteq M$, we use the same letter $Y$ to denote its indicator function $Y : M \to \{0, 1\}$, taking the value $1$ on $Y$ and $0$ on the complement.
So the complement $Y^c=M\setminus Y$ corresponds to the function $Y^c = \mathbf{1} - Y$, where $\mathbf{1}$ denotes the constant function with value $1$ on all of $M$.
\end{notation}

\begin{notation}[Thickenings]
The \emph{$R$-thickening} of a subset $Y\subset M$ is the (closed) set of points lying within distance $R$ from $Y$ and will be denoted by
\[
Y_R:=\{x\in M\,:\,d(x,Y)\leq R\}.
\]
\end{notation}

We note that if $X, Y \subseteq M$, then
\begin{equation}
\label{UnionIntersectionInclusions}
(X \cup Y)_R = X_R\cup Y_R,\qquad \text{and} \qquad (X \cap Y)_R \subseteq X_R\cap Y_R.
\end{equation}






\subsection{Coarsely transverse partitions and half spaces}

Let $M$ be a proper metric space.

\begin{definition}[Big families]
A \emph{big family} $\mathcal{Y}$ in $M$ is a collection of subsets of $M$ that is closed with respect to taking subsets, finite unions, and $R$-thickenings for any $R>0$.
\end{definition}

\begin{example}
The smallest non-empty big family in $M$ is the collection $\cB$ of all bounded subsets of $M$.
\end{example}

\begin{example}
Any subset $Y\subseteq M$ generates a big family comprising those sets that are contained in some thickening of $Y$. This big family is denoted
\begin{equation*}
\{Y\} := \{Z \subseteq Y_R \mid R>0\}.
\end{equation*}
For example, $\{M\}$ is the collection of all subsets of $M$, and this is the largest big family in $M$.
\end{example}

Given two big families $\cX, \cY$ in $M$, the elementwise intersection and union
\begin{align*}
\mathcal{X} \Cap \mathcal{Y} &:= \big\{ X \cap Y \mid X \in \mathcal{X}, Y \in \mathcal{Y}\big\},
\\
\mathcal{X} \Cup \mathcal{Y} &:= \big\{ X \cup Y \mid X \in \mathcal{X}, Y \in \mathcal{Y}\big\},
\end{align*}
is again a big family, as follows directly from \eqref{UnionIntersectionInclusions}.
In particular,  we will often consider the elementwise intersection
\[
\partial X:=\{X\}\Cap\{X^c\},
\]
for subsets $X \subseteq M$, which we call the \emph{coarse boundary} of $X$.
This is not to be confused with the topological boundary of $X$ inside $M$, which will not play a role in this paper.


\begin{definition}[Coarse transversality]
A collection $Y_1,\ldots,Y_n\subseteq M$ of subsets of $M$ is \emph{coarsely transverse} if 
\[
\{Y_1\}\Cap\dots\Cap\{Y_n\}\quad \text{is the big family $\cB$ of bounded subsets.}
\]
Equivalently, the set $(Y_1)_R\cap\dots\cap (Y_n)_R$ is bounded for each $R \geq 0$.
\end{definition}

\begin{definition}[Coarsely transverse partitions] 
\label{dfn:partition}
A \emph{coarsely transverse $n$-partition} of $M$ is an ordered collection $A_0, \dots, A_n \subseteq M$ of pairwise disjoint Borel subsets whose union is $M$ and which are coarsely transverse.
\end{definition}


Coarsely transverse 1-partitions of a manifold were studied by J.\ Roe in \cite{Roe-partition} in the context of his partition index theorem.
Some 2-partitions are illustrated in Fig.\ \ref{fig:coarse.transverse} below. 


\begin{definition}[Coarsely transverse half spaces]
\label{dfn:transverse.half.spaces}
A \emph{coarsely transverse collection of half spaces} is an ordered collection of Borel subsets $X_1,\ldots,X_n \subseteq M$ such that the subsets $X_1, X_1^c, \ldots, X_n, X_n^c$ are coarsely transverse. 
Equivalently, 
\[
\partial X_1 \Cap \cdots \Cap \partial X_n \quad \text{is the big family $\cB$ of bounded sets.}
\]
More generally, a coarsely transverse collection of \emph{switch functions} is a collection of Borel functions $\chi_1, \dots, \chi_n :M\to\C$ such that the sets $\supp(\chi_i)$, $\supp(\mathbf{1} - \chi_i)$, $i=1, \dots, n$, are coarsely transverse.
\end{definition}

\begin{comment}
	Here it does \emph{not} suffice to assume that $\supp(\chi_1), \dots, \supp(\chi_n)$ is a coarsely transverse collection of half spaces.
\end{comment}


