\subsection{Finite propagation operators}\label{SecFinitePropOperators}

Let $\mathcal{H}$ be an \emph{$M$-module}, by which we mean a separable Hilbert space with a $*$-representation of the algebra $C_0(M)$ of continuous functions vanishing at infinity on $M$.
For example, if $M$ is a smooth Riemannian manifold, then $\cH=L^2(M)$ is a $C_0(M)$-module, while if $M$ is a discrete metric space, one usually takes $\cH = \ell^2(M)$.


By the spectral theorem, the $C_0(M)$ action on $\cH$ extends canonically to a $*$-representation of the algebra of bounded Borel functions on $M$ in the algebra $\mathscr{L}(\mathcal{H})$ of bounded operators on $\mathcal{H}$.
For any bounded Borel function $f$ on $M$, we denote the operator on $\mathcal{H}$ that multiplies with $f$ (using the module action) by the same letter.
Moreover, for any Borel subset $X \subseteq M$, we continue to denote its indicator function and, consequently, the corresponding multiplication operator by the same letter.


\begin{definition}[Finite propagation, locally trace-class operators]
\label{DefLTCFP}
Let $\cH$ be an $M$-module and let $T \in \sL(\cH)$.
\begin{enumerate}[(i)]
\item 
$T$ has \emph{propagation bound} $R$, if whenever the supports of two bounded Borel functions $f$ and $g$ have at least $R$, then $f T g =0$;
\item 
$T$ has \emph{finite propagation}, if it admits some finite propagation bound;
\item 
$T$ is \emph{locally trace-class}, if $fT$ and $Tf$ are trace-class operators for any compactly supported Borel function $f$.
\end{enumerate}

 We denote by $\sB(M) \subseteq \sL(\cH)$ the subalgebra of locally trace-class, finite propagation operators. 

\begin{enumerate}
	\item[(iv)]
	If $Y \subseteq M$, we say that an operator $T\in\sL(\mathcal{H})$ is \emph{supported on} $Y$ if $fT = Tf = 0$ whenever $f$ is a bounded Borel function with $\supp(f) \subseteq Y^c$;
	\item[(v)]
	If $\cY$ is a big family in $M$, we say that $T$ is \emph{supported on} $\cY$ if it is supported on some member of $\cY$.
\end{enumerate}

We denote by $\sB(\mathcal{Y}) \subseteq \sB(M) \subset \sL(\cH)$ the subalgebra comprising those locally trace-class and finite propagation operators which are supported on $\mathcal{Y}$. It will follow from Lemmas \ref{LemmaTSsupported} and \ref{LemmaLocallyTraceclass} below that $\sB(\cY)$ are ideals in $\sB(M)$, so we refer to them as \emph{localization ideals}.
\end{definition}

\begin{remark}\label{RemAmpleModule}
We may write $\sB_{\cH}(\cY)$ to emphasize the dependence of the choice of $M$-module, but will usually suppress $\cH$ in notation. 
This simplified notation has the justification that if $\cH$ and $\cH'$ are \emph{ample}---meaning that no non-zero $f \in C_0(M)$ acts as a compact operator---then $\sB_{\cH}(\cY) \cong \sB_{\cH'}(\cY)$ for any big family $\cY$ in $M$, where the isomorphism is provided by conjugation by a finite propagation unitary $\cH \to \cH'$.
In particular, the algebras $\sB_{\cH}(\cY)$ have canonically isomorphic $K$-theory.
Similar remarks hold for the norm closures $C^*_{\cH}(\cY)$ of $\sB_{\cH}(\cY)$, which are called the \emph{Roe algebras} associated to the big families $\cY$. 
For a reference on these facts, see \cite[\S6.3]{HigsonRoe}.
\end{remark}


\begin{lemma}
\label{LemmaTSsupported}
If $S, T \in \sL(\cH)$ are such that $T$ has finite propagation and $S$ is supported on $Y \subseteq M$, then $TS$ and $ST$ are supported on $\{Y\}$.
\end{lemma}

\begin{proof}
Let $R$ be a propagation bound for $T$.
Let $f$ be a bounded Borel function with $\supp(f) \subseteq (Y_R)^c \subseteq Y^c$.
Then clearly $fTS = STf = 0$.
For the other products, observe that $T = TY = YT$ because $T(1-Y) = (1-Y)T = 0$ from the fact that $T$ is supported on $Y$.
Hence $TSf = TYSf = 0$ and similarly $fST = fSYT = 0$ because $d(\supp(f), Y) \geq R$, the propagation bound of $S$.
\end{proof}

\begin{lemma}
\label{LemmaLocallyTraceclass}
If $S, T \in \sL(\cH)$ are such that $T$ has finite propagation and $S$ is locally trace-class, then also $ST$ and $TS$ are locally trace-class.
\end{lemma}

\begin{proof}
We now show that if $T, S \in \sL(\cH)$ are such that $T$ is locally trace-class and $S$ has finite propagation, then $TS$ and $ST$ are also locally trace-class.
To this end, let $f$ be a bounded Borel function supported in a bounded set $B$. Then clearly $fTS$ and $STf$ are trace-class.
By Lemma~\ref{LemmaTSsupported}, $Sf$ and $fS$ are supported on $B_R$ for some $R\geq 0$ (one can choose $R$ to be a propagation bound for $S$).
Hence $TSf = TB_RSf$ and $fST = fSB_RT$ are trace-class, as $TB_R$ and $B_RT$ are trace-class.
\end{proof}


\begin{lemma}
\label{LemmaTraceClass}
The algebra $\sB(\cB)$ consists of trace-class operators.	
\end{lemma}

\begin{proof}
Suppose that $T$ is a locally trace-class operator that is supported on a compact subset $B \subseteq M$. 
Then we may choose a compactly supported Borel function $f$ with $f_{|B} \equiv 1$.
Then $T = Tf + T(1-f)$ and because $\supp(1-f) \subseteq B^c$ while $T$ is supported on $B$, we get that $T(1-f) =0$.
So $T = Tf$, which is trace-class.
\end{proof}


\begin{lemma}
\label{LemmaLocalizationIdealProperty}
Let $Y_1, \dots, Y_n \subseteq M$ be coarsely transverse and let $T_1, \dots, T_n$ be finite propagation operators, at least one of which is locally trace-class.
Then the product 
\[
Y_1T_1 \cdots Y_n T_n \quad \text{is trace-class.}
\]
\end{lemma}


\begin{proof}
Since one of the operators is locally trace-class and each of the $T_i$ as well as the multiplication operators $Y_i$ has finite propagation, the product is locally trace-class by Lemma~\ref{LemmaLocallyTraceclass}.

By Lemma~\ref{LemmaTSsupported}, for each $i=1, \dots, n$, the operators $Y_i T_i$ are supported on $\{Y_i\}$.
Fixing $i$, using the same lemma iteratively shows that the whole product is supported on $\{Y_i\}$.
Altogether this implies that $Y_1T_1 \cdots Y_n T_n$ is supported on $\{Y_1\} \Cap \cdots \Cap \{Y_n\}$.
By coarse transversality, this is the big family $\cB$ of bounded subsets, so the product is trace-class by Lemma~\ref{LemmaTraceClass}.
\end{proof}

We will frequently use the unitization $\sB(M)^+$ of the algebra of finite propagation locally trace-class operators, which may be realized as the subalgebra of $\mathscr{L}(\cH)$ consisting of those operators that differ from $\sB(M)$ by a multiple of the identity operator.

For $k\geq 1$, the matrix algebras $M_k(\sB(M)^+)$ are regarded as acting on the $M$-module $\mathcal{H}^{\oplus k}$,
\[
M_k(\sB(\cH)^+) \subseteq \sL(\cH^{\oplus k}).
\]
Elements $T\in M_k(\sB(M)^+)$ have the form $T=T_0 + S$ where $S\in M_k(\sB(M))$ while $T_0$ is scalar in the sense that its entries are scalar multiples of the identity operator on $\mathcal{H}$.
We write $\GL_k(\sB(M))^+$ for the group of invertible elements of $M_k(\sB(M)^+)$ whose scalar part is the identity operator on $\mathcal{H}^{\oplus k}$.

%\[
%M_k(\sB(M)^+)=M_k(\sB(M))+M_k(\C \cdot 1_\mathcal{H}).
%\]

\subsection{Kitaev and Kubo pairings}\label{SecKitaevKuboPairings}

Let $M$ be a proper metric space and let $\sB(M)$ be the corresponding algebra of locally trace-class, finite propagation operators, defined on some $M$-module $\cH$.



\begin{definition}[Kitaev and Kubo pairings]
\label{DefinitionIdempotentPairing}
Let $A_0, \dots, A_n$ be a coarsely transverse partition of $M$. We define its \emph{Kitaev pairings} by the formulas
\begin{center}
\begin{tcolorbox}[width=0.87\textwidth,colback=white, colframe=black, sharp corners, boxrule=0.55pt]
\vspace{-0.3cm}
\begin{align*}
	\big[ P; A_0, \dots, A_n\big] &:= \Tr\Bigg(\sum_{\sigma \in S_{n+1}} \sgn(\sigma) \cdot A_{\sigma_0} P A_{\sigma_1} P\cdots A_{\sigma_n} P\Bigg)
	\\
	\big[ U; A_0, \dots, A_n\big] &:= \Tr\Bigg(\sum_{\sigma \in S_{n+1}} \sgn(\sigma) \cdot A_{\sigma_0} U A_{\sigma_1} U^{-1}\cdots A_{\sigma_{n-1}} U A_{\sigma_n} U^{-1}\Bigg)
\end{align*}
\end{tcolorbox}
\end{center}
where $P = P^2 \in M_k(\sB(M)^+)$ is an idempotent, $U \in \GL_k(\sB(M))^+$ is invertible, and $S_{n+1}$ denotes the group of permutations of $\{0,1,\ldots,n\}$.
In the second formula, we assume that $n$ is odd.
For a coarsely transverse collection of half spaces $X_1, \dots, X_n$, we set $X_0 := \mathbf{1}$ and define its \emph{Kubo pairings} by
\begin{center}
\begin{tcolorbox}[width=0.9\textwidth,colback=white, colframe=black, sharp corners, boxrule=0.5pt]
\vspace{-0.3cm}
\begin{align*}
	\big[ P; X_1, \dots, X_n\big] &:= \Tr\Bigg(\sum_{\sigma \in S_{n+1}} \sgn(\sigma)\cdot X_{\sigma_0} P X_{\sigma_1} P \cdots X_{\sigma_n} P\Bigg)
	\\
	\big[ U; X_1, \dots, X_n\big] &:= \Tr\Bigg(\sum_{\sigma \in S_{n+1}} \sgn(\sigma)\cdot X_{\sigma_0}U X_{\sigma_1} U^{-1} \cdots X_{\sigma_{n-1}} U X_{\sigma_n} U^{-1}\Bigg),
\end{align*}
\end{tcolorbox}
\end{center}
where in the last formula, we again assume that $n$ is odd.
\end{definition}
The well-definedness of the traces in Definitions \ref{DefinitionIdempotentPairing} is verified {by a hands-on approach in Section \ref{sec:WellDefinedPairings}. 
Alternatively, it also follows from a more abstract analysis of the pairings in Section \ref{SectionCyclicHomology}.



\begin{remark}\label{RemSwitchFunctions}
More generally, one may use a collection $\chi_1, \dots, \chi_n$ of coarsely transverse switch functions in the definition of the Kubo pairing.
However, we will see below (Lemma \ref{LemSwitchToHalfSpace}) that one may always replace the $\chi_i$ with the indicator functions of their support (thus obtaining a coarsely transverse collection of half spaces) without changing the corresponding Kubo pairing. 
Because of this, we will mostly work with half spaces $X_1,\ldots, X_n$ to simplify the presentation.
\end{remark}

\begin{remark}
\label{remarkn=0}
An elaboration is needed for the Kitaev/Kubo pairing when $n=0$.
 Only compact spaces $M$ admit $0$-partitions, in which case $A_0=M=X_0$, and $\sB(M)$ is the algebra $\sL_1$ of trace-class operators on $\mathcal{H}$. 
 By convention, $\Tr$ refers to the trivial extension of the usual trace to $\sB(M)^+=\sL_1^+$ given by $\smash{\widetilde{\Tr}(T + \lambda)} = \Tr(T)$, and likewise to $M_k(\sB(M)^+)$. 
 Thus, the Kitaev pairing of $P=P^2\in M_k(\sB(M)^+)$ with $A_0=M$, or the Kubo pairing with the empty collection of half spaces, is equal to $\smash{\widetilde{\Tr}(P)} = \Tr(Q)$, where $Q\in M_k(\sB(M))$ is the non-scalar part of $P$.
\end{remark}


\begin{remark}
The $n=1$ case with $M=\Z$, $X_1=\N$, and $U=(U_{jk})_{j,k\in\Z}$ a finite propagation unitary on the $M$-module $\cH = \ell^2(\Z;\C )$, was considered by Kitaev in \cite[\S C.1]{Kitaev}. 
Here we have
\begin{equation}\label{eqn:Kitaev_1D_formula}
[U;X_1]=\Tr(UX_1U^*-X_1) 
%&= \Tr(X_1^cUX_1U^*-X_1UX_1^cU^*)\\
%&=\sum_{j\geq 0, k<0}\big(U_{kj}U^*_{jk}-U_{jk}U^*_{kj}\big)
%\\
=\sum_{j\geq 0, k<0}\big(|U_{kj}|^2-|U_{jk}|^2\big),
\end{equation}
which was called the \emph{flow} of $U$. (Our sign convention differs from that in \cite{Kitaev}.) 
Such unitaries are sometimes called \emph{quantum walks}, and \eqref{eqn:Kitaev_1D_formula} was used in \cite{GNVW} as an index for studying quantum walks. When endowed with a suitable topology, the homotopy groups of the group of finite-propagation unitary operators on $\ell^2(\mathbb{Z};\mathbb{C})$ was studied in \cite{KKT}.
\end{remark}

\begin{remark}
The $n=2$ and $M=\Z^2$ case of the Kitaev pairing, Definition~\ref{DefinitionIdempotentPairing}, was considered by Kitaev in \cite[\S C.3]{Kitaev}, as an alternative formula for (half of) the Hall conductance of a projection $P$, (up to a $2\pi i$ factor, Planck's constant and the electron charge).
A more commonly used formula is the Kubo pairing, which has an equivalent expression in terms of commutators with switch functions (see \eqref{KuboPairingCommutatorProduct}),
which is
\begin{equation*}%\label{KuboFormula2D}
\Tr\Big(P \big[[P,\chi_1], [P,\chi_2]\big]\Big),
\end{equation*}
see, e.g., \cite{DEF,EGS}. Typically, one works with $M=\R^2$ and uses switch functions of the form $\chi_i(x_1,x_2)=\Lambda(x_i), i=1,2$, where $\Lambda:\R\to\R$ satisfies
\[
\Lambda(t)=\begin{cases} 1, & t>b,\\
0, &t<a,
\end{cases}
\]
for some interval $[a,b]$. Our more general notion of switch functions emphasizes that coarse transversality of their supports is the key underlying property.


In physics, a typical source of $P$ are the spectral projections for some spectrally gapped local Hamiltonian operator $H$. Such $P$ are usually locally trace-class, but do not have strict finite propagation. 
With sufficiently rapid decay properties, the Kubo formula continues to be well-defined for such $P$, see \cite{LudewigThiangPoly}. 
An example on $M=\R^2$ is explicitly computed in \cite{ThiangFock}.
\end{remark}



The main result of this paper is the following general quantization theorem for the higher Kubo/Kitaev trace pairings, which will be proved in Sections~\ref{SectionIntegralityKubo} and \ref{SectionIntegralityKitaev}.

\begin{theorem}
\label{MainQuantizationThm}
Let $A_0, \dots, A_n$ be a coarsely transverse partition of $M$, and $X_1, \ldots, X_n$ be a  coarsely transverse collection of switch functions on $M$.


\noindent
If $n=2m$ is even, the pairings with an idempotent $P\in M_k(\sB(M)^+)$ satisfy
\begin{align*}
 \big[ P; A_0, \dots, A_{n}\big] &\in \frac{m!}{(2 \pi i)^{m} (2m)!} \cdot \Z,\\
\big[ P; X_1, \dots, X_{n}\big] &\in \frac{m!}{(2 \pi i)^{m} }  \cdot \Z.
\end{align*}
If $n=2m+1$ is odd, the pairings with invertibles $U\in \GL_k(\sB(M))^+$ satisfy
\begin{align*}
  \big[ U; A_0, \dots, A_{n}\big] & \in \frac{1}{(2 \pi i)^{m} m! } \cdot \Z,	\\
  \big[ U; X_1, \dots, X_{n}\big] & \in \frac{(2m +1)!}{(2 \pi i)^{m}m!} \cdot \Z.
\end{align*}
\end{theorem}

We will see below that the pairings with $P$ vanish when $n$ is odd.
For $M= \R^d$, the values of the pairings for $n=d$ are not contained in any smaller subset than the ones specified above, so this result is optimal for general $M$, see Thm.~\ref{ThmNontrivialPairing}.


The following result shows that only the even $n$ case can produce non-trivial pairings with idempotents.

\begin{proposition}
\label{ThmVanishingThmRemainingCases}
Let $A_0, \dots, A_n$ be a coarsely transverse partition of $M$ and let $X_1, \dots, X_n$ be a coarsely transverse collection of half spaces. 
If $n$ is odd, then for any idempotent $P \in M_k(\sB(M)^+)$, we have
\[
[P; A_0, \dots, A_n] = 0 \qquad \text{and} \qquad [P; X_1, \dots, X_n] = 0.
\] 
\end{proposition}

\begin{proof}
By cyclicity of the trace, we have
\begin{align*}
[P; A_0, \dots, A_n]
&= \sum_{\sigma \in S_{n+1}} \sgn(\sigma) \cdot \Tr\big(A_{\sigma_0} P \cdots A_{\sigma_{n-1}}PA_{\sigma_n}P\big)	
\\
&= \sum_{\sigma \in S_{n+1}} \sgn(\sigma) \cdot \Tr\big(A_{\sigma_n}PA_{\sigma_0} P \cdots A_{\sigma_{n-1}}P\big).
\end{align*}
Since $n$ is odd, the cyclic permutation of $n+1$ elements has negative sign. 
Hence substituting $\sigma'_0 = \sigma_n$ and $\sigma_{i+1}' = \sigma_i$, (for $i= 0, \dots, n-1$), we get $\sgn(\sigma') = -\sgn(\sigma)$ and therefore the right hand side above equals $-[P; A_0, \dots, A_n]$. 
Thus $[P; A_0, \dots, A_n]=0$.

Using cyclicity of the trace and the fact that $P$ is an idempotent, we may also take the sum over $PX_{\sigma_0}P \cdots P X_{\sigma_n} P$ in the definition of the Kubo pairing (Definition~\ref{DefinitionIdempotentPairing}), which is therefore equal to the trace of the following operator,
\begin{align*}
\sum_{\sigma\in S_{n+1}}{\rm sgn}(\sigma)\cdot PX_{\sigma_0} P \cdots PX_{\sigma_n}P 
&=  \sum_{i=0}^n \sum_{\substack{\sigma\in S_{n+1} \nonumber\\ \sigma_i=0}}{\rm sgn}(\sigma)\cdot PX_{\sigma_0} P \cdots \underbrace{PX_{\sigma_i} P}_{=P} \cdots PX_{\sigma_n}P
 \nonumber \\
 &= \sum_{i=0}^n\sum_{\sigma^\prime\in S_{n}}(-1)^{i}\cdot{\rm sgn}(\sigma^\prime)\cdot PX_{\sigma^\prime_1} P \cdots PX_{\sigma^\prime_{n}} P. 
 \end{align*}
If $n$ is odd, then $\sum_{i=0}^n (-1)^i = 0$, so the above operator vanishes. Thus the Kubo pairing vanishes in this case.
\end{proof}


\subsection{Well-definedness of the pairings}\label{sec:WellDefinedPairings}

In this section, we show that the Kitaev and Kubo pairings from Definition~\ref{DefinitionIdempotentPairing} are well-defined in the sense that the operators that the trace is taken of is in fact trace-class.
We also derive several alternative formulas for these pairings.


\paragraph{Kitaev pairing with idempotents.}

It follows immediately from Lemma~\ref{LemmaLocalizationIdealProperty} above that if $P$ is an idempotent that is locally trace-class (i.e., contained in $M_k(\sB(M)) \subset M_k(\sB(M)^+)$), then each of the operators $A_{\sigma_0} P \cdots A_{\sigma_n} P$ is trace-class, so the Kitaev pairing is well-defined and we have
\[
[P; A_0, \dots, A_n] = \sum_{\sigma \in S_{n+1}}\sgn(\sigma) \cdot \Tr \big(A_{\sigma_0} P \cdots A_{\sigma_n} P\big),
\]
in other words, the sum over all permutations may be pulled out of the trace.
However, the pairings will be trivial for a large class of such $P$, hence it is especially important to check well-definedness also for projections $P$ in $M_k(\sB(M)^+)$, see Theorem \ref{ThmNontrivialPairing} and Remark \ref{RemarkTranslationInvariantVanish}.
In this case, we may write $P=P_0+Q$, where $P_0\in M_k(\C)$ is a scalar matrix (whose entries are multiples of $1_\mathcal{H}$) while the remainder $Q$ lies in $M_k(\sB(M))$.
As $P_0$ commutes with every $A_i$, we have $A_{\sigma_i}P_0A_{\sigma_{i+1}}=P_0A_{\sigma_i}A_{\sigma_{i+1}}$. Therefore, any term with a factor $A_{\sigma_i}P_0A_{\sigma_{i+1}}$ will vanish after taking the signed sum over all permutations.
Thus, 
\begin{align*}
&\sum_{\sigma \in S_{n+1}}^{\,} \sgn(\sigma)\cdot A_{\sigma_0} P \cdots A_{\sigma_n} P 
=\sum_{\sigma \in S_{n+1}}^{\,} \sgn(\sigma)\cdot A_{\sigma_0} Q \cdots A_{\sigma_{n-1}} Q A_{\sigma_n} (Q+P_0)\nonumber\\
&\qquad =\sum_{\sigma \in S_{n+1}}^{\,} \sgn(\sigma)\cdot A_{\sigma_0} Q \cdots A_{\sigma_n}Q 
 + \sum_{\sigma \in S_{n+1}}^{\,} \sgn(\sigma) \cdot A_{\sigma_0} Q \cdots A_{\sigma_{n-1}} Q A_{\sigma_n}P_0.
\end{align*}
As $Q\in M_k(\sB(M))$ has finite propagation and is locally trace-class, Lemma \ref{LemmaLocalizationIdealProperty} applies, saying that each individual summand is trace-class.
Because $P_0$ commutes with $A_{\sigma_n}$, the second term actually vanishes after applying the trace and using its cyclicity.
Therefore, the Kitaev pairing reduces to
\begin{equation}
\label{AlternativeFormulaKitaevPairing}
\big[ P; A_0, \dots, A_n\big] =\sum_{\sigma \in S_{n+1}} \sgn(\sigma) \cdot \Tr\big( A_{\sigma_0} Q \cdots A_{\sigma_n} Q\big).
\end{equation}
Note that the $n=0$ case of \eqref{AlternativeFormulaKitaevPairing} is precisely the convention for the $n=0$ Kitaev/Kubo pairing mentioned in Remark \ref{remarkn=0}.
%
