\begin{equation*}
[U; A_0, \dots, A_n] = 	\sum_{\sigma \in S_{n+1}}^{\,} \sgn(\sigma) \cdot \Tr\big( A_{\sigma_0} (U - 1) A_{\sigma_1} (U^{-1} - 1)\cdots A_{\sigma_n} (U^{-1} - 1)\big)
