\paragraph{Kubo pairing with idempotents.}

For $n=0$, see Remark \ref{remarkn=0}; we now assume $n\geq 1$. 
Splitting $P = P_0 + Q$ with $P_0 \in M_k(\C)$ and $Q$ locally trace-class and finite propagation, we may argue as in the partition case to obtain the formula
\begin{equation}
\label{KuboPairingCommutatorProduct2}
  	\big[ P; X_1, \dots, X_n\big]
  	= \Tr\left(\sum_{\sigma \in S_{n}} \sgn(\sigma)\cdot X_{\sigma_0} Q X_{\sigma_1} Q \cdots X_{\sigma_n} Q\right).
\end{equation}
However, it is not apparent from this formula that the operator in the bracket is trace-class as Lemma~\ref{LemmaLocalizationIdealProperty} only yields that it is supported on the ``corner space'' $\{X_1\} \Cap \cdots \Cap \{X_n\}$ which is typically not bounded.
We will therefore show that the Kubo pairing may be rewritten as
\begin{equation}
\label{KuboPairingCommutatorProduct}
  	\big[ P; X_1, \dots, X_n\big]
  	= \sum_{\sigma \in S_{n}} \sgn(\sigma)\cdot \Tr\big(P[P,X_{\sigma_1}] \cdots [P,X_{\sigma_n}]\big).
\end{equation}
Then using that $X_{\sigma_i}$ commutes with $P_0$, we may replace each 
$[P,X_{\sigma_i}]$ in \eqref{KuboPairingCommutatorProduct} by $[Q,X_{\sigma_i}]$ and Lemma~\ref{LemmaLocallyTraceclass} implies that the product is locally trace-class.
Moreover, for each $i$, the commutator
\[
[Q,X_i]=(X_i+X_i^c)QX_i-X_iQ(X_i+X_i^c)=X_i^cQX_i-X_iQX_i^c
\]
is supported on $\{X_i\} \Cap \{X_i^c\} = \partial X_i$ by Lemma~\ref{LemmaTSsupported}.
The product over $i$ of these commutators is therefore supported on $\partial X_1 \Cap \cdots \Cap \partial X_n$, and is trace-class by Lemma~\ref{LemmaTraceClass} and the coarse transversality assumption.

The derivation of \eqref{KuboPairingCommutatorProduct} is a rather standard calculation, see \cite[Lemma~1.8]{MoscoviciWu2}: Recalling that $X_0=\mathbf{1}$, we first rewrite
\begin{align*}
&\sum_{\sigma\in S_{n+1}}{\rm sgn}(\sigma)\cdot X_{\sigma_0} P \cdots PX_{\sigma_n}P \\
&= \sum_{\substack{\sigma\in S_{n+1} \\ \sigma_0=0}}\mathrm{sgn}(\sigma)\cdot PX_{\sigma_1}P\cdots PX_{\sigma_n}P + \sum_{i=1}^n \sum_{\substack{\sigma\in S_{n+1} \nonumber\\ \sigma_i=0}}{\rm sgn}(\sigma)\cdot X_{\sigma_0} P \cdots \underbrace{PX_{\sigma_i} P}_{=P} \cdots PX_{\sigma_n}P\\
&=\sum_{\sigma^\prime\in S_{n} }\mathrm{sgn}(\sigma^\prime)\cdot PX_{\sigma^\prime_1}P\cdots PX_{\sigma^\prime_n}P + \sum_{i=1}^n \sum_{\sigma^\prime\in S_{n}}(-1)^i\cdot{\rm sgn}(\sigma^\prime)\cdot X_{\sigma^\prime_1} P \cdots PX_{\sigma^\prime_n}P,
\end{align*}
where in the last equality, for each $\sigma \in S_{n+1}$, (viewed as the group of permutations of the set $\{0, \dots, n\})$,  $\sigma'$ is the permutation of $\{1, \dots, n\}$ given by
\[
\sigma' = 
\begin{pmatrix}
1 & \cdots &i & i +1  & \cdots & n
\\
\sigma_0 & \cdots & \sigma_{i-1} & \sigma_{i+1} &\cdots & \sigma_n
\end{pmatrix},
\]
which has sign $\sgn(\sigma') = (-1)^i \cdot  \sgn(\sigma)$. 
As $\sum_{i=1}^n (-1)^i$ equals $0$ when $n$ is even and $-1$ when $n$ is odd, we have
\[
\sum_{\sigma\in S_{n+1}}{\rm sgn}(\sigma)\cdot X_{\sigma_0} P \cdots PX_{\sigma_n}P=
\sum_{\sigma\in S_n}\mathrm{sgn}(\sigma)\cdot\begin{cases}
PX_{\sigma_1} P\cdots PX_{\sigma_n} P, & n\;\mathrm{even},\\
 [P,X_{\sigma_1}] PX_{\sigma_2}P\cdots PX_{\sigma_n} P, & n\;\mathrm{odd}.
\end{cases}
\]
Next, we iteratively substitute the identity
\[
PX_iPX_jP  = [P,X_i][P,X_j]P + PX_iX_jP,
\]
\begin{comment}
	\begin{align*}
	[P,X_i][P,X_j]P 
	&= (PX_i - X_i P)(PX_j - X_j P)P 
	\\
	&= PX_i PX_j P - X_i \underbrace{P(PX_j - X_j P)P}_{=0} - PX_i X_j P
	\\
	&= PX_i PX_j P  - PX_i X_j P
	\end{align*}
\end{comment}
noting that term $PX_iX_jP$ may be omitted as it does not contribute to a sum which is anti-symmetric in $i,j$. In other words, 
\begin{equation*}%\label{KuboBeforeTrace}
\sum_{\sigma\in S_{n+1}}{\rm sgn}(\sigma)\cdot X_{\sigma_0} P \cdots PX_{\sigma_n}P
=\sum_{\sigma\in S_n}\mathrm{sgn}(\sigma)\cdot [P,X_{\sigma_1}]\cdots [P,X_{\sigma_n}] P, 
\end{equation*}
whether $n$ is even or odd, which implies \eqref{KuboPairingCommutatorProduct} after taking the trace.









