The support condition ensures that for any given big family $\cY$ in $M$, coarse cochains on $\cY$ are integrable against coarse chains supported on $\cY$, providing a bilinear pairing
\begin{equation}
\label{CoarsePairing}
CX^n(\cY) \times CX_n(\cY) \longrightarrow \C, \qquad \langle\theta, \mu\rangle = \int \theta d \mu.
\end{equation}
By the transformation formula, we have
\begin{equation*}
%\label{CompatibilityDifferential}
  \langle \delta \theta, \mu\rangle = \langle \theta, \partial \mu\rangle, 
\end{equation*}
hence this pairing descends to a pairing between coarse homology and coarse cohomology. 



 \begin{lemma}
 \label{DualityLemma}
 If $M$ is discrete, then the pairing \eqref{CoarsePairing} induces an isomorphism
 \[
 CX^n(M) \cong \Hom\big(CX_n(M), \C).
 \]
 \end{lemma}

Since application of the exact functor $\Hom(-, \C)$ commutes with taking (co)homology, we obtain
\begin{equation*}%\label{CoarseCohomologyAsDual}
HX^n(M) \cong \Hom\big(HX_n(M), \C\big).
\end{equation*}
In other words, the pairing \eqref{CoarsePairing} is perfect.
Since any metric space admits a discretization and coarse (co)homology is coarsely inva\-riant, this also holds for non-discrete $M$.


\begin{proof}
If $M$ is discrete, $CX^n(M)$ consists of all complex-valued functions $M^{n+1} \to \C$ whose support is finite when intersected with any $\Delta_r$, while $CX_n(M)$ may be identified (via Dirac delta functions) with the space of all functions $M^{n+1}$ whose support is contained in some $\Delta_r$.
In other words, we have
\[
CX^n(M) = \lim_{r \to \infty} \bigoplus_{x \in \Delta_r} \C, \qquad CX_n(M) = \colim_{r \to \infty} \prod_{x \in \Delta_r} \C.
\]
with the pairing \eqref{CoarsePairing} being the obvious one.
Therefore
\begin{align*}
\Hom\big(CX^n(M), \C\big) 
&= \Hom\left(\lim_{r \to \infty} \bigoplus_{x \in \Delta_r} \C, \C \right) 
\\
&= \colim_{r \to \infty} \Hom\left(\bigoplus_{x \in \Delta_r} \C, \C \right)
= \colim_{r \to \infty} \prod_{x \in \Delta_r} 
\C
= CX_n(M).
\end{align*}
Here we used that the Hom functor preserves limits and that the dual space of the \emph{direct sum} of vector spaces is the \emph{direct product} of the dual spaces of these vector spaces.
\end{proof}






It will be important below that  coarse (co)homology can also be computed using the anti-symmetrization of relevant (co)chain complexes.
Explicitly, for a big family $\cY$ in $M$, we denote by $CX^\bullet_\alpha(\cY) \subset CX^\bullet(\cY)$ the subcomplex consisting of \emph{anti-symmetric} coarse cochains, i.e., those cochains $\theta \in CX^\bullet(\cY)$ satisfying
\[
\theta(x_{\sigma_0}, \dots, x_{\sigma_n}) = \sgn(\sigma) \cdot \theta(x_0, \dots, x_n)
\]
for any permutation $\sigma$.
Particular examples of anti-symmetric $n$-cochains are the functions
\[
f_0 \wedge \cdots \wedge f_n = \sum_{\sigma \in S_{n+1}} \sgn(\sigma) \cdot f_{\sigma_0} \otimes \cdots \otimes f_{\sigma_n}
\]
for bounded Borel functions $f_0, \dots, f_n$ on $M$ (of course, to give an element of $CX_\alpha^n(\cY)$, the wedge product also has to satisfy the relevant support condition).
On these particular cochains, the Alexander-Spanier differential takes the particularly simple form
\begin{equation}
\label{SimpleASDifferential}
\delta(f_0 \wedge \cdots \wedge f_n)  = \mathbf{1} \wedge f_0 \wedge \cdots \wedge f_n.
\end{equation}

By \cite[Prop.~3.26]{Roe-cohom}, the inclusion \begin{equation}
\label{InclusionAnti}
 	CX^\bullet_\alpha(\cY) \to CX^\bullet(\cY)
\end{equation}
 is a quasi-isomorphism, and so the anti-symmetric complex also computes the coarse cohomology groups.
%
\begin{comment}
For $\cY= \{M\}$, this follows directly from Roe's result.
More generally, by Roe, the inclusion $CX^\bullet_\alpha(Y) \hookrightarrow CX^\bullet(Y)$ is a quasi-isomorphism for each $Y \in \cY$. 
For an arbitrary big family, one may obtain the result by using the Milnor sequence for both the anti-symmetric and the usual complex, and use the five-lemma.
\end{comment}
%


Dually, the chain complex $CX^\alpha_\bullet(\cY)$ is the quotient of $CX_\bullet(\cY)$ where two measures $\mu_1$, $\mu_2$ are identified if they arise from each other by a signed permutation of the variables.
Equivalently, they are identified if $\mu_1$ and $\mu_2$ have the same pairing with any anti-symmetric coarse cochain.
This last characterization shows that the pairing \eqref{CoarsePairing} descends to a pairing of the anti-symmetric complexes.
The quotient map  
\begin{equation}
\label{QuotientAntisymmetric}
 CX_\bullet(\cY) \longrightarrow CX_\bullet^\alpha(\cY)
\end{equation}
is a quasi-isomorphism dually to \eqref{InclusionAnti}.
Indeed, by coarse invariance, it suffice to verify this for discrete spaces, where the duality from Lemma~\ref{DualityLemma} identifies $CX^\bullet_\alpha(Y)$ with $\Hom(CX_\bullet^\alpha(Y), \C)$.
That \eqref{QuotientAntisymmetric} is a quasi-isomorphism follows, therefore, from the dual statement of Roe that \eqref{InclusionAnti} is a quasi-isomorphism.

We will use the fact that the coarse (co)homology complexes can also be defined using the anti-symmetric complexes throughout without further mention.



\subsection{The Mayer-Vietoris sequence in coarse homology}
\label{SectionMCCohomology}


In this section, we discuss the Mayer-Vietoris sequence for a decomposition of a proper metric space $M$.
This is rather standard material (see, e.g., \cite{HigsonRoeYu}) but does not appear in the literature in our formulation, using big families and the measure theoretic description of coarse homology, so we recall the relevant material in this language.


\begin{proposition}
\label{PropMayerVietoris}
Let $\cX$, $\cY$ be two big families in $M$.
Then there are short exact sequences of chain complexes
\[
\begin{tikzcd}[column sep=0.5cm, row sep=0.4cm]
0 \ar[r]
&
CX_\bullet(\cX \Cap \cY) \ar[r]
&
CX_\bullet(\cX) \oplus CX_\bullet(\cY)
\ar[r]
&
CX_\bullet(\cX \Cup \cY)
\ar[r]
&
0
\end{tikzcd}
\]
where the first map is the diagonal inclusion, while the second map is given by
\[
(\mu_1, \mu_2) \longmapsto \mu_1 -  \mu_2.
\]
Similarly, we get a short exact sequence when replacing each complex by the quotient complex of anti-symmetric coarse chains.
\end{proposition}


\begin{proof}

Injectivity of the left map is clear.

To see surjectivity of the right map, let $\mu \in CX_n(\cX \Cup \cY)$ be supported on $(X \cup Y)^{n+1} \cap \Delta_R$ for members $X \in \cX$, $Y \in \cY$ and $R \geq 0$.
Then 
\[
\mu_1 := \big(X_{S} \otimes {\underbrace{\mathbf{1} \otimes \cdots \otimes \mathbf{1}}_{n}}\big) \cdot \mu
\] 
is contained in $CX_n(\cX)$ for any $S \geq 0$, as $\mu_1$ vanishes outside
\[
X_S \times M^n \cap \Delta_R \subseteq X_{S+R}^{n+1} \cap \Delta_R.
\] 
The difference $\mu_2 := \mu_1 - \mu$ is given by the same formula, but with $X_S^c$ replacing $X_S$.
The same calculation shows that $\mu_2$ is supported on $(X_S^c)_R \cap (X \cup Y)$, which is contained in $Y$ if $S$ is large enough. 
Hence for such a choice of $S$, we have $\mu_2 \in CX_n(\cY)$.
This shows that $\mu = \mu_1 - \mu_2$ is contained in the image of the right map.

