\paragraph{The coarse character map.}

 The cyclic homology of the localization ideals $\mathscr{A}=\sB(\cY)$ for big families $\cY$ in a proper metric space $M$ is closely related to coarse homology via the \emph{coarse character map} 
\begin{equation}
\label{CharacterMap}
\chi_* : HC_n(\sB(\cY)) \longrightarrow HX_n(\cY),
\end{equation}
see \cite[\S4.2]{Roe-cohom}.
This map is induced by a chain map on the underlying complexes, which we will describe now.
(In fact, the map described here is the dual of the character map introduced in \cite[\S4.2]{Roe-cohom}.)

The map $\chi$ is defined as follows.
Given elements $T_0, \dots, T_n \in \sB(\cY)$, 
let us consider the multilinear functional $\chi(T_0 \otimes \dots \otimes T_n)$ on the space $C_c(M)$ of compactly supported continuous functions on $M$ defined by
\begin{equation}
\label{DefCharacterMap}
  \chi(T_0\otimes \dots \otimes T_n)(f_0, \dots, f_n) := \Tr(f_0 T_0 \cdots f_n T_n).
\end{equation}
Note that because the $T_i$ are locally trace-class and the $f_i$ are compactly supported, each of the terms $f_i T_i$ is trace-class, and so is their product;
hence the expression is well-defined.
It is shown in \cite[\S4.2]{Roe-cohom} that \eqref{DefCharacterMap} is locally bounded as a linear functional on the subspace of decomposables in $C_c(M^{n+1})$, therefore extends by continuity to a linear functional on $C_c(M^{n+1})$ and hence is given by integration with respect to some locally finite complex-valued Borel measure on $M^{n+1}$ by the Kakutani-Markhov-Riesz theorem.
Because each $T_i$ has finite propagation, this measure
has support in some $R$-thickening $\Delta_R$ of the multidiagonal, hence we obtain a well-defined element $\chi(T_0 \otimes \dots \otimes T_n)$ in $CX_n(M)$.

 Moreover, if each $T_i$ is supported on some member $Y_i$ of $\cY$, the measure $\chi(T_0 \otimes \dots \otimes T_n)$ is supported on $Y_0 \cup \cdots \cup Y_n$.
 This gives an element $\chi(T_0 \otimes \dots \otimes T_n)$ in $CX_n(\cY)$.
 This defines a map 
 \[
 \chi : C_n(\sB(\cY)) \longrightarrow CX_n(\cY)
 \]
 for each big family $\cY$ in $M$.


\begin{lemma}
The map $\chi$ defined above descends to a chain map 
\begin{equation*}
%\label{CharacterMap}
  \chi : C_\bullet^\lambda(\sB(\cY)) \longrightarrow CX^\alpha_\bullet(\cY), %\qquad \chi^* : CX^\bullet_\alpha(M) \longrightarrow C^\bullet_\lambda \big(\sB(M)\big)	
\end{equation*}
\end{lemma}

Since the anti-symmetric complex $CX_\bullet^\alpha(\cY)$ also computes coarse homology, this yields the desired character map \eqref{CharacterMap}. 

\begin{proof}
We first show that $\chi$ indeed descends to the quotient $C^\lambda_n(\sB(\cY))$. 
For any decomposable cochain $f_0\otimes\dots\otimes f_n\in CX^n(\cY)$ which is coarse on $\cY$, we use cyclicity of the trace to deduce that
\begin{align*}
\chi\big(\lambda(T_0 \otimes \cdots \otimes T_n)\big)(f_0, \dots, f_n)
&= (-1)^n \cdot \chi(T_n \otimes T_0 \otimes \cdots \otimes T_{n-1})(f_0, \dots, f_n)
\\
&= (-1)^n \cdot \Tr(f_0 T_n f_1 T_0 f_2 T_1 \cdots f_n T_{n-1})
\\
&= (-1)^n \cdot \Tr(f_1 T_0 f_2 T_1 \cdots f_n T_{n-1}f_0 T_n )
\\
&= (-1)^n \cdot \chi(T_0 \otimes \cdots \otimes T_n)(f_1, \ldots, f_n, f_0).
\end{align*}
This shows that $\chi(\lambda(T_0 \otimes \cdots \otimes T_n))$ has the same pairing with anti-symmetric coarse cochains on $\cY$ as $\chi(T_0 \otimes \cdots \otimes T_n)$ does. 
Hence both measures agree in the quotient $CX^\alpha_n(\cY)$.

To see that $\chi$ is a chain map, we calculate
\begin{align*}
\chi\big(b(T_0 \otimes \cdots \otimes T_n)\big)&(f_0, \dots, f_{n-1}) 
\\
&= \sum_{i=0}^{n-1} (-1)^i \chi\big(T_0 \otimes \cdots \otimes T_{i}T_{i+1} \otimes \cdots \otimes T_n\big)(f_0, \dots, f_{n-1})	
\\
&\qquad + (-1)^n \chi\big(T_n T_0 \otimes \cdots  \otimes T_{n-1}\big)(f_0, \dots, f_{n-1})
\\
&= \sum_{i=0}^{n-1} (-1)^i \chi\big(T_0 \otimes \cdots  \otimes T_n\big)(f_0, \dots, \underbrace{\mathbf{1}}_{i+1}, \dots f_{n-1})	
\\
&\qquad + (-1)^n \chi\big(T_n \otimes T_0 \otimes \cdots  \otimes T_{n-1}\big)(f_0, \mathbf{1}, f_1, \dots, f_{n-1})
\\
&= - \chi(T_0 \otimes \cdots \otimes T_n) \big(\delta(f_0 \otimes \dots \otimes f_{n-1})\big)
\\
&\qquad+ \chi(T_0 \otimes \cdots \otimes T_n)(\mathbf{1}, f_0, \dots, f_{n-1})\\
&\qquad + (-1)^n \chi\big(T_0 \otimes \cdots  \otimes T_{n}\big)(\mathbf{1}, f_1, \dots, f_{n-1},f_0).
\end{align*}
Thus, we have
\[
\chi\big(b(T_0 \otimes \cdots \otimes T_n)\big)(f_0\wedge \dots \wedge f_{n-1}) = - \chi(T_0 \otimes \cdots \otimes T_n)\big(\delta(f_0\wedge \dots \wedge f_{n-1})\big),
\]
and it follows that $\chi(b(T_0 \otimes \cdots \otimes T_n))$ has  the same pairing with anti-symmetric cochains as $-\partial \chi(T_0 \otimes \cdots \otimes T_n)$, in other words, they agree in the quotient $CX^\alpha_{n-1}(\cY)$.
\end{proof}





