of algebras, which yields a long exact sequence in homotopy $K$-theory.
%\[
%\partial : KH_\bullet\left(\frac{\sB(\cY \Cap \{X\})}{\sB(\cY \Cap \partial X)}\right) \longrightarrow KH_{\bullet - 1} (\sB(\cY \Cap \partial X)).
%\]
The Mayer-Vietoris boundary map is then the boundary map of this long exact sequence, precomposed with the map induced in $KH$ by the algebra homomorphism
\[
\sB(\cX \Cup \cY) \longrightarrow \frac{\sB(\cX \Cup \cY)}{\sB(\cY)} \cong \frac{\sB(\cX)}{\sB(\cX \Cap \cY)}.
\]



\subsection{Chern characters and Mayer-Vietoris maps}

Quite generally, Chern characters are natural transformations comparing some flavor of $K$-theory with some flavor of cyclic homology.
In this section, we review the general theory needed for the formulation of the Kubo and Kitaev pairings in these terms in Section \ref{SectionIntegralityKubo}. 

\paragraph{Abstract properties.}

For any $n \in \Z$ and any $m \geq 0$, there is a \emph{Chern character} homomorphism
\[
\ch_n^{(m)} : K_n^{\mathrm{alg}}(\sA) \longrightarrow HC_{n+2m}(\sA),
\]
where we sometimes leave out the indices $n, m$, depending on the context.
For fixed $n$, the Chern characters have the property that the Chern characters for different $m$ are related by the $S$-operator \eqref{Soperator} through the formula 
\begin{equation}
\label{CompatibilityS}
S \ch_n^{(m)} = \ch_n^{(m-1)}.
\end{equation}
This relation is a shadow of the fact that the Chern character actually takes values in \emph{periodic} cyclic homology $HP_n(\sA)$, see \cite[11.4.3]{Loday}. 
Because the latter theory is homotopy invariant (in the sense that the evaluation maps $\sA[x] \to \sA$ induce isomorphisms in $HP$, see \cite{Goodwillie}), the Chern character factorizes naturally through homotopy $K$-theory,
\begin{equation*}%\label{ChernCharacterFactorizesThroughKH}
\ch_n^{(m)} : K^{\mathrm{alg}}_n(\sA)
\longrightarrow
KH_n(\sA)
\xrightarrow{~\ch_n~}
HP_n(\sA) 
\longrightarrow
HC_{n+2m}(\sA).
\end{equation*}
The Chern character intertwines the boundary maps corresponding to ideal inclusions $\sJ \subseteq \sA$, leading to commutative diagrams \cite[11.4.8]{Loday}
\begin{equation}
\label{ChernVsBoundary}
\begin{tikzcd}
K_n^{\mathrm{alg}}(\sA/\sJ)
\ar[r] 
\ar[rr, bend left=20, "\ch_n^{(m)}"]
\ar[d, "\partial"']
&
KH_n(\sA/\sJ)
\ar[r, "\ch_n^{(m)}"]
\ar[dd, "\partial"']
&[0.8cm]
HC_{n+2m}(\sA/\sJ)
\ar[d, "\partial"']
\\
K_{n-1}^{\mathrm{alg}}(\sA, \sJ)
&
&
HC_{n-1+2m}(\sA, \sJ)
\\
K_{n-1}^{\mathrm{alg}}(\sJ)
\ar[u]
\ar[r]
\ar[rr, "\ch_n^{(m)}"', bend right=20]
&
KH_{n-1}(\sJ)
\ar[r, "\ch_n^{(m)}"]
&
HC_{n-1+2m}(\sJ).
\ar[u]
\end{tikzcd}	
\end{equation}
If $\sA$ is a Banach algebra, one may define the \emph{topological cyclic homology} groups $HC^{\mathrm{top}}_n(\sA)$, $n \in \Z$ of $\sA$. 
These may be taken to be the homology groups of the cyclic complex $C^{\mathrm{top},\lambda}_\bullet(\sA)$, defined just as $C^\lambda_\bullet(\sA)$ but replacing the algebraic tensor product by the completed projective tensor product. 
The inclusion from the algebraic to the completed tensor product induces comparison maps $HC_n(\sA) \to HC_n^{\mathrm{top}}(\sA)$.
One also has a topological version of the Chern characters defined on topological $K$-theory, which has the property that the squares
\begin{equation*}%\label{CompatibleChAlgTop}
\begin{tikzcd}
K_n^{\mathrm{alg}}(\sA) \ar[r, "\ch_n^{(m)}"]
\ar[d]
&
HC_{n+2m}(\sA)
\ar[d]
\\
K_n^{\mathrm{top}}(\sA) \ar[r, "\ch_n^{(m)}"]
&
HC_{n+2m}^{\mathrm{top}}(\sA)
\end{tikzcd}
\end{equation*}
commute for any Banach algebra $\sA$ \cite[\S4.2]{KaroubiHomologieCyclique}.
It will be important that under the topological Chern character, Bott periodicity is mapped to the $S$-operator \eqref{Soperator} in the sense that we have the commutative diagram
\begin{equation}
\label{CompatibilityBottS}
\begin{tikzcd}[column sep=1.5cm]
K_n^{\mathrm{top}}(\sA) \ar[r, "\ch_n^{(m)}"]
\ar[d, "\beta"']
&
HC_{n+2m}^{\mathrm{top}}(\sA)
\\
K_{n+2}^{\mathrm{top}}(\sA) \ar[r, "\ch_{n+2}^{(m)}"]
&
HC_{n+2m+2}^{\mathrm{top}}(\sA).
\ar[u, "S/2\pi i"']
\end{tikzcd}
\end{equation}
see \cite[Corollaire 4.17]{KaroubiHomologieCyclique}.


\paragraph{Explicit formulas.}
We will use the following explicit cocycle representative for the Chern character in the degrees $n \in \{0, 1\}$, for unital $\sA$.
For any $n=2m$ is even, then the Chern character $K_0^{\mathrm{alg}}(\sA) \to HC_{2m}(\sA)$ is represented by the explicit cocycle
\begin{equation}
\label{Ch0Formula}
  \ch_0^{(m)}(P) := (-1)^m \frac{(2m)!}{m!} \cdot  [\tr(\underbrace{P \otimes \cdots \otimes P}_{n+1})].
\end{equation}
for idempotents $P = (P_a^b) \in M_k(\sA)$, where
\[
\tr(P \otimes \cdots \otimes P) = \sum_{a_0, \dots, a_n = 1}^k P_{a_0}^{a_1} \otimes P_{a_1}^{a_2} \otimes  \cdots \otimes P_{a_{n-1}}^{a_n} \otimes P_{a_n}^{a_0}.
\]
One may check that choosing a similar idempotent $P' = UPU^{-1}$ results in a cohomologous cocycle, hence $\ch_0^{(m)}$ is well-defined on $K_0^{\mathrm{alg}}(\sA)$.
%
\begin{comment}
	If $\sA$ is not necessarily unital, then elements of $K_0(\sA)$ are represented by formal differences $[P] - [Q]$ of idempotents in $M_k(\sA^+)$ such that $P - Q \in M_k(\sA)$.
Here we define
\[
\ch_0^{(m)}([P] - [Q]) = \ch_0^{(m)}(P) - \ch_0^{(m)}(Q) \in HC_{2m}(\sA^+, \sA) \cong HC_{2m}(\sA).
\]
\end{comment}
%
The compatiblity of these cocycles with the $S$-operation \eqref{CompatibilityS} may be explicitly checked on cocycle level using the description of the $S$-operator from \cite[Thm.~2.2.7]{Loday}.

For any $n = 2m+1$ odd, the Chern character $K_1^{\mathrm{alg}}(\sA) \to HC_n(\sA)$ of an invertible element $U \in \GL_k(\sA)^+$ has the explicit cocycle representation

\begin{equation}
\label{Ch1Formula}
\ch_1^{(m)}(U) = m! \cdot \big[\tr\big(\underbrace{(U - 1) \otimes (U^{-1} - 1) \otimes \cdots \otimes (U - 1) \otimes (U^{-1} - 1)}_{m+1 ~\text{pairs}}\big)\big].
\end{equation}
The compatibility with the $S$-operator may again be explicitly checked on cocycle level.
Also the commutativity of the diagrams \eqref{ChernVsBoundary} may be checked explicitly in the $n=1$ case using the explicit description of the boundary map as in \cite[\S4]{Milnor}.

\paragraph{Compatibility with the Mayer-Vietoris map.}

We will crucially use the following compatibility result between Mayer-Vietoris maps in $KH$ and in coarse homology.
\begin{lemma}
\label{LemmaChernMVboundary}
Let $\cX$, $\cY$ be big families in $M$.
Then for any $m, n \in \N_0$, $n \geq 1$, the following diagram commutes:
\[
\begin{tikzcd}
KH_{n-2m}(\sB(\cX \Cup \cY))
\ar[d, "\partial_{\mathrm{MV}}"']
\ar[r, "\ch^{(m)}_{n-2m}"] 
&[1cm]
HC_{n}(\sB(\cX \Cup \cY)) 
\ar[r, "\chi_*"]
&
HX_{n}(\cX \Cup \cY)
\ar[d, "\partial_{\mathrm{MV}}"]
\\
KH_{n-2m-1}(\sB(\cX \Cap \cY))
\ar[r, "\ch^{(m)}_{n-2m-1}"] 
&
HC_{n-1}(\sB(\cX \Cap \cY)) 
\ar[r, "\chi_*"]
&
HX_{n-1}(\cX \Cap \cY)
\end{tikzcd}
\]
\end{lemma}

\begin{proof}
Consider the diagram
\[
\begin{tikzcd}
KH_{n-2m}(\sB(\cX \Cup \cY))
\ar[dddd, "\partial_{\mathrm{MV}}"', bend right=70]
\ar[d]
\ar[r, "\ch_{m}"]
&
HC_n(\sB(\cX \Cup \cY))
\ar[d]
\\
\displaystyle KH_{n-2m}\left(\frac{\sB(\cX \Cup \cY)}{\sB(\cY)}\right)
\ar[r, "\ch_{m}"]
&
\displaystyle HC_n\left(\frac{\sB(\cX \Cup \cY)}{\sB(\cY)}\right)
\\
\displaystyle KH_{n-2m}\left(\frac{\sB(\cX)}{\sB(\cX \Cap \cY)}\right)
\ar[u, "\cong"]
\ar[dd, "\partial"]
\ar[r, "\ch_{m}"]
&
\displaystyle HC_n\left(\frac{\sB(\cX)}{\sB(\cX \Cap \cY)}\right)
\ar[u, "\cong"]
\ar[d, "\partial"]
\\
& HC_{n-1}\big(\sB(\cX), \sB(\cX \Cap \cY)\big)
\\
KH_{n-2m-1}(\sB(\cX \Cap \cY))
\ar[r, "\ch_{m}"]
&
HC_{n-1}(\sB(\cX\Cap \cY)),
\ar[u]
\end{tikzcd}
\]
which commutes by the naturality of the Chern character and its compatibility \eqref{ChernVsBoundary} with boundary maps.
The left vertical composition is by definition the Mayer-Vietoris boundary.
We now paste this diagram to the following diagram,
\[
\begin{tikzcd}
HC_n(\sB(\cX \Cup \cY))
\ar[d]
\ar[r, "\chi_*"]
&
HX_n(\cX \Cup \cY)
\ar[d]
\ar[dddd, "\partial_{\mathrm{MV}}", bend left=70]
\\
\displaystyle HC_n\left(\frac{\sB(\cX \Cup \cY)}{\sB(\cY)}\right)
\ar[r, "\chi_*"]
&
HX_n(\cX \Cup \cY, \cY)
\\
\displaystyle HC_n\left(\frac{\sB(\cX)}{\sB(\cX \Cap \cY)}\right)
\ar[u, "\cong"]
\ar[d, "\partial"]
\ar[r, "\chi_*"]
&
HX_n(\cX, \cX \Cap \cY)
\ar[u, "\cong"]
\ar[dd, "\partial"]
\\
HC_{n-1}\big(\sB(\cX), \sB(\cX \Cap \cY)\big)
\ar[dr, "\chi_*", bend left=10]
\\
HC_{n-1}(\sB(\cX \Cap \cY)),
\ar[u]
\ar[r, "\chi_*"]
&
HX_{n-1}(\cX \Cap \cY),
\end{tikzcd}
\]
which commutes by Lemma~\ref{CharacterBoundary}.
The right vertical map is the Mayer-Vietoris boundary in coarse homology, see Remark~\ref{RemarkAlternativeMVboundary}.
This finishes the proof.
\end{proof}



\section{Proof of the quantization result}

\label{ProofQuantization}

In this section, we give a proof of the quantization result Thm.~\ref{MainQuantizationThm}.
We start by explaining how coarsely transverse collections of half spaces and partitions give rise to coarse cohomology classes, to connect them to the Chern character and the coarse character map.
We then give a proof of the Kubo pairing via dimensional reduction and then reduce the Kitaev pairing to the Kubo case.



\subsection{Coarse cohomology classes from half spaces}
\label{SectionHalfSpaceClasses}

Let $X_1, \dots, X_n$ be a coarsely transverse collection of half spaces in a proper metric space $M$. 
For $k=0,\ldots,n-1$, we define the big families
\begin{equation}
\label{DefinitionXk}
\cX_k := \partial X_{k+1} \Cap \cdots \Cap \partial X_n,	
\end{equation}
so that $\cX_0 = \partial X_1 \Cap \cdots \Cap \partial X_n$   is the big family of bounded subsets (because the collection is coarsely transverse). 
By convention, we also set $\cX_n := \{M\}$.

\begin{lemma}\label{LemShortenedSwitchCochain}
For each $0 \leq k \leq n$, we have
\[
\mathbf{1} \wedge X_1 \wedge \cdots \wedge X_k \in CX^k_\alpha(\cX_k).
\]
\end{lemma}

\begin{proof}
We note that for each $i=1, \dots, k$, we may split up $\mathbf{1} = X_i + X_i^c$, hence by anti-symmetry, we have
\begin{equation}
\label{TrickyRewritten}
 \mathbf{1} \wedge X_1 \wedge \cdots \wedge X_k = X_i^c \wedge X_1 \wedge \cdots \wedge X_k.
\end{equation}
Let $R>0$ and take 
\[
x = (x_0, \dots, x_k) \in \supp(\mathbf{1} \wedge X_1 \wedge \cdots \wedge X_k) \cap \Delta_R \cap \left(\bigcap_{i={k+1}}^n (X_i)_R \cap (X_i^c)_R\right)^{k+1}.
\]
By \eqref{TrickyRewritten}, for each fixed $i=1, \dots, k$, there exists an index $0 \leq a \leq k$ such that $x_a \in X_i^c$ and another index $b$ such that $x_b \in X_i$.
But because $x \in \Delta_R$, we have $d(x_a, x_c) \leq 2R$ for all $0 \leq c\leq n$.
In total, we conclude that $x_c \in (X_i)_{2R} \cap (X_i^c)_{2R}$. 
We conclude that each coordinate $x_c$ is in fact contained in the set
\[
\bigcap_{i=1}^n (X_i)_{2R} \cap (X_i^c)_{2R} \in \partial X_1 \Cap \cdots \Cap \partial X_n,
\]
which is bounded because $X_1, \dots, X_n$ are coarsely transverse.
\end{proof}


Observe that for each $1 \leq k \leq n$, we have a Mayer-Vietoris decomposition
\begin{align*}
\cX_{k} &= \big(\cX_{k} \Cap \{X_k\} \big) \Cup \big(\cX_{k} \Cap \{X_k^c\}  \big), \\
 \cX_{k-1} &= \big( \cX_{k} \Cap \{X_k\} \big) \Cap \big( \cX_{k} \Cap \{X_k^c\}  \big),
\end{align*}
so we obtain Mayer-Vietoris boundary maps
\[
\delta_{\mathrm{MV}} : HX^{\bullet-1}(\cX_{k-1}) \longrightarrow HX^{\bullet}(\cX_k), \rlap{\qquad $k=1, \dots, n$.}
\]
In particular, $HX^0(\cX_0) \cong \C$, the identification given by identifying $1 \in \C$ with the class of the constant function $\mathbf{1}$, so via an iterated application of the Mayer-Vietoris boundary map, we may iteratively define coarse cohomology classes $[\theta_k] \in HX^k(\cX_k)$, $k=0, \dots, n$,  by
\begin{equation}
\label{CompatibilityThetaKboundary}
[\theta_k] = \delta_{\mathrm{MV}}[\theta_{k-1}], \qquad \theta_0 = \mathbf{1}.
\end{equation}

\begin{lemma}
\label{LemmaFormulaThetak}
For each $0 \leq k \leq n$, the above cohomology class can be represented by
\begin{equation}
\label{ThetaCocycle}
\theta_k = (-1)^{\frac{k(k+1)}{2}}\frac{1}{k!} \cdot \mathbf{1} \wedge X_1 \wedge \cdots \wedge X_k.
\end{equation}
\end{lemma}


\begin{proof}
We prove the statement of the lemma by induction. 
For $k=0$, there is nothing to show.
Suppose now that we want to establish the result for $k \geq 1$, knowing the result for $k-1$.
Now by Remark~\ref{RemarkAntiSymmetricVersion}, we have $\delta_{\mathrm{MV}}[\theta_k] = [\delta \tilde{\theta}_k]$ with $\tilde{\theta}_k$ given by the formula Eq.~\eqref{AntisymmetricLocalization}. Explicitly, we have
\begin{align*}
\tilde{\theta}_{k-1} 
&= \frac{(-1)^{\frac{k(k-1)}{2}}}{k!} \cdot \left(\sum_{i=0}^{k-1} {\underbrace{\mathbf{1} \otimes \cdots \otimes \mathbf{1}}_i} \otimes X_k^c \otimes {\underbrace{\mathbf{1} \otimes \cdots \otimes \mathbf{1}}_{k-1-i}}\right)\cdot \mathbf{1} \wedge X_1 \wedge \cdots \wedge X_{k-1}
\\
&= \frac{(-1)^{\frac{k(k-1)}{2}}}{k!} \cdot \left(X_k^c \wedge X_1 \wedge \cdots \wedge X_{k-1} + \sum_{i=1}^{k-1} \mathbf{1} \wedge X_1 \wedge \cdots \wedge X_k^c X_i \wedge \cdots \wedge X_{k-1} \right).
\end{align*}
Then, using \eqref{SimpleASDifferential}, we get
\begin{align*}
[\theta_k]=\delta_{\mathrm{MV}}[\theta_{k-1}] 
= [\delta \tilde{\theta}_{k-1}]
&= \frac{(-1)^{\frac{k(k-1)}{2}}}{k!} \cdot \big[\mathbf{1} \wedge X_k^c \wedge X_1 \wedge \cdots \wedge X_{k-1}\big]
\\
&= \frac{(-1)^{\frac{k(k-1)}{2}}}{k!} (-1)^k\cdot \big[\mathbf{1} \wedge X_1 \wedge \cdots \wedge X_{k-1} \wedge X_k\big],
\end{align*}
which is the claimed result \eqref{ThetaCocycle}.
\end{proof}


We finish this section with a lemma for converting switch functions to half spaces.

\begin{lemma}\label{LemSwitchToHalfSpace}
Let $\chi_1,\ldots,\chi_n$ be a coarsely transverse collection of switch functions on $M$. 
Then $\mathbf{1} \wedge \chi_1 \wedge \cdots \wedge \chi_n$ is a coarse cochain on $M$, and
\[
\big[\mathbf{1}\wedge\chi_1\wedge\dots\wedge \chi_n\big]=\big[\mathbf{1}\wedge X_1\wedge\cdots\wedge X_n\big] \in HX^n(M),
\]
where $X_i=\supp(\chi_i)$, $i=1,\ldots,n$.
\end{lemma}


\begin{proof}
Setting $W_i := \chi_i - X_i$ ($i=1, \dots, n$) and using \eqref{SimpleASDifferential}, one obtains the cochain identity
\begin{align*}
&\mathbf{1}\wedge \chi_1\wedge \dots\wedge\chi_{i}\wedge X_{i+1} \wedge\dots \wedge X_n - \mathbf{1}\wedge \chi_1\wedge \dots\wedge \chi_{i-1}\wedge X_i \wedge\dots \wedge X_n\\
& =\delta\big(
\chi_1\wedge \dots \wedge \chi_{i-1}\wedge W_i\wedge X_{i+1}\wedge \dots \wedge X_n
\big)
\\
& =\delta\Bigg(
\sum_{j=1}^n\big({\underbrace{\mathbf{1} \otimes \cdots \otimes \mathbf{1}}_{j-1}} \otimes W_i \otimes {\underbrace{\mathbf{1} \otimes \cdots \otimes \mathbf{1}}_{n-j}}\big)\cdot
\big(
\chi_1\wedge\dots\wedge \chi_{i-1}\wedge \mathbf{1}\wedge X_{i+1}\wedge \dots\wedge X_n
\big)
\Bigg),
\end{align*}
where in the second step, we use that all summands still contain a factor of $\mathbf{1}$ vanish after applying $\delta$, in light of \eqref{SimpleASDifferential}.


Now, the proof of Lemma~\ref{LemShortenedSwitchCochain} generalizes to show that $\mathbf{1}\wedge \chi_1\wedge \dots\wedge\chi_{i-1}\wedge X_{i+1} \wedge\dots \wedge X_n$ is contained in $CX^{n-1}_\alpha(\cY_i)$ with
\[
\cY_i = \{\supp(\chi_i)\} \Cap \{\supp(\mathbf{1} - \chi_i)\}.
\]
Since $W_i \in \cY_i$, Lemma \ref{LemmaLocalization} (and Remark~\ref{RemarkAntiSymmetricVersion}) yields that the term in the bracket above is contained in $CX^{n-1}_\alpha(M)$.
Therefore, one obtains that if $\mathbf{1}\wedge \chi_1\wedge \dots\wedge\chi_{i}\wedge X_{i+1} \wedge\dots \wedge X_n$ is a coarse cochain on $M$, then so is $\mathbf{1}\wedge \chi_1\wedge \dots\wedge\chi_{i-1}\wedge X_{i} \wedge\dots \wedge X_n$, and both define the same cohomology class.
This implies the result by induction on $i$.
%
%
%
%
\begin{comment}
