\[
\tilde{\cX}_k := \{\supp(\chi_{k+1})\} \Cap  \{\supp(\mathbf{1} - \chi_{k+1})\}\Cap \cdots \Cap \{\supp(\chi_n)\} \Cap  \{\supp(\mathbf{1} - \chi_n)\}
