\subsection{Coarse cohomology classes from partitions}
\label{SectionPartitionClasses}

Let $M$ be a proper metric space.

\begin{lemma}
\label{LemmaPartitionCochain}
Let $A_0, \dots, A_n \subseteq M$ be a collection of Borel subsets.
\begin{enumerate}[{\normalfont(1)}]
\item	
If $\cY$ is a big family such that 
\begin{equation}
\label{CoarseTransversalityOfAi}
\{A_0\} \Cap \cdots \Cap\{A_n\} \Cap \cY\qquad \text{is bounded},
\end{equation}
then the cochain $A_0 \wedge\cdots \wedge A_n$ is contained in $CX^n_\alpha(\cY)$.
\item
If the subsets form a partition, then $A_0 \wedge\cdots \wedge A_n$ is Alexander-Spanier closed.
\end{enumerate}
\end{lemma}

In particular, it follows from this lemma that if $A_0, \dots, A_n$ is a coarsely transverse partition, so \eqref{CoarseTransversalityOfAi} holds for $\cY=\{M\}$, then $A_0 \wedge \cdots \wedge A_n$ is a coarse cocycle on all of $M$, hence defines a coarse cohomology class
\[
[A_0 \wedge \cdots \wedge A_n] \in HX^n(M).
\] 

\begin{proof}
(1) Suppose that \eqref{CoarseTransversalityOfAi} holds.
 For some given $R>0$ and a member $Y$ of $\cY$, let 
\[x = (x_0, \dots, x_n) \in \supp(A_0 \wedge \cdots \wedge A_n) \cap\Delta_R\cap Y^{n+1}.
\]
For each $i =0, \dots, n$, there exists at least one $x_a$ with $x_a \in A_i$.
Since $x \in \Delta_R$, we have $d(x_b, x_a) \leq 2R$ for any $b$, so we have $x_b \in (A_i)_{2R}$ for each $b$. 
Because $i$ was arbitrary, we obtain that $x_b \in (A_0)_{2R} \cap \cdots \cap (A_n)_{2R}\cap Y$ for each each $b$.
This shows that $\supp(A_0 \wedge \cdots \wedge A_n) \cap \Delta_R \cap Y^{n+1}$ is bounded.

(2) If the sets $A_i$ form a partition, then using the formula  \eqref{SimpleASDifferential} for $\delta$ and anti-symmetry, we get
\[
\delta(A_0 \wedge \cdots \wedge A_n) 
= \mathbf{1} \wedge A_0 \wedge \cdots \wedge A_n
= \sum_{i=0}^n A_i \wedge A_0 \wedge \cdots \wedge A_n = 0. \qedhere
\]
\end{proof}

We are interested in the relation between cohomology classes corresponding to coarsely transverse partitions and those corresponding to collections of coarsely transverse half spaces.
We will show below that each half space class is actually an integer multiple of a partition class.

Generalizing Example \ref{ExampleEuclideanHalfSpaces}, the following prescription produces a coarsely transverse partition from any given  coarsely transverse collection of half spaces.


\begin{lemma}\label{LemPartitionFromHalfSpaces}
If $X_1, \ldots, X_n \subseteq M$ are arbitrary Borel subsets $M$, then the sets
\begin{align*}
A_0 & = X_1\cdots X_n,\\
A_i & = X_i^c X_{i+1}\cdots X_n,\qquad i=1,\ldots,n,
\end{align*}
form a partition of $M$.
Moreover, if the $X_i$ form a  coarsely transverse collection of half spaces, then this partition is coarsely transverse.
\end{lemma}

\begin{proof}
The $A_i$ defined above indeed form a partition due to the telescopic sum
\begin{align*}
\sum_{i=0}^n A_i &=X_1 X_2 X_3\cdots X_n + X_1^c X_2 X_3\cdots X_n + X_2^c X_3\cdots X_n\dots + X_{n-1}^c X_n+X_n^c\\
&=X_2 X_3\cdots X_n+X_2^c X_3\cdots X_n+\dots + X_{n-1}^c X_n+X_n^c\\
& ~~\vdots
\\
&= X_n+X_n^c=\mathbf{1}.
\end{align*}
For any $R>0$, we have
\begin{align*}
\bigcap_{i=0}^n(A_i)_R
&=\big(X_1 X_2\cdots X_n\big)_R\cap \big(X_1^c X_2\cdots X_n\big)_R\cap\dots \cap \big(X_n^c\big)_R\\
&\subseteq \big(X_1\big)_R\cap \dots \cap \big(X_n\big)_R\cap \big(X_1^c\big)_R\cap \dots \cap \big(X_n^c\big)_R.
\end{align*}
It follows that if $X_1, \ldots, X_n$ are coarsely transverse half spaces, then $A_0,\ldots, A_n$ are coarsely transverse subsets.
\end{proof}

Similarly, for each permutation $\sigma\in S_n$, we have a partition 
\begin{equation}
\label{eqn:PermutedPartitions}
\begin{aligned}
A^\sigma_0 & = X_{\sigma_1}X_{\sigma_2}\cdots X_{\sigma_n}, \\
A^\sigma_i & = X_{\sigma_i}^cX_{\sigma_{i+1}}\cdots X_{\sigma_n}, 
\rlap{\qquad $(i=1,\ldots,n)$,}
\end{aligned}
\end{equation}
of $M$, which is coarsely transverse if $X_1,\ldots,X_n$ are coarsely transverse half spaces. 
In that case, $A^\sigma_0\wedge \dots \wedge A^\sigma_n$ is a coarse $n$-cocycle on $M$.

\begin{proposition}[Sum rule]\label{PropSumOfPartitions}
For coarsely transverse half spaces $X_1,\ldots, X_n$ in $M$, the formula
\[
[\mathbf{1}\wedge X_1\wedge \dots \wedge X_n]=(-1)^n\cdot \sum_{\sigma\in S_n}\sgn(\sigma)\cdot[A^\sigma_0\wedge \dots \wedge A^\sigma_n] \]
holds in $HX^n(M)$.
\end{proposition}


