\begin{proof}
We will prove this proposition by induction.
To this end, we more generally define for each permutation $\sigma \in S_k$ with $1 \leq k \leq n$,
\begin{equation}
\label{eqn:PartitionSubpermutation}
\begin{aligned}
A^\sigma_0 & = X_{\sigma_1}X_{\sigma_2}\cdots X_{\sigma_k}, \\
A^\sigma_i & = X_{\sigma_i}^cX_{\sigma_{i+1}}\cdots X_{\sigma_k}, 
\rlap{\qquad $(i=1,\ldots, k)$.}
\end{aligned}
\end{equation}
Note that although $A^\sigma_0,\ldots, A^\sigma_k$ is a partition of $M$, it may not be coarsely transverse unless $k=n$. Rather, we have
\[
\{A^\sigma_0\} \Cap \cdots \Cap \{A^\sigma_k\}
=
 \partial X_1\Cap\dots \Cap \partial X_k.
\]
By Lemma \ref{LemmaPartitionCochain}, this implies that $A^\sigma_0\wedge \dots \wedge A^\sigma_k$ is contained in $CX^k_\alpha(\cX_k)$, 
with $\cX_k$ as in \eqref{DefinitionXk}, and that this element is closed, hence defines a class in $HX^k(\cX_k)$. 
We will now prove the more general statement that for each $k=1, \dots, n$, we have the formula
\begin{equation}\label{eqn:SumTheoremFormula}
[\mathbf{1}\wedge X_1\wedge \dots \wedge X_k]=(-1)^k\cdot \sum_{\sigma\in S_k}\sgn(\sigma)\cdot[A^\sigma_0\wedge \dots \wedge A^\sigma_k] \in HX^k(\cX_k).
\end{equation}
Because $\cX_n=\{M\}$, the $k=n$ case is precisely the statement of the Proposition.

For $k=1$, \eqref{eqn:SumTheoremFormula} is automatic, since $A^{(1)}_0=X_1$ and $A^{(1)}_1=X_1^c$, so
\[
\mathbf{1}\wedge X_1=(X_1+X_1^c)\wedge X_1=X_1^c\wedge X_1=-A^{(1)}_0\wedge A^{(1)}_1 \in CX_\alpha^1(\cX_1),
\]
already at the level of cochains. 
%
\begin{comment}
For $k=2$, we can directly calculate that
\begin{align*}
\mathbf{1}\wedge X_1\wedge X_2&=\mathbf{1}\wedge (X_1 X_2+X_1 X_2^c)\wedge (X_2 X_1+X_2 X_1^c)\\
&=\mathbf{1}\wedge X_1X_2\wedge X_1^c X_2+\mathbf{1}\wedge X_2^c X_1\wedge X_1X_2 +\mathbf{1}\wedge X_1^cX_2\wedge X_2X_1^c\\
&= \mathbf{1}\wedge A^{(12)}_0\wedge A^{(12)}_1 + \mathbf{1}\wedge A^{(21)}_2\wedge A^{(21)}_1 + \mathbf{1}\wedge X_1^cX_2\wedge X_2X_1^c \\
&= A^{(12)}_0\wedge A^{(12)}_1  \wedge A^{(12)}_2 - A^{(21)}_0\wedge A^{(21)}_1 \wedge A^{(21)}_2+\mathbf{1}\wedge X_1^cX_2\wedge X_2X_1^c
\end{align*}
in $CX_\alpha^2(\cX_2)$, where we used the fact that $A^\sigma_0\wedge\dots\wedge A^\sigma_{k-1}\wedge A^\sigma_k= A^\sigma_0\wedge \ldots\wedge A^\sigma_{k-1}\wedge \mathbf{1}$ for any partition. The remainder term $\mathbf{1}\wedge X_1^cX_2\wedge X_2X_1^c$ is exact, since $X_1^cX_2\wedge X_2X_1^c$ already lies in $CX_\alpha^1(\cX_2)$. This verifies formula \eqref{eqn:SumTheoremFormula} for $k=2$.
\end{comment}

For general $k\geq 2$, direct comparison of the cochains in \eqref{eqn:SumTheoremFormula} quickly becomes much more difficult, and we shall proceed by induction. 
We appeal to Lemma \ref{LemmaFormulaThetak}, which implies that
%\[
%[\mathbf{1}\wedge X_1\wedge\dots\wedge X_n]=(-1)^{\frac{n(n+1)}{2}}n!\theta_n \in HX^n(\{M\}),
%\]
%where $\theta_n=\delta_{\mathrm MV}\theta_{n-1}$. In other words,
\begin{equation}
\begin{aligned}
\label{eqn:SumTheoremMV}
\frac{(-1)^{k}}{k} \cdot [\mathbf{1}\wedge X_1\wedge\dots\wedge X_k]
&=\delta_{\mathrm{MV}}\big([\mathbf{1}\wedge X_1 \wedge \dots \wedge X_{k-1}]\big)
\\
&= (-1)^{k-1} \cdot \sum_{\sigma \in S_{k-1}} \sgn(\sigma) \cdot \delta_{\mathrm{MV}}\big([A_0^\sigma \wedge \cdots \wedge A_{k-1}^\sigma]\big)
\end{aligned}
\end{equation}
in $HX^k(\cX_k)$, where in the second step, we substituted the induction hypothesis.
By Remark~\ref{RemarkAntiSymmetricVersion}, the class $\delta_{\mathrm{MV}}([A_0^\sigma \wedge \cdots \wedge A_{k-1}^\sigma])$ may be represented by the cocycle
\begin{align*}
&-\delta\left( \left(\frac{1}{k} \cdot\sum_{i=0}^{k-1} {\underbrace{\mathbf{1} \otimes \cdots \otimes \mathbf{1}}_i} \otimes X_k \otimes {\underbrace{\mathbf{1} \otimes \cdots \otimes \mathbf{1}}_{k-1-i}}\right)\cdot A_0^\sigma \wedge \cdots \wedge A_{k-1}^\sigma\right)
\\
&\hspace{4cm}= -\frac{1}{k} \sum_{i=0}^{k-1}\mathbf{1}\wedge A^\sigma_0\wedge\dots\wedge A^\sigma_{i-1}\wedge A^{\sigma}_i X_k\wedge A^\sigma_{i+1}\wedge\dots A^\sigma_{k-1}.
\end{align*}
For each $j\neq i$, we may replace each occurrence of $A_j^\sigma$ in this formula by $A^\sigma_j X_k + A^\sigma_j X_k^c$. 
However, it follows from Lemma~\ref{LemmaPartitionCochain}  that for each $j \neq i$, the cochain
\[
A^\sigma_0\wedge \dots \wedge A_j^\sigma X_k^c \wedge\dots\wedge A^\sigma_{i-1}\wedge A^{\sigma}_iX_k\wedge A^\sigma_{i+1}\wedge\dots A^\sigma_{k-1}
\]
is in fact contained in $CX^\bullet_\alpha(\cX_k)$, hence the corresponding term is exact.
%
\begin{comment}
It contains the factors $A^\sigma_0=X_1\dots X_{k-1}$, $A^\sigma_\ell=X_{\sigma_\ell}^c X_{\sigma_{\ell+1}}\dots X_{\sigma_{k-1}}$ for $\ell \neq i, j$ and $A_j^\sigma = X_{\sigma_k}^cX_{\sigma_j}^c X_{\sigma_{j+1}}\dots X_{\sigma_{k-1}}$, $A_i^\sigma = X_{\sigma_i}^c X_{\sigma_{i+1}} \cdots X_{\sigma_k}$.
In total, it contains the factors $X_1,\ldots, X_k$ and $X_1^c,\ldots, X_{k}^c$.
\end{comment}

Therefore, at the level of cohomology, we may simply replace all the $A^\sigma_j$ with $A^\sigma_j X_k$, which yields
\begin{align*}
\delta_{\mathrm{MV}}\big([A_0^\sigma \wedge \cdots \wedge A_{k-1}^\sigma]\big)
= -\left[\mathbf{1}\wedge A^\sigma_0 X_k\wedge\dots\wedge A^\sigma_{k-1} X_k\right].
\end{align*}

In view of formula \eqref{eqn:PartitionSubpermutation}, we have $A_j^\sigma X_k = A_j^{\sigma^+}$, where $\sigma^+\in S_k$ is the extended permutation
\[
\sigma^+ = \begin{pmatrix}
1 & 2 & 3 & \cdots & k-1 & k
\\
\sigma_1 & \sigma_2 & \sigma_3 & \cdots & \sigma_{k-1} & k
\end{pmatrix}.
\]
Notice that $\sgn(\sigma^+) = \sgn(\sigma)$. 
Hence, with this notation, \eqref{eqn:SumTheoremMV} becomes
\begin{align}
\frac{(-1)^k}{k}\cdot\big[\mathbf{1}\wedge X_1\wedge \dots \wedge X_k\big] &=(-1)^{k-1}\cdot\!\!\!\sum_{\sigma\in S_{k-1}}\sgn(\sigma^+)\cdot\Big(-\left[\mathbf{1}\wedge A^{\sigma^+}_0\wedge\dots\wedge A^{\sigma^+}_{k-1}\right]\Big) \nonumber\\
&=(-1)^k\cdot\!\!\!\sum_{\sigma\in S_{k-1}}\sgn(\sigma^+)\cdot\left[\Big(\sum_{i=0}^k A^{\sigma^+}_i\Big)\wedge A^{\sigma^+}_0\wedge\dots\wedge A^{\sigma^+}_{k-1}\right]
\nonumber\\
&=\sum_{\sigma\in S_{k-1}}\sgn(\sigma^+)\cdot\left[A^{\sigma^+}_0\wedge\dots\wedge A^{\sigma^+}_{k-1}\wedge A^{\sigma^+}_k\right]
\nonumber\\
&=\sum_{\substack{\sigma\in S_k \\\sigma(k)=k}}\sgn(\sigma)\cdot\big[A^\sigma_0\wedge\dots\wedge A^\sigma_k\big].\label{eqn:SumTheoremSubpermutation}
\end{align}

Now, for each $\ell=1,\ldots,k$, let $\tau^{(\ell)}\in S_k$ be the cyclic permutation 
\[
\tau^{(\ell)}
= \begin{pmatrix}
1 & \dots & k-\ell & k-\ell+1 & \dots & k
\\
	\ell+1 & \ldots & k &1 &\ldots &\ell
\end{pmatrix}.
\]
From \eqref{eqn:SumTheoremSubpermutation}, we further conclude that
\begin{align*}
\frac{(-1)^k}{k}\cdot[\mathbf{1}\wedge X_1\wedge \dots \wedge X_k]
&=\frac{(-1)^k}{k}\cdot \sgn(\tau^{(\ell)})\cdot\big[\mathbf{1}\wedge X_{\tau^{(\ell)}_1}\wedge\dots \wedge X_{\tau^{(\ell)}_k}\big]\\
&=\sum_{\substack{\sigma\in S_k \\ \sigma_k =\tau^{(\ell)}_k}}\sgn(\tau^{(\ell)}\circ\sigma )\cdot\left[A^{\tau^{(\ell)}\circ \sigma}_0\wedge\dots\wedge A^{\tau^{(\ell)}\circ \sigma}_k\right]\\
&=\sum_{\substack{\sigma\in S_k \\ \sigma_k=\ell}}\sgn(\sigma)\cdot\left[A^\sigma_0\wedge\dots\wedge A^\sigma_k\right]
\end{align*}
holds for each $\ell=1,\ldots,k$ as well.
 Summing over $\ell=1,\ldots,k$ gives the claimed formula \eqref{eqn:SumTheoremFormula}.
\end{proof}


\begin{proposition}[Equipartition]\label{PropEquipartition}
Let $X_1,\ldots, X_n$ be coarsely transverse half spaces in $M$. 
For any $\sigma\in S_n$, we have
\[
[A^\sigma_0\wedge \dots \wedge A^\sigma_n]=\sgn(\sigma)\cdot[A_0\wedge \dots \wedge A_n]\in HX^n(M).
\]
\end{proposition}


\begin{proof}
Fix any $i=1,\ldots,n$, and consider the adjacent transposition $(i-1,i)$. 
First, note that $A^{(i-1,i)}_0 \wedge \dots \wedge A^{(i-1,i)}_n$ differs from $A_0 \wedge \dots \wedge A_n$ only in the $(i-1)$-th and $i$-th wedge factors. 
Due to anti-symmetry and $\sum_{j=0}^n A_j=\mathbf{1}$, we can replace their $i$-th wedge factors by $\mathbf{1}$, so that
\begin{align*}
& A_0 \wedge \dots \wedge A_n +  A^{(i-1,i)}_0 \wedge \dots \wedge A^{(i-1,i)}_n \\
&= A_0 \wedge \cdots \wedge A_{i-1} \wedge \mathbf{1} \wedge A_{i+1} \wedge \cdots A_n + A_0 \wedge \cdots \wedge A_{i-1}^{(i-1, i)} \wedge \mathbf{1} \wedge A_{i+1} \wedge \cdots A_n
\\
&= A_0 \wedge \dots \wedge A_{i-2} \wedge  \left( ({X_{i-1}^cX_{i}} +X_{i}^cX_{i-1})X_{i+1}\cdots X_n\right)\wedge \mathbf{1} \wedge A_{i+1} \wedge\dots \wedge A_n.
\end{align*}
Next, we add the term
\begin{align*}
&A_0 \wedge \dots \wedge A_{i-2} \wedge   (X_{i-1}^c X_i^c X_{i+1}\cdots X_n)\wedge \mathbf{1} \wedge A_{i+1} \wedge\dots \wedge A_n,
\end{align*}
which is exact because the sets
\begin{align*}
& X_1X_2\cdots X_n, \qquad X_1^cX_2\cdots X_n, \qquad\dots\qquad, X_{i-2}^cX_{i-1}\cdots X_n, \\
&~~~~X_{i-1}^c X_i^c X_{i+1}\dots X_n, \qquad X_{i+1}^cX_{i+2}\cdots X_n, \qquad \dots \qquad X_n^c,
\end{align*}
are coarsely transverse.
So in cohomology, 
\begin{align*}
& \big[A_0 \wedge \dots \wedge A_n\big] +  \big[A^{(i-1,i)}_0 \wedge \dots \wedge A^{(i-1,i)}_n\big] \\
&= \big[A_0 \wedge \dots  \wedge A_{i-2} \wedge\left(( {X_{i-1}^cX_{i}} +X_{i}^cX_{i-1} +X_{i-1}^cX_{i}^c) X_{i+1}\cdots X_n\right)\wedge \mathbf{1} \wedge A_{i+1}\wedge\dots \wedge A_n\big]\\
&=\big[(X_1X_2\cdots X_n) \wedge (X_2\cdots X_n) \wedge \dots \wedge (X_{i-1}\cdots X_n)\wedge\\
& \qquad\wedge \left( ({X_{i-1}^cX_{i}} +X_{i}^cX_{i-1}  +X_{i-1}^cX_{i}^c) X_{i+1}\cdots X_n\right)\wedge \mathbf{1} \wedge (X_{i+1}^cX_{i+2}\cdots X_n)\wedge\dots \wedge X_n^c\big],
\end{align*}
where in the second equality, we used anti-symmetry to rewrite
\begin{align*}
A_0 \wedge A_1 \wedge \dots \wedge A_{i-2}
&= A_0 \wedge (A_0 + A_1) \wedge (A_0 + A_1 + A_2) \wedge \dots \wedge (A_0 + \dots + A_{i-2})	
\end{align*}
and invoked the identity $A_0 + \dots + A_j = X_{j+1} \cdots X_n$ 
(which holds for any $j$).
To proceed, we observe that
\begin{align*}
&(X_{i-1}\cdots X_n)\wedge \big(({X_{i-1}^cX_{i}} +X_{i}^cX_{i-1}  +X_{i-1}^cX_{i}^c) X_{i+1}\cdots X_n\big)\\
&=(X_{i-1}\cdots X_n)\wedge \big((\underbrace{{X_{i-1}^cX_{i}} +X_{i}^cX_{i-1}  +X_{i-1}^cX_{i}^c + X_{i-1}X_i}_{=\mathbf{1}}) X_{i+1}\cdots X_n\big) \\
&=(X_{i-1}\cdots X_n) \wedge (X_{i+1}\cdots X_n),
\end{align*}
so we have the simplification
\begin{align*}
& \big[A_0 \wedge \dots \wedge A_n\big] +  \big[A^{(i-1,i)}_0 \wedge \dots \wedge A^{(i-1,i)}_n\big] \\
&=\big[(X_1X_2\cdots X_n) \wedge (X_2\cdots X_n) \wedge \dots \wedge (X_{i-1}\cdots X_n)\wedge\\
& \qquad\qquad \wedge\underbracket{(
 X_{i+1}\cdots X_n )\wedge \mathbf{1} \wedge (X_{i+1}^cX_{i+2}\cdots X_n)\wedge\dots \wedge X_n^c}\big].
\end{align*}
The bracketed factor now vanishes by another telescoping argument,
\begin{align*}
&(X_{i+1}\cdots X_n)\wedge \mathbf{1}\wedge (X_{i+1}^cX_{i+2}\cdots X_n)\wedge \dots \wedge (X_{n-1}^cX_n) \wedge X_n^c\\
&\quad =(X_{i+1}\cdots X_n)\wedge\mathbf{1}\wedge (X_{i+2}\cdots X_n)\wedge (X_{i+2}^c X_{i+3} \cdots X_n)\wedge \dots \wedge X_{n-1}^cX_n\wedge X_n^c\\
&\quad =(X_{i+1}\cdots X_n)\wedge\mathbf{1}\wedge (X_{i+2}\cdots X_n)\wedge \cdots \wedge X_n \wedge \mathbf{1} =0.
\end{align*}
We therefore obtain that
\[
[A_0 \wedge \dots \wedge A_n]+[A^{(i-1,i)}_0 \wedge \dots \wedge A^{(i-1,i)}_n] = 0.
\]
The same argument shows that starting from any permutation $\sigma\in S_n$, and applying any adjacent transposition $(i-1,i)$,
\[
[A^{\sigma\circ (i-1,i)}_0 \wedge \dots \wedge A^{\sigma\circ (i-1,i)}_n] = -[A^{\sigma}_0 \wedge \dots \wedge A^{\sigma}_n],\qquad i=1,\ldots,n.
\]
Since any permutation can be obtained as a sequence of adjacent transpositions, the Proposition follows.
\end{proof}


\begin{corollary}\label{CorEquipartition}
Let $X_1,\ldots,X_n$ be coarsely transverse half spaces in $M$, and $A_0,\ldots,A_n$ be the associated coarsely transverse partition as given in lemma \ref{LemPartitionFromHalfSpaces}. Then
\[
[\mathbf{1}\wedge X_1\wedge\dots\wedge X_n]=(-1)^n n!\cdot[A_0\wedge \dots\wedge A_n]\in HX^n(M).
\]
\end{corollary}

\begin{proof}
This follows immediately from the sum rule and equipartition result, Propositions \ref{PropSumOfPartitions} and \ref{PropEquipartition} respectively.
\end{proof}





\subsection{Integrality result for Kubo pairings}
\label{SectionIntegralityKubo}


Let $M$ be a proper metric space and choose an $M$-module so that the algebra $\sB(M)$ of locally trace-class, finite propagation operators is defined.
We then have the following observation.

\begin{lemma}
\label{LemmaPartitionInTermsOfChernCharacters}
Let $A_0, \dots, A_n$ be a coarsely transverse partition of $M$ and let $X_1, \dots, X_n$ be a coarsely transverse collection of half spaces. 
Let $P=P^2\in M_k(\sB(M)^+)$ and $U\in \GL_k(\sB(M))^+\subseteq \GL_k(\sB(M)^+)$.
Then we have
\begin{align*}
[P; A_0, \dots, A_n] &= (-1)^m\frac{m!}{(2m)!}\cdot \langle \widetilde{\chi}_*\ch(P), A_0 \wedge \cdots \wedge A_n\rangle
& & (n=2m~\text{even})
\\
[U; A_0, \dots, A_n] 
&= \frac{1}{m!}\cdot \langle \chi_*\ch(U), A_0 \wedge \cdots \wedge A_n\rangle
& & (n=2m+1~\text{odd})
\\
[P; X_1, \dots, X_n] &= (-1)^m\frac{m!}{(2m)!}\cdot\langle \widetilde{\chi}_*\ch(P), \mathbf{1} \wedge X_1 \wedge \cdots \wedge X_n\rangle
& & (n=2m~\text{even})
\\
[U; X_1, \dots, X_n] &= \frac{1}{m!}\cdot\langle \chi_*\ch(U), \mathbf{1} \wedge X_1 \wedge \cdots \wedge X_n\rangle
& & (n= 2m+1~\text{odd})
\end{align*}
Here 
%$P \in M_k(\sB(M)^+)$ be an idempotent and $U \in GL_k(\sB(M))^+$ is an invertible, representing elements in $K_0^{\mathrm{alg}}(\sB(M)^+)$, respectively $K_1^{\mathrm{alg}}(\sB(M))$.
 $\chi_*$ is the character map \eqref{CharacterMap}, and the right hand side is the pairing \eqref{CoarsePairing} with the coarse cohomology class determined by the partition, respectively collection of half spaces (see Section~\ref{SectionHalfSpaceClasses} \& \ref{SectionPartitionClasses}).
\end{lemma}

\begin{proof}
In the case of an idempotent $P \in M_k(\sB(M)^+)$, compare the formula \eqref{Ch0Formula} for the Chern character with the alternative formulas \eqref{AlternativeFormulaKitaevPairing} respectively \eqref{KuboPairingCommutatorProduct2}.
In the case of an invertible element $U \in \GL_k(\sB(M))^+$, compare \eqref{Ch1Formula} with the alternative formula \eqref{KitaevPairingAlt}, respectively \eqref{AlternativeFormulaKuboOdd2}.
\end{proof}

We now prove the quantization result, Thm.~\ref{MainQuantizationThm}, for the Kubo pairings.
To this end, let $X_1, \dots, X_n \subseteq M$ be a coarsely transverse collection of half spaces.
Let $\theta_n$ be the corresponding coarse cocycle given by \eqref{ThetaCocycle}, which agrees with $\mathbf{1} \wedge X_1 \wedge \cdots \wedge X_n$ up to a sign.
Consider the composition
\begin{equation}
\label{ImageNeeded}
	K^{\mathrm{alg}}_{n-2m}(\sB(M)^+)
	\xrightarrow{~~\ch_{n-2m}^{(m)}~}
	HC_n(\sB(M)^+)
	\xrightarrow{~~\tilde{\chi}_*~~}
	HX_n(M)
\xrightarrow{~~\substack{\text{pairing} \\~\text{with}~\theta_n}~~}
	\C,
\end{equation}
where $m$ is chosen such that $n - 2m \in \{0, 1\}$.
In light of Lemma~\ref{LemmaPartitionInTermsOfChernCharacters}, this composition agrees with the Kubo pairing up to a dimensional factor.
Thus, it remains to  show that the image of the composition
is the subgroup 
\begin{equation}
\label{TargetSubgroup}
\frac{1}{(2 \pi i)^m} \cdot \Z \subset \C, 
\qquad
m=
\begin{cases}
\frac{n}{2} & n~\text{even},	
\\
\frac{n-1}{2} & n~\text{odd}.
\end{cases}
\end{equation}
The determination of the groups $K^{\mathrm{alg}}_\bullet(\sB(M)^+)$ or the coarse (co)homology groups of $M$ would be a formidable task. Fortunately, for the purposes of showing that the composition \eqref{ImageNeeded} takes values in \eqref{TargetSubgroup}, a dimensional reduction argument to a manageable case suffices, as detailed in the proof below.


\begin{proof}[Proof of \eqref{TargetSubgroup}]
We drop the indices on the relevant Chern characters for better readability.
For every $m, n \in \N_0$, we may consider the following diagram:
\[
