\ar[r, "\ch"]
\ar[rr, dashed, bend right=18, "(2 \pi i)^{-m} \cdot\, \ch"', near end]
&
HC_{2m}^{\mathrm{top}}(M) 
\ar[r, "(S/2 \pi i)^m"]
&
HC_0^{\mathrm{top}}(\sL_1) = \sL_1 /[\sL_1, \sL_1]
\ar[r, "\Tr"]
&
\C.
\end{tikzcd}
\end{equation*}
Here the composition of the first two arrows equals the dashed arrow by compatiblity of $S$ with $\ch$, see \eqref{CompatibilityS}.
The entire map is just given by sending 
\[
K_0(\sL_1) \ni x = [P] - [Q] \longmapsto (2 \pi i)^{-m} \cdot \big(\Tr(P - Q)\big) \in \C.
\]
Since $\sL_1$ is holomorphically closed in the algebra $\sK$ of compact operators, the inclusion $\sL_1 \hookrightarrow \sK$ induces an isomorphism
\begin{equation}
\label{KtheoryCompactOperators}
K^{\mathrm{top}}_n(\sL_1)\cong K^{\mathrm{top}}_n(\sK) \cong \begin{cases}
 \Z	& \text{if}~n~\text{is even},
