 0	& \text{if}~n~\text{is odd},
 \end{cases}
\end{equation}
so any class $x \in K_0^{\mathrm{top}}(\sL_1)$ may be represented as $x = [P] - [Q]$ with $P, Q$ finite-rank projections in $\sL_1$, by the well-known description of $K_0^{\mathrm{top}}(\sK)$.
Therefore $\Tr(P - Q) = \Tr(P) - \Tr(Q) \in \Z$.
We conclude that the image of the map \eqref{ImageNeeded} is indeed contained in the subgroup \eqref{TargetSubgroup}, as desired.
