\subsection{Integrality result for Kitaev pairings}\label{SectionIntegralityKitaev}

In this section, we will prove Theorem \ref{MainQuantizationThm} for coarsely transverse partitions.
This will be done by reducing it to a ``standard situation''.

Denote by $\R^{n+1}_{\geq 0} \subset \R^{n+1}$ the set of vectors $x=(x_0, \dots, x_n)$ such that $x_a \geq 0$ for each $a=0,\ldots,n$. 
Define the \emph{corner}
\[
\mathrm{C}^n := \partial \R^{n+1}_{\geq 0}
\]
to be its boundary, whose elements have $x_a = 0$ for at least one $a$. 
Equip $\mathrm{C}^n$ with the metric that takes the maximum of the distances in each coordinate.
The \emph{standard} coarsely transverse partition of $\mathrm{C}^n$ is defined by
\begin{equation*}
A_i^{\mathrm{std}} = \big\{x = (x_0, \dots, x_n) \in \mathrm{C}^n \mid x_0, \dots, x_{i-1} >0,\,x_i=0\big\},\qquad i=0,\ldots,n.
\end{equation*}

\begin{lemma}\label{LemPartitionClassifyingMap}
Let $A_0,\ldots,A_n$ be a coarsely transverse partition of $M$. There exists a coarse map $f:M\to \mathrm{C}^n$ such that 
\begin{equation}
\label{PullbackStandard}
f^* A^{\mathrm{std}}_i=A_i, \rlap{\qquad $i=0,\ldots,n$.}
\end{equation}
\end{lemma}

\begin{proof}
Define
\begin{equation*}%\label{PartitionClassifyingMap}
  f = (d_{A_0}, \dots, d_{A_n}) : M \longrightarrow \mathrm{C}^n,
\end{equation*}
where $d_{A_i}$ denotes the distance-from-$A_i$ function.
One easily checks that \eqref{PullbackStandard} holds.
%
\begin{comment}
Note that every $x\in M$ lies in exactly one $A_i$, and that
\[
x\in A_i\Leftrightarrow f(x)\in A^{\mathrm{std}}_i\Leftrightarrow A^{\mathrm{std}}_i(f(x))=(f^*A^{\mathrm{std}}_i)(x)=1,
\]
thus
\[
A_i= f^*A^{\mathrm{std}}_i,\qquad i=0,\ldots,n.
\]
\end{comment}
%
Now, the distance function from any subset is Lipschitz continuous with Lipschitz constant one. 
{It follows that $d(f(x), f(y)) \leq d(x, y)$, hence $f$ is controlled.}

It remains to check that $f$ is proper. To this end, let $B \subseteq \mathrm{C}^n$ be bounded. 
Then for some $R>0$, we have
\[
B\subseteq [0, R]^{n+1}\cap \mathrm{C}^n = \bigcap_{i=0}^{n} (A_i^{\mathrm{std}})_R.
\]
Since $f^*A_i^{\mathrm{std}} = A_i$, we get that
\begin{equation*}
  f^{-1}(B) \subseteq \bigcap_{i=0}^{n} (A_i)_R,
\end{equation*}
which is bounded because $A_0, \dots, A_n$ are coarsely transverse. Hence $f$ is proper.
\end{proof}

\begin{lemma}\label{LemHalfSpacesGeneratingPartition}
Let $n\geq 1$, and let $A_0,\ldots,A_n$ be a coarsely transverse partition of $M$. There exists a collection $X_1,\ldots, X_n$ of coarsely transverse half spaces in $M$ such that
\[
[\mathbf{1}\wedge X_1\wedge\dots\wedge X_n]=(-1)^n n!\cdot [A_0\wedge\dots\wedge A_n] \in HX^n(M).
\]
\end{lemma}

\begin{proof}
Recall the partition of $\R^n$ obtained from the standard half spaces $X^{\mathrm{std}}_1,\ldots,X^{\mathrm{std}}_n$ in $\R^n$, given in Eq.~\eqref{EuclideanStandardPartition} of Example \ref{ExampleEuclideanHalfSpaces}. We write it here as
\begin{align*}
\hat{A}^{\mathrm{std}}_0&=X_1^{\mathrm{std}}\cdots X_n^{\mathrm{std}},\\
\hat{A}^{\mathrm{std}}_i&=(X_i^{\mathrm{std}})^c X_{i+1}^{\mathrm{std}}\cdots X_n^{\mathrm{std}},\qquad i=1,\ldots,n.
\end{align*}
It is related to the standard partition of $\mathrm{C}^n$ as follows. 
The orthogonal projection from $\R^{n+1}$ onto the hyperplane
\begin{equation*}
  H^n = \big\{ x = 	(x_0, \dots, x_n) \in \R^{n+1} \mid x_0 + \dots + x_n = 0 \big\}
\end{equation*}
restricts to a bijective coarse equivalence $h:\mathrm{C}^n\to H^n$.
Let $\{e_0,\ldots,e_n\}$ be the standard basis for $\R^{n+1}$, then $\{h(e_1),\ldots,h(e_n)\}$ is a basis for $H^n$, identifying it with $\R^n$. So $h(A_0^{\mathrm{std}}),\ldots,h(A_n^{\mathrm{std}})$ is a coarsely transverse partition of $\R^n$. By iteratively applying further coarse equivalences $\R^n\to \R^n$, we can ``straighten'' this partition to obtain $\hat{A}^{\mathrm{std}}_0,\ldots,\hat{A}^{\mathrm{std}}_n$. (See Fig.~\ref{fig:standard.partition} for the $n=2$ case.) Thus, there is a coarse map $g: \mathrm{C}^n\to\R^n$ such that
\[
g^*\hat{A}^{\mathrm{std}}_i=A^{\mathrm{std}}_i,\qquad i=0,\ldots,n.
\]

Now let $f:M\to \mathrm{C}^n$ be the coarse map of Lemma \ref{LemPartitionClassifyingMap}, so $f^*A^{\mathrm{std}}_i=A_i$. Then $g\circ f:M\to \R^n$ is a coarse map such that $(g\circ f)^*\hat{A}^{\mathrm{std}}_i=A_i$ for $i=0,\ldots,n$. Now,
\[
X_i=(g\circ f)^*X_i^{\mathrm{std}},\qquad i=1,\ldots,n,
\]
is a  coarsely transverse collection of half spaces in $M$. Furthermore, by construction,
\begin{align*}
A_0 &=(g\circ f)^*\hat{A}^{\mathrm{std}}_0 =(g\circ f)^*(X_1^{\mathrm{std}}\cdots X_n^{\mathrm{std}})=X_1\cdots X_n,\\
A_i &=(g\circ f)^*\hat{A}^{\mathrm{std}}_i =(g\circ f)^*\big((X_i^{\mathrm{std}})^c X_{i+1}^{\mathrm{std}}\cdots X_n^{\mathrm{std}}\big)=X_i^c X_{i+1}\cdots X_n,\qquad i=1,\ldots,n.
\end{align*}
Now we can apply Corollary \ref{CorEquipartition} to obtain the claim of the lemma.
\end{proof}



