\ar[r, "\beta^m"]
&
K^{\mathrm{top}}_{0}(\sK)
\ar[dl, equal]
\\
K^{\mathrm{top}}_{-2m}(\sL_1)
\ar[r, "\beta^m"]
\ar[ur, "\cong"]
&
K^{\mathrm{top}}_{0}(\sL_1)\cong K^{\mathrm{top}}_{0}(\sK)
\ar[rr, "\Tr/(2\pi i)^m"]
&
&
\C,
\end{tikzcd}
\]
where we used that Bott periodicity commutes with the boundary map in topological $K$-theory.
The vertical composition
\begin{equation}
\label{VerticalComposition}
K_{n}^{\mathrm{top}}(C^*(M)^+) \longrightarrow K_0^{\mathrm{top}}(\sK) \cong \Z
\end{equation}
in the above diagram may be described as a generalized index map, as we now describe. 
To this end, we first observe that the subsets $X_1, \dots, X_n$ determine a certain compactification $\overline{M}$ of $M$, as follows.
First we define bounded continuous functions $\chi_1, \dots, \chi_n$ on $M$ by
\[
\chi_i = \frac{\tilde{\chi}_i}{\sqrt{1 + \tilde{\chi}_1^2 + \dots + \tilde{\chi}_n^2}}, \qquad \text{with} \qquad \tilde{\chi}_i(x) = d(x, X_i^c) - d(x, X_i).
\] 
Let $\sA \subseteq C_b(M)$ be the commutative $C^*$-subalgebra generated by $C_0(M)$ and $\chi_1, \dots, \chi_n$.
By coarse transversality of $X_1, \dots, X_n$, the difference $\chi_1^2 + \dots \chi_n^2 - 1$ is contained in $C_0(M)$, hence $\sA$ is a unital $C^*$-algebra and hence there exists a compact Hausdorff space $\overline{M}$ containing $M$ as dense subspace such that $\sA \cong C(\overline{M})$.
Let $N := \overline{M} \setminus M$ be the boundary of this compactification.
There is a well-defined $*$-homomorphism
\[
 C(S^{n-1}) \longrightarrow C(\overline{M})/C_0(M) \cong C(\overline{M} \setminus M) = C(N)
\]
that sends the canonical coordinate function $x_i$ on $S^{n-1}$ to $\chi_i$.
Via Gel'fand duality, this yields a continuous map 
\begin{equation}
\label{CoronaMap}
\varphi = \varphi_{X_1, \dots, X_n} : N \to S^{n-1}.
\end{equation}
We refer to $N$ as the \emph{spherical corona of} $M$ provided by the collection of half spaces.

By \cite{QiaoRoe}, there is a bilinear pairing 
\begin{equation}
\label{RoeAlgebraPairing}
  K_i^{\mathrm{top}}(C^*(M)^+) \times K^{i-1}(N) \longrightarrow \Z,
\end{equation}
where $K^{-j}(N) \cong K_j^{\mathrm{top}}(C(N))$ denotes the topological $K$-theory of the space $N$.
First, there is a $*$-homomorphism
\[
C^*(M)^+ \otimes C(N) \longrightarrow C^*(M)^+/\sK, \qquad T\otimes f\longmapsto [T\tilde{f}],
\]
where $\tilde{f} \in C(\overline{M})$ is an arbitrary extension of $f \in C(N)$ to all of $\overline{M}$.
The point here is that if $g \in C_0(M)$, then $Tg$ is compact (hence the map is independent of the choice of representative $\tilde{f}$) and, moreover, for any $\tilde{f} \in C(\overline{M})$ and $T \in C^*(M)$, the commutator $[T, \tilde{f}]$ is compact as well, so the map is a homomorphism (we use here that elements of $C(\overline{M})$ have vanishing variation at infinity, see \cite{QiaoRoe}).
The pairing \eqref{RoeAlgebraPairing} is now obtained as the composition
\begin{align*}
K_i^{\mathrm{top}}(C^*(M)^+) \times K^{i-1}(N) 
&\longrightarrow K_1^{\mathrm{top}}(C^*(M)^+ \otimes C(N)) \\
&\longrightarrow K_1^{\mathrm{top}}(C^*(M)^+/\sK) \\
&\stackrel{\partial}{\longrightarrow} K_0^{\mathrm{top}}(\sK)\cong \Z,
\end{align*}
where the first map is the external product, the second map is induced by the $*$-homomorphism just described and the third map is the boundary map in topological $K$-theory.
By the general description of the external product (e.g.~\cite[Prop.~4.8.3]{HigsonRoe}), the pairing may be described as
\[
\langle [P], [u]\rangle = \ind(P\tilde{u} + 1-P), \qquad \text{or} \qquad \langle [U], [p]\rangle = \ind(U \tilde{p} + 1 - \tilde{p})
\]
in the cases $i=0$ and $i=1$ (mod $2$), respectively.

By joint work of Bunke and the first author \cite[\S4.7]{BunkeLudewig}, the relation of the pairing \eqref{RoeAlgebraPairing} to the iterated Mayer-Vietoris map \eqref{VerticalComposition} is now described as follows.

\begin{theorem}
\label{ThmIndexPairing}
The iterated Mayer-Vietoris map \eqref{VerticalComposition} is equal to the index pairing with the pullback of the canonical generator $\xi_n$ of $K^{n-1}(S^{n-1}) \cong \Z$ along the map \eqref{CoronaMap},
\[
\Tr(\partial_{\mathrm{MV}}^n(x)) = \langle x, \varphi^*\xi_n\rangle, \rlap{\qquad $\forall x \in K_n(C^*(M)^+)$.}
\]
\end{theorem}

Rearranging the factor of $(2 \pi i)^m$, one obtains the following result.

\begin{corollary}
\label{CorollaryIndexPairingDiagram}
Let $n \in \N$ and write $n = 2m$ or $n = 2m+1$, depending on whether $n$ is even or odd. 
Then the following diagram commutes:
\begin{equation}
\label{DiagramCorollary}
\begin{tikzcd}
K^{\mathrm{alg}}_{n-2m}(\sB(M)^+)
\ar[r, "\ch"]
\ar[d]
&
HC_n(\sB(M)^+)
\ar[r, "\widetilde{\chi}_*"]
&
HX_n(M)
\ar[dd, "\substack{\text{pairing with} \\~(2 \pi i)^m \theta_n}"]
\\
K^{\mathrm{top}}_{n-2m}(C^*(M)^+)
\ar[d, "\beta^m"']
\\
K^{\mathrm{top}}_{n}(C^*(M)^+)
\ar[r, "\substack{\text{index pairing} \\ \text{with}~\varphi^*\xi_n}"]
&
\Z
\ar[r, hookrightarrow]
&
\C
\end{tikzcd}
\end{equation}
\end{corollary}



We are now able to prove the following theorem.

\begin{theorem}
\label{ThmNontrivialPairing}
For $M = \R^n$ and the standard half spaces $X_1^{\mathrm{std}}, \dots, X_n^{\mathrm{std}}$ from Example~\ref{ExampleEuclideanHalfSpaces}, the Kitaev and Kubo pairings map onto the subgroup of $\C$ given in Thm.~\ref{MainQuantizationThm}.
\end{theorem}


\begin{proof}
Write $n = 2m$ or $n=2m+1$, depending on whether $n$ is even or odd.
Collecting all constants, observe that we need to show that the image composition
\[
K_{n-2m}^{\mathrm{alg}}(\sB(\R^n)^+)
\xrightarrow{~\ch~} HC_n(\sB(\R^n)^+) \xrightarrow{~\tilde{\chi}_*~} HX_n(\R^n) \xrightarrow{~\substack{\text{pairing with} \\ (2 \pi i)^m \theta_n}~} \C
\]
equals $\Z \subset \C$.
By the commutative diagram \eqref{DiagramCorollary}, the image of this map is \emph{contained in} $\Z$, and the map itself is equal to the composition
\begin{equation}
\label{SecondComposition}
K^{\mathrm{alg}}_{n-2m}(\sB(\R^n)^+)
\longrightarrow
 K^{\mathrm{top}}_{n-2m}(C^*(\R^n)^+) \xrightarrow{~\beta^m~}
K^{\mathrm{top}}_n(C^*(\R^n)^+)
\xrightarrow{~\substack{\text{index pairing} \\ \text{with}~\varphi^*\xi_n}~}\Z.
\end{equation}
It remains to show that this map is onto.
Since each of the half spaces $X_i^{\mathrm{std}}$ is flasque, their Roe algebra $K$-theory groups are trivial  \cite[Prop.~9.3]{Roe-topology} and so each of the Mayer-Vietoris boundary maps
\[
\partial_{\mathrm{MV}} : K_i^{\mathrm{top}}(C^*(\cX_k)) \longrightarrow K_{i-1}^{\mathrm{top}}(C^*(\cX_{k-1}))
\]
is an isomorphism.
With a view on Thm.~\ref{ThmIndexPairing}, we conclude that the index pairing with $\varphi^*\xi_n$ is an isomorphism in this case.
Since $C^*(\cX_0) = \sK$, the algebra of compact operators on $\cH$ (whose $K$-theory is given in \eqref{KtheoryCompactOperators}), this implies 
\[
K_i(C^*(\R^n)) = 
\begin{cases} 
\Z & i - n\equiv 0 \mod 2
\\
0 & i - n \equiv 1 \mod 2,
\end{cases}
\]
compare also \cite[Thm.~6.4.10]{HigsonRoe}.
We conclude that the composition of the last two maps in \eqref{SecondComposition} is actually an isomorphism (in particular, onto).
It remains to show that the first map in \eqref{SecondComposition} is onto.
This statement hinges on the well-known fact that, the non-trivial $K$-theory groups of $C^*(\R^n)$ are generated by the \emph{coarse index class} $\ind(D)$ of the Dirac operator $D$ on $\R^n$ \cite[pp.~33--34]{Roe-topology}. 
%
\begin{comment}
	This follows for example from the statement for $n=1$ and Prop.~11.1.8 in \cite{HigsonRoe}.
\end{comment}

The coarse index of the Dirac operator may be defined if $M$ is a general complete spin manifold, see for example \cite{Roe-cohom}. 
As shown by Roe in \cite[\S4.3]{Roe-cohom}, if $n=\dim(M)$ is even, then there exists a lift $\ind_{\mathrm{fp}}(D) \in K^{\mathrm{alg}}_0(\sB(M))$ of $\ind(D)$ along the comparison map \eqref{ComparisonBRoe}.
We conclude that the first map in \eqref{SecondComposition} is onto if $n$ is even.

In the case that $n = \dim(M)$ is odd, Roe constructs in \cite[\S4.6]{Roe-cohom} a lift of $\ind(D)$ to $K_{-1}^{\mathrm{alg}}(\sB(M))$, which does not quite fit our setting.
However,  the $C^*$-algebraic coarse index may be defined by the formula
\[
\ind(D) := [w(D)]\in K_1^{\mathrm{top}}(C^*(M)),
\]
for any function $w:\R\to\C^\times$ with $w-1\in C_0(\R)$ and winding number one (of course, any choice of $w$ yields the same $K$-theory class).
Choosing $w$ with compactly supported Fourier transform, the operator $w(D)$ actually defines an invertible element in $\sB(M)^+$ \cite[Prop.~3.6]{Roe-topology}, \cite[Lemma~4.30]{Roe-cohom}, and hence defines a class $\ind_{\mathrm{fp}}(D)$ in $K_1^{\mathrm{alg}}(\sB(M))$ that gets sent to $\ind(D)$ under the comparison map.
This shows that the relevant map maps onto $\Z$ in the odd case as well.
%
\begin{comment}
This is always possible: Take an arbitary function $\tilde{w}$ with winding number $\tilde{w} - 1 \in C_0(\R)$. 
	Now, any function in $C_0(\R)$ may be approximated arbitrarily well by functions with compactly supported Fourier transform. 
	If $f$ is such an approximation of $w-1$, then $w := f+1$ has winding number one if it is close enough. 
	Moreover, since $1$ has compactly supported Fourier transform (it is a multiple of the delta function), so has $w$. 
\end{comment}
%
\end{proof}

\begin{remark}\label{RemarkTranslationInvariantVanish}
The class $\ind_{\mathrm{fp}}(D)\in K^{\mathrm{alg}}_0(\sB(M))$ constructed in \cite{Roe-cohom} is represented by idempotents in $M_2(\sB(M)^+)$, with $\sB(M)^+$ the unitization of $\sB(M)$. 
So the non-trivial Kitaev/Kubo pairings there are achieved with the help of the unitization. One might ask the question: if $P=P^2\in M_k(\sB(M))$, is it possible that $P$ has non-trivial Kubo/Kitaev pairings? 
For $M=\Z^d$, it is easy to see that this is impossible if $P$ is translation invariant.
We take the $M$-module $\cH = \ell^2(\Z^d)\otimes \C^N$ and let $P$ be an idempotent in the $\Z^d$-invariant subalgebra
\[
\sB(\Z^d)^{\Z^d}\cong \C[\Z^d]\otimes M_N(\C).
\]
Here, $\C[\Z^d]$ denotes the group ring of $\Z^d$, or equivalently, the ring of Laurent polynomials in $d$ variables over $\C$,
\[
\C[\Z^d]=\C[z_1^{\pm},\ldots,z_d^{\pm}].
\]
So $P$ represents a class $[P]\in K^{\mathrm{alg}}_0(\sB(\Z^d)^{\Z^d}) = K^{\mathrm{alg}}_0(\C[z_1^{\pm},\ldots,z_d^{\pm}])$. 
Consider the ring homomorphism
\[
\C[\Z^d] \cong \C[z_1^{\pm}, \dots, z_d^{\pm}] \longrightarrow \C
\]
given by sending each generator $z_i^{\pm}$ to $1 \in \C$.
Observe that the element $P_0 := 1 \otimes e \in \C[\Z^d] \otimes M_N(\C)$, where $e$ is a rank one projection, defines a class in $K_0^{\mathrm{alg}}(\C[\Z^d])$, which is sent to a generator of $K_0^{\mathrm{alg}}(\C) \cong \Z$ under the above map.
On the other hand, it is a standard result that the above map induces an isomorphism on $K_0^{\mathrm{alg}}$ \cite[Corollary 3.2.13]{RosenbergK}, hence $P_0$ is also a generator for $K^{\mathrm{alg}}_0(\C[\Z^d])$. 
We conclude that $[P] = n \cdot [P_0]$ for some $n \in \Z$ and this relation continues to hold in $K^{\mathrm{alg}}_0(\sB(\Z^d))$.
However, $P_0$ has zero propagation, so $P_0A=AP_0A$ for any subset $A\subseteq M$, and consequently, the Kitaev pairings for $P_0$ are trivial.
\begin{comment}
\begin{align*}
\big[P_0;A_0,\ldots,A_{2m}]
&=\Tr\sum_{\sigma\in S_{2m+1}}\mathrm{sgn}(\sigma)\cdot A_{\sigma_0}P_0A_{\sigma_1}P_0\cdots A_{\sigma_{2m}}P_0\\
&=\Tr\sum_{\sigma\in S_{2m+1}}\mathrm{sgn}(\sigma)\cdot \underbrace{A_{\sigma_0}A_{\sigma_1}}_{=0}P_0A_{\sigma_1}P_0\cdots A_{\sigma_{2m}}P_0=0.
\end{align*}
\end{comment}
As Kitaev pairings depend only on $K_0$ classes, it follows that all Kitaev pairings of $P$ must also be trivial.


We mention that similar arguments employing $K^{\mathrm{alg}}_0$ of Laurent polynomial rings were made in \cite{CMST} to show the impossibility of flat and topologically non-trivial energy bands in periodic tight-binding models with strictly finite hopping range.
\end{remark}
