%%%%%%%%%%%%% UNNEEDED DISJOINTIFYING LEMMA FOR PARTITIONS %%%%%%%%%%%%%


\begin{lemma}\label{LemHonestPartition}
Let $A_0,\ldots,A_n$ be a coarsely transverse partition of $M$. Then there exists a coarsely transverse partition $A^\prime_0,\ldots, A^\prime_n$ of $M$ comprising disjoint Borel subsets, such that
\[
[A_0\wedge\dots \wedge A_n]=[A^\prime_0\wedge\dots \wedge A^\prime_n]\in HX^n(M).
\]
\end{lemma}
\begin{proof}
For each $i=0,\ldots,n$, the function $A_i$ has value $1$ on $A_i$ except on the intersections $A_i\capA_j, j\neq i$. We shall modify $A_i$ only on these intersections. Such modifications do not expand supports, so the coarse transversality condition will be maintained.

First, fix any $i,j$ with $0\leq i<j \leq n$, and write
\[
B_{ij}:=\supp\,A_i\cap \supp\,A_j\setminus \bigcup_{k\neq i,j}\supp\,A_k,\qquad i<j.
\]
for the corresponding strictly double overlap. Set
\[
A^\prime_i(x)=\begin{cases} 1, & x\in B_{ij},\\
A_i(x), & x\not\in B_{ij},\end{cases}\qquad
A^\prime_j(x)=\begin{cases} 0, & x\in B_{ij},\\
A_j(x), & x\not\in B_{ij},\end{cases}
\]
and $A^\prime_k=A_k$ if $k\neq i,j$. Then we get a modified coarsely transverse partition
\begin{align*}
A^\prime_i&=A_i+W,\\
A^\prime_j&=A_j-W,\\
A^\prime_k&=A_k,\qquad\quad k\neq i,j,
\end{align*}
where $W$ is some function with $W\subseteq B_{ij}$. Then we have the following coarse $n$-cocycle,
\begin{equation}
\begin{aligned}
&A^\prime_0\wedge \dots \wedge A^\prime_n- A_0\wedge \dots\wedge A_n\\
&\quad= A_0\wedge\dots \wedge A_{i-1}\wedge (\underbrace{A^\prime_i-A_i}_{=W}) \wedge A_{i+1}\wedge \dots \wedge A_{j-1}\wedge \mathbf{1} \wedge A_{j+1}\wedge\dots\wedge A_n,
\end{aligned}\label{CobordismDifference}
\end{equation}
where we used lemma \ref{LemDisjointAScoboundary} to replace the $j$-wedge factors by $\mathbf{1}$. Note that $W_R\subseteq B_{ij}_R\subseteq A_i_R\cap A_j_R$ for all $R>0$, thus
\[
A_0,\ldots, A_{i-1}, W, A_{i+1}, \ldots, A_{j-1}, A_{j+1},\ldots, A_n
\]
are coarsely transverse. So the difference in \eqref{CobordismDifference} is actually the coboundary of a \emph{coarse} $(n-1)$-cochain, and therefore
$[A_0\wedge\dots \wedge A_n]=[A^\prime_0\wedge\dots \wedge A^\prime_n]$ holds in $HX^n(M)$. After carrying out the above modification for all strictly double overlaps, we obtain an partition without any strictly double overlaps in supports. For convenience, we drop the primes and call this updated partition $A_0,\ldots,A_n$.

Next, fix any $i,j,k$ such that $0\leq i<j<k \leq n$, and write
\[
B_{ijk}:=\supp\,A_i\cap \supp\,A_j\cap \supp\,A_k \setminus \bigcup_{l\neq i,j,k}\supp\,A_l,\qquad i<j<k
\]
for the associated strictly triple overlap. 
Set
\[
A^\prime_i(x)=\begin{cases} 1, & x\in B_{ijk},\\
A_i(x), & x\not\in B_{ijk},\end{cases}\qquad
A^\prime_j(x)=\begin{cases} 0, & x\in B_{ijk},\\
A_j(x), & x\not\in B_{ijk},\end{cases}\qquad
A^\prime_k(x)=\begin{cases} 0, & x\in B_{ijk},\\
A_k(x), & x\not\in B_{ijk},\end{cases}
\]
and $A^\prime_l=A_l$ if $l\neq i,j,k$. Then
\begin{align*}
A^\prime_i &= A_i+W_j+W_k\\
A^\prime_j &= A_j-W_j\\
A^\prime_k &= A_k-W_k\\
A^\prime_l &= A_l,\qquad\qquad\quad l\neq i,j,k,
\end{align*}
where $W_j,W_k$ are some functions supported in $B_{ijk}$. Then, as in \eqref{CobordismDifference}, we have
\begin{equation*}
\begin{aligned}
&A^\prime_0\wedge \dots \wedge A^\prime_n- A_0\wedge \dots\wedge A_n\\
&\quad= A_0\wedge\dots \wedge A_{i-1}\wedge (W_j+W_k) \wedge A_{i+1}\wedge \dots\\
&\qquad\qquad \wedge A_{j-1}\wedge (-W_j) \wedge A_{j+1}\wedge\dots \wedge A_{k-1}\wedge \mathbf{1}\wedge A_{k+1}\wedge\dots \wedge A_n
\end{aligned}
\end{equation*}
being the coboundary of a coarse $(n-1)$-cochain, thus $[A_0\wedge\dots \wedge A_n]=[A^\prime_0\wedge\dots \wedge A^\prime_n]$ holds in $HX^n(M)$. After carrying out the above modification for all strictly triple overlaps, we obtain an partition with no strictly double or triple overlaps.

In a similar way, continue the above reassignment procedure for quadruple overlaps, etc., finally arriving at an partition $A^\prime_0,\ldots,A^\prime_n$ with no overlap of supports at all, and which satisfies $[A^\prime_0\wedge\dots \wedge A^\prime_n]=[A_0\wedge\dots\wedge A_n]$ is satisfied.
\end{proof}

