\noindent For any affine component of type $A, D$ or $E$,  all roots are all taken of square length $2$; see Appendix \ref{AppendixB}. 

\hip 
Every vector $e_j^i$, for $i=1,\ldots,m, j=1,\ldots r_{i+1}$, 
 can be interpreted as  a spacelike vector normal to a  hyperplane, denoted by  $H_{e_j^i}$,  that passes through $v_{\infty}$.  
 The vertex $v_{\infty}$ appears therefore as the apex of a polyhedral cone $C_{\infty}\subset \mathbb H^n$ over a product of several simplices, each of dimension $\geq 2$, formed by the intersection of the  hyperplanes 
\[
 \{ H_{e_j^i} \  \mid    \  1\leq i \leq m \ ,  \ 1\leq j \leq r_i+1 \   \} \ . 
\] 
The cone $C_{\infty}$ has {\it infinite} volume in $\mathbb H^n$ and has to be truncated by additional hyperplanes  
 not passing through $v_{\infty}$  in order to yield the finite-volume polyhedron  $P\subset \mathbb H^n$. 

\hip 
The first additional hyperplane(s) that we will detect belong to the boundary of the $G_2$-face $F$ described above. 
This set will be completed by additional hyperplanes subject to an admissibility condition,  inspired from the work of Nikulin \cite{Nikulin2} and  Prokhorov \cite{Prk}; see 
 Definition \ref{admissible}.  We provide the technical details below.  

\hip 
Observe that $P$ is a pyramid with apex $v_{\infty}$ if and only if the boundary of $P$ is obtained by adding a {\it unique} additional hyperplane to the set of hyperplanes $\{H_{e_j^i}\}_{i,j}$. 
As all pyramids are classified (see \cite{Tum3} and \cite{Mcleod}), we discuss in what follows the case where $P$ is not a pyramid. 
Note however that we will recover all ADEG-pyramid through our method; see item 4.i. of Section \ref{Section4.1.4}. 
Therefore, we assume next that the set $\{H_{e_j^i}\}_{i,j}$ 
has to be completed  by at least two additional hyperplanes that do not pass through the vertex $v_{\infty}$.   


\hip
As $v_{\infty}$ is Lorentz-orthogonal to all vectors $e_j^i$, and it can be expressed in terms of certain lightlike vectors $v_{\infty}^i$ related to the affine components  $\sigma_i$ for $i=1,\dots m$ as follows. 

\begin{lemma}
For each $1 \leq i \leq m$,   there exist positive integers $c^i_1,\dots, c^i_{r_i+1}$ with $c^i_{r_i+1}=1$ such that the vector $v_{\infty}^i:=c_1^ie_1^i+\dots + c_{r_i+1}^i e_{r_i+1}^i \in \mathbb R^{n,1}$ is collinear with  $v_{\infty}$.  
\label{vi}
\end{lemma}

\begin{proof}
Let $c^i_1,\dots,c^i_{r_i}\in \mathbb Z$  be the integers such that 
\begin{equation}
-e_{r_i+1}^i  = c_1^ie_1^i+\ldots+ c_{r_i}^i e_{r_i}^i \ \in \mathbb R^{r_i} \ ;
\label{ci}
\end{equation}
see Appendix  \ref{AppendixB} for their explicit form.    
The vector $v_{\infty}^i=c_1^ie_1^i+\ldots + c_{r_i}^i e_{r_i}^i + e_{r_i+1}^i$ (suitably extended to a non-zero vector in  $\mathbb R^{n,1}$) satisfies  $\langle v_{\infty}^i, v_{\infty}^i \rangle=0$ by properties of the highest root. 
 In addition,  $\langle v_{\infty}^i, v_{\infty} \rangle=0$ as $\langle e_j^i,  v_{\infty}\rangle =0$ for all $j=1, \ldots, r_i+1$. 
As any two  Lorentz-orthogonal lightlike vectors are collinear, this finishes the proof. 
\end{proof}






\hip As a consequence of Lemma \ref{vi}, 
  the vectors $v_{\infty}$ and  $v_{\infty}^i$  
define the same lightlike ray, which we denote by  $ v_{\infty} \sim    v_{\infty}^i$. 
 In particular, for $i=1$, we derive that 
\begin{equation}
 v_{\infty} \sim v_{\infty}^1=3e_1^1+2e_2^1+e_3^1  \ ; 
 \label{v1}
 \end{equation}
see Appendix \ref{AppendixB.4}. 



\hop 

Assume that $H_x$ and $H_y$ are two  bounding hyperplanes of $P$  not passing through $v_{\infty}$. 
These hyperplanes are characterized by two spacelike normal vectors $x, y \in \mathbb R^{n,1}$  such that  
 $\langle x,v_{\infty} \rangle \neq 0$ and $\langle y ,v_{\infty}\rangle \neq 0$.   
In this setting, the Lorentzian product $\langle x,y \rangle$ can be expressed in terms  of the Lorentzian products  $k_j^i:=\langle x, e_j^i \rangle$ and $ l_j^i:= \langle y,  e_j^i \rangle$  with the vectors $e_j^i$ for $i=1,\dots,m$, $j=1,\dots,r_i+1$; see \cite{Prk}.  

\hip 
We consider  $x$ and $y$ of squared  norm $2$, and encode them by the following strings
\begin{equation}
\begin{split}
x&\leftrightarrow (k_1^1,k_2^1,k_3^1; k_1^2,\ldots, k_{r_2+1}^2;\dots;k_1^m, \dots, k_{r_m+1}^m ) \\
y&\leftrightarrow (l_1^1, l_2^1, l_{3}^1;l_1^2,\dots ,  l_{r_2+1}^2 ; \dots; l_1^m, \dots, l_{r_m+1}^m)   
\end{split} 
\label{strings}
\end{equation}
where $k_j^i=\langle x, e_j^i \rangle$  and $l_j^i=\langle y, e_j^i \rangle$ for $i=1,\ldots, m$ and $j=1,\ldots,r_i+1$.    


\hop 
Since the dihedral angles $\measuredangle (H_x, H_{e_j^i})$  all vary within the set $\{\frac{\pi}{2}, \frac{\pi}{3}, \frac{\pi}{6}\}$,  the quantities  $k_j^i=\langle x, e_j^i \rangle$  are as follows.  
Similar expressions hold for $l_j^i=\langle y, e_j^i \rangle$.    


\begin{equation}
\langle x, e_j^i \rangle = \left\{ 
\begin{array}{ll}
0 & \text{ if } \measuredangle (H_x,  H_{e_j^i}) = \frac{\pi}{2}\\ 
-1 & \text{ if } \measuredangle (H_x,  H_{e_j^i}) = \frac{\pi}{3} \text{ and } ||e_j^i||^2=2\\ 
-\sqrt 3  & \text{ if } \measuredangle ( H_x,  H_{e_j^i}) = \frac{\pi}{6} \text{ and } ||e_j^i||^2=2\\ 
-\sqrt 3  & \text{ if } \measuredangle (H_x,  H_{e_j^i}) = \frac{\pi}{3} \text{ and } ||e_j^i||^2=6\\ 
-3  & \text{ if } \measuredangle ( H_x,  H_{e_j^i}) = \frac{\pi}{6} \text{ and } ||e_j^i||^2=6\\  
\end{array}
\right.  
\label{length}
\end{equation}



\hop Consider  the quantities $\Lambda$ and $\Lambda_i$ for $1\leq i \leq m$ defined as follows
\[
\Lambda= \Lambda_{xy} := \frac{\langle x,v_{\infty}\rangle}{\langle y,v_{\infty}\rangle} \ \text{ and } \ \Lambda_i := 
\frac{\langle x, v_{\infty}^i \rangle}{\langle y, v_{\infty}^i \rangle}=\frac{\langle x, \sum_{k=1}^{r_i+1} c_k^ie_k^i\rangle }{\langle y, \sum_{k=1}^{r_i+1} c_k^ie_k^i\rangle } \ , 
\] 
where the lightlike vectors $v_{\infty}^i$ are defined in Lemma \ref{vi}; see also  \cite{Prk}.  
In particular, in view of  the fact that $\sigma_1=\widetilde G_2$, one has  
\begin{equation}
\Lambda_1  =  \frac{3k_1^1+2k_2^1+k_3^1}{3l_1^1+2l_2^1+l_3^1} \ . 
\label{req1}
\end{equation}


\hip 
From  Lemma \ref{vi}, one immediately deduces that     
\begin{equation}
\Lambda_i =\Lambda \ \text{ for all }  i=1,\ldots,m \ . 
\label{lambda}
\end{equation}

\noindent
We are now able to write down Prokhorov's formula \cite{Prk} for the Lorentzian product $\langle x, y \rangle$.  Note that the signs are changed according to our setting. 


\begin{lemma}[Prokhorov \cite{Prk}]
\begin{equation}
\langle x , y\rangle =\frac{\langle x,x \rangle}{2\Lambda} +\frac{\langle y,y \rangle}{2}\Lambda  - (\Delta_1+\ldots+\Delta_m) \ ,
\label{xy}
\end{equation}
where, 
 for $p\in \{1, \ldots, m\}$,  
\begin{equation}
\Delta_p = \sum\limits_{1\leq i<j\leq r_p+1}(k_i^pl_j^p+k_j^pl_i^p-\frac{k_i^pk_j^p}{\Lambda} - l_i^pl_j^p\Lambda) s_{ij}^p \ . 
\label{Delta}
\end{equation} 
\noindent
The quantities $s_{ij}^p$  in \eqref{Delta} depend on the fundamental weights $w_1,\dots,w_{r_p}$  of the root system $R_p$ as follows

 \begin{equation}\hspace{-1em}\left\{\begin{array}{lll}s_{ij}^p=&\langle w_i,w_j\rangle-\dfrac{\langle  w_i,w_i\rangle c_j^p}{2c_i^p} - \dfrac{\langle w_j,w_j\rangle c_i^p}{2c_j^p} \quad &\text{ for } 1\leq i, j\leq r_p \ ,  \\  s_{ir_p}^p=&\dfrac{\langle  w_i,w_i\rangle}{2c_i^p}  \quad &\text{ for } i=1, \dots, r_p \ , \\s_{ii}^p =&0  \quad &\text{ for } i=1, \dots, r_p+1 \ ,  \end{array}\right.
 \label{sisj}\end{equation} 
where 
 $c_j^p$ are the integers according to \eqref{ci}. 
\label{Prkformula}
\end{lemma}

\hop  The quantities $s_{ij}=s_{ij}^p$   defined in \eqref{sisj}  
