\noindent 
The fundamental weights of $A_n$ are given by 
\[
w_i=\epsilon_1+\ldots+\epsilon_i-\frac{i}{n+1}\sum_{j=1}^{n+1}\epsilon_j  \ \text{ for } \ 1\leq i \leq n \ . 
\]


\hip 
In view of \eqref{sisj}, the quantities $s_{ij}$ involved in Lemma \ref{thmPrk} for a component of  type $\widetilde A_n$ are given by 
\[
s_{ij}= \frac{(j-i)(n+1-(j-i))}{2(n+1)} \ . 
\]

\hip 
Note that for the proof of Theorem \ref{thmN9}, these quantities are needed  for $n\leq 8$ only.  



\hip 


\subsection{The root system $ D_n$} 

Let $V=\mathbb R^n$.  
The  $D_n$-root system is the set of vectors in $V$ of length $\sqrt2$ with integer coordinates given by 
 \[
\mathcal D_n=\{ \epsilon_i-\epsilon_j \mid 1\leq i \neq j \leq n\}\cup \{ \pm(\epsilon_i+\epsilon_j)  \mid 1 \leq i<j\leq n \}\ . 
\]
The natural simple roots are given by $\alpha_1=\epsilon_1-\epsilon_2,  \dots,  \alpha_{n-1}=\epsilon_{n-1}-\epsilon_{n} \ , \ \alpha_{n}$,
%=\epsilon_{n-1}+\epsilon_{n}$
and the  highest root  satisfies  
$
\overline{\alpha}=\alpha_1+2\alpha_2+\ldots+2\alpha_{n-2}+\alpha_{n-1}+\alpha_n = \epsilon_1+ \epsilon_2 \ 
$. 

