\title{\textbf{Classification of Extremal Dependence in Financial Markets via Bootstrap Inference}}
\author[1]{Qian Hui}
\author[2]{Sidney I. Resnick}
\author[1,3]{Tiandong Wang \thanks{Corresponding author, \href{mailto:td_wang@fudan.edu.cn}{td\underline{ }wang@fudan.edu.cn}.}}
