\caption{Overview of the proposed testing procedure.}\label{fig:test}
\end{figure}

{We \sid{describe} the classification procedure in the following series of
steps which are summarized as a flow chart 
in Figure \ref{fig:test}  and as an algorithm in Algorithm \ref{alg:test}.
Decision steps are as follows:}
\begin{enumerate}
\item[\emph{Step 1.}] For a given sample size $n$, choose
  $k=k(n)\sid{\to \infty}$
  such that $k(n)/n\to 0$, and use the 
            $k(n)$ largest observations for estimates. The bootstrap
            sample size is taken as $m=m(n)\sid{=o(n)}$ following
            \cite{athreya:1987b, gine:zinn:1989, feigin:resnick:1997, {resnickbook:2007}}.
            Also, draw $B$ bootstrap samples of size $m$ from the original
            sample. \sid{These samples are taken independently since they result from multinomial sampling.     }
\item[\emph{Step 2.}] \sid{Using} the original sample, estimate the
              parameter vector $(\alpha, a,b)$. \sid{For $\alpha$ use
                the
    Hill estimator} and $(\hat a,\hat b)$ are \sid{consistently}
    estimated by
    $$(\hat a,\hat b):=\arg\min_{0<a\leq b\leq 1}\Bigl\{(b-a) +
    \lambda \sqrt{k(n)}
    \left\vert D_n - 1/\hat{\alpha}\right\vert \Bigr\},$$
          \sid{\citep[Theorem~5.1]{wang:resnick:2025} where $\lambda>0$
              is a tuning parameter.} When $\lambda$ is large, the
            optimization \sid{penalizes distance to the cone
            and hence tends to } favor a wide estimated interval; we choose $\lambda=4$ in this study.

\item[\emph{Step 3.}]   For a bootstrap
                sample of size $m$, $\{(\Theta_i^\boot, R_i^\boot):1\le i\le m\}$, we write
                \[
                D_m^\boot = \frac{1}{k(m)}\sum_{i=1}^{k(m)}\left(1+\frac{d\bigl(\bZ_i^{*\boot}, \mathbb{C}_{\hat{a},\hat{b}}\bigr)}{R^\boot_{(k(m))}}\right)\log\frac{R^\boot_{(i)}}{R^\boot_{(k(m))}},\qquad 
                T_m^\boot = \frac{\sum_{i=1}^{k(m)}\Theta_i^{*\boot}\log\frac{R^\boot_{(i)}}{R^\boot_{(k(m))}}}{\sum_{i=1}^{k(m)}\Theta_i^{*\boot}}.
                \]
               When there
                are $B$ bootstrap samples we write $D_m^{i,\boot},\,T_m^{i,\boot}$,
                $i=1,\dots, B$.
\item[\emph{Step 4.}] Start by testing the existence of strong dependence: 
$$    H^{(1)}_0:\, S([{\hat a},{\hat b}]) = 1 \text{ vs } H^{(1)}_a:\,
S([{\hat a},{\hat b}])<1,$$
using the simple statistics $D_m^{i,\boot}$,                $i=1,\dots,
B$ and reject if
$$
\left\vert {D}_{m}^{i,\boot}-1/\hat{\alpha}\right\vert > 1.96
\frac{1/\hat{\alpha}}{\sqrt{k(m)}}, \; i=1,\dots,B
$$
is true for at least $5\%$ of the bootstrap samples.
\item[\emph{Step 5.}] Failure to reject $H_0^{(1)}$ 
may be due to $S(\cdot)$ concentrating at \emph{some} single point,
%$\theta \in [\hat a,\hat b]$ 
so we then test for full dependence
$$H^{(2)}_0:\, \text{$\text{supp}(S)$ is a single point}\quad \text{ vs }\quad H^{(2)}_a:
  \text{$\text{supp}(S)$ is not a single point},$$
using $T_m^{i,\boot}, i=1,\dots,m$.
%Since the asymptotic variance of $T_n$ is minimal when full dependence is present, we 
Reject
$H^{(2)}_0$ if the bootstrap samples show excessive variability:
\[
k(m)\frac{ \frac{1}{B-1}\sum_{i=1}^B
   \left(T_{m}^{i,\boot}-\bar{T}_{m}^\boot\right)^2}{1/\hat{\alpha}^2} > \chi^2_{0.95, B-1}/(B-1), 
\]
where $\chi^2_{0.95, B-1}$ denotes the 95\% quantile of a chi-square
distribution with $B-1$ degrees of freedom and $\bar T_m^\boot$ is the
mean of $\{T_m^{i,\boot}, i=1,\dots,m\}$.
\item[\emph{Step 6.}] If $H^{(1)}_0$ is rejected, we further test for asymptotic independence vs weak dependence:
$$H^{(3)}_0: S(\{0,1\}) =1 \quad \text{ vs }\quad
 H^{(3)}_a:  \text{supp}(S) = [0,1],$$
by considering the transformed data $\{(r_i,g(\theta_i)), 1\leq i\leq
n\} $. \sid{If asymptotic independence is present, the transformed
  data possess full dependence, and apply the modified T-statistic}
              \[
              T_{m}^{\boot}(g) := \frac{\sum_{i=1}^{k(m)} g(\Theta^{*\boot}_i) \log\frac{R^\boot_{(i)}}{R^\boot_{(k(m))}}}{\sum_{i=1}^{k(m)} g(\Theta^{*\boot}_i)},
              \]
              Reject $H^{(3)}_0$ if 
\[
k(m)\frac{ \frac{1}{B-1}\sum_{i=1}^B
   \left(T_{m}^{i,\boot}(g)-\bar{T}_{m}^\boot(g)\right)^2}{1/\hat{\alpha}^2} > \chi^2_{0.95, B-1}/(B-1). 
\]           
\end{enumerate}

A schematic summary of the testing procedure is given in Algorithm~\ref{alg:test}.

\begin{algorithm}
  \caption{Testing procedure.}
    \label{alg:test}
	\begin{algorithmic}[1]
	    \Require Estimate $\alpha$, $a$ and $b$ from the original sample, denoted as $\hat{\alpha}$, $\hat{a}$ and $\hat{b}$.
		\State Test $H_0^{(1)}: S([\hat{a},\hat{b}]) = 1$ vs $H_a^{(1)}: S([\hat{a},\hat{b}]) < 1$, using ${D}^\text{boot}_m$.
			\If {Accept $H_0^{(1)}$}
				\State Test $H_0^{(2)}:
                                \text{$\text{supp}(S)$ is a single point}$ vs
                                $H_a^{(2)}: \text{$\text{supp}(S)$ is not a single point}$ using
                                ${T}^\text{boot}_m$. 
					\If {Accept $H_0^{(2)}$}
					\State The random vector $\bZ$ exhibits asymptotic full dependence.
					\Else
					\State The random vector $\bZ$ exhibits asymptotic strong dependence.
					\EndIf
			\ElsIf {Reject $H_0^{(1)}$}
                        \State %{
                        Test $H_0^{(3)}:
                                S(\{0,1\})=1$ vs
                                $H_a^{(3)}:  \text{supp}(S)=[0,1]$,
                                using ${T}^\text{boot}_m(g)$, the
                                modified bootstrap statistic resulting
                                from $\theta\mapsto g(\theta)$.
					\If {Accept $H_0^{(3)}$}
					\State The random vector $\bZ$
                                        exhibits asymptotic
                                        independence. 
					\Else
					\State The random vector $\bZ$ exhibits asymptotic weak dependence.
					\EndIf%}
			\EndIf
	\end{algorithmic} 
\end{algorithm}

