\subsection{Conjugacy classes of $G=O(3)\times S_4$}
In order to describe the conjugacy classes of subgroups in $O(3)\times S_{4}$,
we use a special convention that allows us to describe the subgroups of a
product group $G_1\times G_{2}$ (i.e. here $G_1=O(3)$ and $G_{2}=S_{4}$).
For two groups $G_1$ and $G_{2}$, the well-known result of \'{E}. Goursat
(see \cite{Goursat}) provides the following description of arbitrary subgroup
$\mathscr H\leq G_1\times G_{2}$; namely there exist subgroups $H\leq G_1$
and $K\leq G_{2}$, a group $L$, and two epimorphisms $\varphi:H\rightarrow L$
and $\psi:K\rightarrow L$ such that
\[
\mathscr H=\{(h,k)\in H\times K:\varphi(h)=\psi(k)\}.
\]
The notation used to describe $\mathscr H$ is
\begin{equation}
H\prescript{\varphi}{}\times_{L}^{\psi}K,
\label{eq:amalgam-projections}%
\end{equation}
in which case $H\prescript{\varphi}{}\times_{L}^{\psi}K$ is called an
\textit{amalgamated} subgroup of $G_1\times G_{2}$. \vs
The conjugacy classes of  $H{^\varphi\times_L^\psi}K\le G_1\times G_2$ are described in the following theorem (see Theorem E.6 in \cite{newBook}):
\begin{theorem}\label{th:conjugate_amalgamate}
  Let $L$ be a fixed group, $H,\,H'\subset G_1$, $K,\,K'\subset G_2$
  be subgroups and assume that $\varphi:H\to L$, $\varphi':H'\to L$ and
  $\psi:K\to L$, $\psi':K'\to L$ are epimorphisms.
  Then, two amalgamated subgroups $H{^\varphi\times_L^\psi}K$
  and $H'{^{\varphi'}\times_L^{\psi'}}K'$ are conjugate
  if and only if there exist $(a,b)\in G_1\times G_2$ and
$\gamma\in\mathrm{Aut}(L)$ (here {\rm Aut}$(L)$ stands for the group of automorphisms of $L$) such that
  $H'=aHa^{-1}$, $K'=bKb^{-1}$ and for all $h\in H$ and $k\in K$, we have
\begin{equation}\label{eq:con-new} \gamma(\varphi'(a^{-1}ha))=\varphi(h)\quad\mbox{and}\quad \gamma(\psi'(b^{-1}kb))=\psi(k).
  \end{equation}
\end{theorem}
To simplify the amalgamated notation, %$H{^\varphi\times_L^\psi}K$
we simply write
\[
\mathscr H:=H{^{H_o}\times_L^{K_o}}K,
\]where $H_o:=\ker(\vp)$ and $K_o:=\ker(\psi)$. However, if there exists more than one pair $(\vp,\psi)$ of such homomorphisms, which are not conjugate, then we may also write $(H{^{H_o}\times_L^{K_o}}K)_1$ and $(H{^{H_o}\times_L^{K_o}}K)_2$ to indicate their (different) conjugacy classes.


\begin{remark}
Let us emphasize that in the case of $S_4^p,$ the product and twisted subgroups
can be also described as the amalgamated subgroups. However, for the
convenience of notation, in this case we use the abbreviated notation of
twisted subgroups. Moreover, the amalgamated subgroup $\mathscr H$ can be written as $H^{H_o}\times _L{K}$ if $K_o=\mathbb{Z}_1$ or $H^{H_o}\times ^{K_o}{K}$ if $L=\mathbb{Z}_2.$
\end{remark}
\section{Euler and Burnside Rings}\label{app:Eulerring}

\noindent\textbf{Euler Characteristic:} For a topological space $Y$, denote by
$H_{c}^{\ast}(Y)$ the ring of Alexander-Spanier cohomology with compact
support (see \cite{Spa}). If $H_{c}^{\ast}(Y)$ is finitely generated, then the
Euler characteristic $\chi_{c}(Y)$ is well defined. For a compact CW-complex
$X$ and its closed subcomplex $A$, as it is very well-known $H_{c}^{\ast
}(X\setminus A)\cong H^{\ast}(X,A;\mathbb{R})$, where $H^{\ast}(\cdot)$ stands
for a usual cellular cohomology ring (see \cite{Spa}, Ch.~6, Sect.~6, Lemma
11). Therefore, $\chi_{c}(X\setminus A)$ is correctly defined and
\[
\chi(X)=\chi_{c}(X\setminus A)+\chi(A)=\chi(X,A)+\chi(A).
\]
where $\chi(\cdot)$ stands for the Euler characteristic with respect to the
cellular cohomology groups. Moreover, if $Y$ is a compact $CW$-complex,
$B\subseteq Y$ is a closed subcomplex and $p:X\setminus A\rightarrow
Y\setminus B$ a locally trivial fibre bundle with path-connected base and
fibre $F$ is a compact manifold, then (cf. \cite{Spa}, Ch. 9, Sect. 3, Theorem
1)
\[
\chi_{c}(X\setminus A)=\chi(F)\chi_{c}(Y\setminus B).
\]


\vskip.3cm

\noindent\textbf{Euler and Burnside Rings\label{app:Euler}}

In this section we assume that $G$ stands for a compact Lie group and we
denote by $\Phi(G)$ the set of all conjugacy classes $(H)$ of closed subgroups
$H$ of $G$. For any $(H)\in\Phi(G)$ we denote by $N(H)$ the normalizer of $H$
and by $W(H):=N(H)/H$ the Weyl's group of $H$. \vskip.3cm

Notice that $\Phi(G)$ admits a natural order relation given by
\begin{equation}
\label{eq:order}(K)\le(H) \;\; \Leftrightarrow\;\; \exists_{g\in G}\; \;
gKg^{-1}\le H, \;\; \text{ for }\;\; (K),\,(H)\in\Phi(G).
\end{equation}
Moreover, we define for $n=0,1,2,\dots$ the following subsets $\Phi_{n}(G)$ of
$\Phi(G)$
\[
\Phi_{n}(G):=\{ (H)\in\Phi(G): \dim W(H)=n\}.
\]
\vskip.3cm Let us point out that for $(H)$, $(K)\in\Phi(G)$, if $(K)\le(H)$
then $\dim W(K)\ge\dim W(H)$ (see \cite{AED}). \vskip.3cm We denote by
$U(G)={\mathbb{Z}}[\Phi(G)]$ the free ${\mathbb{Z}}$-module generated by
symbols $\Phi(G)$, i.e. an element $a\in U(G)$ is represented as
\begin{equation}
\label{eq:sum-a}a=\sum_{(L)\in\Phi(G)} n_{L} \, (L), \quad n_{L}\in
{\mathbb{Z}},
\end{equation}
where the integers $n_{L}=0$ except for a finite number of elements
$(L)\in\Phi(G)$. For such element $a\in U(G)$ and $(H)\in\Phi(G)$, we will
also use the notation
\begin{equation}
\label{eq:coeff-H}\text{coeff}^{H}(a)=n_{H},
\end{equation}
i.e. $n_{H}$ is the coefficient in \eqref{eq:sum-a} standing by $(H)$. We also
put
\begin{equation}
\label{eq:Phi(a)}\Phi(a):=\{(H)\in\Phi(G): \text{coeff}^{H}(a)\not =0\}.
\end{equation}
Clearly, the set $\Phi(a)$ is finite and we denote by $\text{max}(a)$ the set
of all maximal (with respect to the order \eqref{eq:order}) elements in
$\Phi(a)$, i.e.
\begin{equation}
\label{eq:max-in-a}\max(a):=\{(H)\in\Phi(a): \;(H) \text{ is maximal in }%
\Phi(a)\}.
\end{equation}
We will sometimes write ${\max}^G(a)$ in order to indicate that the order relation is taken from $\Phi(G)$.
\vskip.3cm

\begin{definition}
\textrm{\label{def:EulerRing} (cf. \cite{tD}) Define the
\textit{multiplication} on $U(G)$ as follows: for generators $(H)$,
$(K)\in\Phi(G)$ put:
\begin{equation}
(H)\ast(K)=\sum_{(L)\in\Phi(G)}n_{L}(L),\label{eq:Euler-mult}%
\end{equation}
where
\begin{equation}
n_{L}:=\chi_{c}((G/H\times G/K)_{L}/N(L)),\label{eq:Euler-coeff}%
\end{equation}
($(G/H\times G/K)_{L}$ denotes the set of elements in $G/H\times G/K$ that are
fixed exactly by $L$, and the multiplication defined by Definition
\ref{def:EulerRing} is linearly extended to the multiplication on entire
$U(G)$. We call the free ${\mathbb{Z}}$-module $U(G)$ equipped with
multiplication (\ref{eq:Euler-mult}) the \textit{Euler ring} of the group $G$.
}
\end{definition}

\vskip.3cm It is easy to notice that $(G)$ is the unit element in $U(G)$, i.e.
$(G)*a=a$ for all $a\in U(G)$. \vskip.3cm

\begin{lemma}
\label{lem:inv-1} Assume that $a\in U(G)$ is an invertible element and
$(H)\in\Phi(G)$. Then
\[
\text{\text{\rm coeff}}^{H}((H)*a)\not =0.
\]

\end{lemma}

\begin{proof}
Suppose that
\[
a=\sum_{(L)\in\Phi(a)} n_{L} \, (L).
\]
Then
\[
(H)*a=\sum_{(K)\in\Phi((H)*a)} m_{K}\, (K), \text{ and formula
(\ref{eq:Euler-mult}) implies that} \;\; (H)\ge(K).
\]
Assume for contradiction that $(H)>(K)$ for all $(K)\in\Phi((H)*a)$. Then, by
exactly the same argument we have
\[
(H)*a*a^{-1}=\sum_{(L)\in\Phi((H)*a*a^{-1})} n_{L} \, (L), \quad\text{ where }
(H)>(L),
\]
which is a contradiction with the fact that
\[
(H)*a*a^{-1}=(H)*(G)=(H).
\]

\end{proof}

\vskip.3cm Lemma \ref{lem:inv-1} implies the following: \vskip.3cm

\begin{corollary}
\label{cor:inv} Let $a$, $b\in U(G)$ be such that $a$ is an invertible element
in $U(G)$ and $(H)\in\text{\textrm{max}}(b)$. Then $\text{\textrm{coeff}}%
^{H}(a*b)\not =0$.
\end{corollary}

\vskip.3cm Take $\Phi_{0}(G)=\{(H)\in\Phi(G):$ \textrm{dim\thinspace
}$W(H)=0\}$ and denote by $A(G)={\mathbb{Z}}[\Phi_{0}(G)]$ a free
${\mathbb{Z}}$-module with basis $\Phi_{0}(G).$ Define multiplication on
$A(G)$ by restricting multiplication from $U(G)$ to $A(G)$, i.e. for $(H)$,
$(K)\in\Phi_{0}(G)$ let
\begin{equation}
(H)\cdot(K)=\sum_{(L)}n_{L}(L),\qquad(H),(K),(L)\in\Phi_{0}(G),\text{ where}
\label{eq:multBurnside}%
\end{equation}
\begin{equation}
n_{L}=\chi((G/H\times G/K)_{L}/N(L))=|(G/H\times G/K)_{L}/N(L)|
\label{eq:CoeffBurnside}%
\end{equation}
($\chi$ here denotes the usual Euler characteristic). Then $A(G)$ with
multiplication \eqref{eq:multBurnside} becomes a ring which is called the
\textit{Burnside ring} of $G$. As it can be shown, the coefficients
\eqref{eq:CoeffBurnside} can be found (cf. \cite{AED}) using the following
recursive formula:
\begin{equation}
n_{L}=\frac{n(L,K)|W(K)|n(L,H)|W(H)|-\sum_{(\widetilde{L})>(L)}n(L,\widetilde
{L})n_{\widetilde{L}}|W(\widetilde{L})|}{|W(L)|}, \label{eq:rec-coef}%
\end{equation}
where $(H),$ $(K),$ $(L)$ and $(\widetilde{L})$ are taken from $\Phi_{0}
(G),$ and \begin{align*}
&
N_{G}(L,H)=\Big\{
g\in G:gLg^{-1} \subset H\Big\} , \\
&N_{G}(L,H)/H=\Big\{
Hg: g\in N_{G}(L,H)\Big\}\\
& n(L,H)=\Big|\frac{N(L,H)}{N(H)}\Big|
\end{align*}
\vskip.3cm Observe that although $A(G)$ is clearly a ${\mathbb{Z}}$-submodule
of $U(G)$, in general, it is \textbf{not} a subring of $U(G)$.

\vskip.3cm Define $\pi_{0}:U(G)\rightarrow A(G)$ as follows: for $(H)\in
\Phi(G)$ let
\begin{equation}
\pi_{0}((H))=
\begin{cases}
(H) & \text{ if }\;(H)\in\Phi_{0}(G),\\
0 & \text{ otherwise.}%
\end{cases}
\label{eq:pi_0-homomorphism}%
\end{equation}
The map $\pi_{0}$ defined by (\ref{eq:pi_0-homomorphism}) is a ring
homomorphism {(cf. \cite{BKR})}, i.e.
\[
\pi_{0}((H)\ast(K))=\pi_{0}((H))\cdot\pi_{0}((K)),\qquad(H),(K)\in\Phi(G).
\]
The following well-known result (cf. \cite{tD}, Proposition 1.14, page 231)
shows a difference between the generators $(H)$ of $U(G)$ and $A(G)$.

\begin{proposition}
\label{pro:nilp-elements} Let $(H)\in\Phi_{n}(G)$.

\begin{itemize}
\item[(i)] If $n>0$, then $(H)^{k}=0$ in $U(G)$ for some $k\in\mathbb{N}$,
i.e. $(H)$ is a nilpotent element in $U(G)$;

\item[(ii)] If $n=0$, then $(H)^{k}\not =0$ for all $k\in{\mathbb{N}}$.
\end{itemize}
\end{proposition}
\begin{corollary}
    If $\alpha=n_1(L_1)+n_2(L_2)+\cdots +n_k(L_k),$ where $\dim W(L_j)\ge 0,$ then there exists $n\in \mathbb N$ s.t. $\alpha^n=0.$
\end{corollary}
\begin{proof}
    By induction w.r.t. $k\in \mathbb N$, clearly for $k=1,$ it is exactly the statement of proposition\eqref{pro:nilp-elements}. Suppose that the statement is true for $k\geq 1,$ and will show that it is also true for $k+1.$ Indeed, we have
    \[
\alpha^1=n_1(L_1)+n_2(L_2)+\cdots n_k(L_k)+n_{k+1}(L_{k+1})
    =\alpha+n_{k+1}(L_{k+1}),
    \]
so \[
\alpha^m=\sum_{l=0}^{m}C_m^l \alpha^l n_k^{m-l}(L_{k+1})^{m-l}.
\]
Let $k$ be given by Proposition \eqref{pro:nilp-elements}, for $L:=l_{k+1},$ then for $m\ge n+k,$ one has
\[
\alpha^l (L)^{m-l}=0
\]
    \end{proof}
\vskip.3cm \noindent\textbf{Euler Ring Homomorphism:} Let $\psi:{G^{\prime}
}\rightarrow G$ be a homomorphism of compact Lie groups. Then, ${G^{\prime}} $
acts on the left on $G$ by ${g^{\prime}}x:=\psi({g^{\prime}})x$ (a similarly
