\section{Properties of $G$-Equivariant Gradient Degree}

\label{app:gradient}

In what follows, we assume that $G$ is a compact Lie group.

\subsection{Brouwer $G$-Equivariant Degree}

Assume that $V$ is an orthogonal $G$-representation and $\Omega\subset V$ an
open bounded $G$-invariant set. A $G$-equivariant (continuous) map $f:V\to V$
is called \textit{$\Omega$-admissible} if $f(x)\neq0$ for any $x\in
\partial\Omega$; in such a case, the pair $(f,\Omega)$ is called
\textit{$G$-admissible}. Denote by $\mathcal{M}^{G}(V,V)$ the set of all such
admissible $G$-pairs, and put $\mathcal{M}^{G}:=\bigcup_{V}\mathcal{M}
^{G}(V,V)$, where the union is taken for all orthogonal $G$-representations
$V$. We have the following result (see \cite{AED}):

\begin{theorem}
\label{thm:GpropDeg} There exists a unique map $G$-$\deg:\mathcal{M}^{G}\to
A(G)$, which assigns to every admissible $G$-pair $(f,\Omega)$ an element
$G\mbox{\rm -}\deg(f,\Omega)\in A(G)$, called the \textit{$G$-equivariant
degree} (or simply \textit{$G$-degree}) of $f$ on $\Omega$:
\begin{equation}
\label{eq:G-deg0}G\mbox{\rm -}\deg(f,\Omega)=\sum_{(H_{i})\in\Phi_{0}
(G)}n_{H_{i}}(H_{i})= n_{H_{1}}(H_{1})+\dots+n_{H_{m}}(H_{m}).
\end{equation}
It satisfies the following properties:

\begin{enumerate}
%\item \renewcommand\labelenumi{{\rm(G\arabic{enumi})}}


\item \textrm{\textbf{(Existence)}} If $G\mbox{\rm -}\deg(f,\Omega)\neq0$,
i.e., \eqref{eq:G-deg0} contains a non-zero coefficient $n_{H_{i}}$, then
$\exists_{x\in\Omega}$ such that $f(x)=0$ and $(G_{x})\geq(H_{i})$.

\item \textrm{\textbf{(Additivity)}} Let $\Omega_{1}$ and $\Omega_{2}$ be two
disjoint open $G$-invariant subsets of $\Omega$ such that $f^{-1}(0)\cap
\Omega\subset\Omega_{1}\cup\Omega_{2}$. Then
\[
G\mbox{\rm -}\deg(f,\Omega)=G\mbox{\rm -}\deg(f,\Omega_{1})+G\mbox{\rm -}\deg
(f,\Omega_{2}).
\]


\item \textrm{\textbf{(Homotopy)}} If $h:[0,1]\times V\to V$ is an $\Omega
$-admissible $G$-homotopy, then
\[
G\mbox{\rm -}\deg(h_{t},\Omega)=\mathrm{constant}.
\]


\item \textrm{\textbf{(Normalization)}} Let $\Omega$ be a $G$-invariant open
bounded neighborhood of $0$ in $V$. Then
\[
G\mbox{\rm -}\deg(\text{\text{\textrm{Id}}},\Omega)=(G).
\]


\item \textrm{\textbf{(Product)}} For any $(f_{1},\Omega_{1}),(f_{2}
,\Omega_{2})\in\mathcal{M}^{G}$,
\[
G\mbox{\rm -}\deg(f_{1}\times f_{2},\Omega_{1}\times\Omega_{2})=
G\mbox{\rm -}\deg(f_{1},\Omega_{1})\cdot G\mbox{\rm -}\deg(f_{2},\Omega_{2}),
\]
where the multiplication `$\cdot$' is taken in the Burnside ring $A(G)$.

\item \textrm{\textbf{(Suspension)}} If $W$ is an orthogonal $G$
-representation and $\mathcal{B}$ is an open bounded invariant neighborhood of
$0\in W$, then
\[
G\mbox{\rm -}\deg(f\times\text{\textrm{\textrm{Id}}}_{W},\Omega\times
\mathcal{B} )=G\mbox{\rm -}\deg(f,\Omega).
\]


\item \textrm{\textbf{(Recurrence Formula)}} For an admissible $G$-pair
$(f,\Omega)$, the $G$-degree \eqref{eq:G-deg0} can be computed using the
following recurrence formula
\begin{equation}
\label{eq:RF-0}n_{H}=\frac{\deg(f^{H},\Omega^{H})- \sum_{(K)>(H)}
n_{K}\,n(H,K)\,\left|  W(K)\right|  }{\left|  W(H)\right|  },
\end{equation}
where $\left|  X\right|  $ stands for the number of elements in the set $X$
and $\deg(f^{H},\Omega^{H})$ is the Brouwer degree of the map $f^{H}
:=f|_{V^{H}}$ on the set $\Omega^{H}\subset V^{H}$.
\end{enumerate}
\end{theorem}
\noi \textbf{Computation of Brouwer $G$-Equivariant Degree.}  Consider the $G$-isotypic decomposition of $V$:
$V = \bigoplus_{i=0}^{r} V_i,$
where $V_i$ is modeled on the irreducible $G$-representation $\cV_i$, $i=0, 1, 2,\dots, r.$ Then,
\begin{definition} The Brouwer $G$-equivariant degree
\begin{equation} \label{eq:basicdeg}
\deg_{\cV_i} := G\text{-}\deg(-\id, B(\cV_i)),
\end{equation}
is called the {\it $\cV_i$-basic degree}.
\end{definition}
Now, consider a $G$-equivariant linear isomorphism $A:V\to V.$
For any eigenvalue $\lambda \in \sigma(A)$,  denote by $E_i(\lambda) := E(\lambda) \cap V_i, \; i=0, 1, 2,\dots , r,$ and define the subspaces
\[
E_{i}^-:=\bigoplus\limits_{\lambda \in \sigma_{-}(A)} E_i(\lambda),
\]
where $\sigma_{-}(A)$ denotes the real negative spectrum of $A.$\vs
Then from product property (EB5), one has
\begin{align*}
%\label{eq:prod-prop}
\gdeg(A,B(V))=\prod_{i \in \bn} \gdeg	(A_{i},B(V_{i}))= \prod_{i \in \bn}\prod_{\mu\in\sigma_{-}(A)} \left(	\deg_{\mathcal{V} _{i}}\right)  ^{m_{i}(\lambda)},
\end{align*}
where $m_i(\lambda)=\dim E_i(\lambda)/\dim \cV_i,$ and the product is taken in the Burnside ring $A(G)$.
\vskip.3cm
\noi \textbf{Properties of Basic Degree.}
Notice that from equation \eqref{eq:RF-0}, one can easily compute the basic degrees based on the following formula:
\begin{align*}
	\deg_{\mathcal{V} _{i}}=\sum_{(L)}n_{L}(L),
\end{align*}
where
\begin{align}\label{eq:formula}
n_{L}=\frac{(-1)^{\dim\mathcal{V} _{i}^{L}}- \sum_{L<K}{n_{K}\, n(L,K)\, \left|  W(K)\right|  }}{\left|  W(L)\right|  }.
\end{align}
\vs
The following facts are well-known.
\begin{lemma}\label{le:basic_coefficient}
If for $ (L_o) \in \Phi_0(G)$, one has $\text{coeff}^{L_o} (\deg_{\cV_i})$ is a leading coefficient of $\deg_{\cV_i}$, then $\dim (\cV_i ^{L_o})$ is odd and
\[
\text{coeff}^{L_o}(\deg_{\cV_i})=
\begin{cases}\label{eq:a0}
-1 & \text{if} \; |W(L_o)|=2,\\
-2 & \text{if}\; |W(L_o)|=1;\\
\end{cases}
\]
\end{lemma}
\begin{lemma}\label{le:involutive}
    For any irreducible $G$-representation $\mathcal V_i$, the basic degree $\deg_{\mathcal V_i} \in A(G)$ is an involutive element of the Burnside Ring, i.e.
    \[
    (\deg_{\cV_i})^2=\deg_{\cV_i} \cdot \deg_{\cV_i}=(G).
    \]
\end{lemma}
