\section{Sierpi\'{n}ski products of complete graphs}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%


\begin{lemma}
\label{lem:alpha2}
If $n\ge 3$ and $n\ge m\ge 2$, then 
$\alpha_2(K_m \otimes_f K_n) = m$. 
\end{lemma}

\begin{proof}
Since $n \ge m$, at most $n-1$ vertices of any fiber $u_iK_n$ are connecting vertices. Thus, in each fiber, at least one vertex is not connecting; let $M$ denote a set of non-connecting vertices such that $M$ contains exactly one vertex from each fiber $u_iK_n$, $i\in [m]$). Hence $\vert M\vert =m$. Since the vertices of $M$ are pairwise at distance at least $3$, we have $\alpha_2(K_m \otimes_f K_n)\geq m$. On the other hand, no $2$-packing can contain two vertices of the same fiber. Therefore $\alpha_2(K_m \otimes_f K_n)= m$. \qed
%$x_{i,j_{i}}$ denote such vertices for some $j_{i}\in \{1,2,\dots, n$, $i=1,2,\dots, m$. Clearly, for any $a\not=b, a,b\in \{1,2,\dots, m\}$, $d(x_{a,j_{a}}, x_{b,j_{b}}\ge 3$. Thus we color all such vertices with color 2. On the other hand, we can color only one vertex of each fiber with color 2.
\end{proof}

\begin{lemma}
\label{lem:alpha}
If $m\ge 2$ and $n\ge 3$, then 
$\alpha(K_m \otimes_f K_n) = m$. 
\end{lemma}

\begin{proof}
Let $G=K_m \otimes_f K_n$. Clearly, $\alpha(G)\leq m$ since every maximal independence set in $G$ can contain only one vertex of each fiber of $G$. It remains to show that $\alpha(G)= m$. Let $N=\{(u_i,f(u_i)-1), i\in [m]\}$ (if $f(u_i)=1$ then we set $f(u_i)-1=n$ since we take function values of $f$ modulo $n$). If $(u_a, f(u_a)-1)$ is adjacent to some $(u_b,f(u_b)-1)$, $a,b\in [m]$, $a\not=b$, then $f(u_a)=f(u_{b}) - 1$ and $f(u_b) = f(u_{a}) - 1$ by the definition of the Sierpi\' {n}ski product, implying that $2=0$ (note that indices are taken modulo $n$), which is not possible since $n\ge 3$. Thus for each pair $a,b\in [m]$, $a\not=b$, the vertices $(u_a,f(u_a)-1)$ and $(u_b,f(u_b)-1)$ are not adjacent, hence $N$ is an independent set of size $m$. \qed
\end{proof}

\begin{theorem}
\label{thm:two complete n>=m}
If $n\ge m\ge 3$, then 
$$\pch(K_m, K_n) = \pchu(K_m, K_n) = mn - 2m   + 2\,.$$ 
\end{theorem}

\begin{proof}
Let $G=K_m \otimes_f K_n$. By Lemma \ref{lem:alpha2}, there is a $2$-packing $M\subset V(G)$ with $\vert M\vert =m$. We color all vertices of $M$ with color $2$, but need to distinguish two cases of how $M$ is selected. 

Assume first that $f$ is not surjective. We may  without loss of generality assume that the vertex $n$ is an image of no vertex from $K_m$. Then we set $M = \{(u_1,n), (u_2,n), \ldots, (u_m,n)\}$. Now consider the subgraph $G'$ of $G$ induced by the vertices from $V(G)\setminus M$. Consider further $G'$ to be a Sierpi\'nski product graph with $f' = f$. Then $G'$ contains an independent set $N$ of size $m$ by the virtue of Lemma~\ref{lem:alpha}. As $G'$ is induced in $G$, the set $N$ is also an independent set of $G$, hence we may color all vertices of $N$ with color $1$. 

Assume second that $f$ is surjective. In this case $n=m$, and we may without loss of generality assume that $f(u_i) = i$, $i\in [m]$. Set $M = \{(u_1,1), (u_2,2), \ldots, (u_m,m)\}$ and observe that $M$ is  a 2-packing, hence coloring all vertices of $G$ with color $2$ is legal. Moreover, we infer that the set $N = \{(u_1,2), (u_2,3), \ldots, (u_m,1)\}$ is an independent set of $G$, thus we may color all vertices of $N$ with color $1$. 

Finally, in both cases, color all the remaining (uncolored) vertices of $G$ with mutually distinct colors $3,4,\dots, mn-2m+2$. Since $\diam(G)=3$ by Lemma~\ref{lem:diam}, we cannot use any of the colors $3,4,\dots$ more than once, implying that $\pch(G) = mn - 2m   + 2$.

The above argument is independent of the selection of $f\in K_n^{K_m}$, hence we may conclude that  
$\pch(K_m, K_n) = \pchu(K_m, K_n) = mn - 2m   + 2$.  
\qed
\end{proof}

\begin{theorem}
\label{thm:two complete n>=m}
If $m \ge n\ge 3$, then  
$$\pch(K_m, K_n) = mn - 2m   + 2\,.$$ 
\end{theorem}

\begin{proof}
Let $G = K_m \otimes_f K_n$. Since every fiber $u_iK_n$ is complete, we have $\alpha(G)\le m$ and $\alpha_2(G)\le m$. This means that in any packing coloring of $G$, at most $m$ vertices can receive color $1$ and at most $m$ vertices can receive color $2$. By Lemma~\ref{lem:diam}, every other vertex requires a new, private color. It follows that $\pch(G) \ge 2 + (mn - 2m) = mn - 2m + 2$, and thus $\pch(K_m, K_n) \ge mn - 2m   + 2$.

Consider now the constant function $f'\in K_n^{K_m}$ defined by $f'(u_i) = 1$ for each $i\in [m]$. Then $X= \{(u_i,2):\ i\in [m]\}$ is an independent set of $G$ and $X' = \{(u_i,3):\ i\in [m]\}$ is a $2$-packing of $G$. Since $|X| = |X'| = m$, we get  $\pch(G) \le mn - 2m + 2$, thus $\pch(G) = mn - 2m + 2$. Hence we also have $\pch(K_m, K_n) \le mn - 2m   + 2$ and we are done.
\qed
\end{proof}

\begin{lemma}
\label{lem:rho-at-least-n}
If $m \ge n\ge 3$, (CHECK if 3 or 4) then $\alpha_2(G)\ge n$.
\end{lemma}

\begin{proof}
Let $G = K_m \otimes_f K_n$. If $f$ is not surjective, then we can see similarly as in the proof of Theorem~\ref{thm:two complete n>=m} that the set of vertices $\{(u_1, \ell), (u_2, \ell), \ldots, (u_n,\ell)\}$ is a $2$-packing of $G$, where $\ell$ is a value which is not in ${\mathcal R}(f)$. (Actually, if there is some $\ell\notin {\mathcal R}(f)$, then we can get in this way a $2$-packing of size $m$.) Assume next that $f$ is surjective, and that, without loss of generality $f(u_i) = i$, $i\in [n]$. Then we claim that $S = \{(u_1, 1), (u_2, 2), \ldots, (u_n,n)\}$ is a required $2$-packing of $G$. Suppose this is not the case. Then there exist two vertices $(u_i, i), (u_j,j)$ from $S$ such that $d_G((u_i,i), (u_j,j)) = 2$. Let $(u_k,\ell)$ be a common neighbor of $(u_i, i)$ and $(u_j,j)$. Then $\ell > n$, in particular, $\ell \ne i,j$. Since $(u_i, i)(u_k, \ell)\in E(G)$, we get $f(u_i) = \ell$. Similarly, since $(u_j, j)(u_k, \ell)\in E(G)$, we get $f(u_j) = \ell$. So we have $i = f(u_i) = \ell = f(u_j) = j$, but $i\ne j$, a contradiction. This proves the claim. 
\qed
\end{proof}


\begin{theorem}
\label{thm:two complete m ge n}
If $m \ge n\ge 3$, (CHECK 3 or 4) then 
$$ mn - m - n + 2 \le \pchu(K_m, K_n) \le mn - m + 1\,.$$ 
\end{theorem}

\begin{proof}
Let $G = K_m \otimes_f K_n$. By Lemma~\ref{lem:rho-at-least-n} we have $\alpha_2(G)\ge n$. Next we show that there exists a function $f$ for which $\alpha_2(K_m \otimes_f K_n)\leq n$. For this sake let $f':V(K_m)\rightarrow V(K_n)$ be defined by setting $f'(u_i)=i$ for each $i\in [n]$, and $f'(u_i)=1$ for each $i>n$. Let $G'=K_m \otimes_{f'} K_n$. Consider an arbitrary $2$-packing $M'$ of $G$. 

\medskip\noindent
{\bf Fact 1}: If $M' \cap \{(u_1,1), (u_{n+1},1), \ldots, (u_{m},1)\} \neq \emptyset$, then 
$$|M' \cap (V(u_1K_n) \cup V(u_{n+1}K_m) \cup \cdots \cup V(u_{m}K_m))| = 1\,.$$
Assume that $(v_i, 1)\in M'$, where $i\in \{1, n+1, \ldots, m\}$. Then every vertex from $X = V(u_1K_n) \cup V(u_{n+1}K_m) \cup \cdots \cup V(u_{m}K_m))$ is at distance at most $2$ from $(v_i, 1)$. Since $M'$ is a $2$-packing, $(v_i, 1)$ is the only vertex from $M'\cap X$ which proves Fact 1. 

\medskip\noindent
{\bf Fact 2}: If $j\in \{2,\ldots, n\}$, then 
$$|M' \cap \{(u_1,j), (u_{n+1},j), \ldots, (u_{m},j)\}| \le 1\,.$$
Assume that $(u_i, j)\in M'$, where $i\in \{1, n+1, \ldots, m\}$. If $(u_{i'}, j)$ is an arbitrary  vertex with $i'\in \{1, n+1, \ldots, m\}\setminus \{i\}$, then $(u_j,1)$ is a common neighbor of $(u_i, j)$ and $(u_{i'}, j)$. Hence $(u_{i'}, j)\notin M'$, and so $(u_i, j)$ is the only vertex from $M' \cap \{(u_1,j), (u_{n+1},j), \ldots, (u_{m},j)\}$. This proves Fact 2. 

\medskip
We are now ready to prove that $|M'|\le n$. We distinguish the following two cases.

\medskip\noindent
{\bf Case 1}: $M' \cap \{(u_1,1), (u_{n+1},1), \ldots, (u_{m},1)\} = \emptyset$.\\
In this case, the vertices of $M'$ lie in fibers $u_2K_n, \ldots, u_{n}K_n$. As each of these layers contains at most one vertex from $M'$ we have $|M'| \le n-1$. 

\medskip\noindent
{\bf Case 2}: $M' \cap \{(u_1,1), (u_{n+1},1), \ldots, (u_{m},1)\} \ne \emptyset$.\\
In this case, $|M' \cap (V(u_1K_n) \cup V(u_{n+1}K_m) \cup \cdots \cup V(u_{m}K_m))| = 1$ by Fact 1. Set $I = \{1,n+1,\ldots, m\}$, and let $(u_i,1)\in M'$, where $i\in I$. Set 
$$t = \Big|M' \cap \bigcup_{i'\in I\setminus \{i\}} V(u_{i'}K_n)\Big|\,.$$
In view of Fact 2, $t\le n-1$. Let now $(u_{i'},j)\in M'$, where $i'\ne i$. Then $j\in \{2,\ldots, n\}$ by Fact 1. Now, $(u_{i'},j)(u_{j},1)\in E(G)$, which implies that $M'\cap V(u_{j}K_n) = \emptyset$. From this and using Fact 2 again we get that among the fibers $u_2K_n, \ldots, u_{n}K_n$, at least $t$ of them have no vertex in $M'$. This in turn implies that $|M'| \le 1 + t + (n-1-t) = n$. We can conclude that $\alpha_2(G') \le n$ and hence $\alpha_2(G') = n$. 

Using arguments parallel to those in the proof of Theorem~\ref{thm:two complete n>=m}, we now select a $2$-packing $M$ of $G'$ of size $n$ and an independent set $N$ with $\vert N\vert =m$ such that $N\cap M=\emptyset$. We color all vertices of $N$ with color $1$ and all vertices of $M$ with color $2$. Finally, we color all remaining (uncolored) vertices of $G'$ with mutually distinct colors $3,4,\dots, mn-m-n+2$. Note that we cannot repeat any of these colors since $\diam(G')=3$. This proves that $\pch(G') = mn - m - n + 2$ and we can conclude that $\pchu(K_m, K_n) \ge mn - m - n + 2$. 

