\section{Transversals and v-numbers of binomial edge ideals}\label{section transversals}

This section is devoted to the study of 
v-numbers of binomial edge ideals. By analyzing transversals of a family of subsets arising from the dependencies of certain rank-two matroids, we reduce the problem of computing localized 
v-numbers to that of determining the radical of an explicit ideal. This perspective also yields upper bounds for the localized 
v-numbers. Throughout this section, we fix $G$ to be a simple and connected graph on $[n]$.

\subsection{Reducing the problem to computing the radical of a transversal ideal}\label{reduction with transversals}

In this subsection, we show how Question~\ref{question 2} reduces to computing the radical of a certain ideal generated by transversals. Throughout this section, we fix a minimal prime $P_{\mathcal{S}}$ of $J_{G}$, and focus on addressing Question~\ref{question 2} with respect to this prime. 
We begin by recalling the definition of a transversal and introduce some necessary notation.


\begin{definition}\label{transveral definition}
Let $\Delta$ be a collection of subsets of a set $E$. A subset $A \subset \cup_{e\in \Delta}e$ is called a \emph{transversal} of $\Delta$ if $A \cap e \neq \emptyset$ for all $e \in \Delta$.
\end{definition}



\begin{definition}\label{important notation}
We now introduce the notions and terminology used throughout this section. For context, recall Definitions~\ref{definition MS} and~\ref{def:dependant}.

\begin{enumerate}
    \item[{\rm (i)}] For each $k \geq 2$, let ${\min}_k(G)$ denote the set of minimal $k$-cuts of the graph $G$. We set \[\min(G) := \bigcup_{k \geq 2} {\min}_k(G)\cup \{\emptyset\},\] 
    the collection of all minimal $k$-cuts of $G$, together with the emptyset.

    \item[{\rm (ii)}] For a fixed $\mathcal{S} \in \min(G)$, define $\Delta_{\mathcal{S}}$ as the collection of subsets
    \[
    \left\{ \mathcal{D}(M(\mathcal{S}')) \setminus \mathcal{D}(M(\mathcal{S})) : \mathcal{S}' \in \min(G) \setminus \{ \mathcal{S} \} \right\}
    \subseteq \textstyle (\binom{[n]}{1} \cup \binom{[n]}{2})\setminus \mathcal{D}(M(\mathcal{S})).
    \]
    We denote by $\mathcal{T}(\mathcal{S})$ the set of all transversals of $\Delta_{\mathcal{S}}$.

    \item[{\rm (iii)}]\label{item 3} Each $A \in \mathcal{T}(\mathcal{S})$ is written as a disjoint union $A = A_1 \amalg A_2$, where \[A_1 \subseteq \textstyle \binom{[n]}{1}\quad  \text{and} \quad A_2 \subseteq \binom{[n]}{2}.\] We identify $A_1$ with a subset of $[n]$ in the natural way.

    \item[{\rm (iv)}] For arbitrary subsets $C, D \subseteq [n]$, define the monomial \[g_{C,D} := \prod_{k \in C} x_k \prod_{k \in D} y_k.\]

    \item[{\rm (v)}]\label{item v} For any $A \in \mathcal{T}(\mathcal{S})$ and a partition $A_1 = C \amalg D$, define \[g_{A,C,D} := g_{C,D} \cdot \prod_{\{i,j\} \in A_2} f_{i,j},\]
    where $f_{i,j}=x_{i}y_{j}-x_{j}y_{i}$.
\end{enumerate}
\end{definition}


We are now ready to prove one of the two main results of this section. 

\begin{theorem}\label{theorem transversal}
With the notation above, the following equality of ideals holds:
\begin{equation}\label{equality of ideals}(J_{G}:P_{\mathcal{S}})=\sqrt{J_{G}+(g_{A,C,D}:A\in \mathcal{T}(\mathcal{S}) \ \text{and $C\amalg D=A_{1}$})}.\end{equation}
\end{theorem}

\begin{proof}
Set
\[
J := (g_{A,C,D} : A \in \mathcal{T}(\mathcal{S}) \ \text{and} \ C \amalg D = A_1).
\]
Since both sides of~\eqref{equality of ideals} are radical ideals, it suffices to prove the equality of their varieties:
\begin{equation}\label{closure ideal}
\overline{\mathbb{V}(J_G) \setminus \mathbb{V}(P_{\mathcal{S}})} = \mathbb{V}(J_G) \cap \mathbb{V}(J),
\end{equation}
where we use the identity
\[
\mathbb{V}((J_G : P_{\mathcal{S}})) = \overline{\mathbb{V}(J_G) \setminus \mathbb{V}(P_{\mathcal{S}})},
\]
see~\textup{\cite[§4, Theorem~10 (iii)]{david1991ideals}}, and the fact that $J_{G}$ is radical, see \textup{\cite[Corollary~2.2]{herzog2010binomial}}. Moreover, by Theorems~\ref{theorem decomposition} and~\ref{Theorem minimal primes}, the left-hand side of~\eqref{closure ideal} equals
\begin{equation}\label{union of ideals}
\bigcup_{\mathcal{S}' \in \min(G) \setminus \{\mathcal{S}\}} \mathbb{V}(P_{\mathcal{S}'}).
\end{equation}

We begin by proving the inclusion $\subseteq$. Let $\gamma = (\gamma_1, \ldots, \gamma_n) \in (\CC^2)^n$ be a point in~\eqref{union of ideals}, and suppose without loss of generality that $\gamma \in \mathbb{V}(P_{\mathcal{S}'})$ for some $\mathcal{S}' \ne \mathcal{S}$. We aim to show that $\gamma \in \mathbb{V}(J)$.

Let $g_{A,C,D}$ be an arbitrary generator of $J$. Since $A \in \mathcal{T}(\mathcal{S})$, there exists an element $e \in A \cap \mathcal{D}(M(\mathcal{S}'))$. We distinguish two cases:

\smallskip
\noindent
\textbf{Case $e = \{i\}$:} Then $i \in \mathcal{S}'$, and since $\gamma \in \mathbb{V}(P_{\mathcal{S}'})$, we have $\gamma_i = 0$. Moreover, by construction of $g_{A,C,D}$, either $x_i$ or $y_i$ divides it, so $g_{A,C,D}(\gamma) = 0$.

\smallskip
\noindent
\textbf{Case $e = \{j,k\}$:} Then $j$ and $k$ lie in the same connected component of $G_{[n] \setminus \mathcal{S}'}$, and since $\gamma \in \mathbb{V}(P_{\mathcal{S}'})$, this implies that $\gamma_j$ and $\gamma_k$ are linearly dependent. Since $f_{j,k}$ divides $g_{A,C,D}$, it follows again that $g_{A,C,D}(\gamma) = 0$.

\smallskip
In both cases, $g_{A,C,D}$ vanishes at $\gamma$, and since this holds for all generators, we conclude $\gamma \in \mathbb{V}(J)$.

We now prove the reverse inclusion. Let $\gamma \in \mathbb{V}(J_G) \cap \mathbb{V}(J)$ and suppose, for contradiction, that $\gamma \notin \mathbb{V}(P_{\mathcal{S}'})$ for every $\mathcal{S}' \in \min(G) \setminus \{ \mathcal{S} \}$. We can assume $\gamma \in \mathbb{V}(P_{\mathcal{S}})$, because on the contrary we would have $\gamma \in \mathbb{V}(J_{G})\setminus \mathbb{V}(P_{\mathcal{S}})$.

Let $M(\gamma)$ be the matroid on $[n]$ induced by the vectors $\gamma_1, \ldots, \gamma_n$. Then, since $\gamma \in \mathbb{V}(P_{\mathcal{S}})$ and $\gamma \notin \mathbb{V}(P_{\mathcal{S}'})$ for every $\mathcal{S}' \in \min(G) \setminus \{ \mathcal{S} \}$, it follows that
\[
\mathcal{D}(M(\gamma)) \supseteq \mathcal{D}(M(\mathcal{S})) \quad \text{and} \quad 
\mathcal{D}(M(\gamma)) \nsupseteq \mathcal{D}(M(\mathcal{S}'))
\]
for all $\mathcal{S}' \in \min(G) \setminus \{ \mathcal{S} \}$.

Let $A$ be a set containing one element from each difference
\[
\mathcal{D}(M(\mathcal{S}')) \setminus \mathcal{D}(M(\gamma)).
\]
By construction, $A \in \mathcal{T}(\mathcal{S})$. Since $A \subseteq \textstyle \binom{[n]}{1} \cup \binom{[n]}{2}$ and all its elements lie outside $\mathcal{D}(M(\gamma))$, we have:
\begin{itemize}
\item For each $i \in A_1$, at least one of $x_i$ or $y_i$ does not vanish at $\gamma$;
\item For each $\{j,k\} \in A_2$, we have $f_{j,k}(\gamma) \ne 0$.
\end{itemize}

Hence, we can find a partition $C \amalg D = A_1$ such that $g_{A,C,D}(\gamma) \ne 0$, contradicting the assumption $\gamma \in \mathbb{V}(J)$. This contradiction completes the proof.
\end{proof}


\begin{definition}\label{notation JS}
To simplify notation, we denote by
\[
J_{\mathcal{T}(\mathcal{S})} := \left(g_{A,C,D} : A \in \mathcal{T}(\mathcal{S}) \ \text{with} \ C \amalg D = A_1\right)
\]
the ideal generated by all such polynomials.
\end{definition}


As a consequence of Theorem~\ref{theorem transversal}, we obtain upper bounds for the localized v-numbers. These bounds are computed in a purely combinatorial way.

\begin{theorem}\label{corollary radical}
With the notation above, the localized \textup{v}-number satisfies
\[
\textup{v}_{P_{\mathcal{S}}}(J_{G}) \leq \min \{ |A_{1}| + 2|A_{2}| : A \in \mathcal{T}(\mathcal{S}) \}.
\]
Moreover, equality holds if the ideal $J_{G}+J_{\mathcal{T}(\mathcal{S})}$ is radical.
\end{theorem}

\begin{proof}
Let $A \in \mathcal{T}(\mathcal{S})$. By Theorem~\ref{theorem transversal}, we have $g_{A,C,D} \in (J_G : P_{\mathcal{S}})$ for any partition $\{C, D\}$ of $A_1$. Moreover, since all elements of $A$ lie outside $\mathcal{D}(M(\mathcal{S}))$, each factor of $g_{A,C,D}$ is nonzero on $\mathbb{V}(P_{\mathcal{S}})$. As $\mathbb{V}(P_{\mathcal{S}})$ is irreducible, 
It follows that $g_{A,C,D}$ does not vanish identically on $\mathbb{V}(P_{\mathcal{S}})$, and therefore not on $\mathbb{V}(J_G)$ either. Consequently, we have $g_{A,C,D} \notin J_G$. Note also that
\[
\deg(g_{A,C,D}) = |A_1| + 2|A_2|.
\]
Thus, by Theorem~\ref{results v number} (ii), we have 
\[\textup{v}_{P_{\mathcal{S}}}(J_G)=\alpha((J_G : P_{\mathcal{S}})/J_{G})\leq \deg(g_{A,C,D}) = |A_1| + 2|A_2|,\]
establishing the first part of the claim, since $A\in \TS$ is arbitrary.

Now assume that $J_{G} + \JS$ is radical. By Theorem~\ref{theorem transversal}, we have
\[
(J_G : P_{\mathcal{S}}) / J_G = (J_G + \JS)/J_G.
\]
Moreover, 
\[
\left\{ g_{A,C,D} : A \in \mathcal{T}(\mathcal{S}) \ \text{with} \ C \amalg D = A_1 \right\}
\]
is a generating set for this quotient. Then, applying Theorem~\ref{results v number} (i), we obtain
\[
\textup{v}_{P_{\mathcal{S}}}(J_G) \geq \min \left\{ \deg(g_{A,C,D}) : A \in \mathcal{T}(\mathcal{S}),\ C \amalg D = A_1 \right\} 
= \min \left\{ |A_{1}| + 2|A_{2}| : A \in \mathcal{T}(\mathcal{S}) \right\},
\]
which completes the proof.
\begin{comment}
Then, again by Theorem~\ref{results v number} (ii), we have
\[
\textup{v}_{P_{\mathcal{S}}}(J_G) = \alpha((J_G : P_{\mathcal{S}}) / J_G).
\]
Applying Theorem~\ref{theorem transversal}, it follows that
\begin{equation*}
\begin{aligned}
\alpha((J_G : P_{\mathcal{S}}) / J_G) 
&= \alpha\left( (J_G + \JS)/J_G \right) \\
&= \alpha(\JS) \\
&= \alpha\left( \left( g_{A,C,D} : A \in \mathcal{T}(\mathcal{S}), \, C \amalg D = A_1 \right) \right).
\end{aligned}
\end{equation*}
Hence,
\begin{equation*}
\begin{aligned}
\textup{v}_{P_{\mathcal{S}}}(J_G) 
&= \min\{ \deg(g_{A,C,D}) : A \in \mathcal{T}(\mathcal{S}), \, C \amalg D = A_1 \} \\
&= \min\{ |A_1| + 2|A_2| : A \in \mathcal{T}(\mathcal{S}) \},
\end{aligned}
\end{equation*}
which concludes the proof.
\end{comment}
\end{proof}

\begin{remark}\label{remark strategy}
This method reduces the computation of the localized v-number to determining a finite set of generators for the radical of $J_{G} + \JS$. Once such generators are identified, Theorem~\ref{results v number} provides an explicit formula for $\VPJ$. This leads to the following strategy for computing $\VPJ$:

\begin{enumerate}
\item[{\rm (i)}] Determine the collection of all transversals $\mathcal{T}(\mathcal{S})$.
\item[{\rm (ii)}] Compute the radical of $J_{G} + J_{\mathcal{T}(\mathcal{S})}$, typically via Gröbner basis methods.
\item[{\rm (iii)}] Identify the minimal degree of a homogeneous polynomial in  $\textstyle \sqrt{J_{G} + J_{\mathcal{T}(\mathcal{S})}}/J_G$, which equals $\textup{v}_{P_{\mathcal{S}}}(J_G)$.
\end{enumerate}
\end{remark}


\subsection{Computing $\textup{v}_{J_{\mathcal{K}_{n}}}(J_{G})$}

In this subsection, we fix a connected graph $G$ and consider the case $\mathcal{S} = \emptyset$, corresponding to the prime $J_{\mathcal{K}_{n}}$, where $\mathcal{K}_{n}$ is the complete graph on $[n]$. Using the reduction method introduced in Subsection~\ref{reduction with transversals}, we compute the algebraic invariant $\JK$. We further show that this invariant coincides with a purely combinatorial invariant of $G$: its connected domination number, see Definition~\ref{definition connected domination}.

We note that the results established in this subsection also appear in \cite{jaramillo2024connected} and \cite{ambhore2024v}. However, our treatment is based on a substantially different method, providing a new proof of these results. %We begin by introducing the notion of connected dominant sets.

\begin{comment}
\begin{definition}
Let $G$ be a connected graph. A \emph{connected dominating set} of $G$ is a subset $B \subseteq V(G)$ such that the induced subgraph $G_B$ is connected and every vertex in $V(G) \setminus B$ is adjacent to some vertex in $B$. We denote the collection of connected dominating sets of $G$ by $\mathcal{D}_c(G)$, and define the \emph{connected domination number} of $G$ as
\[
\gamma_c(G) := \min\{ |B| : B \in \mathcal{D}_c(G) \}.
\]
\end{definition}
\end{comment}

Our first step in computing $\JK$ is to describe the set $\mathcal{T}(\emptyset)$ of transversals of
\[
    \left\{ \mathcal{D}(M(\mathcal{S}')) \setminus \mathcal{D}(U_{1,n}) : \mathcal{S}' \in \min(G) \setminus \{ \emptyset \} \right\},
\]
where Remark~\ref{connected and uniform} applies. To that end, we begin by proving the following combinatorial lemma, for which we recall the definition of $\mathcal{D}_c(G)$ from Definition~\ref{definition connected domination}.

\begin{lemma}\label{transversal and connected dominant}
Let $G\neq \mathcal{K}_{n}$ be a connected graph on the vertex set $[n]$. A subset $A \subset [n]$ is a transversal of the collection
\[
\Delta = \{ S : S \in \min(G) \setminus \{ \emptyset \} \}
\]
if and only if $A$ belongs to the collection of connected dominating sets $\mathcal{D}_c(G)$.
\end{lemma}

\begin{proof}
Assume first that $A \in \mathcal{D}_c(G)$. To show that $A$ is a transversal of $\Delta$, we must prove that $A \cap S \neq \emptyset$ for every $S \in \min(G) \setminus \{ \emptyset \}$. Suppose, for contradiction, that there exists $S \in \min(G) \setminus \{ \emptyset \}$ such that $A \cap S = \emptyset$. Then $A \subset [n] \setminus S$, and since $A$ is connected and dominant, it follows that the induced subgraph on $[n] \setminus S$ is connected. This contradicts the assumption that $S \in \min(G)\setminus \{ \emptyset \}$, as such sets have disconnected complements.

Conversely, suppose $A$ is a transversal of $\Delta$. We show that $A \in \mathcal{D}_c(G)$ by verifying that $A$ is both connected and dominant.

\smallskip

\textbf{Connectedness.} Suppose, for contradiction, that $A$ is disconnected. Then the removal of the vertices in $[n] \setminus A$ disconnects the graph. Hence, there exists a minimal subset $S \subset [n] \setminus A$ such that the induced subgraph on $[n] \setminus S$ is disconnected. By minimality, we have $S \in {\min}_{2}(G)$ and $S \cap A = \emptyset$, contradicting that $A$ is a transversal of $\Delta$.

\smallskip

\textbf{Dominance.} Suppose, for contradiction, that $A$ is not dominant. Then there exists a vertex $i \in [n] \setminus A$ that is not adjacent to any vertex in $A$, so the subgraph induced by $A \cup \{i\}$ is disconnected. It follows that the removal of $[n] \setminus (A \cup \{i\})$ disconnects $G$. Thus, there exists a minimal subset $S \subset [n] \setminus (A \cup \{i\})$ such that $[n] \setminus S$ is disconnected. Again, we find $S \in \min(G)$ and $S \cap A = \emptyset$, contradicting that $A$ is a transversal of $\Delta$. This completes the proof.
\end{proof}

We are now in a position to describe the set of transversals $\mathcal{T}(\emptyset)$ and to present an explicit finite generating set for the ideal $J_{\mathcal{T}(\emptyset)}$.

\begin{proposition}\label{ideal J emptyset}
A subset $A \subset \textstyle (\binom{[n]}{1} \cup \binom{[n]}{2})\setminus \mathcal{D}(M(\emptyset))$ belongs to $\mathcal{T}(\emptyset)$ if and only if $A_{1} \in \mathcal{D}_{c}(G)$. Consequently, we have
\[
J_{\mathcal{T}(\emptyset)} = \left( g_{C,D} : C \cup D \in \mathcal{D}_{c}(G),\ C \cap D = \emptyset \right).
\]
\end{proposition}

\begin{proof}
The elements of $\mathcal{T}(\emptyset)$ are precisely the transversals of the collection
\[
    \left\{ \mathcal{D}(M(\mathcal{S}')) \setminus \mathcal{D}(U_{1,n}) : \mathcal{S}' \in \min(G) \setminus \{ \emptyset \} \right\}.
\]
Recall that the set of dependencies of the uniform matroid $U_{1,n}$ consists of all subsets of $[n]$ of size at least two. Hence, for each $\mathcal{S}'$, the difference $\mathcal{D}(M(\mathcal{S}')) \setminus \mathcal{D}(U_{1,n})$ corresponds exactly to the set of loops of the matroid $M(\mathcal{S}')$, which is, by definition, equal to $\mathcal{S}'$.

It follows that $\mathcal{T}(\emptyset)$ coincides with the set of transversals of the collection
\[
\{ \mathcal{S}' : \mathcal{S}' \in \min(G) \setminus \{ \emptyset \} \},
\]
which, by Lemma~\ref{transversal and connected dominant}, is precisely the set $\mathcal{D}_{c}(G)$. This proves the first part of the statement. The second part then follows directly from the definition of the ideal $J_{\mathcal{T}(\emptyset)}$.
\end{proof}


We are now prepared to establish the main result of this subsection, which offers a new proof of~\textup{\cite[Theorem~3.2]{jaramillo2024connected}}. This theorem demonstrates that the algebraic invariant $\JK$ coincides with the connected domination number $\gamma_{c}(G)$.


\begin{theorem}\label{theorem empty}
Let $G$ be a connected graph on $[n]$. Then, we have
\[\JK=\begin{cases}
\gamma_{c}(G) & \text{if $G\neq \mathcal{K}_{n},$}\\
0 & \text{if $G=\mathcal{K}_{n}$.}
\end{cases}
\]
\end{theorem}

\begin{proof}
Suppose that $G \neq \mathcal{K}_n$. By Proposition~\ref{ideal J emptyset}, we have
\[
J_{\mathcal{T}(\emptyset)} = \left( g_{C,D} : C \cup D \in \mathcal{D}_{c}(G),\ C \cap D = \emptyset \right),
\]
which gives
\[
J_G + J_{\mathcal{T}(\emptyset)} = J_G + \left( g_{C,D} : C \cup D \in \mathcal{D}_{c}(G),\ C \cap D = \emptyset \right).
\]
In~\textup{\cite[Lemma~3.5]{jaramillo2024connected}}, the authors construct a squarefree Gröbner basis for this ideal, which implies that it is radical. Hence, by Theorem~\ref{corollary radical}, it follows that
\[
\JK = \min \{\, |A_1| + 2|A_2| : A \in \mathcal{T}(\emptyset) \,\}.
\]
Moreover, Proposition~\ref{ideal J emptyset} shows that $\mathcal{T}(\emptyset) = \DG$, and we conclude that
\[
\JK = \gamma_c(G).
\]

Finally, if $G = \mathcal{K}_n$ is the complete graph, we clearly have $\JK = 0$.
\end{proof}


\section{V-numbers associated to minimal cuts}\label{section minimal cuts}


In this section, we fix a connected graph $G$ on $[n]$ along with a minimal cut $\mathcal{S}$ (see Definition~\ref{minimal cuts}). Using the reduction technique developed in Subsection~\ref{reduction with transversals}, we compute the algebraic invariant $\VPJ$. We also show that this invariant is governed by purely combinatorial properties of $G$, specifically involving connected domination numbers. Throughout this section, we fix a minimal cut $\mathcal{S} \subset [n]$ and introduce the notation that will be used in what follows.

\begin{notation}\normalfont
We introduce the following terminology:
\begin{itemize}
    \item Let $G_{1}$ and $G_{2}$ be the connected components of the induced subgraph on $[n] \setminus \mathcal{S}$, and denote by $V_{1}$ and $V_{2}$ their respective vertex sets.
\item A subset $\mathcal{S}'\subset [n]$ is said to be \emph{nice} if there do not exist vertices $i \in V_{1} \setminus \mathcal{S}'$ and $j \in V_{2} \setminus \mathcal{S}'$ such that $i$ and $j$ lie in the same connected component of $G_{[n] \setminus \mathcal{S}'}$. Observe that if $\mathcal{S}'$ is nice, we have $\mathcal{S}'\not \subset \mathcal{S}$.

\item Let $\Delta$ denote the collection
\begin{equation}\label{delta}
    \Delta := \left\{ \mathcal{S}' \setminus \mathcal{S} : \mathcal{S}' \in \min(G)\setminus \{\mathcal{S}\}, \ \text{and $\mathcal{S}'$ is nice} \right\},
\end{equation}
and let $T$ be the set of all transversals of $\Delta$. 
\end{itemize}
\end{notation}

\begin{comment}
Throughout this subsection, we work under the following assumption.

\begin{assumption}\label{assumption 1}
For each $i = 1, 2$, not every vertex of $V_{i}$ is adjacent to all vertices in $V_{i} \cup \mathcal{S}$.
\end{assumption}

The case where this assumption fails will be addressed separately in Subsection~\ref{GV1 and GV2 complete}.
\end{comment}

Our first step in computing the invariant $\VPJ$ is to describe the set $\mathcal{T}(\mathcal{S})$ of transversals of the collection
\[
    \left\{ \mathcal{D}(M(\mathcal{S}')) \setminus \mathcal{D}(M(\mathcal{S})) : \mathcal{S}' \in \min(G) \setminus \{ \mathcal{S} \} \right\}.
\]
To this end, we begin by establishing a result concerning the transversal $T$, which, as we shall later see, is closely related to the set $\mathcal{T}(\mathcal{S})$. Before doing so, however, we require the following lemma concerning minimal $k$-cuts.

\begin{comment}
\begin{lemma}
Let $B \subseteq [n] \setminus \mathcal{S}$. If 
\[
B \cap V_{i} \in \mathcal{D}_{c}(G_{i}) \quad \text{for } \ i = 1, 2,
\]
then $B \in T_{1}$.
\end{lemma}

\begin{proof}
Suppose that $B$ satisfies the conditions of the lemma and set $B_{i}:=B \cap V_{i}$ for $i=1,2$. To show that $B\in T_{1}$, we must prove that $B\cap \mathcal{S}'\neq \emptyset$ for every $\CS' \in \min(G)$ with $\CS'\supsetneq \CS$. Suppose, for contradiction, that there exists such $\CS'$ such that $B \cap S = \emptyset$. 

Since $\CS'\supsetneq \CS$ and $\CS\in {\min}_{2}(G)$ it is clear that $\CS'\not \in {\min}_{2}(G)$. Hence, since $\CS' \in \min(G)$, we have that the induced subgraph $G_{[n]\setminus \CS'}$ has at least three connected components.

On the other hand, since $B \cap S = \emptyset$, it follows that $B_{i}\subset V_{i}\setminus \CS'$ for $i=1,2$. Consequently, using the $B_{1}$ and $B_{2}$ are connected and dominant we obtain that the induced subgraphs $G_{V_{1}\setminus \CS'
}$ and $G_{V_{2}\setminus \CS'
}$ are connected. Therefore, $G_{[n]\setminus \CS'}$ has at most two connected components, leading to a contradiction.
\end{proof}
\end{comment}


\begin{lemma}\label{refinement}
Let $A \subset [n]$ be a subset such that the induced subgraph $G_{[n] \setminus A}$ has connected components $G_{W_1}, \ldots, G_{W_k}$, where $k\geq 2$ and each $W_i$ denotes the vertex set of a component. Then there exists a subset $B \subset A$ such that $B \in \min(G)$, and each $W_i$ remains entirely contained within a distinct connected component of $G_{[n] \setminus B}$.
\end{lemma}

\begin{proof}
Suppose first that every vertex $i \in A$ is adjacent to at least two connected components of $G_{[n] \setminus A}$. In this case, each $i\in A$ is a cut point of the graph $G_{([n]\setminus A)\cup \{i\}}$, %the removal of $A$ separates the graph in a minimal way, 
so $A \in \min(G)$, and we are done.

Otherwise, there exists a vertex $i_1 \in A$ that is adjacent to at most one connected component of $G_{[n] \setminus A}$. Define $B_1 := A \setminus \{i_1\}$. Since $i_1$ does not reconnect distinct components, each $W_i$ remains entirely contained within a distinct connected component of $G_{[n] \setminus B_1}$.

We proceed inductively: at step $k$, if there exists a vertex $i_k \in B_{k-1}$ adjacent to at most one connected component of $G_{[n] \setminus B_{k-1}}$, we set $B_k := B_{k-1} \setminus \{i_k\}$. In each step, the property that each $W_i$ lies entirely within a distinct component is preserved.

This process yields a strictly decreasing chain of subsets:
\[
A \supsetneq B_1 \supsetneq B_2 \supsetneq \cdots
\]
The process terminates by finiteness, and not with the empty set since $G$ is connected. 
Hence, there exists $\ell$ such that every vertex $i \in B_\ell$ is adjacent to at least two connected components of $G_{[n] \setminus B_\ell}$.  
Thus $B_\ell \in \min(G)$, and setting $B := B_\ell$ completes the proof.
\end{proof}


The following lemma provides a description of the set of transversals $T$, which will later be useful in computing $\mathcal{T}(\mathcal{S})$.


\begin{lemma}\label{transversal for nice subsets}
Let $B \subseteq [n] \setminus \mathcal{S}$ such that $B\cap V_{i}\neq \emptyset$ for $i=1,2$. Then $B \in T$ if and only if
\[
    B \cap V_{i} \in \mathcal{D}_{c}\big(G_{V_{i} \cup \mathcal{S}}\big) \quad \text{for each } i = 1, 2.
\]
\end{lemma}

\begin{proof}
Set $B_i := B \cap V_i$ for $i = 1,2$. Assume first that $B_i \in \mathcal{D}_{c}(G_{V_i \cup \mathcal{S}})$ for $i = 1,2$. To show that $B \in T$, it suffices to prove that
\[
B \cap \mathcal{S}' \neq \emptyset
\]
for every \emph{nice} set $\mathcal{S}' \in \min(G)$. Suppose, for the sake of contradiction, that there exists such a set $\mathcal{S}'$ with $B \cap \mathcal{S}' = \emptyset$. We distinguish two cases.

\smallskip
\noindent\textbf{Case 1: $\mathcal{S}' \supsetneq \mathcal{S}$.} Since $\mathcal{S} \in {\min}_{2}(G)$, it follows that $\mathcal{S}' \notin {\min}_{2}(G)$. Therefore, because $\mathcal{S}' \in \min(G)$, the graph $G_{[n] \setminus \mathcal{S}'}$ must have at least three connected components.

On the other hand, the assumption $B \cap \mathcal{S}' = \emptyset$ implies that $B_i \subset V_i \setminus \mathcal{S}'$ for $i = 1,2$. Since $B_1$ and $B_2$ are connected and dominant, we conclude that $G_{V_1 \setminus \mathcal{S}'}$ and $G_{V_2 \setminus \mathcal{S}'}$ are connected. Hence, $G_{[n] \setminus \mathcal{S}'}$ has at most two connected components, a contradiction.

\smallskip
\noindent\textbf{Case 2: $\mathcal{S}' \not\supset \mathcal{S}$.} Again, $B \cap \mathcal{S}' = \emptyset$ implies $B_i \subset V_i \setminus \mathcal{S}'$ for $i = 1,2$. Since $B_1$ and $B_2$ are connected and dominant in $G_{V_1 \cup \mathcal{S}}$ and $G_{V_2 \cup \mathcal{S}}$, the induced subgraphs
\[
G_{(V_1 \cup \mathcal{S}) \setminus \mathcal{S}'} \quad \text{and} \quad G_{(V_2 \cup \mathcal{S}) \setminus \mathcal{S}'}
\]
are connected.

Moreover, since $B_{1}$ and $B_{2}$ are dominant, every vertex in $\mathcal{S} \setminus \mathcal{S}'$ is adjacent to some vertex in $B_1$ and to some vertex in $B_2$. It follows that $G_{[n] \setminus \mathcal{S}'}$ is connected, contradicting the assumption that $\mathcal{S}' \in \min(G)$.

\smallskip
In both cases, we arrive at a contradiction. Hence, $B \cap \mathcal{S}' \neq \emptyset$ for all nice $\mathcal{S}' \in \min(G)$, and thus $B \in T$, as desired.


For the converse, assume that $B \in T$. We aim to show that $B_i \in \mathcal{D}_{c}(G_{V_i \cup \mathcal{S}})$ for $i = 1, 2$. Without loss of generality, we carry out the proof for $B_1$, which we divide into two steps.

\smallskip

\noindent\textbf{Step 1.} We first show that $B_1 \in \mathcal{D}_{c}(G_1)$.

\smallskip

We may assume that $G_1$ is not complete, since otherwise $B_1 \in \mathcal{D}_{c}(G_1)$ would hold automatically, given that $B_{1} \neq \emptyset$ by the assumption of the lemma. Then, by Lemma~\ref{transversal and connected dominant}, it suffices to verify that $B_1 \cap C \neq \emptyset$ for every nonempty $C \in \min(G_1)$. Assume for contradiction that $B_1 \cap C = \emptyset$ for some such $C$. Moreover, we may assume that $C$ is minimal, i.e., $C \in {\min}_2(G_1)$.

Define $A := \mathcal{S} \cup C$. Observe that $G_{[n] \setminus A}$ has exactly three connected components: $G_2$ and the two components of $G_{V_1 \setminus C}$, whose vertex sets we denote by $W_1$ and $W_2$.

By Lemma~\ref{refinement}, there exists a subset $F \subset A$ such that $F \in \min(G)$ and each of the sets $W_1$, $W_2$, and $V_2$ is entirely contained within a distinct component of $G_{[n] \setminus F}$.

\smallskip

\noindent\textbf{Claim 1.} $C \subset F$.

\smallskip

\noindent Suppose, for contradiction, that $i \in C \setminus F$ for some $i$. Since $C \in {\min}_2(G_1)$, the vertex $i$ is a cut point of $G_{(V_1 \setminus C) \cup \{i\}}$, which implies that $i$ is adjacent to some vertex in $W_{1}$ and to some vertex in $W_{2}$. Consequently, $i$ ensures that all vertices in $W_1 \cup W_2$ belong to the same connected component of $G_{[n] \setminus F}$. This contradicts the definition of $F$.

\smallskip

\noindent\textbf{Claim 2.} $F$ is nice.

\smallskip

\noindent Suppose not. Then there exist vertices $i \in V_1 \setminus F$ and $j \in V_2$ that lie in the same connected component of $G_{[n] \setminus F}$. Since $C \subset F$, we have $V_1 \setminus F = V_1 \setminus C = W_1 \cup W_2$. Without loss of generality, suppose $i \in W_1$. Then all the vertices in $W_1 \cup V_2$ lie in the same component of $G_{[n] \setminus F}$, contradicting the definition of $F$.

\smallskip

Since $F$ is nice, $F \in \min(G)$ and $B \in T$, it follows that $B \cap F \neq \emptyset$. From Claim~1, $F \setminus \mathcal{S} = C$, and since $B\cap \mathcal{S}=\emptyset$, it follows that $B \cap C \neq \emptyset$. This contradicts our assumption that $B_1 \cap C = \emptyset$. Therefore, $B_1 \in \mathcal{D}_{c}(G_1)$.

\smallskip

%\noindent\textbf{Case 2:} $G_1 = \mathcal{K}_{\abs{V_1}}$. In this case, by assumption of the lemma, we have $B_{1}\neq \emptyset$. Consequently, it follows that $B_1 \in \mathcal{D}_{c}(G_1)$. %reduces to proving that $B_1 \neq \emptyset$.

