\begin{lemma}
The set
\begin{equation}\label{grobner}
\mathcal{G}=\bigcup_{i < j} \left\{ u_{\pi} f_{i,j} \mid \pi \text{ is an admissible path in } C_n \text{ from } i \text{ to } j \right\} 
\cup \{ f_{n-2,n} f_{n,2} \}
\end{equation}
is a Gröbner basis of the ideal $J_{C_n} + (f_{n-2,n} f_{n,2})$ with respect to the order $<$.
\end{lemma}


\begin{proof}
Let $\mathcal{G}'$ denote the Gröbner basis of $J_{C_n}$ given in Equation~\eqref{grobner}. To verify that $\mathcal{G}$ is a Gröbner basis, we apply Buchberger's criterion and show that every $S$-pair $(f,h)$ with $f,h \in \mathcal{G}$ reduces to zero. We proceed by analyzing the possible pairs $(f,h)$.

\smallskip
\noindent\textbf{Case 1:} $f,h \in \mathcal{G}'$. Since $\mathcal{G}'$ is a Gröbner basis for $J_{C_n}$, the $S$-polynomial $S(f,h)$ reduces to zero.

\smallskip
\noindent\textbf{Case 2:} $f = f_{n-2,n} f_{n,2}$ and $h \in \mathcal{G}'$. Let $h = u_{\pi} f_{r,s}$, where $\pi$ is an admissible path from $r$ to $s$. Since every admissible path contains the vertex $n$, we have $n \in \pi$, and in particular either $n-1$ or $1$ must lie in $\pi$. Without loss of generality, suppose that $1 \in \pi$. The corresponding $S$-polynomial is
\begin{equation} \label{equation S expression 2}
S(f,h) = \frac{\mathrm{lcm}(\mathrm{in}_{<}(f), \mathrm{in}_{<}(h))}{\mathrm{in}_{<}(f)} \cdot f - \frac{\mathrm{lcm}(\mathrm{in}_{<}(f), \mathrm{in}_{<}(h))}{\mathrm{in}_{<}(h)} \cdot h.
\end{equation}
Since $1 \in \pi$, we know that either $x_1 \mid \mathrm{in}_{<}(h)$ or $y_1 \mid \mathrm{in}_{<}(h)$. As neither $x_1$ nor $y_1$ divides $\mathrm{in}_{<}(f)$, it follows that
\[
x_1 \mid \frac{\mathrm{lcm}(\mathrm{in}_{<}(f), \mathrm{in}_{<}(h))}{\mathrm{in}_{<}(f)} \quad \text{or} \quad y_1 \mid \frac{\mathrm{lcm}(\mathrm{in}_{<}(f), \mathrm{in}_{<}(h))}{\mathrm{in}_{<}(f)}.
\]
Since $f_{n,2} \mid f$, we obtain
\begin{equation} \label{in Jg 2}
f_{n,2} x_1 \mid \frac{\mathrm{lcm}(\mathrm{in}_{<}(f), \mathrm{in}_{<}(h))}{\mathrm{in}_{<}(f)} \cdot f \quad \text{or} \quad f_{n,2} y_1 \mid \frac{\mathrm{lcm}(\mathrm{in}_{<}(f), \mathrm{in}_{<}(h))}{\mathrm{in}_{<}(f)} \cdot f.
\end{equation}
Now, since $n$, $1$, and $2$ form a path in $C_n$, Proposition~\ref{grobner basis for JG}~(ii) implies that both $f_{n,2} x_1$ and $f_{n,2} y_1$ belong to $J_{C_n}$. Therefore, by \eqref{in Jg 2},
\[
\frac{\mathrm{lcm}(\mathrm{in}_{<}(f), \mathrm{in}_{<}(h))}{\mathrm{in}_{<}(f)} \cdot f \in J_{C_n}.
\]
Moreover, since $h \in J_{C_n}$, Equation~\eqref{equation S expression 2} shows that $S(f,h) \in J_{C_n}$. Finally, since $\mathcal{G}'$ is a Gröbner basis for $J_{C_n}$, it follows that $S(f,h)$ reduces to zero.
\end{proof}



