Applying Lemmas~\ref{saturation with xi} and~\ref{saturation with f}, we are now ready to establish a new lower bound for the localized v-number $\VCN$.


\begin{proposition}\label{bound interval 2}
Let $\mathcal{S} \in \min(C_n)$ with $\size{\mathcal{S}} \geq 3$. Then, we have the inequality
\[
\VCN \geq n - \size{\mathcal{S}}.
\]
\end{proposition}

\begin{proof}
To establish the result, assume that $(J_{C_n} : f) = P_{\mathcal{S}}$ for some homogeneous polynomial $f$, and we aim to show that $\deg(f) \geq n - \size{\mathcal{S}}$.

By Proposition~\ref{proposition dey}, we may assume $\mathrm{in}_{<}(f) \notin \mathrm{in}_{<}(J_{C_n})$. Since $f \in (J_{C_n} : P_{\mathcal{S}})$, it follows that $f \in (J_{C_n} : x_i)$ for every $i \in \mathcal{S}$. Consequently, by Lemma~\ref{saturation with xi}, we obtain
\[
\mathrm{in}_{<}(f) \in \mathrm{in}_{<}(J_{C_n}) + (x_{i-1}, y_{i-1}) \cdot (x_{i+1}, y_{i+1}).
\]
Using that $\mathrm{in}_{<}(f) \notin \mathrm{in}_{<}(J_{C_n})$, it follows that for each $i \in \mathcal{S}$, at least one of the following monomials divides $\mathrm{in}_{<}(f)$:
\[
x_{i-1}x_{i+1}, \quad x_{i-1}y_{i+1}, \quad y_{i-1}x_{i+1}, \quad y_{i-1}y_{i+1}.
\]
Hence, for every $\ell \in F$, we have
\begin{equation}\label{x y}
x_{\ell} \mid \mathrm{in}_{<}(f) \quad \text{or} \quad y_{\ell} \mid \mathrm{in}_{<}(f).
\end{equation}

Now consider any vertex $i \in [n] \setminus (\mathcal{S} \cup F)$. Since $f \in (J_{C_n} : P_{\mathcal{S}})$ and $f_{i-1,i+1} \in P_{\mathcal{S}}$, it follows that $f \in (J_{C_n} : f_{i-1,i+1})$. Consequently, by Lemma~\ref{saturation with f}, we obtain
\[
\mathrm{in}_{<}(f) \in \mathrm{in}_{<}(J_{C_n}) + (x_i, y_i) + \left( g_{C,D} \,\middle|\, C \cup D = [n] \setminus \{i-1, i, i+1\},\; C \cap D = \emptyset \right).
\]
Using again that $\mathrm{in}_{<}(f) \notin \mathrm{in}_{<}(J_{C_n})$, there are three possibilities: either $g_{C,D} \mid \mathrm{in}_{<}(f)$ for some partition $\{C,D\}$ of $[n] \setminus \{i-1, i, i+1\}$, or $x_i \mid \mathrm{in}_{<}(f)$ or $y_i \mid \mathrm{in}_{<}(f)$. In the first case, we obtain
\[
\deg(f) = \deg(\mathrm{in}_{<}(f)) \geq \deg(g_{C,D}) = n - 3 \geq n - \size{\mathcal{S}},
\]
since we are assuming $\size{\mathcal{S}}\geq 3$, which proves the statement. It remains to consider the other cases, where
\[
x_i \mid \mathrm{in}_{<}(f) \quad \text{or} \quad y_i \mid \mathrm{in}_{<}(f)
\]
for every $i \in [n] \setminus (\mathcal{S} \cup F)$. Together with~\eqref{x y}, we then have
\[
x_i \mid \mathrm{in}_{<}(f) \quad \text{or} \quad y_i \mid \mathrm{in}_{<}(f)
\]
for all $i \in [n] \setminus \mathcal{S}$. Consequently,
\[
\deg(f) = \deg(\mathrm{in}_{<}(f)) \geq n - \size{\mathcal{S}},
\]
as desired.
\end{proof}



By combining Propositions~\ref{bound interval} and~\ref{bound interval 2}, we obtain effective upper and lower bounds for the localized v-numbers, thereby limiting their possible values to a small number of cases.

\begin{proposition}\label{proposition localized v for Cn}
Let $\mathcal{S} \in \min(C_n)$ with $\size{\mathcal{S}} \geq 3$. Then the following holds:
\begin{enumerate}
\item[{\rm (i)}]\label{3} If $C_1(\mathcal{S}) = \emptyset$, then
\[
\VCN = n - \size{\mathcal{S}}.
\]
\item[{\rm (ii)}] If $\size{C_1(\mathcal{S})} = 1$, then
\[
n - \size{\mathcal{S}} \leq \VCN \leq n - \size{\mathcal{S}} + 1.
\]
\item[{\rm (iii)}] If $\size{C_1(\mathcal{S})} \geq 2$, then
\[
n - \size{C_2(\mathcal{S})} - 2 \leq \VCN \leq n - \size{C_2(\mathcal{S})}.
\]
\end{enumerate}
\end{proposition}



\begin{proof}
The upper bounds in each case follow from \textup{\cite[Theorem~4.7]{dey2024v}}, which gives $\VCN\leq n - \size{C_2(\mathcal{S})}$, and the fact that $\size{\mathcal{S}}=\size{C_1(\mathcal{S})}+\size{C_2(\mathcal{S})}$. The lower bounds in \textup{(i)} and \textup{(ii)} follow from Proposition~\ref{bound interval 2}, while that in \textup{(iii)} is a consequence of Proposition~\ref{bound interval}.
\end{proof}



We are now ready to present the main result of this section, which gives effective upper and lower bounds for the v-number of $C_n$. While this does not yield an explicit formula for $\VCNN$, it reduces its possible value to only two cases.



\begin{theorem}\label{main theorem 2}
The \textup{v}-number of $C_n$ satisfies the following:
\begin{enumerate}
\item[{\rm (i)}] If $n = 3k$, then $\VCNN = 2k$.
\item[{\rm (ii)}] If $n = 3k + 2$, then $\VCNN \in [2k + 1,\, 2k + 2]$.
\item[{\rm (iii)}] If $n = 3k + 1$, then $\VCNN \in [2k ,\, 2k + 1]$.
\end{enumerate}
\end{theorem}

\begin{proof}
We may assume that $n \geq 6$, as the statement holds for $n \leq 5$ by \textup{\cite[Propositions~4.8 and~4.9]{dey2024v}}. Using \textup{\cite[Corollary~4.10]{dey2024v}}, we obtain the upper bound $\VCNN \leq \textstyle \left\lceil \frac{2n}{3} \right\rceil$. Thus, it remains to establish the lower bounds: namely, that $\VCNN \geq \textstyle\left\lceil \frac{2n}{3} \right\rceil$ when $n \equiv 0 \pmod{3}$, and that $\VCNN \geq\textstyle \left\lceil \frac{2n}{3} \right\rceil - 1$ when $n \equiv 1,2 \pmod{3}$. To this end, we show that for every $\mathcal{S} \in \min(C_n)$, the localized v-number satisfies
\[
\VCN \geq 2k, \quad \VCN \geq 2k+1, \quad \text{or} \quad \VCN \geq 2k,
\]
according to whether $n = 3k$, $n = 3k+2$, or $n = 3k+1$, respectively.

For proving this, we will make repeated use of the following inequality, valid for any $\mathcal{S} \in \min(C_n)$:
\begin{equation}\label{equation with S}
n \geq \size{\mathcal{S}} + \size{C_{1}(\mathcal{S})} + 2\size{C_{2}(\mathcal{S})} = 3\size{\mathcal{S}} - \size{C_{1}(\mathcal{S})} = 2\size{C_{1}(\mathcal{S})} + 3\size{C_{2}(\mathcal{S})}.
\end{equation}

Moreover, if $\mathcal{S} = \emptyset$, it follows from \textup{\cite[Theorem~3.2]{jaramillo2024connected}} that $\VCN = n - 2$, and when $\abs{\mathcal{S}} = 2$, Theorem~\ref{main theorem} again gives $\VCN = n - 2$. Since we are assuming $n \geq 6$, we have $n - 2 \geq \left\lceil \tfrac{2n}{3} \right\rceil$. Thus, it suffices to consider the case where $\mathcal{S} \in \min(C_n)$ and $\abs{\mathcal{S}} \geq 3$.

\smallskip

\noindent
(i) When $n=3k$, we will show that $\VCN \geq 2k$ for every $\mathcal{S} \in \min(C_n)$ with $\abs{\mathcal{S}} \geq 3$, proceeding by cases:

\smallskip
\emph{Case 1: $\size{C_{1}(\mathcal{S})} \leq 1$.} Applying~\eqref{equation with S}, we obtain
\[
3k \geq 3\size{\mathcal{S}} - \size{C_{1}(\mathcal{S})} \geq 3\size{\mathcal{S}} - 1,
\]
which implies $\size{\mathcal{S}} \leq k$. Then, by Proposition~\ref{proposition localized v for Cn}~(i), (ii),
\[
\VCN \geq 3k - \size{\mathcal{S}} \geq 2k.
\]

\smallskip
\emph{Case 2: $\size{C_{1}(\mathcal{S})} \geq 2$.} Then~\eqref{equation with S} gives
\[
3k \geq 2\size{C_{1}(\mathcal{S})} + 3\size{C_{2}(\mathcal{S})} \geq 4 + 3\size{C_{2}(\mathcal{S})},
\]
yielding $\size{C_{2}(\mathcal{S})} \leq k - 2$. By Proposition~\ref{proposition localized v for Cn}~(iii),
\[
\VCN \geq 3k - \size{C_{2}(\mathcal{S})} - 2 \geq 2k.
\]

\smallskip
\noindent
(ii) When $n = 3k + 2$, we will show that $\VCN \geq 2k + 1$ for every $\mathcal{S} \in \min(C_n)$ with $\abs{\mathcal{S}} \geq 3$. We proceed as above.

\smallskip
\emph{Case 1: $\size{C_{1}(\mathcal{S})} \leq 1$.} Then~\eqref{equation with S} gives
\[
3k + 2 \geq 3\size{\mathcal{S}} - \size{C_{1}(\mathcal{S})} \geq 3\size{\mathcal{S}} - 1,
\]
hence $\size{\mathcal{S}} \leq k + 1$, and by Proposition~\ref{proposition localized v for Cn}~(i), (ii),
\[
\VCN \geq 3k + 2 - \size{\mathcal{S}} \geq 2k + 1.
\]

\smallskip
\emph{Case 2: $\size{C_{1}(\mathcal{S})} \geq 2$.} Then
\[
3k + 2 \geq 2\size{C_{1}(\mathcal{S})} + 3\size{C_{2}(\mathcal{S})} \geq 4 + 3\size{C_{2}(\mathcal{S})},
\]
so $\size{C_{2}(\mathcal{S})} \leq k - 1$. Proposition~\ref{proposition localized v for Cn}~(iii) then gives
\[
\VCN \geq 3k + 2 - \size{C_{2}(\mathcal{S})} - 2 \geq 2k + 1.
\]

\smallskip
\noindent
(iii) When $n = 3k + 1$, we will prove that $\VCN \geq 2k$ for every $\mathcal{S} \in \min(C_n)$ with $\abs{\mathcal{S}} \geq 3$.

\smallskip
\emph{Case 1: $\size{C_{1}(\mathcal{S})} \leq 1$.} Then~\eqref{equation with S} yields
\[
3k + 1 \geq 3\size{\mathcal{S}} - \size{C_{1}(\mathcal{S})} \geq 3\size{\mathcal{S}} - 1,
\]
so $\size{\mathcal{S}} \leq k$, and Proposition~\ref{proposition localized v for Cn}~(i), (ii) gives
\[
\VCN \geq 3k + 1 - \size{\mathcal{S}} \geq 2k.
\]

\smallskip
\emph{Case 2: $\size{C_{1}(\mathcal{S})} \geq 2$.} Then
\[
3k + 1 \geq 2\size{C_{1}(\mathcal{S})} + 3\size{C_{2}(\mathcal{S})} \geq 4 + 3\size{C_{2}(\mathcal{S})},
\]
implying $\size{C_{2}(\mathcal{S})} \leq k - 1$. Proposition~\ref{proposition localized v for Cn}~(iii) then ensures
\[
\VCN \geq 3k + 1 - \size{C_{2}(\mathcal{S})} - 2 \geq 2k. \qedhere
\]
\end{proof}






