\section{Minimal bounds on cooperativity and rates for the existence of bistability in auto-activation}

The auto-activation system can exhibit bistability, meaning that it can reach different steady states depending on the initial condition. However, this behavior arises only within a restricted range of parameter values, shown in Fig.~\ref{fig:autoactivation_ccmin_ccmax_sweep} as the red region. To investigate the conditions for which multiple different steady states are possible, we derive analytic bounds in parameter space. Setting $d\bar{A}/d\bar{t} = 0$ and re-expressing in standard polynomial form, $\bar{A}$ must satisfy
\begin{align}
    \omega p_\text{act}^ 2 \bar{A}^3 + p_\text{act}(2-\omega \bar{r}_2p_\text{act})\bar{A}^2+(1-2\bar{r}_1p_\text{act})\bar{A} - \bar{r}_0=0.
    \label{eq:auto_activation_steady_state_polynomial}
\end{align}

If the system exhibits bistability, the corresponding polynomial must have three real roots, as a third-order polynomial cannot have exactly two. Physically, these roots correspond to two stable steady states and one unstable steady state. Further, the presence of only one real root indicates that the system is monostable, as discussed in Appendix~\ref{appendix:auto_activation_more_theorem}.

To identify conditions for bistability, we search for combinations of $\omega$, $\bar{r}{0}$, $\bar{r}{1}$, $\bar{r}_{2}$, and effector concentration $c$ that produce three positive real roots of the polynomial—corresponding to the red region in Fig.~\ref{fig:autoactivation_ccmin_ccmax_sweep}. We may bound this bistable region of parameter space analytically using Descartes' rule of signs, which states that for a single-variable polynomial with real coefficients, the number of positive roots of the polynomial is equal to the number of sign changes between consecutive non-zero coefficients minus an even number. In our case, the polynomial in Eqn.~\ref{eq:auto_activation_steady_state_polynomial} must then have either one or three sign changes. Therefore, three sign changes are necessary for the system to allow bistability.  Evaluating Eqn.~\ref{eq:auto_activation_steady_state_polynomial}, we observe that the coefficient of $\bar{A}^3$ is strictly positive and the constant term is strictly negative. Thus, three (consecutive) coefficient sign changes are only possible if the second term of Eqn.~\ref{eq:auto_activation_steady_state_polynomial} is negative, and the third term of that same equation is positive. Specifically, the condition on the second term implies that
\begin{equation}
    p_\text{act}(c)\Big(2-\omega \bar{r}_2p_\text{act}(c)\Big) < 0 \implies p_\text{act}(c) > \frac{2}{\omega \bar{r}_2},
\end{equation}
while the condition on the second term leads to
\begin{equation}
    1-2\bar{r}_1p_\text{act}(c) > 0 \implies p_\text{act}(c) < \frac{1}{2\bar{r}_1}.
\end{equation}
% \begin{align}
% \begin{split}
%     p_\text{act}(c)\Big(2-\omega \bar{r}_2p_\text{act}(c)\Big) < 0 &\implies p_\text{act}(c) > \frac{2}{\omega \bar{r}_2} \\
%     1-2\bar{r}_1p_\text{act}(c) > 0 &\implies p_\text{act}(c) < \frac{1}{2\bar{r}_1},
% \end{split}
% \end{align}
Thus, these two conditions can be combined to yield
\begin{equation}
    \frac{2}{\omega \bar{r}_2} < p_\text{act}(c) < \frac{1}{2\bar{r}_1}. \label{eq:pactboundrange}
\end{equation}

\subsection{Necessary condition for bistability at some effector concentration $c$}
\label{appendix:autoact_derivation_of_descartes_bound}
Note that if the above condition were to be true at all possible effector concentrations $c$, the system would always be bistable. Rather, we are more specifically interested in the conditions that would allow bistability for at least one value of effector concentration $c_0$. In other words, there exists a concentration such that
\begin{equation}
   \frac{2}{\omega \bar{r}_2} <p_\text{act}(c_0)\label{eq:descartes_min_max1}
\end{equation}
and
\begin{equation}
    \frac{1}{2 \bar{r}_1} >p_\text{act}(c_0).
    \label{eq:descartes_min_max2}
\end{equation}
If the inequality in Eqn.~\ref{eq:descartes_min_max1} holds true, then we also know that
\begin{equation}
    \frac{2}{\omega \bar{r}_2} <p_\text{act}(c_0) \leq \max_{c\in[0,\infty]}[p_\text{act}(c)].
\end{equation}
This result itself then directly requires the existence of some effector concentration for which Eqn.~\ref{eq:descartes_min_max1} is true. We can prove this by considering two possible cases. First, if
\begin{equation}
    \frac{2}{\omega\bar{r}_{2}} < \min_{c\in[0,\infty]}[p_\text{act}(c)] < \max_{c\in[0,\infty]}[p_\text{act}(c)],
\end{equation}
then we know that Eqn.~\ref{eq:descartes_min_max1} holds true for all concentrations $c\geq 0$. Otherwise, if
\begin{equation}
    \min_{c\in[0,\infty]}[p_\text{act}(c)] < \frac{2}{\omega\bar{r}_{2}} < \max_{c\in[0,\infty]}[p_\text{act}(c)],
\end{equation}
then Eqn.~\ref{eq:descartes_min_max1} is true for all non-negative effector concentrations smaller than a threshold concentration
\begin{equation}
    c^* = p^{-1}_\text{act}\Big(\frac{2}{\omega\bar{r}_{2}}\Big),
\end{equation}
(derived from the inverse of Eqn.~\ref{eq:descartes_min_max1}) because $p_\text{act}$ is a continuous and monotonically decreasing function.

Applying similar logic to the inequality in Eqn.~\ref{eq:descartes_min_max2}, we may thus rewrite the necessary conditions for bistability in Eqns.~\ref{eq:descartes_min_max1} and ~\ref{eq:descartes_min_max2} as
\begin{eqnarray}
   \frac{2}{\omega \bar{r}_2} &<& \max_{c \in [0, \infty]} \left( p_\text{act}(c) \right) = \frac{1}{1+e^{-\beta \varepsilon}}, \label{eq:pactboundintermed1}\\
   \frac{1}{2 \bar{r}_1} &>& \min_{c \in [0, \infty]} \left( p_\text{act}(c) \right) =\frac{1}{1+e^{-\beta \varepsilon}\bar{K}_c^2}, \label{eq:pactboundintermed2}
\end{eqnarray}
and
\begin{equation}
   \omega \bar{r_2}> 4\bar{r_1},
    \label{eq:pactboundintermed3}
\end{equation}
where we have recalled the saturation (maximum) and leakiness (minimum) of $p_\text{act}(c)$ defined in Eqns.~\ref{eq:pact_limit1} and ~\ref{eq:pact_limit2}.
Note that we are in a setting where effector binding stabilizes the inactive form of the activator such that $\bar{K}_c=K_A/K_I>1$.
This fixes the values of saturation and leakiness, which would otherwise be switched if $K_c<1$. After some algebra, we can re-express Eqns.~\ref{eq:pactboundintermed1} and ~\ref{eq:pactboundintermed2} such that the necessary conditions for bistability are given by
\begin{eqnarray}
    \frac{\omega \bar{r}_2}{2} &>& 1 + e^{-\beta \varepsilon},\label{eq:bistabconds1}\\
    1 + e^{-\beta \varepsilon}\bar{K}_c^2 &>& 2 \bar{r}_1,\label{eq:bistabconds2}
\end{eqnarray}
and
\begin{equation}
    \omega \bar{r}_2>4\bar{r}_1. \label{eq:bistabconds3}
\end{equation}
Following a similar procedure as in the previous section,  in the next section we derive a necessary condition for bistability that depends on the concentration of effector $c$. For fixed parameter values, this condition defines a bounded range of effector concentrations outside of which the system is guaranteed to be monostable.

\subsection{Necessary condition for bistability for a fixed concentration of effector $c$}
\label{appendix:descart_for_c_auto_act}

We consider the case where the activation probability $p_\text{act}(c)$ is a decreasing function of the effector concentration $c$, as seen in Fig.~\ref{fig:pact}. This monotonicity condition, which requires the derivative of the probability function to be negative for all possible $c$, depends on the parameters of the model, particularly the ratio of dissociation constants $\bar{K}_c$. The derivative of $p_\text{act}(c)$ with respect to $c$ is given from Eqn.~\ref{eqn:MWC2site} by
\begin{equation}
\frac{dp_\text{act}}{dc} = -\frac{2 (1 + c/K_A) e^{\beta \varepsilon} (-1 + \bar{K}_c)(1 + c/K_I)}{\left( (1 + c/K_A)^2 e^{\beta \varepsilon} + (1 + c/K_I)^2 \right)^2},
\end{equation}
which is negative for all $c > 0$ if and only if $\bar{K}_c > 1$. 

Recalling the previously-derived necessary condition for bistability,
\begin{equation}
\frac{2}{\omega \bar{r}_2} < p_\text{act}(c) < \frac{1}{2\bar{r}_1},
\end{equation}
we now investigate what constraint this condition imposes on the effector concentration $c$, assuming the parameters of the system are fixed. First, the inequality
\begin{equation}
    p_\text{act}(c) < \frac{1}{2\bar{r}_1} \label{eq:B2bound1}
\end{equation}
can be re-expressed equivalently using the explicit expression of $p_{\text{act}}(c)$ in Eqn.~\ref{eqn:MWC2site} as
\begin{align}
\displaystyle g(c) =\; &\left(\frac{c}{K_A}\right)^2\frac{1}{1+e^{-\beta \varepsilon}}\left[\frac{1}{2\bar{r}_1}-\frac{1}{1+e^{-\beta \varepsilon}\bar{K}_c^2}\right]\nonumber \\
&+ 2\frac{c}{K_A}\frac{\frac{1}{2\bar{r}_1}(1+e^{-\beta \varepsilon}\bar{K}_c)-1}{(1+e^{-\beta \varepsilon})(1+e^{-\beta \varepsilon}\bar{K}_c^2)} \nonumber \\
&+ \left[\frac{1}{2\bar{r}_1}-\frac{1}{1+e^{-\beta \varepsilon}}\right]\frac{1}{1+e^{-\beta \varepsilon}\bar{K}_c^2} > 0.
\end{align}
Similarly, the condition 
\begin{equation}
    p_\text{act}(c) > \frac{2}{\omega \bar{r}_2} \label{eq:B2bound1}
\end{equation}
is equivalent to requiring that
\begin{align}
h(c) =\; &\left(\frac{c}{K_A}\right)^2\frac{1}{1+e^{-\beta \varepsilon}}\left[\frac{2}{\omega \bar{r}_2}-\frac{1}{1+e^{-\beta \varepsilon}\bar{K}_c^2}\right] \\
&+ 2\frac{c}{K_A}\frac{\frac{2}{\omega \bar{r}_2}(1+e^{-\beta \varepsilon}\bar{K}_c)-1}{(1+e^{-\beta \varepsilon})(1+e^{-\beta \varepsilon}\bar{K}_c^2)} \nonumber \\
&+ \left[\frac{2}{\omega \bar{r}_2}-\frac{1}{1+e^{-\beta \varepsilon}}\right]\frac{1}{1+e^{-\beta \varepsilon}\bar{K}_c^2} < 0. \nonumber
\end{align}

We can now apply Descartes’ Rule of Signs to the polynomials $g(c)$ and $h(c)$ to determine when the inequalities are satisfied. Since we are working under the assumption that $\bar{K}_c > 1$, this means that,
\begin{equation}
p_\text{act}^{\text{max}} = \frac{1}{1+e^{-\beta \varepsilon}} > \frac{1}{1+e^{-\beta \varepsilon} \bar{K}_c} > \frac{1}{1+e^{-\beta \varepsilon} \bar{K}_c^2} = p_\text{act}^{\text{min}}.
\end{equation}
For the polynomial $g(c)$, three cases then arise. First, if
\begin{equation}
    \frac{1}{2\bar{r}_1} > \frac{1}{1+e^{-\beta \varepsilon}},
\end{equation}
then all coefficients of $g(c)$ are positive and $g(c) > 0$ for all $c \geq 0$, so Eqn.~\ref{eq:B2bound1} is always satisfied. Second, if
\begin{equation}
    \frac{1}{2\bar{r}_1} > \frac{1}{1+e^{-\beta \varepsilon} \bar{K}_c^2},
\end{equation}
then all coefficients are negative, and the condition is never satisfied for any $c$. Finally, if the intermediate case
\begin{equation}
\frac{1}{1 + e^{-\beta \varepsilon} \bar{K}_c} > \frac{1}{2\bar{r}_1} > \frac{1}{1 + e^{-\beta \varepsilon} \bar{K}_c^2}
\end{equation}
holds, then the coefficient of the term proportional to $c^2$ in $g(c)$ is positive, while those of the remaining terms proportional to $c^1$ and $c^0$ are negative. This results in exactly one sign change, so by Descartes’ Rule of Signs, the polynomial $g(c)$ has exactly one positive root. This defines the minimal concentration for bistability, denoted $c_{\text{bistab}}^{\min}(\bar{r}_1)$, and given by
{\footnotesize
\begin{equation}
c_{\text{bistab}}^{\min}(\bar{r}_1) = K_A
\frac{e^{-\beta \varepsilon} \bar{K}_c + 2\bar{r}_1 - 1 + \sqrt{e^{-\beta \varepsilon} (1 + \bar{K}_c)^2 (2\bar{r}_1 - 1)}}{e^{-\beta \varepsilon} \bar{K}_c^2 - 2\bar{r}_1 + 1}.
\end{equation}}
Under these conditions, the inequality $g(c) > 0$ holds for all $c > c_{\text{bistab}}^{\min}(\bar{r}_1)$.

We now turn to the polynomial $h(c)$. If
\begin{equation}
    \frac{2}{\omega \bar{r}_2} > \frac{1}{1 + e^{-\beta \varepsilon}},
\end{equation}
then all coefficients are positive and the polynomial is strictly positive for all $c$, meaning that the condition in Eqn.~\ref{eq:B2bound1} is never satisfied. Conversely, if 
\begin{equation}
    \frac{2}{\omega \bar{r}_2} < \frac{1}{1 + e^{-\beta \varepsilon} \bar{K}_c^2},
\end{equation}
then all coefficients are negative and the condition is always satisfied. Lastly, in the intermediate case
\begin{equation}
\frac{1}{1 + e^{-\beta \varepsilon} \bar{K}_c} > \frac{2}{\omega \bar{r}_2} > \frac{1}{1 + e^{-\beta \varepsilon} \bar{K}_c^2},
\end{equation}
Descartes’ Rule of Signs again implies exactly one positive root of $h(c)$, corresponding to the upper bound of the bistable region. This upper concentration threshold is denoted $c_{\text{bistab}}^{\max}(\omega \bar{r}_2)$ and given by
{\footnotesize
\begin{equation}
c_{\text{bistab}}^{\max}(\omega \bar{r}_2) = K_A
\frac{e^{-\beta \varepsilon} \bar{K}_c + \frac{\omega \bar{r}_2}{2} - 1 + \sqrt{e^{-\beta \varepsilon} (1 + \bar{K}_c)^2 \left( \frac{\omega \bar{r}_2}{2} - 1 \right)}}{e^{-\beta \varepsilon} \bar{K}_c^2 - \frac{\omega \bar{r}_2}{2} + 1}.
\end{equation}}
Under these conditions, the inequality $h(c) < 0$ holds for all $c < c_{\text{bistab}}^{\max}(\omega \bar{r}_2)$.

Summing up the case-by-case analysis, we derive an effector concentration-dependent necessary condition for bistability. The full set of conditions allowing for bistability in different ranges of effector concentrations is given by
\begin{equation}
    \begin{cases}
    c_{\text{bistab}}^{\max} > c > c_{\text{bistab}}^{\min} & \text{if } \frac{1}{1 + e^{-\beta \varepsilon} \bar{K}_c^2} < \frac{2}{\omega \bar{r}_2} < \frac{1}{2\bar{r}_1} < \frac{1}{1 + e^{-\beta \varepsilon}}, \\
    c_{\text{bistab}}^{\max} > c & \text{if } \frac{1}{1 + e^{-\beta \varepsilon} \bar{K}_c^2} < \frac{2}{\omega \bar{r}_2} < \frac{1}{1 + e^{-\beta \varepsilon}} < \frac{1}{2\bar{r}_1}, \\
    c > c_{\text{bistab}}^{\min} & \text{if } \frac{2}{\omega \bar{r}_2} < \frac{1}{1 + e^{-\beta \varepsilon} \bar{K}_c^2} < \frac{1}{2\bar{r}_1} < \frac{1}{1 + e^{-\beta \varepsilon}}, \\
    c \geq 0 & \text{if } \frac{2}{\omega \bar{r}_2} < \frac{1}{1 + e^{-\beta \varepsilon} \bar{K}_c^2} < \frac{1}{1 + e^{-\beta \varepsilon}} < \frac{1}{2\bar{r}_1}, \\
    \text{no bistability} & \text{if } \frac{2}{\omega \bar{r}_2} > \frac{1}{1 + e^{-\beta \varepsilon}} \text{ or } \frac{1}{1 + e^{-\beta \varepsilon} \bar{K}_c^2} > \frac{1}{2\bar{r}_1}.
    \end{cases}
    \label{eq:auto_act_all_decartes}
\end{equation}

As noted, the parameter $\bar{r}_0$ does not enter into these Descartes-based bounds and thus does not influence the existence of bistability in this analysis. From these expressions, we recover the necessary conditions for bistability, stated in the previous section as
\begin{equation}
    \frac{2}{\omega \bar{r}_2} < \frac{1}{1 + e^{-\beta \varepsilon}},
\end{equation}
\begin{equation}
    \frac{1}{1 + e^{-\beta \varepsilon} \bar{K}_c^2} < \frac{1}{2\bar{r}_1},
\end{equation}
and
\begin{equation}
    \frac{2}{\omega r_2} < \frac{1}{2\bar{r}_1}.
\end{equation}
and re-expressed in Eqns.~\ref{eq:bistabconds_final1}-~\ref{eq:bistabconds_final3}.
\begin{figure*}[t]
    \centering
    \includegraphics[width=\linewidth]{Figures/Fig28.pdf}
