\section{Auto-activation : Bistability is possible for non cooperative systems ($\omega=1$).}
\label{appendix:auto_act_bistab_low_coop}
\subsection{Definition of the effective Hill coefficient}
\label{appendix:def_of_hill}
We first recall how to compute the Hill coefficient of an activating Hill function with constitutive expression, denoted $g(x)$, defined by
\begin{equation}
    g(x) = \frac{\bar{r}_0 + \bar{r}_2 x^n}{1 + x^n}.
\end{equation}
Its log-derivative is
\begin{equation}
    \frac{d \ln g}{d \ln x} = n \cdot \frac{x^n (\bar{r}_2 - \bar{r}_0)}{(1 + x^n)(\bar{r}_0 + \bar{r}_2 x^n)}.
\end{equation}
Let us define $x^*$ such that
\begin{equation}
    g(x^*) = \frac{\bar{r}_2 + \bar{r}_0}{2}.
\end{equation}
This holds for $x^* = 1$. Evaluating the derivative at this value then gives
\begin{equation}
    \left. \frac{d \ln g}{d \ln x} \right|_{x = x^*} = \frac{1}{2}n \cdot \frac{\bar{r}_2 - \bar{r}_0}{\bar{r}_2 + \bar{r}_0},
\end{equation}
and solving for $n$, we obtain
\begin{equation}
    n = \left. \frac{d \ln g}{d \ln x} \right|_{x = x^*} \cdot 2 \frac{\bar{r}_2 + \bar{r}_0}{\bar{r}_0 - \bar{r}_2}.
\end{equation}

We now define a similar expression for a thermodynamic model $w(x)$ given by
\begin{equation}
    w(x) = \frac{\bar{r}_0 + 2\bar{r}_1 p_{\text{act}} x + \omega \bar{r}_2 p_{\text{act}}^2 x^2}{1 + 2p_{\text{act}} x + \omega p_{\text{act}}^2 x^2}.
\end{equation}
We observe that $w(x)$ can be written as $\hat{w}(p_{\text{act}}x)$ with
\begin{equation}
    \hat{w}(\hat{x}) = \frac{\bar{r}_0 + 2\bar{r}_1 \hat{x} + \omega \bar{r}_2 \hat{x}^2}{1 + 2h \hat{x} + \omega \hat{x}^2},
\end{equation}
where $h=1$ in our case. Since $d \ln w/d \ln x = d \ln \hat{w}/d \ln \hat{x}$ when $h=1$, the effective Hill coefficient does not depend on $p_{\text{act}}$. The derivative of $\hat{w}$ is
\begin{equation}
    \frac{d \ln \hat{w}}{d \ln \hat{x}} = \frac{2(1 + h \hat{x})}{1 + \hat{x}(2h + \omega \hat{x})} - \frac{2(\bar{r}_0 + \bar{r}_1 \hat{x})}{\bar{r}_0 + \hat{x}(2\bar{r}_1 + \omega \bar{r}_2 \hat{x})}.
\end{equation}
Letting $\hat{x}^*$ be defined by $\hat{w}(\hat{x}^*) = \frac{\bar{r}_2 + \bar{r}_0}{2}$ yields
\begin{equation}
    \hat{x}^* = \frac{-h \bar{r}_0 + 2 \bar{r}_1 - h \bar{r}_2}{(\bar{r}_0 - \bar{r}_2) \omega} + \sqrt{S},
\end{equation}
where
\begin{equation}
S = \frac{
\splitfrac{\textstyle h^2 \bar{r}_0^2 - 4 h \bar{r}_0 \bar{r}_1 + 4 \bar{r}_1^2 + 2 h^2 \bar{r}_0 \bar{r}_2}
          {\textstyle - 4 h \bar{r}_1 \bar{r}_2 + h^2 \bar{r}_2^2 + \bar{r}_0^2 \omega - 2 \bar{r}_0 \bar{r}_2 \omega + \bar{r}_2^2 \omega}
}{
(\bar{r}_0 - \bar{r}_2)^2 \omega^2}.
\end{equation}
This then gives the derivative at $\hat{x}^*$ as
\begin{equation}
\frac{d \ln \hat{w}}{d \ln \hat{x}} \bigg|_{\hat{x} = \hat{x}^*} = \frac{\bar{r}_2 - \bar{r}_0}{\bar{r}_2 + \bar{r}_0} \cdot \frac{(h(\bar{r}_0 + \bar{r}_2) - 2\bar{r}_1) u + t}{(2h \bar{r}_2 - 2\bar{r}_1) u + t},
\label{eq:dlnwhatdlnx}
\end{equation}
with
\begin{equation}
\begin{cases}
\alpha = \sqrt{\frac{(-2\bar{r}_1 + h(\bar{r}_0 + \bar{r}_2))^2}{(\bar{r}_0 - \bar{r}_2)^2} + 4\omega}, \\
u = -2\bar{r}_1 + h(\bar{r}_0 + \bar{r}_2) + (-\bar{r}_0 + \bar{r}_2) \alpha, \\
t = 4(\bar{r}_0 - \bar{r}_2)^2 \omega.
\end{cases}
\end{equation}

We defined $\hat{w}$ with an extra parameter $h$ to allow a mapping between the thermodynamic model and the Hill function. For the Hill case, we set $h = 0$, $\bar{r}_1 = 0$, and $\omega = 1$. In our thermodynamic model, $h = 1$ and the expression of Eqn.~\ref{eq:dlnwhatdlnx} becomes
\begin{equation}
\frac{d \ln \hat{w}}{d \ln \hat{x}} \bigg|_{\hat{x} = \hat{x}^*} = \frac{\bar{r}_2 - \bar{r}_0}{\bar{r}_2 + \bar{r}_0} \cdot \frac{(\bar{r}_0 + \bar{r}_2 - 2\bar{r}_1) u + t}{(2\bar{r}_2 - 2\bar{r}_1) u + t},
\label{eq:dlnwdlnxheq1}
\end{equation}
with
\begin{equation}
\begin{cases}
\alpha = \sqrt{\frac{(-2\bar{r}_1 + \bar{r}_0 + \bar{r}_2)^2}{(\bar{r}_0 - \bar{r}_2)^2} + 4\omega}, \\
u = -2\bar{r}_1 + \bar{r}_0 + \bar{r}_2 + (-\bar{r}_0 + \bar{r}_2) \alpha, \\
t = 4(\bar{r}_0 - \bar{r}_2)^2 \omega.
\label{eq:alpha_u_t_heq1}
\end{cases}
\end{equation}

To ensure consistency with the Hill model case, we therefore define the effective Hill coefficient as
\begin{equation}
    n_{\text{eff}} = \left. \frac{d \ln w}{d \ln x} \right|_{x = x^*} \cdot 2 \frac{\bar{r}_2 + \bar{r}_0}{\bar{r}_2 - \bar{r}_0}\label{appendix:neff}
\end{equation}
for
\begin{equation}
    w(x) = \frac{\bar{r}_0 + 2\bar{r}_1 p_{\text{act}} x + \omega \bar{r}_2 p_{\text{act}} x^2}{1 + 2 p_{\text{act}} x + \omega p_{\text{act}} x^2}
\end{equation}
and $x^*$ defined such that
\begin{equation}
    w(x^*) = \frac{\bar{r}_2 + \bar{r}_0}{2}.
    \label{eq:w_half_value}
\end{equation}

We note that for the auto activation system, in which $\bar{r}_0\leq\bar{r}_1\leq\bar{r}_2$, having an effective Hill coefficient larger than unity ($n_{eff}>1$) is equivalent to 
\begin{equation}
   \omega>\frac{(\bar{r}_1-\bar{r}_0)(\bar{r}_2-\bar{r}_1)}{(\bar{r}_2-\bar{r}_0)^2}. 
\end{equation}
Therefore, depending on the parameters of the system, the effective Hill coefficient can be larger or smaller than one, despite the activator having two binding sites.

% We can also prove than if there exist a value $x$ for which the function, $\frac{d \ln \hat{\omega}}{d \ln \hat{x}}$ is bigger than one, then the auto-activation system is necessarily bistable. Indeed let's study the function $h: \hat{x}\to \frac{d \ln \hat{\omega}}{d \ln \hat{x}} -1$. We notice that $h(0)=0$ and $\displaystyle\lim _{x\to \infty}h(x)=0$. Therefore, the intermediate value theorem applied twice shows that if there exist a positive value of $h(\hat{x})$ for a given positive $\hat{x}$, then the function $h$ vanishes twice. 

\subsection{Numerical sweep for minimal cooperativity above which there is bistability.}
