\section{Separatrix for mutual repression}
\label{appendix:sep_mut_rep}

We recall the differential equations governing the mutual repression system,
\begin{align}
\label{eq:mutRep1}
    \frac{d\bar{R}_{1}}{d\bar{t}} &= - \bar{R}_{1} + \bar{r}\frac{1}{1 + 2p_\text{act}(c_2)\bar{R}_{2} + \omega_2 \left[p_\text{act}(c_2)\bar{R}_{2} \right]^2} \nonumber\\
    &= F(\bar{R}_1,\bar{R}_2),
\end{align}
\begin{align}
    \frac{d\bar{R}_{2}}{d\bar{t}} &= - \bar{R}_{2} + \bar{r}\frac{1}{1 + 2p_\text{act}(c_1)\frac{\bar{R}_{1}}{\bar{K}} + \omega_1 \left[p_\text{act}(c_1)\frac{\bar{R}_{1}}{\bar{K}}\right]^2} \nonumber\\
    &= G(\bar{R}_1,\bar{R}_2).\label{eq:mutRep2}
\end{align}

The separatrix is defined as the curve $\bar{R}_2(\bar{R}_1)$ that satisfies the differential equation
\begin{equation}
    \frac{d\bar{R}_2}{d\bar{R}_1} = \frac{G(\bar{R}_1,\bar{R}_2)}{F(\bar{R}_1,\bar{R}_2)},
\end{equation}
which tracks the trajectory along which the system transitions between the basins of attraction of the two stable steady states.

