\begin{prop}[Steadiness of the Hammersley process with sources/sinks]\label{prop:Stationnaire<}
For every $t>0$, $\alpha>0$, let $(H^{(\alpha)}(i))_{i\geq 0}$ be the Hammersley process defined as $H$ with the following sets of sources and sinks.
\begin{itemize}
\item The set $H^{(\alpha)}(0)$ of sources is distributed according to a homogeneous PPP with intensity $\alpha$ on $[0,t]\times \{0\}$;
\item Let $I^{(\alpha)}_1,I^{(\alpha)}_2,\dots$ be a sequence of independent Bernoulli random variable where each $I_i$ has mean $p_i/(p_i+\alpha)$. Then we put a sink at position $(0,i)$ for each $i$ such that $I^{(\alpha)}_i=1$.
\item Sources, sinks, and $\Pi_n$ are independent. 
\end{itemize}
Then:
\begin{itemize}
\item[(i)]({\bf Bottom-to-top steadiness.}) For every $i$, the configuration
$H^{(\alpha)}(i)$ is a PPP with mean $\alpha$.
\item[(ii)]({\bf Left-to-right stationarity.}) Set $J^{(\alpha)}_i=1$ if a particle is created at time $i$, $J^{(\alpha)}_i=0$ otherwise. Then 
$$
(J^{(\alpha)}_1,J^{(\alpha)}_2,\dots ) \stackrel{\text{(d)}}{=} (I^{(\alpha)}_1,I^{(\alpha)}_2,\dots )
\stackrel{\text{(d)}}{=}
\mathrm{Bernoulli}(\tfrac{p_1}{p_1+\alpha})\otimes
\mathrm{Bernoulli}(\tfrac{p_2}{p_2+\alpha})\otimes \dots
$$
\end{itemize}
\end{prop}


