\begin{proof}[Proof of Proposition \ref{prop:Stationnaire<}]

By induction it suffices to prove the proposition for $i=1$. 
Consider the process $(Z_1(x))_{0\leq x\leq t}$ defined by
$$
Z_1(x)=
\begin{cases}
 1&\text{if a Hammersley line touches }(x^+,1),\\
 0&\text{otherwise.}
 \end{cases}
$$

We regard $(Z_1(x))_{0\leq x\leq t}$ as a random process with time going from left to right. 
The initial value $Z_1(0)$ is equal to one if and only if there is a sink at $(0,1)$, which happens with probability $p_1/(p_1+\alpha)$. The process $(Z_1(x))_{0\leq x\leq t}$ is a continuous time Markov chain in $\set{0,1}$ with with '$+1$ rate' equal to $p_1$ and '$-1$ rate' equal to $\alpha$ (see a \cref{fig:ProcessH}). 
The Bernoulli$(p_1/(p_1+\alpha))$ distribution is stationary for this Markov chain, so that $(Z_1(x))_{0\leq x\leq t}$ is a stationary continuous-time Markov chain.

The configuration $H^{(\alpha)}(1)$  is given  by the union of (i) "$+1$ steps" of the process $Z_1$ and (ii) the points of $H^{(\alpha)}(0)$ that do not correspond to a '$-1$' jump (look at $\star$'s in \cref{fig:ProcessH}). It remains to prove that this set is distributed as a homogeneous PPP with intensity $\alpha$. This will follow from the following Lemma.

\begin{figure}
\begin{center}
\includegraphics[width=130mm]{Figures/ProcessHGeneral.pdf} 
\end{center}
\caption{Notation of Lemma \ref{lem:Burke}. Points of $Q=Q_0\cup Q_1$ are depicted with $\star$'s. (Green $\star$'s correspond to $Q_0$, the brown $\star$ corresponds to $Q_1$.)}
\label{fig:H}
\end{figure}


\begin{lem}\label{lem:Burke}
%Let $\beta>\lambda>0$ be fixed parameters. 
 (The reader is invited to look at Fig.\ref{fig:H} for notation.)\\
Let $t> 0$. Let $Q_\nearrow,Q_\searrow$ be two independent homogeneous PPP over $(0,t)$ with respective intensities $p,\alpha>0$. Let $(\mathcal{Z}_x)_{0\leq x\leq t}$ be the continuous-time Markov process with values in $\set{0,1}$ such that
\begin{itemize}
    \item $\mathcal{Z}_0$ is  independent from $Q_\nearrow,Q_\searrow$ and drawn accordingly to a Bernoulli$(p/(p+\alpha))$;
    \item If $\mathcal{Z}_{x^-}=0$ and $x\in Q_\nearrow$ then $\mathcal{Z}_{x}=1$;
    \item If $\mathcal{Z}_{x^-}=1$ and $x\in Q_\searrow$ then $\mathcal{Z}_{x}=0$.
\end{itemize}
(In words  '+1' jumps are given by $Q_\nearrow$ and its '-1' jumps are given by $Q_\searrow$.)

Let $Q_0,Q_1$ be respective point processes given by \emph{unused} "$-1$ jumps" and \emph{used} "$+1$ jumps":
$$
Q_0=\set{x\in Q_\searrow\text{ such that } \mathcal{Z}_{x^-}=0},\qquad 
Q_1=\set{x\in Q_\nearrow\text{ such that } \mathcal{Z}_{x^-}=0}.
$$
Then:
\begin{itemize}
    \item[(i)] the process $Q:=Q_0\cup Q_1$ is a homogeneous PPP with intensity $\alpha$;
    \item[(ii)] $\mathcal{Z}_{t}\in\set{0,1}$ is a $\mathrm{Bernoulli}(p/(p+\alpha))$ independent from the point process $Q$.
\end{itemize}
\end{lem}

\begin{proof}[Proof of Lemma \ref{lem:Burke}]
The point process $Q_\nearrow\cup Q_\searrow$ is a homogeneous PPP with intensity $p+\alpha$, independent from $\mathcal{Z}_0$. We claim that $Q$ is a subset of $Q_\nearrow\cup Q_\searrow$ where each point in  $Q_\nearrow\cup Q_\searrow$ is taken independently with probability $\alpha/(p+\alpha)$, it is therefore a homogeneous  PPP with intensity $\alpha$, as required. 

We need a few notation in order to prove the claim. Set $P_0=0$ and for $i\geq 1$ let $P_i$ be the $i$-th leftmost point of $Q_\nearrow\cup Q_\searrow$ and let $(\widetilde{\mathcal{Z}}_i)_{i\geq 0}$ be the discrete-time embedded chain associated to $\mathcal{Z}$, \emph{i.e.} $\widetilde{\mathcal{Z}}_i=\mathcal{Z}_{P_i}$ for every $i$.
First observe that $\widetilde{\mathcal{Z}}_i$ has probability transitions given by $\begin{pmatrix} \frac{\alpha}{p+\alpha} & \frac{p}{p+\alpha}\\ \frac{\alpha}{p+\alpha} & \frac{p}{p+\alpha}\end{pmatrix}$, and is therefore a sequence of i.i.d. $\mathrm{Bernoulli}(p/(p+\alpha))$.

Now, for every $i\geq 1$,
\begin{align*}
\set{P_i\in Q}&=\set{P_i\text{ is a "used" $+1$ jump}}\cup \set{P_i\text{ is a "unused" $-1$ jump}}\\
&=\set{P_i\in Q_\nearrow, \widetilde{\mathcal{Z}}_{i-1}=0}\cup \set{P_i\in Q_\searrow, \widetilde{\mathcal{Z}}_{i-1}=0}\\
&=\set{\widetilde{\mathcal{Z}}_{i-1}=0},
\end{align*}
and therefore the sequence  $\set{P_i\in Q}$ is a sequence of i.i.d. $\mathrm{Bernoulli}_{\geq 0}(p/(p+\alpha))$, as claimed. It implies assertion (i): $Q$ is a homogeneous PPP with intensity $\alpha$.

Let now $P_{K_t}$ be the rightmost point of $Q_\nearrow\cup Q_\searrow$. The above construction also shows that no matter $Q_0,Q_1$, $\mathcal{Z}_t=(\widetilde{\mathcal{Z}}_{K_t})$ is a fresh Bernoulli$(p/(p+\alpha))$ which shows (ii).

\end{proof}
To conclude the proof of Proposition \ref{prop:Stationnaire<} we apply successively Lemma  \ref{lem:Burke} with
$$
\begin{array}{l l l}
p=p_1, & Q_\searrow=H^{(\alpha)}(0)=\set{\text{sources of $(0,n)$}},&  Q_\nearrow=\Pi_1,\\
p=p_2, & Q_\searrow=H^{(\alpha)}(1),&  Q_\nearrow=\Pi_2,\\
p=p_3, & Q_\searrow=H^{(\alpha)}(2),&  Q_\nearrow=\Pi_3,\\
\dots & & 
\end{array}
$$
\end{proof}

With Proposition \ref{prop:Stationnaire<} we are now ready to prove  the stochastic bounds \cref{eq:Majo_E_LN,eq:Mino_E_LN} of Theorem \ref{th:poisson_domination}.

\begin{proof}[Proof of Theorem \ref{th:poisson_domination}.]

For $x\leq t$, let ${\sf So}_x=H(0)\cap[0,x]$  be the random set of sources with abscissas $\leq x$  and for $i_0\geq 1$, let  ${\sf Si}_{i_0}$ be the set of sinks with ordinates $\leq i_0$. In particular,
$$
\mathrm{card}({\sf So}_x)\stackrel{\text{(d)}}{=}\mathrm{Poisson}(x\alpha ),\qquad \mathrm{card}({\sf Si}_{i_0})=\sum_{i\leq i_0} I^{(\alpha)}_i\stackrel{\text{(d)}}{=}\sum_{i\leq i_0}\mathrm{Bernoulli}\left(\frac{p_i}{p_i+\alpha}\right).
$$
 It is convenient to use the notation $L_{=<}(\mathcal{P})$
which is, as before, the length of the longest increasing path taking points in $\mathcal{P}$ but when the path is also allowed to go through several sources (which have however the same ordinate) or several sinks (which have the same abscissa). Formally,
$$
L_{=<}(\mathcal{P})=\max\set{L; \hbox{ there exists }P_1  =\prec P_2 =\prec \dots =\prec P_L, \text{ where each }P_i \in \mathcal{P} },\\
$$
where
$$
(a,b)=\prec (a',b') \text{ if }
\begin{cases}
 &a<a'\text{ and }b<b', \\
\text{ or } &a=a'=0 \text{ and }b<b', \\
\text{ or } &a<a' \text{ and }b=b'=0.
\end{cases}
$$
Proposition \ref{prop:NombreLignes} generalizes easily to the settings of sinks and sources.
\begin{claim*}(See \cref{fig:schemasHammersley_sources}.)
\begin{align}
L_{=<}\left( \Pi^{\leq i_0}_t\cup {\sf So}_t\cup {\sf Si}_{i_0}\right) &=\mathrm{card}(H^{(\alpha)}(i_0))+\sum_{i\leq i_0} I^{(\alpha)}_i\label{claim:GaucheHaut}\\
&=\mathrm{card}(H^{(\alpha)}(0))+\sum_{i\leq i_0} J^{(\alpha)}_i.\label{claim:DroiteBas}
\end{align}
%(recall from Proposition \ref{prop:Stationnaire<} that $C_i=1$ if a particle is created at time $i$).
\end{claim*}
(For the example of \cref{fig:schemasHammersley_sources} one has indeed that
$L_{=<}\left( \Pi^{\leq i_0}_t\cup {\sf So}_t\cup {\sf Si}_{i_0}\right)$ is equal to $5=2+3=$  $\mathrm{card}(H^{(\alpha)}(i_0))+\sum_{i\leq i_0} I^{(\alpha)}_i$  but also equal to $4+1= \mathrm{card}(H^{(\alpha)}(0)) +\sum_{i\leq i_0} J^{(\alpha)}_i$.) 
\begin{proof}[Proof of the Claim.] By the same reasoning as in the proof of Proposition \ref{prop:NombreLignes} the LHS is exactly the number of broken lines in the box $[0,t]\times [0,i_0]$. 
The number of such broken lines can be double-counted:
\begin{itemize}
    \item either by saying that each broken lines escapes the box either through the left (it thus corresponds to a sink) or through the top (and is thus counted by $\mathrm{card}(H^{(\alpha)}(i_0))$), hence $$L_{=<}\left( \Pi^{\leq i_0}_t\cup {\sf So}_t\cup {\sf Si}_{i_0}\right) =\mathrm{card}(H^{(\alpha)}(i_0))+\sum_{i\leq i_0} I^{(\alpha)}_i;$$
    \item or by saying that each broken lines enters the box either through the bottom (it thus corresponds to a source) or through the right (and is thus counted by the number of creations of particles) hence 
    $$
    L_{=<}\left( \Pi^{\leq i_0}_t\cup {\sf So}_t\cup {\sf Si}_{i_0}\right) =\mathrm{card}(H^{(\alpha)}(0))+\sum_{i\leq i_0} J^{(\alpha)}_i.
    $$
\end{itemize}
\end{proof}

\noindent{\bf Proof of \cref{eq:Majo_E_LN}: upper bound in Theorem \ref{th:poisson_domination}.}
Adding sources and sinks may not decrease longest increasing paths. Thus,
\begin{align}
L\left( \Pi^{\leq i_0}_{t}\right) &\leq L_{=<}\left( \Pi^{\leq i_0}_t\cup {\sf So}_t\cup {\sf Si}_{i_0}\right) \notag\\
&= \mathrm{card}(H^{(\alpha)}(i_0))+\sum_{i\leq i_0} I^{(\alpha)}_i\qquad \text{ (using \cref{claim:GaucheHaut})}.\label{eq:presque_Majo_E_LN}
%&\stackrel{\text{(d)}}{=} \mathrm{card}(H^{(\alpha)}(i_0))+\sum_{i\leq i_0} I_i \using  \text{ (using bottom-to-top stationnarity: Lemma \ref{prop:Stationnaire<} (i))}.
%&\stackrel{\text{(d)}}{=}  \mathcal{M}_n+ \sum_{i\leq i_0} I_i,
\end{align}
%where $\mathcal{M}_n$ is a Poisson random variable with mean $n$. 
Let now $i'$ be the ordinate of the highest point of $\Pi_t\cup {\sf So}_t\cup {\sf Si}_{i_0}$. Then by construction,  for every $i_0\geq i'$ one has $H^{(\alpha)}(i_0)=H^{(\alpha)}(i')$, in particular $H^{(\alpha)}(i_0)$ converges almost surely when $i_0\to +\infty$. Besides we have that, using bottom-to-top steadiness (Proposition \ref{prop:Stationnaire<} (i)),
$$
H^{(\alpha)}(i_0)\stackrel{\text{(d)}}{=}H^{(\alpha)}(0)\stackrel{\text{(d)}}{=}
\text{PPP with intensity $\alpha$ on $(0,t)$}.
$$
It follows that $H^{(\alpha)}(i')\stackrel{\text{(d)}}{=}
\text{PPP with intensity  $\alpha$ on $(0,t)$}$. 
Letting now $i_0\to +\infty$ in \cref{eq:presque_Majo_E_LN} we obtain
$$
L\left( \Pi_{t}\right) \leq \mathrm{card}(H^{(\alpha)}(i'))+ \sum_{i\geq 1} I^{(\alpha)}_i =: \mathcal{H}^{(\alpha)}_t+ \sum_{i\geq 1} I^{(\alpha)}_i,
$$
where $\mathcal{H}^{(\alpha)}_t$ is a Poisson random variable with mean $\alpha t$.

\noindent{\bf Proof of \cref{eq:Mino_E_LN}: lower bound in Theorem \ref{th:poisson_domination}.}


A maximizing path for $L_{=<}\left( \Pi^{\leq i_0}_t\cup {\sf So}_t\cup {\sf Si}_{i_0}\right)$ goes through some points of $\Pi^{\leq i_0}_t$ (at most $L( \Pi^{\leq i_0}_{t})$ of them) and goes through sinks or sources but not both. Hence 
\begin{align*}
L_{=<}\left( \Pi^{\leq i_0}_t\cup {\sf So}_t\cup {\sf Si}_{i_0}\right)&\leq L\left( \Pi^{\leq i_0}_{t}\right) +\max\set{ \mathrm{card}(H^{(\alpha)}(0)); \sum_{i=1}^{i_0}I^{(\alpha)}_i}.
\end{align*}
Assume that $\mathrm{card}(H^{(\alpha)}(0))\ge \sum_{i=1}^{i_0}I^{(\alpha)}_i$. Then we get
\begin{equation*}
    L\left( \Pi^{\leq i_0}_{t}\right) \ge L_{=<}\left( \Pi^{\leq i_0}_t\cup {\sf So}_t\cup {\sf Si}_{i_0}\right)- \mathrm{card}(H^{(\alpha)}(0)) \stackrel{\text{\cref{claim:DroiteBas}}}{=} \sum_{i=1}^{i_0}J^{(\alpha)}_i.
\end{equation*}
Assume on the contrary that $\mathrm{card}(H^{(\alpha)}(0))\leq \sum_{i=1}^{i_0}I^{(\alpha)}_i$. Using now \cref{claim:GaucheHaut}, $L\left( \Pi^{\leq i_0}_{t}\right)\ge  \mathrm{card}(H^{(\alpha)}(i_0))$. Finally
\begin{align*}
 L\left( \Pi^{\leq i_0}_{t}\right)\ge  \min\set{ \mathrm{card}(H^{(\alpha)}(i_0)); \sum_{i=1}^{i_0}J^{(\alpha)}_i}.
\end{align*}
As for the proof of the upper bound, we let $i_0\to +\infty$ and obtain
$$
L(\Pi_t) \geq \min\set{\mathcal{H}^{(\alpha)}_t,\sum_{i\geq 1}J^{(\alpha)}_i}.
$$
\end{proof}

\section{Basic properties of $f_t$ and $w_t$}\label{Sec:Properties_f_n}
We collect here for convenience some simple properties of both quantities $f_t$ and $w_t$ that will be used throughout Section \ref{sec:PreuvePrincipale}.
To this aim we put
\begin{equation}\label{eq_def_g}
    g_t(a)= at+\sum_{i\geq 1}\frac{p_i}{p_i+a}
\end{equation}
and recall the notation:
\begin{align*}
    f_t&= \inf_{x\geq 0}\left\{ x+\sum_{i\geq 1}\frac{tp_i}{tp_i+x}\right\}=
    \inf_{a\geq 0}\left\{ at+\sum_{i\geq 1}\frac{p_i}{p_i+a}\right\}=
    \inf_{a\geq 0}\left\{ g_t(a)\right\},\\
w_t&\text{ is the unique positive solution of }w_t=\sum_{i\geq 1}\frac{tp_i}{tp_i+w_t}.
\end{align*}

\begin{lem}[Properties of $f_t,w_t$]\label{lem:basic}
For every $t>0$ and $\varepsilon\in (0,1)$,
    \begin{enumerate}[label=(\roman*)]
        \item $f_t \leq 2\sqrt{t}$ and $f_t=\mathrm{o}(\sqrt{t})$. \label{majorf}
         \item  $w_t\leq f_t\leq 2w_t$.\label{encadref}
       \item  $f_{t(1+\eps)}\leq (1+\eps)f_t.$\label{ineqf}
        \item  $(1-\eps) w_t \leq w_{t(1-\eps)}.$\label{ineqw}
%        \item $(f_n)_{n\in\N}$ is a non-decreasing sequence which tends to infinity and such that $f_{n+1} - f_n\leq 1$.\label{propf}
     %   \item $(w_n)_{n\in\N}$ is a non-decreasing sequence which tends to infinity and such that $w_{n+1} - w_n\leq 1$.\label{propw}
        \item\label{item:majo_somme_degueu} We have the upper bound
$$  \sum_{i=1}^\infty\frac{tp_i}{(tp_i+w_t)^2}\leq 4.$$
    \end{enumerate}
\end{lem}
\begin{proof}[Proof of Lemma  \ref{lem:basic}]
For \ref{majorf}, let us  write
    $$
f_t\leq g_t(\frac{1}{\sqrt{t}})=\sqrt{t}+\sum_{i=1}^{+\infty}\frac{p_i}{p_i+\frac{1}{\sqrt{t}}}\leq \sqrt{t}+\sqrt{t}\sum_{i=1}^{+\infty}p_i=2\sqrt{t}.
    $$
Moreover, for every $\eps>0$    
    $$
f_t\leq g_t(\frac{\varepsilon}{\sqrt{t}})=\varepsilon\sqrt{t}+\sum_{i=1}^{\varepsilon\sqrt{t}}\frac{p_i}{p_i+\frac{\varepsilon}{\sqrt{t}}}+\sum_{i> \varepsilon\sqrt{t}}\frac{p_i}{p_i+\frac{\varepsilon}{\sqrt{t}}}\leq\varepsilon\sqrt{t}+\varepsilon\sqrt{t}+\frac{\sqrt{t}}{\varepsilon}\sum_{i> \varepsilon\sqrt{t}}p_i\le 3\varepsilon\sqrt{t},
    $$    
for large enough $t$. Hence \ref{majorf}.

We turn to the proof of \ref{encadref}.
     We have that 
     $$
 f_t\leq g_t(\frac{w_t}{t})=w_t +    \sum_{i\geq 1}\frac{p_i}{p_i+\frac{w_t}{t}}=2w_t.
     $$
 Regarding the left inequality in \ref{encadref}, first observe that,
 since for every $t$, $g_t(\cdot)$ is strictly convex on $(0,\infty)$ with $\lim_{a\to 0^+} g_t(a)=\lim_{a\to +\infty} g_t(a)=+\infty$, there exists a unique $\alpha^\star_t\in (0,\infty)$ such that 
 \begin{equation}\label{eq:def_alpha_n_star}
 f_t=g_t(\alpha_t^\star).
 \end{equation}
Assume first  that $t\alpha_t^\star>w_t$, then 
     $f_t=t\alpha_t^\star+\sum_{i=1}^{+\infty}\frac{p_i}{p_i+\alpha_t^\star}> w_t$. Conversely, if $t\alpha_t^\star\leq w_t$, then
     $$
f_t\geq \sum_{i=1}^{+\infty}\frac{p_i}{p_i+\alpha_t^\star}\geq \sum_{i=1}^{+\infty}\frac{p_i}{p_i+\frac{w_t}{t}}=w_t.
     $$
Hence, in any case, $f_t\ge w_t$.

   In order to prove \ref{ineqf} we write
   $$
f_{t(1+\eps)}= \inf_{a>0}\left\{t(1+\eps)a+\sum_{i=1}^{+\infty}\frac{p_i}{p_i+a}\right\}\leq \inf_{a>0}\left\{t(1+\eps)a+(1+\eps)\sum_{i=1}^{+\infty}\frac{p_i}{p_i+a}\right\}= (1+\eps)f_t.
    $$

     To prove \ref{ineqw} we write for $t>0$
    $$
\frac{w_t}{t}=\frac{1}{t}\sum_{i=1}^\infty \frac{p_i}{p_i+\frac{w_t}{t}}.
    $$
    From this equality we see that $t\mapsto \frac{w_t}{t}$ is non-increasing. Hence we have for all $t> 0$ and $\eps\in (0,1)$
    $$
\frac{w_t}{t}\leq \frac{w_{(1-\eps)t}}{(1-\eps)t},
    $$
    and the inequality follows. 
    %To see that $(w_n)_{n\in\N}$ is non-decreasing we can write 
    %$$
   % w_n=\sum_{i=1}^{+\infty}\frac{p_i}{p_i+\frac{w_n}{n}},
  %  $$
 %   with $(\frac{w_n}{n})_{n\in\N}$ non-increasing.




Let us finally prove \ref{item:majo_somme_degueu}. 
Let $\alpha_t^\star$ be defined by \cref{eq:def_alpha_n_star}, we first observe that $\alpha_t^\star t\leq  g_t(\alpha_t^\star) =  f_t\le 2w_t$ (using  \ref{encadref}).
Besides $g_t'(\alpha_t^\star)=0$, \emph{i.e.} 
$$\sum_{i=1}^\infty\frac{tp_i}{(tp_i+t\alpha_t^\star)^2}=1.$$
Therefore
$$1\ge \sum_{i=1}^\infty\frac{tp_i}{(tp_i+2w_t)^2}\ge \frac{1}{4}\sum_{i=1}^\infty\frac{tp_i}{(tp_i+w_t)^2}.$$
\end{proof}


\section{Proof of Theorem \ref{th:encadrement}}\label{sec:PreuvePrincipale}
\subsection{Proof of  Theorem \ref{th:encadrement}: upper bound for $\mathbb{E}[\LIS_n]$}
\label{SectionUpper}


The aim of this section is to prove the upper bound for $\LIS_n$ given in Theorem \ref{th:encadrement}, namely
\begin{equation}\label{eq:upper_bound_Esperance}
\limsup_{n\to \infty} \frac{\mathbb{E}[\LIS_n]}{f_n}\leq 1.
\end{equation}


\begin{proof}[Proof of \cref{eq:upper_bound_Esperance}: upper bound in Theorem \ref{th:encadrement}]
The upper bound for the expectation of $\LIS_n$ is a direct consequence of the stochastic domination of $\LIS_{N_t}$ given in Theorem \ref{th:poisson_domination}  \ref{item:poisson_upper}. Indeed, let $\alpha_t^\star$ be such that 
$$f_t=g_t(\alpha_t^\star)=\alpha_t^\star t +\sum_{i\ge 1}\frac{p_i}{p_i+\alpha_t^\star}.$$
Choosing $\alpha=\alpha_t^\star$ in  Theorem \ref{th:poisson_domination} \ref{item:poisson_upper} implies that, for any $t> 0$, 
\begin{equation}\label{eq:DominationEsperance}
\E(\LIS_{N_t})\le f_t.
\end{equation}
Fix now $\eps>0$. By monotonicity of $\LIS_n$ it holds that
\begin{equation}\label{eq:OnUtiliseIndependance}
\E[\LIS_{N_{n(1+\eps)}}]\geq \E[\LIS_{N_{n(1+\eps)}}\mathbf{1}_{N_{n(1+\eps)}\geq n}]\geq \E[\LIS_n]\times\mathbb{P}(N_{n(1+\eps)}\geq n).
\end{equation}
Since $\mathbb{P}(N_{n(1+\eps)}\geq n)\stackrel{n\to+\infty}{\to} 1$, we get that, if  $n$ is large enough, 
$\E[\LIS_n]\leq (1+\eps)\E[\LIS_{N_{n(1+\eps)}}]$. We get
    $$
\frac{\E[\LIS_n]}{f_{n(1+\eps)}}\leq (1+\eps)\frac{\E[\LIS_{N_{n(1+\eps)}}]}{f_{n(1+\eps)}}\stackrel{\text{eq.}\eqref{eq:DominationEsperance}}{\leq} (1+\eps).
    $$
Using that 
$
f_{n(1+\eps)}\leq (1+\eps)f_{n}
$ (\emph{c.f.} Lemma \ref{lem:basic} \ref{ineqf}),
we get, for all $\eps$, if $n$ is large enough,
$$
\frac{\E[\LIS_n]}{f_n}\leq (1+\eps)^2
$$
which gives the upper bound of Theorem \ref{th:encadrement}.
\end{proof}

\subsection{
Proof of Theorem \ref{th:encadrement}: lower bound for $\mathbb{E}[\LIS_n]$ }
\label{SectionLower}

Recall that $w_t$ the unique positive solution of the equation  
$$w_t=\sum_{i=1}^\infty \frac{tp_i}{tp_i+w_t}.$$
The aim of this section is to prove the lower bound in Theorem \ref{th:encadrement}, namely
\begin{equation}\label{eq:lower_bound_Theorem}
\liminf_{n\to \infty} \frac{\mathbb{E}[\LIS_n]}{w_n}\geq 1.
\end{equation}
We first prove a lower bound for the poissonized version $L_{N_t}$.

\begin{prop}\label{prop:concentration2}
Let $N_t$ be a $\mathrm{Poisson}$ random variable with mean $t$.
   For all $\eps\in (0,1)$,  we have:
    $$
\mathbb{P}(L_{N_t}<(1-\eps)w_t)\leq 2\exp\left(-\frac{\varepsilon^2 w_t}{40}\right).
    $$
\end{prop}


\begin{proof}
\newcommand{\alfa}{\widetilde{\alpha}_t}

Using Theorem \ref{th:poisson_domination} \ref{item:poisson_lower}  with  $\alfa=w_t/t$, we get that
 $$L_{N_t} \geq \min\set{\mathcal{H}^{(\alfa)}_t\ ;\ \sum_{i\geq 1} J^{(\alfa)}_i}$$
 where    $(J^{(\alfa)}_i)_{i \geq 1}$ are independent random variables with Bernoulli distributions with respective means 
 $\left(\frac{p_i}{\alfa+p_i}\right)=\left(\frac{t p_i}{w_t+t p_i}\right)$ and 
    $\mathcal{H}^{(\alfa)}_t$ is a Poisson random variable with parameter $t\alfa =w_t$.
Thus
\begin{equation*}
    \mathbb{P}(L_{N_t}<(1-\eps)w_t)\leq \mathbb{P}(\mathcal{H}^{(\alfa)}_t\le (1-\eps)w_t)+ \mathbb{P}(\sum_{i\ge 1} J^{(\alfa)}_i\le (1-\eps)w_t).
\end{equation*}
From a standard concentration inequality for Poisson random variables \cite[eq.(2.5) and Rem.2.6]{janson2011random} we have
\begin{equation}\label{eq:lowerbound1}
\mathbb{P}(\mathcal{H}^{(\alfa)}_t\le (1-\eps)w_n)\le \exp\left(-\frac{\varepsilon^2 w_t}{2}\right).
\end{equation}
Let $Z_t:=\sum_{i\ge 1} J^{(\alfa)}_i$ and for $M>0$,  $Z^M_{t}=\sum_{i=1}^M J^{(\alfa)}_i$.
Let choose $M:=M(t)$ such that 
$$(1-\varepsilon) w_t-\E(Z^M_{t})=\sum_{i>M}\frac{tp_i}{tp_i+w_t}-\varepsilon w_t\le -\frac{\varepsilon w_t}{2}.$$
We get
$$\mathbb{P}(Z_{t}\le (1-\eps)w_t)\le \mathbb{P}(Z^M_{t}\le (1-\eps)w_t)\le\mathbb{P}\left(Z^M_{t}-\E(Z^M_{t})\le -\frac{\varepsilon w_t}{2}\right).$$
Using Bernstein inequality, we get 
$$\mathbb{P}(Z^M_{t}\le (1-\eps)w_t)\le \exp\left(-\frac{\frac{(\varepsilon w_t)^2}{8}}{w_t\sum_{i=1}^M\frac{tp_i}{(tp_i+w_t)^2}+\frac{\varepsilon w_t}{3}}\right)\le \exp\left(-\frac{\frac{(\varepsilon w_t)^2}{8}}{w_t\sum_{i=1}^\infty\frac{tp_i}{(tp_i+w_t)^2}+\frac{\varepsilon w_t}{3}}\right).$$
%Recall   that
%$f_n\le 2w_n$ (Lemma \ref{lem:basic} \ref{encadref}). Thus, for $\alpha_n^\star$ such that $f_n=g_n(\alpha_n^\star)$, we have $\alpha_n^\star n\le f_n\le 2w_n$
%Since 
%$$\sum_{i=1}^\infty\frac{np_i}{(np_i+n\alpha_n^\star)^2}=1$$
%we get 
%$$1\ge \sum_{i=1}^\infty\frac{np_i}{(np_i+2w_n)^2}\ge \frac{1}{4}\sum_{i=1}^\infty\frac{np_i}{(np_i+w_n)^2}.$$
Using Lemma \ref{lem:basic} \ref{item:majo_somme_degueu} we obtain, 
 for $\varepsilon \in (0,1)$, 
\begin{equation}\label{eq:lowerbound2}
    \mathbb{P}(Z^M_{t}\le (1-\eps)w_t)\le  \exp\left(-\frac{\frac{(\varepsilon w_t)^2}{8}}{4w_t+\frac{\varepsilon w_t}{3}}\right)\le \exp\left(-\frac{\varepsilon^2 w_t}{40}\right). 
\end{equation}
Combining \cref{eq:lowerbound1} and \cref{eq:lowerbound2} yields the proposition.
\end{proof}

We deduce from the previous  proposition the following left-tail inequality for $\LIS_n$.

\begin{prop}\label{prop:concentration2_depoiss}  For all $\eps\in (0,1)$, $n\geq 1$ and every distribution $(p_i)_{i\geq 1}$ we have:

    $$
\mathbb{P}(\LIS_n\le (1-\eps)w_n)\leq 3\exp\left(-\frac{\varepsilon^2(1-\varepsilon)}{40}w_{n}\right).
    $$
\end{prop}

\begin{proof}
We have 
\begin{eqnarray*}
\mathbb{P}(\LIS_n\le (1-\varepsilon)^2 w_n) & \le & \mathbb{P}(N_{n(1-\varepsilon)}\ge n)+\mathbb{P}(\LIS_n\le (1-\varepsilon)^2 w_n, N_{n(1-\varepsilon)}\le n)\\
& \le & \mathbb{P}(N_{n(1-\varepsilon)}\ge n)+\mathbb{P}(\LIS_{N_{n(1-\varepsilon)}}\le (1-\varepsilon)^2 w_n).
\end{eqnarray*}
Using that $(1-\varepsilon)^2 w_n \le w_{n(1-\varepsilon)}(1-\varepsilon)$ ( Lemma \ref{lem:basic} \ref{ineqw}) and Proposition \ref{prop:concentration2}, we get
$$\mathbb{P}(\LIS_{N_{n(1-\varepsilon)}}\le (1-\varepsilon)^2 w_n)\le \mathbb{P}(\LIS_{N_{n(1-\varepsilon)}}\le (1-\varepsilon) w_{n(1-\varepsilon)})\le 2\exp(-\frac{\varepsilon^2}{40}w_{n(1-\varepsilon)}) \le 2\exp\left(-\frac{\varepsilon^2(1-\varepsilon)}{40}w_{n}\right), $$
using again that $ w_{n(1-\varepsilon)}\ge (1-\varepsilon)w_n $ for the last inequality.
Now, using that $w_n\le n$, we get 
$$\mathbb{P}(N_{n(1-\varepsilon)}\ge n)\le \exp(-\frac{n\varepsilon^2}{40})\le \exp\left(-\frac{w_n\varepsilon^2}{40}\right).$$
\end{proof}


\begin{proof}[Proof of \cref{eq:lower_bound_Theorem}: lower bound in Theorem \ref{th:encadrement}]
We have 
$$\E(\LIS_n)\ge (1-\varepsilon)w_n \mathbb{P}(\LIS_n\ge (1-\varepsilon)w_n).$$
Thus Proposition \ref{prop:concentration2_depoiss} implies that, for all $\varepsilon>0$, 
$$\liminf_{n\to \infty} \frac{\E(\LIS_n)}{w_n}\ge 1-\varepsilon.$$
\end{proof}




\section{Asymptotics of $f_t$}\label{sec:bornes_f}

Theorem \ref{th:encadrement} states that $L_n$ is asymptotically between $\frac{f_n}{2}$ and $f_n$. In this section we try to determine the asymptotic behaviour of the deterministic sequence $f_n$, with strategies that depend on ${\mathbf p}$.

\subsection{Preliminaries: a lower bound from a greedy algorithm}\label{sec:greedy}

Neither Theorem \ref{th:encadrement} nor its proof gives a constructive way to find a long increasing subsequence. This section partially addresses the problem by presenting a simple greedy algorithm which, for a large class of distributions, produces a long increasing subsequence of the right asymptotic order of magnitude.
Besides, this will provide estimates which will be used in the proofs of Proposition \ref{prop:lighttail}  and Proposition \ref{prop:heavytail}.

In order to explain the construction, let us first assume that $(p_i)_{i\ge 1}$ is non-increasing. Fix $n\ge 1$ and  consider the increasing subsequence $(E_1,E_2,\dots, E_{R_n})$ defined as follows:
\begin{itemize}
    \item $E_1$ is the first appearance of $1$ in the sequence $(X_k)_{k\ge 1}$, namely, 
    $
    E_1=\min \set{k\geq 1; X_k=1}
    $.
    \item $E_2$ is the first appearance of $2$ after $E_1$, namely, 
    $
        E_2=\min \set{k\geq E_1; X_k=2}
    $.
    \item ... and so on for any $i\ge 1$.
\end{itemize}
Let $R_n$ be the largest index such that $E_{R_{n}}\le n$.
The sequence $(X_{E_1},X_{E_2},\dots, X_{E_{R_n}})=(1,2,\ldots,R_n)$ is thus an increasing subsequence of $(X_1,\dots , X_n)$. It is clear that $E_i-E_{i-1}$ is a geometric random variable with mean $1/p_i$, so we expect that the length $R_n$ of the above subsequence satisfies $R_n \approx r_n$ where\footnote{Recall that ${\mathbf p}$ has a infinite support, therefore $r_n$ is well defined.} 
$$
r_n=\sup\{r\geq 1, \sum_{i=1}^{r}\frac{1}{p_i}\le n\}.
$$
This construction looks good if $\mathbf{p}$ is non-increasing but may give a very poor result in the case of a general $\mathbf{p}$ (imagine if $p_1$ is very small, or even zero). It is very easy to fix this by reordering the $p_i$'s and this is the purpose of the general construction that we give now:
\begin{enumerate}
    \item For $i\geq 1$, let $p^{\downarrow}_i$ be the $i$-th greatest element of the sequence $\mathbf{p}$ (with multiplicity). In other words $\mathbf{p}^{\downarrow}:=(p^{\downarrow}_i)_{i\ge 1}$ is the non-increasing rearrangement of the sequence $\mathbf{p}$.
    \item For $n\geq 1$ let $r_n$ be uniquely defined by
    \begin{equation}\label{eq:rn}
        r_n=\sup\{r\geq 1, \sum_{i=1}^{r}\frac{1}{p^{\downarrow}_i}\le n\}.
    \end{equation}
    \item Let $i^{(n)}_1<i^{(n)}_2<\dots <i^{(n)}_{r_n}$ be such that
    $$
    \set{p_{i^{(n)}_1},p_{i^{(n)}_2},\dots, p_{i^{(n)}_{r_n}}}=
     \set{p^{\downarrow}_{1},p^{\downarrow}_{2},\dots, p^{\downarrow}_{r_n}}.
    $$
    \item Then apply the construction of the non-increasing case:
 \begin{itemize}
    \item $E_1$ is the first appearance of $i^{(n)}_1$ in the sequence $(X_k)_{k\ge 1}$, namely,  
    $
    E_1=\min \set{k\geq 1; X_k=i^{(n)}_1}
    $.
    \item $E_2$ is the first appearance of $i^{(n)}_2$ after $E_1$, namely, 
    $
        E_2=\min \set{k\geq E_1; X_k=i^{(n)}_2}
    $.
    \item ... and so on for any $i\le r_n$.
\end{itemize}  
\item Finally return $(X_{E_1},\dots,X_{E_{ R_n}})$ where $R_n$ is the largest index such that we have that $E_{R_{n}}\le n$ (note that by construction  $R_n\le r_n$).
\end{enumerate}
This algorithm returns an increasing subsequence of $(X_1,\ldots,X_n)$ of length $R_n$, implying in particular that $L_n\ge R_n$.
Observe that this algorithm is greedy for fixed $n$ but requires to know $n$ in advance in order to determine $i^{(n)}_1,i^{(n)}_2,\dots $. In particular the outputs of the algorithm for successive integers $n,n+1$ may differ significantly and the sequence $(R_n)_{n\ge 1}$ is not in general nondecreasing.
Using this strategy, we obtain the following lower bound for $L_n$.
\begin{prop}\label{prop:R_n_r_n}
For every distribution $\mathbf{p}$, we have 
$$\liminf_n \frac{\LIS_n}{r_n}\ge 1\qquad \mbox{a.s.}$$
where $(r_n)_{n \ge 1}$ is given by \cref{eq:rn}.
\end{prop}


%
\begin{proof} 
Let $\lambda\in (0,1)$ and $n\in \N$. With the notation introduced above, observe that $R_n<\lfloor \lambda r_n\rfloor $ if and only if $E_{\lfloor\lambda r_n\rfloor}>n$.
Since $L_n\ge R_n$, this yields
$$\mathbb{P}(L_n<\lfloor \lambda r_n\rfloor)\le \mathbb{P}(R_n<\lfloor \lambda r_n\rfloor)=\mathbb{P}(E_{\lfloor\lambda r_n\rfloor}>n).$$
Recalling that $E_{\lfloor\lambda r_n\rfloor}$ is the sum of $\lfloor\lambda r_n\rfloor$ independent geometric variables with respective parameters $(p^{\downarrow}_i)_{i\le \lfloor\lambda r_n\rfloor} $, we get
\begin{eqnarray*}
\mathbb{P}(L_n<\lfloor \lambda r_n\rfloor)  %& \mathbb{P}(E_{\lfloor\lambda r_n\rfloor}>n) %\\
%& = &\P\left(G_1+\ldots G_{\lfloor \lambda r_n\rfloor} >n\right)\\
& = &\P\left(E_{\lfloor\lambda r_n\rfloor}-\sum_{i=1}^{\lfloor \lambda r_n\rfloor}\frac{1}{p^{\downarrow}_i} >n-\sum_{i=1}^{\lfloor \lambda r_n\rfloor}\frac{1}{p^{\downarrow}_i}\right)\\
& \leq &\P\left(E_{\lfloor\lambda r_n\rfloor}-\E[E_{\lfloor\lambda r_n\rfloor}] >\sum_{i=1}^{r_n} \frac{1}{p^{\downarrow}_i} -\sum_{i=1}^{\lfloor \lambda r_n\rfloor}\frac{1}{p^{\downarrow}_i}\right)\qquad (\text{using }\sum_{i=1}^{r_n}1/p^{\downarrow}_i\leq n)\\
& \le & \P\left(E_{\lfloor\lambda r_n\rfloor}-\E[E_{\lfloor\lambda r_n\rfloor}]>\sum_{i={\lfloor \lambda r_n\rfloor}+1}^{r_n}\frac{1}{p^{\downarrow}_i}\right)\\
& \le & \frac{\mbox{Var}(E_{\lfloor\lambda r_n\rfloor})}{ \left(\sum_{i={\lfloor \lambda r_n\rfloor}+1}^{r_n}\frac{1}{p^{\downarrow}_i}\right)^2}\\
& \le & \frac{\sum_{i=1}^{\lfloor \lambda r_n\rfloor}\frac{1}{p_i^{\downarrow^2}}}{ \left(r_n(1-\lambda)\frac{1}{p^{\downarrow}_{\lfloor \lambda r_n\rfloor}}\right)^2}
\le  \frac{\lambda}{(1-\lambda)^2 r_n}.
\end{eqnarray*}
 Let us note that $(r_n)_{n \ge 1}$ is a non-decreasing integer sequence which tends to infinity and such that $r_{n+1}-r_{n}\le 1$. Considering $(r_{m_n})_{n\ge 1}$ such that $r_{m_n}=n^2$, the Borel-Cantelli Lemma yields that $L_{m_n}\ge \lfloor\lambda r_{m_n}\rfloor$ a.s. for $n$ large enough.  Using  the same trick as in Section \ref{sec:Cv_ps_Theorem}, we easily deduce 
$$\liminf_m \frac{\LIS_{m}}{r_{m}}\ge 1\qquad \mbox{a.s.}$$
\end{proof}
%



\subsection{Bounds for $f_t$}\label{sec:bounds_ft}

We have proved that, 
$$\liminf_n \frac{\LIS_n}{r_n}\ge 1 \qquad \mbox{ and } \qquad \limsup_n \frac{\LIS_n}{f_n}\le 1 \qquad \mbox{a.s.}$$
So it is natural to try to find bounds on these two quantities for various  distributions $\mathbf{p}$.

\begin{lem}\label{lem:Encadrement_f_n}
Assume that  ${\bf p}$ is eventually non-increasing.  Let $p:[0,\infty)\rightarrow (0,\infty)$ be an eventually non-increasing continuous function such that $p(n)=p_n$ for $n\in \N$ and let $\bar{F}(x)=\int_{x}^\infty p(u)du$. Then, for $t$ large enough, there exist  unique $\mu_t>0$ and $\nu_t>0$ such that
\begin{equation}\label{eq:mu_beta}
\frac{\mu_t}{p(\mu_t)}=t \qquad \mbox{ and } \qquad \frac{\nu_t^2}{\bar{F}(\nu_t)}=t.
\end{equation}
Moreover, for $n$ large enough, we have
\begin{equation}\label{eq:Encadrement_f_n}
\lfloor\mu_n\rfloor \le r_n \text{ and } f_n \le 3\nu_n.
\end{equation}
\end{lem}

\begin{proof}
First note that, for $n$ large enough $\mu_t$ and $\nu_t$ are well defined since the functions $x\mapsto \frac{x}{p(x)}$ and $x\mapsto\frac{x^2}{\bar{F}(x)}$ are both continuous, eventually increasing and tend to infinity. Note also that we necessarily have $\lim_{t\to \infty} \mu_t=\lim_{t\to \infty} \nu_t=\infty$. 
We first prove the first inequality in \cref{eq:Encadrement_f_n}. Since $\mathbf{p}$ is eventually non-increasing and $\mu_n$ tends to infinity, we get, for $n$ large enough,  $p(\mu_n)\le p_i$ for all $i\le \mu_n$.
Thus, we deduce
$$\sum_{i=1}^{\lfloor\mu_n\rfloor}\frac{1}{p_i}\le \frac{\lfloor\mu_n\rfloor}{p(\mu_n)}\le \frac{\mu_n}{p(\mu_n)}= n.$$
So by definition of $r_n$, we get $r_n\ge \lfloor\mu_n\rfloor$.

Let us prove the second inequality in \cref{eq:Encadrement_f_n}.
%Recall that  $f_n$ is the solution of the variational problem
%\begin{equation*}
%    f_n= \inf_{a\geq 0}\left\{ an+\sum_{i\geq 0}\frac{p_i}{p_i+a}\right\}.
%\end{equation*}
The function $\frac{\bar{F}(x)}{{x}}$ is continuous, decreasing on $(0,\infty)$ from infinity to   0. Let $q$ be its inverse function, i.e., for all $a>0$,
$\frac{\bar{F}(q(a))}{{q(a)}}=a$ .
Then 
$$\sum_{i\geq 0}\frac{p_i}{p_i+a}\le  \sum_{i\leq q(a)}\frac{p_i}{p_i+a}+ \sum_{i> q(a)}\frac{p_i}{p_i+a}
\leq q(a)+\sum_{i> q(a)}\frac{p_i}{a}
= q(a)+\frac{\bar{F}(q(a))}{a}=2q(a).$$
Thus
$f_n \le  \inf_{a\geq 0}\left\{an+2q(a)\right\}$. Taking $a=\nu_n/n$, we obtain 
\begin{equation*}
    f_n \le  \nu_n+2q(\nu_n/n).
\end{equation*}
By definition of $\nu_n$ we have that 
$\nu_n/n=\bar{F}(\nu_n)/\nu_n$, so we get
$$q(\nu_n/n)=q(\bar{F}(\nu_n)/\nu_n)=\nu_n$$
and so $f_n\le 3 \nu_n$.
\end{proof}


We now show that for light-tailed distributions $r_n$ and $f_n$ are of the same order, implying that our lower and upper bounds for $\LIS_n$ are also of the same order. 
The proposition below applies for example for the geometric and Poisson distributions.


\begin{prop}[Asymptotics for  sub-exponential  distributions]\label{prop:f_sous_exp} Assume that   
 $\limsup_i p_{i+1}/p_i<1$. Then, when $n\to +\infty$,
 $$
w_n\sim f_n\sim r_n\sim\mu_n.
 $$
 (For convenience we recall that $w_n,f_n,r_n,\mu_n$ are respectively  defined in \cref{eq:wn,eq:fn,eq:mu_beta,eq:rn}.)
\end{prop}
Note that Proposition \ref{prop:f_sous_exp} combined with Theorem \ref{th:encadrement} implies that $\frac{L_n}{f_n}\to 1$ for all sub-exponential distributions.
\begin{proof}
        First, combining  Theorem \ref{th:encadrement} with  Proposition \ref{prop:R_n_r_n}, we get $\liminf_n \frac{f_n}{r_n}\geq 1$. Moreover, with Lemma \ref{lem:Encadrement_f_n}, we know that 
        $\liminf_n \frac{f_n}{\mu_n}\ge 1$ (the assumption  $\limsup_i p_{i+1}/p_i<1$ ensures that $(p_i)_{i\ge 1}$ is eventually non-increasing).

        Let us show that $\limsup_n \frac{f_n}{\mu_n}\le 1$. Let $\eps>0$ and $n\in\N$. We write (recall that $g_n$ was defined in \cref{eq_def_g})
        \begin{align*}
            g_n(\eps\frac{\mu_n}{n})&=\eps\mu_n+\sum_{i=1}^{\lfloor\mu_n\rfloor}\frac{p_i}{p_i+\eps\frac{\mu_n}{n}}+\sum_{i=\lfloor \mu_n\rfloor+1}^{+\infty}\frac{p_i}{p_i+\eps\frac{\mu_n}{n}}\\
                &\le \eps\mu_n +\sum_{i=1}^{\lfloor\mu_n\rfloor}1+\sum_{i=\lfloor \mu_n\rfloor+1}^{+\infty}\frac{n}{\eps\mu_n}p_i\\
                &\le\eps\mu_n+\mu_n+\frac{n}{\eps\mu_n}\sum_{i>\mu_n}p_i.
        \end{align*}
        Now, since $\limsup_i \frac{p_{i+1}}{p_i}<1$, there exists $0<\lambda<1$ and $j\in\N$ such that for all $i\geq j$ and $k\geq0$, $p_{i+k}\le p_i\lambda^k$. Thus for all $i\in\N$
        $$
        \sum_{k>i}p_k\le p_i\sum_{k=0}^{+\infty}\lambda^k=p_i\frac{1}{1-\lambda}.
        $$
        It yields that 
        $$
f_n\le g_n(\eps\frac{\mu_n}{n})\le (1+\eps)\mu_n+ \frac{n}{\eps\mu_n}p(\mu_n)\frac{1}{1-\lambda}.
        $$
        Since $\frac{np(\mu_n)}{\mu_n}=1$ we finally have
        $$
f_n\le (1+\eps)\mu_n+\frac{1}{(1-\lambda)\eps},
        $$
        which implies
        $
\limsup_n \frac{f_n}{\mu_n}\le 1
$
(recall that $\mu_n\to +\infty$).         
        Now, according to  Lemma \ref{lem:Encadrement_f_n}, for $n$ large enough $\lfloor\mu_n\rfloor\le r_n$ so 
        $$
\limsup_n \frac{f_n}{r_n}\le \limsup_n \frac{f_n}{\mu_n}\le 1,
        $$
        thus
        $$
\lim_{n\to+\infty}\frac{f_n}{r_n}=\lim_{n\to+\infty}\frac{f_n}{\mu_n}=1
        $$
      \emph{i.e.}  $f_n\sim\mu_n\sim r_n$. Since, $w_n\le f_n$, it remains to find a lower bound of $w_n$  of the same order. Let $\varepsilon>0$ and let us prove that, for $n$ large enough, $w_n\ge \mu_n(1-\varepsilon):=t_n$.
        For $n\ge 0$, put $$h_n(x):=\sum_{i\ge 1} \frac{np_i}{np_i+x}$$
        so that $h_n(w_n)=w_n$. We show that $h_n(t_n)\ge t_n$.
        Since $h_n$ is a non-increasing function, this would imply that $w_n\ge t_n$ and conclude the proof.
        Let $\eta>0$ such that $(1-\eta)/(1+\eta)=(1-\varepsilon)$ and let 
        $$I_n:=\{i\ge 1, \frac{t_n}{np_i}\le \eta\}.$$
We have 
$$h_n(t_n)\ge \sum_{i\in I_n} \frac{1}{1+\frac{t_n}{np_i}}\ge |I_n|\frac{1}{1+\eta}.$$
We need now to find a lower bound on the cardinal of $I_n$. We claim, that for $n$ large enough, 
$$|I_n|\ge (1-\eta)\mu_n.$$
Indeed recalling that $p(\mu_n)=\mu_n/n$ We have
$$i\in I_n \Longleftrightarrow p_i\ge \frac{t_n}{\eta n} \Longleftrightarrow p(\mu_n)\le \frac{\eta}{(1-\varepsilon)}p_i.$$
Using that $\mathbf{p}$ is sub-exponential, we have, for $n$ large enough and $i\le (1-\eta)\mu_n $, 
$$p(\mu_n)\le \lambda^{\eta \mu_n} p((1-\eta)\mu_n)\le \lambda^{\eta \mu_n} p_i$$
and so $i\in I_n$ if $n$ is large enough such that $\lambda^{\eta \mu_n}\le \eta/(1-\varepsilon)$.
Hence, we get
$$h_n(t_n)\ge \frac{1-\eta}{1+\eta}\mu_n=t_n.$$
    \end{proof}
