We now give a lemma comparing $(\mu_t)_{t>0}$ and $(\nu_t)_{t>0}$ for heavy tailed distribution regularly varying with index strictly larger than $1$. This lemma will be useful for the proof of  Proposition \ref{prop:heavytail} below.
\begin{lem}\label{lem:borne_nu_mu}
If $p_i= \ell(i)i^{-\gamma}$ with $\gamma>1$ and $\ell$ slowly varying and $\mathbf{p}$ is eventually non-increasing, then, for all $c>1$, for $t$ large enough $ \nu_t \le \mu_{ct/(\gamma-1)}$.
\end{lem}

\begin{proof}
If $p_i= \ell(i)i^{-\gamma}$, then $\bar{F}(i):= \sum_{j>i}p_j\sim \frac{1}{\gamma-1}\ell(i)i^{-\gamma+1}$ (see \cite{feller1991},  Section VIII.9, Theorem 1). In particular, for any $c>1$ and $x$ large enough, 
$$\bar{F}(x)\le  \frac{c}{\gamma-1}x p(x).$$
Thus, for $t$ large enough
$$\nu_t^2=t\bar{F}(\nu_t)\le t\frac{c }{\gamma-1}\nu_t p(\nu_t)$$
and so 
$$\frac{ \nu_t}{p( \nu_t )}\le \frac{tc }{\gamma-1}= \frac{ \mu_{tc/(\gamma-1)} }{p( \mu_{tc/(\gamma-1)})}.$$
We use again that the function $x\rightarrow x/p(x)$ is increasing to conclude.
\end{proof}

\subsection{Some explicit estimates}\label{sec:explicit}

Recall that $\mu_n$ was defined in \cref{eq:mu_beta} as the solution of 
$\frac{\mu_n}{p(\mu_n)}=n$.  The combination of 
Lemma \ref{lem:Encadrement_f_n}, Proposition \ref{prop:f_sous_exp} and Lemma \ref{lem:borne_nu_mu} allow to translate bounds for $\mu_n$ into  bounds for $f_n$, for various distributions.
The purpose of the next lemma is therefore to estimate $\mu_n$ in several cases.

\begin{lem}\label{lem:calcul} %Recall that $\mu_n$ is given by $\frac{\mu_n}{p(\mu_n)}=n$. 
 \begin{itemize}
    \item If ${\bf p}$ is a geometric distribution $p_i:=p (1-p)^{i-1}$, then  
    \begin{equation}\label{eq:mu_geometrique}
    \mu_n\sim \frac{\log n}{|\log (1-p)|}.
    \end{equation}
    \item If  ${\bf p}$ is a Poisson distribution $p_i:=\frac{e^{-\lambda}\lambda^i }{i!}$, then 
    \begin{equation}\label{eq:mu_poisson}
    \mu_n\sim \frac{\log n}{|\log \log n|}.
    \end{equation}
      \item If  ${\bf p}$ is eventually non-increasing and $p_i\sim c i^{-\beta}(\log i)^\gamma$, $\beta>1$, $\gamma \in \R$, then 
      $$
      \mu_n\sim \left( c n\left(\frac{\log n}{(1+\beta)}\right)^\gamma \right)^{1/(1+\beta)}.
      $$
%where $\mu_n$ is defined in \eqref{eq:mu_beta}.
 \end{itemize}
 \end{lem}
 \begin{proof}
Recall that  $p:[0,\infty)\rightarrow (0,\infty)$ is an eventually non-increasing continuous function such that $p(i)=p_i$ for $n\in \N$. It follows that $\lim_{n\to +\infty}\mu_n =+\infty$.
\begin{itemize}
\item  Assume that $p_i=p(1-p)^{i-1}$ and define the function $p$ for  $x\ge 1$ by $p(x)=p(1-p)^{x-1}$. Then
 $$
 \frac{\mu_n}{n}=p(\mu_n)=p(1-p)^{\mu_n-1}.
 $$
 Thus we have
 $$
 \log \mu_n - \mu_n\log(1-p) =\log n+\log\left(\frac{p}{1-p}\right).
 $$
 Now, since $\log{\mu_n}=o(\mu_n)$, we get $\mu_n|\log(1-p)|\sim \log n$, hence \cref{eq:mu_geometrique}.
 \item Consider now the distribution $p_i=\frac{e^{-\lambda}\lambda^i}{i!}$ and  for  $x\ge 1$ set $p(x)= e^{-\lambda}\frac{\lambda^x}{\Gamma(x+1)}$. The function $p$ is increasing on $[1,x_\lambda]$ and decreasing on $[x_\lambda,+\infty)$ for some $x_\lambda >1$.
Since $\mu_n\to+\infty$, there exists $n(\lambda)\in\N$ such that for all $n\geq n(\lambda)$, $\mu_n\geq x_\lambda$. 
For such $n$,
 $$
 p(\mu_n)=\frac{\mu_n}{n}=\frac{e^{-\lambda}\lambda^{\mu_n}}{\Gamma(\mu_n+1)}.
 $$
 Now, since $\Gamma(\mu_n+1)=\mu_n\Gamma(\mu_n)$ we get
 $$
 \mu_n^2\frac{\Gamma(\mu_n)}{\lambda^{\mu_n}}=\frac{n}{e^\lambda}.
 $$
 Thanks to the Stirling formula we can write:
 $$
 \mu_n^2\times \left(\frac{\mu_n}{\lambda e}
 \right)^{\mu_n}\sqrt{2\pi \mu_n}\sim \frac{n}{e^\lambda}.
 $$
 Now by taking the logarithm and using that $\log \mu_n$ and $ \mu_n$ are negligible compared to $\mu_n \log \mu_n$, we get $ \mu_n\log(\mu_n)\sim \log(n)$. Applying the logarithm a last time, we  then obtain  $\log(\mu_n)\sim \log(\log(n))$, hence \cref{eq:mu_poisson}.
 \item Let $\beta>1$, $\gamma\in \R$ and assume that $p_i\sim c(\log i)^\gamma i^{-\beta}$,  so $p(\mu_n)\sim c(\log \mu_n)^\gamma\mu_n^{-\beta}$ for $n$ large enough. We get
 $$n=\frac{\mu_n}{p(\mu_n)}\sim \frac{\mu_n^{1+\beta}}{c(\log \mu_n)^\gamma}.$$ 
 Taking the logarithm, we get 
 $$\log n \sim (1+\beta) \log \mu_n.$$
 Plugging this in the previous equation, we get 
 $$\mu_n^{1+\beta}\sim c n\left(\frac{\log n}{(1+\beta)}\right)^\gamma.$$ 
 which yields the result.
\end{itemize}
 \end{proof}

 \begin{proof}[Proof of Proposition \ref{prop:lighttail}] Using  Theorem \ref{th:encadrement}, we know that 
 $$\liminf_n \frac{L_n}{w_n}\ge 1 \qquad \limsup_n \frac{L_n}{f_n}\le 1 \qquad a.s.$$
 Moreover, if $\mathbf{p}$ is a geometric or a Poisson distribution, thanks to 
 Proposition \ref{prop:f_sous_exp}, we know that 
 $f_n\sim w_n \sim \mu_n$. 
 Then we estimate $\mu_n$ using  Lemma \ref{lem:calcul} in order to deduce Proposition \ref{prop:lighttail}.

 \end{proof}




\begin{proof}[Proof of Proposition \ref{prop:heavytail}]
Recall that $\mu_n$ and $\nu_n$ are defined by \cref{eq:mu_beta}.
Combining Theorem \ref{th:encadrement} and Proposition \ref{prop:R_n_r_n} we obtain
\begin{equation}\label{eq:encadrement_mu_nu_inf}
    \liminf_n \frac{L_n}{\mu_n}=  \liminf_n \frac{L_n}{r_n}\times \frac{r_n}{\mu_n} \geq 1 \times 1 >0. 
\end{equation}
Besides, combining Theorem \ref{th:encadrement}, and Lemma \ref{lem:Encadrement_f_n} yields  
\begin{equation}\label{eq:encadrement_mu_nu_sup}
\limsup_n \frac{L_n}{\nu_n}= 
\limsup_n \frac{L_n}{f_n} \times  \frac{f_n}{\nu_n}
\leq 1 \times 3 <+\infty.
\end{equation}


In the case $p_i\sim c (\log i)^\gamma i^{-\beta}$ with $\beta >1$, we deduce \ref{PropHT_i} in  Proposition \ref{prop:heavytail}  using the asymptotic for $\mu_n$ computed in  Lemma \ref{lem:calcul}  and the upper bound for $\nu_n$ given in Lemma \ref{lem:borne_nu_mu}.

Let us now consider the case \ref{PropHT_ii} of Proposition \ref{prop:heavytail}, namely $p_i\sim c (\log i)^\gamma i^{-1}$ with $\gamma <-1$. 
Then,  we have, for some $c_1>0$,
$$ \bar{F}(x)= \sum_{i> x} p_i \sim c_1(\log x)^{\gamma+1}.$$
As $\frac{\nu_n^2}{\bar{F}(\nu_n)}=n$ this implies that  $$\nu_n\sim c_2\sqrt{n(\log n)^{\gamma+1}}$$
for some $c_2 >0$. 
This asymptotic combined with \cref{eq:encadrement_mu_nu_sup} yields the upper bound 
$$\limsup_n \frac{L_n}{\sqrt{n(\log n)^{\gamma+1}}}<\infty.$$
An easy computation shows that $\mu_n\sim c_3{\sqrt{n(\log n)^{\gamma}}}$, so we will not obtain  the desired lower bound for $L_n$ just using that asymptotically $L_n\ge \mu_n$. We should make here more precise computation to find a lower bound for $f_n$ (and so for $w_n$).

Recall that $p(x)$ is eventually non-increasing and such that $p(i)=i$ for every  integer $i$. For $a$ close to $0$, let $u(a)$ such that $a=p(u(a))$. Thus
$$
a \stackrel{a\to 0}{\sim} c (\log u(a))^\gamma u(a)^{-1}
$$
which implies 
$$ 
u(a)\stackrel{a\to 0}{\sim} c |\log a|^\gamma a^{-1}.
$$
Using that $\mathbf{p}$ is eventually decreasing, we have, for $a$ close to $0$, $p_i\le a$ if $i\ge u(a)$. So we get 
$$\sum_{i=1}^\infty \frac{p_i}{p_i+a} \ge \sum_{i\ge u(a)} \frac{p_i}{a+a} \sim \frac{\bar{F}(u(a))}{2a} \sim  \frac{c_1|\log a|^{\gamma+1}}{2a}.$$
Hence, we get, for $n$ large enough 
\begin{equation*}
    f_n= \inf_{a\geq 0}\left\{ an+\sum_{i\geq 0}\frac{p_i}{p_i+a}\right\}\ge \inf_{a\geq 0}\left\{ an+\frac{c_1|\log a|^{\gamma+1}}{4a }\right\}\sim c_3\sqrt{n(\log n)^{\gamma+1}}.
\end{equation*}
Using Theorem \ref{th:encadrement} and that $w_n\ge f_n/2$, this yields the expected lower bound:
$$\liminf_n \frac{L_n}{\sqrt{n(\log n)^{\gamma+1}}}>0.$$

\end{proof}

\begin{rem}\label{rem:indice1}
In the case $p_i\sim c (\log i)^\gamma i^{-1}$ with $\gamma <-1$, we can also compute the order of $r_n$. Indeed, up to constant,
$\sum \frac{1}{p_i}\sim c\sum i (\log i)^{-\gamma} \sim c_4k^2 (\log k)^{-\gamma}$
And so $r_n$ is such that $c_4r_n^2 (\log r_n)^{-\gamma} \sim n$ which yields $r_n\sim c_5\sqrt{n (\log n)^\gamma}$. Hence, we see that $L_n\gg r_n$ which shows that in this case, the greedy algorithm described in Section \ref{sec:greedy} does not give a subsequence of the right order.
\end{rem}


\section{Case of a generic distribution: proof of Theorem  \ref{th:distribution_generique}}\label{sec:distribution_generique}

We explain in this section how Theorem \ref{th:encadrement}, dealing with  discrete distributions on integers, can in fact be extended to any discrete distribution, even if its support cannot be enumerated in increasing order, as in the cases of $\mathbb{Z}$ or $\mathbb{Q}$.
Let us first observe that the proof of $\LIS_n/\mathbb{E}(\LIS_n)\to 1$ (\emph{i.e} \cref{eq:Cv_ps_Theorem}) is valid for any distribution $\rho$. Therefore, in order to extend the Theorem \ref{th:encadrement} to arbitrary distributions  we just need to control $\E(L_n)$.

\begin{proof}[Proof of Theorem \ref{th:distribution_generique}]
We begin by proving item (i) in Theorem \ref{th:distribution_generique}.
Let $\rho$ be a discrete distribution on a countable set $S:=\{i_1,i_2,\ldots\}$. Let $(X_i)_{i\ge 1}$ be an i.i.d. sequence with law $\rho$ and for $M,n\ge 1$, set
$$D_n^M:=\{1\le i \le n, X_i\in \{i_1,\ldots,i_M\}\}.$$
We define $L_n^M:=L((X_i)_{i\in D_n^M})$, the length of the longest increasing subsequence with values in $\{i_1,\dots,i_M\}$.
Since the set $\{i_1,\dots,i_M\}$ is finite, it can be enumerated in the increasing order and so we can apply Theorem \ref{th:poisson_domination} : if $N_t$ is a Poisson random variable with parameter $t$ independent of the sequence $(X_i)_{i\ge 1}$, then, for any $\alpha>0$, we have the stochastic domination :
\begin{equation*}
    L^M_{N_t} \leq \mathcal{H}^{(\alpha)}_t+ \sum_{j=1}^M I^{(\alpha)}_j,
    \end{equation*}
where $\mathcal{H}^{(\alpha)}_t$ is a Poisson random variable with parameter $\alpha t$ and  $(I^{(\alpha)}_j)_{j \geq 1}$ is a sequence of independent random variables with $\mathrm{Bernoulli}\left(\frac{\rho(\{i_j\})}{\alpha+\rho(\{i_j\})}\right)$ distribution. Thus, for any $\alpha>0$
\begin{equation*}
   \E( L^M_{N_t} )\leq \alpha t + \sum_{j=1}^M \frac{\rho(\{i_j\})}{\alpha+\rho(\{i_j\})} \le \alpha t + \sum_{i\in S} \frac{\rho(\{i\})}{\alpha+\rho(\{i\})}.
    \end{equation*}
Optimizing over $\alpha$, we get     $\E( L^M_{N_t} )\le f_t$ and so, by monotone convergence, $\E( L_{N_t} )\le f_t$. We conclude as in Section \ref{SectionUpper} that 
$$\limsup_n \frac{\E(L_n)}{f_n}\le 1.$$


 \newcommand{\alfa}{\widetilde{\alpha}_t}
Regarding the lower bound, using again Theorem \ref{th:poisson_domination}, we get the stochastic lower bound
\begin{equation*}
  L_{N_t} \geq   L^M_{N_t} \geq \min(\mathcal{H}^{(\alpha)}_t, \sum_{j=1}^M J^{(\alpha)}_j).
    \end{equation*}
Let $w_t$ the unique positive solution of the equation  
\begin{equation*}
w_t=\sum_{i\in S} \frac{t\rho(\{i\})}{t\rho(\{i\})+w_t}
\end{equation*}
and take   $\alfa=w_t/t$. We get
 \begin{equation*}
    \mathbb{P}(L_{N_t}<(1-\eps)w_t)\leq \mathbb{P}(\mathcal{H}^{(\alfa)}_t\le (1-\eps)w_t)+ \mathbb{P}(Z^M_{t}\le (1-\eps)w_t),
\end{equation*}
where  $Z^M_{t}:=\sum_{i=1}^M J^{(\alfa)}_i$. One can check that \cref{eq:lowerbound1} and \cref{eq:lowerbound2} still hold in this case if $M$ is chosen large enough and thus imply that 
  $$
\mathbb{P}(L_{N_t}<(1-\eps)w_t)\leq 2\exp\left(-\frac{\varepsilon^2 w_t}{40}\right),
    $$
as obtained in Proposition \ref{prop:concentration2} in the case of a distribution on the integers. We conclude, as in Section \ref{SectionLower}, that 
$$\liminf_n \frac{\E(L_n)}{w_n}\ge 1.$$


\medskip





Let us now prove item (ii) in Theorem \ref{th:distribution_generique}. Let $\rho$ be a probability measure on $\R$ and write $\rho=\rho_1+\rho_2$ where $\rho_1$ is atomless and $\rho_2$ is purely discrete. Let $S$ be the (countable) support of $\rho_2$. For $n\ge 1$, define
$$D^1_n:=\{i\le n, X_i\notin S\} \qquad \mbox{ and }\qquad D^2_n:=\{i\le n, X_i\in S\}$$
and set $L_n^1:=L((X_i)_{i\in D^1_n})$ and  $L_n^2:=L((X_i)_{i\in D^2_n})$. Note that, for $k\in \{1,2\}$,  $|D^k_n|$ is a binomial random variable with parameters $(n,\rho_k(\R))$.   Moreover,  since $\rho_1$ is atomless, conditionally on $|D^1_n|$, $L_n^1$ has the law of $\mathcal{L}_{|D^1_n|}$, the length of the longest increasing subsequence in a uniform permutation of size  $|D^1_n|$. 
Besides, we have
$$L_n^1\le L_n\le L_n^1+L_n^2.$$
On the one hand, using (i) of Theorem \ref{th:distribution_generique} and the fact that $f_n=o(\sqrt{n})$ for any discrete distribution, we get 
$$\lim_{n\to \infty} \frac{L_n^2}{\sqrt{n}}=0 \mbox{ a.s.}$$
On the other hand, using the Ver\v{s}ik-Kerov's theorem on uniform permutations \cite{vershik1977asymptotics}, we obtain
 $$\lim_{n\to \infty} \frac{L_n^1}{2\sqrt{|D_n^1|}}=1 \mbox{ a.s.}$$
as soon as $|D_n^1|$ converges to infinity almost surely. We conclude using the fact that, if $\rho_1(\R)>0$, then $|D_n^1|\sim n\rho_1(\R)$ almost surely.

 \end{proof}

