\title{A hybrid nonet with $J^{PC}=1^{-+}$ or a tetraquark 81-plet}

\author{Niu Su$^1$}
\author{Er-Liang Cui$^2$}
\author{Yi-Wei Jiang$^3$}
\author{Hua-Xing Chen$^3$}
\email{hxchen@seu.edu.cn}

\affiliation{$^1$College of Physics and Optoelectronic Engineering, Taiyuan University of Technology, Taiyuan 030024, China
\\
