\section{$k$-quasi $n$-power Posinormal Weighted Composition Operators}
This section extends these results to weighted composition operators \(W_T = M_\pi C_T\). We characterize \(k\)-quasi \(n\)-power posinormality for \(W_T\) and its adjoint \(W_T^*\), assuming \(T^{-k}(\Sigma) = \Sigma\) and \(\pi \geq 0\). The criteria involve products of weights \(\pi_k\) and Radon-Nikodym derivatives \(h_k\), yielding norm inequalities analogous to those in Section 2. We denote the adjoint of $W_T$ by $W_T^*$. We denote $h_0=1$, $h_1=h$, $E_1=E$.

 \begin{theorem}\label{thm3.1} \cite{Campbell}
 Let $W_T$ be the weighted composition operator induced by $T$ and $\pi$ on $L^2(\mu)$, then the following statements hold for $f\in L^2(\mu)$ and $k\in \mathbb{N}$,
 \begin{enumerate}
 \item[(i)] $W_T^*f=h.E(\pi .f)\circ T^{-1}.$
 \item[(ii)] $W_T^k f =\pi_{k}.f\circ T^k.$
 \item[(iii)] $W_T^{*k}f=h_kE_k(\overline{\pi}_kf)\circ T^{-k}$.
 \item[(iv)]$W_T^*W_T(f)=hE(|\pi|^2)\circ T^{-1}(f).$
 \item[(v)] $W_TW_T^*(f)=\pi(h\circ T)E(\overline{\pi}f).$
 \item[(vi)] $W_T^{*k}W_T^k(f)=h_kE_k(|\pi_k |^2)\circ T^{-k}(f).$
 \item[(vii)] $W_T^kW_T^{*k}(f)=\pi_k (h_k\circ T^k)E_k(\overline{\pi}_k f),$
where $\pi_k=\pi(\pi \circ T)(\pi \circ T^2)\dots (\pi \circ T^{k-1}).$
\end{enumerate}

 \end{theorem}

   We assume that $\pi \geq 0$.
\begin{theorem}\label{thm3.2}  Let $W_T \in B(L^2(\mu ))$. Let $E$ be the projection from $L^2(\mu )$ onto $\overline {R(C_T)}$ and if $T^{-k}(\Sigma)=\Sigma$ for all $k$, then
\begin{enumerate}
\item [(i)] $W_T$ is $k$-quasi $n$-power posinormal if and only if, $$\lambda ^2h_{k+1}\pi^2_{k+1}\circ T^{-(k+1)}\geq \pi^2_k\pi^2_n (h_k\circ T^{-k})(h_n\circ T^n).$$\\
\item [(ii)] $W_T^*$ is $k$-quasi $n$-power posinormal  if and only if, $$\lambda^2 {\pi_k}^2(h_k\circ T^k)\geq {\pi_k}^2{\pi_n}^2(h_k\circ T^k)(h_n\circ T^{n+k}) .$$
\end{enumerate}
\end{theorem}

\begin{proof}
(i)  Now,
\begin{align*}
\lambda^2{W_T^*}^{k+1} W_T^{k+1} f &= \lambda^2h_{k+1}E_{k+1}(|\pi_{k+1}|^2)\circ T^{-(k+1)}f.\\
&= \lambda^2h_{k+1}\pi^2_{k+1}\circ T^{-(k+1)}f.
\end{align*}


\begin{align*}
{W_T^*}^kW_T^nW_T^{*n} W_T^k f &= {W_T^*}^kW_T^nW_T^{*n} [\pi_k. f\circ T^k]\\
&= {W_T^*}^k [\pi_n (h_n\circ T^n)E_n[\overline{\pi}_n\pi_k. f\circ T^k]]\\
&= h_k E_k\{\overline{\pi}_k[\pi_n (h_n\circ T^n)E_n[\overline{\pi}_n\pi_k. f\circ T^k]]\}\circ T^{-k}\\
&= h_k[E(\overline{\pi}_k\pi_n)E(h_n\circ T^n)E(\overline{\pi}_n\pi_k)E(f\circ T^k)]\circ T^{-k}\\
&= h_k[\overline{\pi}_k\pi_n (h_n\circ T^n) \overline{\pi}_n\pi_k (f\circ T^k)]\circ T^{-k}\\
&= \pi^2_k\pi^2_n(h_k\circ T^{-k})(h_n\circ T^n)f.
\end{align*}

Thus, for every $f\in L^2(\mu)$,

$$\langle (\lambda ^2{W_T^*}^{k+1} W_T^{k+1}- {W_T^*}^k W_T^n {W_T^*}^n W_T^k ) f, f \rangle ~ \geq 0.$$

$$\Longleftrightarrow \lambda ^2h_{k+1}\pi^2_{k+1}\circ T^{-(k+1)}\geq \pi^2_k\pi^2_n(h_k\circ T^{-k}) (h_n\circ T^n).$$
Hence the result.\\

(ii) 		Now,
\begin{align*}
\lambda^2 W_T^{k+1} {W_T^*}^{k+1} f &= \lambda^2 \pi_k(h_k\circ T^k)E_k(\overline{\pi}_kf)\\
&=\lambda^2 \pi_k(h_k\circ T^k)\pi_kf\\
&=\lambda^2 {\pi_k}^2(h_k\circ T^k)f.
%&=L_{k+1} f.
\end{align*}

\begin{align*}
W_T^k{W_T^*}^nW_T^n{ W_T^*}^k f &= W_T^k{W_T^*}^nW_T^n[h_kE_k(\overline{\pi}_kf)\circ T^{-k}  ]\\
&= W_T^k [\pi_n(h_n\circ T^n)E_n(\overline{\pi}_n h_kE_k(\overline{\pi}_kf)\circ T^{-k})]\\
&= W_T^k [\pi_n(h_n\circ T^n)\pi_n h_k\pi_k(f\circ T^{-k})]\\
&=\pi_k.[(\pi_n(h_n\circ T^n)\pi_n h_k\pi_k(f\circ T^{-k}))\circ T^k]\\
&={\pi_k}^2{\pi_n}^2(h_k\circ T^k)(h_n\circ T^n\circ T^k)f
\end{align*}

Therefore, for every $f\in L^2(\mu)$,

$$\langle (\lambda ^2W_T^{k+1} {W_T^*}^{k+1}- W_T^k{W_T^*}^n W_T^n {W_T^*}^k) f, f \rangle ~ \geq 0.$$

$$\Longleftrightarrow \lambda^2 {\pi_k}^2(h_k\circ T^k)\geq {\pi_k}^2{\pi_n}^2(h_k\circ T^k)(h_n\circ T^{n+k}) .$$
\end{proof} 		
%=========================================================================================================
The following example demonstrates the applicability of Theorem \ref{thm3.2} for non-constant weights and identity transformations, with explicit verification of the key inequality.
\begin{example} Consider the weighted composition operator \(W_T\) on the Hilbert space \(L^2([0,1], \mu)\), where \(\mu\) is the Lebesgue measure. Define:
\begin{itemize}
  \item Transformation \(T\): The identity map \(T(x) = x\) for all \(x \in [0,1]\).
  \item Weight function \(\pi\): \(\pi(x) = x\) (non-constant and non-negative).
  \item Key Properties:
  \begin{enumerate}
    \item [i.] Radon-Nikodym derivatives: Since \(T\) is the identity, \(\mu \circ T^{-k} = \mu\) for all \(k \in \mathbb{N}\). Thus, \(h_k(x) = \frac{d(\mu \circ T^{-k})}{d\mu}(x) = 1\) for all \(k\) and almost every \(x\).
    \item [ii.] Iterated weight \(\pi_k\):
   \[
   \pi_k(x) = \pi(x) \cdot \pi(T(x)) \cdots \pi(T^{k-1}(x)) = x \cdot x \cdots x = x^k.
   \]
    \item [iii.] Adjoint and range condition: \(T^{-k}(\Sigma) = \Sigma\) holds trivially.
  \end{enumerate}
\end{itemize}
 Verification of Theorem \ref{thm3.2}(i):
\(W_T\) is \(k\)-quasi \(n\)-power posinormal if and only if:
\[
\lambda^2 h_{k+1} \pi_{k+1}^2 \circ T^{-(k+1)} \geq \pi_k^2 \pi_n^2 (h_k \circ T^{-k}) (h_n \circ T^n) \quad \text{a.e.}
\]
Substitute the values:
- \(h_{k+1}(x) = 1\), \(h_k(T^{-k}(x)) = 1\), \(h_n(T^n(x)) = 1\),
- \(\pi_{k+1}(T^{-(k+1)}(x)) = \pi_{k+1}(x) = x^{k+1}\),
- \(\pi_k(x) = x^k\), \(\pi_n(x) = x^n\).

The inequality simplifies to:
\[
\lambda^2 \cdot 1 \cdot (x^{k+1})^2 \geq (x^k)^2 (x^n)^2 \cdot 1 \cdot 1
\]
\[
\lambda^2 x^{2(k+1)} \geq x^{2k} x^{2n} = x^{2(k+n)}
\]
\[
\lambda^2 \geq x^{2(n-1)} \quad \text{a.e. on } [0,1].
\]
Conclusion:
Since \(x \in [0,1]\), the function \(x^{2(n-1)}\) is bounded by \(1\) for all \(n \geq 1\). Choosing \(\lambda \geq 1\) (e.g., \(\lambda = 1\)) satisfies the inequality. Thus, \(W_T\) is \(k\)-quasi \(n\)-power posinormal for all \(k, n \in \mathbb{N}\).

Operator Interpretation:
\(W_T f(x) = x \cdot f(x)\) is a multiplication operator. Its posinormality properties are confirmed by the above calculation, illustrating Theorem \ref{thm3.2}(i) concretely.
\end{example}


