\section{$k$-Quasi $n$-Power Cauchy Dual of Lambert Conditional Operators}
%====================================================================================
This section examines the Cauchy dual \(\omega(T)\) of Lambert conditional operators \(T = M_w E M_u\), defined via the Moore-Penrose inverse. We derive conditions under which \(\omega(T)\) and its adjoint are \(k\)-quasi \(n\)-power posinormal. These conditions reduce to inequalities involving conditional expectations of \(u\) and \(w\) on a critical set \(K\) (Corollary 4.4). An example on \([0,1]\) demonstrates cases where \(\omega(T)\) is \(k\)-quasi \(n\)-power posinormal but not posinormal.
%======================================================================================

Here we consider the Cauchy dual of Lambert conditional operator $T=M_wEM_u$ introduced by Sohrabi in \cite{Mort} using the Moore-Penrose inverse. The Cauchy dual of $T\in B_C(\mathscr {H})$ is defined as,
 $ \omega (T)=T(T^*T)^ {\dagger} $.

 Let's recall few basic theorems.

%reference
 \begin{theorem}\label{thm4.1}
 \cite{Jabbar}Let $T=M_wEM_u\in B_C(L^2(\Sigma))$ with $u,w\geq 0$. Then $$T^{\dagger}=M_{\frac{\chi_K}{E(u^2)E(w^2}}T^*.$$
 \end{theorem}
We assume that $u, w\in L_+^0(\Sigma)$, $R=S(E(uw))$ and $K:=P\cap Q$, where $P=S(E(u))$ and $Q=S(E(w))$.
%reference
\begin{theorem}\label{thm4.2}
 \cite{Mort}Let $T=M_wEM_u\in B_C(L^2(\Sigma))$ with $u,w\geq 0$. Then we have
 \begin{enumerate}
 \item $\omega(T)=M_{\frac{\chi_K}{E(u^2)E(w^2)}}T$ and $\omega(T)^{\dagger}=T^*$.
 \item $\omega(T^*)=M_{\frac{\chi_K}{E(u^2)E(w^2)}}T^*=\omega(T)^*$.
 \end{enumerate}
 \end{theorem}

 %our result  4.3%%%%%%%%%%%%%%-----Thm4.3------------
 \begin{theorem}\label{THM1}
Let $T=M_wEM_u\in B_C(L^2(\Sigma))$. Then the following statements hold, for some $\lambda >0$:-

\begin{enumerate}
\item[(i)]  If $\omega(T)$ is  posinormal, then $\lambda^2 E(uw)^2\geq E(u^2)E(w^2)$ on $K$.

\item[(ii)] If $\omega(T)$ is $n$-power posinormal, then $\lambda^2 E(u^2)^{2n-3}E(w^2)^{2n-3}\geq E(uw)^{2n-4}~\text{on}~ K.$

\item[(iii)] $\omega(T)$ is $k$-quasi $n$-power posinormal if and only if
\[
\lambda^2E(u^2)^{2n-3}E(w^2)^{2n-3} \geq E(uw)^{2n-4}~\text{on}~K.
 \]
  \item[(iv)]$\omega(T)^*$ is $k$-quasi $n$-power posinormal if and only if $\omega(T)$ is $k$-quasi $n$-power posinormal.


\end{enumerate}
\end{theorem}

\begin{proof}

%\begin{enumerate}
% proof of 1
(i) Suppose $\omega(T)$ is  posinormal, then $\lambda^2 \omega(T)^* \omega(T)- \omega(T)\omega(T)^* \geq 0$, for some $\lambda>0$.

For $f\in L^2(\Sigma)$, we have, $$\omega(T)^* \omega (T)f=\frac{\chi_K u}{E(u^2)^2E(w^2)}E(uf).$$
and
$$\omega(T) \omega (T)^*f=\frac{\chi_K w}{E(u^2)E(w^2)^2}E(wf).$$

Now, since $\omega(T)$ is posinormal, for all $f\in L^2(\Sigma)$,
\begin{equation}\label{intK2}
\int_{K}^{} \left( \lambda^2 \dfrac{uE(uf)}{E(u^2)^2E(w^2)}
-\dfrac{wE(wf)}{E(u^2)E(w^2)^2}\right) \overline{f}d\mu\geq0.
\end{equation}

Since $\mathcal{A}$ is $\sigma$-finite, there exists $\{A_m\}\subseteq \mathcal{A}$ such that $X=\cup A_m$, $A_m\subseteq A_{m+1}$
with $A_m\in \mathcal{A}$ with $0<\mu(A_m)<\infty$.

Substituting $f_m=w\sqrt{E(u^2)}\chi_{A_m}$ in \ref{intK2}, we get,
$$\int_{K\cap A_m}^{} \left( \lambda^2 \dfrac{uwE(uw)}{E(u^2)E(w^2)}
-\dfrac{w^2}{E(w^2)}\right) d\mu\geq0.$$
Hence, we obtain,  $\lambda^2 uwE(uw)\geq w^2E(u^2)$ on $K$.
Now, taking $E$ on both sides, we get,
$\lambda^2 E(uw)^2\geq E(u^2)E(w^2)$ on $K$.

%proof of 2
(ii) Suppose $\omega(T)$ is  $n$-power posinormal, then $$\lambda^2 \omega(T)^* \omega(T)- \omega(T)^n\omega(T)^{*n} \geq 0 ~\text{for some}~\lambda>0 .$$

Now, for $f\in L^2(\Sigma)$, we have,
$$\omega(T)^* \omega (T)f=\frac{\chi_K u}{E(u^2)^2E(w^2)}E(uf).$$
and
$$\omega(T)^n \omega (T)^{*n}f=\frac{\chi_K wE(uw)^{2n-2}}{E(u^2)^{2n-1}E(w^2)^{2n}}E(wf).$$
Therefore, since $\omega(T)$ is $n$-power posinormal, for all $f\in L^2(\Sigma)$,
\begin{equation}\label{intK1}
\int_{K}^{} \left( \lambda^2 \dfrac{uE(uf)}{E(u^2)^2E(w^2)}
-\dfrac{wE(uw)^{2n-2}E(wf)}{E(u^2)^{2n-1}E(w^2)^{2n}}\right) \overline{f}d\mu\geq0.
\end{equation}
Since $\mathcal{A}$ is $\sigma$-finite, there exists $\{A_m\}\subseteq \mathcal{A}$ such that $X=\cup A_m$, $A_n\subseteq A_{m+1}$
with $A_m\in \mathcal{A}$ with $0<\mu(A_m)<\infty$
Substituting $f_m=w\sqrt{E(u^2)}\chi_{A_m}$ in \ref{intK1}, we get,
$$\int_{K\cap A_m}^{} \left( \lambda^2 \dfrac{uwE(uw)E(u^2)}{E(u^2)^2E(w^2)}
-\dfrac{w^2E(uw)^{2n-2}E(w^2)E(u^2)}{E(u^2)^{2n-1}E(w^2)^{2n}}\right) \overline{f}d\mu\geq0.$$
Thus, we get, $\lambda^2 u E(u^2)^{2n-3}E(w^2)^{2n-2}\geq wE(uw)^{2n-3}$ on $K$.

Now multiplying both sides by $w$ and applying $E$, we obtain,
$$\lambda^2 E(u^2)^{2n-3}E(w^2)^{2n-3}\geq E(uw)^{2n-4}~\text{on}~ K.$$

%proof of 3
(iii) By definition, $\omega(T)$ is $k$-quasi $n$-power posinormal if and only if $$\lambda^2 \omega(T)^{*(k+1)}\omega(T)^{k+1}- \omega(T)^{*k}\omega(T)^n\omega (T)^{*n}\omega(T)^k \geq 0~\text{for some}~ \lambda>0.$$
For $f\in L^2(\Sigma)$, we have, $$\omega (T)f=M_{\frac{\chi_K}{E(u^2)E(w^2)}}Tf.$$
Therefore, for $n \in \mathbb {N}$ we get,
\begin{align*}
\omega(T)^n f&=\frac{\chi_Kw[E(uw)]^{n-1}}{(E(u^2))^n(E(w^2))^n}E(uf).
\end{align*}

Now,
$$\omega(T)^* f=M_{\frac{\chi_K}{E(u^2)E(w^2}}T^*f.$$

Similarly, for $n \in \mathbb {N}$ we get,
\begin{align*}
\omega(T)^{*n} f&=\frac{\chi_Ku[E(uw)]^{n-1}}{E(u^2)^nE(w^2)^n}E(wf).
\end{align*}

Now,
\begin{align*}
\omega(T)^{*k+1} \omega(T)^{k+1}f
&=\frac{\chi_Ku[E(uw)]^{2k}E(uf)}{E(u^2)^{2k+2}E(w^2)^{2k+1}}.
\end{align*}

By similar computation we get,
\begin{align*}
\omega(T)^{*k} \omega(T)^n\omega(T)^{*n} \omega(T)^kf
&=\frac{\chi_Ku[E(uw)]^{2k+2n-4}E(uf)}{E(u^2)^{2k+2n-1}E(w^2)^{2k+2n-2}}.
\end{align*}

Then we obtain,\\

$\langle (\lambda^2 \omega(T)^{*(k+1)} \omega(T)^{k+1}- \omega(T)^{*k}\omega(T)^n\omega (T)^{*n}\omega(T)^k)f, f\rangle$ \\\\


$=\bigint_{X}^{} \left( \lambda^2 \dfrac{\chi_Ku[E(uw)]^{2k}E(uf)}{E(u^2)^{2k+2}E(w^2)^{2k+1}}-\dfrac{\chi_Ku[E(uw)]^{2k+2n-4}E(uf)}{E(u^2)^{2k+2n-1}E(w^2)^{2k+2n-2}}\right) \overline{f}d\mu$\\

$=\bigint_{K}^{} \left(\lambda^2  \dfrac{[E(uw)]^{2k}}{E(u^2)^{2k+2}E(w^2)^{2k+1}}-\dfrac{[E(uw)]^{2k+2n-4}}{E(u^2)^{2k+2n-1}E(w^2)^{2k+2n-2}}\right)|E(uf)|^2d\mu$\\\\

$=\bigint _{K}^{} \dfrac{E(uw)^{2k}}{E(u^2)^{2k+2}E(w^2)^{2k+1}}\left( \lambda^2 -\dfrac{E(uw)^{2n-4}}{E(u^2)^{2n-3}E(w^2)^{2n-3}}\right)|E(uf)|^2d\mu$.\\

This implies that if $\lambda^2 E(u^2)^{2n-3}E(w^2)^{2n-3} \geq E(uw)^{2n-4}$ on $K$, then $\omega(T)$ is $k$-quasi $n$-power posinormal operator for every $n, ~k\in \mathbb{N}$.


Conversely, assume that $\omega(T)$ is a $k$-quasi $n$-power posinormal operator. Then for all $f\in L^2(\Sigma)$, we have
$$\langle (\lambda^2 \omega(T)^{*(k+1)} \omega(T)^{k+1}- \omega(T)^{*k}\omega(T)^n\omega (T)^{*n}\omega(T)^k)f, f\rangle \geq 0.$$

Let $B\in \mathscr{A}$, with $B\subseteq K$ and $0<\mu(B)<\infty$. Taking $f=\chi_B$, we have

$$\bigint_{K}^{} \left( \lambda^2 \dfrac{[E(uw)]^{2k}}{E(u^2)^{2k+2}E(w^2)^{2k+1}}-\dfrac{[E(uw)]^{2k+2n-4}}{E(u^2)^{2k+2n-1}E(w^2)^{2k+2n-2}}\right)|E(u\chi_B)|^2d\mu\geq 0.$$

Therefore,\\
$\bigint_{B}^{} \left( \lambda^2 \dfrac{[E(uw)]^{2k}}{E(u^2)^{2k+2}E(w^2)^{2k+1}}-\dfrac{[E(uw)]^{2k+2n-4}}{E(u^2)^{2k+2n-1}E(w^2)^{2k+2n-2}}\right)E(u^2)d\mu\geq 0.$\\\\
Since $B \in \mathscr{A}$ is arbitrary, we get $\lambda^2 E(u^2)^{2n-3}E(w^2)^{2n-3} \geq E(uw)^{2n-4}$  on $K$. Hence the proof.

%proof of 4
(iv) By similar computation as the above it can be shown that,
 $\omega(T)^*$ is $k$-quasi $n$-power posinormal if and only if
 $\lambda^2E(u^2)^{2n-3}E(w^2)^{2n-3} \geq E(uw)^{2n-4}~\text{on}~K.$
Then by Theorem \ref{THM1} (3), the result follows.

\end{proof}

%corollary 4.1
\begin{corollary}\label{cor4.1}
Let $T=M_wEM_u\in B_C(L^2(\Sigma))$. Then,
\begin{enumerate}
 \item $\omega(T)$ is $n$-power posinormal if and only if
$$\lambda^2E(u^2)^{2n-3}E(w^2)^{2n-3} \geq E(uw)^{2n-4}~\text{on}~ K.$$
\item $\omega(T)$ is posinormal  if and only if
$\lambda^2E(uw)^2\geq E(u^2)E(w^2)$ on $K$.
\end{enumerate}
\end{corollary}

%example 1
\begin{example}\label{ex.4.2}
Let $X=[0,1]$, $d\mu=dx$, $\Sigma$ be the Lebesgue measurable sets and let $\mathscr{A}=\{\phi,X\}$. Therefore, $Tf(x)=w(x)E(uf)(x)=w(x)\int_{0}^{1}u(x)f(x)dx$. Taking $u(x)=\frac{x}{2\sqrt{2}}$ and $w(x)=5x^2+3$, we get $E(u^2)=\frac{1}{24}$, $E(w^2)=24$ and $E(uw)=\frac{11}{8\sqrt{2}}$. Therefore, for $n=2$, $\lambda^2 E(u^2)E(w^2)\geq 1$ if and only if $\lambda^2\geq1$.Thus, if $\lambda^2\geq1$, $\omega(T)$ is $k$-quasi $2$-power posinormal for all $k\in \mathbb{N}$. In general, for $\lambda^2\geq (0.98)^{2n-4}$, then $\omega(T)$ is $k$-quasi $n$-power posinormal for $k,n \in \mathbb{N}$.\\
Now, $\omega(T)$ posinormal if and only if $\lambda^2\geq1.06$.
Therefore,  there exists $\omega(T)$'s which are $k$-quasi $n$-power posinormal, but not posinormal (for example, take  $\lambda^2=0.9$ and $n=4.$)


\end{example}


%section 5%
\section{$k$-Quasi $n$-Power Posinormal Weighted Shifts on Directed Trees}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
This section concludes with an application to weighted shifts on rooted directed trees. After reviewing graph-theoretic preliminaries, we characterize \(k\)-quasi \(n\)-power posinormality for shifts \(S_\mu\) and provide a detailed example on a tree with one root and two branches . The analysis reveals explicit norm conditions dependent on the tree’s weight structure.
%===========================================================================================

A pair $\mathscr{T}=(V,E)$ is a \textit{directed graph} if $V$ is a nonempty set and $E$ is a subset of $V\times V \backslash \{(v,v): v\in V\}$. An element of $V$ is called a \textit{vertex} of $\mathscr{T}$ and an element $E$ is called an \textit{edge} of $\mathscr{T}$.  A directed graph $\mathscr{T}$ is \textit{connected }if for any two distinct vertices $u$ and $v$ of $\mathscr{T}$, there exists a finite sequence $v_1, v_2,\cdots, v_n$ of vertices of $\mathscr{T}$ $(n\geq 2)$ with $u=v_1$, $v=v_n$ and $(v_j,v_{j+1})\in E$ or  $(v_{j+1},v_j)\in E$ for all $1 \leq j\leq n-1$. A  finite sequence $\{v_i\}_{i=1}^{n}$ of distinct vertices is said to be a circuit of $\mathscr{T}$ if $n\geq2$, for $1\leq i \leq n-1$ $(v_i,v_{i+1})\in E$ and $(v_n,v_1)\in E$.  For $W\subset V$, define $\text{Chi}(W)=\bigcup_{u\in W}\{v\in V:(u,v)\in E\}$. Inductively, for $n\in \mathbb{Z}_+$, $\text{Chi}^{<n>}(W)=W$ if $n=0$ and $\text{Chi}^{<n>}(W)=\text{Chi}(\text{Chi}^{<n-1>}W)$, if $n\geq1$. Given $v\in V$,  $\text{Chi}(v)= \text{Chi}(\{v\})$ and  $\text{Chi}^{<n>}(v)= \text{Chi}^{<n>}(\{v\})$.
 A member of $\text{Chi}(v)$ is called a \textit{child} of $v$. For  $u\in V$ if there exists a unique vertex $v\in V$ such that $(v,u)\in E$, then $v$ is said to be a \textit{parent} of
$u$ and is denoted as $\text{par}(u)=v$. A vertex $v$ of $\mathscr{T}$ is called a \textit{root} of $\mathscr{T}$ or $v\in Root(\mathscr{T})$, if there is no vertex $u$ of $\mathscr{T}$ such that $(u,v)\in E$. If $Root(\mathscr{T})$ is a singleton set, then the unique element is denoted by root. We write,
$V^0:=V \backslash Root(\mathscr{T})$. 
A directed graph $\mathscr{T}=(V,E)$ is called a \textit{directed tree} if $\mathscr{T}$ is connected,
$\mathscr{T}$ has no circuits, and each vertex $v\in V^0$ has a parent. Any directed tree has atmost one root \cite{Jablon}.



Let $\ell^2(V)$ denotes the Hilbert space of square summable complex functions on $V$ equipped with the standard inner product. The set $\{e_u\}_{u\in V}$ is an orthonormal basis of $\ell^2(V)$, where $e_u \in \ell^2(V)$ is the indicator function of $\{u\}$. For a system $\mu=\{\mu_v\}_{v\in V^0}$
of non-negative real numbers, define the \textit{weighted shift operator} $S_{\mu}$ on $\mathscr{T}$ with weights $\bold{\mu}$ by
$$S_{\mu}f:=\Lambda_{\mathscr{T}}f, f\in \mathscr{D}(S_{\mu}),$$
where, $$\mathscr{D}(S_{\mu}):=\{f \in \ell^2(V): \Lambda_{\mathscr{T}}f \in \ell^2(V)\}$$ and for $f\in \ell^2(V)$, $\Lambda _{\mathscr{T}}$ is the mapping given by

$$(\Lambda _{\mathscr{T}}f)(v):=
\begin{cases}
	\mu_v. f(\text{par}(v))& \text{if } v\in V^0,\\
	0 & \text{if v is a root of}~ \mathscr{T}.
\end{cases}$$


If $S_\mu$ is a densely defined weighted shift on the directed tree $\mathscr{T}$ with weights $\mu=\{ \mu_v\}_{v\in V^0}$, then
 $e_u\in \mathscr{D}(S_\mu^*)$ and $$S_{\mu}^*e_u=
\begin{cases}
\overline{\mu_u}e_{\text{par}(u)}&;~ u\in V^0\\
0 &; ~ \text{if u is a root of}~ \mathscr{T}
\end{cases}$$ \cite{Jablon}. Let $S_{\mu}$ be a weighted shift on a directed tree $\mathscr{T}$ with weights $\mu=\{\mu_v\}_{v\in V^0}$ and let $\sup\limits_{u\in V} \text{card}(\text{Chi}(u))<\infty$. Then $S_{\mu}\in B(\ell^2(V))$ if and only if $\sup\limits_{v\in V^0}|\mu_v|<\infty$  \cite{Jablon}. We refer \cite{Jablon} for more information regarding a weighted shift on a directed tree.




\begin{theorem}\label{thm5.4}
Let $S_{\mu}\in B(\ell^2(V))$ be a non-zero weighted shift on a directed tree $\mathscr{T}$ with weights $\mu=\{\mu_v\}_{v\in V^0}$. Then $S_{\mu}$ is $k$-quasi $n$-power posinormal operator if and only if $\lVert S_{\mu}^{*n}S_{\mu}^k f \rVert^2 \leq \lambda^2 \lVert S_{\mu}^{k+1}f\rVert^2$, for all $f\in \ell^2(V)$ and for some $\lambda >0$.
\end{theorem}

\begin{proof}
$S_{\mu}$ is $k$-quasi $n$-power posinormal operator if and only if
$$S_{\mu}^{*k}[\lambda ^2 S_{\mu}^*S_{\mu}-S_{\mu}^n S_{\mu}^{*n}]S_{\mu}^k\geq 0.$$
$$\Longleftrightarrow \langle (\lambda ^2 S_{\mu}^{*k+1}S_{\mu}^{k+1}-S_{\mu}^{*k}S_{\mu}^n S_{\mu}^{*n}S_{\mu}^k)f,f\rangle\geq0,~ \text{for all} ~f\in \ell^2(V). $$
$$\Longleftrightarrow \lVert S_{\mu}^{*n}S_{\mu}^k f \rVert^2 \leq \lambda^2 \lVert S_{\mu}^{k+1}f\rVert^2 ~ \text{for all} ~f\in \ell^2(V).$$

\end{proof}

\begin{example}\label{ex5.5}
Let $\mathscr{T}=(V,E)$ be a directed tree with one root and $V^0=\{v_{ij};i=1,2 ~\text{and}~ j=1,2, \cdots\}$ such that $\text{card}(\text{Chi}(root))=2$ and $\text{card}(\text{Chi}(v))=1$ for all $v\in V^0$.
Let $S_{\mu}$ be the weighted shift on $\mathscr{T}$ with weights given by,
$$\mu_{v_{11}}=1, ~\mu_{v_{1j}}=2 ~\text{for all} ~j\geq2$$
$$\text{and}~\mu_{v_{22}}=\frac{1}{2}, ~\mu_{v_{2j}}=2 ~\text{for all} ~j \neq 2.$$

By \ref{PROP1}, $S_{\mu}\in B(\ell^2(V))$.

Now, $S_{\mu}e_{root}=e_{v_{11}}+e_{v_{21}}$,  $S_{\mu}(e_{v_{1j}})=2  e_{v_{1j+1}} $, for $j\geq1$.

$S_{\mu}(e_{v_{21}})=\frac{1}{2}  e_{v_{22}} $, $S_{\mu}(e_{v_{2j}})=  e_{v_{2j+1}} $, for $j\geq2$.\\
Now,
$$S_{\mu}^*e_u=
\begin{cases}
\overline{\mu_u}e_{\text{par}(u)}&;~ u\in V^0,\\
0 &; ~ u=\text{root}.
\end{cases}$$

Therefore, $S_{\mu}^*(e_\text{root})=0$,

$$S_{\mu}^*e_{v_{1j}}=
\begin{cases}
e_{\text{root}} &; ~ j=1,\\
2e_{v_{1j-1}} &;~j\geq 2.
\end{cases}$$

and
$$S_{\mu}^*e_{v_{2j}}=
\begin{cases}
e_{\text{root}} &; ~ j=1,\\
\frac{1}{2}e_{v_{21}} &; j=2,\\
e_{v_{2j-1}} &;~j> 2.
\end{cases}$$

Let $f\in \ell^2(V)$ and $f=\alpha_0e_{root}+\sum\limits_{j=1}^{\infty}\alpha_{1j}e_{v_{1j}}+\sum\limits_{j=1}^{\infty}\alpha_{2j}e_{v_{2j}}$. Then,

$S_{\mu}f=\alpha_0e_{v_{11}}+\alpha_0e_{v_{21}}+\sum\limits_{j=1}^{\infty}\alpha_{1j}e_{v_{1j+1}}+\frac{1}{2} \alpha_{21} e_{v_{22}}+\sum\limits_{j=1}^{\infty}\alpha_{2j}e_{v_{2j+1}}$.

In general,

$S_{\mu}^kf=2^{k-1}\alpha_0e_{v_{1k}}+\frac{1}{2}\alpha_0e_{v_{2k}}+2^k\sum\limits_{j=2}^{\infty}\alpha_{1j}e_{v_{1j+k}}+\frac{1}{2} \alpha_{21} e_{v_{2k+1}}+\sum\limits_{j=2}^{\infty}\alpha_{2j}e_{v_{2j+k}}$.

Therefore,

$\lVert S_{\mu}^{k+1}f\rVert^2=2^{2k}|\alpha_0|^2+\frac{1}{4}|\alpha_0|^2+2^{2k+2}\sum\limits_{j=2}^{\infty}|\alpha_{1j}|^2+\frac{1}{4}|\alpha_{21}|^2+\sum\limits_{j=2}^{\infty}|\alpha_{2j}|^2$.

By computations, we get, for $k-n>1$,
$$S_{\mu}^{*n}S_{\mu}^kf=2^{k+n-1}\alpha_0e_{v_{1k-n}}+\frac{1}{2}\alpha_0e_{v_{2k-n}}+2^{k+n}\sum\limits_{j=2}^{\infty}\alpha_{1j}e_{v_{1j+k-n}}+\frac{1}{2} \alpha_{21} e_{v_{2k-n+1}}+\sum\limits_{j=2}^{\infty}\alpha_{2j}e_{v_{2j+k-n}}.$$

Therefore, for $k-n>1$,
$$\lVert S_{\mu}^{*n}S_{\mu}^kf\rVert^2=2^{2k+2n-2}|\alpha_0|^2+\frac{1}{4}|\alpha_0|^2+2^{2k+2n}\sum\limits_{j=2}^{\infty}|\alpha_{1j}|^2++\sum\limits_{j=2}^{\infty}|\alpha_{2j}|^2.$$

Taking, $$y_1=2^{2k}|\alpha_0|^2, y_2=\frac{1}{4}|\alpha_0|^2, y_3= 2^{2k+2}\sum\limits_{j=2}^{\infty}|\alpha_{1j}|^2, y_4=\frac{1}{4}|\alpha_{21}|^2~ \text{and}~ y_5=\sum\limits_{j=2}^{\infty}|\alpha_{2j}|^2,$$

we get, for $k>n+1$ $S_{\mu}$ is $k$-quasi $n$-power posinormal if and only if $$\lambda^2\geq \dfrac{2^{2n-2}y_1+y_2+2^{2n}y_3+y_4+y_5}{y_1+y_2+y_3+y_4+y_5}.$$
Since $y_i\geq 0$, for all $i$, we can see that, $2^{2n}$ is a upper bound for $\dfrac{2^{2n-2}y_1+y_2+2^{2n}y_3+y_4+y_5}{y_1+y_2+y_3+y_4+y_5}.$
Therefore, taking $\lambda\geq2^{n}$, $S_{\mu}$ is $k$-quasi $n$-power posinormal for $k>n+1$.
\end{example}
