Gate complementation utilizes the specific properties of $\A$.  The
automaton $\A$ accepts the language $L_1.\{c\}.L_2$ where
$L_1=\langof{A_1}$ and $L_2=\langof{A_2}$.  A word
$w \in\Sigma^*$ belongs to
$\compl{L_1.\{c\}.L_2}$ in the following cases:
% \begin{enumerate}
%     \item $w$ does not contain any $c$. \label{item:gate-nogsym}
%     \item $w = ucv$, where $u \in (\Sigma\smallsetminus\{c\})^*$, and either 
%     \begin{enumerate}
%         \item $u \notin L_1$, or \label{item:gate-pre}
%         \item $v \notin L_2$. \label{item:gate-suf}
%     \end{enumerate}
% \end{enumerate}
\begin{enumerate}
    \item $w$ does not contain any $c$, \label{item:gate-nogsym}
    \item $w = ucv$ where $u \in (\Sigma\smallsetminus\{c\})^*$ and $u \notin L_1$, or \label{item:gate-pre}
    \item $w = ucv$ where $u \in (\Sigma\smallsetminus\{c\})^*$ and $v \notin L_2$. \label{item:gate-suf}
\end{enumerate}

Let
$\C_1 = (\elc{Q}_1, \Sigma\smallsetminus\{c\}, \elc{\delta}_1,
\elc{I}_1, \elc{F}_1)$ be an arbitrary complement of $\A_1$ with
respect to the alphabet $\Sigma\smallsetminus\{c\}$ and
$\C_2 = (\elc{Q}_2, \Sigma, \elc{\delta}_2, \elc{I}_2, \elc{F}_2)$ be
an arbitrary complement of~$\A_2$ with respect to the alphabet
$\Sigma$. Then, the complement~$\C$ of~$\A$ consists of two parts:
$\pre{\C}$~accepting the words according to Case~\ref{item:gate-pre} and
$\suf{\C}$~accepting the words according to Cases~\ref{item:gate-nogsym}
and~\ref{item:gate-suf}. Schemes of $\C$, $\pre{\C}$, and $\suf{\C}$ can be seen in
\cref{fig:gate-simple}.

Formally, we set $\C = \pre{\C} \Cup \suf{\C}$ where
$\pre{C} = (\elc{Q}_1 \cup \{s\}, \Sigma, \pre{\delta}, \elc{I}_1,
\{s\})$ and
$\suf{C} = (\elc{Q}_2 \cup \{t\}, \Sigma, \suf{\delta}, \{t\}, \{t\}
\cup \elc{F}_2)$ such that $s,t$ are fresh states,
\begin{align*}
    \pre{\delta} &= \elc{\delta}_1 \cup \{p \xrightarrow{c} s \mid p \in \elc{F}_1\} \cup \{s \xrightarrow{a} s \mid a \in \Sigma\} \text{, and } \\
    \suf{\delta} &= \elc{\delta}_2 \cup \{t \xrightarrow{c} p \mid p \in \elc{I}_2\} \cup \{t \xrightarrow{a} t \mid a \in \Sigma\smallsetminus\{c\}\}.
\end{align*}
The correctness of the construction is proven in \cref{app:proofs}.

