 (see Definition~\ref{regu}).
 Then $L\th$ is a CR function of class $C^s$
 and
 strict pseudoconvexity implies $L\th\ne 0$.
Hence we can
define
 \beq
 \Label{l-def}
 \mathcal L:=\frac{1}{L\theta}L
 \quad
 \Longrightarrow
 \quad
 \mathcal L\theta=1.
 \eeq
 %(we use the above basic $(0,1)$ section $L$). 
% We then have $$,$$ according to \eqref{eqdelta}.

Now, applying $\mathcal L$ once to \eqref{condit} and using \eqref{l-def}, we obtain
\beq\Label{L}
\mathcal L\Phi=a_1+2a_2\theta+3a_3\theta^2,
\eeq
where we took into account the fact that all the $a_j$ are CR-functions. 
Note that the latter implies the regularity condition 
$$
\mathcal L\Phi  \in C^{s-2}(U),\quad L\Phi=L\theta\cdot\mathcal L\Phi\in C^{s-2}(U).
$$
Repeating this argument three more times, we get respectively
\beq\Label{L2}
\mathcal L^2\Phi=2a_2+6a_3\theta,\eeq
then
\beq\Label{L3}
\mathcal L^3\Phi=6a_3,\eeq
and finally:
\beq\Label{spherical}
\mathcal L^4\Phi=0,\quad L^4\Phi=0
\eeq
(see the discussion in the Introduction).
Furthermore, we have the improved regularity properties
\beq\Label{improved}
\mathcal L\Phi,\mathcal L^2\Phi,\mathcal L^3\Phi,L\Phi,L^2\Phi,L^3\Phi\in C^{s-2}(U).
\eeq 
Thus, the differential equation \eqref{spherical} and the regularity conditions \eqref{improved}  give  necessary conditions for the sphericity of $M$, and this proves the necessity in \autoref{main-2}. 
\end{proof}

