	\centering
	\includegraphics[width = .35\textwidth]{figs/sg.pdf}
	\caption{SG.}
	\label{fig:sg}
\end{figure}


  The sequence of graphs $\Gamma_n=(V_n,E_n)$ approximating $K$ is constructed as follows.
  Let $V_n$ stand for the set of vertices of $\Gamma_n$. Then $V_0=\{ v_1, v_2, v_3\}$ and
  for $n\ge 1$ set
  $$
V_n=\bigcup_{i=1}^3 F_i(V_{n-1}).
$$
Further, $\Gamma_0$ is the complete graph on three nodes. To describe the set of edges of $\Gamma_n$,
we need an alphabet $S\doteq \{1,2,3\}$
and the set of words consisting of $n$ symbols, $S^n$.
Then  $v_i,v_j \in V_n$ are adjacent (denoted by either $v_i\sim_n v_j$, or simply $i\sim_n j$) if there is $w=(w_1,w_2,\dots, w_n)\in S^n$,
such that 
$$
v_i,v_j\in F_w(V_0), \quad\mbox{where}\quad F_w\doteq F_{w_1}\circ F_{w_2}\circ\dots\circ F_{w_n}.
$$
Geometrically, $\Gamma_0$ is a triangle with vertices $v_1, v_2,$ and $v_3$, and
$\Gamma_n=\bigcup_{w\in S^n} F_w(\Gamma_0)$. Two nodes $v_i,v_j\in V_n$ are adjacent
if both belong to the same $n$--cell $F_w(\Gamma_0)$ for some $w\in S^n$
(see Fig.~\ref{fig:sg_graphs}).
\begin{figure}[h]
	\centering
	\includegraphics[width = .9\textwidth]{figs/sg_graphs.pdf}
	\caption{Graphs $\Gamma_n$ approximating SG.}
	\label{fig:sg_graphs}
      \end{figure}
      There are $\frac{3}{2}\left(3^n-1\right)$ vertices of $\Gamma_n$. We will distinguish between
      the boundary vertices given by $V_0=\{v_1, v_2, v_3\}\subset V_n$ and the interior vertices
      $V_n\setminus V_0$. Note that the interior vertices have degree $4$ while the boundary ones
      have degree $2$.

We pause to explain the  coding of the nodes of the graphs
approximating $K$. Let $T$ denote the solid triangle with vertices $v_1, v_2,$ and
$v_3$. Every node from $V_n$ is a vertex of the corresponding triangle
$$
T_w=F_w(T),\; w=(w_1,w_2,\dots ,w_n) \in S^n
%;\quad\mbox{where}\quad F_w\doteq F_{w_1}\circ F_{w_2}\circ\dots\circ F_{w_n}.
$$ 
and can be represented
as
$$
\bigcap_{k=1}^\infty
F_{ w\underbrace{ \scriptscriptstyle iii\dots i}_\text{\normalfont $k$ times}}\,(T).
$$
For each node in $V_n$ we define an itinerary $w\bar{i}$,
where $\bar{i}$ stands for the infinite sequence of $i$'s: $iii\dots,$ $i\in S$.
Note that for $v\in V_n\setminus V_0$ there are two possible itineraries, e.g.,
$v_{1\bar{2}}$ and $v_{2\bar{1}}$
correspond to the same node from $V_2$.   We order the vertices in $V_n$ by the
corresponding itineraries in lexicographical order:
\begin{equation}\label{order-nodes}
V_n=\{ v_{\bar 1}, v_{\bar 2}, v_{\bar 3}, v_{1\bar 1}, v_{1 \bar 2}, \dots\}.
\end{equation}
Abusing notation, we will use $v_1, v_2, v_3, v_4, \dots$ to denote the elements of $V_n$
appearing in the same order as in \eqref{order-nodes}.






Now we are ready to formulate the KM on $\Gamma_n$:
\begin{equation}\label{KM-intro}
  \dot u(t,v_i)=\left(\frac{5}{3}\right)^n \sum_{j\sim_n i} \sin\left(2\pi\left(u(t,v_j)-u(t,v_i)\right)\right), \quad
  v_i\in  V_n,
\end{equation}
where $u(t,v_i)$ represents the state of oscillator located at $v_i$ at time $t$. The scaling factor $\left(\frac{5}{3}\right)^n$
is used so that the model has a nontrivial continuum limit as $n\to\infty$.


It is instructive to rewrite the KM on $\Gamma_n$ as the gradient system
\begin{equation}\label{KM-grad}
  \dot u=-2\pi \nabla  \cJ_n(u), \quad u= (u(t,v_1),u(t,v_2),\dots, u(t,v_{k_n})),
\end{equation}
where
\begin{equation}\label{KM-energy}
\cJ_n(u) \doteq \left(\frac{5}{3}\right)^n\frac{1}{4\pi^2} \sum_{(i,j)\in E_n} \left( 1-\cos\left(2\pi(u(t,v_j)-u(t,v_i))\right)\right).
\end{equation}
We use the convention that each (undirected) edge $(i,j)\in E_n$ appears only once in the sum to avoid double-counting. The factor $\frac{1}{4\pi^2}$ is taken for convenience of future analysis. 

Since \eqref{KM-grad} is a gradient system, its attractor coincides with the set of minima of the energy
function $\cJ_n$. Due to translation invariance of \eqref{KM-intro} the points of minimum of $\cJ_n$ are
not isolated. To eliminate this translation invariance, we fix the value at $v_1$ in the steady-state solutions of \eqref{KM-intro}
to $0$. This leads to the following minimization problem:
\begin{equation}\label{min-intro}
  \cJ_n \;\rightarrow\; \min_{H_n},\quad H_n\doteq \{ u\in L(V_n, \T):\; u(v_1)=0\},
\end{equation}
where $L(X,Y)$ denotes the space of functions with domain $X$ and co-domain $Y$.

The main result of this paper reveals the link between the structure of the attractor of \eqref{KM-intro} and the
topology of the SG. We show that there is one-to-one correspondence between the homotopy classes
of continuous functions from the SG to $\T$ and stable equilibria of \eqref{KM-intro}.


Before formulating the
main result, we review the homotopy classes of continuous maps on SG following \cite{MM2024}.
To this end, let
        $$
        \mathcal{P}_n=\left\{ \partial T_w,\; w\in S^n\right\} \quad \mbox{and}\quad
        \mathcal{P}= \bigcup_{n=0}^\infty   \mathcal{P}_n.
        $$

        For each triangular loop $\gamma\in\mathcal{P}$, we choose a reference point $O_\gamma\in\gamma$.
        For concreteness, let $O_\gamma$ be the leftmost vertex of $\gamma$.
% For $f\in C(G,\T)$ and $\gamma\in\mathcal{P}$, consider $f_\gamma\doteq f\left|_\gamma\right.$, the
% restriction of $f$ to $\gamma$.
Choose a \textit{uniform} parametrization
$c_\gamma:\T\to\gamma$, which starts at $O_\gamma$, $c_\gamma(0)=O_\gamma$, and traces $\gamma$ in clockwise
direction with constant speed.
% Throughout this paper, we will always
% assume that for $\gamma\in \mathcal{P}$, $O_\gamma$ is the leftmost vertex of the  triangle
% $T_w$ such that $\gamma=\partial T_w$.


For a given $f\in C(K,\T)$,  $f_\gamma\doteq f\circ c_\gamma$ is a continuous function
from $\T$ to itself\footnote{Throughout this paper, $c_\gamma$ is a uniform parametrization, i.e.,
$\dot c_\gamma=1.$}. There is   a unique continuous function $\bar{f}_\gamma:\R\to\R$
such that
\begin{align} \label{lift-1}
  \hat{f}_\gamma(0)&= f(0),\\
  \label{lift-2}
  \hat{f}_\gamma(x)&= f(x\mod 1) + k(x), \quad k(x)\in \Z.
\end{align}
The second condition \eqref{lift-2} can be written as 
\begin{equation}\label{lift-3}
\pi\circ \hat f_\gamma=  f_\gamma \circ \pi,
\end{equation}
where $\pi: \,\R\ni x\mapsto x\mod 1.$ 

$\hat{f}_\gamma$ is called the lift of $f_\gamma$. 
The degree of $f_\gamma$ is expressed in terms of the lift of 
$f_\gamma$:
$$
\omega(f_\gamma)\doteq \hat{f}_\gamma(1)-\hat{f}_\gamma(0).
$$

\begin{definition}\label{def.w-vector}
  The degree of $f\in C(K,\T)$ is defined by
  \begin{equation}\label{w-vector}
    \bar\omega(f)=\left(\omega_{\gamma_0}(f), \omega_{\gamma_1}(f), 
    \omega_{\gamma_2}(f),\dots \right),
\end{equation}
where $\omega_\gamma(f)\doteq\omega(f_\gamma)$.
\end{definition}

\begin{remark}
    Since $f$ is uniformly continuous on $K$, the number of nonzero entries in \eqref{w-vector}
    is finite. Unless specified otherwise, we use the topology on $K$ induced by the Euclidean metric.
\end{remark}

\begin{definition}\label{def.homotopy}
  Two maps $f,g \in C(K,\T)$ are called homotopic, denoted $f\sim g$, if there exists a continuous mapping
  $F: [0,1]\times K\to \T$ such that
  \begin{equation}\label{F-hom}
    F(0,\cdot)=f\qquad\mbox{and}\quad F(1,\cdot)=g.
    \end{equation}
  \end{definition}

  \begin{theorem}\label{thm.homotopy}(Theorem 2.4 in \cite{MM2024}) Let $f,g \in C(K,\T)$. Then
    $f\sim g$ if and only if $\bar\omega(f)=\bar\omega(g)$.
  \end{theorem}

  We will need the following result on harmonic maps from SG to the circle. It follows from \cite{Strich02}.
  For a given $\omega^\ast\in \Z^\ast \doteq \bigcup_{l=1}^\infty \Z^l$ there exists a unique solution $u^\ast \in L(K,\T)$
  of the following boundary value problem:
  \begin{align}\label{HM-Lap}
    \Delta u^\ast & =0,\\
    \label{HM-dir}
    u^\ast(v_1)&= 0,\\
    \label{HM-neu}
    \partial_{\bf n} u^\ast (v_i) &=0,  i=1,2,3, \\
    \label{HM-deg}
    \bar \omega(u^\ast)&=\omega^\ast,
    \end{align}
    where $\partial_{\bf n}$ stands for the normal derivative \cite{Str06}.

    We can now formulate the main result of this work. Below, we will generalize this result for the KM
  on p.c.f. fractals, but for now we restrict our attention to the KM on SG.
    \begin{theorem}\label{thm.main-sg}
