 The remainder of this paper will be mainly focused on proving Theorem \ref{thm.main-sg}. We will begin by considering a simpler variation of the problem with trivial degree (i.e., $\bar \omega(u^*)=(0,0,\dots)$) and Dirichlet boundary conditions (cf. \eqref{HM-neu}). This problem is interesting in its own right, but also serves to build intuition and develop the necessary tools for the main result. In Section \ref{sec.harmSG} we review the necessary background on  harmonic functions on SG, and in Section \ref{sec.gamma} we combine $\Gamma$-convergence and a priori H\"older estimates to establish the convergence of KM equilibria to these (real-valued)  harmonic functions (Theorem \ref{thm:conv_minSG}). In Section \ref{sec.near} we translate these techniques to the setting of the KM on nearest-neighbor graphs. In particular, we show how covering spaces are used to adapt the results to $\T$-valued harmonic maps. We will then be prepared to prove Theorem \ref{thm.main-sg}. In Section \ref{sec.hmaps} we first review the necessary theory of $\T$-valued harmonic maps on SG, and in Section \ref{sec.proof} we complete the remaining details for Theorem \ref{thm.main-sg}. Finally, in Section \ref{sec.pcf} we describe how these results can be applied in a more general setting to study the KM on post-critically finite fractals.


\section{Harmonic functions on SG}\label{sec.harmSG}
\setcounter{equation}{0}

Harmonic functions can be defined as minimizers of the Dirichlet energy (cf.~\cite{Struwe-PDE}).
On a Euclidean domain, the Dirichlet energy is given by
\begin{equation}\label{Dir-Euc}
  \cI(u)=\frac{1}{2}\int_\Omega \left| \nabla u\right|^2 dx,\qquad \Omega\subset\R^d.
\end{equation}
On a fractal set, partial derivatives are not defined in general. Instead, the Dirichlet energy is defined
as a limit of the functionals $\cE_n$ defined using graphs approximating a given fractal
(see Figure~\ref{fig:sg_graphs}). For the reader's convenience, we outline the limiting procedure below and
refer the interested reader to \cite{Kig01} for details.% The approach works for p.c.f. fractals, which we postpone until Section \ref{sec.pcf}. For
%clarity of presentation, we restrict to SG only.


First, we construct the sequence of graphs $(\Gamma_m)$
approximating SG (Figure~\ref{fig:sg_graphs}). 
On $\Gamma_m$ we define the discrete Laplacian
\begin{equation}\label{n-Laplace}
   \Delta_m f(v_i)=\left(\frac{5}{3}\right)^m\sum_{j\sim_m i} \left[f(v_j)-f(v_i)\right], \quad f\in L(V_n,\R).
\end{equation}

A function $f_m^* \in L(V_m,\R)$ is called $\Gamma_m$-harmonic if it satisfies the discrete
	Laplace equation at every interior node of $\Gamma_m$:
	\begin{equation}\label{d-harm}
	\Delta_mf_m^*(v)=0\quad \forall v\in V_m\setminus V_0.
              \end{equation}
Equivalently, harmonic functions are critical points of the associated Dirichlet forms
\begin{equation}
	\cE_m(f) \doteq \left(\frac{5}{3}\right)^m\sum_{(i,j)\in E_n} \frac{(f(v_j)-f(v_i))^2}{2},\quad f\in L(V_n,\R).\end{equation}
   The sequence of Dirichlet forms $(\mathcal{E}_m)$ has the following 
properties.
\begin{enumerate}
    \item A $\Gamma_m$-harmonic $f_m^\ast\in L(V_m,\R)$ minimizes $\mathcal{E}_m$ 
    over all functions subject
    to the same boundary conditions
    \begin{equation}\label{variational-harmonic}
    \mathcal{E}_m(f_m^\ast)=\min\left\{ \mathcal{E}(f):\; f\in L(V_m,\R), \; f|_{V_0}=f_m^\ast|_{V_0}\right\}.
    \end{equation}
\item The minimum of the energy over all extensions of 
$f\in L(V_{m-1},\R)$ to $V_m$ is equal to $\mathcal{E}_{m-1}(f)$:
\begin{equation}\label{variational-extension}
 \min\left\{ \mathcal{E}_m(\tilde f):\; \tilde f\in L(V_m,\R), 
 \tilde f|_{V_{m-1}}=f\in L(V_{m-1},\R)\right\} = \mathcal{E}_{m-1}(f).
\end{equation}
In particular,
\begin{equation}\label{marting}
  f^\ast_{m+1}|_{V_m}=f^\ast_m.
  \end{equation}
\end{enumerate}
The first property follows from the
Euler-Lagrange equation for $\cE_m$. This property does not depend on the scaling
coefficient $(5/3)^m.$ The second property, on the other hand, holds 
due to the choice of the scaling constant.  The sequence of 
$(\mathcal{E}_m)$ equips $K$ with a \textit{harmonic structure} (cf.~\cite{Kig01}).

Now let $f$ be a continuous function on $K$, $f\in C(K,\R)$. Define 
$
P_m: C(K,\R)\to L(V_m,\R)
$
by restricting $f$ to $V_m$:\;
$
P_m f\doteq f|_{V_m}.
$
We next extend the definition of $\cE_m$ to functions in $C(K,\R)$ (which we also denote by $\cE_m$ by abuse of notation):
$$
\cE_m(f):= \cE_m\circ P_m(f).
$$
By \eqref{variational-extension}, $(\cE_m(f))$ is a non-decreasing sequence. Thus,
\begin{equation}\label{monotone-conv}
\cE(f)\doteq \lim_{m\to\infty} \cE_m(f)
\end{equation}
defines a functional on $C(K,\R)$. 

 The domain of the Laplacian on $K$ is defined by
$$
\operatorname{dom}(\cE)=\left\{ f\in C(K,\R):\; \cE(f)<\infty \right\}.
$$

\begin{definition}\label{def.R-harm}
A function $f\in \operatorname{dom}(\cE)$ is called harmonic if it 
minimizes $\cE(f)$ over all continuous functions on SG subject to boundary conditions 
on $V_0$.
\end{definition}


The combination of \eqref{variational-harmonic} and \eqref{variational-extension}, implies that 
the restriction of harmonic $f\in \operatorname{dom}(\cE)$ to $\Gamma_m$,
  $f\left|_{\Gamma_m}\right.$, is
$\Gamma_m$-harmonic on $\Gamma_m$ for every $m\in\N$.


      The second property of the energy form (cf.~\eqref{variational-extension})  yields a
      a recursive algorithm for computing the values of a harmonic function on 
      $V_\ast=\bigcup_{m=0}^\infty V_m$, a dense subset
      of $K$. For $m=0$, the values on $V_0$ are prescribed:
      $$
      f|_{V_0}=\phi.
      $$
      Given $f|_{V_{m-1}},\; m\ge 1,$ the values on $V_m\setminus V_{m-1}$ are computed using the
      following $\frac{1}{5}-\frac{2}{5}$ rule, which we state for an arbitrary fixed $(m-1)$-cell
      $T_w,\; w\in S^{m-1}$: Suppose the values of $f$ at $a, b, c$, the nodes of $T_w$, are
 known. Then the values of $f$ at $x,y,z,$ the nodes at the next level of discretization  are 
 computed as follows 
\begin{equation}\label{classical-extension}
\begin{pmatrix} f(x) \\ f(y)\\ f(z)
\end{pmatrix}
=
\begin{pmatrix}
    \frac{2}{5} &  \frac{2}{5} &  \frac{1}{5}\\
     \frac{1}{5} &  \frac{2}{5} &  \frac{2}{5}\\
      \frac{2}{5} &  \frac{1}{5} &  \frac{2}{5}
\end{pmatrix}
\begin{pmatrix} f(a) \\ f(b)\\ f(c)
  \end{pmatrix},
\end{equation}
%where $f_v$ stands for the value of $f$ at $v\in V_m$ 
see Fig.~\ref{fig:harm_ext}.
\begin{figure}[h]
	\centering
	\includegraphics[width  =.3\textwidth]{figs/harm_ext.pdf}
	\caption{Harmonic extension algorithm for harmonic functions, see \eqref{classical-extension}.}
	\label{fig:harm_ext}
\end{figure}

      This algorithm is called \textit{harmonic extension}.
      Using \eqref{variational-extension}, one can show that at each step of the harmonic extension:
      $$
      \cE_m(f|_{V_m})=\cE_0(f|_{V_0})=\min \left\{ \cE_m(f):\; f\in L(V_m,\R),\; f|_{V_0}=\phi\right\}.
      $$
      Note that each of  $f|_{V_m}$ is a $\Gamma_m$-harmonic function. Further, harmonic extension
      results in a uniformly continuous function on $V_*$. Thus, the values of $f$ on $G\setminus V_*$ can
      be obtained from those on $V_*$ by continuity.

      Finally, the following H\"older estimate will be used to provide
      compactness needed for convergence of the energies and the equilibria of the KM.
  %    In order to establish convergence of energies and equilibria, we will also require additional compactness.
  %    Indeed, functions in the domain of $\cE$ satisfy a H\"older estimate.
%      
%      \begin{definition}
%      	The {\em effective resistance metric}, $R(x,y)$ is defined by
%      	\begin{equation*}
%      		R(x,y)^{-1} = \min\{\cE(u) : u\in C(G,\R), u(x)=0,\quad u(y)=1\}.
%      	\end{equation*}
%      \end{definition}
%Then $R$ is a metric on $G$, and it can be shown that $R(x,y)$ is equivalently the minimum value so that
%\begin{equation}\label{eq:eff_res_holder}
%	|u(x)-u(y)|^2\leq R(x,y)\cE(u)
%\end{equation}
%for all $u\in \operatorname{dom}(\cE)$ \cite{Str06}. That is, all   $u\in \operatorname{dom}(\cE)$ are H\"older continuous of order 1/2.  
\begin{lemma}[cf. \cite{Str06,Kozlov1993}]\label{lem.SG_holder}
	If $f\in \operatorname{dom}(\cE)$ then
	\begin{equation*}
	\frac{|f(x)-f(y)|}{|x-y|^{\beta}}\leq C\sqrt{\mathcal{E}(f)},
	\end{equation*}
        where  $\beta = \frac{\log(5/3)}{2\log(2)}$ and $C$ is independent of $f$.
\end{lemma}
