\section{$\Gamma$-convergence}\label{sec.gamma}
\setcounter{equation}{0}

$\Gamma$-convergence is our main tool for studying the asymptotic
behavior of stable equilibria in the KM for large $n$.
Below we recall the definition of $\Gamma$-convergence on metric spaces and refer the reader to \cite{Braides-handbook} for further details.

% Introduced by De~Giorgi in the 1970s, $\Gamma$-convergence
% has become a powerful tool of the calculus of variations with applications ranging from
% discrete-to-continuum problems, to homogenization, to geometric flows and phase
% transitions (cf.~\cite{Braides-handbook}). We remind the reader the definition of
% $\Gamma$-convergence and refer to \cite{Braides-handbook} for further details.

\begin{definition} \label{def.Gamma} Let $(X,d)$ be a metric space and
        $F_n,F\colon X\to \overline{\R}:=\R\cup \{\pm \infty\}$ be a sequence of functionals.
        Then $F_n$ {\it $\Gamma$-converges} to $F$, written 
        $\Gamma$-$\lim F_n = F$, if the following two conditions hold.
	\begin{enumerate}
		\item[C1.] For all $x_n\in X$ with $x_n\to x\in X$, $F(x)\leq \liminf_{n\to\infty} F_n(x_n)$.
		\item[C2.] For all $x\in X$, there is some $x_n\to x$ so that $F(x)\geq \limsup_{n\to\infty} F_n(x_n)$.
	\end{enumerate}
\end{definition}

\begin{remark} Sequence $(x_n)$ in C2 is called  a \textit{recovery sequence}.
The combination of C1  and C2 implies that
% In view of C1, C2  can be rewritten as follows:
for every $x\in X$, there exists $x_n\to x$ such that
	\begin{equation*}
		F(x) = \lim_{n\to\infty} F_n(x_n).
	\end{equation*}
      \end{remark}

      Let $X$ be the space of continuous functions on $K$, $C(K,\R)$, equipped with the supremum metric
      \begin{equation}\label{sup-metric}
d(f,g)\doteq\sup_{x\in K} |f(x)-g(x)|.
\end{equation}

First, we note that $\cE_n$ $\Gamma$-converges to $\cE$. This follows from the monotone
pointwise convergence of $\cE_n\nearrow\cE$ (cf.~\eqref{monotone-conv}) and continuity of $\cE_n$
(cf.~\cite[Remark~1.10(ii)]{Braides-beginners}). Importantly, $\cJ_n$ also $\Gamma$-converges to $\cE$ as shown
in the following theorem.

\begin{theorem} \label{thm:SGThm}
  Let $(\cJ_n)$ be the Kuramoto energy functionals (cf.~\eqref{KM-energy}). Then
  \begin{equation}\label{Kuramoto-converge}
    \cE=\Glim{n\to\infty} \cJ_n.
    \end{equation}
  Moreover, suppose $(u^n)$ is a sequence of minimizers of  $(\cJ_n)$ converging to  $u^\ast\in X$, then
  $u^\ast$ is a minimizer of $\mathcal{E}$ and
	\begin{equation}\label{Kuramoto-minimizers}
	\lim_{n\to\infty} \cJ_n(u^n) = 	\cE(u^\ast).
	\end{equation}
\end{theorem}

	\begin{proof}
        By the Taylor's expansion of $\cos$, 
	\begin{align}\nonumber
          \cJ_n(u) &= \left(\frac{5}{3}\right)^n \sum_{(j,i)\in E_n}  \frac{(u(v_j)-u(v_i))^2}{2}
                     \left[1+g(u(v_j)-u(v_i))\right]\\
          \label{Taylor-cos}
          &= \cE_n(u)+ \left(\frac{5}{3}\right)^n \sum_{(j,i)\in E_n} g(u(v_j)-u(v_i))\frac{(u(v_j)-u(v_i))^2}{2},
	\end{align}
	where $g(x)=-\frac{2(2\pi x)^2}{4!}+\frac{2(2\pi x)^4}{6!}-\cdots$. Using the alternating series remainder bound,
        we have
	\begin{equation} \label{g-bound1}
		|g(x)|\leq \frac{\pi^2|x|^2}{3}.
	\end{equation} 

	Suppose $u^n\to u\in\operatorname{dom}(\cE)$. Then
	\begin{align*}
          \liminf_n \cJ_n(u^n) &\geq \liminf_n \cE_n(u^n) +
                                 \liminf_n \left(\frac{5}{3}\right)^n\sum_{(j,i)\in E_n}   g(u^n(v_j)-u^n(v_i))
                                 \frac{(u^n(v_j)-u^n(v_i))^2}{2}\\
                               &\geq \mathcal{E}(u)+
                                 \liminf_n \left(\frac{5}{3}\right)^n \sum_{(j,i)\in E_n} g(u^n(v_j)-u^n(v_i))\frac{(u^n(v_j)-u^n(v_i))^2}{2},
	\end{align*}
	where we used $\Glim{n\to\infty} \cE_n =\cE$.

	Using \eqref{Taylor-cos}, \eqref{g-bound1}, and Lemma \ref{lem.SG_holder}, we continue
	\begin{align}
          &\left|\left(\frac{5}{3}\right)^n\sum_{(j,i)\in E_n} g(u^n(v_j)-u^n(v_i))
          \frac{(u^n(v_j)-u^n(v_i))^2}{2}\right| \label{eq:liminf_ineq}\\
          &\leq \max_{j\sim_n i} |g(u^n(v_j)-u^n(v_i))|\left(\frac{5}{3}\right)^n
           \sum_{(j,i)\in E_n} \frac{(u^n(v_j)-u^n(v_i))^2}{2} \nonumber\\
          &\leq C\max_{j\sim_n i}|u^n(v_j)-u^n(v_i)|^2\left(\frac{5}{3}\right)^n
           \sum_{(j,i)\in E_n} \frac{(u^n(v_j)-u^n(v_i))^2}{2} \nonumber\\
              &\leq C \left[\max_{j\sim_n i} \frac{|u^n(v_j)-u^n(v_i)|^2}{|v_j-v_i|^{2\beta}}\right]
               \max_{j\sim_n i}|v_j-v_i|^{2\beta} \cE_n(u^n) \nonumber\\
         &\leq C (\mathcal{E}(u^n))^2\max_{j\sim_n i}|v_j-v_i|^{2\beta} \nonumber.
	\end{align}

	Since $u^n\to u$, the continuity of $\mathcal{E}$ implies a uniform bound on
        $\cE(u^n)$.
        Finally, by construction of $\Gamma_n$,
        $$
        |v_j-v_i | = 2^{-n}, \quad \mbox{ when } j\sim_n i.
        $$
        %where $C$ depends only on $v_1, v_2,$ and $v_3$.
        Thus, $ \max_{j\sim_n i} |v_j-v_i|^{2\beta}\to 0$ as $n\to \infty$, and 
	$$
        \lim_{n\to \infty} \left(\frac{5}{3}\right)^n \sum_{j\sim_n i} g(u^n(v_j)-u^n(v_i))
        \frac{(u^n(v_j)-u^n(v_i))^2}{2}= 0.
        $$
	We conclude that $\liminf \cJ_n(u^n)\geq \mathcal{E}(u)$. This verifies the lower bound in the
        definition of $\Gamma$-convergence (cf.~C1. Definition~\ref{def.Gamma}).

        To verify the upper bound, we need to show that for an arbitrary $u \in X$ there is a recovery sequence
        $u^n\to u$ such that $\lim_{n\to\infty} \cJ_n(u^n)=\cE(u^\ast)$.
        To this end, let $u^n=u^\ast$ be a constant sequence.
        Arguing as above, we show that
        \begin{equation}\label{constant-seq}
          \lim_n\cJ_n(u)= \mathcal{E}(u).
          \end{equation}
        This completes the proof of $\Gamma$-convergence of $\cJ_n$.

	Finally, the fact that convergent sequences of minimizers converge to a minimizer of the
        $\Gamma$-limit is a standard result (see, e.g.,
        \cite{Braides-beginners}). Below we include a short proof of
        this statement for completeness.

	First, by $\Gamma$-convergence of $(\cJ_n)$, for $u \in X$ there is a recovery sequence
        $u^n\to u$ such that $\limsup_{n} \cJ_n(u^n)\leq \cE(u)$. Thus,
	\begin{equation*}
		\limsup_n \min_{w\in X} \cJ_n(w)\leq \limsup_n \cJ_n(u^n)\leq \cE(u).
	\end{equation*}
	Since $u\in X$ is arbitrary,
	\begin{equation}\label{eq:limsupEst1}
		\limsup_n \min_{w\in X} \cJ_n(w) \leq \inf_{u\in X} \mathcal{E}(u).
	\end{equation}

	Suppose now that $u^n$ is a sequence of minimizers of $\cJ_n$ with $u^{n}\to u$.
        Using $\Gamma$-convergence  of $(\cJ_n)$ again, we have
	\begin{equation*}
          \inf_{X} \mathcal{E} \leq \mathcal{E}(u) \leq \liminf_n\cJ_n(u^n) =
          \liminf_n \min_{X} \cJ_n\leq \limsup_n \min_{X} \cJ_n\leq \inf_{X}\cE,
	\end{equation*}
	where the final inequality follows from \eqref{eq:limsupEst1}. Thus,
	$$
        \min_{X} \cE=\cE(u) = \lim_n \cJ_n(u^n).
        $$
\end{proof}

The key implication of the $\Gamma$-convergence of $(\mathcal{E}_n)$ and $(\mathcal{J}_n)$ to $\mathcal{E}$ is that any limit point of a sequence of minimizers
of $(\mathcal{E}_n)$ or $(\mathcal{J}_n)$ is a minimizer of $\mathcal{E}$, i.e., a harmonic function on
the SG. For $(\mathcal{E}_n)$, one can easily find the minimizers by either solving
a system of linear equations
or by harmonic extension. It is straightforward to show that the
sequence of these minimizers converges.
% Alternatively, the minimizers can be constructed using the harmonic
% extension algorithm (cf.~\cite{Str06}).
% In either case, one obtains a convergent sequence of minimizers of $(\mathcal{E}_n)$.
The situation for the Kuramoto energy functionals $(\mathcal{J}_n)$ is more subtle: the minimization
does not reduce to a linear system, and the harmonic extension method is not applicable. Nevertheless,
using general properties of $\Gamma$-convergence, below we show the existence of a sequence
of minimizers of $(\mathcal{J}_n)$ that converges to a harmonic function on SG.
% A more refined analysis, such as using the Newton-Kantorovich method, would require
% new estimates on the eigenvalues of the Jacobian evaluated on harmonic splines on SG.
% We defer this technical investigation to future work.

\begin{theorem}\label{thm:conv_minSG}
  Let $u^*$ be the harmonic function on the SG subject to the following boundary condition
  $u^*|_{V_0}=\phi\in L(V_0,\R)$.
  Then there exists a sequence of stable equilibria of the KM on $\Gamma_n$, $u^n$, with $u^n|_{V^0}=\phi$ so that
  $\max_{x\in V_n}\|u^n(x)-u^*(x)\|\to 0$ as $n\to\infty$.
\end{theorem}

\begin{proof}
  Let $X$ be the space of H\"{o}lder continuous functions on $K$ with exponent $\beta=\frac{\log(5/3)}{2\log 2}$
  equipped with the norm
  \begin{equation}\label{Holder-norm}
    \|v\|_\beta \doteq \sup_{x\in K}|v(x)| + \sup_{x\neq y} \frac{|v(y)-v(x)|}{|x-y|^\beta}.
  \end{equation}

  Let $\varepsilon>0$ be arbitrary but fixed. Below, we prove that for all  sufficiently
  large $n\in\N$, $\cJ_n$ has a local minimum in
$$
  B_\varepsilon(u^*)=\{f\in X\colon f|_{V_0}=\phi,\; \|f -u^*\|_{\beta}< \varepsilon\}.
  $$

A continuous function on $K$, whose restriction to each $n$-cell of
$K$ is a harmonic function is called a harmonic spline (cf.~\cite{Str06}).
Consider the space of harmonic splines on $K$,
\begin{equation}\label{harm-splines}
		X^n := \{f \in C(K,\R) : f\circ F_w \mbox{ is harmonic for all } |w|=n \}.
              \end{equation}
%This is a space of continuous functions on $K$, whose restriction to every $n$-cell is harmonic
             Then $X^n$ is a finite-dimensional subspace of $X$ and $X_n\cap \overline{B_\varepsilon(u^*)}$ is a compact
              subset of $X$, as a closed and bounded subset of a finite-dimensional subspace.
              For every  $n\in\N$, $J_n$ is a continuous functional on $X$. Thus, it achieves its minimum
              on $X_n\cap \overline{B_\varepsilon(u^*)}$. Denote this minimum by $u^n$. In case of multiple minima,
              whenever possible we choose the one lying in $B_\epsilon(u^*)$.

              It remains to show that $u^n\in B_\epsilon(u^*)$ for all but possibly finite number of $n\in\N$. That is, we show that for all $n$ sufficiently large there is a local minimizer, $u^n$ of $\cJ_n$ satisfying $\|u^n-u^*\|_{C(K)}<\varepsilon$, which will complete the proof.

              Suppose on the contrary that there are infinitely many $n$ such that
              $\|u^n-u^*\|_\beta=\varepsilon$.
%           After restricting to this subsequence, we have
%	\begin{equation*}
%          \min \{\cJ_{n_k}(f)\colon \|f-u\|_{\beta}=\varepsilon\}<\inf\{\cJ_{n_k}(f)\colon\;
%          \|f-u\|_{\beta}< \varepsilon\}\leq \cJ_{n_k}(u).
%	\end{equation*}
Thus, there is an infinite subsequence $u^{n_k}\in C(K,\R)$ such
        that $\|u^{n_k}-u^*\|_\beta=\varepsilon$ and $\cJ_n(u^{n_k})< \cJ_{n_k}(u^*)$.
	The sequence $\{u^{n_k}\}$ is  bounded in $X$ and using the compactness of the embedding
        $X$ in $C(K,\R)$, we can extract a subsequence
        $u^{n_j}$ converging to $\bar{u}$  in the norm of $C(K,\R)$. 


      %  Since $u$ is the point of minimum of $\cE$ on $X$, we have $\mathcal{E}(u)\leq \mathcal{E}(\bar{f})$.
        By construction, the harmonic $u^*\in C(K,\R)$ satisfies the following inequalities
        $
 \cE_n(u^*) \le  \cE_n(\bar u)\; \forall n\in\N.
        $
        Therefore, $\cE (u^*) \le  \cE_n(\bar u)$ (cf.~\eqref{monotone-conv}).
        On the other hand, by Theorem~\ref{thm:SGThm},
	$$
        \mathcal{E}(\bar{u})\leq \liminf \cJ_n(u^{n_j})\leq \liminf \cJ_n(u^*)=\mathcal{E}(u^*),
        $$
        where the first inequality follows from
        \eqref{Kuramoto-converge} and the second from \eqref{Kuramoto-minimizers}.
        We conclude that $\mathcal{E}(\bar{u})=\mathcal{E}(u^*)$ and $\bar{u}=u^*$.
        This contradicts the assumption that
        $\|u^n-u^*\|_\beta=\epsilon$.	
      \end{proof}

\begin{remark}
Both Theorem~\ref{thm:conv_minSG} and Theorem~\ref{thm.main-sg} claim
the existence of families of equilibria in the discrete KM models converging to harmonic
functions on~$K$.
However, the settings of the two theorems differ. In the former case,
we consider real-valued solutions subject to Dirichlet boundary conditions, whereas in
the latter, we deal with $\T$-valued solutions for the model with free boundary
conditions. Nonetheless, the proof of Theorem~\ref{thm:conv_minSG} provides a roadmap
that will be useful in addressing the more challenging setting of Theorem~\ref{thm.main-sg}.
\end{remark}

       \section{The KM on nearest-neighbor graphs}\label{sec.near}
      \setcounter{equation}{0}

      In the previous section, we proved $\Gamma$-convergence of the Kuramoto energy to the Dirichlet
energy as $n \to \infty$.
Until now, we have treated solutions of the KM as real-valued
functions. It is time to recognize the importance of viewing them as maps from their respective
domains to the circle. To extend $\Gamma$-convergence techniques to $\T$-valued maps, we
incorporate several geometric constructions developed in~\cite{MM2024}. To make the
transition to the $\T$-valued setting more intuitive, we first analyze the KM on the unit circle.
The fact that a circle, an interval, and a cube are self-similar sets was used effectively
in~\cite{Str06} to elucidate analysis on fractals.
Similarly, we begin the analysis of the KM on SG by
first considering it on nearest-neighbor graphs.
Besides its pedagogical value, the KM
on nearest-neighbor graphs is of independent interest, as it features prominently in many applications
(see, e.g.,~\cite{WilStr06, BMS2025, MedZhu12}).

      In this section, consider the KM on the nearest-neighbor graph
      \begin{equation}\label{KM-nn}
        \dot u^n(t,v_i)=2^n\sum_{j\sim_n i} \sin\left( 2\pi(u^n(t,v_j)-u^n(t,v_i))\right),\quad i\in\left\{0, 1, \dots, 2^n-1 \right\},
      \end{equation}
      where
      \begin{equation}\label{nn-adj}
        j\sim_n i \Leftrightarrow j=i\pm 1 \mod 2^n\end{equation}

        Since we are interested in the continuum limit of \eqref{KM-nn} as $n\to\infty$, it is convenient
        to interpret $u^n(t,v_i)$ as the values of $u^n(t,x)$ at $x=i2^{-n}$ where $i$ runs from $0$ to $2^n-1$.
        Specifically,
        we represent the spatial domain of $u^n(t,x)$ as a discretization of the unit interval with the two end points
        identified
        $I=[0,1]\setminus \{0\simeq 1\}$ by the set of points
        \begin{equation}\label{vertex-nn}
        V_n=\{0, 2^{-n}, 2\cdot 2^{-n},\dots, (2^{n}-1)2^{-n}\}=:\{v_0,v_1,\dots\}.
        \end{equation}
        Accordingly, we view \eqref{KM-nn} as a dynamical system on the nearest neighbor graph $\Gamma^n$
        with the vertex set $V_n$ \eqref{vertex-nn} and the adjacency relation \eqref{nn-adj}.

        We will argue that the natural candidate for the continuum limit of \eqref{KM-nn} is the heat equation on 
        \begin{equation}\label{heat-c}
          \partial_t u=\Delta u, 
          \end{equation}
       on $(0,1)$ with periodic boundary condition
          $
          u(0)=u(1).
          $
          Here, we view $u(t,\cdot)$ as a map from $\T$ to $\T$. Thus, the steady states of \eqref{heat-c}
          are harmonic maps from $\T$ to $\T$:
          \begin{equation}\label{1d-hm}
            \Delta u =0, \quad u(0)=u(1)=0.
          \end{equation}
          Here, we set $u(0)=0$ to eliminate translation invariance.

          If $u$ were real-valued then $u\equiv 0$ would be a unique solution of \eqref{1d-hm}. In the class
          of $\T$-valued functions, \eqref{1d-hm} has infinitely many solutions:
          \begin{equation}\label{twist}
            u(x)= qx\mod 1,\quad q\in\Z,
          \end{equation}
          i.e.,   one solution per homotopy class, determined by the degree  $q$. Such solutions are called
          $q$-twisted states after \cite{WilStr06}.

          Going back to the KM, it is easy to find discrete counterparts of \eqref{twist}:
          \begin{equation}\label{disc-twist}
            u(v_i)=qi2^{-n}\mod 1, \quad i\in [2^n].
          \end{equation}
          In the case of the KM on the circle, \eqref{disc-twist} clearly converges to \eqref{twist} as $n \to \infty$.
However, for other self-similar sets, e.g., for SG, the relation between the solutions of the KM and those
of its continuum limit is not as transparent. In preparation for the analysis of the KM on SG and other
fractals, we extend below the $\Gamma$-convergence techniques from the previous section.

\subsection{Harmonic maps on $\T$}\label{sec:mapsonT}
          Before we begin, we recall a few basic facts about continuous maps from $\T$ to $\T$ (see also Section \ref{sec.intro}).
          For a given $f\in C(\T,\T)$, there is a unique $\hat f\in C(\R,\R)$ such that
          $$
          \pi\circ \hat f(x)= f\circ \pi (x)\quad \forall x\in\R,
          $$
          where $\pi(x)\doteq x\mod 1$. $\hat f$ is called the \textit{lift}  of $f$.

          The integer $\hat f(1)-\hat f(0)$ is called the \textit{degree of} $f$. The degree counts the number of
          rotations around the circle made by  the trajectory $(f(t), \;0\le t\le 1)$.
          By the Hopf degree theorem, the degree determines the homotopy class
          of continuous maps from $\T$ to $\T$.

          We now explain our strategy for extending the $\Gamma$-convergence techniques for the model at hand.
          \begin{description}
          \item[I.] Let $q\in\Z$ be fixed. For a homotopy class defined by $q$, we  construct the
            covering of the circle. Define
            \begin{align*}
              \T_\times & \doteq \T\times \Z,\\
              \T^k&\doteq \T\times \{k\}\subset \T_\times, \; k\in \Z\qquad\mbox{(sheets)}
            \end{align*}
            Cut $\T^k$ at $0\times \{k\}$ producing two copies $0^k$ and $1^k$. Identify $1^k\simeq 0^{k+q}$. Then $\tilde{\T}\doteq \T_\times/\simeq$ is the covering space, and $\T^0$ is called the \textit{fundamental domain}, see Figure \ref{fig:cs_circle}. Discretize $\T^0$ by $V_n^0 = \{0,2^{-n},\dots, (2^n-1)2^{-n},1\}$, where we omit superscripts on vertex points for notational ease. 
             \begin{figure}[h]
             	\centering
             	\includegraphics[width = .8\textwidth]{figs/covering_space_circle1.pdf}
             	\caption{Construction of the covering space $\tilde{\T}$ for $q=1$. The fundamental domain $\T^0$ is highlighted in red.}
             	\label{fig:cs_circle}
             \end{figure}
             \item[II.] On the fundamental domain, reformulate the boundary value problem for the discrete Laplacian
               for the lift of $u$:
               \begin{equation}\label{bvp-fundamental}
\Delta_n \hat u^{n}=0, \quad \hat u^{n}(0)=0, \; \hat u^{n}(1)=q.
              \end{equation}    
               In one-dimension, this problem can be solved immediately:
              \begin{equation}\label{discrete-twist}
\hat u^{n}(v_i)=qi 2^{-n},\quad i\in \{0,1,\dots, 2^n\}.
              \end{equation}
           %    It can also be solved inductively in $n$ by harmonic extension, which in the case of the interval is straightforward
           %    (see \cite{Str06}). For SG and other p.c.f. fractals, harmonic extension is going to be  the only way 
           %    available to us. 
%Extend to other sheets of the covering space:
%$$
%\hat u^{k,n}=u^{0,n}+k, \quad k\in\Z.
%$$
%This yields the (real-valued) steady-state solution of the discrete Laplace equation on the covering space.
             \item[III.] We have computed the value of solutions on a dense subset of the
               fundamental domain $V^\ast=\bigcup_{k\in \Z} V^0_n$. Noting that the discrete twisted states are
               \eqref{discrete-twist} are Lipschitz continuous on $V^\ast$, we extend by them by continuity
               to the rest of the fundamental domain, to obtain the harmonic
               function on the fundamental domain, denoted
               $
\hat u^{\ast}.
$
Extend these solutions to other sheets of the covering space:
$$
{\bf \hat u^{\ast}}(x,k)=\hat u^{\ast}(x)+k, \quad k\in\Z.
$$
Then ${\bf \hat u^{\ast}}$ is a harmonic function on the covering space.
\item[IV.] Finally, project the range of the harmonic function ${\bf \hat u^{\ast}}$ back to $\T$-values:
\begin{equation*}
	u^* := {\bf \hat u^{\ast}}|_{\T^0}\mod 1.
\end{equation*}
Then $u^*$ is the desired harmonic map on $\T$. %That is, it is a minimizer of the discrete energies
%\begin{equation*}
%	\cE_n(u) = 2^n\sum_{j\sim_n i} \frac{d_\T(u_j,u_i)^2}{2},
%\end{equation*}
%for all sufficiently large $n,$ where $d_\T$ is the geodesic distance on $\T$ (see \cite{MM2024}). Of course, it is clear that $u^*$ is none other than the $q$-twisted state \eqref{twist}.
\end{description}


\subsection{$\Gamma$-convergence on the covering space}

In Section~\ref{sec.gamma}, we demonstrated convergence of the energy functional in the KM
to the Dirichlet energy, from which we derived convergence of stable equilibria of the KM to
harmonic functions. To derive these statements to the KM on the nearest-neighbor graph, we first need
to translate the analysis to the real-valued setting. To this end, we use the procedure described in the previous subsection.
Specifically, we first lift the $\T$-valued solutions on $\T$ and their discretizations to $\R$-valued functions
on the covering spaces. Then we replicate the arguments from
Section~\ref{sec.gamma} to obtain desired convergence of the energy functionals and the equilibria on the fundamental domain, $\T^0$. 
%Finally, we will translate the results back to the original setting by restricting ranges back to $\T$.
%After that we will project back to the fundamental domain, i.e., to $\T^0$ to translate these result to the
%original setting of the KM.
