% \end{equation*}
% see, e.g., \cite{Str06}.
By Morrey's inequality  \cite{brezis2011functional}, we have 
\begin{equation*}
	\|{u}\|_{1/2}\leq C\|{u}\|_{H^1([0,1])},
      \end{equation*}
      where $\|\cdot\|_{1/2}$ is the $1/2$-H\"older norm, and $C$ is independent of $u$.
%Hence,
%\begin{equation}
