\subsection{Harmonic structure on $\tilde K$}\label{sec.harm-struct}
\setcounter{equation}{0}

In this subsection, we construct a harmonic map from $K$ to $\T$ without imposing
any boundary conditions. To this end, we first construct a real-valued harmonic function on the fundamental domain $K^0$, which will extend to the covering space $\tilde K$.  


The energy form  on $\Gamma^0_m$ is defined as follows
  \begin{equation}\label{EGamma}
      \cE_m[\Gamma^0_m]( f) = \left(\frac{5}{3}\right)^m\sum_{(x,y)\in E_m^0} \frac{\left( f(x)- f(y)\right)^2}{2},
      \qquad  f\in L(V_m^0,\R), m\in\N.
    \end{equation}

%    We consider the following minimization problem:
%    \begin{equation}\label{minimize-fundamental}
%\cE_m[\Gamma^0_m](f) \longrightarrow\; \min
%      \end{equation}
We consider minimizing $\cE_m[\Gamma^0_m]( f)$
      subject to the jump condition
      \begin{equation}\label{jump}
  f(z^0_+) =  f(z^0_-)+\rho_0,
\end{equation}
As before, to remove translation invariance we fix $f(v^0_1)=0$. Since we will work exclusively on the fundamental domain $K^0$, in the following we suppress some superscripts for simplicity.

The minimization problem can be reformulated as 
\begin{equation}\label{variational}
\cE_m[\Gamma^0_m](f) \longrightarrow\; \min_{f\in H^0_m},
\end{equation} 
where 
\begin{equation}\label{def-H}
  H^0_m\doteq \{ f\in L(V_m^0, \R):\quad f(v_1)=0,\;
  f(z_+) = f(z_-)+\rho_0\}.
\end{equation}


The energy form $\cE_m[\Gamma^0_m]$ inherits the key properties of the 
Dirichlet form $\cE_m$ (see \eqref{variational-harmonic}, \eqref{variational-extension}):
	\begin{enumerate}
		\item A $\Gamma_m^0$-harmonic\footnote{
 In the present context, a function $f$ is said to be  $\Gamma_m^0$-harmonic if it satisfies the discrete Laplace equation:
\begin{equation}
	\sum_{(x,y)\in E_m^0} (f(y)-f(x)) = 0,\qquad \forall x\in V_m^0\setminus \{v_1,z_+,z_-\}.
\end{equation} 
        } 
        $f_m^0\in H_m^0$ minimizes $\cE_m[\Gamma^0_m]$ over $H_m^0$:
		\begin{equation}\label{E-harmonic}
			\cE_m[\Gamma^0_m](f^0_m)=
			\min\left\{ \cE_m[\Gamma^0_m](f):\; f\in H_m^0 \right\}.
		\end{equation}
		\item The minimum of the energy form $\cE_m[\Gamma^0_m]$ over all extensions of 
		$f\in H_{m-1}^0$ to $H_m^0$ is equal to $\cE_m[\Gamma^0_{m-1}](f)$:
		\begin{equation}\label{E-extension}
			\min\left\{ \cE_m[\Gamma^0_m](\tilde f):\; \tilde f\in H_m^0,\; 
			\tilde f|_{V_{m-1}}=f\in H_{m-1}^0 \right\} = \cE_m[\Gamma^0_{m-1}](f).
		\end{equation} 
	Moreover, this minimizer is obtained by taking the harmonic extension of $f$.
	\end{enumerate}

 As in \eqref{monotone-conv}, since energies are monotone increasing, the limit
 \begin{equation}\label{eq:limit_k0_energy}
 	\cE_{K^0}(f) = \lim_{m\to\infty} \cE_m[\Gamma_m^0](f)	
\end{equation}
is well defined for $f\in C(K^0,\R)$.

Applying the arguments in \cite[Lemma~5.1]{MM2024}, we also conclude that the variational problem \eqref{variational} has a unique solution
$f^0_m \in H^0_m$:
$$
\cE_m[\Gamma_m^0](f^0_m)=\min_{f\in H_m^0} \cE_m[\Gamma_m^0](f),
$$
and the minimizers $f^0_m$ satisfy the following properties:
\begin{enumerate}
	\item $f_m^0$ \; is $\Gamma^0_m$-harmonic,
	\item $f^0_{m+1}|_{V^0_m} = f_m^0$. 
\end{enumerate}

\begin{remark}
	This second property requires comment. In principle, it is not obvious that minimizers must agree on common vertices (particularly as boundary conditions at $v_2$ and $v_3$ are not fixed, in contrast to \cite{MM2024}). However, given $f_m^0$,  from \eqref{E-extension}, its harmonic extension $\tilde{f}_m^0 \in H_{m+1}^0$ satisfies $\cE_{m+1}[\Gamma_{m+1}^0](f^0_{m+1}) = \cE_{m+1}[\Gamma_{m+1}^0](\tilde{f})$. Since minimizers are unique, it must follow that $\tilde{f} = f^0_{m+1}$ and so $f^0_{m+1}|_{V^0_m}= f_m^0$.
\end{remark}




