We extend it by continuity to the fundamental domain $K^0$,
and further to a uniformly
continuous function on the covering space:
\begin{equation}\label{k-period}
  \mathbf{\hat f}^\ast (x,s) = \hat f^\ast(x) +s , \qquad x\in K^0, \; s\in \Z.
\end{equation}


Recall that $\tilde\Gamma_m$ and $\tilde V_m$ stand for the family of graphs approximating
the covering space $\tilde K$ and their vertex sets respectively (see item $5$ in \S\ref{sec.cover}).
By \cite[Theorem~5.2]{MM2024}, the restriction of $  \mathbf{\hat f}^\ast$ on $\tilde V_m$, $ \mathbf{\hat f}^\ast|_{\tilde V_m}$,
is  $\tilde\Gamma_m$-harmonic for every $m\in \N$,
 i.e., it satisfies the discrete Laplace equation
 \begin{equation}\label{G-harmonic}
  \Delta_m   \mathbf{\hat f}^\ast|_{\tilde V_m}(x) = 0\quad \forall x\in \tilde{V}_m\setminus \{v^s_1\}.   
  \end{equation}

Finally, by restricting the domain of $  \mathbf{\hat f}^\ast$ to the fundamental domain 
and by projecting the range of $  \mathbf{\hat f}^\ast$ to $\T$, we obtain the harmonic map from
the SG to the circle $f^\ast:\, K\to \T$:
\begin{equation}\label{project-back}
     f^\ast\doteq   \mathbf{\hat f}^\ast|_{K^0}\mod 1.
  \end{equation}


H\"older continuity of functions on $K^0$ also holds with minor adjustments. 
  The fundamental domain $K^0$ is the union of the three subdomains
  $K^0_i, \; i=1,2,3$ (see Fig.~\ref{fig:sg_graph_cut}), each a copy of $K$ itself. Specifically,  $K^0_1, K^0_2,$ and $K^0_3$
  correspond to the intersection of $K^0$ with the closed triangles $v_1xz_-,$ $xv_2y$,
  and $z_+yv_3$, respectively.  Let $ f\in \operatorname{dom}(\cE_{K^0})$.
  By Lemma \ref{lem.SG_holder}, we immediately see that the restriction of
  $ f$ on each of the subdomains $K^0_i, i\in [3]$ is
  a H\"older continuous function. This yields the following lemma.
\begin{lemma}\label{lem.Holder-G^0}
	Let $ f\in \operatorname{dom}(\cE_{K^0})$ then for every $K_i^{0}, i\in [3]$ and $x,y\in K^0_3$,
	\begin{equation*}
          \frac{| f(x)- f(y)|}{|x-y|^\beta}\leq C\sqrt{\cE_{K^0}( f)},\quad
          \beta = \frac{\log(5/3)}{2\log(2)},
	\end{equation*}
	where $C>0$ is independent of $ f$. 
\end{lemma}

We conclude this subsection by showing that minimization of the Dirichlet energy on the fundamental
domain without imposing any boundary conditions on $V_0$ results in a solution satisfying
zero Neumann boundary conditions.

 \begin{lemma}\label{lem.natural}
$f^\ast$ satisfies natural boundary conditions \eqref{HM-neu}.
\end{lemma}
\begin{proof}
	We recall that for a harmonic function $\hat f^* \in C(K^0,\R)$, the normal derivative at a boundary vertex $v_j \in V_0$ is 
	\begin{equation*}
		\partial_{\bf n} \hat f^*(v_j) = \left(\frac{5}{3}\right)^m\sum_{y\sim_m j} \hat f^*(y)-\hat f^*(v_j),
	\end{equation*}
	which is well-defined because the right hand side is constant in $m$ for harmonic functions \cite{Str06}. In the following, we work always on the fundamental domain and suppress superscripts/subscripts for simplicity.

	For every $m\in \N$, the Euler-Lagrange equations for \eqref{EGamma} at the boundary points $v_2$ and $v_3$ is 
	\begin{equation}\label{eq:EL_lift}
		\sum_{j\sim_m i} (\hat f^*(v_j)-\hat f^*(v_i))=0, \quad i=2,3,
	\end{equation}
	from which it follows $\partial_{\bf n} \hat f^*(v_2)=\partial_{\bf n}\hat f^*(v_3) = 0$. To see that $\partial_{\bf n} \hat f^*(v_1)=0$ as well, we use a discrete divergence theorem. For $x\in \Gamma^0_n\setminus V^0_0$, define 
	\begin{equation*} 
		\Delta_n \hat {f}^*(x) = \left\{ \begin{array}{cc} 
			\sum_{y\sim_n x} (\hat f^*(y)-\hat f^*(x)) &\mbox{ if } x \mbox{ is not a jump vertex}\\
			\sum_{y\sim_n x_+} (\hat f^*(y)-\hat f^*(x_+))+\sum_{y\sim_n x_-} (\hat f^*(y)-\hat f^*(x_-)) &\mbox{ if } x \mbox{ is a jump vertex}.
		\end{array}\right.
	\end{equation*} 
	In this way,  $\Delta_n \hat f^*(x)=0$ for all $x\not\in V_0$ (cf. \eqref{G-harmonic}). Then, summing over all junction points results in the discrete divergence theorem: 
	\begin{equation*} \sum_{x\in V_n\setminus V_0} \Delta_n \hat f^*(x)=\sum_{v_i\in V_0}\sum_{y\sim_n v_i} \hat f^*(y)-\hat f^*(v_i).
	\end{equation*} 
	Together with \eqref{eq:EL_lift} this shows $\partial_{\bf n}\hat  f^*(v_1)=0$. Projecting  $f^*=\hat f^*|_\T$ preserves normal derivatives, so the result follows.
      \end{proof}

  \subsection{Higher order harmonic maps}\label{sec.higher}

  In the previous section, we explained how to construct a harmonic map when the
  winding vector has a single nontrivial entry, $\bar{\omega}(f) = (\rho_0)$. The procedure
  for a general winding vector, $\bar{\omega}(f) = (\rho_0, \rho_1, \dots, \rho_k)$, follows the
  same general approach but requires multiple cuts to construct the covering space.
  The idea is to introduce one cut point for each nonzero entry in the winding vector.
  Care must be taken in choosing these points, as the loops used for cutting must be
  linearly independent. The choices of cut points when $\bar{\omega}(f) = (\rho_0, \rho_1, \rho_2, \rho_3)$
  and $\bar{\omega}(f) = (\rho_0, \rho_1, \rho_2, \dots, \rho_{12})$ are shown
  in Figure~\ref{fig:gen_cuts}. The general procedure of selecting cut points for a p.c.f. fractal is
  explained in detail in Sections 7 and 8 of \cite{MM2024}. For completeness, 
  we discuss the construction of the covering space for SG for an arbitrary winding vector below
  and refer the reader to \cite{MM2024} for further details.



 % A similar construction exists for general $\bar{\omega}(f) = (\rho_0,\rho_1,\dots)$ with finitely many
 % non-zero entries. We highlight the main ideas, and refer to \cite{MM2024} for further details. Fix
 % $\bar{\omega}(f)$ and again start from $G_\times \doteq G\times \Z$. Cut and re-identify the sheets
 % $G^k$ at finitely many vertices, namely one for each non-zero entry in $\bar{\omega}(f)$.
 % For ease of future notation, relabel the entries of $\bar{\omega}(f)$ as follows: if $\rho_i$
 % is the winding number of $f$ around $\partial T_w$, $w\in S^n$, then relabel $\rho_i \to \rho_w$.

  Let $f\in C(K,\T)$ be a harmonic map of order $N\in \N$, i.e., $\bar{\omega}(f) = (\rho_0,\rho_1,\dots, \rho_k)$
    with
    $$
    \frac{3^N-1}{2} \le k\le \frac{3^{N+1}-3}{2}.
    $$
    Note that to each nonzero entry of $\bar{\omega}(f)$, $\rho_i, i\le \frac{3^{N+1}-3}{2}$,
    corresponds a unique loop $\partial T_w, w\in S^N$. For the remainder of this subsection,
    let us denote $\rho_i$ by $\rho_w$, i.e., by the itinerary of the cell, whose boundary has
    winding number $\rho_i$.

    For each nonzero $\rho_w$ with $n:=|w|\le N$, we cut $K^s$ at a vertex  $z_w$
    satisfying $z_w \in \partial T_w \setminus (\bigcup_{|v|=n-1} \partial T_v),$
    see Fig. \ref{fig:gen_cuts}.
    Denote the two copies of $z_w$ by $(z_w)_-$ and $(z_w)_+$.
    Finally, identify vertices in the sheets $K^s$ by
  \begin{equation*}
  	(z_w^k)_+ \simeq (z_w^{k+\rho_w})_-.
  \end{equation*}
  The covering space is then $\tilde{K} \doteq K_{\times}/ \simeq$,
  and the fundamental domain $K^0$. Construction of the approximating graphs
  of the covering space, $\Gamma^s_m=(V^s_m,E^s_n)$, follows analogously.


