  	\centering
  	\includegraphics[width = .3\textwidth]{figs/general_cuts2.pdf}
  	\caption{For arbitrary degree $\bar{\omega}(f)$, each non-zero entry requires an associated cut vertex. As before, for $\partial T$ we cut at the single orange vertex. For loops $\partial T_1,\partial T_2,\partial T_3$ we cut the three blue vertices. Finally, for loops $\partial T_{ij}$ there are 9 corresponding green vertices.}
  	\label{fig:gen_cuts}
  \end{figure}  


  Constructing the harmonic structure on $\tilde{K}$ also follows similarly. Introduce the
  corresponding spaces on the fundamental domain $K^0$:
  \begin{align*}
  	H^0_m = \{  f \in L(V^0_m,\R)\colon  & f(v^0_1)=0,\\
  	&\;  f((z^0_w)_+)= f((z^0_w)_-)+\rho_w, \forall w\in S^n, |n|\leq m\}
  \end{align*}
  and energies $\cE_m[\Gamma_m^0]$ as in \eqref{EGamma}.
  The resultant harmonic structure satisfies the same results as in
  Section~\ref{sec.harm-struct}, so we construct a harmonic function ${\bf \hat f}^*$ on
  the covering space by minimizing the $\cE_m[\Gamma_m^0]$ on the fundamental domain within the class
  $H_m^0$, followed by inductive application of the harmonic extension algorithm.
  The projection of the range of ${\bf \hat f}^*$ to $\T$ yields the desired HM,
  $f^*$, with degree $\bar{\omega}$.


 Arguing as in \S~\ref{sec.harm-struct}, we represent the fundamental domain as a union of
closed $m$-cells $G^0=\bigcup_{|w|=m} K^0_w$. Recall $K^0_w=F_w(K^0)$.  As before,
the restriction of $ f\in\operatorname{dom}(\cE_{K^0})$ on each of these subdomains
is a H\"older continuous function.
  \begin{lemma}\label{lem:holder_sg_lift}
  	Let $ f\in \operatorname{dom}(\cE_{K^0})$ and  $K^0_w,$ $|w|=m$. For any 
$x,y\in K^0_w$ we have
  	\begin{equation*}
  		\frac{| f(x)- f(y)|}{|x-y|^\beta}\leq C\sqrt{\cE_{K^0}( f)}, \quad \beta = \frac{\log(5/3)}{2\log(2)},
  	\end{equation*}
  	where $C$ is independent of $ f$. 
  \end{lemma}



  \section{The proof of Theorem~\ref{thm.main-sg}}\label{sec.proof}
  \setcounter{equation}{0}

  We are now prepared to prove Theorem~\ref{thm.main-sg}. We work with the
  lifts of solutions of the KM restricted to the fundamental domain. The proof for the most
  part coincides with the proofs of Theorems~\ref{thm:SGThm} and \ref{thm:conv_minSG}.
  %The only minor adjustments are required to adapt to different boundary conditions: in Section~\ref{sec.gamma} we analyzed the model with Dirichlet boundary conditions,
  %whereas now we work with jump conditions in $H^0_n$.
  Only minor adjustments are required to deal with the fact that the covering space is a union of finitely many copies of $K$. 
   Below, we comment on the necessary
  adjustments to the arguments in Section~\ref{sec.gamma}.

  Let
  $$
  \omega^\ast=\left(\rho_0, \rho_1, \dots,\rho_{M(m)}\right)\in\Z^{M(m)+1}, M(m)\doteq \frac{3(3^m-1)}{2},
  $$
  be arbitrary but fixed. We assume that
  $$
\sum_{i=M(m-1)+1}^{M(m)} |\rho_i|>0.
  $$
  The last condition means that at least some cells of order $m$ are used in the construction of the
  covering space corresponding to $\omega^\ast$. 
  % which determines the homotopy class for the
  %solution of the boundary value problem \eqref{HM-Lap}-\eqref{HM-deg}.

  Next, construct the covering space using the algorithm explained in
  \S\S\ref{sec.harm-struct}, \ref{sec.higher}. Decompose the fundamental domain $K^0$ into the union of
  $m$-cells, $K^0=\bigcup_{|w|=m} K^0_w$. Let $\hat u_m$ stand for the unique minimizer of the
  Dirichlet energy
  $
\cE_m[\Gamma_m^0]
  $
  over $H^0_m$ and denote by $\hat u^*$ the harmonic extension of $\hat u_m$ to $K^0$. Finally, $u^\ast$ is obtained
  by projecting the co-domain of $\hat u^*$ to $\T$. By construction (and using Lemma \ref{lem.natural}), $u^\ast$ satisfies \eqref{HM-Lap} - \eqref{HM-deg}.

 \noindent{\bf $\Gamma$-convergence.} We first establish $\Gamma$-convergence of the Kuramoto energies on $K^0$.
	Take as $X$ the space of continuous functions $C(K^0,\R)$ with the supremum metric. As before, $\Glim{n} \cE_n = \cE_{K^0}$ by virtue of continuity of the $\cE_n$ and monotone pointwise convergence of the energies. Next define the Kuramoto energy on $\Gamma_n^0$:
	\begin{equation}\label{eq:k0_km_energy}
		\cJ_n(u) = \left(\frac{5}{3}\right)^n\frac{1}{4\pi^2} \sum_{(i,j)\in E_n^0} (1-\cos(2\pi(u(v_j)-u(v_i)))).
	\end{equation} 
Repeating the proof of Theorem \ref{thm:SGThm} establishes $\Glim{n} \cJ_n = \cE_{K^0}$. We remark only that when establishing estimates \eqref{eq:liminf_ineq}, each pair of adjacent vertices live in a common $m$-cell so that H\"older estimates of Lemma \ref{lem:holder_sg_lift} apply.


\noindent{\bf Existence of sequence of stable equilibria.}  It remains to show that there is a sequence of stable steady states of the KM,     $u^{n}\in L(V_n^0,\T),$ converging to $u^\ast$. 

We proceed as in Theorem \ref{thm:conv_minSG} to construct minimizers of $\cJ_n$ converging to $u^*$. Importantly, since we now seek minimizers in the space $H_m^0$ (which does not assume Dirichlet boundary conditions), then minimizers of $\cJ_n$ correspond to stable equilibria of \eqref{KM-intro} (cf. \eqref{min-intro}). Since the proofs are essentially the same, we only outline the main steps.

 Recall that
$K^0 = \bigcup_{|w|=m} K^{0}_w$. Introduce the space of H\"older continuous functions on each
$K^{0}_w$ with norm
	\begin{equation*}
          \|f\|_{C^\beta(K^{0}_w)} =  \sup_{x\in K^{0}_w} |f(x)|+  \sup_{x\neq y} \frac{|f(y)-f(x)|}{|x-y|^\beta}.
	\end{equation*}
	Let $X$ be the space of functions on $K^0$ that are H\"older continuous on each $K^0_w$ with exponent $\beta = \frac{\log(5/3)}{2\log 2}$. 
	Fix $\varepsilon>0$ and consider the minimization of $\cJ_n$ on the closed set
	\begin{equation*}
		\overline{B_\varepsilon(u^*)}:=\{f\in X\colon \max_w \|f-u^*\|_{C^\beta(K^0_w)}\leq \varepsilon\}.
	\end{equation*}
	Restricting the minimization problem to the space of harmonic splines, $X^n$, (cf. \eqref{harm-splines}) is a finite dimensional problem, and so repeating the compactness argument of $\cJ_n$ guarantees a minimum on $X^n\cap \overline{B_\varepsilon(u^*)}$. 


	We need only show that minimizers are attained on the interior of the ball $B_\varepsilon(u^*)$ for all $n$ sufficiently large (so as to be true local minima). Suppose not. Then, there is a sequence $f^n\in X$
        with $\max_w \|f^n-u^*\|_{C^\beta(K^0_w)}= \varepsilon$.   Restricting to $K^0_1$, Lemma \ref{lem:holder_sg_lift} implies that there is a subsequence $f^{n_k}\to \bar{f}\in C(K^0_1)$. If necessary, pass to a further subsequence so that
        $f^{n_{k_\ell}}\to \bar{f}\in C(K^0_1\cup K^0_2)$. As there are finitely many subdomains $K^0_w$, repeating
        this results in a subsequence (which we denote $f^{n_j}$ for simplicity) that converges on the entire domain:
        $f^{n_j}\to \bar{f} \in C(K^0)$.

      As before, by the $\Gamma$-convergence of $\cJ_n$ to $\cE_{K^0}$, we obtain the contradiction
      $\bar{f}=u^*$. Thus, for all $n$ sufficiently large, there is a (local) minimizer, $u^n$, of $\cJ_n$ in the interior of $B_\varepsilon(u^*)$. By construction $u^n$ has degree $\omega^\ast$. Thus both \eqref{steady-state-approx} and \eqref{harm-spline-estimate} follow.

%       establishing \eqref{steady-state-approx}.       
%      Finally, as harmonic functions satisfy the maximum principle \cite{Str06}, the harmonic spline extending $u^{n}$ to a piecewise harmonic function on $K^0$ is the desired continuous  function $\tilde u^{n}$ with degree $\omega^\ast$, completing.






  \section{The KM on post-critically finite fractals}\label{sec.pcf}
  \setcounter{equation}{0}
The analysis of functions on SG naturally extends to a broader class of self-similar domains
known as p.c.f. fractals. Examples include higher-order Sierpinski Gaskets, the pentagasket, and the hexagasket (see Fig.~\ref{fig:pcf_figs}), to name a few.  
In this final section, we describe how the preceding results can be
extended to the KM on p.c.f. fractals. While there are some technical differences in the construction of covering spaces (highlighted below), the techniques developed above remain applicable.
