  \subsection{Background on p.c.f. fractals}

  We first review some relevant background of p.c.f. fractals and refer the reader to \cite{Kig01} for further details. Let $K\subset \R^d$ be a non-empty, connected, and compact set satisfying
  \begin{equation}
  	K=\bigcup_{i=1}^N F_i(K),
  \end{equation}
  where the $F_i:\R^d\to \R^d$, $1\leq i\leq N$, are contraction maps with corresponding contraction ratios $0<\lambda_i<1$. For simplicity, assume the $F_i$ are homotheties so that $|F_i(x)-F_i(y)|=\lambda_i|x-y|$.
  Denoting the $n$-cells
  \begin{equation*}
  	K_w = F_w(K),\quad w=(w_1,w_2,\dots,w_n)\in [N]^n,
  \end{equation*}
  the critical set is defined by
  \begin{equation*}
  	\mathcal{C} = \bigcup_{i\neq j} (K_i\cap K_j).
  \end{equation*}
  If $\mathcal{C}\neq \emptyset$, then the post-critical set is
  \begin{equation*}
  	V_0 = \bigcup_{m\geq 1}\bigcup_{|w|=m} F_w^{-1}(\mathcal{C}).
  \end{equation*}
  If $V_0$ is finite, then $K$ is called a p.c.f. fractal. Moreover, the post-critical set $V_0$ is taken to be the boundary of $K$ (e.g., for the associated Dirichlet problem).


  We assume there is a harmonic structure defined on $K$, which we describe below. Define the vertex sets
  \begin{equation*}
  	V_n = \bigcup_{i=1}^N F_i(V_{n-1}),\quad n\geq 1,
  \end{equation*}
  with $V_*=\bigcup_{n\geq 1} V_n$. Following \eqref{order-nodes}, denote the vertices $V_n = \{v_1,v_2,v_3,\dots\}$. Define the Dirichlet energies
  \begin{equation}
  	\label{eq:quadratic_energy_pcf}
  	\mathcal{E}_n(u) = \sum_{i,j=1}^{|V_n|}c_{ij}^n \frac{(u(v_j)-u(v_i))^2}{2},\quad u\in L(V_n,\R),
  \end{equation}
  where $c_{ij}^n\geq 0$. As before, it is possible to extend the domain of $\mathcal{E}_n$ to all $u\in C(K,\R)$.
  %In doing so, we can assume that the $\mathcal{E}_n$ all share a common domain, $C(K,\R)$. 
  We assume that the $\mathcal{E}_n$ satisfy the following two conditions. 
  \begin{enumerate}
  	\item There are $0<r_i<1$ so that
  	\begin{equation}
  		\label{eq:compatability0}
  		\mathcal{E}_n(u)=\sum_{i=1}^N r_i^{-1} \mathcal{E}_{n-1}(u\circ F_i),\quad u\in L(V_n,\R).
  	\end{equation}
  	\item For every $n\geq 1$,
  	\begin{equation}
  		\label{eq:compatability}
  		\mathcal{E}_{n-1}(u) = \min\{\mathcal{E}_n(\bar{u})\colon \bar{u}\in L(V_n,\R), \bar{u}|_{V_{n-1}}=u\}.
  	\end{equation}
  \end{enumerate}

  In particular, \eqref{eq:compatability} implies that $\mathcal{E}_n(u)$ is non-decreasing for any $u\in C(K,\R)$ so the limit
  \begin{equation*}
  	\mathcal{E}(u)=\lim_{n\to\infty} \mathcal{E}_n(u)
  \end{equation*}
  is well-defined. Moreover, it is possible to define a harmonic extension algorithm analogous to \eqref{classical-extension} \cite{Str06}. As before write
  \begin{equation*}
  	\operatorname{dom}(\mathcal{E})=\{u\in C(K,\R)\colon \mathcal{E}(u)<\infty\}.
  \end{equation*} 
%  Condition \eqref{eq:compatability0} ensures that the limiting energy $\mathcal{E}$ is self-similar on $K$, e.g.,
%  \begin{equation*}
 % 	\mathcal{E}(u) = \sum_{i=1}^N r_i^{-1} \mathcal{E}(u\circ F_i).
%  \end{equation*}
  The energies \eqref{eq:quadratic_energy_pcf} also naturally induce graph structures $\Gamma_n = (V_n,E_n)$. Namely, for all $v_j,v_i\in V_n$,
  \begin{equation*}
  	i\sim_n j \mbox{ iff } c_{ij}^n>0.
  \end{equation*}



To define the degree of a $\T$-valued map on a p.c.f. fractal $K$, we must describe the cycle space, $Cyc(\Gamma_m)$ of the approximating graph $\Gamma_m$ of $K$. For $SG$, the boundaries of the $n$-cells $\partial F_w(K)$ sufficed. In general, however, there is no canonical way to form a basis for this cycle space, so one must choose it. Let
  \begin{equation}
  	\mathcal{B}_m=\left\{\gamma_1^{(m)},\dots,\gamma_{n_m}^{(m)}\right\}
  \end{equation}
  be a basis for $Cyc(\Gamma_m)$.  For $f\in C(K,\T)$, define the degree 
  \begin{equation*}
  	\bar{\omega}^{(m)}(f)=\left( \omega_{\gamma_1^{(m)}}(f),\dots, 	\omega_{\gamma_{n_m}^{(m)}}(f)\right),
  \end{equation*}
  where 
  $
  \omega_{\gamma}(f)
  $
  is the degree of $f|_\gamma$. 

  Again, to generate harmonic maps, we construct a covering space depending on the degree. To that end, we require a few technical assumptions, described below. We believe they are not overly restrictive, e.g., they hold for standard examples of p.c.f. fractals such as the higher order Sierpinski Gaskets, the pentagasket, and the hexagasket \cite{MM2024}.
  %These technical assumptions are used in the construction of the covering spaces of $K$. 

  Fix an embedding {$\iota :\mathcal{B}_m\to \operatorname{Cyc}(\Gamma_{m+1})$,}
  such that 
  {
  	\begin{equation}\label{cycle_extend}
  		V\left(\gamma^{(m)}_i\right) \subset V\left(\iota(\gamma^{(m)}_i)\right),\quad 1\leq i\leq n_m,
  	\end{equation}
  }
  and
  \begin{equation}\label{embed}
  	V\left(\iota(\gamma^{(m)}_i )\right)\cap V\left(\iota(\gamma^{(m)}_j )\right)  =
  	V\left(\gamma^{(m)}_i \right)\cap V\left(\gamma^{(m)}_j \right), \quad 1\le i,j\le n_m,\;\;\; {j\neq i}.
  \end{equation}

  Assume that for every $i \in [n_m]$ there is $\xi(\gamma_i^{(m)})\in V_{m+1}$ such that
  \begin{equation}\label{pcf-cut}
  	V\left(\iota(\gamma^{(m)}_i )\right)\ni  \xi(\gamma_i^{(m)})\notin V\left(\iota(\gamma^{(m)}_j )\right),
  	\quad j\neq i.
  \end{equation}
 In particular, the $\xi(\gamma_i^{(m)})$ serve the role of the cut vertices. 



  %Let $\gamma_0\in\operatorname{Cyc}(\Gamma_m)$ be a cycle that contains boundary vertices $V_0\subset V(\gamma_0)$. 
  % \marginpar{From the same embedding issues above, $p$ may not correspond to a % unique loop in $K$. Maybe instead we start from $p$, a loop in $K$ containing % $V_0$. Then its restrictions to $V_m$ are in $Cyc(\Gamma_m)$.}
  %Recall that $\bar f_p$ stands for the 
  %lift of $f_p=f\circ c_p,$ where $c_p$ is an appropriate parametrization
  %of $p$.
 % Here, by abuse of notation $\gamma_0$ also stands for the corresponding 
 % loop in $K$. Denote $\rho_0=\omega_{\gamma_0}(f)$, and define the boundary increments
 % \begin{align}
 % 	\p_{v_1v_2} f&= \delta_1, \nonumber\\
 % 	\p_{v_2v_3} f&= \delta_2, \label{pcf-bc-hm}\\
 % 	&\dots,\nonumber\\
 % 	\p_{v_{\ell-1}v_{\ell}} f &= \delta_{\ell-1}\nonumber \\
 %	\p_{v_{\ell}v_1} f&=\rho_0-\delta_1-\delta_2-\dots-\delta_{\ell-1}, \nonumber
 % \end{align}
 % where  $V_0=\{v_1,v_2,\dots, {v_\ell}\}.$

From \eqref{cycle_extend}-\eqref{pcf-cut}, we can construct a covering space $\tilde{K}$ using the same procedure as in Section \ref{sec.hmaps}. Indeed, first fix a degree
\begin{equation}
	\bar{\omega}^{(m)}(f) = (\rho_1,\dots, \rho_{n_m})\in \Z^{n_m}.
\end{equation}
Let $K_\times = K\times \Z$. On each sheet $K^s = K\times \{s\}$, create two copies of the cut vertices $z_i^{s}:= \xi(\gamma_i^{(m)})$, named $(z_{i}^{s})_-$ and $(z_{i}^{s})_+$. Identifying 
\begin{equation*}
	(z_{i}^s)_+ \simeq (z_{i}^{s+\rho_i})_-,
\end{equation*}
results in the covering space $\tilde{K} = K_\times/\simeq$ with fundamental domain $K^0$. Additionally, $K^0$ is approximated by graphs $\Gamma_m^s = (V_m^s,E_n^s)$. 

As a visual example, Figure \ref{fig:sg3_cut} shows this construction on $\Gamma_1$ of $SG_3$, a higher-order Sierpinski Gasket (see, e.g., \cite{MM2024} for a precise construction of this higher order SG). Given degree $\bar{\omega}^{(m)}$, gluing cut points across sheets results in the associated covering space $\tilde{K}$.

