\subsection{Convergence of KM on p.c.f. fractals}

An analogous theory of harmonic functions exists on these covering spaces. Introduce Dirichlet energies on the fundamental domain,
\begin{equation*}
	\cE_n[\Gamma_n^0](u) = \sum_{(i,j)\in E^0_n} c_{ij}^n\frac{(u(v_j)-u(v_i))^2}{2},
\end{equation*}
and corresponding spaces
  \begin{align*}
	H^0_n = \{ f \in L(V^0_n,\R)\colon  &f(v^0_1)=0,\\
	&\; f((z^0_i)_+)=f((z^0_i)_-)+\rho_i, \forall i\in [n_m]\},
\end{align*}
where, as usual, the value at $v_1^0\in V^0$ is fixed to remove translation invariance. As in \eqref{eq:limit_k0_energy}, the limit
\begin{equation*}
	\cE_{K^0}(f) = \lim_{n\to\infty} \cE_n[\Gamma_n^0](f)
\end{equation*}
is well-defined. Denote $\operatorname{dom}(\cE_{K^0})\doteq \{u\in C(K^0,\R) : \cE_{K^0}(u)<\infty\}$.

Minimizing $\cE_n[\Gamma_n^0]$ and repeatedly applying the harmonic extension algorithm results in a harmonic function on $K^0$, which can be extended to all of $\tilde{K}$ as in Section \ref{sec.harm-struct}. Projecting the range to $\T$ results in the desired harmonic map. Moreover, the resultant map satisfies natural boundary conditions (cf. Lemma \ref{lem.natural}).
% For further details, see also \cite{MM2024}.



  \begin{theorem}\label{thm.pcf}
  	  Fix $m\in \N$ and a degree
  	  \begin{equation}\label{eq:winding_vec_general}
  		\bar{\omega}^{(m)}(f)=(\rho_1,\dots,\rho_{n_m}).
  	\end{equation}
  	There is a harmonic map $f\colon K\to\mathbb{T}$ satisfying \eqref{eq:winding_vec_general} and $\partial_{\bf n}f(v_i)=0$ for all $v_i\in V^0$.  \end{theorem}

As in the previous sections, to establish convergence results we require H\"older continuity. A variation of the following can be found in \cite{Str06}. Recall that the fundamental domain $K^0$ can be represented as a finite union of $m$-cells. Denoting $K^0_w\doteq K_w(K^0)$, we have $K^0 = \bigcup_{|w|=m}K^0_w$, where each $K^0_w$ is a copy of $K$.

\begin{lemma}\label{lem:holder_estimate_pcf}
	Let $f\in \operatorname{dom}(\mathcal{E}_{K^0})$, and represent the fundamental domain as a union of $m$-cells: $K^0=\bigcup_{|w|=m} K^0_w$. There exists $\beta>0$ so that for any $x,y \in K^0_w$,  
	\begin{equation*}
		\frac{|f(x)-f(y)|}{|x-y|^{\beta}}\leq C\sqrt{\mathcal{E}_{K^0}(f)},
	\end{equation*}
	where $C$ is independent of $f$.
\end{lemma}

\begin{proof}
	Arguing as in Lemma \ref{lem:holder_sg_lift}, it is sufficient to establish H\"older continuity on $K$ itself. Let $R(x,y)$ be the effective resistance metric induced by $\cE_{K}$ on $K$. That is,
	\begin{equation*}
		R(x,y)^{-1}\doteq \min \{\cE(u)\colon u(x)=0,\; u(y)=1\}.
	\end{equation*} 
	Then $R$ is a metric and induces a 1/2-H\"older norm on the domain of $\cE_{K}$, cf \cite{Kig01}:
	$$|f(x)-f(y)|\leq R(x,y)^{1/2}\sqrt{\cE(f)}.$$
	Hence, we need only show that $R(x,y)^{1/2}\leq C|x-y|^\beta$. 

	To that end, assume first that $x,y\in V_n$ and take $u\in \operatorname{dom}(\cE)$ to be the harmonic spline whose values on $V_n$ are $u(z)=\delta_{zy}$ (i.e., $u(z)=1$ only when $z=y$). Then $\cE(u)\geq \cE_n(u)\geq Cr_w^{-1}$, where $r_w$ is a product of the $r_i$ defined in \eqref{eq:compatability0}. From the definition of $R$ certainly $R(x,y)\leq Cr_w$. Defining $\bar{r}=\max r_i <1$, we have $R(x,y)\leq C\bar{r}^n$. Next, recall that the $F_i$ have contraction ratios $\lambda_i$. Letting $\underline{\lambda}=\min \lambda_i$, we have a lower bound $|x-y|\geq C\underline{\lambda}^n$, $x,y \in V_n$. Thus taking $\alpha = \log(\overline{r})/\log(\underline{\lambda})$ then 
	\begin{equation*}
		R(x,y)^{1/2}\leq C |x-y|^{\alpha/2}.
	\end{equation*}
	If $x,y\in K$ are arbitrary, then by density of $V_*$ there are sequences $x_n\to x$ and $y_n\to y$ with $x_n,y_n\in V_n$ and the same estimate follows by continuity.
\end{proof}


The convergence of stable equilibria of KM on p.c.f. fractals now follows similarly. Consider the KM on $\Gamma_n$ approximating $K$:
\begin{equation}\label{KM-pcf}
	\dot u(t,v_i)= \sum_{i,j}c_{i,j}^n \sin\left(2\pi\left(u(t,v_j)-u(t,v_i)\right)\right), \quad
	v_i\in  V_n.
\end{equation} 
  	Combining the covering space construction of harmonic maps (Theorem \ref{thm.pcf}), and the a priori H\"older estimates on the fundamental domain (Lemma \ref{lem:holder_estimate_pcf}), applying the same arguments as in Section \ref{sec.proof} results in the following Theorem.

  	\begin{theorem}
  		Fix $m\in \N$ and a degree $\bar{\omega}^{(m)}(u^*)$. Construct a harmonic map $u^*\in C(K,\T)$ as in Theorem \ref{thm.pcf}. Then, for each $\varepsilon>0$, there exists $N\in \N$ such that for all $n\geq N$, the KM on $\Gamma_n$ has a stable steady state solution $u^{n}\in L(V_n,\T)$ such that
  	\begin{equation}
	\max_{x\in V_n} | u^{n}(x)-u^*(x)|<\epsilon.
\end{equation}
Moreover, there is an extension of $u^{n}$ to a continuous function on $K$, $\tilde{u}^{n}$
	such that 
	$\bar{\omega}^{(m)}(\tilde u^{n})=\bar{\omega}^{(m)}(u^*)$ and
	\begin{equation}
		\max_{x\in K} | \tilde{u}^{n}(x)-u^*(x)|<\epsilon.
	\end{equation}
  	\end{theorem}

