\subsection{Estimation error for $\widehat{\protect\bB}^{(2)}$}

\label{stage3}

Let $\mathcal{L}(\cdot;\bS_{xx},\bS_{xy},\bTheta):\mathbb{R}^{p\times q}\rightarrow\mathbb{R}$
be the loss functions to estimate \textbf{$\bB^{*}$} which depend
on matrices $\bS_{xx}\in\mathbb{R}^{p\times p}$, $\bS_{xy}\in\mathbb{R}^{p\times q}$
and $\bTheta\in\mathbb{R}^{q\times q}$. Let $\bB\in\mathbb{\mathbb{R}}^{p\times q}$
be any arbitrary matrix and set 
\begin{align}
\mathcal{L}(\bB;\bS_{xx},\bS_{xy},\bTheta) & =\tr[(\bB^{\top}\bS_{xx}\bB/2-\bS_{xy}^{\top}\mathbf{B})\bTheta]\nonumber \\
 & =\vec(\bB)^{\top}(\bTheta\otimes\bS_{xx})\vec(\bB)/2-\tr(\bTheta\bS_{xy}^{\top}\bB).\label{eq:2ndBeta_loss}
\end{align}
The quantity $\bS_{xx}$ in \eqref{eq:2ndBeta_loss} will be replaced
by the estimate of $\bSigma_{xx}^{*}$ from the data since there is
no missingness in $\bX$. The quantities $\bS_{xy}$ and $\bTheta$
will be replaced by the surrogate and the estimates of $\bSigma_{xy}^{*}$
and $\bTheta_{\varepsilon\varepsilon}^{*}$, respectively. For brevity,
we write, $\mathcal{L}(\cdot;\bS_{xx},\bS_{xy},\bTheta)$ as $\mathcal{L}$
in the following derivations.

We consider the elementwise sparsity of $\bB^{*}$. A matrix $\bB^{*}$
is called elementwise sparse if its support set $S\subset\mathbb{R}^{p\times q}$
is such that $s=\card(S)\ll pq$. In order to obtain an elementwise
sparse estimator of \textbf{$\bB^{*}$}, it is natural to regularize
the least squares program with the $\VERT\cdot\VERT_{1,1}$ penalty
of $\bB$, 
\begin{equation}
\widehat{\bB}^{(2)}=\argmin_{\bB\in\mathbb{R}^{p\times q}}\left\{ \mathcal{L}(\bB;\bS_{xx},\widehat{\bS}_{xy},\widehat{\bTheta}_{\varepsilon\varepsilon})+\lambda_{\bB}\VERT\bB\VERT_{1,1}\right\} ,\label{eq:Beta_obj_mat}
\end{equation}
where $\lambda_{\bB}>0$ is a tuning parameter.

Next, we establish the restricted eigenvalue (RE) condition for the
loss function. Following \citet{negahban2012unified}, let us define,
for all $\bDelta=\bB-\bB^{*}\in\mathbb{Q}$, 
\begin{align*}
\mathcal{E}\mathcal{L}(\bDelta,\bB^{*}) & =\mathcal{E}\mathcal{L}(\bDelta,\bB^{*};\bS_{xx},\bS_{xy},\bTheta_{\varepsilon\varepsilon}^{*})\\
 & =\mathcal{L}(\bB^{*}+\bDelta;\bS_{xx},\bS_{xy},\bTheta_{\varepsilon\varepsilon}^{*})-\mathcal{L}(\bB^{*};\bS_{xx},\bS_{xy},\bTheta_{\varepsilon\varepsilon}^{*})-\langle\nabla_{\bB}\mathcal{L}(\bB^{*};\bS_{xx},\bS_{xy},\bTheta_{\varepsilon\varepsilon}^{*}),\bDelta\rangle\\
 & =\langle\bDelta^{\top}\bS_{xx}\bDelta,\bTheta_{\varepsilon\varepsilon}^{*}\rangle/2\\
 & =\vec(\bDelta)^{\top}(\bTheta_{\varepsilon\varepsilon}^{*}\otimes\bS_{xx})\vec(\bDelta)/2,
\end{align*}
where 
\[
\nabla_{\bB}\mathcal{L}(\bB;\bS_{xx},\bS_{xy},\bTheta_{\varepsilon\varepsilon}^{*})=\bS_{xx}\bB\bTheta_{\varepsilon\varepsilon}^{*}-\bS_{xy}\bTheta_{\varepsilon\varepsilon}^{*}
\]
To derive the bound for the estimator $\widehat{\bB}^{(2)}$
we need the following assumption on the RE condition for the loss
function. 
\begin{assumption}
\label{assu:3}The loss function $\mathcal{L}(\cdot;\bS_{xx},\bS_{xy},\bTheta_{\varepsilon\varepsilon}^{*})$
satisfies the RE condition 
\begin{equation}
\mathcal{E}\mathcal{L}(\bDelta,\bB^{*})\geq\kappa\VERT\bDelta\VERT_{F}^{2}\qquad\forall\bDelta\in\mathbb{C}(S).\label{eq:RE_refined_B}
\end{equation}
with constant $\kappa>0$ over the cone set $\mathbb{C}(S)=\left\{ \bM\in\mathbb{R}^{p\times q}:\VERT(\bM)_{S^{c}}\VERT_{1,1}\leq3\VERT(\bM)_{S}\VERT_{1,1}\right\} $. 
\end{assumption}
\begin{thm}
\label{thm:1}Suppose that Assumption \ref{assu:3} and the assumptions
of Proposition \ref{prop:2} hold. Further suppose that for $s=\card(S)$,
where $S\subset\mathbb{R}^{p\times q}$ is the support set 
\end{thm}
\begin{enumerate}
\item $n$ is sufficiently large to ensure that $\kappa^{\prime}\geq\kappa>0$,
where $\kappa^{\prime}$ is defined as the empirical counterpart to
$\kappa$ in Assumption \ref{assu:3} as 
\begin{equation}
\kappa^{\prime}=\kappa-\VERT\bS_{xx}\VERT_{2}\Delta_{1}(\bTheta_{\varepsilon\varepsilon}^{*})/2\label{eq:kappa_prime}
\end{equation}
\item The tuning parameter $\lambda_{\bB}$ in \eqref{eq:Beta_obj_mat}
satisfies 
\begin{equation}
\lambda_{\bB}/2\geq(\lambda_{0}/2)(\VERT\widehat{\bTheta}_{\varepsilon\varepsilon}-\bTheta_{\varepsilon\varepsilon}^{*}\VERT_{1}+\VERT\bTheta_{\varepsilon\varepsilon}^{*}\VERT_{1}),\label{eq:lambda_overall}
\end{equation}
with 
\[
\lambda_{0}\coloneqq  C(\sigma_{W},\sigma_{\varepsilon}) \sqrt{\frac{\log p}{n}},
\]
where $C(\sigma_{W},\sigma_{\varepsilon})=2X_{\max}\max\left[\sigma_{W}s_{\max}X_{\max}B_{\max}/\mu_{\min},\sigma_{W}\sigma_{\varepsilon}/\mu_{\min},\sigma_{\varepsilon}\right],$ then the estimator $\widehat{\bB}^{(2)}$
satisfies 
\begin{equation}
\VERT\widehat{\bB}^{(2)}-\bB^{*}\VERT_{F}\leq3\sqrt{s}\lambda_{\bB}/\kappa^{\prime},\qquad\VERT\widehat{\bB}^{(2)}-\bB^{*}\VERT_{1,1}\leq12s\lambda_{\bB}/\kappa^{\prime}\label{eq:B_final_est}
\end{equation}
with probability $1-qC\exp(-c\log p)$.
\end{enumerate}
\ref{Pr_Thm1} provides the proof of Theorem \ref{thm:1}. 

\section{Simulation}


\subsection{Simulations to verify theoretical results\label{sim_theory_verify}}
In this section, we present simulation results to study the scaling behavior of estimation errors across the three stages of estimation, as discussed by our theoretical analysis.

We generate an $n\times p$ matrix $\bX$ with rows
drawn independently from $\mathcal{N}_{p}(0,\bSigma^{*}_{xx})$ where $[\bSigma^{*}_{xx}]_{i,j}=0.7^{|i-j|}$ follows an AR(1) covariance. Response matrix  $\bY \in \mathbb{R}^{n \times q}$ is generated from a multivariate Gaussian distribution
with $\mathcal{N}_{q}(\bX\bB^{*},\bSigma^{*}_{\varepsilon\varepsilon})$. We consider the AR(1) error covariance $[\bSigma^{*}_{\varepsilon\varepsilon}]_{i,j}=\rho_{\varepsilon}^{|i-j|}$, which leads to a tri-diagonal, sparse precision matrix $\bTheta^{*}_{\varepsilon\varepsilon}=(\bSigma^{*}_{\varepsilon\varepsilon})^{-1}$. We generate $\bW$ from a Bernoulli distribution with varying
probability of missingness for each column $\rho_{W}$. To obtain an elementwise sparse model on $\bB^{*}$,
generated a $p\times q$ matrix $\bB^{*}$ so that in each
of its columns, only 5 entries of $p$ (chosen at random within
each column) are drawn from the uniform distribution on $[-1, 1]$ and the remaining entries are equal to zero. Finally, we derive the contaminated responses as $\bZ=\bY\odot\bW$. 


We aim to examine how the estimation error \( \|\widehat{\bbeta}_{l}-\bbeta_{l}^{*}\|_{2} \), presented in Proposition \ref{prop:1}, with its upper bound dependent on the tuning parameter $\lambda_l$ defined in \eqref{eq:lambda_ell}, behaves under an AR(1) covariance structure for the error. We vary two parameters: the error correlation \( \rho_{\varepsilon} \), where $[\bSigma^{*}_{\varepsilon\varepsilon}]_{i,j}=\rho_{\varepsilon}^{|i-j|}$, and the minimum signal strength \( \mu_{\min} = \min_{j}\mu_{j} = \min_{j}(1 - \rho_{W,j}) \), which is related to the probability of missingness in the $j$th column of the outcome, \( \rho_{W,j} \). For simplicity, we assume the same probability of missingness across columns. We analyze the impact of varying \( \rho_{\varepsilon} \) and \( \rho_{W,j} \) separately to evaluate the performance of the estimation error. In this stage, we inspect two scenarios: (S1A) varying \( n \) with fixed \( p \), and (S1B) varying \( p \) with fixed \( n \). The plots present the average estimation error, with shaded regions indicating standard errors, based on 100 replicated samples.




\textbf{Scenario S1A:} Let $n = (200, 400, 800, 1600, 3200, 6400, 12800)$, $p = 100$, $q = (10, 20)$, and $s_{\max} = 5$. We evaluate the following two scenarios by plotting $\|\widehat{\bbeta}_{l} - \bbeta_{l}^{*}\|_{2}$ against $\sqrt{n}$, as shown in Figure \ref{fig:ERS1P1}:
(a)   $\rho_{\varepsilon} = (0, 0.3, 0.7, 0.9)$ with $\rho_{W,j} = 0.05$; and (b)   $\rho_{W,j} = (0.005, 0.1, 0.2, 0.3)$ with $\rho_{\varepsilon} = 0.7$.

\textbf{Scenario S1B:} We set $p = (50, 100, 200, 400, 800)$, $n = 400$, $q = (10, 20)$, and $s_{\max} = 5$. We test the following two scenarios by plotting $\|\widehat{\bbeta_{l}} - \bbeta_{l}^{*}\|_{2}$ versus $\sqrt{\log(p)}$, as shown in Figure \ref{fig:ERS1P2}:
(a)  $\rho_{\varepsilon} = (0, 0.3, 0.7, 0.9)$ with $\rho_{W,j} = 0.05$;
    and (b)  $\rho_{W,j} = (0.005, 0.1, 0.2, 0.3)$ with $\rho_{\varepsilon} = 0.7$.

