%Then, the product estimate~\eqref{apdx:pdt:algb} and the composition estimate~\eqref{apdx:composition:gen} yield the desired estimate.
%\end{proof}

The issue of loss of derivatives on $\eta$ (and thus, on $\eta_0$ in the case where $\eta$ is given by~\eqref{eqn:phi:def:bary}) is solved by using Alinhac's good unknowns, introduced in~\cite{Alinhac1989}, and defined as
\begin{equation}
\label{apdx:alinhac:definition}
\pointal{f}{s} := \dot{\Lambda}^{s} f -  \frac{\dot{\Lambda}^{s} (\etab+ \epsilon \eta)}{\hb+\epsilon h} \partial_r f.
\end{equation}
See also~\cite{AlazardMetivier2009} and~\cite{Lannes2013} for its use for the water waves equations, as well as~\cite[Proposition 3.17]{Castro2014a} and~\cite{MasmoudiRousset2012} for the present context. Note also that, because of~\eqref{hyp:Hb:reg}, the diffeomorphism $\varphi$ defined in~\eqref{eqn:phi:def} is a perturbation of size $\epsilon \vee \beta$ of the identity. Hence, the commutator in~\eqref{apdx:alinhac:comm_brutal} is of size $\epsilon \vee \beta$. This is also true for the commutators in Lemma~\ref{apdx:alinhac:def}.
%Recall the notation $$ \varphi(t,x,r) = (t,x,r + \epsilon \eta(t,x,r)).$$

\begin{lemma}[Alinhac's good unknown,~\cite{Alinhac1989}]
\label{apdx:alinhac:def}
%\knowledgenewrobustcmd{\diff}{\cmdkl{\mathbb{\Lambda}}}

Let $s_0,s \in \N$ with $s_0 > \frac{d+1}{2}$, $s \geq s_0 + 2$. Assume that $\eta_0 \in H^{s_0+2}$ and~\eqref{hyp:H}. Then there exists $C>0$ depending only on an upperbound on $\vert \eta_0 \vert_{H^{s_0+2}(\R^d)}$ such that the following holds. Let $f \in H^{s}$. We have 
\begin{equation}
\label{apdx:alinhac:comm1}
\dot{\Lambda}^{s}  \gradphi[t,x,r] f = \gradphi[t,x,r] \pointal{f}{s}  + \commal{\dot{\Lambda}^{s}}{\gradphi[t,x,r]}{f},
\end{equation}
and we can write
\begin{equation}
\label{apdx:alinhac:R1}
\Vert \commal{\dot{\Lambda}^{s}}{\gradphi[t,x,r]}{f}\Vert_{L^2(S)} \leq C(\epsilon \vee \beta) (1+\vert \eta_0 \vert_{H^{s}(\R^d)}) \Vert \gradphi[t,x,r] f\Vert_{H^{s-1}(S)} .
\end{equation}
