\begin{proposition}
\label{prop:pression}
Let $s_0,s \in \N$, with $s_0 > \frac{d+1}{2}$, $s \geq s_0 + 1$, $1 \leq k \leq s$, and assume~\eqref{hyp:b},~\eqref{hyp:density},~\eqref{hyp:H},~\eqref{hyp:Hb:reg},~\eqref{hyp:H:reg}. Let $M > 0$ and assume  $\Vert V, \sqrt{\mu} w \Vert_{H^{s,k}} + \Vert \rho \Vert_{H^{s,k}} + |\eta_0|_{H^{s+1}} \leq M$. Then there exists $C > 0$ depending only on $M$ such that
\begin{equation}
\label{eqn:pression:estimee}
\Vert \sqrt{\mu} \gradphi P, \partialphi{r} P \Vert_{H^{s,k}} \leq C \sqrt{\mu} \left(\Vert V, \sqrt{\mu} w \Vert_{H^{s+1,k+1}} + \Vert \vort  \Vert_{H^{s,k}} + \sqrt{\mu}|\eta_0|_{H^{s+1}} + \frac{\delta}{\sqrt{\mu}} \Vert \rho \Vert_{H^{s,k}}\right).
%\Vert(\Fun,\sqrt{\mu} \Fdeux) \Vert_{H^{s,k}} +  \Vert(\partialphi{t} \Ftrois,\gradphi[x,r] \Ftrois) \Vert_{H^{s-1,k-1}}
\end{equation}
%If moreover $k \geq 2$ \note{ à vérifier !}
%$$\Vert \Lambda^{s-k} \partial_r^k \sqrt{\mu} \gradphi P, \Lambda^{s-k} \partial_r^k\partialphi{r} P \Vert_{L^2} \lesssim \sqrt{\mu} \epsilon \Vert V, \sqrt{\mu} w \Vert_{H^{s,k}}$$ \note{comme il y a du $\partial_r$ on a meme mieux que ça non ?}
\end{proposition}
\begin{proof}
First note that~\eqref{eqn:pression} can be reformulated as
\begin{equation}
\label{eqn:pression:A}
\nablamu \cdot \A \nablamu P  = \nablamu \cdot \vec{R},
\end{equation}
with
\begin{equation}
\label{eqn:A:def}
\A := \frac{1}{\rhotot}\coo{(\hb + \epsilon h)I_d & - \sqrt{\mu} \nabla \eta \\
			- \sqrt{\mu} (\nabla \eta)^T & \frac{1+\mu |\nabla \eta|^2}{\hb + \epsilon h}},
\end{equation}
\begin{equation}
\label{eqn:nablamu:def}
\nablamu := \coo{\sqrt{\mu} \nabla \\ \partial_r},
\end{equation}
and
\begin{equation}
\label{eqn:def_src_pression}
\vec{R} = \sqrt{\mu}\coo{ - \frac{\hb + \epsilon h}{\rhotot} \vec{U} \cdot \gradphi[x,r]V - \frac{g\rhob}{\rhotot} \nabla \eta_0 \\
				\frac{\sqrt{\mu}}{\rhotot}\nabla(\etab + \epsilon \eta) \cdot \left( \vec{U} \cdot \gradphi[x,r] V \right) + \frac{\sqrt{\mu}}{\rhotot}\vec{U} \cdot \gradphi[x,r] w + \frac{\delta}{\sqrt{\mu}} \frac{g \rho}{\rhotot}}. 
\end{equation}
% +(\hb + \epsilon h) \Fun
%- \sqrt{\mu} \nabla(\etab + \epsilon \eta) \cdot \Fun - \sqrt{\mu} \vec{U} \cdot \gradphi[x,r] w + \sqrt{\mu}\Fdeux
We now notice that the bottom boundary condition in~\eqref{eqn:pression:bc} can be recast as
\begin{equation}
\label{eqn:pression:bc:A}
\vec{e_{d+1}} \cdot \A \nablamu P = \vec{e_{d+1}} \cdot \vec{R} \qquad \text{ at } r=-1.
\end{equation}
Therefore, we can use~\cite[Lemma 4.1 eq. (4.9)]{Duchene2022} to solve~\eqref{eqn:pression:A} together with~\eqref{eqn:pression:bc:A} and the homogeneous Dirichlet boundary condition at the surface, and to write the estimates
\begin{equation}
\label{eqn:pression:estimee1}
\Vert \sqrt{\mu} \nabla P, \partial_r P \Vert_{H^{s,k}} \leq C \Vert \vec{R} \Vert_{H^{s,k}},
\end{equation}
where $C$ depends on $M$. Note that according to~\eqref{eqn:gradphi:def} and the product estimate~\eqref{apdx:eqn:pdt:algb}, we get
$$\Vert \sqrt{\mu} \gradphi P, \partialphi{r} P \Vert_{H^{s,k}} \leq C' \Vert \vec{R} \Vert_{H^{s,k}},$$
with $C'>0$ depending on $M$. Thus, it only remains to bound the right-hand side of~\eqref{eqn:pression:estimee1}. The remaining of the proof is devoted to the proof of the following bound, for $s' \geq s_0$ and $1 \leq k' \leq s'$:
\begin{equation}
\label{eqn:R:estimee:finale}
\Vert \vec{R} \Vert_{H^{s',k'}} \leq C \sqrt{\mu}\left( \Vert V, \sqrt{\mu} w \Vert_{H^{s'+1,k'+1}} + \Vert \vort \Vert_{H^{s',k'}} + \sqrt{\mu} \vert \eta_0\vert_{H^{s+1}} + \frac{\delta}{\sqrt{\mu}}\Vert \rho \Vert_{H^{s',k'}} \right).% + \sqrt{\mu}|\eta_0|_{H^{s'+1}} +  \Vert(\Fun,\sqrt{\mu} \Fdeux,\Ftrois)\Vert_{H^{s',k'}} \right).
\end{equation}
Note that the condition $s' \geq s_0$ is less restrictive than the one on $s$ in Proposition~\ref{prop:pression}, hence the notation. Using the definition~\eqref{eqn:def_src_pression} of $\vec{R}$ and the product estimate~\eqref{apdx:eqn:pdt:algb:tame}, we get
\begin{equation}
\label{eqn:R:estimee}
\begin{aligned}
 \frac{1}{\sqrt{\mu}} \Vert \vec{R} \Vert_{H^{s',k'}} &\lesssim \Vert\frac{\hb + \epsilon h}{\rhotot} V \cdot \gradphi V \Vert_{H^{s',k'}} + \Vert \frac{\hb + \epsilon h}{\rhotot} w \partialphi{r} V \Vert_{H^{s',k'}} \\
 &+ \sqrt{\mu}\Vert \frac{1}{\rhotot} V \cdot \gradphi w \Vert_{H^{s',k'}} + \sqrt{\mu} \Vert \frac{1}{\rhotot} w \partialphi{r} w \Vert_{H^{s',k'}}\\
 & + \Vert(1-\epsilon \delta \frac{\rho}{\rhotot} )\nabla \eta_0 \Vert_{H^{s',k'}} + \frac{\delta}{\sqrt{\mu}}\Vert \frac{\rho}{\rhotot} \Vert_{H^{s',k'}}.
  %+ \Vert \Fun \Vert_{H^{s',k'}} + \sqrt{\mu} \Vert \Fdeux \Vert_{H^{s',k'}} 
\end{aligned}
\end{equation}
We now treat only the second and fourth terms on the right-hand side of~\eqref{eqn:R:estimee}, as the other ones are treated the same way. 
%the non-linear terms. 
First note that% $\hb + \epsilon h = 1 - \beta b + \epsilon \eta_0 $ and 
\begin{equation}
\label{eqn:trick:compo}
\frac{1}{\rhotot} = \frac{1}{\rhob} - \epsilon \delta \frac{\rho/\rhob}{\rhotot}.
\end{equation}
%Thus, the product estimates~\eqref{apdx:eqn:pdt:algb} and~\eqref{apdx:eqn:pdt:infty} yield
%$$\begin{aligned}
%\Vert\frac{\hb + \epsilon h}{\rhotot} V \cdot \gradphi V \Vert_{H^{s',k'}} &\leq C (1+\beta \vert b \vert_{H^{s'}} + \epsilon \vert \eta_0 \vert_{H^{s'}})(\frac{1}{\rhob} + \epsilon \delta \Vert \frac{\rho/\rhob}{\rhotot} \Vert_{H^{s',k'}}) \Vert V \Vert_{H^{s',k'}} \Vert V \Vert_{H^{s'+1,k'+1}}. \end{aligned}$$
Using the composition estimate~\eqref{apdx:eqn:composition:gen} for the second factor with $F:y \mapsto \frac{y/\rhob}{\rhob + \epsilon \delta y}$, with~\eqref{hyp:density} and~\eqref{hyp:H},~\eqref{hyp:Hb:reg},~\eqref{hyp:H:reg} and the product estimate~\eqref{apdx:eqn:pdt:algb}, we get
%$$\Vert\frac{\hb + \epsilon h}{\rhotot} V \cdot \gradphi V \Vert_{H^{s',k'}} \leq C \Vert V \Vert_{H^{s'+1,k'+1}},$$
%where $C$ depends on an upperbound on $\Vert \rho \Vert_{H^{s'}}, \Vert V \Vert_{H^{s'+1,k'+1}}, \vert \eta_0 \vert_{H^{s'+1}}.$ The same computations yield
%$$\begin{aligned}
%\sqrt{\mu}\Vert \frac{1}{\rhotot}V \cdot \gradphi w \Vert_{H^{s',k'}}&\leq C \Vert V \Vert_{H^{s',k'}} \Vert \sqrt{\mu} w \Vert_{H^{s'+1,k'+1}} \leq C \Vert \sqrt{\mu} w \Vert_{H^{s'+1,k'+1}}.
%\end{aligned}$$
%We now bound the second term in~\eqref{eqn:R:estimee}. The factor $\frac{\hb + \epsilon h}{\rhotot}$ is treated as before and we omit it. We write, thanks to the product estimate~\eqref{apdx:eqn:pdt:algb}
\begin{equation}
\label{eqn:R:estimee2}
\Vert \frac{\hb + \epsilon h}{\rhob + \epsilon \delta \rho} w \partialphi{r} V \Vert_{H^{s',k'}} \leq C \Vert \sqrt{\mu} w \Vert_{H^{s',k'}} \Vert \frac{1}{\sqrt{\mu}} \partialphi{r} V \Vert_{H^{s',k'}}.
\end{equation}
Using the definition~\eqref{eqn:vort:def} of $\vort$ and triangular inequality, we get
$$ \Vert \frac{1}{\sqrt{\mu}} \partialphi{r} V \Vert_{H^{s',k'}} \leq C \left( \Vert \vort \Vert_{H^{s',k'}} + \Vert \sqrt{\mu} w \Vert_{H^{s'+1,k'+1}} \right).$$
Together with~\eqref{eqn:R:estimee2}, this yields the control on the second term in~\eqref{eqn:R:estimee}. \\
We now treat the fourth term in the right-hand side of~\eqref{eqn:R:estimee}. The factor depending on $\rho$ is treated as before and we omit it. Thanks to the product estimate~\eqref{apdx:eqn:pdt:algb} we get
\begin{equation}
\label{eqn:R:estimee3}
\Vert\sqrt{\mu}  w \partialphi{r} w \Vert_{H^{s',k'}} \leq C \Vert \sqrt{\mu} w \Vert_{H^{s',k'}} \Vert  \partialphi{r} w \Vert_{H^{s',k'}}.
\end{equation}
We use the incompressibility condition in~\eqref{eqn:euler_phi} and triangular inequality to get
$$\Vert\sqrt{\mu}  w \partialphi{r} w \Vert_{H^{s',k'}} \leq C \Vert \sqrt{\mu} w \Vert_{H^{s',k'}}  \Vert  V \Vert_{H^{s'+1,k'+1}}.$$% + \Vert \Ftrois \Vert_{H^{s',k'}}\right).$$
%The last two terms in~\eqref{eqn:R:estimee} are treated the same way and we omit them.
\end{proof}
Recall now the definition of the Rayleigh-Taylor coefficient
\begin{equation}
\taylor := g\rhob - (\frac{\epsilon}{\hb + \epsilon h} \partial_r P)_{|r=0}.
\end{equation}
We write a similar result as Proposition~\ref{prop:pression}, although with lower regularity, that controls the term
\begin{equation}
\label{eqn:def:dta}
\frac{d}{dt} \taylor := \frac{d}{dt} \left(g\rhob - (\frac{\epsilon}{\hb + \epsilon h}\partial_r P)_{|r=0}\right).
\end{equation}
\begin{lemma}
\label{lemma:taylor:dt}
Under the same assumptions as Proposition~\ref{prop:pression}, we have
\begin{equation}
\label{eqn:taylor:dt}
 \left\vert (\taylor-g\rhob,\frac{d}{dt} \taylor) \right\vert_{L^{\infty}} \leq C\epsilon \left( \Vert V,\sqrt{\mu}w,\sqrt{\mu} \rho \Vert_{H^{s_0+2}}  +  \vert \eta_0 \vert_{H^{s_0+2}} \right). %+ \delta \Vert \rho \Vert_{H^{s_0+2}}
\end{equation}
\end{lemma}
\begin{proof}
We only treat the estimate on $\frac{d}{dt} \taylor$, as the other one is treated the same way. The first term in~\eqref{eqn:def:dta} is actually zero because $\rhob$ does not depend on time. We now use the definition~\eqref{eqn:taylor:def} of $\taylor$ so that the second term on the right-hand side of~\eqref{eqn:def:dta} writes
$$\epsilon \frac{\epsilon\partial_t \eta_0}{(\hb + \epsilon h)^2} (\partial_r P)_{|r=0} + \frac{\epsilon}{\hb + \epsilon h} (\partial_r \partial_t P)_{|r=0}.$$
Taking the $L^{\infty}$-norm of this expression, we use the classical embedding $H^{s_0}(\R^d) \hookrightarrow L^{\infty}(\R^d)$ and the embedding~\eqref{apdx:eqn:embedding} to write
$$ \vert\frac{d}{dt} \taylor \vert_{L^{\infty}} \leq C \epsilon \left(\vert \epsilon\partial_t \eta_0 \vert_{H^{s_0}} \Vert(\partial_r P)\Vert_{H^{s_0,1}} + \Vert \partial_r \partial_t P \Vert_{H^{s_0,1}}\right),$$
where we also used~\eqref{hyp:H}.
The first term on the right-hand side is bounded using the equation~\eqref{eqn:euler_phi:bc} for $\partial_t \eta_0$ and the elliptic estimate~\eqref{eqn:pression:estimee} together with the trace estimate~\eqref{apdx:eqn:trace}. For the second term, using~\eqref{hyp:H} and the trace estimate~\eqref{apdx:eqn:trace}, we get
$$ \left\vert\frac{1}{\hb + \epsilon h} (\partial_r \partial_t P)_{|r=0}\right\vert_{L^2} \leq C \Vert \partial_r \partial_t P \Vert_{H^{s_0,1}}.$$
%Note however that applying directly Proposition~\ref{prop:pression} requires $(V,w)$ to be in $H^{s_0+\frac72,3}$ which is not in accordance with the assumption~\eqref{hyp:M}.
We write the elliptic system satisfied by $\partial_t P$:
\begin{equation}
\label{eqn:pression:A:2}
\nablamu \cdot \A \nablamu \partial_t P  = \nablamu \cdot \vec{R'},
\end{equation}
with
\begin{equation}
\label{eqn:a:temp:1}
\vec{R'} := \partial_t \vec{R} + [\partial_t,\A]\nablamu P,
\end{equation}
where $\vec{R}$ is defined in~\eqref{eqn:def_src_pression}. The equation~\eqref{eqn:pression:A:2} is completed by the boundary conditions obtained by differentiating~\eqref{eqn:pression:bc} with respect to time. We use~\cite[Lemma 2.38]{Lannes2013} with $s=s_0+\frac12$ and~\eqref{eqn:R:estimee:finale} and use that $V,w,\rho,\eta_0$ are solutions to~\eqref{eqn:euler_phi} to estimate their time derivative through space derivatives, to finally get~\eqref{eqn:taylor:dt}.
\end{proof}
\begin{remark}
In this subsection, we use two different elliptic estimates, namely~\cite[Lemma 4.1]{Duchene2022} for Proposition~\ref{prop:pression} and~\cite[Lemma 2.38]{Lannes2013} for Lemma~\ref{lemma:taylor:dt}. The advantage of the first one is that it controls high order vertical derivatives in $P$. The advantage of the second one is that it is more precise for the low regularities, namely $s_0$ here.
\end{remark}
