\subsection{Quasilinear structure}
\label{subsection:quasilin}
In this subsection, we define an energy functional in~\eqref{eqn:energy:def}. This is the energy functional whose control can be propagated through the equations~\eqref{eqn:euler_phi}, as shown in Subsection~\ref{subsection:nrj}. We show in Lemma~\ref{lemma:energy:equiv} that it controls the Sobolev norms of the unknowns, as well as two quantities that would only be controlled up to a factor $\frac{1}{\sqrt{\mu}}$ with more naive estimates. In Proposition~\ref{prop:restes} we show how to estimate the remainder terms from the quasilinear formulation~\eqref{eqn:euler_quasilin} of~\eqref{eqn:euler_phi}.\\

We start by describing the energy functional that we will use in Subsection~\ref{subsection:nrj}. To this end, recall the definition of the Rayleigh-Taylor coefficient
\begin{equation}
\label{eqn:taylor:def}
\taylor := g\rhob - (\frac{\epsilon}{\hb + \epsilon h} \partial_r P)_{|r=0}.
\end{equation}
We make the following assumption:
\begin{hyp}
\label{hyp:taylor}
\taylor \geq c_* > 0.
\end{hyp}We consider the energy, for $s_0,s \in \N, s_0 > \frac{d+1}{2},  s \geq s_0+2$
%$$\E := \Vert \Lambda^s (V,\sqrt{\mu} w, \taylor \eta_0)\Vert_{L^2}^2 + \Vert \partial_r^2 \Lambda^{s-2} V \Vert_{L^2}^2 + \Vert \vort \Vert_{H^{s-1,k-1}}^2$$
\begin{equation}
\label{eqn:energy:def}
\begin{aligned}
\E :=  \Elow &+ \left\Vert\left(\sqrt{(\hb + \epsilon h)(\rhob + \epsilon \delta \rho)}\pointal{V}{s},\sqrt{\mu (\hb + \epsilon h)(\rhob + \epsilon \delta \rho)}\pointal{w}{s}, \sqrt{\mu (\hb + \epsilon h)} \pointal{\rho}{s}\right)\right\Vert_{L^2(S)}^2 \\
&+ \vert \taylor \point{\eta}{s}_0\vert_{L^2(\R^d)}^2 + \Vert \vort \Vert_{H^{s-1}(S)}^2 ,
\end{aligned}
\end{equation}
where 
\begin{equation}
\label{eqn:energy:def:Elow}
\Elow := \left\Vert\left(V,\sqrt{\mu} w,\rho\right)\right\Vert_{H^{s_0+1}}^2+ g\rhob \vert  \eta_0 \vert_{H^{s_0+1}}^2,
\end{equation}
and where we define
\begin{equation}
\label{eqn:alinhac:def}
\begin{aligned} \point{f}{s} &:= \dot{\Lambda}^{s} f, \qquad
				&\pointal{f}{s} := \dot{\Lambda}^{s}f - \frac{\dot{\Lambda}^{s}(\etab + \epsilon \eta)}{\hb + \epsilon h} \partial_r f.
				%\pointal{f}{s,k} &:= \Lambda^{s-k}\partial_r^kf - \frac{\Lambda^{s-k}\partial_r^k(\etab + \epsilon \eta)}{\hb + \epsilon h} \partial_r f. 
				\end{aligned} 
				\end{equation}	
%We also take the convention $\pointal{f}{s,0} := \pointal{f}{s}$ to lighten the notations later on.	
We assume the existence of a solution $(V,w,\rho,\eta_0) \in C^0([0,T],H^{s}(S)^{d+2}\times H^s(\R^d))$ of~\eqref{eqn:euler_phi} such that there exists $M > 0$ such that
\begin{hyp}
\label{hyp:M}
\sup_{0\leq t\leq T}\E \leq M.
\end{hyp}
\begin{lemma}
\label{lemma:energy:equiv}
Under Assumptions~\eqref{hyp:H},\eqref{hyp:Hb:reg},~\eqref{hyp:H:reg} and~\eqref{hyp:M}, there exists $C > 0$ depending only on $M$ such that:
\begin{equation}
\label{eqn:drV}
\frac{1}{\sqrt{\mu}}\Vert \partial_r V \Vert_{H^{s-1}} \leq C \E,
\end{equation}
as well as
\begin{equation}
\label{eqn:drw}
\Vert \partial_r w \Vert_{H^{s-1}} \leq C \E,
\end{equation}
and
\begin{equation}
\label{eqn:w:trick}
\Vert w \Vert_{H^{s-1}} \leq C \E.
\end{equation}
Moreover, under the additional assumption~\eqref{hyp:taylor}, for $s\geq s_0+2$, we can write 
\begin{equation}
\label{eqn:energy:equiv}
\frac{1}{C} \left(\Vert V,\sqrt{\mu} w,\sqrt{\mu} \rho \Vert_{H^s}^2 + \Vert \vort \Vert_{H^{s-1}}^2 + \vert \eta_0 \vert_{H^s}^2 \right) \leq \E \leq C \left(\Vert V,\sqrt{\mu} w,\sqrt{\mu} \rho\Vert_{H^s}^2 + \Vert \vort \Vert_{H^{s-1}}^2 + \vert \eta_0 \vert_{H^s}^2 \right).
\end{equation}
\end{lemma}
\begin{proof}
The energy $\E$ is bounded from above with a constant depending on $\taylor > 0$ and the constant in~\eqref{hyp:H}, thanks to Cauchy-Schwarz inequality. \\
The energy $\E$ controls $\Vert \vort\Vert_{H^{s-1}(S)}$, and $\vert \eta \vert_{H^s(\R^d)}$ as $\taylor > 0$. It also controls $\Vert V,\sqrt{\mu} w\Vert_{H^{s,0}}$ by~\eqref{eqn:alinhac:equiv}. Let us now prove that it also controls $\Vert V,\sqrt{\mu} w\Vert_{H^{s,k}}$ for any $k \leq s$ by induction. The base case $k=0$ has already been discussed. Assume that $\E$ controls $\Vert V,\sqrt{\mu} w\Vert_{H^{s,l}}$ for every $0 \leq l < k \leq s$.
From the definition of the first component $\vort^{[x]}$ of the vorticity and the incompressibility condition, we can write
\begin{equation}
\label{eqn:1}
\frac{1}{\sqrt{\mu}} \left( I_d + \mu \epsilon^2 \begin{pmatrix} - \partial_y \eta \partial_x \eta & - (\partial_y \eta)^2 \\ (\partial_x \eta)^2 & \partial_y \eta \partial_x \eta \end{pmatrix} \right) \partialphi{r} V  = \vort^{[x]} - \sqrt{\mu} \nabla^{\perp} w - \sqrt{\mu} (\nabla \eta)^{\perp} (\nabla \cdot V).
\end{equation}
The matrix on the left-hand side is invertible, for any $\mu \geq 0,\epsilon \geq 0$ (its eigenvalues are $1$). Now, because $\eta \in H^{s,l}$ (recall from its definition~\eqref{eqn:phi:def:bary} that $\eta$ is linear in $r$), the matrix $(I_d + \mu \epsilon^2 (\nabla \eta)^{\perp} \nabla \eta)^{-1}$ is bounded uniformly in $\mu$ in $H^{s-1,l}$. Using~\eqref{eqn:1} and the product estimate~\eqref{apdx:eqn:pdt:algb} yields $\partialphi{r} V \in H^{s-1,l}$, so we get that $V \in H^{s,l+1}$, and more precisely we have~\eqref{eqn:drV}. \\
For the bound on $\Lambda^{s-(l+1)} \partial_r^{l+1} w$ needed to derive~\eqref{eqn:drw}, we use the incompressibility condition to get
\begin{equation}
\label{eqn:w:trick:temp}
\Vert \Lambda^{s-(l+1)} \partial_r^{l+1} w \Vert_{L^2} \leq \Vert (\hb + \epsilon h) \gradphi \cdot V \Vert_{H^{s-1,l}}.
\end{equation}
We use product estimates~\eqref{apdx:eqn:pdt:algb} and~\eqref{apdx:eqn:pdt:infty} to write
$$\Vert \Lambda^{s-(l+1)} \partial_r^{l+1} w \Vert_{H^{s,l+1}} \leq C (1+|\eta_0|_{s_0+\frac12}) \vert \eta_0 \vert_{H^{s}} \Vert V \Vert_{H^{s,l+1}}.$$
The previous control on $\Vert V \Vert_{H^{s,l+1}}$ yields the result.\\
For the bound~\eqref{eqn:w:trick}, we write for $(t,x,r) \in [0,T)\times \R^d \times [-1,0]$,
$$\begin{aligned}
w(t,x,r) &= w(t,x,-1) + \int_{-1}^{r} \partial_r w(t,x,r')dr' \\
&= \beta \nabla b \cdot V(t,x,-1) + \int_{-1}^{r}\partial_r w(t,x,r')dr',
\end{aligned}
$$
by the boundary condition at the bottom~\eqref{eqn:euler_phi:bc}. Taking the $H^{s-1}$ norm of the previous expression and using the trace estimate~\eqref{apdx:eqn:trace} as well as~\eqref{eqn:drw}, we get~\eqref{eqn:w:trick}.
\end{proof}
%We will also need a norm on the source terms $\Fun,\Fdeux,\Ftrois,\Fquatre$. To this end, we define
%\begin{equation}
%\label{eqn:F:def}
%\Vert F \Vert_{s} := \Vert (\Fun,\sqrt{\mu} \Fdeux,\Ftrois)\Vert_{H^{s}} + \vert \Fquatre \vert_{H^s} + \Vert (\partial_t\Fun,\sqrt{\mu} \partial_t \Fdeux)\Vert_{H^{s_0+\frac32}} + \vert \partial_t \Fquatre \vert_{H^{s_0+\frac32}}.
%\end{equation}
Recall the notation $\dot{\Lambda}^s$ from Subsection~\ref{subsection:notations}. Applying the operator $\diff$ with $s \geq 1$ to~\eqref{eqn:euler_phi} and using~\eqref{apdx:alinhac:comm1} %and the notations defined in~\eqref{eqn:alinhac:def} 
yields the following system 
\begin{equation}
\label{eqn:euler_quasilin}
\sys{ \partialphi{t} \pointal{V}{s} + \epsilon \vec{U} \cdot \gradphi[x,r] \pointal{V}{s} + \epsilon \point{w}{s} \partialphi{r} V  + \frac{1}{\rhotot}\gradphi \pointal{P}{s} + g\frac{\rhob}{\rhotot} \nabla \point{\eta}{s}_0 &= \Run, \\
		\mu \left( \partialphi{t} \pointal{w}{s} + \epsilon \vec{U} \cdot \gradphi[x,r] \pointal{w}{s} \right) + \frac{1}{\rhotot} \partialphi{r} \pointal{P}{s} &= \sqrt{\mu} \Rdeux, \\
		\gradphi \cdot \pointal{V}{s} + \partialphi{r} \pointal{w}{s} &= \Rtrois, }
	\qquad \text{ in } S,
\end{equation}
where
\begin{equation}
\label{eqn:euler_quasilin:restes}
\sys{\Run &:= \commal{\diff}{\partialphi{t}}{V} + \epsilon [\diff , V \cdot] \gradphi V +  \epsilon [\diff ; w ,\partialphi{r} V] \\
&+ \epsilon \vec{U} \cdot \commal{\diff}{\gradphi[x,r]}{V} + [\diff, \frac{1}{\rhotot}] \gradphi P + \frac{1}{\rhotot}\commal{\diff}{\gradphi}{P} \\
&+ [\diff, \frac{g\rhob}{\rhotot}]\nabla \eta_0,\\% + \diff \Fun,\\
\sqrt{\mu}\Rdeux &:= \mu \commal{\diff}{\partialphi{t}}{w} + \epsilon \mu [\diff , \vec{U} \cdot] \gradphi[x,r] w \\
&+ \epsilon \mu \vec{U} \cdot \commal{\diff}{\gradphi[x,r]}{w}  + [\diff, \frac{1}{\rhotot}] \partialphi{r} P + \frac{1}{\rhotot} \commal{\diff}{\partialphi{r}}{P}\\
& - \delta \diff \frac{\rho}{\rhotot},\\% + \mu \diff \Fdeux,\\
\Rtrois &:= \commal{\diff}{\gradphi \cdot }{V} + \commal{\diff}{\partialphi{r}}{w}.% + \diff \Ftrois.
}
\end{equation}
The quasilinear system~\eqref{eqn:euler_quasilin} is completed with the boundary conditions
\begin{equation}
\label{eqn:euler_quasilin:bc}
\sys{\pointal{P}{s}_{|r=0} + g\rhob \point{\eta}{s}_0 &= \taylor \point{\eta}{s}_0, \\
	\partial_t \point{\eta}{s}_0 + \epsilon V_{|r=0} \cdot \nabla \point{\eta}{s}_0 + \epsilon \pointal{V}{s}_{|r=0} \cdot \nabla \eta_0 -\pointal{w}{s}_{|r=0} &= \Rquatre,\\
	\vec{N_b} \cdot \point{\vec{U}}{s}_{|r=-1} &= \Rcinq,\\
}
\end{equation}
where
\begin{equation}
\label{eqn:euler_quasilin:bc:restes}
\sys{\Rquatre &:= \epsilon [\diff;V_{|r=0}\cdot ,\nabla \eta_0] + \epsilon^2 \point{\eta}{s}_0 (\partialphi{r} V)_{|r=0} \cdot \nabla \eta_0 - \epsilon  \point{\eta}{s}_0 (\partialphi{r} w)_{|r=0} ,\\%+ \diff \Fquatre\\
	\Rcinq &:= [\diff,\vec{N_b}] \cdot \vec{U}_{|r=-1}.}
\end{equation}
Note that the commutator in $\Rquatre$ is a symmetric one, and that the other terms in $\Rquatre$ are here so that we make the good unknowns $\pointal{V}{s}$ and $\pointal{w}{s}$ appear on the left-hand side of~\eqref{eqn:euler_quasilin:bc}. Note also that the boundary condition on $\pointal{P}{s}$ in~\eqref{eqn:euler_quasilin:bc} stems from the definition~\eqref{eqn:alinhac:def} of Alinhac's good unknown $\pointal{P}{s}$ as well as the boundary condition~\eqref{eqn:euler_phi:bc} on the pressure and the definition~\eqref{eqn:taylor:def} of $\taylor$.\\
We also apply an operator of the form $\dot{\Lambda}^{s-k}\partial_r^k$ to the equation on $\rho$ in~\eqref{eqn:euler_phi}, to get
\begin{equation}
\label{eqn:euler_quasilin:rho}
\partialphi{t} \pointal{\rho}{s,k} + \epsilon \vec{U} \cdot \gradphi[x,r] \pointal{\rho}{s,k} =\frac{1}{\sqrt{\mu}}\Rdeuxetdemi,
\end{equation}
where $\pointal{\rho}{s,k}$ is Alinhac's good unknown
$$\pointal{\rho}{s,k} := \dot{\Lambda}^{s-k}\partial_r^k \rho - \frac{\dot{\Lambda}^{s-k}\partial_r^k(\etab + \epsilon \eta)}{\hb + \epsilon h} \partial_r \rho,$$
and where 
\begin{equation}
\label{eqn:euler_quasilin:rho:reste}
\frac{1}{\sqrt{\mu}}\Rdeuxetdemi :=  \commal{\dot{\Lambda}^{s-k}\partial_r^k}{\partialphi{t}}{\rho} + \epsilon [\dot{\Lambda}^{s-k}\partial_r^k, \vec{U}] \cdot \gradphi[x,r] \rho + \epsilon \vec{U} \cdot \commal{\dot{\Lambda}^{s-k}\partial_r^k}{\gradphi[x,r]}{\rho}.
\end{equation}
We also apply an operator of the form $\Lambda^{s-k}\partial_r^{k-1}$ with $0 \leq k-1 \leq s-1$ to the equation~\eqref{eqn:euler_phi:vort}, and get
\begin{equation}
\label{eqn:euler_quasilin:vort}
\begin{aligned}
%\partialphi{t} \point{\vort}{s-1,k-1} &+ \epsilon \vec{U} \cdot \gradphi[x,r] \point{\vort}{s-1,k-1} + \epsilon \vort^{[x]} \cdot \gradphi \begin{pmatrix} \point{V}{s-1,k-1} \\ \sqrt{\mu} \point{w}{s-1,k-1} \end{pmatrix} \\
%&+ \epsilon \vort^{[z]} \partialphi{r} \begin{pmatrix} \frac{1}{\sqrt{\mu}} \point{V}{s-1,k-1} \\ \point{w}{s-1,k-1} \end{pmatrix} = \Rsix,
\partialphi{t} \point{\vort}{s-1,k-1} &+ \epsilon \vec{U} \cdot \gradphi[x,r] \point{\vort}{s-1,k-1} = \Rsix,
\end{aligned}
\end{equation}
with
\begin{equation}
\label{eqn:euler_quasilin:vort:reste}
\begin{aligned}
%\Rsix &:=   \epsilon \vort^{[x]} \cdot \gradphi \begin{pmatrix} \point{V}{s-1,k-1} \\ \sqrt{\mu} \point{w}{s-1,k-1} \end{pmatrix} + \epsilon \vort^{[z]} \partialphi{r} \begin{pmatrix} \frac{1}{\sqrt{\mu}} \point{V}{s-1,k-1} \\ \point{w}{s-1,k-1} \end{pmatrix}+ [\Lambda^{s-k}\partial_r^{k-1}, \partialphi{t} + \vec{U} \cdot \gradphi[x,r]] \vort \\
%&+ [\Lambda^{s-k}\partial_r^{k-1}, \vort \cdot \gradphi[x,r] ] \vec{U} + \frac{\delta}{\sqrt{\mu}} \Lambda^{s-k}\partial_r^k \vec{F}. 
 %+ \commal{\Lambda^{s-k}\partial_r^{k-1}}{\gradphi[x,r] \times}{ \coo{\Fun \\\Fdeux}} + \gradphi[x,r] \times \coo{\Lambda^{s-k}\partial_r^{k-1} \Fun \\ \Lambda^{s-k}\partial_r^{k-1} \Fdeux} .
 \Rsix &:= [\Lambda^{s-k}\partial_r^{k-1}, \partialphi{t} + \epsilon \vec{U} \cdot \gradphi[x,r]] \vort - \epsilon \Lambda^{s-k}\partial_r^{k-1} \left(  \vort^{[x]} \cdot \gradphi \begin{pmatrix} V \\ \sqrt{\mu} w \end{pmatrix}
+ \vort^{[z]} \partialphi{r} \begin{pmatrix} \frac{1}{\sqrt{\mu}} V \\ w \end{pmatrix} \right) \\
&+ \frac{\delta}{\sqrt{\mu}} \Lambda^{s-k}\partial_r^k \vec{F}.
\end{aligned}
\end{equation}
We estimate the remainders $\Run, \dots , \Rsix$ in the following proposition.
\begin{proposition}
\label{prop:restes}
Let $s_0,s \in \N$, $s_0 > \frac{d+1}{2}$, $s \geq s_0 + 2$. Assume that there exists $T>0$ and $(V,w,\eta_0) \in C^0([0,T), (H^{s}(S))^{d+1} \times H^s(\R^d))$ satisfying~\eqref{eqn:euler_phi} as well as~\eqref{hyp:b},~\eqref{hyp:H},~\eqref{hyp:M}.
Then there exists $C > 0$ a constant depending only on $M$ such that
\begin{equation}
\label{eqn:restes:estimee}
\Vert (\Run,\Rdeux,\Rtrois,\Rdeuxetdemi,\Rsix)\Vert_{L^2}  + \vert \Rquatre \vert_{L^2} + \vert \Rcinq \vert_{H^{\frac12}} \leq  (\epsilon \vee \beta\vee (\delta/\sqrt{\mu})) C \E^{\frac12}.% + \Vert (\Fun,\sqrt{\mu}\Fdeux)\Vert_{H^s} + \vert \Fquatre \vert_{H^s}
\end{equation}
\end{proposition}
\begin{proof}
We only treat the terms in $\Run, \Rquatre,\Rcinq$ and $\Rdeuxetdemi $, the other ones can be treated the same way. For the first term in $\Run$, we use~\eqref{apdx:alinhac:R1} to write
$$\Vert \commal{\diff}{\partialphi{t}}{V} \Vert_{L^2} \leq C (\epsilon \vee \beta) \Vert \gradphi[t,x,r] V \Vert_{H^{s-1}}.$$
Using the product estimates~\eqref{apdx:eqn:pdt:algb} and~\eqref{apdx:eqn:pdt:infty}, we get
$$\Vert \gradphi[x,r] V \Vert_{H^{s-1}} \leq C (1+| \eta_0 |_{H^s})\Vert V \Vert_{H^{s}} \leq C \E^{\frac12},$$
where the last inequality stems from~\eqref{eqn:energy:equiv}. Using now~\eqref{eqn:euler_phi}, we can write
\begin{equation}
\label{eqn:quasilin:dt}
\begin{aligned}
\Vert \partialphi{t} V \Vert_{H^{s-1}} &= \Vert  \epsilon \vec{U} \cdot \gradphi[x,r] V + \frac{1}{\rhotot}\gradphi P + g \frac{\rhob}{\rhotot} \nabla \eta_0 \Vert_{H^{s-1}}\\
&\leq \Vert  \epsilon V \cdot \gradphi V\Vert_{H^{s-1}} + \epsilon \left\Vert \sqrt{\mu} w \left( \frac{1}{\sqrt{\mu}} \partialphi{r} V \right) \right\Vert_{H^{s-1}}\\
& + \Vert \frac{1}{\rhotot}\gradphi P \Vert_{H^{s-1}} + \vert g\frac{\rhob}{\rhotot} \nabla \eta_0 \vert_{H^{s-1}}.
\end{aligned}
\end{equation}
For the first term on the right-hand side of~\eqref{eqn:quasilin:dt}, we use the product estimate~\eqref{apdx:eqn:pdt:algb} as well as the definition~\eqref{eqn:gradphi:def} of $\gradphi$, to write
$$\Vert V \cdot \gradphi V\Vert_{H^{s-1}} \leq C \Vert V \Vert_{H^s} \leq C \E^{\frac12}.$$
Recall indeed that we allow $C$ to depend on an upperbound on $\Vert V \Vert_{H^s}$. For the second term in~\eqref{eqn:quasilin:dt}, we use the product estimate~\eqref{apdx:eqn:pdt:algb} and~\eqref{eqn:drV} to write
\begin{equation}
\label{eqn:restes:drV:utilisation}
\left\Vert \sqrt{\mu} w \left( \frac{1}{\sqrt{\mu}} \partialphi{r} V \right) \right\Vert_{H^{s-1}} \leq C \E^{\frac12}.
\end{equation}
For the third term in~\eqref{eqn:quasilin:dt}, we use the expression~\eqref{eqn:trick:compo} for the factor $1/(\rhotot)$ and the product estimate~\eqref{apdx:eqn:pdt:algb} to write
$$\Vert \frac{1}{\rhotot} \gradphi P \Vert_{H^{s-1}} \leq C (\frac{1}{\rhob} + \epsilon \delta \Vert \frac{\rho/\rhob}{\rhotot} \Vert_{H^{s-1}}) \Vert \gradphi P \Vert_{H^{s-1}}. $$
Using the composition estimate~\eqref{apdx:eqn:composition:gen} and the estimate~\eqref{eqn:pression:estimee}, we get
$$\Vert \frac{1}{\rhotot} \gradphi P \Vert_{H^{s-1}} \leq C \E^{\frac12}.$$
The last term in~\eqref{eqn:quasilin:dt} is treated like the third one and we omit it. For the second term of $\Run$, we use the commutator estimate~\eqref{apdx:eqn:commutator_sym:horizontal}, and the definition~\eqref{eqn:gradphi:def} of $\gradphi$ together with product estimate~\eqref{apdx:eqn:pdt:algb} to write
$$ \begin{aligned} \Vert [\diff , V \cdot] \gradphi V \Vert_{L^2} &\leq C \Vert V \Vert_{H^{s}} \Vert \gradphi V \Vert_{H^{s-1}} \\
& \leq C \E^{\frac12}. \end{aligned} $$
For the third term of $\Run$, we use the symmetric commutator estimate~\eqref{apdx:eqn:commutator_sym:horizontal} to write
$$ \begin{aligned} \Vert [\diff ; w ,\partialphi{r} V] \Vert_{L^2} &\leq C \Vert \sqrt{\mu}w \Vert_{H^{s-1}} \Vert \frac{1}{\sqrt{\mu}}\partialphi{r} V \Vert_{H^{s-1}}. \end{aligned} $$
We then use~\eqref{eqn:drV} to write
$$ \Vert [\diff ; w ,\partialphi{r} V] \Vert_{L^2} \leq C \E^{\frac12}.$$
The remaining terms in $\Run$ are treated as the first term in $\Run$. Combining all these estimates, we get
$$ \Vert \Run \Vert_{L^2} \leq C (\epsilon \vee \beta) \E^{\frac12}.$$% + \Vert \Fun \Vert_{H^s}.$$
For the first term of $\Rquatre$, we use the commutator estimate~\eqref{apdx:eqn:commutator:Rd:classic} to write
$$ \vert [\diff;V\cdot ,\nabla \eta_0]\vert_{L^2} \leq C \vert V_{|r=0}\vert_{H^{s-1}} \vert \nabla \eta_0 \vert_{H^{s-1}} .$$
Using the trace estimate~\eqref{apdx:eqn:trace}, we get
$$ \vert [\diff;V\cdot ,\nabla \eta_0]\vert_{L^2} \leq C \Vert V\Vert_{H^{s}} \vert  \eta_0 \vert_{H^{s}} \leq C \E^{\frac12}.$$
For the second term of $\Rquatre$, we use the Hölder inequality and the embedding~\eqref{apdx:eqn:embedding} to get
$$\vert \point{\eta}{s}_0 \partialphi{r} V \cdot \nabla \eta_0 \vert_{L^2} \leq \vert \point{\eta}{s}_0 \vert_{L^2} \vert \partialphi{r} V \vert_{L^2} \vert \nabla \eta_0 \vert_{L^{\infty}} \leq C \vert \eta_0 \vert_{H^s} \Vert V \Vert_{H^{s_0+1,2}} \vert \eta_0 \vert_{H^{s_0+1}} \leq C \E^{\frac12}.$$
The third term of $\Rquatre$ is  treated the same way and we eventually get
$$ \vert \Rquatre \vert_{L^2} \leq C (\epsilon \vee \beta) \E^{\frac12}.$$% + \vert \Fquatre \vert_{H^s}.$$
For the estimate on $\Rcinq$, we use the definition of $\vec{N_b}$ to write
$$[\diff,\vec{N_b}]\cdot \vec{U} = \left[\diff,\begin{pmatrix} -\beta \nabla b \\ 1 \end{pmatrix} \right] \cdot \vec{U} = -\beta[\diff, \nabla b] \cdot V.$$
We now use the commutator estimate~\eqref{apdx:eqn:commutator:Rd:sprime} with $s' = \frac12$ to write
$$\vert \beta [\diff,\nabla b] \cdot V_{|r=-1} \vert_{H^{\frac12}} \leq \beta C \vert V_{|r=-1} \vert_{H^{s-\frac12}} \leq \beta C \E,$$
where the last inequality results from the trace estimate~\eqref{apdx:eqn:trace}.\\
For $\Rdeuxetdemi$, we only treat the second term, as the other ones are treated the same way. We write, by the commutator estimate~\eqref{apdx:eqn:commutator:gen}, as $s\geq s_0+2$:
$$ \Vert\sqrt{\mu} [\dot{\Lambda}^{s-k} \partial_r^k, \vec{U}] \cdot \gradphi[x,r] \rho \Vert_{L^2} \leq C  \Vert \sqrt{\mu} \vec{U} \Vert_{H^{s,k}} \Vert \rho \Vert_{s,k} \leq C \E.$$
The terms in $\Rdeux$ and $\Rsix$ are treated the same way and we omit then. Not however that they yield a contribution of size $\frac{\delta}{\sqrt{\mu}}$, see the definitions~\eqref{eqn:euler_quasilin:restes} and~\eqref{eqn:euler_quasilin:vort:reste}.
%For the estimate on $\Rsix$, we only treat the first two terms, as the other ones are similar to the terms in $\Run$. Note that here:
%$$(\point{V}{s-1,k-1},\point{w}{s-1,k-1}) := \Lambda^{s-k}\partial_r^{k-1}(V,w),$$
%with $k-1 \leq s-1$. Thus
%$$\left\Vert \gradphi \begin{pmatrix} \point{V}{s-1,k-1} \\ \sqrt{\mu} \point{w}{s-1,k-1} \end{pmatrix} \right\Vert_{L^2} \leq C \Vert (V,\sqrt{\mu}w)\Vert_{H^s} \leq C \E.$$
%We can thus write, by the product estimate~\eqref{apdx:eqn:pdt:tame}:
%$$\begin{aligned}
%\left\Vert \vort^{[x]} \cdot \gradphi \begin{pmatrix} \point{V}{s-1,k-1} \\ \sqrt{\mu} \point{w}{s-1,k-1} \end{pmatrix} \right\Vert_{L^2} &\leq \Vert \vort \Vert_{H^{s_0+\frac12}} \Vert (V,\sqrt{\mu}w)\Vert_{H^{s}}\\
%&\leq \epsilon C \E.\end{aligned}$$
%For the second term in the definition of $\Rsix$, note that the relation~\eqref{eqn:w:trick} stemming from the incompressibility condition and~\eqref{eqn:drV} yield
%$$ \left \Vert \partialphi{r}\begin{pmatrix} \frac{1}{\sqrt{\mu}} \point{V}{s-1,k-1} \\ \point{w}{s-1,k-1} \end{pmatrix} \right\Vert_{L^2} \leq C \E.$$
%The product estimate~\eqref{apdx:eqn:pdt:tame} thus yields
%$$\epsilon \left\Vert \vort^{[z]} \partialphi{r} \begin{pmatrix} \frac{1}{\sqrt{\mu}} \point{V}{s-1,k-1} \\ \point{w}{s-1,k-1} \end{pmatrix} \right\Vert_{L^2} \leq C\epsilon  \E^{\frac12}.$$
\end{proof}
\subsection{$L^2$ estimates on quasilinear equations}
\label{subsection:quasilin:gen}
In this subsection we study quasilinear systems of the form~\eqref{eqn:euler_quasilin} and~\eqref{eqn:euler_quasilin:vort}, with general source terms $\Run,\Rdeux,\Rtrois,\Rquatre,\Rcinq,\Rdeuxetdemi,\Rsix$.\\
First, we consider the following system on the unknowns $\pointgen{V},\pointgen{w},\pointgen{\eta}_0$
\begin{equation}
\label{eqn:quasilin:gen}
\sys{ \partialphi{t} \pointgen{V} + \epsilon \vec{U} \cdot \gradphi[x,r] \pointgen{V} + \epsilon \pointgen{w} \partialphi{r} V  + \frac{1}{\rhob + \epsilon \delta \rho}\gradphi \pointgen{P} + g \frac{\rhob}{\rhob + \epsilon \delta \rho} \nabla \pointgen{\eta_0} &= \Run, \\
		\mu \left( \partialphi{t} \pointgen{w} + \epsilon \vec{U} \cdot \gradphi[x,r] \pointgen{w} \right) + \frac{1}{\rhob + \epsilon \delta \rho}\partialphi{r} \pointgen{P} &= \sqrt{\mu}\Rdeux, \\
		%\partialphi{t} \pointgen{\rho} +\epsilon \vec{U} \cdot \gradphi[x,r] \pointgen{\rho} = \frac{1}{\sqrt{\mu}} \Rdeuxetdemi,\\
		\gradphi \cdot \pointgen{V} + \partialphi{r} \pointgen{w} &= \Rtrois, }
	\qquad \text{ in } S.
\end{equation}
Here, $\Run, \Rdeux,\Rtrois$ are source terms. The quantity $\pointgen{P}$ is also considered as a source term, in the sense that we do not use the elliptic equation~\eqref{eqn:pression}, but rather keep the dependency in $\pointgen{P}$ in the estimates of the following Lemma~\ref{lemma:quasilin:gen}. We take $\vec{U} := (V,w)^T$, $\eta_0$ and $\rho$ a vector field and two scalar fields, respectively, that are coefficients, not related to the unknowns $\pointgen{\vec{U}},\pointgen{\eta}_0$  a priori. Recall that the operators $\gradphi[x,r], \partialphi{t}$ are defined from $\eta_0$ through~\eqref{eqn:phi:def},\eqref{eqn:phi:def:bary} and $\hb,h$ are defined through~\eqref{eqn:h:def}. We assume that $\vec{U}$ is divergence free
\begin{hyp}
\label{hyp:U:div}
\gradphi[x,r] \cdot \vec{U} = 0,
\end{hyp}and that it is tangential to the surface and bottom, that is
\begin{hyp}
\label{hyp:U:BC}
\begin{aligned}
\partial_t \eta_0 + \epsilon V_{|r=0} \cdot \nabla \eta_0 - w_{|r=0} &= 0,\\
\vec{U}_{|r=-1} \cdot \vec{N_b} &= 0.
\end{aligned}
\end{hyp}We also assume that there exists $\Mb > 0$ such that
\begin{hyp}
\label{hyp:Mb}
\Vert (V,\sqrt{w}) \Vert_{H^{s_0+2}} + \Vert \frac{1}{\sqrt{\mu}} \partialphi{r} V \Vert_{H^{s_0+1}} + \vert \eta_0 \vert_{H^{s_0+2}} \leq \Mb.
\end{hyp}We complete~\eqref{eqn:quasilin:gen} with the following boundary condition
\begin{equation}
\label{eqn:quasilin:gen:bc}
\sys{ \pointgen{P}_{|r=0} + g\rhob \pointgen{\eta}_0& = \taylorgen  \pointgen{\eta}_0,\\
\partial_t \pointgen{\eta}_0 + \epsilon V_{|r=0} \cdot \nabla \pointgen{\eta}_0 + \epsilon \pointgen{V}_{|r=0} \cdot \nabla \eta_0 -\pointgen{w}_{|r=0} &= \Rquatre,\\
	\vec{N_b} \cdot \pointgen{\vec{U}} &= \Rcinq,\\
}
\end{equation}
where $\Rquatre,\Rcinq$ are source terms. The quantity $\taylorgen $ is the Rayleigh-Taylor coefficient; see~\eqref{eqn:quasilin:taylor} below for  the derivation of the first boundary condition~\eqref{eqn:quasilin:gen:bc} in the quasilinearization process of~\eqref{eqn:euler_phi}.
We then consider the following transport equation
\begin{equation}
\label{eqn:quasilin:vort:gen}
\partialphi{t} \pointf + \epsilon \vec{U} \cdot \gradphi[x,r] \pointf = \Rsix,
\end{equation}
where $\Rsix$ is a source term. Note that~\eqref{eqn:quasilin:vort:gen} is the quasilinear structure of the equations~\eqref{eqn:euler_quasilin:rho} on the density and~\eqref{eqn:euler_quasilin:vort} on the vorticity.\\
We also assume that there exists a constant $c_*>0$ such that 
\begin{hyp}
\label{hyp:quasilin:taylor}
\taylorgen \geq c_* \qquad \text{ and } \qquad \vert(\taylorgen , \partial_t \taylorgen ) \vert_{L^{\infty}(\R^d)} \leq \Mb.
\end{hyp}
%This condition will correspond exactly to~\eqref{hyp:taylor} in the application of Lemma~\ref{lemma:quasilin:gen}, see Subsection~\ref{subsection:nrj}.
\begin{remark}
Note that in~\eqref{eqn:euler_quasilin} and~\eqref{eqn:euler_quasilin:bc}, the unknowns are $\pointgen{\vec{U}} = (\pointgen{V},\pointgen{w})^T$ and $\pointgen{\eta}_0$. The quantities $\vec{U} = (V,w)^T$ and $\eta_0$ play the role of general coefficients and are not related to the unknowns $\pointgen{\vec{U}},\pointgen {\eta}_0$ a priori.
% Although in the proof of Proposition~\ref{prop:energy} they are related (see Step 2), the situation in Section~\ref{section:cvce} is slightly different, see for instance the system~\eqref{eqn:euler_diff:quasilin}.
\end{remark}
\begin{lemma}
\label{lemma:quasilin:gen}
Let $s_0,s \in \N$, with $s_0 > \frac{d+1}{2}$ and $s \geq s_0+2$, and let $T > 0$. Let $(\vec{U},\eta_0) \in C^0([0,T), H^{s_0+2,3}(S)^{d+1} \times H^{s_0+2}(\R^d))$ satisfying~\eqref{hyp:b},~\eqref{hyp:H},~\eqref{hyp:Hb:reg},~\eqref{hyp:H:reg},~\eqref{hyp:U:div},~\eqref{hyp:U:BC},~\eqref{hyp:Mb},~\eqref{hyp:quasilin:taylor}. \\
Let $(\pointgen{V},\pointgen{w},\pointgen{\eta_0}) \in C^0([0,T),H^1(S)^{d+1} \times H^1(\R^d))$ be a solution of~\eqref{eqn:quasilin:gen} with boundary conditions~\eqref{eqn:quasilin:gen:bc}, of energy bounded by a constant $M$ as in~\eqref{hyp:M}. Then there exists $C$ depending only on $\Mb$ and $M$ such that
\begin{equation}
\label{eqn:quasilin:gen:energy:L2}
\begin{aligned}
&\frac{d}{dt} \left( \Vert \sqrt{(\hb + \epsilon h)(\rhob + \epsilon \delta \rho)} \pointgen{V}, \sqrt{\mu(\hb+ \epsilon h)(\rhob + \epsilon \delta \rho)} \pointgen{w}\Vert_{L^2}^2 + \vert \sqrt{\taylorgen } \pointgen{\eta}_0 \vert_{L^2}^2 \right)\\
& \leq C (\epsilon \vee \beta \vee \frac{\delta}{\mu} ) \left( \Vert \pointgen{V},\sqrt{\mu}\pointgen{w},\sqrt{\mu}\pointgen{\rho}\Vert_{L^2}^2 + \vert\pointgen{\eta}_0 \vert_{L^2}^2 \right) \\
&+ C \left(\Vert (\Run,\Rdeux,\Rtrois)\Vert_{L^2} + \vert (\Rquatre,\Rcinq)\vert_{L^2} \right) \left( \Vert \pointgen{V},\sqrt{\mu}\pointgen{w},\sqrt{\mu} \pointgen{\rho}\Vert_{L^2} + \vert\pointgen{\eta}_0 \vert_{L^2} \right)\\
 &+ C \Vert \pointgen{P} \Vert_{L^2} \Vert \Rtrois \Vert_{L^2} + C \vert \pointgen{P}_{r=-1} \vert_{H^{-\frac12}} \vert \Rcinq \vert_{H^{\frac12}}.
\end{aligned}
\end{equation}
If now $\pointf$  is a smooth solution of~\eqref{eqn:quasilin:vort:gen}, then
\begin{equation}
\label{eqn:quasilin:gen:vort:energy:L2}
\frac{d}{dt}\Vert \sqrt{\hb + \epsilon h} \pointf \Vert_{L^2}^2 \leq C \epsilon \Vert \pointf \Vert_{L^2}^2 + C \Vert \Rsix \Vert_{L^2} \Vert \pointf \Vert_{L^2}.
\end{equation}
\end{lemma}
\begin{proof}
We start with the estimate~\eqref{eqn:quasilin:gen:energy:L2}. 
We integrate the first two equations in~\eqref{eqn:quasilin:gen} and the second equation in~\eqref{eqn:quasilin:gen:bc} against $((\hb + \epsilon h)(\rhob + \epsilon \delta \rho)\pointgen{V}, (\hb + \epsilon h)(\rhob + \epsilon \delta \rho) \pointgen{w}, \taylorgen  \pointgen{\eta}_0)$, to get
\begin{equation}
\label{eqn:energy:V:1}
\begin{aligned}
\int_S & (\hb + \epsilon h)(\rhotot) \partialphi{t} \left( |\pointgen{V}|^2 + \mu |\pointgen{w}|^2 \right) & (i)\\
&+ \int_S \epsilon (\hb + \epsilon h)(\rhotot) \vec{U} \cdot \gradphi[x,r] |\pointgen{V}|^2 + \epsilon (\hb + \epsilon h)(\rhotot) \vec{U} \cdot \gradphi[x,r] |\sqrt{\mu}\pointgen{w}|^2 & (ii)\\
&+ \int_{R^d} \taylorgen  \frac{d}{dt}|\pointgen{\eta}_0|^2 + \epsilon \taylorgen  V_{|r=0} \cdot \nabla |\pointgen{\eta}_0|^2 & (iii)\\ 
&+ \int_S \epsilon (\hb + \epsilon h)(\rhotot) \pointgen{V}\pointgen{w} \partialphi{r} V  & (iv)\\
&+ \int_S (\hb + \epsilon h) \gradphi[x,r] \pointgen{P} \cdot \pointgen{\vec{U}} +  g\rhob (\hb + \epsilon h)\nabla \pointgen{\eta_0}\cdot \pointgen{V} & (v) \\
&+ \int_{\R^d} \taylorgen  (\pointgen{V}_{|r=0} \cdot \nabla \eta_0 - \pointgen{w}_{|r=0}) \pointgen{\eta}_0 & (vi)\\
& = \int_S (\hb + \epsilon h)(\rhotot) \Run \cdot \pointgen{V} + (\hb + \epsilon h)(\rhotot) \Rdeux \pointgen{w} + \int_{R^d} \taylorgen  \Rquatre \pointgen{\eta}_0;
\end{aligned} 
\end{equation}
here, we denote by $\pointgen{\vec{U}} := (\pointgen{V},\pointgen{w})^T$.
The terms on the right-hand side can be bounded from above by the Cauchy-Schwarz inequality so that we focus on the terms on the left-hand side.
