\end{aligned}
\end{equation}
for $f$ any smooth enough function defined on $[0,T]\times S$. Using~\eqref{eqn:quasilin:dtint} and the divergence-free condition~\eqref{hyp:U:div} and boundary condition~\eqref{hyp:U:BC} yields that the terms $(i),(ii)$ and $(iii)$ amount to the left-hand side of~\eqref{eqn:quasilin:gen:energy:L2}, up to remainder terms that are easily bounded by the product estimate~\eqref{apdx:eqn:pdt:tame}.\\

For the first term in $(iv)$ in~\eqref{eqn:energy:V:1}, we use Hölder inequality and the embedding of Lemma~\ref{apdx:lemma:embedding} to get
$$\begin{aligned}
\int_S \epsilon (\hb + \epsilon h) \pointgen{V}\pointgen{w} \partialphi{r} V &\leq \epsilon C \Vert \hb + \epsilon h \Vert_{L^{\infty}} \Vert \pointgen{V} \Vert_{L^2} \Vert \pointgen{w} \Vert_{L^2} \Vert \partialphi{r} V \Vert_{L^{\infty}}\\
&\leq \epsilon C \Vert \pointgen{V} \Vert_{L^2} \Vert \sqrt{\mu} \pointgen{w} \Vert_{L^2} \Vert\frac{1}{\sqrt{\mu}}  \partialphi{r} V \Vert_{H^{s_0}}\\
& \leq \epsilon C \Vert (\pointgen{V},\sqrt{\mu}\pointgen{w})\Vert_{L^2};
\end{aligned}$$
we crucially used the second term in~\eqref{hyp:Mb} to obtain a bound that is uniform in $\mu$.\\
Now note that the terms in $(v)$ can be written as
$$ \int_S (\hb + \epsilon h) \gradphi[x,r] \left( \pointgen{P} + g\rhob \pointgen{\eta}_0 \right) \cdot \pointgen{\vec{U}};$$
indeed, as $\pointgen{\eta}_0$ depends only on $t,x$ but not on $r$, the definition~\eqref{eqn:gradphi:def} of $\gradphi[x,r]$ yields $\gradphi[x,r] \pointgen{\eta}_0 = \begin{pmatrix} \nabla \pointgen{\eta}_0 \\ 0 \end{pmatrix}.$ We thus use the definition~\eqref{eqn:quasilin:gen:bc} of $\taylorgen $ and integrate by parts thanks to Lemma~\ref{apdx:lemma:IPP}, to write
\begin{equation}
\label{eqn:pression:ipp}
\begin{aligned}
\int_S (\hb + \epsilon h) \gradphi[x,r] \left( \pointgen{P} + g \rhob\pointgen{\eta_0}\right)  \cdot \pointgen{\vec{U}} &= \int_{r=0}\taylorgen \pointgen{\eta_0} \pointgen{\vec{U}} \cdot \vec{N}_s \\
&- \int_{r=-1} (\pointgen{P}_{|r=-1} + g \rhob\pointgen{\eta_0})  \pointgen{\vec{U}}_{|r=-1} \cdot \vec{N}_b \\
&- \int_S (\hb + \epsilon h)(\pointgen{P} + g \rhob\pointgen{\eta_0})  \gradphi[x,r] \cdot \pointgen{\vec{U}},
\end{aligned}
\end{equation}
where we used the notation $\vec{N}_s := \begin{pmatrix} -\epsilon \nabla \eta_0 \\ 1\end{pmatrix}$ and~\eqref{eqn:def:Nb} of $\vec{N}_b$. The third term on the right-hand side of~\eqref{eqn:pression:ipp} is bounded as one can use the divergence-free equation in~\eqref{eqn:quasilin:gen}, Cauchy-Schwarz inequality.\\
For the second term on the right-hand side of~\eqref{eqn:pression:ipp}, we use the boundary condition~\eqref{eqn:quasilin:gen:bc} to write

\begin{equation}
\label{eqn:temp:3}
\begin{aligned}
\left| \int_{r=-1} \left( \pointgen{P} + g \rhob \pointgen{\eta}_0 \right) \pointgen{\vec{U}} \cdot \vec{N}_b \right|  &\leq \left| \int_{r=-1}  g \rhob \pointgen{\eta}_0 \Rcinq \right| + \left| \int_{r=-1}  \pointgen{P} \Rcinq \right|\\
&\leq C \vert \pointgen{\eta}_0 \vert_{L^2} \vert \Rcinq \vert_{L^2} + C\vert \pointgen{P}_{r=-1} \vert_{H^{-\frac12}} \vert \Rcinq \vert_{H^{\frac12}}.
\end{aligned}
\end{equation}
For the first term on the right-hand side of~\eqref{eqn:pression:ipp}, recall that the boundary condition~\eqref{eqn:quasilin:gen:bc} on $\pointgen{P}_{|r=0}$ reads
$$ \pointgen{P}_{|r=0} + g\rhob  \pointgen{\eta}_0 = \taylorgen  \pointgen{\eta}_0,$$
where $\taylorgen $ is the Taylor coefficient. Therefore, this term and the term in $(vi)$ in~\eqref{eqn:energy:V:1} cancel out each other.\\
We eventually get the estimate~\eqref{eqn:quasilin:gen:energy:L2}. \\
For the equation~\eqref{eqn:quasilin:gen:vort:energy:L2}, we integrate~\eqref{eqn:quasilin:vort:gen} against $(\hb + \epsilon h)\pointf$ to get
\begin{equation}
\label{eqn:energy:vort:gen}
\begin{aligned}
&\int_S (\hb + \epsilon h) \partialphi{t} |\pointf|^2 + \epsilon (\hb + \epsilon h) \vec{U} \cdot \gradphi[x,r] |\pointf|^2\\
&= \int_S (\hb + \epsilon h)\Rsix \cdot\pointf.
\end{aligned}
\end{equation}
The right-hand side of~\eqref{eqn:energy:vort:gen} is bounded, by Cauchy-Schwarz inequality. The first and second terms of~\eqref{eqn:energy:vort:gen} are treated the same way as~\eqref{eqn:energy:V:1} (i) and~\eqref{eqn:energy:V:1} (ii) and we omit it.
\end{proof}
%\begin{remark}
%\label{rk:triche:gen}
%Notice that in the proof of Lemma~\ref{lemma:quasilin:gen}, we need $\pointgen{V},\pointgen{w},\pointgen{\eta}_0$ to be in $H^1$, for the energy estimate on the $L^2$ norm of the unknowns to hold. The reason is twofold: first, we need to define the traces of $\pointgen{V}$ and $\pointgen{w}$, for instance in~\eqref{eqn:energy:V:1}(vi). Second, the terms in~\eqref{eqn:quasilin:gen} and~\eqref{eqn:quasilin:vort:gen} need to be in $L^2$ so that~\eqref{eqn:energy:V:1} and~\eqref{eqn:energy:vort:gen} make sense. For instance, the term
%$$\int_S \vec{U} \cdot \gradphi \pointgen{V} \cdot \pointgen{V}$$
%is ill-defined if $\pointgen{V}$ is only in $L^2(S)$, as it would be the (integral of a) product of a distribution against a $L^2$ function. See Remark~\ref{rk:triche} for a note on this issue.
%\end{remark}
\subsection{Energy estimates}
\label{subsection:nrj}
%Suppose $\E \leq M$.
%\begin{lemma}
%There exists $C$ depending only on $M$ such that
%$$\frac{d}{dt} \Vert \vort \Vert_{L^2}^2 \leq C \Vert \vort \Vert_{L^2}^2$$
%\end{lemma}
We are now in a position to prove the energy estimates on the system~\eqref{eqn:euler_phi}. For this, we assume the existence of a solution of~\eqref{eqn:euler_phi} such that the energy defined in~\eqref{eqn:energy:def} is bounded from above by a constant $M>0$, i.e.~\eqref{hyp:M} holds.
\begin{proposition}
\label{prop:energy}
Let $s_0, s \in \N$, with $s_0 > \frac{d+1}{2}$, $s \geq s_0 + 2$. Assume that there exists $T>0$ and $(V,w,\rho,\eta_0) \in C^0([0,T),H^s(S)^{d+2} \times H^s(\R^d))$ a solution of~\eqref{eqn:euler_phi}, satisfying the initial condition~\eqref{eqn:euler_phi:ci} and boundary conditions~\eqref{eqn:euler_phi:bc}, as well as~\eqref{hyp:b},~\eqref{hyp:density},~\eqref{hyp:H},~\eqref{hyp:Hb:reg},~\eqref{hyp:H:reg},~\eqref{hyp:taylor},~\eqref{hyp:M}. Then there exists $C$ depending only on $M$ such that
$$\frac{d}{dt} \E \leq C(\epsilon \vee \beta \vee \frac{\delta}{\mu}) \E.$$% + \Vert F \Vert_{s}^{\frac12} \E^{\frac12}$$
\end{proposition}
\begin{remark}
\label{rk:tps_long:vort}
The energy estimate in Proposition~\ref{prop:energy} mainly relies on two main estimates. First, we derive in Step 2 an estimate on horizontal derivatives of $(V,w,\eta_0)$. The main advantage to use only horizontal derivatives in the operator $\dot{\Lambda}^{s}$ used to differentiate the system~\eqref{eqn:euler_phi} is that we can also differentiate the boundary conditions~\eqref{eqn:euler_phi:bc}. \\
The reason why we also derive an estimate on the vorticity in Step 3 is two-fold. First, it allows us to control the vertical derivatives of $V$ and $w$, that was not possible in Step 1, thanks to Lemma~\ref{lemma:energy:equiv}. Then, it allows us to propagate the condition $\partial_r V \sim \sqrt{\mu}$ (see for instance~\eqref{eqn:drV}).\\
Lastly, note that the estimate~\eqref{eqn:vort:estimee} yields a factor $\epsilon$ on the right-hand side. Thus, the presence of vorticity does not seem to be a major obstruction to get a large-time existence result for~\eqref{eqn:euler_phi}. The terms of order $\beta$ (responsible for the short-time result in the case $\delta = 0$ of no density variations) rather appear in Step 2, in the boundary term at the bottom resulting from the integration by parts for the pressure term  (see the term $(v)$ in~\eqref{eqn:energy:V:1} as well as the bound on $\Rcinq$ in~\eqref{eqn:restes:estimee}).
\end{remark}
\begin{proof}
In the proof we assume that $V,w,\rho,\eta_0$ are smooth enough so that the following computations make sense, see Remark~\ref{rk:triche}. \\
{\bf \underline{Step 1}: Control of the low regularity part $\Elow$:} \\
For the low-regularity part $\E_0$ in the definition~\eqref{eqn:energy:def} of $\E$, {\it let $s' := s_0+1$.} We first apply $\Lambda^{s'}$ to~\eqref{eqn:euler_phi}. We use extensively the notation $\point{f}{s'} := \Lambda^{s'} f$ for a quantity $f$ defined in the strip $S$ or on $\R^d$. We thus obtain an equation of the form 
\begin{equation}
\label{eqn:euler_quasilin_dummy}
\sys{
\partial_t \point{V}{s'} + g\rhob \nabla \point{\eta}{s'}_0&= R^0_1,\\
\mu \partial_t \point{w}{s'} &= \sqrt{\mu}R^0_2,\\
(\hb + \epsilon h)\gradphi \cdot \point{V}{s'} + \partial_r \point{w}{s'} &= R^0_4,
}
\end{equation}
with
\begin{equation}
\label{eqn:quasilin_dummy:restes}
\Vert (R^0_1,R^0_2,R^0_3,R^0_4) \Vert_{L^2} \leq C(\epsilon \vee \beta \frac{\delta}{\sqrt{\mu}}) \left(\Vert (V,\sqrt{\mu} w, \sqrt{\mu} \rho, \vort) \Vert_{H^{s_0+2}} +\vert \eta_0 \vert_{H^{s_0+2}}\right).% + \Vert \Fun,\sqrt{\mu} \Fdeux,\Fquatre)\Vert_{H^{s_0+\frac32}} + \vert\Ftrois\vert_{H^{s_0+\frac32}}\right).
\end{equation}
The estimate~\eqref{eqn:quasilin_dummy:restes} is proven as is~\eqref{eqn:restes:estimee} and we omit it.
We also apply $\Lambda^{s'}$ to the boundary conditions~\eqref{eqn:euler_phi:bc} to get
\begin{equation}
\label{eqn:quasilin_dummy:bc}
\partial_t \point{\eta}{s'}_0 - \point{w}{s} =R^0_3, \\
\end{equation}
with 
$$\vert R^0_3 \vert_{H^{s_0+1}} \leq C \epsilon \left( \Vert (V,\sqrt{\mu} w) \Vert_{H^{s_0+2}} +\vert \eta_0 \vert_{H^{s_0+2}}\right).$$% + \vert\Ftrois\vert_{H^{s_0+\frac32}}.$$
Note that there is a loss of derivatives in the above upper bound of the remainder terms, but as $s' = s_0+1$ and $s \geq s_0 +2$, we can still write
$$\Vert (R^0_1,R^0_2,R^0_4) \Vert_{L^2} + \vert R^0_3 \vert_{L^2}\leq C(\epsilon \vee \beta \vee \frac{\delta}{\sqrt{\mu}}) \E^{\frac12}.$$% + \Vert \Fun,\sqrt{\mu} \Fdeux)\Vert_{H^{s_0+\frac32}} + \vert\Ftrois\vert_{H^{s_0+\frac32}}.$$
However, note that we do not consider the terms $\nabla \point{\eta}{s'}_0$ and $-\point{w}{s'}$ in~\eqref{eqn:euler_quasilin_dummy} and~\eqref{eqn:quasilin_dummy:bc} as remainders, since they are not bounded from above by terms containing a factor $\epsilon \vee \beta\vee\frac{\delta}{\sqrt{\mu}}$. The system~\eqref{eqn:euler_quasilin_dummy} together with the boundary conditions~\eqref{eqn:quasilin_dummy:bc} are in the form of the quasilinear system~\eqref{eqn:quasilin:gen}. Using the estimate~\eqref{eqn:quasilin:gen:energy:L2} together with~\eqref{eqn:quasilin_dummy:restes}, we get
\begin{equation}
\label{eqn:temp:10}
\frac{d}{dt}\left( \Vert  V, \sqrt{\mu}w\Vert_{H^{s_0+1,0}} + \vert \eta_0 \vert_{H^{s_0+1}} \right) \leq C(\epsilon \vee \beta\vee\frac{\delta}{\mu})  \E.
\end{equation}
According to Lemma~\ref{lemma:quasilin:gen}, $C$ depends on an upperbound $\Mb > 0$ such that
$$\Vert (V,\sqrt{\mu}w) \Vert_{H^{s_0+2}} + \Vert \frac{1}{\sqrt{\mu}} \partialphi{r} V \Vert_{H^{s_0+1}} + \vert \eta_0 \vert_{H^{s_0+2}} \leq \Mb,$$
as well as the constants from Assumptions~\eqref{hyp:b},~\eqref{hyp:H}. The first and last terms are bounded from above by $M$ by~\eqref{hyp:M}. The second term is bounded from above, up to a constant, by $M$ thanks to~\eqref{eqn:drV}. Hence the constant $C$ in~\eqref{eqn:temp:10} depends only on $M$. 
To conclude on the estimate on the low regularity part $\Elow$ in the definition~\eqref{eqn:energy:def} of $\E$, we need to apply an operator of the form $\Lambda^{s'-k}\partial_r^k$ to the system~\eqref{eqn:euler_phi}, with $1\leq k \leq s'$. This yields a system of the form~\eqref{eqn:euler_quasilin_dummy}, where
$$ \point{\eta}{s',k}_0 := \Lambda^{s'-k} \partial_r^k \eta_0 = 0,$$
as $\eta_0$ only depends on the horizontal variable $x$ and $k \geq 1.$ The estimates~\eqref{eqn:quasilin_dummy:restes} still hold and using~\eqref{eqn:quasilin:gen:energy:L2} we eventually get
$$ \frac{d}{dt} \Vert (V,\sqrt{\mu}w) \Vert_{H^{s_0+1}} \leq C(\epsilon \vee \beta \vee \frac{\delta}{\mu}) \E.$$% + \Vert(\Fun,\frac{1}{\sqrt{\mu}} \Fdeux,\Ftrois,\Fquatre) \Vert_{H^{s_0+\frac32}}.$$ 
The estimate on the density $\rho$ using the equation~\eqref{eqn:euler_phi} is very similar and we omit it.\\

\noindent{\bf \underline{Step 2}: Control of the horizontal and vertical velocities:}
We now account for the term of main interest in the definition~\eqref{eqn:energy:def} of the energy, that is 
$$\Vert\sqrt{(\hb + \epsilon h)(\rhotot)}\pointal{V}{s},\sqrt{\mu(\hb + \epsilon h)(\rhotot)}\pointal{w}{s}, \sqrt{\mu(\hb + \epsilon h)} \rho\Vert_{L^2(S)}^2 + \vert \sqrt{\taylor} \point{\eta}{s}\vert_{L^2(\R^d)}^2.$$ Recall that applying $\dot{\Lambda}^{s}$ with $s \geq s_0+2$ to~\eqref{eqn:euler_phi} yields~\eqref{eqn:euler_quasilin}, where $\pointal{V}{s}, \pointal{w}{s}$ are defined through~\eqref{eqn:alinhac:def}. The system~\eqref{eqn:euler_quasilin} is of the form of~\eqref{eqn:quasilin:gen} with $(\pointgen{V},\pointgen{w},\pointgen{\rho},\pointgen{P},\pointgen{\eta}_0) := (\pointal{V}{s},\pointal{w}{s},\pointal{\rho}{s},\pointal{P}{s},\point{\eta}{s}_0)$. Note that because of the boundary condition on the pressure~\eqref{eqn:euler_phi:bc}, we can write:
$$\pointal{P}{s}_{|r=0} = \diff P_{|r=0} - \frac{\point{\eta}{s}_0}{\hb + \epsilon h} \partial_r P_{|r=0}.$$
Thus, the boundary condition on the pressure in~\eqref{eqn:quasilin:gen:bc} is satisfied, as
\begin{equation}
\label{eqn:quasilin:taylor}
\pointal{P}{s} + g \rhob\point{\eta}{s}_0 = (g\rhob - \frac{1}{\hb + \epsilon h} \partial_r P) \point{\eta}{s}_0 = \taylor \point{\eta}{s}_0,
\end{equation} 
where $\taylor$ is defined in~\eqref{eqn:taylor:def}, and corresponds to $\taylorgen $ in~\eqref{eqn:quasilin:gen:bc}. Then~\eqref{hyp:quasilin:taylor} is satisfied because of Lemma~\ref{lemma:taylor:dt} and~\eqref{hyp:taylor}. We can therefore use~\eqref{eqn:quasilin:gen:energy:L2} together with the estimate on the remainder terms~\eqref{eqn:restes:estimee} and on the pressure~\eqref{eqn:pression:estimee} to get
\begin{equation}
\label{eqn:temp:4}
\begin{aligned}
&\frac{d}{dt} \left(\Vert(\sqrt{(\hb + \epsilon h)(\rhotot)}\pointal{V}{s},\sqrt{\mu(\hb + \epsilon h)(\rhotot)}\pointal{w}{s}, \sqrt{\mu(\hb + \epsilon h)} \rho)\Vert_{L^2(S)} + \vert \sqrt{\taylor} \point{\eta}{s}\vert_{L^2(\R^d)}^2\right)\\
& \leq C (\epsilon \vee \beta \vee \frac{\delta}{\mu}) \E  + \vert \pointal{P}{s} \vert_{H^{-\frac12}} \vert \Rcinq \vert_{H^{\frac12}}. %+ \Vert \vec{F} \Vert_{s} \E^{\frac12}.
\end{aligned}
\end{equation}
It remains to estimate the last term in~\eqref{eqn:temp:4}. We write, thanks to the definition~\eqref{eqn:alinhac:def} of $\pointal{P}{s}$:
$$\vert \pointal{P}{s}_{|r=-1} \vert_{H^{-\frac12}} \leq \vert |D|\Lambda^{s-\frac32} P_{|r=-1} \vert_{L^2} + \vert \point{\eta}{s}_0 \partialphi{r} P_{|r=-1} \vert_{H^{-\frac12}}.$$
We use the product estimate~\eqref{apdx:eqn:pdt:s1s2} (with $s = - \frac12$, $s_1=-\frac12$, $s_2 = s_0+1$) for the second term, and the trace estimate~\eqref{apdx:eqn:trace} as well as the estimate~\eqref{eqn:pression:estimee} on the pressure to get
\begin{equation}
\label{eqn:temp:5}
\begin{aligned}
\vert \pointal{P}{s}_{|r=-1} \vert_{H^{-\frac12}} &\leq C \Vert \nabla P \Vert_{H^{s-1}}  + C \vert \eta_0 \vert_{H^{s-\frac12}} \Vert \partialphi{r} P \Vert_{H^{s_0+1}} \\
&\leq C \E^{\frac12}.
\end{aligned}
\end{equation}
Plugging~\eqref{eqn:temp:5} and the control on $\vert \Rcinq \vert_{H^{\frac12}}$ from~\eqref{eqn:restes:estimee} into~\eqref{eqn:temp:4} yield
$$\begin{aligned}
&\frac{d}{dt} \left(\Vert\sqrt{(\hb + \epsilon h)(\rhotot)}\pointal{V}{s},\sqrt{\mu(\hb + \epsilon h)(\rhotot)}\pointal{w}{s}, \sqrt{\mu(\hb + \epsilon h)} \rho\Vert_{L^2(S)}^2 + \vert \sqrt{\taylor} \point{\eta}{s})\vert_{L^2(\R^d)}^2\right) \\
&\leq C (\epsilon \vee \beta\vee\frac{\delta}{\mu}) \E.
\end{aligned}$$

\noindent{\bf \underline{Step 3}: Control of the vorticity and the density:}
For the estimate on $\vort$, take $0 \leq k-1 \leq s-1$ and define 
$$ \point{\vort}{s-1,k-1} := \Lambda^{s-k} \partial_r^{k-1} \vort.$$
Then $\point{\vort}{s-1,k-1}$ satisfies~\eqref{eqn:euler_quasilin:vort}, which is of the form of~\eqref{eqn:quasilin:vort:gen}. Using~\eqref{eqn:quasilin:gen:vort:energy:L2}, we thus get
$$\frac{d}{dt} \Vert \point{\vort}{s-1,k-1} \Vert_{L^2}^2 \leq \epsilon C \E.$$
Finally, summing the previous expression on $0 \leq k-1 \leq s-1$, we get
\begin{equation}
\label{eqn:vort:estimee}
\frac{d}{dt} \Vert \vort \Vert_{H^{s-1}}^2 \leq \epsilon C \E.
\end{equation}
The estimate on $\rho$ follows the same line: multiplying the whole quasilinear equation~\eqref{eqn:euler_quasilin:rho} by $\mu$, we get an equation of the form~\eqref{eqn:quasilin:vort:gen} with no singular term in $\mu$. This concludes the proof.
\end{proof}
\begin{remark}
\label{rk:triche}
The unknowns $V,w,\rho,\eta_0$ are in $H^s$, so that $\pointal{V}{s},\pointal{w}{s},\pointal{\rho}{s},\point{\eta}{s}_0,\point{\vort}{s-1,k-1}$ defined in Step 2 and Step 3 are in $L^2$, but not in $H^1$, and this is not enough regularity to apply Lemma~\ref{lemma:quasilin:gen}. This is solved by following the standard smoothing strategy used for instance in~\cite[Lemma 2.38]{Lannes2013}, namely applying smoothing operators, both in the horizontal direction $x$ and the vertical direction $r$. For the horizontal direction, one should replace $\Lambda^s$ by $\chi(\iota  \Lambda) \Lambda^s$ in the proof of Proposition~\ref{prop:energy}, with $\chi$ a cutoff and $\iota  > 0$. Using that fact that the flow is tangent to the boundaries, one can also define a smoothing operator in the vertical direction, see the operator $K^{\iota }(a \partial_z)$ in~\cite[Lemma 4.8]{Castro2014a}. With $\iota  > 0$, the unknowns are now sufficiently regular so that Lemma~\ref{lemma:quasilin:gen} can be applied, and the estimates are independent of $\iota $. Taking the limit $\iota  \to 0$ yields the estimate of Proposition~\ref{prop:energy}.
\end{remark}
\subsection{Existence scheme}
\label{subsection:scheme}
In this subsection we state and prove Theorem~\ref{thm:euler_phi}, which is the main result of this paper. Given the energy estimate from Proposition~\ref{prop:energy}, it only remains to construct a solution, from a sequence of suitable approximate solutions. Because of the presence of boundaries, and particularly  a free-surface, this is not completely standard.\\
Let $s_0, s\in \N$, with $s_0>\frac{d+1}{2}$, $s \geq s_0+2$. Let $(V_{\ini},w_{\ini},\rho_{\ini}, (\eta_0)_{\ini}) \in (H^{s})^{d+2}(S) \times H^s(\R^d)$, more precisely we assume that there exists $M_{\ini} > 0$ such that
\begin{hyp}
\label{hyp:Mini}
\Vert V_{\ini}, \sqrt{\mu} w_{\ini},\sqrt{\mu} \rho_{\ini}\Vert_{H^s(S_r)} + \vert (\eta_0)_{\ini}\vert_{H^s(\R^d)} + \Vert (\vort)_{\ini} \Vert_{H^{s-1}(S)} \leq M_{\ini},
\end{hyp}where $(\vort)_{\ini}$ is defined through~\eqref{eqn:vort:def}. We have the following theorem.
\begin{theorem}
\label{thm:euler_phi}
Let $\epsilon,\beta,\delta \in [0,1]$, $\mu \in (0,1]$. Let $M_{\ini} >0$ and $(V_{\ini},w_{\ini},\rho_{\ini}, (\eta_0)_{\ini}) \in (H^{s})^{d+1}(S) \times H^s(\R^d)$ satisfying~\eqref{hyp:b},~\eqref{hyp:H},~\eqref{hyp:taylor},~\eqref{hyp:Mini}, the first and third boundary conditions in~\eqref{eqn:euler_phi:bc} and the incompressibility condition in~\eqref{eqn:euler_phi}.
%Let $\Fun,\Fdeux,\Ftrois,\Fquatre$ be source terms satisfying~\eqref{hyp:source}. Assume that there exists $T > 0$ such that~\eqref{hyp:energy_estimate} holds. 
Then there exists $T > 0$ depending only on $d,s_0,s,M_{\ini}$ such that the following holds. There exists $T_{\max} > 0$ and a unique solution $(V,w,\rho,\eta_0)$ to~\eqref{eqn:euler_phi} in $C^0([0,T_{\max}),H^{s}(S)^{d+2} \times H^s(\R^d))$ satisfying the boundary conditions~\eqref{eqn:euler_phi:bc} and the initial condition~\eqref{eqn:euler_phi:ci}, and we have the lower bound
\begin{equation}
\label{eqn:T:lowerbound}
T_{\max} \geq \frac{T}{\epsilon \vee \beta \vee \frac{\delta}{\mu}}.
\end{equation}
Moreover, if $T_{\max}$ is finite, we can write
\begin{equation}
\label{eqn:critere_explosion}
\begin{aligned}
 &\limsup\limits_{t \to T_{\max}} \Vert (V, \sqrt{\mu} w,\sqrt{\mu} \rho)(t,\cdot)\Vert_{H^s(S_r)} + \vert \eta_0(t,\cdot)\vert_{H^s(\R^d)} + \Vert \vort(t,\cdot) \Vert_{H^{s-1}(S)} = \infty, \\
%& \inf\limits_{(x,r)\in S} (1-\beta b(x) + \epsilon \eta_0(t,x,r)) \underset{t\to T_{\max}}{\longrightarrow} 0.
\text{or } \quad & \liminf\limits_{t \to T_{\max}} \inf\limits_{(x,r)\in S} \taylor = 0.\\
%\text{or } \quad & \liminf\limits_{t \to T_{\max}} \inf\limits_{(x,r)\in S} (\rhob + \epsilon \delta \rho) = 0.
\end{aligned}
\end{equation}
\end{theorem}
\begin{remark}
The blow-up criterion~\eqref{eqn:critere_explosion} states that either the norm of the solutions blows up, or a hyperbolicity criterion (related to $\taylor$) fails when $t \to T_{\max}$. One might expect the alternatives $\liminf\limits_{t \to T_{\max}} \inf\limits_{(x,r)\in S} (1 - \beta b + \epsilon \eta_0) =0$ and $\liminf\limits_{t \to T_{\max}} \inf\limits_{(x,r)\in S} (\rhob + \epsilon \delta \rho) = 0$ to appear in the blow-up criterion, as they are needed to derive the energy estimates from Proposition~\ref{prop:energy}. We show however at the end of the following proof that as long as the solution $(V,w)$ remains bounded in Sobolev norms, then the water height $1 - \beta b + \epsilon \eta_0$ and the density $\rhob + \epsilon \delta \rho$ cannot go to $0$. 
\end{remark}
\begin{proof}
The proof adapts arguments from~\cite{Fradin2024} to the free surface case and is organized as follows. In Step $1$ we define some technical tools, in particular the semi-Lagrangian coordinates. These are used in Steps $2$ and $3$ to construct a solution to~\eqref{eqn:euler_phi} on a short time interval using the standard strategy from~\cite{AJMajda2002}, as the initial boundary value problem~\eqref{eqn:euler_phi} becomes an initial value problem, see~\eqref{eqn:euler:slag}. More precisely, in Step $2$ we mollify the system~\eqref{eqn:euler:slag} into~\eqref{eqn:moll:123} with three regularization parameters $\iota_1,\iota_2,\iota_3$ and in Step $3$ we show that the gradient of the pressure defined from the unknowns in~\eqref{eqn:moll:123} is Lipschitz continuous with respect to these unknowns, so that~\eqref{eqn:moll:123} is a system of ODEs. A standard compactness argument yields a solution to~\eqref{eqn:moll:123}. In Step $4$ we derive several energy estimates to send the regularization parameters $\iota_1,\iota_2,\iota_3$ to 0, in that order. The reason why we need several parameters is that the energy estimate of Proposition~\ref{prop:energy} does not hold for the regularized system~\eqref{eqn:moll:123}. We thus use other, less accurate energy estimates that allow us to send $\iota_1,\iota_2$ to $0$ in Steps $4.1,4.2$ and only then we use the energy estimate of Proposition~\ref{prop:energy} in Step $4.3$ to send $\iota_3$ to $0$. In Step $5$ we show the blow-up criterion~\eqref{eqn:critere_explosion}.\\

We start with the local existence of a solution to~\eqref{eqn:euler_phi}. At this stage, we do not keep track of the dependency in the parameters $\beta,\mu,\epsilon,\delta$, so that we set them to $1$ to simplify the notations.\\

\noindent{\bf \underline{Step 1:} Technical tools} \saut
We use a different coordinate system in Steps $2$ and $3$ to prove the local existence part, namely semi-Lagrangian coordinates. To this end, we start from the system~\eqref{eqn:euler_euleriennes} in Eulerian coordinates. Let $\eta_{\ini} : S \to \R$, be such that $(x,r) \mapsto r + \eta_{\ini}(x,r)$ is a diffeomorphism that sends $\Omega_0$ to $S$, where $\Omega_0$ is defined through~\eqref{eqn:def:Omegat}, for instance of the form~\eqref{eqn:phi:def:bary}. We now {\it define } $\eta: [0,T]\times S \to \R$ as a solution of
\begin{equation}
\label{eqn:eta:def}
\partial_t \eta + V \cdot \nabla \eta - w = 0 \qquad \text{ in } [0,T] \times S,
\end{equation}
with initial condition
\begin{equation}
\label{eqn:eta:ci}
\eta_{|t=0} = \eta_{\ini}.
\end{equation}
We define $\varphi$ from $\eta$ through 
\begin{equation}
\label{eqn:phi:def:slag}
\varphi : \begin{aligned} S &\to \Omega_t \\ (x,r) &\mapsto (x,(r + \eta)(t,x,r)) \end{aligned}
\end{equation}
and $\partialphi{t}$,$\partialphi{r}$,$\gradphi$ through~\eqref{eqn:gradphi:def}. Note that the free-surface $\eta_0$ is nothing but the trace of $\eta$ evaluated at $r=0$.\\
This coordinate system enjoys a semi-Lagrangian property, namely 
\begin{equation}
\label{eqn:slag}
\partialphi{t} + \vec{U} \cdot \gradphi[x,r] = \partial_t + V \cdot \nabla.
\end{equation}
We now write the Euler equations in this system of coordinates, coupled with~\eqref{eqn:eta:def}, namely
\begin{equation}
\label{eqn:euler:slag}
\sys{
\partial_t \vec{U} + V \cdot \nabla \vec{U} + \frac{1}{\rhob +  \rho} \gradphi[x,r]P + \frac{g\rhob}{\rhob + \rho}\nabla_{x,r} \eta_0 +  \frac{g\rho}{\rhotot} \vec{e_z}&= 0,\\
\partial_t \rho + V \cdot \nabla_x \rho &= 0,\\
\partial_t \eta + V \cdot \nabla \eta - w &= 0, \\
\gradphi[x,r] \cdot \vec{U} &= 0,}
\end{equation}
where $\vec{e_z} := (0,0,1)^T$ and recall that $\eta_0$ is independent of $r$ so that $\partial_r \eta_0 = 0$.
This is completed with the boundary conditions~\eqref{eqn:euler_euleriennes:bc} and the initial condition~\eqref{eqn:euler_euleriennes:ci} for $\vec{U}$ as well as~\eqref{eqn:eta:ci} for $\eta$.\\
Note that there are no vertical derivatives in~\eqref{eqn:euler:slag} (except for the incompressibility constraint and its associted Lagrange multiplier $P$, but we show how to treat these in Step $3$), so that the associated Cauchy problem is not an initial boundary value problem. Thanks to this remark, we only need to define mollification operators with respect to the horizontal coordinate. Following~\cite{AJMajda2002}, let $\mathcal{J}_{\iota}$ for any $\iota > 0$ the mollification operator defined by the product with a smooth cutoff function in the horizontal Fourier space (see ~\cite{AJMajda2002}), to regularize $\nabla_x$. It satisfies the following properties, see~\cite[Lemma 3.5]{AJMajda2002}.
\begin{lemma}
\label{lemma:moll}
Let $s,s' \in \R$, $f \in H^{s'}(\R^d)$. For $\iota > 0$, we can write
\begin{equation}
\label{eqn:moll:borne}
\vert \mathcal{J}_{\iota} f \vert_{H^s(\R^d)} \leq C_{\iota,s,s'} \vert f \vert_{H^{s'}(\R^d)},
\end{equation}
for some constant $ C_{\iota,s,s'}$.\\
For $\iota' > 0$, we also have 
\begin{equation}
\label{eqn:moll:lip}
\vert (\mathcal{J}_{\iota} - \mathcal{J}_{\iota'})f\vert_{H^{s'-1}} \leq C |\iota - \iota'| \vert f \vert_{H^{s'}},
\end{equation}
where $C$ does not depend on $\iota$ nor $\iota'$.
\end{lemma}

\noindent{\bf \underline{Step 2:} The mollified system} \saut
We now introduce the following mollified system
\begin{equation}
\tag{\ensuremath{E_{\iota}}}
\label{eqn:moll:123}
\sys{ \partial_t \vec{U} + \mathcal{J}_{\iota_1} \left[ \mathcal{J}_{\iota_2}V \cdot \nabla_x \mathcal{J}_{\iota_1} \vec{U} \right]+ \frac{1}{\rhob + \rho}\gradphi[x,r] P  + \frac{g\rhob}{\rhob + \rho} \mathcal{J}_{\iota_2} \nabla_{x,r} \eta_0 + g \frac{\rho}{\rhob + \rho} \vec{e_z}& = \frac{\iota_3}{\rhob + \rho} \mathcal{J}_{\iota_2} \gradphi[x,r] \Lambda \eta_0^h, \\
\partial_t \rho  + \mathcal{J}_{\iota_1} \left[ \mathcal{J}_{\iota_2}V \cdot \nabla_x \mathcal{J}_{\iota_1} \rho \right] &= 0,\\
		\partial_t \eta + \mathcal{J}_{\iota_1} \left[ \mathcal{J}_{\iota_2}V \cdot \nabla_x \mathcal{J}_{\iota_1} \eta \right] - \reg{2}w &= 0,}
\end{equation}
where $\eta_0^h$ is the harmonic extension of $\eta_0$ to the strip $S$. The benefit from taking a harmonic extension is the following property (see for instance~\cite[Prop. 2.36]{Lannes2013}):
\begin{lemma}
If $\eta_0 \in H^{s}(\R^d)$ for some $s \geq s_0+1$, then $\Lambda^{s-\frac12} \nabla_{x,z} \eta_0^h \in L^2(S)$.
\end{lemma}This set of equations is completed with the initial conditions
\begin{equation}
\label{eqn:moll:CI}\vec{U}_{|t=0} = \vec{U}_{\ini}, \qquad 
	\rho_{|t=0} = \rho_{\ini}, \qquad 
		\eta_{t=0} = \eta_{\ini}.
\end{equation}
We define the pressure $P$ through the elliptic equation
\begin{equation}
\label{eqn:existence:elliptic}
\gradphi[x,r] \cdot \frac{1}{\rhob + \rho}\gradphi[x,r] P = - \partial_i^{\varphi} \reg{2}\vec{U}_j  \partial_j^{\varphi} \vec{U}_i - \reg{2} \Delta_x \eta_0 - \partialphi{r} \frac{\rho}{\rhob+\rho} + \iota_3 \gradphi[x,r] \cdot \reg{2} \gradphi[x,r] \Lambda \eta_0^h,
\end{equation}
completed with the boundary condition at the top
\begin{equation}
\label{eqn:existence:elliptic:bc:top}
P = 0 \qquad \text{ at } r=0,
\end{equation}
and at the bottom
\begin{equation}
\label{eqn:existence:elliptic:bc:bot}
\vec{N_b} \cdot \gradphi[x,r] P = - \reg{2} \vec{N_b} \cdot (V \cdot \nabla_x \vec{U})  - \frac{\rho}{\rhob+\rho} + \iota_3 \vec{N_b} \cdot \reg{2} \gradphi[x,r] \Lambda \eta_0^h \qquad \text{ at } r=-1,
\end{equation}
where $\vec{N}_b$ given by~\eqref{eqn:def:Nb} is the upward normal at the bottom.
% Note that the right-hand side of~\eqref{eqn:existence:elliptic:bc:bot} comes from taking the scalar product of~\eqref{eqn:euler:slag} with $\vec{N_b}$, taking the trace at the bottom and using $\vec{n} \cdot \vec{U} = 0$ at the bottom, and $\partial^2 b$ denotes the matrix $(\partial_i \partial_j b)_{(i,j) \in \{1,\dots,d\}^2}$.\\


\noindent{\bf \underline{Step 3:} $(\vec{U},\eta) \mapsto \gradphi[x,r] P $ is well-defined and Lipschitz continuous} \saut
Recall that $s \geq s_0+2$. The following lemma states that $(\vec{U},\eta) \mapsto \gradphi[x,r] P $ is well-defined and a Lipschitz continuous operator from $H^s(S)$ to itself, although not uniformly in the regularization parameters $\iota_2$ and $\iota_3$.
\begin{lemma}
\label{lemma:moll:pression}
Under the assumptions and notations of Theorem~\ref{thm:euler_phi},~\eqref{eqn:existence:elliptic} completed with~\eqref{eqn:existence:elliptic:bc:top} and~\eqref{eqn:existence:elliptic:bc:bot} has a unique solution $P$ and there exists $C_{\iota_2,\iota_3}>0$ depending only on $M$ and $\iota_2,\iota_3$ such that
\begin{equation}
\label{eqn:existence:elliptic:borne}
\Vert P \Vert_{L^2} + \Vert \gradphi[x,r] P\Vert_{H^s} \leq C_{\iota_2,\iota_3} \Vert (\vec{U},\rho,\eta)\Vert_{H^s}.
\end{equation}
We also have the bound, with $C$ independent of $\iota_2$ and $\iota_3$:
\begin{equation}
\label{eqn:existence:elliptic:borne:unif}
\Vert P \Vert_{L^2} + \Vert \gradphi[x,r] P\Vert_{H^s} \leq C \Vert (\vec{U},\eta)\Vert_{H^{s+1}}+ C \iota_3 \vert \eta_0\vert_{H^{s+\frac32}}.
\end{equation}
Moreover, if $P^{(1)}$ and $P^{(2)}$ are defined from $(\vec{U}^{(1)},\rho^{(1)},\eta^{(1)})$ and $(\vec{U}^{(2)},\rho^{(2)},\eta^{(2)})$ through~\eqref{eqn:existence:elliptic}, then
\begin{equation}
\label{eqn:existence:elliptic:lip}
\Vert P^{(1)} - P^{(2)} \Vert_{L^2} + \Vert \gradphi[x,r] (P^{(1)} - P^{(2)}) \Vert_{H^s} \leq C_{\iota_2,\iota_3} \Vert (\vec{U}^{(1)}-\vec{U}^{(2)},\rho^{(1)}-\rho^{(2)},\eta^{(1)}-\eta^{(2)})\Vert_{H^s}.
\end{equation}
\end{lemma}
\begin{proof}
Using standard elliptic estimates (see for instance~\cite[Lemma 2.38]{Lannes2013} or~\cite[Lemma 4]{Desjardins2019}), we get
\begin{equation}
\label{eqn:pression:lowreg}
\Vert P\Vert_{L^2} + \Vert \gradphi[x,r] P\Vert_{H^{s_0+1}} \leq C \Vert (\vec{U},\rho,\eta)\Vert_{H^{s_0+2}}.
\end{equation}
Using~\cite[Proposition 2.6]{Fradin2024} and~\eqref{eqn:pression:lowreg}, we get~\eqref{eqn:existence:elliptic:borne}.\\
The strategy to obtain~\eqref{eqn:existence:elliptic:lip} relies on Alinhac's good unknown and~\cite[Proposition 2.6]{Fradin2024}. This is detailed in~\cite[Step 1 of the proof of Prop. 4.1]{Fradin2024} and we omit it.
\end{proof}
Therefore, the system~\eqref{eqn:moll:123} has an ODE structure with a Lipschitz source term, thanks to Lemma~\ref{lemma:moll:pression}, and as such, admits a unique solution on a time interval $[0,T_{\iota_1,\iota_2,\iota_3}]$ with respect to the initial data given by~\eqref{eqn:moll:CI}. \\

\noindent{\bf\underline{Step 4.1:} Sending $\iota_1$ to $0$} \saut
The time of existence $T_{\iota_1,\iota_2,\iota_3}$ given in Step $3$ is not independent of the regularization parameters. A standard energy estimate shows that $T_{\iota_1,\iota_2,\iota_3}$ is bounded from below by a constant independent of $\iota_1$, see for instance~\cite[Section 3.2]{AJMajda2002}.\\
\begin{remark}
\label{rk:iota1}
The energy estimate from Proposition~\ref{prop:energy} does not apply here: the regularization operators $\reg{1}$ forbid to use the identity~\eqref{eqn:slag}.  In particular, the divergence-free condition is not propagated and the use of Alinhac's good unknown is not possible. We thus use a more standard energy estimate to show that $t_{\iota_1,\iota_2,\iota_3}$ is independent of $\iota_1$. This energy estimate is, however, not enough to conclude the independence with respect to the other regularization parameters.
\end{remark}
\noindent{\bf \underline{Step 4.2:} Incompressibility and sending $\iota_2$ to $0$} \saut
We now have a solution to the system~\eqref{eqn:moll:123} with $\iota_1 = 0$. 
Thanks to the equation on $\eta$ in~\eqref{eqn:moll:123} with $\iota_1=0$, we can write~\eqref{eqn:moll:123} with $\iota_1=0$ and without the semi-Lagrangian property~\eqref{eqn:slag}; this reads
\begin{equation}
\label{eqn:moll:23}
\sys{ \partialphi{t} \vec{U} + \mathcal{J}_{\iota_2} V \cdot \gradphi \vec{U} + \reg{2}w \partialphi{r} \vec{U} + \frac{1}{\rhob + \rho}\gradphi[x,r] P  + \frac{g\rhob}{\rhob + \rho} \mathcal{J}_{\iota_2} \nabla_{x,r} \eta_0 + g \frac{\rho}{\rhob + \rho} \vec{e_z}& = \frac{\iota_3}{\rhob + \rho} \mathcal{J}_{\iota_2} \gradphi[x,r] \Lambda \eta_0^h, \\
\partialphi{t} \rho  + \mathcal{J}_{\iota_2}V \cdot \gradphi \rho  + \reg{2}w \partialphi{r} \rho &= 0,\\
\partial_t \eta + \reg{2} V \cdot \nabla_x \eta - \reg{2} w &= 0,}
\end{equation}
with the kinematic equation for the surface
\begin{equation}
\label{eqn:moll:23:eta}
\partial_t \eta_0 + \mathcal{J}_{\iota_2}V_{|r=0} \cdot \nabla_x \eta_0  - \reg{2}w_{|r=0} = 0.
\end{equation}
Applying $\gradphi[x,r] \cdot$ to the equations on $V$ and $w$ in~\eqref{eqn:moll:23} and using the equation~\eqref{eqn:existence:elliptic} satisfied by the pressure, we can see that $\gradphi[x,r] \cdot \vec{U}$ satisfies a transport equation at velocity $\reg{2} \vec{U}$. Thus, as the initial condition $(V_{\ini},w_{\ini})^T$ is divergence-free, so is the solution to~\eqref{eqn:moll:23} that we constructed in Step 4.1.\\

We now perform an energy estimate similar to Proposition~\ref{prop:energy}, in order to show that $T_{\iota_2,\iota_3}$ is independent of $\iota_2$. More precisely, we apply $\dot{\Lambda}^{s}$ with $s\geq s_0+2$ to~\eqref{eqn:moll:23} and get the following equations in $S$
\begin{equation}
\label{eqn:moll:23:quasilin}
\sys{ \partialphi{t} \pointal{\vec{U}}{s} + \mathcal{J}_{\iota_2} V \cdot \gradphi \pointal{\vec{U}}{s} + w \partialphi{r} \pointal{\vec{U}}{s} + \frac{1}{\rhob + \rho}\gradphi[x,r] \pointal{P}{s}  + g \rhob \mathcal{J}_{\iota_2} \nabla_{x,r} \pointal{\eta_0}{s} & \approx \frac{\iota_3}{\rhob + \rho} \mathcal{J}_{\iota_2} \gradphi[x,r] \Lambda (\pointal{\eta_0}{s})^h, \\
\partialphi{t} \pointal{\rho}{s}  + \mathcal{J}_{\iota_2}V \cdot \gradphi \pointal{\rho}{s} + w \partialphi{r} \pointal{\rho}{s} &\approx 0,\\
\partial_t \pointal{\eta}{s} + \reg{2} V \cdot \nabla_x \pointal{\eta}{s} & \approx 0,}
\end{equation}
\begin{equation}
\label{eqn:moll:23:quasilin:eta0}
\partial_t \pointal{\eta_0}{s} + \reg{2} V_{|r=0} \cdot \nabla \pointal{\eta_0}{s} + \reg{2} \pointal{V}{s}_{|r=0} \cdot \nabla \eta_0 - \reg{2} \pointal{w}{s}_{|r=0} \approx 0,
\end{equation}
where the symbol $\approx$ means that remainder terms are omitted. Those remainder terms are of the form of the ones in~\eqref{eqn:euler_quasilin:restes} with additional but harmless terms stemming from commutators with $\reg{2}$ and the dispersive regularization $\iota_3 \gradphi[x,r] \Lambda \eta_0^h$. Note that we use Alinhac's good unknown here. We now define the following energy functional $\tilde{\mathcal{E}}_s$ defined as
\begin{equation}
\label{eqn:nrj:def:moll}
 \left\Vert\left(\sqrt{(\hb +  h)(\rhob + \rho)}\pointal{V}{s},\sqrt{ (\hb + h)(\rhob +\rho)}\pointal{w}{s}, \sqrt{(\hb + h)} \pointal{\rho}{s}\right)\right\Vert_{L^2(S)}^2 + \vert (g\rhob+\iota_3 \Lambda^{\frac12}) \pointal{\eta}{s}_0\vert_{L^2(\R^d)}^2 + \Vert \vec{\omega} \Vert_{H^{s-1}(S)}^2.
\end{equation}
Note that because of the additional dispersion term $\frac{\iota_3}{\rhob + \rho} \mathcal{J}_{\iota_2} \gradphi[x,r] \Lambda (\pointal{\eta_0}{s})^h$~\eqref{eqn:moll:23:quasilin}, we control an extra half-derivative on $\eta_0$ compared to Proposition~\ref{prop:energy}.
Following the same steps as the proofs of Propositions~\ref{prop:energy} and~\ref{prop:restes}, we can write
\begin{equation}
\label{eqn:nrj:estimee:moll}
\begin{aligned}
\frac{d}{dt} \tilde{\mathcal{E}}_s &+ \epsilon \int_{\R^d} \point{\eta_0}{s} (\partialphi{r} P)_{|r=0} \cdot \pointal{\vec{U}}{s}_{|r=0} + \int_S \reg{2} \gradphi[x,r] (g\rhob \pointal{\eta_0}{s} + \iota_3\Lambda (\pointal{\eta_0}{s})^h) \cdot \pointal{\vec{U}}{s}\\
&  + \int_{\R^d}(\reg{2} \pointal{V}{s}_{|r=0} \cdot \nabla \eta_0 - \reg{2} w) g \rhob \pointal{\eta_0}{s} \approx 0.
\end{aligned}
\end{equation}
The first integral comes from the integration by parts on the pressure term, see~\eqref{eqn:pression:ipp}. We bound this term from above, up to a constant, by
$$\vert \point{\eta_0}{s} \vert_{H^{\frac12}(\R^d)} \vert \pointal{\vec{U}}{s}_{|r=0} \vert_{H^{-\frac12}(\R^d)},$$
which in turn is bounded by $\tilde{\mathcal{E}}$, thanks to the trace estimate~\eqref{apdx:eqn:trace}.
Now using the symmetry of $\reg{2}$ for the $L^2-$scalar product in the second integral and integrating by parts, we get, similarly to~\eqref{eqn:energy:V:1}(v):
$$\frac{d}{dt} \tilde{\mathcal{E}} \approx 0.$$
This shows that the time of existence of the solutions of~\eqref{eqn:moll:23} $T_{\iota_2,\iota_3}$ is independent of $\iota_2$.\\
\begin{remark}
\label{rk:iota2}
The only difference between this energy estimate and the one in Proposition~\ref{prop:energy} is the second term in~\eqref{eqn:nrj:estimee:moll}. Because it involves $\pointal{\vec{U}}{s}$ and not $\reg{2}\pointal{\vec{U}}{s}$ (like the third term in~\eqref{eqn:nrj:estimee:moll}), it cannot be treated via a symmetry argument (as in Proposition~\ref{prop:energy}). We rather use the dispersion term that controls an extra half derivative on $\eta_0$.
\end{remark}
\noindent{\bf \underline{Step 4.3:} Sending $\iota_3$ to $0$} \saut
We now have the existence of a solution to the system~\eqref{eqn:moll:23} with $\iota_2 = 0$. We can now apply the energy estimate of Proposition~\ref{prop:energy}, in particular using the Rayleigh-Taylor coefficient as in~\eqref{eqn:pression:ipp}, with the additional dispersion term $\iota_3 \Lambda^{\frac12} \point{\eta_0}{s}$ as in~\eqref{eqn:nrj:def:moll}. Contrary to Step $4.2$, we do not use the regularizing property of the dispersion (except to control terms stemming from the dispersion itself, which are of size $\iota_3$), hence the time of existence $T_{\iota_3}$ is independent of $\iota_3$. We eventually have existence of solutions to the system~\eqref{eqn:euler_phi}. Finally, changing variables, this yields a solution of the original system~\eqref{eqn:euler_euleriennes} in Eulerian coordinates, or equivalently,~\eqref{eqn:euler_phi}. This same energy estimate also provides the dependency with respect to $\epsilon,\beta,\mu,\delta$ of the time of existence in Theorem~\ref{thm:euler_phi} and the uniqueness of the solution.\\

\noindent{\bf \underline{Step 5:} Blow-up criterion} \saut
Classically (see~\cite{AJMajda2002}), the solutions can be continued as long as the assumptions of the energy estimate of Proposition~\ref{prop:energy} are satisfied, and we denote by $T_{\max}$ the maximal time of existence of a solution. This yields the following blow-up criterion
\begin{equation}
\label{eqn:critere_explosion:temp}
\text{or } \quad
\begin{aligned}
 &\limsup\limits_{t \to T_{\max}} \Vert (V, \sqrt{\mu} w,\sqrt{\mu} \rho)(t,\cdot)\Vert_{H^s(S_r)} + \vert \eta_0(t,\cdot)\vert_{H^s(\R^d)} + \Vert \vort(t,\cdot) \Vert_{H^{s-1}(S)}= + \infty \\
%& \inf\limits_{(x,r)\in S} (1-\beta b(x) + \epsilon \eta_0(t,x,r)) \underset{t\to T_{\max}}{\longrightarrow} 0,
& \liminf\limits_{t \to T_{\max}}\inf\limits_{(x,r)\in S} \taylor = 0,\\
& \liminf\limits_{t \to T_{\max}}\inf\limits_{(x,r)\in S} (\rhob + \epsilon \delta \rho) = 0,\\
& \liminf\limits_{t \to T_{\max}}\inf\limits_{x\in \R^d} 1 - \beta b(x) + \epsilon \eta_0(t,x) = 0.\\
\end{aligned}
\end{equation}
We now show that the last two conditions cannot happen. The condition on the density cannot happen as $\rho$ is transported by the fluid, therefore if~\eqref{hyp:density} holds initially, it holds as long as $V$ and $w$ remain Lipschitz continuous. for the last alternative in~\eqref{eqn:critere_explosion:temp}, we can compute, thanks to the kinematic equation~\eqref{eqn:euler_phi:bc} on $\eta_0$ and the divergence-free condition in~\eqref{eqn:euler_phi}:
$$\begin{aligned}
\frac{d}{dt} (1 - \beta b(x) + \epsilon \eta_0(t,x)) &= \epsilon \partial_t \eta_0(t,x) = -V(t,x,0) \cdot \nabla \eta_0(t,x) + w(t,x,0) \\
&= \int_{-1}^0 \partial_r (-V(t,x,r) \cdot \nabla (\etab(x,r) + \epsilon \eta(t,x,r)) + w(t,x,r))dr \\
&= \int_{-1}^0 \left( -\nabla(\etab + \epsilon \eta)\partial_r V + \partial_r w - V \nabla (\hb + \epsilon h) \right)\\
&= -\int_{-1}^0 \nabla \cdot ((\hb + \epsilon h)V)\\
\partial_t (1 - \beta b + \epsilon \eta_0)&= -\nabla \cdot ((1 - \beta b + \epsilon \eta_0) \overline{V}),
\end{aligned} $$
where 
$$\overline{V}(t,x) := \frac{1}{1 - \beta b(x) + \epsilon \eta_0(t,x)} \int_{-1}^0 (\hb(x,r) + \epsilon h(t,x,r)) V(t,x,r)dr$$
is the vertically averaged horizontal velocity. This is the conservation of the fluid height, and so if initially the fluid height is bounded from below (see Assumption~\eqref{hyp:non_cavitation:euleriennes}), then it holds as long as $\overline{V}$ remains Lipschitz continuous, by the characteristics method, and the blow-up criterion~\eqref{eqn:critere_explosion:temp} boils down to~\eqref{eqn:critere_explosion}. \\
\begin{comment}
{\bf \underline{Step 3:} Blow-up criterion} \saut
We get the blow-up criterion (See~\cite[Step 4 of the proof of Prop. 4.1]{Fradin2024}):
\begin{equation}
\label{eqn:blowup:temp}
\text{either}\qquad \Vert \vec{U}(t,\cdot) \Vert_{H^{s}} \underset{t \to T}{\longrightarrow} + \infty \qquad \text{or} \qquad \inf\limits_{(x,r)\in S} (1+h(t,x,r)) \underset{t \to T}{\longrightarrow} 0.
\end{equation}
The alternative~\eqref{eqn:blowup:temp} is not exactly~\eqref{eqn:critere_explosion}, as it depends on the choice of diffeomorphism $\eta$. However, going back to Eulerian coordinates, if~\eqref{eqn:critere_explosion} does not hold, then we can define a new set of semi-Lagrangian coordinates stemming from $t=T$, and construct a unique solution stemming from $t=T$. Using time-reversibility and uniqueness in Eulerian coordinates, this solution coincide with the previous one, and thus we can extend it on $[0,T']$ with $T<T'$. \\
To go back to Eulerian coordinates, we define $\vec{\check{U}} := \vec{U} \circ \varphi^{-1}$, which is in $C^0([0,T],H^s(\Omega_t))$ and is a solution of~\eqref{eqn:euler_euleriennes}, with $\eta_0$ defined as the trace of $\eta$ at $r=0$. Note that the trace estimate~\eqref{apdx:eqn:trace} yields $\eta_0 \in C^0([0,T],H^{s-\frac12})$. \\
{\bf \underline{Step 4:} Continuity with respect to the initial data in $H^{s-1}$-norm} \saut
We prove the following statement, that will be used in Step 6. Note that the constant $C$ in~\eqref{eqn:weak_continuity} depends on an upperbound of $\Vert (\vec{U}_1,\eta_1,\vec{U}_2,\eta_2)\Vert_{H^s}$.
\begin{lemma}
\label{lemma:weak_continuity}
If $(\vec{U}_1,\eta_1)$ (resp. $(\vec{U}_2,\eta_2)$) is the solution of~\eqref{eqn:euler:slag} constructed in the previous step with initial data $(\vec{U}_1,\eta_1)_{\ini} \in H^{s}(S)^{d+2}$ (resp. $(\vec{U}_2,\eta_2)_{\ini}$), then there exists a constant $C > 0$ depending only on an upperbound of $\Vert (\vec{U}_1,\eta_1,\vec{U}_2,\eta_2)\Vert_{H^s}$ such that
\begin{equation}
\label{eqn:weak_continuity}
\sup\limits_{t \in [0,T)}\Vert (\vec{U}_1 - \vec{U}_2,\eta_1 - \eta_2)(t,\cdot)\Vert_{H^{s-1}} \leq C \Vert (\vec{U}_1 - \vec{U}_2,\eta_1 - \eta_2)(0,\cdot)\Vert_{H^{s-1}}.
\end{equation}
\end{lemma}
\begin{proof}
\renewcommand{\diff}{\mathbb{\Lambda}}
The proof is an energy estimate on the difference of the two solutions, and we only sketch the proof for $\vec{\tilde{U}} := \vec{U_1} - \vec{U_2}$. Taking the difference of~\eqref{eqn:euler:slag} satisfied by $\vec{U_1}$ and $\vec{U_2}$, and then applying $\diff := \Lambda^{s-k}\partial_r^{k-1}$ for $0 \leq k-1 \leq s-1$ yields
\begin{equation}
\label{eqn:weak_continuity:temp:1}
\partial_t \diff \vec{\tilde{U}} + V_1 \cdot \nabla \diff \vec{\tilde{U}} = - \diff\left( \nabla^{\varphi_1}P_1 - \nabla^{\varphi_2}P_2 \right) +\diff( \tilde{V} \cdot \nabla \vec{U_2}) + [\diff,\vec{U_1}\cdot \nabla] \tilde{U},
\end{equation}
where $\varphi_1$ is defined from $\eta_1$ through~\eqref{eqn:phi:def:slag} (resp. $\varphi_2$). Testing this equation against $\diff \vec{\tilde{U}}$, using a horizontal integration by parts for the term on the left-hand side and Cauchy-Schwarz inequality for the terms on the right-hand side yields
\begin{equation}
\label{eqn:weak_continuity:temp:2}
\begin{aligned}
\frac12 \frac{d}{dt}&\Vert \diff \vec{\tilde{U}}\Vert_{L^2}^2 \leq \int_{S} \nabla \cdot V_1 |\diff \vec{\tilde{U}}|^2 \\
&+ \left(\Vert\diff (\nabla^{\varphi_1}P_1 - \nabla^{\varphi_2}P_2) \Vert_{L^2} +\Vert\diff( \tilde{V} \cdot \nabla \vec{U_2})\Vert_{L^2} + \Vert[\diff,\vec{U_1}\cdot \nabla] \tilde{U}\Vert_{L^2}\right)\Vert\diff\vec{\tilde{U}}\Vert_{L^2}.
\end{aligned}
\end{equation}
We use~\eqref{eqn:existence:elliptic:lip} (with $\delta = 0$) for the first term of the right-hand side, the product estimate~\eqref{apdx:eqn:pdt:algb} for the second term, and the commutator estimate~\eqref{apdx:eqn:commutator:gen} for the third one. Note that this second term makes appear $\Vert \vec{U_2} \Vert_{H^{s}}$. Using Gronwall lemma, we get~\eqref{eqn:weak_continuity}.
\end{proof}
\uline{From now on, we go back to the set of coordinates defined in~\eqref{eqn:phi:def:bary}, as we do not need the semi-Lagrangian property anymore.}\\

\noindent{\bf \underline{Step 6:} Propagation of the divergence-free condition} \saut
It only remains to check that the solution constructed above is divergence-free.
Applying $\gradphi[x,r] \cdot$ to~\eqref{eqn:euler_phi} and using the equation~\eqref{eqn:existence:elliptic} satisfied by the pressure, we get
\begin{equation}
\label{eqn:existence:div}
\partial_t^{\varphi} \gradphi[x,r] \cdot \vec{U}  + \vec{U} \cdot \gradphi[x,r] \left( \gradphi[x,r] \cdot \vec{U} )\right) = 0.
\end{equation}
Testing this equation against $\gradphi[x,r] \cdot \vec{U}$, we get
\begin{equation}
\label{eqn:existence:div:nrj}
\frac{d}{dt} \Vert \gradphi[x,r] \cdot \vec{U} \Vert_{L^2} \leq C  \Vert \gradphi[x,r] \cdot \vec{U} \Vert_{L^2},
\end{equation}
where $C$ depends on $M_{\ini}, h_*,h^*$. Using Gronwall Lemma, we get that the divergence-free condition in~\eqref{eqn:euler_phi} is propagated by the Euler equations if it holds initially.\\
\end{comment}
\begin{comment}
{\bf \underline{Step 6:} Dependency in $\beta,\epsilon,\mu$ and regularity of the free-surface $\eta_0$} \saut
Recall that we now have a solution $\vec{U} = (V,\sqrt{\mu}w)^T$, $\eta_0$ of~\eqref{eqn:euler_phi}, with $\vec{U} \in C^0([0,T),H^s)$ and $\eta_0 \in C^0([0,T),H^{s-\frac12})$. However, $T$ might depend badly on $\beta,\epsilon,\mu$, and the free-surface less regular than expected by the energy estimate in Proposition~\ref{prop:energy}.\\
Recall that $H^{s+1}(S)$ is dense in $H^s(S)$ (resp. $\R^d$) so that for any $\delta > 0$, we can choose $(V_{\ini},w_{\ini})_{\delta} \in H^{s+1}$, $(\eta_{0,\ini})_{\delta} \in H^{s+1}(\R^d)$ such that
\begin{equation}
\label{eqn:existence:temp:1}
\Vert (V_{\ini}-(V_{\ini})_{\delta},w_{\ini}-(w_{\ini})_{\delta})\Vert_{H^s} + \vert \eta_{0,\ini} - (\eta_{0,\ini})_{\delta} \vert_{H^s} \leq \delta.
\end{equation}
Now the previous analysis yields a solution $(V,w,\eta_0) \in C^0([0,T_{\beta,\epsilon,\mu}),H^s(S)^{d+1} \times H^s(\R^d))$ with regularized initial condition $(V_{\ini})_{\delta}, (w_{\ini})_{\delta},(\eta_{0,\ini})_{\delta}$. Because of the energy estimate of Proposition~\ref{prop:energy}, both alternatives in the blow-up criterion~\eqref{eqn:critere_explosion} for the $H^s-$norm cannot happen before a time $T_{\beta,\epsilon,\mu} = O(\frac{1}{\epsilon \vee \beta})$, and $T$ is in particular independent of $\delta$. Hence, the sequence $(V_{\delta},w_{\delta},(\eta_0)_{\delta})_{\delta > 0}$ is bounded in $C^0([0,T),H^s(S)^{d+1}\times H^s(\R^d))$, and admits a weak limit $(\tilde{V},\tilde{w},\tilde{\eta}_0)$ (up to taking a subsequence) in this same space. Now, the sequence $(V_{\delta},w_{\delta},(\eta_0)_{\delta})_{\delta>0}$ converges to the solution $(V,w,\eta_0)$ of~\eqref{eqn:euler_phi} in a weaker norm, namely in $C^0([0,T),H^{s_0+2}(S)^{d+1}\times H^{s_0+2})$, because of Lemma~\ref{lemma:weak_continuity} and the equivalence~\eqref{apdx:eqn:equiv} between the $H^s-$norm of $\vec{U}$ in the coordinates defined in Section~\ref{section:change_variables} and the semi-Lagragian coordinates defined in Step 1 and used in Lemma~\ref{lemma:weak_continuity}. This implies that $(V,w,\eta_0) = (\tilde{V},\tilde{w},\tilde{\eta}_0)$, and thus that $(V,w,\eta_0) \in C^0([0,T),H^s(S)^{d+1}\times H^s(\R^d))$.\\
\end{comment}
\end{proof}
