\section{The shallow water limit}
\label{section:cvce}
In this section, we study the shallow water limit, namely $\mu \to 0$, in the system~\eqref{eqn:euler_phi}. We show in Subsection~\ref{subsection:cvce_short} that the solution of~\eqref{eqn:euler_phi} converges towards the solution of the non-linear shallow water equations~\eqref{eqn:nlsw}. In Subsection~\ref{subsection:cheating}, we use this result to improve the time of existence of Theorem~\ref{thm:euler_phi}, although in a specific setting and only to a time of order $\log(\frac{1}{\epsilon})$.
\subsection{Quantitative comparison with the non-linear shallow water equations}
\label{subsection:cvce_short}
Recall the non-linear shallow water equations~\eqref{eqn:nlsw}. In order to compare a solution $(V_{\sw},\eta_{\sw})$ of this system defined on $\R^d$ to a solution of~\eqref{eqn:euler_phi} defined in $S$, we identify $V_{\sw}$ to its natural extension $(t,x,r) \mapsto V_{\sw}(t,x)$ defined in $S$. Moreover, we define a shallow water vertical velocity $w_{\sw}$ as
\begin{equation}
\label{eqn:def_wsw}
w_{\sw} := \beta V_{\sw} \cdot \nabla b - (r + 1)(1-\beta b + \epsilon \eta_{\sw}) \nabla \cdot V_{\sw},
\end{equation}
so that the incompressibility condition in~\eqref{eqn:euler_phi} and the boundary condition~\eqref{eqn:euler_phi:bc} at the bottom and at the top are also satisfied by $(V_{\sw},w_{\sw})$. Defining $P_{\sw} := 0$, we can thus write the non-linear shallow water equations~\eqref{eqn:nlsw} as
\begin{equation}
\label{eqn:nlsw:euler_form}
\sys{\partialphi{t} V_{\sw} + \epsilon \vec{U}_{\sw} \cdot \gradphi[x,r] V_{\sw} + \frac{1}{\rhob} \gradphi[x] P_{\sw} + \nabla_x \eta_{\sw} &= 0 \\
\mu \left( \partialphi{t} w_{\sw} + \epsilon \vec{U} \cdot \gradphi[x,r] w_{\sw} \right) + \frac{1}{\rhob} \partialphi{r} P_{\sw} &= \mu f_2,\\
\nabla_x \cdot V_{\sw} + \partial_z w_{\sw} &= 0,} \qquad \text{ in } [0,T] \times \R^d \times [-1,0],
\end{equation}
with $f_2 := \partialphi{t} w_{\sw} + \epsilon \vec{U} \cdot \gradphi[x,r] w_{\sw}$ so that the second equation in~\eqref{eqn:nlsw:euler_form} is trivial. We still write it to stress the comparison with the Euler equations~\eqref{eqn:euler_phi}. Note that the analogous of the equation on the density $\rho$ in~\eqref{eqn:euler_phi} still holds if we define $\rho_{\sw} = 0$. The equations~\eqref{eqn:nlsw:euler_form} are completed with the boundary conditions
\begin{equation}
\label{eqn:nlsw:euler_form:bc}
\sys{ P_{\sw|r=0} &= 0,\\
	\partial_t \eta_{\sw} + \epsilon V_{\sw | r=0} \cdot \nabla_x \eta_{\sw} - w_{\sw|r=0} &= 0,\\
	\vec{N}_b \cdot \vec{U}_{\sw |r=-1} &= 0,\\}
\end{equation}
coming from~\eqref{eqn:nlsw} and the definition of $w_{\sw}$ and $P_{\sw}$. They are also completed with initial conditions analogous to~\eqref{eqn:euler_phi:ci}.
%According to [BM], there exists a unique solution of~\eqref{eqn:nlsw} in $C([0,T/\epsilon[,H^{s}(\R^d))$ with initial condition $(V_{\sw}_{\ini},(\eta_0)_{\ini}) \in H^s(\R^d)$. 

Let us now state the assumptions for the following theorem to hold true. Let $s_0,s \in \N$, with $s_0>\frac{d+1}{2}$ and $s \geq s_0+2$. Let $(V,w,\eta_0) \in C^0([0,T),(H^s)^{d+1}(S) \times H^s(\R^d))$ be a solution of~\eqref{eqn:euler_phi} and $(V_{\sw},\eta_{\sw}) \in C^0([0,T[,H^{s+1}(\R^d)^{d+1})$ be a solution of~\eqref{eqn:nlsw}. We assume that the two solutions are close initially, that is
\begin{hyp}
\label{hyp:E0}
\Vert (V - V_{\sw}, \sqrt{\mu}(w - w_{\sw})) \Vert_{H^s} + \vert \eta - \eta_{\sw} \vert_{H^s} + \Vert \sqrt{\mu} \rho \Vert_{H^s} + \frac{1}{\mu} \Vert \partial_r V \Vert_{H^{s-1}} \leq  \sqrt{\mu} \qquad \text{ at } t=0,
\end{hyp}We also write $M_{\sw}>0$ a constant such that
\begin{hyp}
\label{hyp:Msw}
\vert (V_{\sw},\eta_{\sw})\vert_{H^{s+1}} \leq M_{\sw}.
\end{hyp}We also assume weak density perturbations , that is
\begin{hyp}
\label{hyp:weak_density}
\delta \leq \mu.
\end{hyp}
\begin{theorem}
\label{thm:convergence:svt}
Let $T > 0$ such that there exist a solution $(V_{\sw},\eta_{\sw})$ of~\eqref{eqn:nlsw} in \\$C^0([0,T], H^{s+1}(\R^d)^{d+1})$ and a solution $(V,w,\rho,\eta_0)$ of~\eqref{eqn:euler_phi} in $C^0([0,T[, H^{s}(S)^{d+2} \times H^s(\R^d))$ satisfying~\eqref{hyp:b},~\eqref{hyp:H},~\eqref{hyp:taylor},~\eqref{hyp:M},~\eqref{hyp:Mini},~\eqref{hyp:E0},~\eqref{hyp:Msw},~\eqref{hyp:weak_density}. Then there exists a constant $C$ depending only on $M$ (defined in~\eqref{hyp:M}) and $M_{\sw}$ such that
$$\sup_{t\in[0,T]} \left( \Vert V - V_{\sw} \Vert_{H^{s}(S)} + \vert \eta_0-\eta_{\sw} \vert_{H^s(\R^d)} \right) \leq C\sqrt{\mu}.$$
\end{theorem}
\begin{remark}
The constant $C$ depends on $M_{\sw}$, an upperbound on $\vert (V_{\sw},\eta_{\sw})\vert_{H^{s+1}}$, which is a stronger norm than the one used in Theorem~\ref{thm:convergence:svt} for the convergence (i.e. we only control the difference of the solutions of~\eqref{eqn:euler_phi} and~\eqref{eqn:nlsw} in $H^s$). However, it only depends on an upperbound on the $H^s$-norm of the solution $(V,w,\rho,\eta_0)$ of~\eqref{eqn:euler_phi}, through~\eqref{hyp:M}. This is achieved by plugging the solution of the non-linear shallow water equations into the Euler equations~\eqref{eqn:euler_phi}, not the other way around. This fact will be used in Subsection~\ref{subsection:cheating}.
\end{remark}
\begin{remark}
\label{rk:euler_diff:estimate}
The proof of Theorem~\ref{thm:convergence:svt} yields the slightly more precise estimate, for any $t \in [0,T]$:
\begin{equation}
\label{eqn:euler_diff:estimate}
\begin{aligned}
&\Vert (V - V_{\sw}, \sqrt{\mu}(w - w_{\sw}))(t,\cdot) \Vert_{H^s} + \vert (\eta - \eta_{\sw})(t,\cdot) \vert_{H^s} + \Vert \sqrt{\mu} \rho \Vert_{H^s}+\frac{1}{\sqrt{\mu}} \Vert \partial_r V(t,\cdot) \Vert_{H^{s-1}} \\
&\leq C \sqrt{\mu} (1+t) e^{C (\epsilon \vee \beta\vee\frac{\delta}{\mu}) t},
\end{aligned}
\end{equation}
using~\eqref{hyp:E0}. This will be used in Subsection~\ref{subsection:cheating}.

Note also that the control of the difference of the solutions given by~\eqref{eqn:euler_diff:estimate} is in $\sqrt{\mu}$. This mostly comes from the fact that the columnar motion is only true up to order $O(\sqrt{\mu})$, see Remark~\ref{rk:columnar}. This is consistent with the result in~\cite{Castro2014a}. Note however that~\eqref{eqn:euler_diff:estimate} can be improved to a rate $O(\mu)$ in the homogeneous and irrotational case, see for instance~\cite{Lannes2013}.
\end{remark}
%According to [BM], there exists a unique solution $(V_{\sw},\eta_{\sw})$ of~\eqref{eqn:nlsw} in $C([0,T/\epsilon[,H^{s}(\R^d))$ with initial condition $((V_{\sw})_{\ini},(\eta_0)_{\ini}) \in H^s(\R^d)$.
\begin{proof}
With the notations and assumptions of Theorem~\ref{thm:convergence:svt}, let 
\begin{equation}
\label{eqn:def:Vdiff}
(\Vdiff,\wdiff,\etadiff) := (V-V_{\sw},w-w_{\sw},\eta_0-\eta_{\sw}).
\end{equation}
We look for an equation of the form~\eqref{eqn:quasilin:gen} satisfied by $(\Vdiff,\wdiff,\rho,\etadiff)$. Taking the difference between~\eqref{eqn:euler_phi} and~\eqref{eqn:nlsw:euler_form} yields
\begin{equation}
\label{eqn:euler_diff:ordre0}
\sys{
\partialphi{t} \Vdiff + \epsilon \vec{U} \cdot \gradphi[x,r] \Vdiff + \frac{1}{\rhob + \epsilon \delta \rho} \gradphi \Pdiff + \frac{g\rhob}{\rhob + \epsilon \delta \rho} \nabla \etadiff &= \Fun \\
\mu\left( \partialphi{t} \wdiff + \epsilon \vec{U} \cdot \gradphi[x,r] \wdiff \right) + \frac{1}{\rhob + \epsilon \delta \rho}\partialphi{r}\Pdiff + \frac{\delta \rho}{\rhotot} &= \mu\Fdeux, \\
\partialphi{t} \rho + \vec{U} \cdot \gradphi[x,r] \rho &= 0,\\
\gradphi \cdot \Vdiff + \partialphi{r} \wdiff &= \Ftrois,
}
\end{equation}
where we used that $V_{\sw}$ does not depend on $r$. This system is completed with boundary conditions
\begin{equation}
\label{eqn:euler_phi:order0:bc}
\sys{ \Pdiff_{r=0} &= 0, \\
	\partial_t \etadiff + \epsilon V_{|r=0} \cdot \nabla \etadiff - \wdiff_{|r=0} &= \Fquatre, \\
	\vec{N_b} \cdot \vec{\tilde{U}}_{|r=-1} &= 0;}
\end{equation}
where we have used the following notations:
\begin{equation}
\label{eqn:euler_diff:ordre0:restes}
\begin{aligned}
\Fun &:=\epsilon \Vdiff \cdot \nabla V_{\sw} + \delta \epsilon \frac{\rho}{\rhotot} \nabla \eta_{\sw},\\
\Fdeux&:= \partialphi{t} w_{\sw} + \epsilon \vec{U} \cdot \gradphi[x,r] w_{\sw},\\
\Ftrois&:= \epsilon \frac{(1+r)\etadiff}{(\hb + \epsilon h)(\hb + \epsilon h_{\sw})} \partial_r w_{\sw},\\
\Fquatre&:=\epsilon \Vdiff \cdot \nabla \eta_{\sw}.
\end{aligned}
\end{equation}
We also define a shallow water vorticity :
$$\Vortsw := \begin{pmatrix} 0 \\ \vortsw \end{pmatrix} := \begin{pmatrix} 0 \\ \nabla^{\perp} \cdot V_{\sw} \end{pmatrix},$$
as well as the difference of the vorticities
$$\vortdiff := \vort - \Vortsw.$$
Applying $\nabla^{\perp}$ to the equation on $V_{\sw}$ in~\eqref{eqn:nlsw} and taking the difference with the equation~\eqref{eqn:euler_phi:vort} on $\vort$, we get
\begin{equation}
\label{eqn:euler_diff:vort}
\partialphi{t} \vortdiff + \epsilon \vec{U} \cdot \gradphi[x,r] \vortdiff  = \Fcinq.
\end{equation}	
where
\begin{equation}
\label{eqn:vort:diff:reste}
\Fcinq := \epsilon \Vdiff \cdot \nabla \Vortsw + \epsilon \vortsw \partialphi{r} \begin{pmatrix} \frac{1}{\sqrt{\mu}} \Vdiff \\ \wdiff \end{pmatrix} - \epsilon \vortdiff^{[x]} \cdot \gradphi \begin{pmatrix} V \\ \sqrt{\mu} w \end{pmatrix} - \epsilon \vortdiff^{[z]} \partialphi{r} \begin{pmatrix} \frac{1}{\sqrt{\mu}} V \\ w \end{pmatrix} + \frac{\delta}{\sqrt{\mu}} \vec{F},
\end{equation}
where $\vec{F}$ is defined from $\rho,P,\eta_0$ through~\eqref{eqn:def:vort:source}.
We used that the horizontal component of $\Vortsw$ is zero and that $\vortsw$ does not depend on $r$ to simplify the above equation.\\

As the equation on $\rho$ in~\eqref{eqn:euler_diff:ordre0} is the same as the one in~\eqref{eqn:euler_phi}, the energy estimate is the same as in the proof of Proposition~\ref{prop:energy} and we omit it in this proof. Let us define
\begin{equation}
\label{eqn:def:Vdiffs}
(\Vdiffs,\wdiffs,\etadiffs) := (\pointal{V}{s} - \point{V}{s}_{\sw},\pointal{w}{s} - \point{w}{s}_{\sw},\point{\eta}{s}_0 - \point{\eta}{s}_{\sw}), 
\end{equation}
where  $(\point{V}{s}_{\sw},\point{\eta}{s}_{\sw}) := (\diff V_{\sw},\point{\eta}{s}_{\sw})$, $\point{\eta}{s}_0 := \dot{\Lambda}^{s}\eta_0$ and $\pointal{V}{s},\pointal{w}{s}$ are Alinhac's good unknowns defined through~\eqref{apdx:alinhac:definition}. We look for a system of equations on $(\Vdiffs,\wdiffs,\etadiffs)$.
To this end, we apply the operator $\diff$ to~\eqref{eqn:nlsw:euler_form} and~\eqref{eqn:nlsw:euler_form:bc} to get
\begin{equation}
\label{eqn:nlsw:quasilin}
\sys{	\partial_t \point{V}{s}_{\sw} + \epsilon V_{\sw} \cdot \nabla \point{V}{s}_{\sw} + g\nabla \point{\eta}{s}_{\sw} &=\Run^{\sw}, \\
\nabla \cdot \point{V}{s}_{\sw} + \frac{1}{1-\beta b + \epsilon \eta_{\sw}}\partial_r \point{w}{s}_{\sw} &= \Rtrois^{\sw}, \\
\partial_t \point{\eta}{s}_{\sw} + \epsilon V_{\sw} \cdot \nabla  \point{\eta}{s}_{\sw}  + (w_{\sw})_{|r=0}^s & = \Rquatre^{\sw},\\
	} \qquad \text{ in } \R^d,
\end{equation} 
with
\begin{equation}
\label{eqn:nslw:quasilin:restes}
\begin{aligned}
\Run^{\sw} &:= \epsilon [\diff,V_{\sw}] \cdot \nabla V_{\sw},\\
\Rtrois^{\sw} &:= [\diff,\frac{1}{1-\beta b + \epsilon \eta_{\sw}}] \partial_r w_{\sw},\\
\Rquatre^{\sw} &:= [\diff,V_{\sw} \cdot \nabla, \eta_{\sw}].\\% +[\diff,-\beta b + \epsilon \eta_{\sw}]\nabla \cdot V_{\sw} .\\
\end{aligned}
\end{equation}
Recall now the quasilinear system~\eqref{eqn:euler_quasilin} satisfied by Alinhac's good unknowns $(\pointal{V}{s},\pointal{w}{s})$, and $\point{\eta}{s}_0$. Taking the difference between~\eqref{eqn:nlsw:quasilin} and~\eqref{eqn:euler_quasilin} yields
\begin{equation}
\label{eqn:euler_diff:quasilin}
\sys{
\partialphi{t} \Vdiffs + \epsilon \vec{U} \cdot \gradphi[x,r] \Vdiffs + \frac{1}{\rhotot} \gradphi \Pdiffs + \frac{g\rhob}{\rhotot} \nabla \etadiffs &= \tilde{\Run} \\
\mu\left( \partialphi{t} \wdiffs + \epsilon \vec{U} \cdot \gradphi[x,r] \wdiffs \right) + \frac{1}{\rhotot}\partialphi{r}\Pdiffs  + \delta \frac{\rho}{\rhotot}&= \sqrt{\mu} \tilde{\Rdeux},\\
\gradphi \cdot \Vdiffs + \partialphi{r} \wdiffs &= \tilde{\Rtrois},
}
\end{equation}
where
\begin{equation}
\label{eqn:source:diff}
\begin{aligned}
\tilde{\Run} &:= \Run - \Run^{\sw}- \epsilon \Vdiffs \cdot \gradphi V_{\sw} - \delta \epsilon \frac{\rho}{\rhotot},\\
\tilde{\Rdeux} &:= \Rdeux-\sqrt{\mu} \left( \partialphi{t} \point{w}{s}_{\sw} + \epsilon U \cdot \gradphi[x,r] \point{w}{s}_{\sw} \right),\\
\tilde{\Rtrois} &= \Rtrois - \Rtrois^{\sw} + \epsilon \frac{(1+r)\etadiffs}{(\hb + \epsilon h)(\hb + \epsilon h_{\sw})} \partial_r w_{\sw},
\end{aligned}
\end{equation}
where $h_{\sw}$ is defined from $\eta_{\sw}$ through~\eqref{eqn:h:def}. Here, $\pointal{P}{s}$ is Alinhac's good unknown defined from $\varphi$ and $P$ through~\eqref{eqn:alinhac:def}, and $\Run,\Rdeux,\Rtrois$ are defined through~\eqref{eqn:euler_quasilin:restes}.
This set of equations is completed with the boundary conditions
\begin{equation}
\label{eqn:euler_phi:diff:bc}
\sys{ P_{r=0} &= 0, \\
	\partial_t \etadiffs + \epsilon V_{|r=0} \cdot \nabla \etadiffs - \wdiffs_{|r=0} &= \tilde{\Rquatre}, \\
	\vec{N_b} \cdot \vec{\tilde{U}}_{|r=-1} &= \tilde{\Rcinq},}
\end{equation}
where
\begin{equation}
\label{eqn:source:diff:eta}
\begin{aligned}
\tilde{\Rquatre} &:= \Rquatre - \Rquatre^{\sw} - \epsilon \Vdiffs_{r=0} \cdot \nabla \eta_{\sw},\\
\tilde{\Rcinq} &:= \Rcinq,
\end{aligned}
\end{equation}
and $\Rquatre,\Rcinq$ are defined through~\eqref{eqn:euler_quasilin:bc:restes}. We now define the following energy functional
\begin{equation}
\label{eqn:energy:Ediff:def}
\begin{aligned}
\Ediff &:=  \Edifflow + \Vert(\sqrt{(\hb + \epsilon h)(\rhotot)}\Vdiffs,\sqrt{\mu(\hb + \epsilon h)(\rhotot)}\wdiffs, \sqrt{\taylor} \etadiffs \Vert_{L^2}^2 \\
&+ \sum\limits_{k \leq s} \Vert \sqrt{\mu(\hb + \epsilon h)} \pointal{\rho}{(s,k)} \Vert_{L^2}^2 + \Vert \vortdiff \Vert_{H^{s-1}(S)}^2,
\end{aligned}
\end{equation}
where 
\begin{equation}
\label{eqn:energy:def:Edifflow}
\Edifflow := \Vert(\Vdiff,\sqrt{\mu} \wdiff)\Vert_{H^{s_0+1,2}}^2 + \Vert \sqrt{\mu} \rho\Vert_{L^2}^2 +   g\vert  \etadiff \vert_{H^{s_0+1}}^2.
\end{equation}
Lemma~\ref{lemma:equiv:Ediff} states that this functional is equivalent to the $H^s$-norm of $(\Vdiff,\wdiff,\rho,\etadiff)$, and in this sense, is analogous to Lemma~\ref{lemma:energy:equiv}.
\begin{lemma}
\label{lemma:equiv:Ediff}
Under Assumptions~\eqref{hyp:H},\eqref{hyp:taylor},\eqref{hyp:M}, for any $s\geq s_0+2$, $\Ediff$ is equivalent to $\Vert \Vdiff,\sqrt{\mu} \wdiff,\sqrt{\mu} \rho \Vert_{H^s}$ $+ \vert \etadiff \vert_{H^s}$, that is there exists $C > 0$ such that
\begin{equation}
\label{eqn:energy:equiv:Ediff}
\frac{1}{C} \left(\Vert \Vdiff,\sqrt{\mu} \wdiff,\sqrt{\mu} \rho \Vert_{H^s}^2  + \Vert \vortdiff \Vert_{H^{s-1}}^2+ \vert \etadiff \vert_{H^s}^2 + \mu\right) \leq \Ediff \leq C \left(\Vert \Vdiff,\sqrt{\mu} \wdiff,\sqrt{\mu} \rho \Vert_{H^s}^2  + \Vert \vortdiff \Vert_{H^{s-1}}^2+ \vert \etadiff \vert_{H^s}^2 + \mu \right) 
\end{equation}
\end{lemma}
\begin{proof}
First note that
$$\Vdiffs = \pointal{V}{s} - \point{V}{s}_{\sw} = \diff \Vdiff - \frac{\diff (\etab + \epsilon \eta)}{\hb + \epsilon h} \partial_r \Vdiff,$$
as $V_{\sw}$ does not depend on $r$. Thus, $\Vdiffs$ is Alinhac's good unknown associated to $\Vdiff$. Now, notice that
$$\wdiffs = \pointal{w}{s} - \point{w}{s}_{\sw} = \diff \wdiff - \frac{\diff (\etab + \epsilon \eta)}{\hb + \epsilon h} \partial_r \wdiff -\frac{\diff (\etab + \epsilon \eta)}{\hb + \epsilon h} \partial_r w_{\sw}.$$
Therefore, $\sqrt{\mu} \wdiffs$ is Alinhac's good unknown associated to $\sqrt{\mu}\wdiff$, up to an error term of order $\sqrt{\mu}$. We can thus write:
$$\Ediff = \E + \mu C,$$
where $C$ depends only on $M$ and $M_{\sw}$ and $\E$ is defined through~\eqref{eqn:energy:def}. Then the estimate~\eqref{eqn:energy:equiv} yields the result.
\end{proof}
The remaining part of the proof is devoted to the proof of the following estimate
\begin{equation}
\label{eqn:energy:Ediff}
\frac{d}{dt} \Ediff \leq C (\epsilon \vee \beta \vee \frac{\delta}{\mu}) \Ediff + C \sqrt{\mu} \Ediff^{\frac12},
\end{equation}
as from~\eqref{eqn:energy:Ediff}, Lemma~\ref{lemma:equiv:Ediff} and Gönwall's lemma imply~\eqref{eqn:euler_diff:estimate}, which in turn implies the estimate in Theorem~\ref{thm:convergence:svt} thanks to~\eqref{hyp:E0}. \\
We start by estimating the remainder terms in~\eqref{eqn:euler_diff:quasilin},~\eqref{eqn:euler_phi:diff:bc} as well as in~\eqref{eqn:euler_diff:ordre0:restes}.
\begin{lemma}
\label{lemma:reste:quasilin:diff}
Under the assumptions of Theorem~\ref{thm:convergence:svt}, there exists $C$ depending only on $M$, $M_{\sw}$ such that
\begin{equation}
\label{eqn:pression:estimee:diff}
\Vert \tilde{P} \Vert_{H^s} \leq C \Ediff^{\frac12} + C \sqrt{\mu},
\end{equation}
as well as
\begin{equation}
\label{eqn:restes:estimee:diff}
\Vert (\tilde{\Run},\tilde{\Rdeux},\tilde{\Rtrois},\tilde{\Rsix})\Vert_{L^2}  + \vert \tilde{\Rquatre} \vert_{L^2} + \vert \tilde{\Rcinq} \vert_{H^{\frac12}} \leq (\epsilon \vee \beta\vee\frac{\delta}{\mu})C \Ediff^{\frac12} + C \sqrt{\mu}.
\end{equation}
and
\begin{equation}
\label{eqn:restes:estimee:diff:0}
\Vert (\Fun,\Fdeux,\Ftrois,\Fquatre,\Fcinq)\Vert_{H^{s-1}}  \leq (\epsilon \vee \beta\vee\frac{\delta}{\mu}) C \Ediff^{\frac12} + C \sqrt{\mu}.
\end{equation}
\end{lemma}
\begin{proof}
The estimate~\eqref{eqn:restes:estimee:diff:0} comes from the product, commutator estimates~\eqref{apdx:eqn:pdt:algb},~\eqref{apdx:eqn:commutator:gen}. Similar estimations have already been performed in Proposition~\ref{prop:restes} and we refer to them for the details. Note however that the operator $\gradphi$ in $\Fdeux$ is of order $1$, and is responsible for the loss of derivatives in~\eqref{eqn:restes:estimee:diff:0}.\\ 
We now prove~\eqref{eqn:pression:estimee:diff}. Note that as $(\pointal{V}{s},\pointal{w}{s},\pointal{P}{s})$ satisfy the system~\eqref{eqn:euler_diff:quasilin}, which is of the form~\eqref{eqn:euler_phi} with additional source terms, we can write an elliptic equation satisfied by $\pointal{P}{s}$. It is of the form of~\eqref{eqn:pression}, with additional source terms. A slight adaptation of the pressure estimate~\eqref{eqn:pression:estimee} to take these source terms into account yields
\begin{equation}
\label{eqn:temp:8}
\begin{aligned}
\Vert \sqrt{\mu} \gradphi \tilde{P}, \partialphi{r} \tilde{P} \Vert_{H^{s}} \leq C \sqrt{\mu} &( \Vert \Vdiff, \sqrt{\mu} \wdiff,\sqrt{\mu} \rho \Vert_{H^{s+1}} + \Vert \vortdiff  \Vert_{H^{s}} \\
&+ \sqrt{\mu}|\etadiff|_{H^{s+1}} + \Vert(\Fun,\sqrt{\mu} \Fdeux,\Ftrois,\partialphi{t}\Fquatre) \Vert_{H^{s}} ),
\end{aligned}
\end{equation}
with $(\Fun,\Fdeux,\Ftrois,\Fquatre)$ defined in~\eqref{eqn:euler_diff:ordre0:restes}.
%$$\begin{aligned}
%\Fun &:= \epsilon \vec{\tilde{U}} \cdot \nabla V_{\sw} & \qquad 
%\Fdeux := \partialphi{t} w_{\sw} + \vec{U} \cdot \gradphi[x,r] w_{\sw}\\
%\Ftrois &:= \epsilon \Vdiff \cdot \nabla \eta_{\sw} & \qquad
%\Fquatre := \epsilon \frac{(1+r) \etadiff}{(\hb + \epsilon h)(\hb + \epsilon h_{\sw})} \partial_r w_{\sw}.
%\end{aligned}$$
%Using the definition~\eqref{eqn:alinhac:def} of Alinhac's good unknown, we now write
%$$ \Vert \Pdiffs \Vert_{L^2} \leq C \Vert \gradphi P \Vert_{H^{s-1}}.$$
Using~\eqref{eqn:restes:estimee:diff:0} to bound the source terms in~\eqref{eqn:temp:8}, this yields~\eqref{eqn:pression:estimee:diff}.\\
For the estimate~\eqref{eqn:restes:estimee:diff}, we only treat $\tilde{\Run}$, the other terms are treated the same way. Let us expand the terms in $\tilde{\Run}$ to get: 
\begin{equation}
\label{eqn:temp:7}
\begin{aligned}
\tilde{\Run} &= \commal{\diff}{\partialphi{t}}{V}   + \epsilon \vec{U} \cdot \commal{\diff}{\gradphi[x,r]}{V} + \frac{1}{\rhotot}\commal{\diff}{\gradphi}{P} \\ 
 &+ \epsilon [\diff , V \cdot] \gradphi V- \epsilon [\diff,V_{\sw}] \cdot \nabla V_{\sw} \\
 & +  \epsilon [\diff ; w ,\partialphi{r} V] - \epsilon \Vdiffs \cdot \gradphi V_{\sw}\\
 &+ [\diff, \frac{1}{\rhotot}] \gradphi P + [\diff, \frac{g\rhob}{\rhotot}]\nabla \eta_0\\
 &- \delta \epsilon \frac{\rho}{\rhotot}.\\
\end{aligned}
\end{equation}
For the first term, we write
$$ \commal{\diff}{\partialphi{t}}{V} = \diff (\etab + \epsilon \eta) \partialphi{t} \partialphi{r} V + (\partial \varphi)^{-T} [\diff;(\partial \varphi)^T-I_{d+2},\gradphi[t,x,r] V],$$
where we made $[\diff;I_{d+2},\gradphi[t,x,r] V] = 0$ appear. Thus, according to the particular form of $(\partial \varphi)^T$, the symmetric commutator only depends on $\partialphi{r}V$:
$$ \begin{aligned}\commal{\diff}{\partialphi{t}}{V} &= \diff (\etab + \epsilon \eta) \partialphi{t} \partialphi{r} V \\
&+ (\partial \varphi)^{-T} [\diff;(\epsilon \partial_t \eta, (\nabla(\etab+\epsilon \eta))^T, -\beta b + \epsilon \eta_0)^T ,\partialphi{r}(V-V_{\sw})], \end{aligned}$$
where we used $\partialphi{r} V_{\sw}=0$. Thus, we get by~\eqref{apdx:alinhac:R1}:
$$\Vert \commal{\diff}{\partialphi{t}}{V} \Vert_{L^2} \leq C (\epsilon \vee \beta) \Ediff.$$
The second and third terms in~\eqref{eqn:temp:7} are treated the same way, with the estimate~\eqref{eqn:pression:estimee:diff} for the third one. The sixth term in~\eqref{eqn:temp:7} is treated the same way as it only depends on $\partialphi{r} V$. \\
For the fourth and fifth terms in~\eqref{eqn:temp:7}, we write
$$ [\diff , V \cdot] \gradphi V- [\diff,V_{\sw}] \cdot \nabla V_{\sw} = [\diff , V \cdot] \gradphi \Vdiff - [\diff,\Vdiff] \cdot \nabla V_{\sw}.$$
The commutator estimate~\eqref{apdx:eqn:commutator:gen} then yields
$$ \Vert [\diff , V \cdot] \gradphi V- [\diff,V_{\sw}] \cdot \nabla V_{\sw} \Vert_{L^2} \leq C \Ediff^{\frac12}.$$
The last terms in~\eqref{eqn:temp:7} are bounded by the product estimate~\eqref{apdx:eqn:pdt:algb}, commutator estimate~\eqref{apdx:eqn:commutator:horizontal} as well as the estimate~\eqref{eqn:pression:estimee:diff} on the pressure.
\end{proof}
We are now in a position to prove~\eqref{eqn:energy:Ediff}. 
Applying $\Lambda^{s_0+1-k}\partial_r^k$ to~\eqref{eqn:euler_diff:ordre0} for $0\leq k \leq s_0+1$ yields a quasilinear system of the form~\eqref{eqn:quasilin:gen}. The estimate~\eqref{eqn:quasilin:gen:energy:L2} together with ~\eqref{eqn:restes:estimee:diff:0} then yields
$$\frac{d}{dt} \Edifflow \leq C(\epsilon \vee \beta\vee\frac{\delta}{\mu})\Ediff + C\sqrt{\mu} \Ediff^{\frac12}. $$
The computations are the same as in the Step 1 of the proof of Proposition~\ref{prop:energy} and we refer the reader to this part for more details. \\
Now, the system~\eqref{eqn:euler_diff:quasilin} is of the form~\eqref{eqn:quasilin:gen}. Applying~\eqref{eqn:quasilin:gen:energy:L2} and the estimates~\eqref{eqn:restes:estimee:diff}, we readily get
$$\frac{d}{dt} \left(\Vert((\hb + \epsilon h)\Vdiffs,\sqrt{\mu} (\hb + \epsilon h)\wdiffs, \taylor \etadiffs \Vert_{L^2}^2\right) \leq C(\epsilon \vee \beta\vee\frac{\delta}{\mu})\Ediff + C\sqrt{\mu}\Ediff^{\frac12}. $$
For the estimate on the vorticity, we notice that~\eqref{eqn:euler_diff:vort} is exactly of the form~\eqref{eqn:quasilin:vort:gen}. Therefore, the estimate~\eqref{eqn:quasilin:gen:vort:energy:L2} yields
$$\frac{d}{dt} \Vert \vortdiff \Vert_{H^{s-1}}^2 \leq C (\epsilon \vee \beta\vee\frac{\delta}{\mu}) \Ediff + \Vert \Fcinq \Vert_{H^{s-1}}\Vert \vortdiff \Vert_{H^{s-1}},$$
Where $\Fcinq$ is defined through~\eqref{eqn:vort:diff:reste}. We readily get, by the product estimate~\eqref{apdx:eqn:pdt:algb}:
$$\Vert \Fcinq \Vert_{H^{s-1}} \leq C \epsilon \Ediff^{\frac12}.$$
\end{proof}

\subsection{A note on a larger time of existence for~\eqref{eqn:euler_phi}}
\label{subsection:cheating}
In this subsection, we use the result in~\cite{BreschMetivier10} that the solution $(V_{\sw},\eta_{\sw})$ of~\eqref{eqn:nlsw} exists on a time of order $\frac{T}{\epsilon}$, even in the presence of large topographic variations. As explained in Remark~\ref{rk:tps_long}, this is a better result than the one in Theorem~\ref{thm:euler_phi}. We can use the result in~\cite{BreschMetivier10} to improve the time of existence in Theorem~\ref{thm:euler_phi}, although with well-prepared initial data (Assumption~\eqref{hyp:E0}), and state this result in Corollary~\ref{cor:tps_long}. In the specific regime described by Assumption~\eqref{hyp:mu}, this boils down to a time of order $T \log(\frac{1}{\epsilon})$. This is much smaller that the large time $\frac{T}{\epsilon}$ from~\cite{BreschMetivier10}, and is called the Ehrenfest time in semi-classical analysis~\cite{Shepelyansky2020}.\\
In order to simplify the notations, we now assume $\beta = 1$ (large topographic variations) and $\delta \leq \mu$ (weak density variations). \\
Let $(V_{\sw},\eta_{\sw}) \in C^0([0,T/\epsilon[,(H^{s+1})^{d+1}(\R^d))$ the solution to the equations~\eqref{eqn:nlsw} with initial conditions in $H^{s+1}$, and let $M_{\sw}>0$ such that~\eqref{hyp:Msw} is satisfied.
In the following corollary, we assume that the initial data~\eqref{eqn:euler_euleriennes:ci} is well-prepared in the sense of~\eqref{hyp:E0}, and assume the regime
\begin{hyp}
\label{hyp:mu}
\mu \leq \epsilon.
\end{hyp}We take $M>0$ such that 
\begin{hyp}
\label{hyp:M:tpslong}
\Vert V_{\ini},\sqrt{\mu}w_{\ini},\sqrt{\mu} \rho_{\ini} \vert_{H^s} + \vert (\eta_0)_{\ini}\vert_{H^s} \leq M.
