\begin{equation}
\label{eqn:blowup_with_cte}
\begin{aligned}
T_* := \sup\{ T \leq \frac{1}{\epsilon},
 &\sup_{0 \leq t\leq T} \Vert (V,\sqrt{\mu}w,\sqrt{\mu} \rho)(t,\cdot) \Vert_{H^s} + \vert \eta_0(t,\cdot) \vert_{H^s} \leq 2M,\\
&\inf_{t\leq T} \inf_{(x,r)\in S} \taylor \geq c_*/2 \},\\
\end{aligned}
\end{equation}
so that in particular the maximal time of existence of the solution $(V,w,\rho,\eta_0)$ to~\eqref{eqn:euler_phi} $T_{\max}$ satisfies $T_{\max} \geq T_*$ by the blow-up criterion from Theorem~\ref{thm:euler_phi}. 

We start from the estimate~\eqref{eqn:euler_diff:estimate} in the special case where $\delta\leq\mu,\beta=1$ and with the well-preparation~\eqref{hyp:E0}, to get, by triangular inequality
\begin{equation}
\label{eqn:cheating:temp}
\Vert (V,\sqrt{\mu}w,\sqrt{\mu} \rho)(t,\cdot) \Vert_{H^s} + \vert \eta_0(t,\cdot) \vert_{H^s} \leq \Vert (V_{\sw},\sqrt{\mu}w_{\sw})(t,\cdot) \Vert_{H^s} + \vert \eta_{\sw}(t,\cdot) \vert_{H^s} + C \sqrt{\mu} e^{Ct}.
\end{equation}
Evaluating~\eqref{eqn:cheating:temp} at time $t$ with $t\leq \frac{1}{4C}\log(\frac{1}{\mu})$, the first term of the right-hand side of~\eqref{eqn:cheating:temp} stays bounded by $2M$ thanks to~\cite[Theorem 2.1]{BreschMetivier10}, and $\sqrt{\mu}( 1+ \frac{1}{4C}|\log \mu |) e^{\log(\frac{1}{\mu^{1/4}})}$ is bounded from above, uniformly in $\mu$. Hence the first condition in the definition of the set in~\eqref{eqn:blowup_with_cte} can only fail after the time $t_*:=\frac{1}{4C}\log(\frac{1}{\mu})$.\\
For the second condition in~\eqref{eqn:blowup_with_cte}, we use the bound on $\taylor$~\eqref{eqn:taylor:dt} to get
\begin{equation}
\label{eqn:cheating:temp:2}
\vert \taylor(t,\cdot) - g\rhob \vert_{L^{\infty}} \leq C \epsilon (\Vert (V,\sqrt{\mu} w,\sqrt{\mu} \rho)\Vert_{H^{s_0+2}} + \vert \eta_0 \vert_{H^{s_0+1}}).
\end{equation}
Together with the bound~\eqref{eqn:cheating:temp}, this yields
\begin{equation}
\label{eqn:cheating:temp:3}
\sup_{t\leq t_*}\vert \taylor(t,\cdot) - g\rhob \vert_{L^{\infty}} \leq C M \epsilon.
\end{equation}
Then $\inf\limits_{t\leq t_*}\inf\limits_{x\in \R^d}\taylor(t,x) \geq \frac12 c_*$, if $\epsilon \leq (g\rhob - c_*/2)/(CM)$. Hence the second condition in~\eqref{eqn:blowup_with_cte} can only fail after the time $t_*$. This eventually yields $T_{\max} \geq T_* \geq t_* = \frac{1}{2C} \log(\frac{1}{\mu})$ and this concludes the proof.
\end{proof}

