\begin{lemma}[Equivalence of norms by change of variables]
Let $t_0 > d/2$, $s \in \N$ with $s \geq t_0+\frac32$, $f \in H^{s}(S)$. Let $\eta \in H^s(S)$, satisfying~\eqref{hyp:H} as well as
$$\Vert \eta \Vert_{H^s}\leq M,$$
for some $M > 0$. We write $\check{f}(t,x,r) := f(t,x,r+\eta(t,x,r))$. Then there exists $C > 0$ depending only on $M$ such that
\begin{equation}
\label{apdx:eqn:equiv}
\Vert \check{f}\Vert_{H^s} \leq C \Vert f\Vert_{H^s}.
\end{equation}
\end{lemma}
\begin{proof}
Let $\alpha \in \N^{d+1}$ a multi-index of norm $|\alpha| \leq s$. We write
$$\partial^{\alpha} \check{f} = ((\partial^{\varphi})^{\alpha} f)\circ \varphi,$$
where $\partialphi{}$ is defined through~\eqref{eqn:gradphi:def}. Thus, by the product estimate~\eqref{apdx:eqn:pdt:tame}, we get~\eqref{apdx:eqn:equiv}.
\end{proof}
\begin{lemma}[A continuous embedding for anisotropic spaces]
\label{apdx:lemma:embedding}
Let $s \in \R$, and $f \in H^{s+\frac{1}{2},1}$. Then $f \in C^0([-1,0],H^s(\R^d))$ and moreover, there exists $C > 0$ such that
\begin{equation}
\label{apdx:eqn:embedding}
 \max\limits_{0 \leq  r \leq 1}|f(\cdot, r) |_{H^s} \leq C \Vert f \Vert_{H^{s+\frac12,1}}. 
\end{equation}
In particular, denoting by $f_{|r=-1}$ the trace of $f$ at the bottom of the strip $S$ (resp. $f_{|r=-1}$ at the surface), we can write
\begin{equation}
\label{apdx:eqn:trace}
\vert f_{|r=-1} \vert_{H^s(\R^d)} + \vert f_{|r=0} \vert_{H^s(\R^d)}\leq C \Vert f \Vert_{H^{s+\frac12,1}(S)},
\end{equation}
\end{lemma}
\begin{proof}
See for instance~\cite[Lemma A.1]{Duchene2022} or~\cite[Proposition 2.12]{Lannes2013}.
\end{proof}

\begin{lemma}[Standard product estimates in Sobolev spaces $H^s(\R^d)$]
Let $d \in \N^*$, $t_0 > d/2$, $s\in \R$, $s_1,s_2 \in \R$ such that $s\leq s_1$, $s\leq s_2$, $s_1 + s_2 \geq 0$ and $s \leq s_1 + s_2 - t_0$. There exists a constant $C > 0$ such that for any $f \in H^{s_1}(\R^d)$, $g \in H^{s_2}(\R^d)$, we can write
\begin{equation}
\label{apdx:eqn:pdt:s1s2}
 | fg |_{H^s(\R^d)} \leq C |f|_{H^{s_1}} |g|_{H^{s_2}}. 
\end{equation}
\end{lemma}
\begin{proof}
See for instance~\cite[Proposition B.2]{Lannes2013} and references therein.
\end{proof}


\begin{lemma}[Product estimates in anisotropic spaces]
\label{apdx:pdt}
Let $d\in \N^*$, $t_0 > d/2$, $s \in \R$ and $k \in \N$ with $0 \leq k \leq s$.
\begin{itemize}[label=\textbullet]
\item There exists $C > 0$ such that for any $f \in L^2(S_r)$ and $g \in H^{t_0+\frac12,1}(S_r)$,  we can write
\begin{equation}
\label{apdx:eqn:pdt:tame}
\Vert fg\Vert_{L^2} \leq C \Vert f \Vert_{L^2} \Vert g \Vert_{H^{t_0+1/2,1}}.
\end{equation}
\item If $s \geq t_0+\frac12$, $k \geq 1$, then there exists $C > 0$ such that for any $g\in H^{s,k}$, $f \in H^{s,k} $
\begin{equation}
\label{apdx:eqn:pdt:algb}
\Vert fg\Vert_{H^{s,k}} \leq C \Vert f \Vert_{H^{s,k}} \Vert g \Vert_{H^{s,k}}.
\end{equation}
\item If $s \geq t_0+\frac32$, $k \geq 2$, then there exists $C > 0$ such that for any $g\in H^{s,k}$, $f \in H^{s,k} $
\begin{equation}
\label{apdx:eqn:pdt:algb:tame}
\Vert fg\Vert_{H^{s,k}} \leq C \Vert f \Vert_{H^{s-1,k-1}} \Vert g \Vert_{H^{s,k}} + C \Vert f \Vert_{H^{s,k}} \Vert g \Vert_{H^{s-1,k-1}}.
\end{equation}
\item If $f \in W^{k,\infty}_r$ is independent of $x$ and $g \in H^{s,k}$, then 
\begin{equation}
\label{apdx:eqn:pdt:infty}
 \Vert fg \Vert_{H^{s,k}} \leq C | f |_{W^{k,\infty}} \Vert g \Vert_{H^{s,k}}.
 \end{equation}
\end{itemize}
\end{lemma}
\begin{proof}
See for instance~\cite[Lemma A.4]{Fradin2024} and references therein.
\end{proof}
We now state commutator estimate in $\R^d$. Note that in the case $s' = 0$,~\eqref{apdx:eqn:commutator:Rd:sprime} boils down to the classical commutator estimate that can be found, for instance, in~\cite[Proposition B.8]{Lannes2013}.
\begin{lemma}
Let $d \geq 1$, $t_0 > d/2$, $s \geq 0$.
\begin{itemize}
\item If $s_1 \geq s$ and $s_2 \geq s-1$ with $s_1+s_2 \geq s+t_0$, then there exists $C > 0$ such that
\begin{equation}
\label{apdx:eqn:commutator:Rd:classic}
|[\Lambda^s,f]g|_{L^2} \leq C | f |_{H^{s_1}} |g|_{H^{s_2}}.
\end{equation}
\item Let $s' \geq 0$. If moreover $s \geq t_0+1$, Then
\begin{equation}
\label{apdx:eqn:commutator:Rd:sprime}
|[\Lambda^s,f]g|_{H^{s'}} \leq C | f |_{H^{s+s'}} |g|_{H^{s+s'-1}}.
\end{equation}
\end{itemize}
\end{lemma}
\begin{proof}
The first inequality is classical. For the second one, we write
$$ \Lambda^{s'}( [\Lambda^s,f]g) = [\Lambda^{s+s'},f] g + [\Lambda^{s'},f] \Lambda^s g,$$
by definition of the commutator (see Subsection~\ref{subsection:notations}.
Using~\eqref{apdx:eqn:commutator:Rd:classic} with $s_1 = s+s'$ and $s_2 = s+s' -1$ to estimate the first term, and with $s_1 = s' + t_0+1$, $s_2 = s' -1$ for the second term, we get the result. 
\end{proof}
We now state commutator estimates in $H^{s,k}$ spaces.
\begin{lemma}[Commutator estimates] 
\label{apdx:commutator}
Let $d\in \N^*$, $t_0 > d/2$, $s >0$ and $k \in \N$ with $0 \leq k \leq s$.
 \begin{itemize}[label=\textbullet]
\item If $l\in \N$ with $0 \leq l \leq k$, then there exists $C > 0$ such that for any $f \in H^{s\vee(t_0+\frac32),k\vee2}$ and $g \in H^{(s-1)\vee(t_0+\frac12),2\vee(k\wedge(s-1))}$, we can write 
\begin{equation}
\label{apdx:eqn:commutator:gen}
\Vert [\Lambda^{s-l} \partial_r^l,f]g \Vert_{L^2} \leq C \Vert f \Vert_{H^{s\vee(t_0+\frac32),k\vee2}} \Vert g \Vert_{H^{(s-1)\vee(t_0+\frac12),2\vee(k\wedge(s-1))}}.
\end{equation}

\item If $s \geq  1$, then there exists $C > 0$ such that for any $f \in H^{s,0} \cap H^{t_0+\frac32,1}$, $g \in H^{s-1,0}$, we can write 
\begin{equation}
\label{apdx:eqn:commutator:horizontal}
\Vert [\dot{\Lambda}^{s},f]g \Vert_{L^2} \leq C \Vert \nabla_x f \Vert_{H^{t_0+\frac12,1}} \Vert g \Vert_{H^{(s-1)\vee(t_0+\frac12),0}}  + C \langle \Vert \nabla_x f \Vert_{H^{(s-1)\vee(t_0+\frac12),0}} \Vert g \Vert_{H^{t_0+\frac12,1}}\rangle_{s > t_0+1}.
\end{equation}

\item Let $k \geq 1$. There exists $C > 0$ such that if $f \in W^{k,\infty}_r$ and $g \in H^{s,k}$, then
\begin{equation}
\label{apdx:commutator:infty}
 \Vert [\Lambda^{s-k} \partial_r^k,f]g \Vert_{L^2} \leq C | f |_{W^{k,\infty}} \Vert g \Vert_{H^{s-1,k-1}}. 
\end{equation}
\end{itemize}
\end{lemma}
\begin{proof}
See~\cite[Lemma A.5]{Fradin2024} and references therein.
\end{proof}

We now state a similar lemma on symmetric commutators.
\begin{lemma}[Symmetric commutator estimates]
\label{apdx:commutator_sym}
Let $d\in \N^*$, $t_0 > d/2$, $s \in \R$  with $s \geq t_0+\frac52$ and $k \in \N$ with $2 \leq k \leq s$.

\begin{itemize}[label=\textbullet]
\item 
If $l\in \N$ with $0 \leq l \leq k$. Then there exists $C > 0$ such that for any $f \in H^{s,k}$, $g \in H^{s-1,k\wedge(s-1)}$, we can write 
\begin{equation}
\label{apdx:eqn:commutator_sym:gen}
\Vert [\Lambda^{s-l} \partial_r^l;f,g] \Vert_{L^2} \leq C \Vert f \Vert_{H^{s-1,k\wedge(s-1)}} \Vert g \Vert_{H^{s-1,k\wedge(s-1)}}.
\end{equation}
\item 
For $s \in \R$ and $ s \geq 1$, $f \in H^{s-1,0} \cap H^{t_0+\frac32,1}$, $g \in H^{s-1,0} \cap H^{t_0+\frac32,1}$ we can write 
\begin{equation}
\label{apdx:eqn:commutator_sym:horizontal}
\Vert [\dot{\Lambda}^{s};f,g] \Vert_{L^2} \leq C \Vert f \Vert_{H^{s-1,0}} \Vert g \Vert_{H^{t_0+\frac32,1}} + C \Vert g \Vert_{H^{s-1,0}} \Vert f \Vert_{H^{t_0+\frac32,1}}.
\end{equation}
%\item 
%There exists a constant $C_0$ also depending on $\Vert f \Vert_{H^{t_0+\frac32,2}}$ and $\Vert g \Vert_{H^{t_0+\frac32,2}}$ such that
%\begin{equation}
%\label{apdx:eqn:commutator_sym:un}
%\Vert [\Lambda^{s-1} \partial_r;f,g] \Vert_{L^2} \leq C_0\left( \Vert f \Vert_{H^{s-1,1}}   + \Vert g \Vert_{H^{s-1,1}} \right).
%\end{equation}
\end{itemize}
\end{lemma}
We conclude this appendix with composition estimates.
\begin{lemma}[Composition estimates in $H^{s,k}(S_r)$]
\label{apdx:composition}
Let $d \in \N^*$, $t_0 > d/2$. Let $s \in \R$ with $s \geq t_0+\frac12$, $k\in \N$ with $1 \leq k \leq s$, $M> 0$ . There exists $C > 0$ such that for any $F \in W^{s,k,\infty}(\R\times(0,1))$ with $F(0,\cdot) = 0$, and any $u \in H^{s,k}(S_r)$ such that $\Vert u \Vert_{H^{s,k}} \leq M$, the following holds. Define $F \circ u : (x,r) \mapsto F(u(x,r),r)$. Then
\begin{equation}
\label{apdx:eqn:composition:gen}
\Vert F \circ u \Vert_{H^{s,k}} \leq C | F |_{W^{s,k,\infty}(\R\times(0,1))} \Vert u \Vert_{H^{s,k}}.
\end{equation}
In the particular case $u = \epsilon h$ and $F(y) = \frac{y}{1+y}$, under assumption~\eqref{hyp:H}, we get
\begin{equation}
\label{apdx:eqn:composition:H}
\Vert \frac{\epsilon h}{\hb+\epsilon h} \Vert_{H^{s,k}} \leq \epsilon C \Vert h \Vert_{H^{s,k}}
\end{equation}
\end{lemma}
\begin{proof}
See for instance~\cite[Lemma A.5]{Duchene2022}.
\end{proof}

