Consider the following problem:
\begin{equation}\label{mainproblemw}
    \begin{cases}
        -\Delta u(x)+(-\Delta)^{s}u(x)=q(x) u(x),\,\,\,x\in\Om,\\
        u(x)=0,\,\,\,\,x\in \mathbb{R}^{n}\setminus\Om,
    \end{cases}
\end{equation}
where $q\in L^{\gamma}(\Omega)$ and $\gamma >\frac{n}{2s}$.

In the next theorem, we present the Lyapunov inequality and, as a corollary, we show a lower bound estimate of the first eigenvalue.
    \begin{theorem}[Lyapunov-type inequality]\label{strthmlyap}
Let $\Omega\subset \Rn$ be a smooth bounded domain. Assume that $n> 2s$, $\gamma >\frac{n}{2s}$, $q\in L^{\gamma}(\Omega)$. If $u\in \mathbb{X}(\Omega)$ is a  non-trivial weak solution of \eqref{mainproblemw}, then we have
\begin{equation}
    \left(\frac{C_{B,s}^{2^{\ast}_{s}(1-\beta)}}{2^{\beta}}\max\{|\Omega|^{\beta-\frac{2 \beta}{2_{s}^{*}}} C^{\beta}_{B,s},|\Omega|^{\beta-\frac{2\beta }{2^{*}}} C^{\beta}_{B,1} \}\right)^{\frac{1}{\gamma'}} \|q\|_{L^{\gamma}(\Omega)}\geq 1,
\end{equation}
where $\beta=\frac{\gamma-\frac{n}{2s}}{\gamma-1}\in (0,1)$ and $C_{B,s}$ and $C_{B,1}$ are the best constants defined in \eqref{best}. 
    \end{theorem}
    \begin{proof}
Firstly, let us start to show the following estimates to $\|u\|_{L^{2}(\Om)}$ and $\|u\|_{L^{2^{*}}(\Om)}$. Using \eqref{typpoin} and \eqref{typpoin1}, we have
\begin{equation}\label{12}
    \begin{split}
      \int_{\Omega}&|u(x)|^{2}  \dx x=  \int_{\Omega}\frac{|u(x)|^{2}}{2}+\frac{|u(x)|^{2}}{2}\dx x\\&
      \leq \frac{|\Omega|^{1-\frac{2 }{2_{s}^{*}}} C_{B,s} }{2}\int_{\Omega}\int_{\Omega}\frac{|u(x)-u(y)|^{2}}{|x-y|^{n+2s}}\dx x\dx y +\frac{|\Omega|^{1-\frac{2 }{2^{*}}} C_{B,1} }{2}\int_{\Om}|\nabla u(x)|^{2}\dx x\\&
      \leq \frac{\max\{|\Omega|^{1-\frac{2 }{2_{s}^{*}}} C_{B,s} ,|\Omega|^{1-\frac{2 }{2^{*}}} C_{B,1} \}}{2}\left(\int_{\Omega}\int_{\Omega}\frac{|u(x)-u(y)|^{2}}{|x-y|^{n+2s}}\dx x\dx y+\int_{\Om}|\nabla u(x)|^{2}\dx x\right),
    \end{split}
\end{equation}
and utilising the fractional Sobolev inequality \eqref{fracsob} and the embedding  \eqref{hsh1} we have one 
\begin{equation}\label{13}
    \begin{split}
       \int_{\Omega}|u(x)|^{2_{s}^{*}}\dx x &\leq \left(C_{B,s}^{2}\int_{\Omega}\int_{\Omega}\frac{|u(x)-u(y)|^{2}}{|x-y|^{n+2s}}\dx x\dx y\right)^\frac{2_{s}^{*}}{2}\\&
       \leq C^{2^*_{s}}_{B,s}\left(\int_{\Omega}\int_{\Omega}\frac{|u(x)-u(y)|^{2}}{|x-y|^{n+2s}}\dx x\dx y+\int_{\Omega}|u(x)|^{2}\dx x\right)^\frac{2_{s}^{*}}{2}.
    \end{split}
\end{equation}
By denoting
\begin{equation}\label{qbeta1}
    q=2\beta +2^{\ast}_{s}(1-\beta),
\end{equation}
and 
\begin{equation*}\label{beta1}
    \beta=\frac{\gamma-\frac{n}{2s}}{\gamma-1}\in (0,1),
\end{equation*}
with $\gamma\in\left(\frac{n}{2s},+\infty\right)$ and $2_{s}^{*}=\frac{2n}{n-2s}$. Then, we have $q=2\gamma'$ and by using H\"{o}lder's inequality with $\beta_{s}+(1-\beta_{s})=1$, \eqref{12} and \eqref{13}, we get
\begin{equation*}
    \begin{split}
        \int_{\Omega}|u(x)|^{q_{s}}\dx x&=\int_{\Omega}|u(x)|^{2\beta +2_{s}^{*}(1-\beta)}\dx x\\&
        \leq \left(\int_{\Omega}|u(x)|^{2}\dx x\right)^{2\beta }\left(\int_{\Omega}|u(x)|^{2_{s}^{*}}\dx x\right)^{1-\beta}\\&
       \stackrel{\eqref{hsh1}}\leq 
       \frac{C_{B,s}^{2^{\ast}_{s}(1-\beta)}}{2^{\beta}}\max\{|\Omega|^{\beta-\frac{2 \beta}{2_{s}^{*}}} C^{\beta}_{B,s},|\Omega|^{\beta-\frac{2\beta }{2^{*}}} C^{\beta}_{B,1} \}\left(\int_{\Omega}\int_{\Omega}\frac{|u(x)-u(y)|^{2}}{|x-y|^{n+2s}}\dx x\dx y +\int_{\Om}|\nabla u(x)|^{2}\dx x\right)^{\beta }\\&
       \times
      \left(\int_{\Omega}\int_{\Omega}\frac{|u(x)-u(y)|^{2}}{|x-y|^{n+2s}}\dx x\dx y +\int_{\Om}|\nabla u(x)|^{2}\dx x\right)^{\frac{2^{*}_{s}(1-\beta)}{2}}\\&
      = \frac{C_{B,s}^{2^{\ast}_{s}(1-\beta)}}{2^{\beta}}\max\{|\Omega|^{\beta-\frac{2 \beta}{2_{s}^{*}}} C^{\beta}_{B,s},|\Omega|^{\beta-\frac{2\beta }{2^{*}}} C^{\beta}_{B,1} \}\left(\int_{\Omega}\int_{\Omega}\frac{|u(x)-u(y)|^{2}}{|x-y|^{n+2s}}\dx x\dx y +\|\nabla u\|^{2}_{L^{2}(\Omega)}\right)^{\frac{q}{2}}\\&
      =\frac{C_{B,s}^{2^{\ast}_{s}(1-\beta)}}{2^{\beta}}\max\{|\Omega|^{\beta-\frac{2 \beta}{2_{s}^{*}}} C^{\beta}_{B,s},|\Omega|^{\beta-\frac{2\beta }{2^{*}}} C^{\beta}_{B,1} \} \left(\int_{\Omega}q(x)|u(x)|^{2}\dx x \right)^{\frac{q}{2}},
          \end{split}
\end{equation*}
where $C_{B,s}$ and $C_{B,1}$ are the best constants defined in \eqref{best} and by combining \eqref{qbeta1} and H\"{o}lder's inequality  $\frac{1}{\gamma'}+\frac{1}{\gamma}=1$, we obtain
\begin{equation*}
    \begin{split}
        \int_{\Omega}|u(x)|^{q_{s}}\dx x&
        \leq \frac{C_{B,s}^{2^{\ast}_{s}(1-\beta)}}{2^{\beta}}\max\{|\Omega|^{\beta-\frac{2 \beta}{2_{s}^{*}}} C^{\beta}_{B,s},|\Omega|^{\beta-\frac{2\beta }{2^{*}}} C^{\beta}_{B,1} \} \left(\int_{\Omega}q(x)|u(x)|^{2}\dx x \right)^{\frac{q}{2}}\\&
        \leq \frac{C_{B,s}^{2^{\ast}_{s}(1-\beta)}}{2^{\beta}}\max\{|\Omega|^{\beta-\frac{2 \beta}{2_{s}^{*}}} C^{\beta}_{B,s},|\Omega|^{\beta-\frac{2\beta }{2^{*}}} C^{\beta}_{B,1} \}\left(\int_{\Omega}q^{\gamma}(x)\dx x\right)^{\frac{q}{2\gamma}}\left(\int_{\Omega}|u(x)|^{2\gamma'}\dx x\right)^{\frac{q}{2\gamma'}}\\&
        =\frac{C_{B,s}^{2^{\ast}_{s}(1-\beta)}}{2^{\beta}}\max\{|\Omega|^{\beta-\frac{2 \beta}{2_{s}^{*}}} C^{\beta}_{B,s},|\Omega|^{\beta-\frac{2\beta }{2^{*}}} C^{\beta}_{B,1} \}\|q\|^{\gamma'}_{L^{\gamma}(\Omega)}\int_{\Omega}|u(x)|^{q}\dx x.
    \end{split}
\end{equation*}

Finally, we have 
\begin{equation*}
   \left(\frac{C_{B,s}^{2^{\ast}_{s}(1-\beta)}}{2^{\beta}}\max\{|\Omega|^{\beta-\frac{2 \beta}{2_{s}^{*}}} C^{\beta}_{B,s},|\Omega|^{\beta-\frac{2\beta }{2^{*}}} C^{\beta}_{B,1} \}\right)^{\frac{1}{\gamma'}} \|q\|_{L^{\gamma}(\Omega)}\geq 1.
\end{equation*}
\end{proof}

    \begin{corollary}
        Let  $\lambda_{1}$ be the first eigenvalue of \eqref{mainproblem}. Then we have 
        \begin{equation}\label{corlyap}
        \lambda_{1}\geq \left(\frac{C_{B,s}^{2^{\ast}_{s}(1-\beta)}}{2^{\beta}}\max\{|\Omega|^{\beta-\frac{2 \beta}{2_{s}^{*}}} C^{\beta}_{B,s},|\Omega|^{\beta-\frac{2\beta }{2^{*}}} C^{\beta}_{B,1} \}\right)^{-\frac{1}{\gamma'}}|\Om|^{-\frac{1}{\gamma}}.    
        \end{equation}

    \end{corollary}
    \begin{proof}
        Taking $q(x)=\lambda_{1}$ and using the previous theorem, we get \eqref{corlyap}.
    \end{proof}


In the pioneering work  \cite[p. 406]{Lia07}, A. Lyapunov  showed that  if 
$u$ is a nontrivial solution to the boundary value problem:
\begin{equation}\label{1}\left\{\begin{array}{l}u''(t)+q(t)u(t)=0,\,a<t<b,\\ u(a)=u(b)=0,\end{array}\right.
\end{equation} where $q\in C\left([a,b];\mathbb{R}\right),$ then the following inequality holds:
\begin{equation}\label{2}\int\limits_{a}^{b}\left|q(s)\right|ds>\frac{4}{b-a}.\end{equation}
 The inequality given in \eqref{2} is known as the (classical) Lyapunov inequality. Furthermore, the constant 4 appearing in \eqref{2} is optimal, meaning it cannot be replaced by a larger value.

As a consequence of \eqref{2}, we can derive a lower bound for the first eigenvalue of \eqref{1} in the special case where 
$q(x)=\lambda\in\mathbb{R}$, namely:
\begin{equation*}
    \lambda_{1}>\frac{4}{(b-a)^{2}}.
\end{equation*}

In the context of the multi-dimensional case, De Napoli and Pinasco (see \cite{DP16}) considered the $p$-Laplacian-Dirichlet problem
\begin{equation}\label{problem2-eucl}
    \begin{cases}
    -\Delta_p u(x)=\lambda u(x),\,\,\,\,\,x\in\Om,\,\,\,\,\,p>1,\\
    u(x)=0,\,\,\,\,x\in\partial\Omega,
    \end{cases}
\end{equation}
 where $\Delta_p u=\text{div} \left(|\nabla u|^{p-2}\nabla u\right)$ is a $p$--Laplace operator. 
 The authors applied a Lyapunov-type inequality to establish lower bounds for the first eigenvalue in the case where 
$N\neq p$. The result is stated as follows:

\begin{theorem}[{\cite[Corollary 2.6]{DP16}}]
Let $\lambda_{1,p}$ be the first eigenvalue of 
\begin{equation*}
    -\Delta_{p}u(x)=\lambda|u(x)|^{p-2}u(x),
\end{equation*}
in $\Om$ with zero Dirichlet condition in $\partial \Om$. Then,
\begin{itemize}
    \item if $n>p$ and $s>\frac{n}{p}$, we have
    \begin{equation}
        \lambda_{1,p}\geq  \frac{C_{H}^{-\alpha p}C_{S}^{-\frac{np}{n-p}(1-\alpha)}}{r^{\frac{sp-n}{s}}_{\Om}|\Om|^{\frac{1}{s}}},
    \end{equation}
    where $C_{H}$ and $C_{S}$ are the best constants of Hardy and Sobolev inequalities, respectively and $\alpha=\frac{\frac{np}{n-p}-s'p}{\frac{np}{n-p}-p}$ with $\frac{1}{s}+\frac{1}{s'}=1$;
    \item if $N<p$, we have
    \begin{equation}\label{eucmor}
        \lambda_{1,p}\geq \frac{C_{M}}{r^{p-N}_{\Om}|\Om|},
    \end{equation}
    where $C_{M}$ is the best constant of the Morrey inequality.
\end{itemize}
\end{theorem}

