    and using the continuous embedding $H_{0}^{1}(\Om)\hookrightarrow H^{s}(\Om)$, we compute
    \begin{equation*}
        \begin{split}
        (1+bC_{E}) \int_{\Rn}|\xi|^{2}f(\xi)\dx \xi&= \sum_{i=1}^{k} (1+bC_{E})\int_{\Rn}|\xi|^{2}|\hat{u}_{i}(\xi)|^{2}\dx \xi\\&
        =(1+bC_{E})\sum_{i=1}^{k} \int_{\Om}|\nabla u_{i}(x)|^{2}\dx x\\&
        \leq \sum_{i=1}^{k} \int_{\Om}\left(|\nabla u_{i}(x)|^{2}\dx x+b\int_{\Omega}\int_{\Omega}\frac{|u_{i}(x)-u_{i}(y)|^{2}}{|x-y|^{n+2s}}\dx x\dx y\right)\\&
        =\sum_{i=1}^{k} \lambda_{i}.
        \end{split}
    \end{equation*}
    Using Lemma \ref{lem1} with $b=0$, we have
     \begin{equation*}
        \begin{split}
            k=\int_{\Rn}f(\xi)\dx \xi &\leq  \frac{(2\pi)^{-n}|\Omega| |\Sn|}{n}\left(\sum\limits_{i=1}^{k} \lambda_{i}\right)^{\frac{1}{n+2}}\left((2\pi)^{-n}|\Omega||\Sn|\left(\frac{1+bC{_{E}}}{n+2}\right)\right)^{-\frac{1}{n+2}},
        \end{split}
    \end{equation*}
    and, finally
    \begin{equation*}
        \sum\limits_{i=1}^{k} \lambda_{i} \geq 
n^{\frac{n+2}{n}} \left( \frac{1 + bC_{E}}{n + 2} \right) k^{\frac{n+2}{n}} 
\left( (2\pi)^{-n}|\Omega||\mathbb{S}^{n-1}| \right)^{-\frac{2}{n}}.
    \end{equation*}
\end{proof}

\begin{proof}
    Let us denote $g(z)=M_{1}\chi_{\{|z|\leq R\}}$ where $\chi$ is the characteristic function and $R$ will be chosen as 
\begin{equation}\label{inlemfor1}
 \int_{\Rn}[a|z|^{2}+b|z|^{2s}]g(z)\dx z=M_{2}.   
\end{equation}
Hence (checking separately, $|z|\leq R$ and $|z|> R$), we have 
$$(a|z|^{2}+b|z|^{2s}-aR^{2}-bR^{2s})(f(z)-g(z))\geq0.$$
Using the last fact with \eqref{conlem1}, we establish
\begin{equation}\label{inlemfor2}
    (aR^{2}+bR^{2s})\int_{\Rn}(f(z)-g(z))\dx z \leq \int_{\Rn}(a|z|^{2}+b|z|^{2s})(f(z)-g(z))\dx z \leq 0.
\end{equation}
From \eqref{inlemfor1} for $R>0$, we compute
$$M_{2}= \int_{\Rn}(a|z|^{2}+b|z|^{2s})g(z)\dx z=M_{1}|\Sn|\left[\frac{aR^{n+2}}{n+2}+\frac{bR^{n+2s}}{n+2s}\right],$$
where $|\Sn|$ is the volume of the unit $n-1$ sphere.
Then, we have
\begin{equation*}
R\leq \min\Bigg\{M^{\frac{1}{n+2}}_{2}\left(M_{1}|\Sn|\left(\frac{a}{n+2}\right)\right)^{-\frac{1}{n+2}},
M^{\frac{1}{n+2s}}_{2}\left(M_{1}|\Sn|\left(\frac{b}{n+2s}\right)\right)^{-\frac{1}{n+2s}}\Bigg\}.        
\end{equation*}
Using the polar decomposition, we have one
$$\int_{\Rn}g(z)\dx z= \frac{M_{1}}{n}|\Sn|R^{n}, \,\,\,\text{for}\,\,\,R>0.$$
Combining \eqref{inlemfor2} with the last facts, we conclude
\begin{equation*}
\begin{split}
    \int_{\Rn}f(z)\dx z&\leq \int_{\Rn}g(z)\dx z\\&
    = M_{1}|\Sn|\frac{R^{n}}{n}\\&
    \leq  \frac{M_{1}|\Sn|}{n}\max\Bigg\{M^{\frac{1}{n+2}}_{2}\left(M_{1}|\Sn|\left(\frac{a}{n+2}\right)\right)^{-\frac{1}{n+2}},\\&
M^{\frac{1}{n+2s}}_{2}\left(M_{1}|\Sn|\left(\frac{b}{n+2s}\right)\right)^{-\frac{1}{n+2s}}\Bigg\}^{n},
\end{split}
\end{equation*} which completes the proof.\end{proof}
In the next we recall the fractional Sobolev inequality.
\begin{theorem}[The fractional Sobolev inequality, Theorem 6.5, \cite{DVP12}]
    Let $s\in(0,1)$ be  such that $n>2s$. Then for any measurable and compactly supported function $u$, we have
    \begin{equation}\label{fracsob}
    \|u\|_{L^{2^{*}_{s}}(\mathbb{R}^{n})}\leq C_{B,s}\left(\int_{\mathbb{R}^{n}}\int_{\mathbb{R}^{n}}\frac{|u(x)-u(y)|^{2}}{|x-y|^{n+2s}}\dx x\dx y\right)^{\frac{1}{2}},
\end{equation}
where $ 2^{*}_{s}=\frac{2n}{n-2s}$ and $C_{B,s}$ is the best constant of the fractional Sobolev inequality, and has the following form:
\begin{equation}\label{best}
    C_{B,s}=2^{-s}\pi^{-\frac{s}{2}}\frac{\Gamma^{\frac{1}{2}}\left(\frac{n-2s}{2}\right)}{\Gamma^{\frac{1}{2}}\left(\frac{n+2s}{2}\right)}\left(\frac{\Gamma(n)}{\Gamma\left(\frac{n}{2}\right)}\right)^{\frac{s}{n}}.
\end{equation}
\end{theorem}

Hence, we have the following:
\begin{theorem}
    Let $s\in(0,1)$ be  such that $n>2s$ and $ 2^{*}_{s}=\frac{2n}{n-2s}$. Then for any measurable and compactly supported function $u$, we have 
    \begin{align}\label{typpoin}
   \int_{\Omega}|u(x)|^{2}\dx  CC^{2}_{B,s}|\Om|^{1-\frac{2}{2_{s}^{*}}}|\nabla u(x)|^{2}\dx x,
\end{align}
and if $s=1$, we have
\begin{align}\label{typpoin1}
    \int_{\Omega}|u(x)|^{2}\dx x\leq C^{2}_{B,1}|\Om|^{1-\frac{2}{2^{*}}}\int_{\Omega}|\nabla u(x)|^{2}\dx x,
\end{align}
\end{theorem}
\begin{proof}
By using H\"{o}lder's inequality with $\left(1-\frac{2}{2_{s}^{*}}\right)+\frac{2}{2_{s}^{*}}=1$ and the fractional Sobolev inequality \eqref{fracsob}, we have
\begin{align}
    \nonumber \int_{\Omega}|u(x)|^{2}\dx x&\leq |\Om|^{1-\frac{2}{2_{s}^{*}}}\left(\int_{\Omega}|u(x)|^{2_{s}^{*}}\dx x\right)^{\frac{2}{2_{s}^{*}}}\\& 
    \nonumber \leq C^{2}_{B,s}|\Om|^{1-\frac{2}{2_{s}^{*}}}\int_{\Omega}\int_{\Omega}\frac{|u(x)-u(y)|^{2}}{|x-y|^{n+2s}}\dx x\dx y\\&
    \nonumber\stackrel{\eqref{hsh1}}\leq CC^{2}_{B,s}|\Om|^{1-\frac{2}{2_{s}^{*}}}|\nabla u(x)|^{2}\dx x.
\end{align}
In addition for $s=1$, we get
\begin{align}\
    \nonumber\int_{\Omega}|u(x)|^{2}\dx x&\leq |\Om|^{1-\frac{2}{2^{*}}}\left(\int_{\Omega}|u(x)|^{2^{*}}\dx x\right)^{\frac{2}\nonumber{2^{*}}}\\&\leq C^{2}_{B,1}|\Om|^{1-\frac{2}{2^{*}}}\int_{\Omega}|\nabla u(x)|^{2}\dx x,
\end{align}
where $n>2$ and $2^{\ast}=\frac{2n}{n-2}.$    
\end{proof}

In the pioneering paper  \cite[p. 406]{Lia07}, A. Lyapunov  proved that  if 
$u$ is a nontrivial solution to the boundary value problem:
\begin{equation}\label{1}\left\{\begin{array}{l}u''(t)+q(t)u(t)=0,\,a<t<b,\\ u(a)=u(b)=0,\end{array}\right.
\end{equation} where $q\in C\left([a,b];\mathbb{R}\right),$ then the following inequality holds:
\begin{equation}\label{2}\int\limits_{a}^{b}\left|q(s)\right|ds>\frac{4}{b-a}.\end{equation}
 This inequality, referred to as \eqref{2}, is known as the (classical) Lyapunov inequality. Furthermore, the constant $4$ in \eqref{2} is optimal, meaning it cannot be replaced by a larger number.

As a consequence of \eqref{2}, we can derive a lower bound for the first eigenvalue of \eqref{1} when $q(x)=\lambda$ for some $\lambda\in\mathbb{R}_{+}$, namely:

\begin{equation*}
    \lambda_{1}>\frac{4}{(b-a)^{2}}.
\end{equation*}

In the multi-dimensional case, De Napoli and Pinasco (see \cite{DP16}) considered the $p$-Laplacian-Dirichlet problem
\begin{equation}\label{problem2-eucl}
    \begin{cases}
    -\Delta_p u(x)=\lambda u(x),\,\,\,\,\,x\in\Om,\,\,\,\,\,p>1,\\
    u(x)=0,\,\,\,\,x\in\partial\Omega,
    \end{cases}
\end{equation}
 where $\Delta_p u=\text{div} \left(|\nabla u|^{p-2}\nabla u\right)$ is a $p$--Laplace operator. The authors  showed an application of the Lyapunov-type inequality, obtaining lower bounds for the first eigenvalue  and  stated below: 

\begin{theorem}
Let $\lambda_{1}$ be the first eigenvalue of 
\begin{equation*}
    -\Delta_{p}u(x)=\lambda|u(x)|^{p-2}u(x),
\end{equation*}
in $\Om$ with zero Dirichlet condition in $\partial \Om$. Then,
\begin{itemize}
    \item if $N>p$ and $s>\frac{N}{p}$, we have
    \begin{equation}
        \lambda_{1}\geq  \frac{C_{H}^{-\alpha p}C_{S}^{-\frac{Np}{N-p}(1-\alpha)}}{r^{\frac{sp-N}{s}}_{\Om}|\Om|^{\frac{1}{s}}},
    \end{equation}
    where $C_{H}$ and $C_{S}$ are the best constants of Hardy and Sobolev inequalities, respectively and $\alpha=\frac{\frac{Np}{N-p}-s'p}{\frac{Np}{N-p}-p}$ with $\frac{1}{s}+\frac{1}{s'}=1$;
    \item if $N<p$, we have
    \begin{equation}\label{eucmor}
        \lambda_{1}\geq \frac{C_{M}}{r^{p-N}_{\Om}|\Om|},
    \end{equation}
    where $C_{M}$ is the best constant of the Morrey inequality.
\end{itemize}
\end{theorem} The Lyapunov-type inequality and its corollary for the fractional Laplacian and Dirichlet boundary condition were investigated in \cite{JKS17}.

In the next theorem, we show the Berezin-Li-Yau inequality in the case $a>0$ and $b<0$ such that $\frac{b}{a}>-\frac{1}{C_{E}}$ where $C_{E}$ is defined in \eqref{hsh1}.
\begin{theorem}
  Assume that $\lambda_{k}$ is the $k$-th eigenvalue of \eqref{mainproblem} with $a>0$ and $b<0$ such that $\frac{b}{a}>-\frac{1}{C_{E}}$. Then,  for any bounded domain $\Omega \subset \Rn$, we have 
    \begin{equation}
  \sum_{i=1}^{k}\lambda_{i}\geq \max\left\{\frac{4(a+C_{E}b)\pi n}{n+2}\left(\frac{\Gamma\left(1+\frac{n}{2}\right)}{|\Omega|}\right)^{\frac{2}{n}}k^{1+\frac{2}{n}},\frac{(4\pi)^{s}(a+C_{E}b)n}{(n+2s)C_{E}}\left(\frac{\Gamma\left(1+\frac{n}{2}\right)}{|\Omega|}\right)^{\frac{2s}{n}}k^{1+\frac{2s}{n}}\right\}.
    \end{equation}
\end{theorem}
\begin{proof}
  Similarly to the proof of the previous theorem, we have 
    \begin{equation*}\label{thmfor21}
     f(\xi):=   \sum_{i=1}^{k}|\hat{u}_{i}(\xi)|^{2},
    \end{equation*}
    where $\hat{u}$ is the Fourier transform of $u$. 
    By the Plancherel equality and orthonormality of the system of eigenfunctions $\{u_{k}\}_{k=1}^{\infty}$ on $L^{2}(\Om)$ and \eqref{hsh1}, we have:
    \begin{equation}\label{thmfor23}
        \begin{split}
      \left(1+\frac{bC_{E}}{a}\right)\int_{\Rn}|\xi|^{2}f(\xi)\dx \xi&= \left(1+\frac{bC_{E}}{a}\right)\sum_{i=1}^{k} \int_{\Rn}|\xi|^{2}|\hat{u}_{i}(\xi)|^{2}\dx \xi \\&
      =\sum_{i=1}^{k} \left(1+\frac{bC_{E}}{a}\right)\|\nabla u_{i}\|^{2}_{L^{2}(\Om)}\\&
      \leq a^{-1}\sum_{i=1}^{k}\left(a\|\nabla u_{i}\|^{2}_{L^{2}(\Om)}+b\int_{\Omega}\int_{\Omega}\frac{|u_{i}(x)-u_{i}(y)|^{2}}{|x-y|^{n+2s}}\dx x\dx y\right)\\&
      =a^{-1}\sum_{i=1}^{k} \lambda_{i}.
        \end{split}
    \end{equation}
  and  similarly,
    \begin{equation}\label{thmfor24}
      \left(\frac{1}{C_{E}}+\frac{b}{a}\right)\int_{\Rn}|\xi|^{2s}f(\xi)\dx \xi\leq a^{-1}\sum_{i=1}^{k} \lambda_{i}.
    \end{equation}
    Combining  \eqref{thmfor2} and \eqref{thmfor23} with $M_{1}=(2\pi)^{-n}|\Omega|$ and  $M_{2}=\frac{1}{(a+C_{E}b)}\sum\limits_{i=1}^{k} \lambda_{i}$, and fixing $M_{1}=(2\pi)^{-n}|\Omega|$ and  $M_{2}=\frac{C_{E}}{a+C_{E}b}\sum\limits_{i=1}^{k} \lambda_{i}$ in Lemma \ref{lem1} , we get
    \begin{equation*}
        \begin{split}
          \sum_{i=1}^{k}\lambda_{i}\geq \max\left\{\frac{4\pi (a+C_{E}b) n}{n+2}\left(\frac{\Gamma\left(1+\frac{n}{2}\right)}{|\Omega|}\right)^{\frac{2}{n}}k^{1+\frac{2}{n}},\frac{(4\pi)^{s}(a+C_{E}b)n}{(n+2s)C_{E}}\left(\frac{\Gamma\left(1+\frac{n}{2}\right)}{|\Omega|}\right)^{\frac{2s}{n}}k^{1+\frac{2s}{n}}\right\}.
        \end{split}
    \end{equation*}
completing the proof.
\end{proof}
\begin{corollary}
By the non-decreasing monotonicity of $k\rightarrow \lambda_{k}$, we have that
    $$\lambda_{k}\geq \max\left\{\frac{4\pi (a+C_{E}b) n}{n+2}\left(\frac{\Gamma\left(1+\frac{n}{2}\right)}{|\Omega|}\right)^{\frac{2}{n}}k^{\frac{2}{n}},\frac{(4\pi)^{s}(a+C_{E}b)n}{(n+2s)C_{E}}\left(\frac{\Gamma\left(1+\frac{n}{2}\right)}{|\Omega|}\right)^{\frac{2s}{n}}k^{\frac{2s}{n}}\right\}.$$
\end{corollary}

The following result provides a comprehensive characterisation of the eigenvalues and their corresponding eigenfunctions of \eqref{mainproblem}.
\begin{proposition}\cite[Proposition 1]{MMV23}
If $a>0$ and $b\neq0$, the following statements hold true:
\begin{itemize}
    \item [a)] There exists $C>0$, which thhe eigenvalues of \eqref{mainproblem} with  admits divergent and 
    $$-C<\lambda_{1}\leq\lambda_{2}\leq \ldots \leq \lambda_{k}\rightarrow +\infty,\,\,\,\,\text{as}\,\,\,k\rightarrow +\infty.$$
    Moreover, for every $k \in \mathbb{N}$, $\lambda_{k}$ can be characterised as

    \begin{equation}\label{replam}
        \lambda_{k}=\min\limits_{u\in \mathbb{P}_{k},\,\|u\|_{L^{2}}=1}\left\{a\int_{\Om}|\nabla u|^{2}\dx x+b\int_{\Om}\int_{\Om} \frac{
     |u(x)-u(y)|^{2}}{|x-y|^{n+2s}}\dx x\dx y\right\},
    \end{equation}
     where $\mathbb{P}_{1}:=\mathbb{X}(\Om),$ and for every $k\geq 2,$
     $$\mathbb{P}_{k}:=\{u\in\mathbb{X}(\Om):\mathcal{B}_{\Om,s}(u,u_{j})=0\,\,\,\text{for\,\,every}\,j=1,2,\ldots,k-1\};$$
    \item [b)] for every $k \in \mathbb{N}$ there exists an eigenfunction $u_{k} \in \mathbb{X}(\Om)$ corresponding to
$\lambda_k$, which realizes the minimum in \eqref{replam};
\item[c)] the sequence $\{u_k\}_{k=1}^{\infty}$ of eigenfunctions constitutes an orthonormal basis of
$L^2(\Om)$. Moreover, the eigenfunctions are $\mathcal{B}$-orthogonal;
\item[d)] for every $k \in \mathbb{N}$, $\lambda_k$ has finite multiplicity.
\end{itemize}
\end{proposition}

