We now introduce a reflection operation on lattice paths associated with the $\mathbf{m}$-free monomials. We will subsequently prove that those lattice paths whose reflections remain admissible correspond bijectively to the $\mathbf{m}$-free monomials in the initial ideal of $I_{n,\mathbf{m},k}$.



\begin{definition}\label{def:reflect}
Let $(a, b)\in \mathbb{Z}^2$ be a lattice point with $0\leq a \leq n$. Reflecting this point at the intersection of the graph of $L_{n,\mathbf{m},k}$ and the vertical line $x = a$ yields a new point $(a, b')$, where
\[
b'= b - 2(b - L_{n,\mathbf{m},k}(a)).
\]
We denote this reflection by $(a,b)' := (a,b')$.
Now consider an $\mathbf{m}$-admissible lattice path $\mathbf{P}$ associated with an $\mathbf{m}$-free term of degree $d$, with vertices $P_0 = (0,0), P_1, \ldots, P_n = (n, n - d)$.
We say that the path $\mathbf{P}$ is \emph{critical} if there exists an index $0 \leq i \leq n$ such that the path  
\[
    {^i\mathbf{P}'} := (P_0, P_1, \ldots, P_{i-1}, P_i', P_{i+1}', \ldots, P_n')
\]  
is also $\mathbf{m}$-admissible.
For each critical path $\mathbf{P}$, define $\lambda(\mathbf{P})$ to be the \emph{maximal} index $i$ for which ${^i\mathbf{P}'}$ remains $\mathbf{m}$-admissible. The \emph{reflection map} associated with %the data 
$(n,\mathbf{m},k)$ is then~defined~as  
\begin{equation*}\label{eq:Reflection_map_for_paths}
    \Lambda : \{ \mathbf{P} \mid \mathbf{P} \text{ critical and } \mathbf{m}\text{-admissible} \}
    \to \{ \mathbf{P} \mid \mathbf{P} \text{ $\mathbf{m}$-admissible} \}, \quad \mathbf{P} \mapsto {^{\lambda(\mathbf{P})}\mathbf{P}'}.
\end{equation*}
\end{definition}


