\begin{lemma}\label{lem:revlex_segment}
    Let $s \in M_{n,\mathbf{m},k}$ be a minimal generator of degree $d$. Let $t$ be any monomial of degree $d$ such that $t \succ s$ with respect to the reverse lexicographic ordering. Then $t \in (M_{n,\mathbf{m},k})$.
\end{lemma}
\begin{proof}
    Without loss of generality, we may assume that $x_n$ divides $s$. Otherwise, if the variable of largest index dividing $s$ is $x_{n_1}$ and $\mathbf{m}_1$ denotes the vector consisting of the first $n_1$ entries of $\mathbf{m}$, then $s \in M_{n_1, \mathbf{m}_1, k}$. In this case, both $s$ and all monomials $t$ of degree $d$ with $t \succ s$ lie in $\mathbf{k}[x_1,\ldots,x_{n_1}]$, reducing the problem to fewer variables.

    Hence, we may assume the last edge $AB$ in the lattice path associated with $s$ does not go up. By Lemma~\ref{lem:MinGens_no_path_vertex_below}, the endpoint $B$ lies on or above the red path. Let $B'$ be the reflection of $B$. Denote by $CD$ the last edge of the path associated with $t$.
    Since $s$ is a minimal generator, Lemma~\ref{lem:MinGens_no_path_vertex_below}(ii) guarantees that the slope of $AB'$ is admissible. If $CD = AB$, then $CD'$ is admissible, and hence $t \in (M_{n,\mathbf{m},k})$.
    Otherwise, since $t \succ s$ and $\deg(t) = \deg(s)$, the paths of $t$ and $s$ share the common endpoint $B = D = (n, n-d)$. We may write $A = (n-1, n - d + \delta)$ and $C = (n-1, n - d + \epsilon)$ for some positive integers with $\epsilon < \delta$.
    Two cases arise:

    Case 1. If $C$ lies on or below the red path, then because the path of $t$ starts above the red path, it must contain an edge $EF$ ending on or crossing the red path. For such an edge, $EF'$ (where $F'$ is the reflection of $F$) is admissible, so $t \in (M_{n,\mathbf{m},k})$.

    Case 2. If $C$ lies above the red path, then since $B'$ lies on or below the red path, the slope of $CB'$ is negative but of smaller absolute value than the negative admissible slope of $AB'$. Hence, $CB'$ is admissible, and again $t \in (M_{n,\mathbf{m},k})$.
\end{proof}

Before stating the last result of this section, we need to recall the following definition.

\begin{definition}
Let $I$ be an ideal generated by a set $V$ of $\mathbf{m}$-free monomials. Then $I$ is called \emph{strongly $\mathbf{m}$-stable} if for any $sx_j\in V$ and any index $i<j$, if $sx_i$ is $\mathbf{m}$-free, then $sx_i\in I$.
\end{definition}

Lemma~\ref{lem:revlex_segment} yields the following result, resolving a problem posed in~\cite{kling2024grobnerbasesresolutionslefschetz}.

\begin{corollary}\label{cor:m_stability}
The $\mathbf{m}$-free part of the ideal $(M_{n,\mathbf{m},k})$ is strongly $\mathbf{m}$-stable.
\end{corollary}
\begin{proof}
Let $s \in M_{n,\mathbf{m},k}$ be an $\mathbf{m}$-free minimal generator. Clearly, $s \neq 1$. Let $x_j$ be the variable of highest index dividing $s$. Then $s \in M_{j,\mathbf{m},k}$. 
Now, let $x_i$ be a variable with $i < j$ such that $s_i+1 < m_i$, and let $x_\ell$ be a variable dividing $s$ with $i < \ell$. Set $t=x_i(s/x_\ell)$.    
We need to show that $t$ has a divisor in $M_{n,\mathbf{m},k}$. It suffices to find such a divisor in $M_{j,\mathbf{m},k}$.
Since $\deg(t) = \deg(s)$ and $t \succ s$ in the reverse lexicographic ordering, the existence of this divisor follows immediately from Lemma~\ref{lem:revlex_segment}.
\end{proof}

\section{Gr\"obner bases}\label{sec:GB}


This section contains our main results. We begin by showing that the  ideal $(M_{n,\mathbf{m},k})$, generated by the monomials corresponding to critical $\mathbf{m}$-admissible lattice paths and variable powers introduced in Section~\ref{sec:InitialIdeal}, coincides with the initial ideal of $I_{n,\mathbf{m},k}$ with respect to the reverse lexicographic order induced by $x_1 \succ \cdots \succ x_n$ 
(Theorem~\ref{thm:Initial_Ideal_Equality}). We further prove that this equality holds for any term order compatible with this variable ordering (Theorem~\ref{thm:GB_determined_by_var_ranking}). In particular, $\operatorname{in}(I_{n,\mathbf{m},k}) = (M_{n,\mathbf{m},k})$. As a direct consequence, we provide a new proof that all monomial complete intersections possess the Strong Lefschetz Property over fields of characteristic zero (Corollary~\ref{cor:has_SLP}). We also describe the reduced Gr\"obner basis of $I_{n,\mathbf{m},k}$ and establish Theorem~\ref{thm:Main_Thm_Introduction} from the introduction.
In \S\ref{sub:var}, we establish an upper bound on the number of distinct reduced Gr\"obner bases of $I_{n,\mathbf{m},k}$. When the ideal $P_{n,\mathbf{m}}$ is equigenerated, we determine the exact number of such bases (Proposition~\ref{prop:Cardinality_GFan_Equigenerated}). We then study the degree sequences of the elements in these Gr\"obner bases. In particular, Proposition~\ref{prop:GB_degree_element_count_sequences_general_case} provides an efficient method for computing the degree sequences via differences of Hilbert series coefficients of $R/P_{n,\mathbf{m}}$.


\subsection{Initial ideal}
Throughout, for a monomial $p$, we write $p_i$ for the exponent of $x_i$ in $p$, so that $p = x_1^{p_1} \cdots x_n^{p_n}$.  
Our first goal is to construct, for each $s \in M_{n,\mathbf{m},k}$ that corresponds to an $\mathbf{m}$-free generator of $(M_{n,\mathbf{m},k})$, a polynomial $g_s \in I_{n,\mathbf{m},k}$ such that $\operatorname{in}(g_s) = s$.  
The key technical ingredient for this construction is provided by the following lemma.


\begin{lemma}
\label{lem:Counting_lemma}
Let $p$, $q$, and $r$ be monomials such that $pq = x_1^{\alpha_1} \cdots x_n^{\alpha_n}$ and $r|pq$.  Then
\begin{equation}\label{eq:formula}
\sum_{\substack{v| p \\ v|r}} (-1)^{\deg(v)}\left(\prod_{i=1}^n\binom{r_i}{v_i}\binom{\alpha_i-v_i}{p_i-v_i} \right) = \prod_{i=1}^n \binom{\alpha_i-r_i}{p_i}.
\end{equation}
\end{lemma}

\begin{proof}
First, consider the case $n=1$. We then have integers $p, q,$ and $r$ such that $p + q = \alpha$ and $r \leq \alpha$. The identity to prove reduces to
\begin{equation}
\label{eq:n=1_inclusion_exclusion}
\sum_{k=0}^{\infty} (-1)^k \binom{r}{k} \binom{\alpha - k}{p - k} = \binom{\alpha - r}{p}.
\end{equation}
Formally, the summation index should be restricted to $k \leq \min\{p,r\}$. However, since the terms vanish for $k > \min\{p,r\}$, extending the sum to infinity does not affect its value.

The right-hand side of \eqref{eq:n=1_inclusion_exclusion} counts the number of ways to choose $p$ elements from a set of size $\alpha$, excluding a subset of $r$ forbidden elements. The term $\binom{r}{k} \binom{\alpha - k}{p - k}$ counts the number of ways to choose exactly $k$ forbidden elements and $p-k$ from the remaining elements. The alternating sum corresponds exactly to the inclusion-exclusion principle, thereby proving the identity.

For general $n$, we apply the case $n = 1$ coordinatewise, adopting the convention that $\binom{n}{k} = 0$ whenever $k < 0$ or $k > n$.  
By interchanging the order of summation and product, the left-hand side of~\eqref{eq:formula} becomes
\[
\sum_{v} \prod_{i=1}^n (-1)^{\deg(v_i)} \binom{r_i}{v_i} \binom{\alpha_i - v_i}{p_i - v_i} 
= \prod_{i=1}^n \left( \sum_{v_i=0}^\infty (-1)^{\deg(v_i)} \binom{r_i}{v_i} \binom{\alpha_i - v_i}{p_i - v_i} \right) 
= \prod_{i=1}^n \binom{\alpha_i - r_i}{p_i},
\]
as desired.
\end{proof}

\begin{setup}\label{setup_for_main_theorem}
Let $s =x_1^{s_1}\cdots x_n^{s_n}= s' x_n^{s_n}\in R$ be a monomial satisfying the conditions
\begin{itemize}[leftmargin=2em]
    \item $s_n > 0$,
    \item $s_n = 2 \deg(s) - k - \sum_{i=1}^{n-1} m_i + (n - 1)$,
    \item $s' \mid x_1^{m_1 - 1} \cdots x_{n-1}^{m_{n-1} - 1}$.
\end{itemize}
Next, let 
$R' = \mathbf{k}[x_1, \dots, x_{n-1}, y] \big/ (x_1^{m_1}, \dots, x_{n-1}^{m_{n-1}})$
and set
$\ell = x_1 + \cdots + x_{n-1} + y$. We can then associate to $s$ two polynomials $f_s$ and $g_s$ in $R'$, defined as follows.

\begin{itemize}
\item[{\rm (i)}] \textbf{Construction of $g_s$:} Let 
\[
g_s = \sum_{s'' \mid s'} \lambda_{s''} \cdot s'' \cdot y^{\deg(s) - \deg(s'')},
\]
where for each monomial $s'' \mid s'$, we define
\[ 
\lambda_{s''} = \left( \prod_{i=1}^{n-1} \frac{s_i!}{s''_i!} \binom{m_i - s''_i - 1}{s_i - s''_i} \right) \cdot \frac{s_n!}{(\deg(s) - \deg(s''))!}.
\] 

\item[{\rm (ii)}]  \textbf{Construction of $f_s$:} Let $u$ be the unique monomial such that 
\[
u \cdot s' = x_1^{m_1 - 1} \cdots x_{n-1}^{m_{n-1} - 1}.
\]
Then define
\[
f_s = \sum_{v \mid u} \mu_v \cdot v \cdot \ell^{\deg(s) - \deg(v) - k},
\]
where for each monomial $v \mid u$, we set
\[
\mu_v = (-1)^{\deg(v)} \left( \prod_{i=1}^{n-1} \frac{s_i!}{v_i!} \binom{m_i - 1 - v_i}{u_i - v_i} \right) \cdot \frac{s_n!}{(\deg(s) - \deg(v))!}.
\]
\end{itemize}
\end{setup}

