\section{Derksen-Weyman saturation theorem}
%=============================================================================
In this section, we give our proof of the saturation theorem of Derksen-Weyman~\cite{MR1758750}.
The theorem states that the following semigroup is satured and gives a concrete description in terms of linear inequalities.

\begin{definition}
Let $\CV$ be a family of vector spaces with dimension vector~$\vn$.
Define $\Sigma_{\rep,Q}(\vn) \subset \Lambda$ as the semigroup consisting of the weights $\vsigma$ such that there exists a non-zero semi-invariant polynomial of weight $\vsigma$ on $\CH_Q(\CV)$.
\end{definition}

\begin{theorem}\label{theo:sat}
$\Sigma_{\rep,Q}(\vn)=\Sigma_{\geo,Q}(\vn)\cap \Lambda$.
\end{theorem}

To prove the theorem, we can assume without loss of generality that $n_x > 0$ for all $x \in Q_0$.
Indeed, if we denote by $Q'$ the quiver obtained by removing all vertices~$x$ with~$n_x = 0$, and by $\vn', \vsigma'$ the dimension vector and weight with all corresponding entries removed, then it is immediate that $\vsigma \in \Sigma_{\rep,Q}(\vn)$ if and only if $\vsigma' \in \Sigma_{\rep,Q'}(\vn')$, and likewise for $\Sigma_{\geo,Q}(\vn)$.

The main ingredient in our proof is the observation that if a weight~$\vsigma$ satisfies King's inequalities for~$\vn$ (\cref{def:Kingcone}), $\vA \coloneqq L_1^{-1}(\vsigma)$ is a dimension vector that satisfies Schofield's inequalities for~$\vA + \vn \twoheadrightarrow_Q \vn$ (\cref{theo:crit}).
Recall that $\vA = L_1^{-1}(\vsigma)$ means that $\Euler_Q(\vA,\vxi) = \langle \vsigma,\vxi \rangle$ for all $\vxi\in \z_Q$.

\begin{proposition}\label{pro:king vs schofield}
Let $\vsigma\in \Sigma_{Q,\geo}(\vn) \cap \Lambda$.
Then, $\vA \coloneqq L_1^{-1}(\vsigma)$ is a dimension vector and it holds that~$\Euler_Q(\vA, \vgamma) \geq 0$ for every dimension vector~$\vgamma$ such that $\vn \twoheadrightarrow_Q \vgamma$.
Moreover, it holds that~$\Euler_Q(\vA, \vn) = 0$.
\end{proposition}
\begin{proof}
In \cref{lem:main} below, we prove that~$\vA$ is a dimension vector.
Now the remaining claims follows immediately from $\Euler_Q(\vA,\cdot) = \langle \vsigma, \cdot \rangle$ and the defining inequalities and equation of $\Sigma_{Q,\geo}(\vn)$.
% it is easy to deduce the claim from the inequalities and the equation defining~$\Sigma_{Q,\geo}(\vn)$ (\cref{def:Kingcone}): we have
% \begin{equation*}
%   \Euler_Q(\vA, \vn) = \langle \vsigma, \vn \rangle = 0
% \end{equation*}
% and, for every~$\vgamma$ such that~$\vn \twoheadrightarrow_Q \vgamma$,
% \begin{equation*}
%   \Euler_Q(\vA, \vgamma) = \langle \vsigma, \vgamma \rangle \geq 0.
%   \qedhere
% \end{equation*}
\end{proof}

It remains to prove the central lemma used in the above proof.

\begin{lemma}\label{lem:main}
If $\vsigma\in \Sigma_{Q,\geo}(\vn) \cap \Lambda$, then $\vA \coloneqq L_1^{-1}(\vsigma)$ is a dimension vector.
That is, $\vA \in \Gamma$ and $A_x \geq 0$ for all $x \in Q_0$.
\end{lemma}

\begin{proof}
Because~$L_1$ is an isomorphism between~$\Gamma$ and~$\Lambda$, we already know that~$\vA \in \Gamma$, so it remains to prove that it is entrywise nonnegative.
Because~$Q$ is acyclic, we can enumerate the vertices as~$Q_0 = \{x_1,\dots,x_K\}$ in a topological order.
% \MW{I would almost find it easier to just call the vertices $1,\dots,K$, and refer to all matrix entries as $M_{ij}$... but note that $m_{ij} = M_{ji}$.}
That is, if $m_{ij}$ denotes the number of arrows from $x_i$ to $x_j$ then we have $m_{ij} = 0$ if $i > j$.
Define the map
\[ M \colon \z_Q \to \z_Q, \quad M(\vdelta_{x_i}) = \sum_{i < j} m_{ij} \vdelta_{x_j} = \sum_{a : x_i \to x_j \in Q_1} \vdelta_{x_j}. \]
Let $\Iso \colon \z_Q^*\to \z_Q$ denote the map such that $\Iso(\vdelta^x)=\vdelta_x$ for all $x \in Q_0$.
Then we have
\[ \Euler_Q(\valpha, \Iso(\vtau)) = \langle \vtau, (I - M) \valpha \rangle
\qquad (\forall \valpha \in \z_Q, \vtau \in \z_Q^*)
\]
Observe that $M$ is strictly lower triangular.
Hence $I - M$ is invertible and its inverse is again an integer matrix:
\begin{align*}
  P \coloneqq (I - M)^{-1} = \sum_{k=0}^K M^k.
\end{align*}
Observe that $P\vdelta_{x_i} =\sum_j  p_{ij}\vdelta_{x_j}$, with $p_{ij}$ the number of paths from~$x_i$ to~$x_j$.
By convention, the number of paths of length~$0$ is $1$, so $p_{ii}=1$.
We have $p_{ij}=0$ if~$i>j$.
In particular,
\begin{align}\label{eq:A}
  \vA = (I - M)^{-1} \Iso(\vsigma) = P \Iso(\vsigma),
\end{align}
that is,
\begin{align*}
  A_{x_k} = \sigma_{x_k} + \sum_{i < k} p_{ik} \sigma_{x_i}.
\end{align*}
% We need to prove that $A_{x_k}\geq 0$ for every $k$.%
To prove that ${A}_{x_k}\geq 0$, we will use the inequalities $\langle \vsigma,\vbeta\rangle \geq 0$ for natural Schofield subdimension vectors  $\vbeta\hookrightarrow_{Q^*}\vn$.%
\footnote{Note that since $x_1$ is minimal, we have $A_{x_1}=\sigma_{x_1} \geq 0$ by \cref{lem:min}.}
To this end we consider subrepresentations generated by nonzero vectors $0\neq v_k\in \CV^*_{x_k}$ (such vectors exist since $n_{x_k} > 0$).
Let $s=(s_a)_{a\in Q_1^*}\in \CH_{Q^*}(\CV^*)$.
If~$j<k$ and~$p$ is any path from~$x_k$ to~$x_j$ in the quiver~$Q^*$, we denote by~$s_p\in \Hom(\CV^*_{x_k},\CV^*_{x_j})$
the composition of the matrices~$s_a$ along the path~$p$.
Denote by $\Sub(v_k,s,x_j)$ the subspace of~$\CV_{x_j}^*$ generated by the elements~$s_p(v_k)$ of $\CV_{x_{j}}^*$, where $p$ runs on all paths from~$x_k$ to~$x_j$ in~$Q^*$.
Because in the quiver~$Q^*$ we have $p_{jk}$ paths from~$x_k $ to~$x_j$, the dimension of this subspace is less or equal to~$p_{jk}$.%
\footnote{If all entries of the dimension vector $\vn$  are sufficiently large, then the dimension of this subspace is equal to $p_{jk}$ for generic $s$.}
For $j=k$, define  $\Sub(v_k,s,x_j)=\C v_k$.
For $j>k$, define  $\Sub(v_k,s,x_j)=0$.
By construction, for any $v_k\in \CV_{x_k}^*$, the family $\CS(v_k,s)$
of subspaces $\CS(v_k,s)_{x_j}=\Sub(v_k,s,x_j)$ defines a subrepresentation of~$s$.
Let $t_{jk}$ denote the maximal dimension of $\Sub(v_k,s,x_j)$ when $s$ varies in $\CH_{Q^*}(\CV^*)$.
This maximum does not depend the choice of nonzero~$v_k$ in $\CV_{x_k}^*$, since we can conjugate $v_k$ to any other non-zero element by the action of $\GL_Q(\CV^*)$.
Thus, for any choice of~$v_k$ there is a Zariski open subset of~$s \in \CH_{Q^*}(\CV^*)$ such that $\dim \CS(v_k,s) = \vtheta_k$, where $\vtheta_k \coloneqq \sum_j t_{jk} \vdelta_{x_j}$.
It follows that~$\vtheta_k \hookrightarrow_{Q^*} \vn$, i.e., $\vn \twoheadrightarrow_Q \vtheta_k$, because $\vsigma \in \Sigma_{Q,\geo}(\vn)$ we see that%
\footnote{For $\vn$ large, $ \langle \vsigma, \vtheta_k\rangle =\sigma_k +\sum_{i<k} p_{ik} \sigma_i$, so is precisely equal to $A_{x_k}$, and hence $A_{x_k} \geq 0$.
So, at least when $\vn$ is large, \cref{lem:main} is clear.}
\[ \langle \vsigma, \vtheta_k \rangle \geq 0. \]
Define
\[ T\colon\z_Q \to \z_Q, \quad T(\vdelta_{x_i})=\sum_{i\leq j} t_{ij} \vdelta_{x_j}, \]
and consider
\begin{align*}
  W \coloneqq I - T(I - M) = (I - T) + TM
\end{align*}
We will now show that $W$ is entrywise nonnegative.%
\footnote{For $\vn$ large, $T=P=(I-M)^{-1}$, so $W=0$.}
The matrix~$W$ is strictly lower triangular since~$M$ and~$(I-T)$ are strictly lower triangular.
In fact:
\begin{align*}
  W(\vdelta_{x_i})
= -\sum_{i<k}t_{ik} \vdelta_{x_k}+\sum_{i<j\leq k}m_{ij}t_{jk} \vdelta_{x_k}
\end{align*}
Thus, the matrix~$W$ has nonnegative entries if and only if, for all $i < k$,
\begin{equation}\label{eq:nonneg}
  t_{ik} \leq \sum_{i<j\leq k} m_{ij} t_{jk} = m_{ik} + \sum_{i<j<k} m_{ij} t_{jk}.
\end{equation}
Recall that, for $s$ in a Zariski open subset of $\CH_{Q^*}(\CV^*)$, for all $k > i$, $t_{ik}$ is the dimension of the vector space $ \Sub(v_k,s,x_i) \subseteq \CV_{x_i}^*$  spanned by the vectors $s_p(v_k)$ where $p$ runs over all paths from~$x_k$ to~$x_i$ in $Q^*$.
There are $m_{ik}$ arrows from~$x_k$ to~$x_i$, hence the paths of length one contribute at most~$m_{ik}$ to~$t_{ik}$.
All other paths are composed of an arrow from~$x_k$ to some~$x_j$ and some path from~$x_j$ to~$x_k$, hence they contribute at most~$m_{ij} t_{jk}$, for any~$j$.
This proves \cref{eq:nonneg} and hence all entries of the matrix~$W$ are nonnegative.
% The paths going directly from $k$ to $i$ in one step are in numbers $m_{ik}$.
% So the  subspace of $L(i,k)$ obtained by  considering these one step paths is of dimension less or equal to $m_{ik}$.
% Otherwise we have at least two steps,
% and  paths are composed  of paths $q$ from  $x_k$ to $x_j$
% and paths $a:x_j$ to $x_i$  in numbers $m_{ij}$.
% The subspace of  $L(i,k)$ spanned by the vectors $s_a s_q v_k$ is thus of dimension less that
% $m_{i,j} t_{jk}$.

Now recall from \cref{eq:A} that $\vA = (I - M)^{-1} \Iso(\vsigma)$.
It follows that $W \vA = \vA - T \Iso(\vsigma)$ and hence
\begin{align*}
  \vA = W \vA + T \Iso(\vsigma) = W \vA + \sum_k \langle \vsigma, \vtheta_k \rangle \vdelta_{x_k},
\end{align*}
where $W$~is strictly lower triangular with nonnegative entries and $\langle \vsigma, \vtheta_k \rangle \geq 0$ for all~$k$.
Thus we must have $A_1 = \langle \vsigma, \vtheta_1 \rangle \geq 0$,%
\footnote{We note that this is equivalent to, and hence reproves, \cref{lem:min}.} and then it follows by induction that~$A_{x_k} \geq 0$ for all~$k$.
This concludes the proof.
\end{proof}

\begin{example}
Consider a quiver with $K=3$ vertices and
\[ M = \begin{bmatrix} 0&0&0\\ m_{{1,2}}&0&0
\\ m_{{1,3}}&m_{{2,3}}&0\end{bmatrix}. \]
Then,
\begin{align*}
  P&=\begin{bmatrix} 1&0&0\\ m_{{1,2}}&1&0
\\ m_{{2,3}}m_{{1,2}}+m_{{1,3}}&m_{{2,3}}&1
\end{bmatrix},
\qquad
  T=\begin{bmatrix} 1&0&0\\ t_{{1,2}}&1&0
\\ t_{{1,3}}&t_{{2,3}}&1
\end{bmatrix},
\intertext{and}
W&=\begin{bmatrix} 0&0&0\\ -t_{{1,2}}+m_{{1
,2}}&0&0\\ t_{{2,3}}m_{{1,2}}+m_{{1,3}}-t_{{1,3}}&-t
_{{2,3}}+m_{{2,3}}&0\end{bmatrix}.
\end{align*}
\end{example}

\begin{proof}[Proof of \cref{theo:sat}]
The inclusion $\subseteq$ holds due to King's lemma (\cref{lem:king}).

For the converse inclusion $\supseteq$, let $\vsigma\in \Sigma_{Q,\geo}(\vn) \cap \Lambda$ and set $\vA \coloneqq L_1^{-1}(\vsigma)$.
\Cref{pro:king vs schofield}, along with Schofield's criterion (\cref{theo:crit}), implies that~$\vA + \vn \twoheadrightarrow \vn$.
The proposition also states that $\Euler_Q(\vA, \vn) = 0$.
Using \cref{cor:deter} (with~$\vA$, $\vN = \vA + \vn$, and $\vB = \vn$), we conclude that $C^{\vA,\vn}(v,\cdot)$ is a nonzero semi-invariant of weight~$\vsigma$ on~$\CH_Q(\CG)$ for generic $v \in \CH_Q(\CF)$, where $\dim\CF = \vA$ and $\dim\CG = \dim\CV = \vn$.
Thus, $\vsigma \in \Sigma_{\rep,Q}(\vn)$.
\end{proof}

