\title{A structure-preserving finite element framework for the Vlasov--Maxwell system} 


\author[1]{Katharina Kormann}
\ead{k.kormann@rub.de}
\author[2]{Murtazo Nazarov}
\ead{murtazo.nazarov@uu.se}
\author[2]{Junjie Wen\corref{cor1}}
