+ \|(\pmb{\mathsf{A}}^{\textrm{L},n})^{\frac12} \GRAD f^n_h\|^2
=
\frac{\tau_n}{2} \Big\|\frac{f^{n+1}_h - f^n_h}{\tau_n} \Big\|^2.
\end{equation}
