\| \pmb{\mathsf{A}}^{\textrm{L},n} \GRAD f^n_h \| \, C_1 k h_{\min}^{-1} \|w\|
\Bigg)
\\
&\, = 
\|\pmb{\bbetaa}_h^n \SCAL \GRAD f^n_h\| + \textcolor{black}{}
C_1 k h_{\min}^{-1} \| \pmb{\mathsf{A}}^{\textrm{L},n} \GRAD f^n_h \| \, 
\\
&\, = 
\|\pmb{\bbetaa}_h^n \SCAL \GRAD f^n_h\| + \textcolor{black}{}
C_2 k^\frac12 h_{\min}^{-\frac12} \|\pmb{\bbetaa}_h^n \|_{L^\infty(\Omega)}^{\frac12} \| (\pmb{\mathsf{A}}^{\textrm{L},n})^{\frac12} \GRAD f^n_h \| , 
\end{aligned} 
\end{equation*}
}
\end{comment}
The flux term in the last inequality can be estimated as:
\[
\|\pmb{\bbetaa}_h^n \SCAL \GRAD f^n_h\| 
\le
\|\pmb{\bbetaa}_h^n\|_{L^\infty(\Omega)}
\|\GRAD f^n_h\|
\le
\|(\pmb{\mathsf{A}}^{\textrm{L},n})^{-1} \|_{L^\infty(\Omega)}^\frac12
\|\pmb{\bbetaa}_h^n\|_{L^\infty(\Omega)}
\|(\pmb{\mathsf{A}}^{\textrm{L},n})^{\frac12} \GRAD f^n_h\|.
\]
Each components $z\in\{x , v \}$ of the viscosity matrix can be estimated as
\[
(\e^{\textrm{L},n}_{z_l})^{-1} = 
\Big( \sum_{j\in\calI} \big(\e^{\textrm{L},n}_{z_l}\big)_j \psi_j \Big)^{-1}
\le
2 k\, h_{\min}^{-1} \Big( \min_{j\in\calI} \|\pmb{\bbetaa}_h^n\|_{L^\infty(S(j))} \Big)^{-1},
\]
for every $l=1,\ldots,d_z$, where we also used the partition of unity property of $\psi_j$. Thus,
\[
\|\pmb{\bbetaa}_h^n \SCAL \GRAD f^n_h\| 
\le
C_3 k^\frac12\, h_{\min}^{-\frac12} \|\pmb{\bbetaa}_h^n\|_{L^\infty(\Omega)}^\frac12
\|(\textcolor{black}{\pmb{\mathsf{A}}^{\textrm{L},n}})^{\frac12} \GRAD f^n_h\|,
\]
where
\textcolor{black}{
$
C_3 := 
\Big(
2 \|\pmb{\bbetaa}_h^n\|_{L^\infty(\Omega)} 
\big(
\min_{j\in\calI} \|\pmb{\bbetaa}_h^n\|_{L^\infty(S(j))}
\big)^{-1}
\Big)^{\frac12}
$
}. 
Now, we multiply \eqref{eq:FO:l2} by $2\tau_n$ and collect all terms in \eqref{eq:Dtf} and obtain
\begin{equation}\label{eq:case1}
\|f^{n+1}_h\|^2 
+ 2\tau_n
\Big(
1 - C \tau_n k h_{\min}^{-1} \|\pmb{\bbetaa}_h^n\|_{L^\infty(\Omega)}
\Big)
\|(\pmb{\mathsf{A}}^{\textrm{L},n})^{\frac12} \GRAD f^n_h\|^2
\le
\|f^n_h\|^2,
\end{equation}
where $C:=\textcolor{black}{\frac{1}{2}(C_2+C_3)^2}$ is independent of the mesh size, then sum \eqref{eq:case1} over $n=0,1,\ldots, N_T$, and get the desired estimate.
\hfill $\square$
\end{proof}

\subsection{Nonlinear residual-based viscosity}\label{sec:RV}
We have proved that the scheme \eqref{eq:GFEM:visc} with the artificial viscosity coefficients defined in \eqref{eq:AV:L} is stable in the previous section. However, this choice of viscosity coefficients results in only a first-order convergent scheme; as introduced in \cite{wen2025anisotropicnonlinearstabilizationfinite}, it yields upwind schemes. In this section, we present a nonlinear construction of the viscosity coefficients that take into account the finite element residual of the Vlasov--Maxwell equations, following the approach in \cite{MR3011445, Nazarov_Hoffman_2013, MR4754161} and other references cited therein, where similar methods were applied to the compressible Euler and magnetohydrodynamic equations.

In many previous works \textcolor{black}{(see, for example, \cite{wen2025anisotropicnonlinearstabilizationfinite,MR3998292, MR4754161,MR4664977, MR4456197,MR4734518})} we usually seek the residual of equation \eqref{eq:vw:advection} through the following $L^2$-projection: find $ R^n(f_h):=\sum_{j\in\calI} R^n_j\psi_j\in \polV$ such that 
\begin{equation}\label{eq:residual}
(R^n,\psi_i)=\big(\big| D_{\tau} f^n_h+\pmb{\bbetaa}_h^n\SCAL\nabla f_h^n\big|, \psi_i\big),\qquad\forall i\in\calI,
\end{equation}
where $D_{\tau} f^n_h$ is a reasonable approximation of the time-derivative of $f_h$ at time level $t^n$. \textcolor{black}{Additional operations may be applied to \eqref{eq:residual}, such as lumping the mass matrix or adding smoothing terms.} Once the finite element residual is approximated, we construct the following high-order artificial viscosity matrices: $\pmb{\mathsf{A}}^{\textrm{H},n}:= \textrm{diag}(\mathsf{A}^{\textrm{H},n}_{{\pmb{x}}}, \mathsf{A}^{\textrm{H},n}_{{\pmb{v}}})$, $\mathsf{A}^{\textrm{H}, n}_{{\pmb{x}}}\in[\polV]^{d_{\pmb{x}}}:= \textrm{diag}(\e^{\textrm{H},n}_{x_1}, \ldots, \e^{\textrm{H},n}_{x_{d_{\pmb{x}}}})$, and $\mathsf{A}^{\textrm{H},n}_{{\pmb{v}}}\in[\polV]^{d_{\pmb{v}}}:= \textrm{diag}(\e^{\textrm{H},n}_{v_1}, \ldots, \e^{\textrm{H},n}_{v_{d_{\pmb{v}}}})$, where the nodal values of $\e^{\textrm{H},n}_{x_l}$ and $\e^{\textrm{H},n}_{v_l}$ are given by
\begin{equation}\label{eq:AV:L=H}
\begin{aligned}
\big(\e^{\textrm{H},n}_{x_l}\big)_i 
&= 
\min\Big(\big(\e^{\textrm{L},n}_{x_l}\big)_i,\Big(\frac{\Delta x_l}{k}\Big)^{2} \frac{|R_i^n|}{\Lambda_\Omega(f^n_h)}\Big), \\ 
\big(\e^{\textrm{H},n}_{v_l}\big)_i 
&= 
\min\Big(\big(\e^{\textrm{L},n}_{v_l}\big)_i,\Big(\frac{\Delta v_l}{k}\Big)^{2} \frac{|R_i^n|}{\Lambda_\Omega(f^n_h)}\Big),
\end{aligned}
\end{equation}
for every node $i=1,\ldots,N$ and $l = 1, \dots, d_\bz$, $\bz\in\{{\pmb{x}},{\pmb{v}}\}$. Here, $\Lambda_\Omega(f^n_h)$ is the normalization constant at $t = t_n$, which we define below. This constant is used to remove the scale of $f_h$ from the residual. Various normalization functions have been presented in the literature where entropy and residual-based stabilization were used. In this work, we define
\begin{equation}
     \Lambda_Q(w):= \big \| w - \overline{w} \big \|_{L^\infty(Q)},
     \notag
\end{equation}
where $\overline{w} = \frac{1}{|Q|} \int_{Q} w$ is the average of the solution in the domain $Q$. In practice, to avoid division by zero, one can normalize the residual 
$\frac{R^n_i}{\Lambda_\Omega(f^n_h)} \approx R^n_i \frac{\Lambda_\Omega(f^n_h)}{(\Lambda_\Omega(f^n_h))^2  + 10^{-14} \|f^n_h\|^2_{L^{\infty}(\Omega)}}$. 

\textcolor{black}{
\begin{remark}
We use the first-order viscosity as an upper bound of viscosity coefficients to make sure our scheme is not overly diffusive and want to emphasize that we cannot establish a similar stability estimate as in Proposition \ref{prop:SE} for the residual viscosity. The main reason is the lack of a lower bound for the PDE residual. This implies that the residual can theoretically be zero, in which case the scheme essentially reduces to the standard Galerkin finite element method. However, in practice, if the PDE residual is zero or close to zero, it typically indicates that the solution is extremely smooth and therefore does not require additional stabilization.
In order to achieve theoretical completeness, one possible approach is to introduce a higher-order stabilization term that is activated when the residual vanishes. An example of such a mechanism is the edge stabilization method described in \cite{MR3062586}. However, this is beyond the scope of the present manuscript.
\end{remark}}


\subsection{A novel residual-based viscosity}\label{sec:newRV}
\textcolor{black}{
The method introduced in Section \ref{sec:RV} for computing the residual is robust for low-dimentional problems; while it is problematic when applied to high-dimensional cases. First, the backward differentiation formulas (BDFs) are applied for computing $D_\tau f_h^n$, and in our previous works, the experiments show that usually BDF2 is sufficient enough, which is given by ${\rm BDF}2(f_h)^n = (3f_h^n-4f_h^{n-1}+f_h^{n-2})/(2\tau_n)$, when the time-step is uniform, for the fourth-order accurate scheme.
The BDFs require storing the solutions at previous time steps, e.g., $f_h^{n-2}$, $f_h^{n-1}$ and $f_h^{n}$ are needed when using BDF2; the size of $f_h$ increases dramatically with the dimension, resulting in significantly higher storage requirement. 
In addition, projection step \eqref{eq:residual} requires solving a linear system, which can equally expensive as solving the Euler step of \eqref{eq:FO}.}

Due to this limitation, we introduce a novel approach for constructing the residual-based artificial viscosity suitable for high-dimensional problems. Let us start by taking the integral of \eqref{eq:vw:advection:visc} in $\Omega_{\pmb{x}}$ and $\Omega_{\pmb{v}}$ respectively, and obtain
\begin{equation}\label{eq:uv_ux}
  \begin{aligned}
    \partial_t u_v+\nabla_{\pmb{v}}\cdot\mathbf{F}_{\pmb{v}}(u_v)-\nabla_{\pmb{v}}\cdot(\mathsf{A}_{\pmb{v}}\nabla_{\pmb{v}} u_v)=0,\\
    \partial_t u_x+\nabla_{\pmb{x}}\cdot\mathbf{F}_{\pmb{x}}(u_x)-\nabla_{\pmb{x}}\cdot(\mathsf{A}_{\pmb{x}}\nabla_{\pmb{x}} u_x)=0,
  \end{aligned}
\end{equation}
where
\begin{equation}\label{eq:flux}
  \begin{aligned}
    u_v({\pmb{v}},t)=\int_{\Omega_{\pmb{x}}}f\ {\rm d}{\pmb{x}},\qquad
    \mathbf{F}_{\pmb{v}}(u_v)=\int_{\Omega_{\pmb{x}}}\bbetaa_{\pmb{v}} f\ {\rm d}{\pmb{v}},\\
    u_x({\pmb{x}},t)=\int_{\Omega_{\pmb{v}}}f\ {\rm d}{\pmb{v}},\qquad
    \mathbf{F}_{\pmb{x}}(u_x)=\int_{\Omega_{\pmb{v}}}\bbetaa_{\pmb{x}} f\ {\rm d}{\pmb{x}}.
  \end{aligned}
\end{equation}
In addition, we require the viscosity matrices $\mathsf{A}_{\pmb{x}}:=\mathsf{A}_{\pmb{x}}(u_x)$ and $\mathsf{A}_{\pmb{v}}:=\mathsf{A}_{\pmb{v}}(u_v)$ be fully anisotropic. For this purpose, we propose to regularize \eqref{eq:uv_ux} component-wise, where the viscosity matrices are constructed using the following corresponding residuals: find $ R_{x}^n(u_{h,x})\in \polV_{{\pmb{x}}}$ and $ R_{v}^n(u_{h,v})\in \polV_{{\pmb{v}}}$ such that 
\begin{equation}\label{eq:residual:density}
  \begin{aligned}
    (R^n_{x},\phi_i)&=\big(\big| D_{\tau} u^n_{h,x}+\nabla_{\pmb{x}}\cdot\mathbf{F}_{h,{\pmb{x}}}^n\big|, \phi_i\big),\qquad\forall i\in\calI_{\pmb{x}},\\
    (R^n_{v},\varphi_j)&=\big(\big| D_{\tau} u^n_{h,v}+\nabla_{\pmb{v}}\cdot\mathbf{F}_{h,{\pmb{v}}}^n\big|, \varphi_j\big),\qquad\forall j\in\calI_{\pmb{v}},
  \end{aligned}
\end{equation}
where $u^n_{h,x}$ and $u^n_{h,v}$ are finite element approximation of $u^n_{x}(t^n,{\pmb{x}})$ and $u_{v}(t^n,{\pmb{v}})$ respectively, $D_{\tau} u^n_{h,x}$ and $D_{\tau} u^n_{h,v}$ are approximations of $\partial_t u_{h,x}$ and $\partial_t u_{h,v}$ at time level $t^n$, which are computed using BDF2; $u^n_{h,x}$, $u^n_{h,v}$, $\mathbf{F}^n_{h,{\pmb{x}}}$ and $\mathbf{F}^n_{h,{\pmb{v}}}$ are derived from $f_h^n$ and $\pmb{\bbetaa}_h^n$ using the formulation \eqref{eq:flux}. \textcolor{black}{Note that the projection problems in \eqref{eq:residual:density} are low-dimensional and can be computed very efficiently.}

In order to make the viscosity anisotropic, the first-order viscosity is reduced to depend only on the spatial or velocity space by taking the average values over the other direction, i.e.,
\begin{equation}
  \begin{aligned}
  \big(\nu^{\textrm{L},n}_{x_l}\big)_i 
  &= \frac{1}{N_\bv}\sum_{j\in\calI_{\pmb{v}}}\big(\e^{\textrm{L},n}_{x_l}\big)_{i,j},\qquad \forall i\in\calI_{\pmb{x}},\\ 
  \big(\nu^{\textrm{L},n}_{v_l}\big)_i 
  &= \frac{1}{N_\bx}\sum_{j\in\calI_{\pmb{x}}}\big(\e^{\textrm{L},n}_{x_l}\big)_{j,i},\qquad \forall i\in\calI_{\pmb{v}}.
  \end{aligned}\notag
\end{equation}
In addition, since the residual viscosity is derived from the residuals of \eqref{eq:uv_ux}, the normalization function should also be defined in terms of $u^n_{h,x}$ and $u^n_{h,v}$. Following the approach in \cite{Dao2022a,WEN2025114079}, we introduce a parameter that depends on local discontinuities and define the following normalization function:
\begin{equation}
  \begin{aligned}
    \Lambda_{\bz_i}=\left(1-0.5\frac{\max_{j\in S_z(i)}u^n_{z,j}-\min_{j\in S_z(i)}u^n_{z,j}}{\max_{j\in\calI_\bz}u^n_{z,j}-\min_{j\in\calI_\bz}u^n_{z,j}}\right)\big \|u^n_{h,z} - \overline{u^n_{h,z}} \big \|_{L^\infty(\Omega_\bz)},\quad\forall i\in\calI_\bz,\\
%    \Lambda_{\bx_i}=\left(1-0.5\frac{\max_{j\in S_x(i)}u^n_{x,j}-\min_{j\in S_x(i)}u^n_{x,j}}{\max_{j\in\calI_\bx}u^n_{x,j}-\min_{j\in\calI_\bx}u^n_{x,j}}\right)\big \|u^n_{h,x} - \overline{u^n_{h,x}} \big \|_{L^\infty(\Omega_\bx)},\quad\forall i\in\calI_\bx,\\
%    \Lambda_{\bv_i}=\left(1-0.5\frac{\max_{j\in S_v(i)}u^n_{v,j}-\min_{j\in S_v(i)}u^n_{v,j}}{\max_{j\in\calI_\bv}u^n_{v,j}-\min_{j\in\calI_\bv}u^n_{v,j}}\right)\big \| u^n_{h,v}- \overline{u^n_{h,v}} \big \|_{L^\infty(\Omega_\bv)},\quad\forall i\in\calI_\bv.
  \end{aligned}\notag
\end{equation}
for $\bz \in \{ \bx, \bv\}$, and then we compute the high-order viscosity whose nodal values are given by
\begin{equation}\label{eq:AV:L=H2}
  \begin{aligned}
  \big(\nu^{\textrm{H},n}_{x_l}\big)_i 
  &= 
  \min\Big( \big(\nu^{\textrm{L},n}_{x_l}\big)_i ,\, \Big(\frac{\Delta x_l}{k}\Big)^{2} \frac{\vert R^n_{x,i}\vert}{\Lambda_{\bx_i}}\frac{d_\bx}{d_\bx+d_\bv}\Big),\qquad \forall i\in\calI_{\pmb{x}}, l = 1,\ldots,d_\bx,\\ 
  \big(\nu^{\textrm{H},n}_{v_l}\big)_i 
  &= 
  \min\Big( \big(\nu^{\textrm{L},n}_{v_l}\big)_i ,\, \Big(\frac{\Delta v_l}{k}\Big)^{2} \frac{\vert R^n_{v,i}\vert}{\Lambda_{\bv_i}}\frac{d_\bv}{d_\bx+d_\bv}\Big),\qquad \forall i\in\calI_{\pmb{v}}, l = 1,\ldots,d_\bv. 
  \end{aligned}
\end{equation}
Finally, we define the new viscosity matrices as follows: $\pmb{\mathsf{A}}^{\textrm{H},n}:= \textrm{diag}(\mathsf{A}^{\textrm{H},n}_{\pmb{x}},\mathsf{A}^{\textrm{H},n}_{\pmb{v}})$, 
$\mathsf{A}^{\textrm{H},n}_{\pmb{x}}\in[\polV_{\pmb{x}}]^{d_{\pmb{x}}}:= \textrm{diag}(\nu^{\textrm{H},n}_{x_1}, \ldots, \nu^{\textrm{H},n}_{x_{d_{\pmb{x}}}})$, and $\mathsf{A}^{\textrm{H},n}_{{\pmb{v}}}\in[\polV_{\pmb{v}}]^{d_{\pmb{v}}}:= \textrm{diag}(\nu^{\textrm{H},n}_{v_1}, \ldots, \nu^{\textrm{H},n}_{v_{d_{\pmb{v}}}})$.
\textcolor{black}{
\begin{remark}
  The new formulation \eqref{eq:residual:density} for computing the residual is more efficient than the conventional approach \eqref{eq:residual}, as the computational cost of \eqref{eq:residual:density} scales with $N_\bx + N_\bv$, whereas the cost of \eqref{eq:residual} scales with $N_\bx N_\bv$. This leads to a significantly lower computational expense, especially when both $N_\bx$ and $N_\bv$ are large. The robustness of the new definition of residual viscosity is verified through numerical experiments. For example, Figure~\ref{fig:LD} shows that in the presence of a strong shock, the viscosity is sufficient to stabilize the FE solutions.
\end{remark}}
\begin{remark}
  The artificial viscosity introduces diffusion into the system. To compute the viscosity coefficients, we use the PDE residuals such that the artificial viscosity vanishes in smooth regions. In this work, we construct the viscosity in each direction based on the residuals of \eqref{eq:uv_ux}. However, since diffusion accumulates across all directions, we apply the scaling factors $\frac{d_\bx}{d_\bx + d_\bv}$ and  $\frac{d_\bv}{d_\bx + d_\bv}$  to balance the contribution. This choice ensures consistency with the conventional residual viscosity method. For instance, when $d_\bv = 0$, we have $\frac{d_\bx}{d_\bx + d_\bv} = 1$ and $\frac{d_\bv}{d_\bx + d_\bv} = 0$.
\end{remark}
\begin{proposition}
The forward Euler scheme \eqref{eq:FO} is conservative if we use the artificial viscosity defined in Section \ref{sec:newRV}.
\end{proposition}
\begin{proof}
  We refer to the proof in \cite[Prop. 3]{WEN2025114079}, and in this work, the new artificial viscosity defined in Section \ref{sec:newRV} preserves the property $\sum_{j=1}^N d_{ij}^n = \sum_{i=1}^N d_{ij}^n = 0$, so the same argument applies here as well. 
  \hfill $\square$
\end{proof}

\subsection{Tensor product FE approximations for Vlasov--Maxwell equations}
We now introduce the approach for implementing the finite element methods introduced above using the Kronecker product of matrices. The function $f_h$ can be denoted by $f_h(\pmb{x},\pmb{v},t)=\sum_{j\in\calI} f_j(t)\psi_j(\pmb{x},\pmb{v})$, and the equation \eqref{eq:GFEM:visc} can be reformulated as follows
\begin{equation}\label{eq:GFEM:ts}
  \begin{aligned}
    \bigg(\partial_t\sum_{j\in\calI} f_j\psi_j,\psi_i\bigg)+\bigg(\pmb{v}\cdot\nabla_{\pmb{x}}\sum_{j\in\calI}f_j\psi_j,\psi_i\bigg)+\bigg(\pmb{E}_h\cdot\nabla_{\pmb{v}}\sum_{j\in\calI}f_j\psi_j,\psi_i\bigg)\\
    +\bigg(\pmb{B}_h\cdot\Big(\nabla_{\pmb{v}}\sum_{j\in\calI}f_j\psi_j\times\pmb{v}\Big),\psi_i\bigg)+\bigg(\mathsf{A}_{{\pmb{x}}}\Big(\nabla_{\pmb{x}}\sum_{j\in\calI}f_j\psi_j\Big),\nabla_{\pmb{x}}\psi_i\bigg)\\+\bigg(\mathsf{A}_{{\pmb{v}}}\Big(\nabla_{\pmb{v}}\sum_{j\in\calI}f_j\psi_j\Big),\nabla_{\pmb{v}}\psi_i\bigg)=0,\qquad\forall i\in\calI.
  \end{aligned}
\end{equation}
We sort the basis functions $\{\psi_i\}_{i\in\calI}$ using such index: 
\begin{equation}
  \{\psi_1,\cdots\psi_{N_{\pmb{v}}},\cdots,\psi_{(N_{\pmb{x}}-1)N_{\pmb{v}}+1},\cdots,\psi_{N_{\pmb{x}} N_{\pmb{v}}}\},\notag
\end{equation}
which is equivalent to 
\begin{equation}
  \{\phi_1\varphi_1,\ldots,\phi_1\varphi_{N_{\pmb{v}}},\ldots,\phi_{N_{\pmb{x}}}\varphi_1,\ldots,\phi_{N_{\pmb{x}}}\varphi_{N_{\pmb{v}}}\}.\notag
\end{equation}
Let the vector $\polf=(f_1,\cdots,f_N)^{\mathsf{T}}$ be the collection of all the degrees of freedom of $f_h$, ordered as previously introduced. 

The equation \eqref{eq:GFEM:ts} yields the following system
\begin{equation}\label{eq:system}
  \begin{aligned}
    (\polM^{{\pmb{x}}}\otimes \polM^{{\pmb{v}}})\dot{\polf} + 
    \sum_{l=1}^3 
    \Big( 
      \polA^{\pmb{x},l}\otimes\polC^{\pmb{v},l}
      & + 
      \polC^{\pmb{x},l}(\bE)\otimes \polA^{\pmb{v},l} + 
      \polC^{\pmb{x},l}(\bB)\otimes \polG^{\pmb{v},l}
    \Big)  
      \polf\\
    & +
     (\polD^{{\pmb{x}}}\otimes \polM^{{\pmb{v}}})\polf+(\polM^{{\pmb{x}}}\otimes \polD^{{\pmb{v}}})\polf= 0,
  \end{aligned}
\end{equation}
where the operators in above equation are defined as follows
  \begin{align*}
    \polA_{ij}^{{\pmb{x}},l} &= \int_{\Omega_{\pmb{x}}}\textcolor{black}{(}\partial_{x_l}\phi_j\textcolor{black}{)}\phi_i\ {\rm d}\pmb{x}, \quad
    \polC_{ij}^{{\pmb{x}},l}(\bw) = \int_{\Omega_{\pmb{x}}} w_l\phi_j\phi_i\ {\rm d}\pmb{x}, 
    \quad l = 1,2,3,\\
    \polM_{ij}^{{\pmb{x}}} &= \int_{\Omega_{\pmb{x}}}\phi_j\phi_i\ {\rm d}\pmb{x}, \quad
    \polD_{ij}^{{\pmb{x}}}= \int_{\Omega_{\pmb{x}}}\mathsf{A}_{{\pmb{x}}}\textcolor{black}{(}\nabla_{\pmb{x}}\phi_j\textcolor{black}{)}\SCAL\textcolor{black}{(}\nabla_{\pmb{x}}\phi_i\textcolor{black}{)}\ {\rm d}\pmb{x}, \quad
    \forall i,j\in\calI_{\pmb{x}},
  \end{align*}
and
  \begin{align*}
    \polA_{ij}^{{\pmb{v}},l} &= \int_{\Omega_{\pmb{v}}}\textcolor{black}{(}\partial_{v_l}\varphi_j\textcolor{black}{)}\varphi_i\ {\rm d}\pmb{v}, \quad 
    \polC_{ij}^{{\pmb{v}},l} = \int_{\Omega_{\pmb{v}}} v_l\varphi_j\varphi_i\ {\rm d}\pmb{v}, \\
    \polG_{ij}^{\pmb{v},l} &= \int_{\Omega_{\pmb{v}}} \big(\nabla_{\pmb{v}} \CROSS \pmb{v} \big)_l \varphi_j \varphi_i {\rm d} \pmb{v} , 
    \quad l = 1,2,3, \\
    \polM_{ij}^{{\pmb{v}}} &=\int_{\Omega_{\pmb{v}}}\varphi_j\varphi_i\ {\rm d}\pmb{v}, \quad 
    \polD_{ij}^{{\pmb{v}}}= \int_{\Omega_{\pmb{v}}}\mathsf{A}_{{\pmb{v}}}\textcolor{black}{(}\nabla_{\pmb{v}}\varphi_j\textcolor{black}{)}\SCAL\textcolor{black}{(}\nabla_{\pmb{v}}\varphi_i\textcolor{black}{)}\ {\rm d}\pmb{v}, \quad \forall i,j\in\calI_{\pmb{v}}.
  \end{align*}
\begin{remark}
  In reduced Vlasov--Maxwell systems, equations \eqref{eq:system} will simplify to the equations introduced in section \ref{sec:reducedVM}.
\end{remark}


