\subsection{Finite element approximation of the Maxwell’s equations}
Once the approximation $f_h^{n} \in \polV$ is obtained, according to \eqref{eq:denst}, we can compute the charge density and current density as follows
\begin{equation}
  \rho_h^n = \int_{\Omega_{\pmb{v}}}f_h^n\ {\rm d}\pmb{v},\qquad \pmb{J}_h^n = \int_{\Omega_{\pmb{v}}}\pmb{v}f_h^n\ {\rm d}\pmb{v}\notag.
\end{equation}
Since $f_h^n\in\polV:=\polV_{\pmb{x}}\otimes\polV_{\pmb{v}}$, it naturally holds true that $\rho_h^n\in\polV_{\pmb{x}}$ and $\pmb{J}_h^n\in[\polV_{\pmb{x}}]^{d_{\pmb{v}}}$. Now recall the modified current density \eqref{eq:J_h:visc}, we replace $\bJ^n_h$ with the following object
\begin{equation}\label{eq:current_mod}
  \widetilde{\bJ_h^n} =\bJ_h^n - \int_{\Omega_{\pmb{v}}}\mathsf{A}^n_{{\pmb{x}}}\GRAD_{{\pmb{x}}}f_h^n\ {\rm d}{\pmb{v}}= \bJ_h^n - \mathsf{A}^n_{{\pmb{x}}}\GRAD_{{\pmb{x}}}\rho_h^n.
\end{equation}

\label{sec:fem:maxwell}
Let us define an anisotropic polynomial space $\polQ_{\alpha_1, \alpha_2, ..., \alpha_{d_{\pmb{x}}}}$ composed of $d_{\pmb{x}}$-variate polynomials whose degree with respect to $x_i$ is at most $\alpha_i$. Then, we define the following spaces adopted from \cite[Sec.~3.9]{Monk_2003}:
\[
\pmb{\polE}:=
\{
\bw\in \bH(\textrm{curl};\Omega_{{\pmb{x}} }): [\GRAD_{\widehat{{\pmb{x}} }}\bT_K(\widehat{{\pmb{x}} }))]^\top \bw(\bT_K({\widehat{{\pmb{x}} }})) \in \calN_{k-1}(\widehat{K}), \forall K\in \calT_{{\pmb{x}} }
\},
\]
and
\[
\begin{aligned}
\pmb{\polB}:=
\{
\bw & \in \bH(\textrm{div};\Omega_{{\pmb{x}} }): \\
&
\det(\GRAD_{\widehat{{\pmb{x}} }}\bT_K(\widehat{{\pmb{x}} }))
[\GRAD_{\widehat{{\pmb{x}} }}\bT_K(\widehat{{\pmb{x}} }))]^{-1} 
\bw(\bT_K({\widehat{{\pmb{x}} }})) \in \calR\calT_{k-1}(\widehat{K}), 
 \forall K\in \calT_{{\pmb{x}} }
\},
\end{aligned}
\]
where
\[
\begin{aligned}
\calN_{k}(\widehat{K}) 
&:= 
\big[ \polQ_{k, k+1, k+1}(\widehat{K}), \polQ_{k+1, k, k+1}(\widehat{K}), \polQ_{k+1, k+1, k}(\widehat{K}) \big], \\
\calR\calT_{k}(\widehat{K}) 
&:= 
\big[ 
\polQ_{k+1, k, k}(\widehat{K}), 
\polQ_{k, k+1, k}(\widehat{K}), 
\polQ_{k, k, k+1}(\widehat{K}) \big] 
\end{aligned}
\]
are the well-known N\'ed\'elec and Raviart-Thomas elements of order $k$ for cartesian grids for the case of $d_{\pmb{x}}=3$.

With these spaces at hand, we obtain the finite element discretization of the Maxwell's equations \eqref{eq:AP:visc} as follows: for given $f^n_h \in \polV$, $\rho^n_h \in \polV_{\pmb{x}}$, $\pmb{J}^n_h \in [\polV_{\pmb{x}}]^{d_{\pmb{v}}}$, $\bE^n_h \in \pmb{\polE}$ and $\bB^n_h \in \pmb{\polB}$, we are looking for $\bE^{n+1}_h \in \pmb{\polE}$ and $\bB^{n+1}_h\in\pmb{\polB}$ from the following forward Euler scheme: 

\begin{equation}\label{eq:fem:AP11}
\begin{aligned}
  \Big(
	\frac{\bE^{n+1}_h - \bE^{n}_h}{\tau_n},\, \pmb{\eta} 
  \Big)
  &=
  \big(
  c^2\bB^n_h,\nabla_{\pmb{x}}\times\pmb{\eta}\big)-\big(\epsilon_0^{-1}\big(\bJ^n_h-\mathsf{A}^n_{{\pmb{x}}}\GRAD_{{\pmb{x}}}\rho^n_h\big),\ \pmb{\eta}
  \big), \quad \forall \pmb{\eta} \in \pmb{\polE},
  \\
	\Big(
	\frac{\bB^{n+1}_h - \bB^{n}_h}{\tau_n},\, \pmb{\xi} 
  \Big)
  &=
  \big(
  -\nabla_{{\pmb{x}} }\CROSS\bE^n_h,\, \pmb{\xi}
  \big), \quad \forall \pmb{\xi} \in \pmb{\polB}.
\end{aligned}
\end{equation}
Moreover, the forward Euler discretization of \eqref{eq:ctcharge:visc} gives us
\begin{equation}\label{eq:discreteContinuityEqn}
    \big(\GRAD_{{\pmb{x}}}\SCAL \big(\bJ^n_h-\mathsf{A}^n_{{\pmb{x}}}\GRAD_{{\pmb{x}}}\rho^n_h\big),\phi_i\big)=
  -\Big(
	\frac{\rho^{n+1}_h - \rho^{n}_h}{\tau_n},\, \phi_i
  \Big),\qquad\forall i\in\calI_\bx,
\end{equation}
and we introduce the computation of $\rho_h^n$ and $\bJ^n_h$ in section \ref{sec:density}.

\begin{proposition}[Discrete Gauss' law] Suppose the initial condition is chosen such that the Gauss' law \eqref{eq:GL} is satisfied and the discrete continuity equation \eqref{eq:discreteContinuityEqn} holds for all time steps. Then, the finite element solutions $\bE_h^{n+1}$ and $\bB_h^{n+1}$ of the scheme \eqref{eq:fem:AP11} satisfy the Gauss' law weakly, \ie
\begin{equation}\label{eq:weak:GL}
\begin{aligned}
\Big(
\frac{\bE^{n+1}_h - \bE^{n}_h}{\tau_n}, \, \GRAD_{{\pmb{x}}}\phi_i
\Big) &= -\Big(
	\epsilon_0^{-1}\frac{\rho^{n+1}_h - \rho^{n}_h}{\tau_n},\,\phi_i 
  \Big), \qquad \forall i\in \calI_\bx,\\
\GRAD_{{\pmb{x}}} \SCAL \bB_h^{n+1} &= 0, \mbox{ a.e.}. \\
\end{aligned}
\end{equation}
\end{proposition}

\begin{proof}
Since, for any function $\phi_i\in\polV_\bx$, we have $\nabla_{\pmb{x}}\phi_i\in \pmb{\polE}$. Thus, we test \eqref{eq:fem:AP11} with the test function $\pmb{\eta} = \GRAD_{{\pmb{x}}}\phi_i$ and obtain initially:
\[
  \Big(
	\frac{\bE^{n+1}_h - \bE^{n}_h}{\tau_n},\, \GRAD_{{\pmb{x}}}\phi_i
  \Big)
  =
  \big(
  c^2\bB^n_h,\nabla_{{\pmb{x}} }\CROSS(\nabla_{\pmb{x}}\phi_i)\big)-\big(\epsilon_0^{-1}\big(\bJ^n_h-\mathsf{A}^n_{{\pmb{x}}}\GRAD_{{\pmb{x}}}\rho^n_h\big),\ \GRAD_{{\pmb{x}}}\phi_i
  \big).  
\]
Integration by parts of the right hand side term, and taking into account the periodic boundary conditions, we obtain
\begin{equation*}\label{eq:prop:gl:E}
  \begin{aligned}
  \Big(
	\frac{\bE^{n+1}_h - \bE^{n}_h}{\tau_n},\, & \GRAD_{{\pmb{x}}}\phi_i
  \Big)
   =\\
   & \big(
  c^2\bB^n_h,\nabla_{{\pmb{x}} }\CROSS(\nabla_{\pmb{x}}\phi_i)\big)+\big(\epsilon_0^ {-1}\GRAD_{{\pmb{x}}}\SCAL\big(\bJ^n_h -\mathsf{A}^n_{{\pmb{x}}}\GRAD_{{\pmb{x}}}\rho^n_h\big),\phi_i
  \big).  
\end{aligned}
\end{equation*}
Note that, the first term of the right hand side is zero because $\nabla_{\pmb{x}}\times(\nabla_{\pmb{x}}\phi_i)=0$ almost everywhere, $\forall w\in\polV_{\pmb{x}}$, and for the second term we can use  \eqref{eq:discreteContinuityEqn} to find
\[
  \Big(
	\frac{\bE^{n+1}_h - \bE^{n}_h}{\tau_n},\, \GRAD_{{\pmb{x}}}\phi_i 
  \Big)
  =
-\Big(
	\epsilon_0^{-1}\frac{\rho^{n+1}_h - \rho^{n}_h}{\tau_n},\,\phi_i  
  \Big), \qquad \forall i \in \calI_\bx.
\]
It proves the first equality of \eqref{eq:weak:GL}, which is a discrete weak version of the Gauss' law \eqref{eq:GL_E_dt}.

To prove the second statement in \eqref{eq:weak:GL}, we observe that $\nabla_{{\pmb{x}}} \times \bE^n_h \in \pmb{\polB}$, which implies 
\[
	\frac{\bB^{n+1}_h - \bB^{n}_h}{\tau_n}
  +\nabla_{{\pmb{x}} }\CROSS\bE^n_h = 0, \quad \mbox{ a.e.}.
\]

Now, taking the divergence of this equality and noting $\nabla_{{\pmb{x}}} \cdot \bB^{n}_h = 0$ and $\nabla_{{\pmb{x}}} \cdot (\nabla_{{\pmb{x}}} \times \bE^n_h) = 0$ almost everywhere, we conclude that $\nabla_{{\pmb{x}}} \cdot \bB^{n+1}_h = 0$ almost everywhere.
\end{proof}


