\section{Numerical examples}\label{sec:exp}
In this section, we present the numerical results of our methods in various benchmark problems of Vlasov--Maxwell equations. We use the fourth-order, five-stage SSP-RK method from \cite{Kraaijevanger_1991} for all the experiments in this manuscript. The time step is controlled by the CFL condition \eqref{eq:CFL}; the CFL number we use is $\lambda=0.4$. The time-stepping algorithm of the methods can be described by Algorithm \ref{alg:FEVM}. We note that the artificial viscosity matrix is updated after each time step iteration. 

The finite element method is a grid-based scheme, and in our experiments, we manually cut the velocity space. The distribution functions are initialized with Gaussian perturbations in velocity space, with the velocity boundaries defined such that the value of $f$ is neglectable at the edges of the velocity space.

\begin{algorithm}[hbt!]
  \caption{Time-stepping procedure}\label{alg:FEVM}
  \SetKwInput{KwInput}{Input}
  \SetKwInput{KwOutput}{Output}
  \KwInput{Initial conditions: $f_0$, $\pmb{E}_0$, $\pmb{B}_0$; Final time: $T$}
  \KwOutput{$f_h(t = T)$, $\pmb{E}_h(t = T)$, $\pmb{B}_h(t = T)$}

  % Initialization
  Initialize: $f_h^0 \leftarrow f_0$, $\pmb{E}_h^0 \leftarrow \pmb{E}_0$, $\pmb{B}_h^0 \leftarrow \pmb{B}_0$, $t \leftarrow 0$, $n \leftarrow 0$\;

  \While{$t < T$}{
    Compute $u^{n}_{h,x}$, $u^{n}_{h,v}$, $\mathbf{F}^{n}_{h,{\pmb{x}}}$, and $\mathbf{F}^{n}_{h,{\pmb{v}}}$\ using \eqref{eq:int:v} and \eqref{eq:int:x}\;
    Compute the residual $R_{x}^{n}$ and $R_{v}^{n}$ using \eqref{eq:residual:density}\;
    Compute the viscosity $\pmb{\mathsf{A}}^{n}$ using \eqref{eq:AV:L=H2}\;
    Determine the time step $\Delta t = \tau_n$ using \eqref{eq:CFL}\;
    Apply the Runge-Kutta scheme to update $f_h^{n+1}$, $\pmb{E}_h^{n+1}$, and $\pmb{B}_h^{n+1}$\;
    Update time: $t \leftarrow t + \Delta t$, $n \leftarrow n + 1$\;
  }
\end{algorithm}

\subsection{Vlasov--Maxwell in 1D2V and 2D2V phase-space}\label{sec:reducedVM}
Assuming all physical parameters are set to 1, we consider a single species and apply our methods to the Vlasov–Maxwell equations in the following reduced phase spaces.

Let $\Omega := \Omega_x\otimes\Omega_{{\pmb{v}} }$, where $\Omega_x\subset\mathbb{R}^1$, $\Omega_{{\pmb{v}} }:=\Omega_{v_1}\otimes\Omega_{v_2}\subset\mathbb{R}^2$. The electromagnetic fields are given by
\begin{equation*}
    \pmb{E}(x,t) = (E_1(x,t),E_2(x,t),0),\qquad\pmb{B}(x,t) = (0,0,B_3(x,t)). 
\end{equation*}
The advection field of the Vlasov equation becomes
\[
    \pmb{\bbetaa} = \begin{pmatrix}
        v_1,E_1+v_2B_3,E_2-v_1B_3
    \end{pmatrix}^\top,\qquad\nabla = \begin{pmatrix}
        \partial_x,\partial_{v_1},\partial_{v_2}
    \end{pmatrix}^\top.
\]
The coupled Maxwell's equations are given by
\begin{equation}
\begin{aligned}
  \partial_t E_1&=-J_1,\\
  \partial_t E_2&=-\partial_x B_3-J_2,\\
  \partial_t B_3&= -\partial_x E_2 ,\\
  \partial_x E_1&=\rho-\rho_0.
\end{aligned}\notag
\end{equation}
In this simplified setting, the system \eqref{eq:system} for the Vlasov--Maxwell equations reduces to:
\begin{equation}
\begin{aligned}
    (\polM^x\otimes \polM^\bv)\dot{\polf} + 
    \Big( 
      \polA^{x,1}\otimes\polC^{\bv,1} 
      & + 
       \sum_{l=1}^2\polC^{x,l}(\bE)\otimes \polA^{\bv,l} + 
      \polC^{x,3}(\bB)\otimes \polG^{\bv,3}
    \Big)  
      \polf\\
    & +
     (\polD^x\otimes \polM^\bv+\polM^x\otimes \polD^\bv)\polf= 0,
  \end{aligned}\notag
\end{equation}

Next, let $\Omega := \Omega_{\pmb{x}}\otimes\Omega_{\pmb{v}}$, where $\Omega_{\pmb{x}}:=\Omega_{x_1}\otimes\Omega_{x_2}\subset\mathbb{R}^2$, $\Omega_{{\pmb{v}} }:=\Omega_{v_1}\otimes\Omega_{v_2}\subset\mathbb{R}^2$. The fields are then simplified as follows
\begin{equation*}
    \pmb{E}({\pmb{x}},t) = (E_1({\pmb{x}},t),E_2({\pmb{x}},t),0),\qquad\pmb{B}({\pmb{x}},t) = (0,0,B_3({\pmb{x}},t)). 
\end{equation*}
The electromagnetic fields are given by
\[
    \pmb{\bbetaa} = \begin{pmatrix}
        v_1,v_2,E_1+v_2B_3,E_2-v_1B_3
    \end{pmatrix}^\top,\qquad\nabla = \begin{pmatrix}
        \partial_{x_1},\partial_{x_2},\partial_{v_1},\partial_{v_2}
    \end{pmatrix}^\top.
\]
The coupled Maxwell's equations are given by
\begin{equation}
\begin{aligned}
  \partial_t E_1&=\partial_{x_2}B_3-J_1,\\
  \partial_t E_2&=-\partial_{x_1} B_3-J_2,\\
  \partial_t B_3&= -\partial_{x_1} E_2+\partial_{x_2}E_1 ,\\
  \partial_{x_1} E_1+\partial_{x_2} E_2&=\rho-\rho_0.
\end{aligned}\notag
\end{equation}
Similarly, in the 2D2V phase space, system \eqref{eq:system} becomes
\begin{equation}
\begin{aligned}
    (\polM^\bx\otimes \polM^\bv)\dot{\polf} + 
    \Big( 
      \sum_{l=1}^2\polA^{\bx,l}\otimes\polC^{\bv,l} 
      & + 
       \sum_{l=1}^2\polC^{\bx,l}(\bE)\otimes \polA^{\bv,l} + 
      \polC^{\bx,3}(\bB)\otimes \polG^{\bv,3}
    \Big)  
      \polf\\
    & +
     (\polD^\bx\otimes \polM^\bv+\polM^\bx\otimes \polD^\bv)\polf= 0.
  \end{aligned}\notag
\end{equation}

\begin{remark}
Note that in both reduced models, only the third component of the magnetic field is nonzero and there is no dependence on $x_3$. Therefore, the magnetic Gauss's law is trivially satisfied.
\end{remark}

