\section{Proof of Theorem \ref{thm:exist-constrain}}\label{sec:prf-constrain}
The main technical idea underlying the proof is the conversion of Gelfand integrals—which are technically challenging—to Bochner integrals. Unfortunately, $L^{\infty}(\mathbb{P})$ can fail to be a separable Banach space, and so Bochner integrability is too narrow a condition to incorporate an arbitrary $\mathcal{X}$-feasible allocation. To fix this problem, one must change the underlying Banach space, which we accomplish by viewing $L^{\infty}(\mathbb{P})$ as a subset of $L^{1}(\mathbb{P})$ (see, in particular, the proof of Lemma \ref{lem:compact-optimize} below).
\subsection{Lemmata}
\subsubsection{Finiteness of the Value Function}
Firstly, we establish finiteness of the value function.
\begin{lemma}\label{lem:finitevalconstrain}
    The value function at $\mathcal{X}$ is real-valued, i.e.,
    \begin{equation*}
        \inf_{(Y_{a})_{a\in A}\in\mathbb{A}^{\zeta}_{\xi}(\mathcal{X})}\int_{A}\varrho_{a}(Y_{a})\mu(da)\in\mathbb{R}.
    \end{equation*}
\end{lemma}
\begin{proof}
    We first show that $\inf_{(Y_{a})_{a\in A}\in\mathbb{A}^{\zeta}_{\xi}(\mathcal{X})}\int_{A}\varrho_{a}(Y_{a})\mu(da)>-\infty$. For every $(Y_{a})_{a\in A}\in\mathbb{A}^{\zeta}_{\xi}(\mathcal{X})$, we have that
    \begin{equation*}
        \int_{A}\varrho_{a}(Y_{a})\mu(da)\geq\int_{A}\varrho_{a}(-\Vert{Y_{a}^{-}}\Vert_{L^{\infty}})\mu(da)=\int_{A}\left(\varrho_{a}(0)-\Vert{Y_{a}^{-}}\Vert_{L^{\infty}}\right)\mu(da)
    \end{equation*}
    \begin{equation*}
        \geq-\int_{A}\vert{\varrho_{a}(0)}\vert\mu(da)-\int_{A}\zeta(a)\mu(da)>-\infty.
    \end{equation*}
    Since the last bound above is uniform in $(Y_{a})_{a\in A}\in\mathbb{A}^{\zeta}_{\xi}(\mathcal{X})$, it follows that
    \begin{equation*}
        \inf_{(Y_{a})_{a\in A}\in\mathbb{A}^{\zeta}_{\xi}(\mathcal{X})}\int_{A}\varrho_{a}(Y_{a})\mu(da)>-\infty,
    \end{equation*}
    as desired.
    \par
    We now show that $\inf_{(Y_{a})_{a\in A}\in\mathbb{A}^{\zeta}_{\xi}(\mathcal{X})}\int_{A}\varrho_{a}(Y_{a})\mu(da)<\infty$. Since $\mathbb{A}^{\zeta}_{\xi}(\mathcal{X})\neq\emptyset$, we may fix some $(Z_{a})_{a\in A}\in\mathbb{A}^{\zeta}_{\xi}(\mathcal{X})$. Then,
    \begin{equation*}
        \inf_{(Y_{a})_{a\in A}\in\mathbb{A}^{\zeta}_{\xi}(\mathcal{X})}\int_{A}\varrho_{a}(Y_{a})\mu(da)\leq\int_{A}\varrho_{a}(Z_{a})\mu(da)\leq\int_{A}\varrho_{a}(\Vert{Z_{a}^{+}}\Vert)\mu(da)
    \end{equation*}
    \begin{equation*}
        =\int_{A}\left(\varrho_{a}(0)+\Vert{Z_{a}^{+}}\Vert_{L^{\infty}}\right)\mu(da)\leq\int_{A}\vert{\varrho_{a}(0)}\vert\mu(da)+\int_{A}\xi(a)\mu(da)<\infty,
    \end{equation*}
    as desired.
\end{proof}
\subsubsection{A Compactness Principle}
In this subsection, we state and prove a compactness principle, to be applied when an optimizing sequence is fixed.
\par
\begin{lemma}\label{lem:compact-optimize}
    Let $\left((Y^{n}_{a})_{a\in A}\right)_{n=1}^{\infty}\subseteq\mathbb{A}^{\zeta}_{\xi}(\mathcal{X})$ be a sequence. We may find convex combinations $(\widetilde{Y}^{n}_{a})_{a\in A}\in\mathrm{co}\left\{(Y^{m}_{a})_{a\in A}:m\geq n\right\}$ and an allocation $(X_{a})_{a\in A}\in\mathbb{A}^{\zeta}_{\xi}(\mathcal{X})$ such that, on some set $B\in\mathscr{A}$ of full $\mu$-measure, $\left((\widetilde{Y}^{n}_{a})_{a\in A}\right)_{n=1}^{\infty}$ converges in probability to $(X_{a})_{a\in A}$.
\end{lemma}
The proof relies on the concept of Bochner integration; the reader unfamiliar with this notion is referred to Aliprantis and Border \cite{aliprantis-inf-dim} (in particular, pp. 422-428 thereof) for more information. For the convenience of the reader, we recall the Lebesgue-Bochner space $L^{1}(\mu,E)$, and a corollary to the extension of Talagrand's \cite{rosental} parameterized Rosenthal $\ell_{1}$-theorem to $L^{1}(\mu,E)$ by Diestel, Ruess, and Schachermayer \cite{drs-proc}.
\par
Given a separable Banach space $E$ (in our concrete application $E=L^{1}(\mathbb{P})$), the Lebesgue-Bochner space $L^{1}(\mu,E)$ is the Banach space of Bochner-integrable functions $f:A\longrightarrow E$, modulo $\mu$-a.e. equivalence, under the norm $f\longmapsto\int_{A}\Vert{f}\Vert_{E}\mu(da)$. In the sequel, we will need the following proposition, which serves as a compactness principle for $\mu$-a.e. convergence.
\begin{proposition}[Diestel-Ruess-Schachermayer, \cite{drs-proc}]\label{prop:drs-corr}
    Let $K\subseteq L^{1}(\mu,E)$ be a bounded subset of $L^{1}(\mu,E)$ such that the following holds for some indexed collection $(H_{a})_{a\in A}\subseteq 2^{E}$ of $\sigma(E,E^{\ast})$-compact sets. For each $f\in K$, one has that $f(a)\in H_{a}$ for $\mu$-a.e. $a\in A$. Then, for every sequence $(f_{n})_{n=1}^{\infty}\subseteq K$, we may find convex combinations $g_{n}\in\mathrm{co}\{f_{m}:m\geq n\}$ such that $(g_{n})_{n=1}^{\infty}$ converges $\mu$-a.e. in the norm topology to some $f\in L^{1}(\mu,E)$.
\end{proposition}
\begin{proof}
    See (Theorem 2.4, \cite{drs-proc}).
\end{proof}
Equipped with the above proposition, we now prove Lemma \ref{lem:compact-optimize}.
\begin{proof}[Proof of Lemma \ref{lem:compact-optimize}]
    By viewing $L^{\infty}(\mathbb{P})$ as a subset of $L^{1}(\mathbb{P})$, view $\left((Y^{n}_{a})_{a\in A}\right)_{n=1}^{\infty}$ as a sequence of functions $A\longrightarrow L^{1}(\mathbb{P})$. It is easy to see that each $Y^{n}$ is in the Lebesgue-Bochner space $L^{1}(\mu;L^{1}(\mathbb{P}))$.\footnote{The only non-trivial aspect of this claim is showing that each $Y^{n}$ is $\mathscr{A}$-measurable when $L^{1}(\mathbb{P})$ is equipped with the Borel $\sigma$-algebra $\mathscr{B}$ of the $L^{1}(\mathbb{P})$-norm, which  is a consequence of noticing that $\mathscr{B}$ coincides with the Baire $\sigma$-algebra of $\sigma(L^{1},L^{\infty})$.} By the Dunford-Pettis theorem and NEL$\wedge$NEP, for $\mu$-a.e. $a\in A$, the sequence $(Y^{n}_{a})_{n=1}^{\infty}$ lies within a relatively weakly compact subset (which could depend on $a$) of $L^{1}(\mathbb{P})$. Thus, by Proposition \ref{prop:drs-corr}, we may find $(\widetilde{Y}^{n}_{a})_{a\in A}\in\mathrm{co}\left\{(Y^{m}_{a})_{a\in A}:m\geq n\right\}$ and $(X_{a})_{a\in A}\in L^{1}(\mu;L^{1}(\mathbb{P}))$ such that $\left((\widetilde{Y}^{n}_{a})_{a\in A}\right)_{n=1}^{\infty}$ converges $\mu$-a.e. in $L^{1}(\mathbb{P})$ to $(X_{a})_{a\in A}$ (hence also $\mu$-a.e. in probability, by Markov's inequality).
    \par
    We claim that the following conditions hold.
    \begin{enumerate}
        \item $(X_{a})_{a\in A}$ is valued in $L^{\infty}(\mathbb{P})$ $\mu$-a.e., and
        \begin{equation*}
        \Vert{X_{a}^{+}\Vert}_{L^{\infty}}\leq\xi(a)
        \end{equation*}
        \begin{equation*}
        \Vert{X_{a}^{-}\Vert}_{L^{\infty}}\leq\zeta(a)
        \end{equation*}
        hold for $\mu$-a.e. $a\in A$.
        \item Viewed as a function $A\longrightarrow L^{\infty}(\mathbb{P})$, $(X_{a})_{a\in A}$ is $\mathscr{A}$-measurable.
        \item $(X_{a})_{a\in A}$ is Gelfand-integrable, and the Gelfand integral $\int_{A}X_{a}\mu(da)$ is $\mathcal{X}$.
    \end{enumerate}
    The three points above, in tandem with previous arguments, imply the claim.
    \par
    (1) is obvious, since each $\left(\widetilde{Y}^{n}_{a}\right)_{a\in A}$ satisfies NEL$\wedge$NEP. (2) is also clear; indeed, $a\longmapsto\mathbb{E}^{\mathbb{P}}(X_{a}\mathcal{Y})$ is $\mathscr{A}$-measurable for each $\mathcal{Y}\in L^{\infty}(\mathbb{P})$ (by virtue of Bochner measurability when viewed as a function $A\longrightarrow L^{1}(\mathbb{P})$), and the claim follows by approximating each $\mathcal{Y}\in L^{1}(\mathbb{P})$ by a sequence in $L^{\infty}(\mathbb{P})$.
    \par
    We now prove (3). By (Theorem 11.52 on pg. 430, \cite{aliprantis-inf-dim}), $(X_{a})_{a\in A}$ is Gelfand integrable. Thus, it suffices to show that the Gelfand integral $\int_{A}X_{a}\mu(da)$ is $\mathcal{X}$. By a density argument, this is equivalent to
    \begin{equation*}
        \mathbb{E}^{\mathbb{P}}(\mathcal{X}\mathcal{Y})=\int_{A}\mathbb{E}^{\mathbb{P}}(X_{a}\mathcal{Y})\mu(da)
    \end{equation*}
    for all $\mathcal{Y}\in L^{\infty}(\mathbb{P})$.
    \par
    Fix $\mathcal{Y}\in L^{\infty}(\mathbb{P})$. By $\mu$-a.e. convergence in $L^{1}(\mathbb{P})$ norm, $\left(\mathbb{E}^{\mathbb{P}}(\widetilde{Y}^{n}\mathcal{Y})\right)_{n=1}^{\infty}$ converges $\mu$-a.e. to $\mathbb{E}^{\mathbb{P}}(X\mathcal{Y})$. Lebesgue's dominated convergence theorem and NEL$\wedge$NEP implies
    \begin{equation*}
        \lim_{n\to\infty}\int_{A}\mathbb{E}^{\mathbb{P}}(\widetilde{Y}^{n}_{a}\mathcal{Y})\mu(da)=\int_{A}\mathbb{E}^{\mathbb{P}}(X_{a}\mathcal{Y})\mu(da).
    \end{equation*}
    The claim now follows from the fact that $\int_{A}\mathbb{E}^{\mathbb{P}}(\widetilde{Y}^{n}_{a}\mathcal{Y})\mu(da)=\mathbb{E}(\mathcal{X}\mathcal{Y})$.
\end{proof}
\subsection{The Proof}
\begin{proof}[Proof of Theorem \ref{thm:exist-constrain}]
    By Lemma \ref{lem:finitevalconstrain}, we may find $\left((Y^{n}_{a})_{a\in A}\right)_{n=1}^{\infty}\subseteq\mathbb{A}^{\zeta}_{\xi}(\mathcal{X})$ such that
    \begin{equation}\label{eq:optimize-seq}
        \int_{A}\varrho_{a}(Y^{n}_{a})\mu(da)\leq\frac{1}{n}+\inf_{(Y_{a})_{a\in A}\in \mathbb{A}^{\zeta}_{\xi}(\mathcal{X})}\int_{A}\varrho_{a}(Y_{a})\mu(da).
    \end{equation}
    Using Lemma \ref{lem:compact-optimize}, we may find convex combinations $(\widetilde{Y}^{n}_{a})_{a\in A}\in\mathrm{co}\left\{(Y^{m}_{a})_{a\in A}:m\geq n\right\}$ and an allocation $(X_{a})_{a\in A}\in\mathbb{A}^{\zeta}_{\xi}(\mathcal{X})$ such that, on some set $B\in\mathscr{A}$ of full $\mu$-measure, $\left((\widetilde{Y}^{n}_{a})_{a\in A}\right)_{n=1}^{\infty}$ converges in probability to $(X_{a})_{a\in A}$. The Fatou property, NEL$\wedge$NEP, Fatou's lemma, convexity, and (\ref{eq:optimize-seq}) imply
    \begin{equation*}
        \int_{A}\varrho_{a}(X_{a})\mu(da)\leq\inf_{(Y_{a})_{a\in A}\in \mathbb{A}^{\zeta}_{\xi}(\mathcal{X})}\int_{A}\varrho_{a}(Y_{a})\mu(da).
    \end{equation*}
    Since $\int_{A}\varrho_{a}(X_{a})\mu(da)\geq\inf_{(Y_{a})_{a\in A}\in \mathbb{A}^{\zeta}_{\xi}(\mathcal{X})}\int_{A}\varrho_{a}(Y_{a})\mu(da)$, it follows that
    \begin{equation*}
        \int_{A}\varrho_{a}(X_{a})\mu(da)=\inf_{(Y_{a})_{a\in A}\in \mathbb{A}^{\zeta}_{\xi}(\mathcal{X})}\int_{A}\varrho_{a}(Y_{a})\mu(da),
    \end{equation*}
    as desired.
\end{proof}
\section{The Weak-Star Strassen Theorem}\label{sec:tech}
Theorem 2.2 of Hiai and Umegaki \cite{hiai-umegaki} establishes an integral exchange formula for correspondences valued in a separable Banach space, allowing one to swap an infimum (equivalently, a supremum) and an integral, allowing one to characterize the support function of certain set integrals. The Hiai-Umegaki result is an example of a Strassen-type theorem. Strassen-type theorems have been extended to cover correspondences valued in separable Banach spaces equipped with the weak topology (see \cite{strass-pettis}), correspondences valued in the compact subsets of a locally convex topological vector space (see \cite{strass-comp}), and have ramifications even in the finite dimensional case (see \cite{aumann-exchange}). However, the literature on this topic is both highly technical and likely not directly applicable to our circumstances (e.g. requiring the correspondence to take weak-star compact values). Thus, in this section, we derive a Strassen-type theorem for correspondences valued in the dual of a separable Banach space, with measurability and integration understood in a weak-star sense.
\subsection{Notation}
Let $(A,\mathscr{A},\mu)$ denote a finite complete measure space. The trace $\sigma$-algebra $\{C\cap B:C\in\mathscr{A}\}$ of $B\in\mathscr{A}$ is denoted $\mathscr{A}_{B}$. Let $E$ be a separable Banach space; denote by $B$ the unit ball of $E$, and let $B^{\ast}=B^{\circ}$ denote the closed unit ball of $E^{\ast}$, the dual of $E$.
\par
A function $f:A\longrightarrow E^{\ast}$ is said to be $\mathscr{A}$-measurable if $a\longmapsto\langle{x,f(a)}\rangle$ is $\mathscr{A}$-measurable for each $x\in E$. An $\mathscr{A}$-measurable function $f:A\longrightarrow E^{\ast}$ is said to be Gelfand integrable if $\langle{x,f}\rangle\in L^{1}(\mu)$ for each $x\in E$. If $f$ is Gelfand integrable, and $B\in\mathscr{A}$, there exists a unique element $g_{B}\in E^{\ast}$ such that $\langle{x,g_{B}}\rangle=\int_{B}\langle{x,f(a)}\rangle\mu(da)$. The element $g_{B}$ is denoted $\int_{B}f(a)\mu(da)$, and is called the Gelfand integral of $f$ over $B$. These notions all parallel those introduced for $E^{\ast}=L^{\infty}(\mathbb{P})$ in \S\ref{subsec:alloc}.
\par
Consider a correspondence $F:A\longrightarrow 2^{E^{\ast}}$. Given a subset $U\subseteq E^{\ast}$, define
\begin{equation*}
    F^{-1}(U)=\{a\in A:F(a)\cap U\neq\emptyset\}.
\end{equation*}
An integrable selector of $F$ is a Gelfand integrable function $f:A\longrightarrow E^{\ast}$ such that $f(a)\in F(a)$ for $\mu$-a.e. $a\in A$. The set of integrable selectors of $F$ is denoted $S^{1}(F)$.
\begin{definition}\label{def:aumann-int}
    The Aumann integral of $F$, denoted $\int_{A}F(a)\mu(da)$, is the subset of $E^{\ast}$ defined by
    \begin{equation*}
        \int_{A}F(a)\mu(da)=\left\{\int_{A}f(a)\mu(da):f\in S^{1}(F)\right\}.
    \end{equation*}
\end{definition}
In a similar fashion to the above concept of integration, one can introduce notions of measurability for correspondences.
\begin{definition}\label{def:corr-measurable}
    $F$ is said to be $\mathscr{A}$-measurable if $F^{-1}(U)\in\mathscr{A}$ for every $\sigma(E^{\ast},E)$-closed $U\subseteq E^{\ast}$.
\end{definition}
\begin{definition}\label{def:effros}
    $F$ is said to be Effros $\mathscr{A}$-measurable if $F^{-1}(U)\in\mathscr{A}$ for every $\sigma(E^{\ast},E)$-open $U\subseteq E^{\ast}$.
\end{definition}
Definition \ref{def:corr-measurable} and Definition \ref{def:effros} are coherent for correspondences valued in any topological space, not just $(E^{\ast},\sigma(E^{\ast},E))$. In the sequel, we generally employ $\mathscr{A}$-measurability rather than Effros $\mathscr{A}$-measurability, since the former has better stability properties. However, since many results are stated in terms of Effros $\mathscr{A}$-measurability, we cannot expunge Definition \ref{def:effros} from our analysis.
\par
From this point onward, we use $F$ to denote an $\mathscr{A}$-measurable correspondence with non-empty $\sigma(E^{\ast},E)$-closed values.
\subsection{Preliminary Results}
For $\lambda\geq0$, define a correspondence $F_{\lambda}:A\longrightarrow 2^{\lambda B^{\ast}}$ by $F_{\lambda}=F\cap\lambda B^{\ast}$. $F_{\lambda}$ is $\mathscr{A}$-measurable. Define $\widetilde{F}_{\lambda}$ as the restriction of $F_{\lambda}$ to $R_{\lambda}=F^{-1}(\lambda B^{\ast})\in\mathscr{A}$; it is easy to see that $\widetilde{F}_{\lambda}$ is $\mathscr{A}_{R_{\lambda}}$-measurable.
\begin{lemma}\label{lem:count-represent}
    There exists a collection $\{f_{n}:n\in\mathbb{N}\}\subseteq (E^{\ast})^{A}$ of $\mathscr{A}$-measurable functions such that
    \begin{equation*}
        F(a)=\overline{\bigcup_{n\in\mathbb{N}}\{f_{n}(a)\}}^{\sigma(E^{\ast},E)}
    \end{equation*}
    for each $a\in A$.
\end{lemma}
\begin{proof}
    Take $\lambda$ large enough so $R_{\lambda}\neq\emptyset$. By a result of Himmelberg \cite{himm-meas}, since $\lambda B^{\ast}$ is a Polish space and $\widetilde{F}_{\lambda}$ is $\mathscr{A}_{R_{\lambda}}$-measurable, there exists a collection $\{g_{n}^{\lambda}:n\in\mathbb{N}\}\subseteq (E^{\ast})^{R_{\lambda}}$ of $\mathscr{A}_{R_{\lambda}}$-measurable functions such that
    \begin{equation*}
        F(a)=\overline{\bigcup_{n\in\mathbb{N}}\left\{g_{n}^{\lambda}(a)\right\}}^{\sigma(E^{\ast},E)}
    \end{equation*}
    for each $a\in R_{\lambda}$. If there exists an $\mathscr{A}$-measurable $h:A\longrightarrow E^{\ast}$ such that $h(a)\in F(a)$ for each $a\in A$, the claim is proved. Indeed, take $(\lambda_{n})_{n=1}^{\infty}\uparrow\infty$, and consider the countable collection $\left\{k^{n}_{m}:(n,m)\in\mathbb{N}\times\mathbb{N}\right\}$ of $\mathscr{A}$-measurable functions defined by
    \begin{equation*}
        k^{n}_{m}|_{R_{\lambda_{n}}}=g^{\lambda_{n}}_{m},
    \end{equation*}
    \begin{equation*}
        k^{n}_{m}|_{A\setminus R_{\lambda_{n}}}=h.
    \end{equation*}
    Then $F(a)=\overline{\bigcup_{(n,m)\in\mathbb{N}\times\mathbb{N}}\{k^{n}_{m}(a)\}}^{\sigma(E^{\ast},E)}$, proving the claim, since one can consider a bijection $\mathbb{N}\longrightarrow\mathbb{N}\times\mathbb{N}$.
    \par
    We now prove the existence of an $\mathscr{A}$-measurable $h:A\longrightarrow E^{\ast}$ such that $h(a)\in F(a)$ for each $a\in A$. There exists a disjoint partition $\{D_{n}:n\in G\subseteq\mathbb{N}\}\subseteq\mathscr{A}\setminus\{\emptyset\}$ of $A$ such that for each $n\in G$, $D_{n}\subseteq F^{-1}(\lambda' B^{\ast})$ for large enough $\lambda'$ (which may depend on $n$).\footnote{For example, take $\widetilde{\lambda}$ large enough so that $R_{\widetilde{\lambda}}\neq\emptyset$. Define $D_{1}=F^{-1}\left(\widetilde{\lambda}B^{\ast}\right)$, and let $D_{n+1}=F^{-1}\left((n+1)\widetilde{\lambda}B^{\ast}\right)\setminus F^{-1}\left(n\widetilde{\lambda}B^{\ast}\right)$. Taking $G=\{n:D_{n}\neq\emptyset\}$ yields the desired construction.} Fix $n\in G$. Since $\lambda'B^{\ast}$ is a Polish space and $\widetilde{F}_{\lambda'}$ is $\mathscr{A}_{R_{\lambda'}}$-measurable (hence also Effros $\mathscr{A}_{R_{\lambda'}}$-measurable, see Lemma 18.2 of \cite{aliprantis-inf-dim}), the Kuratowski-Ryll-Nardzewski selection theorem (see pg. 600, \cite{aliprantis-inf-dim}) implies the existence of an $\mathscr{A}$-measurable $h_{n}:D_{n}\longrightarrow E^{\ast}$ with $h_{n}(a)\in F(a)$ for each $a\in D_{n}$. Allowing $n$ to vary, we may define $h$ by setting $h|_{D_{n}}=h_{n}$ for each $n\in G$.
\end{proof}
\begin{lemma}\label{lem:sup-measurable}
    Let $F$ be $\mathscr{A}$-measurable. Then, for every $x\in E$, the function
    \begin{equation*}
        a\longmapsto\sup_{x^{\ast}\in F(a)}\langle{x,x^{\ast}}\rangle
    \end{equation*}
    is $\mathscr{A}$-measurable.
\end{lemma}
\begin{proof}
    Let $\{f_{n}:n\in\mathbb{N}\}$ be as in Lemma \ref{lem:count-represent}. Since the map $x^{\ast}\longmapsto\langle{x,x^{\ast}}\rangle$ is $\sigma(E^{\ast},E)$-continuous for each $x\in E$, it follows that, for each $x\in E$,
    \begin{equation*}
        \sup_{x^{\ast}\in F(a)}\langle{x,x^{\ast}}\rangle=\sup_{n\in\mathbb{N}}\langle{x,f_{n}(a)}\rangle,
    \end{equation*}
    representing $a\longmapsto\sup_{x^{\ast}\in F(a)}\langle{x,x^{\ast}}\rangle$ as a countable supremum of $\mathscr{A}$-measurable functions.
\end{proof}
\subsection{Statement of the Result}
\begin{theorem}\label{thm:hiai-umegaki}
    Suppose $S^{1}(F)\neq\emptyset$. For all $x\in E$, we have that
    \begin{equation*}
        \sup_{x^{\ast}\in\int_{A}F(a)\mu(da)}\langle{x,x^{\ast}}\rangle=\int_{A}\sup_{x^{\ast}\in F(a)}\langle{x,x^{\ast}}\rangle\mu(da).
    \end{equation*}
\end{theorem}
Note that Lemma \ref{lem:sup-measurable} implies that $a\longmapsto\sup_{x^{\ast}\in F(a)}\langle{x,x^{\ast}}\rangle$ is $\mathscr{A}$-measurable, making the integral in Theorem \ref{thm:hiai-umegaki} above well-defined.
\par
Let us state a corollary to Theorem \ref{thm:hiai-umegaki}, which is more directly applicable to our situation with risk measures than Theorem \ref{thm:hiai-umegaki}. Rather than being interested in the supremum of $\langle{x,x^{\ast}}\rangle$ over $x^{\ast}\in\int_{A}F(a)\mu(da)$, we are interested in the supremum of a larger set $C\supseteq\int_{A}F(a)\mu(da)$.
\begin{theorem}\label{thm:hiai-umegaki-dense}
    Suppose $S^{1}(F)\neq\emptyset$, and let $C$ be such that $C=\overline{\int_{A}F(a)\mu(da)}^{\mathscr{T}}$ for some topology $\mathscr{T}$ finer than $\sigma(E^{\ast},E)$. For all $x\in E$, we have that
    \begin{equation*}
        \sup_{x^{\ast}\in C}\langle{x,x^{\ast}}\rangle=\int_{A}\sup_{x^{\ast}\in F(a)}\langle{x,x^{\ast}}\rangle\mu(da).
    \end{equation*}
\end{theorem}
\begin{proof}
    The claim is a trivial joint consequence of Theorem \ref{thm:hiai-umegaki} and $\mathscr{T}$-continuity of the map $x^{\ast}\longmapsto\langle{x,x^{\ast}}\rangle$.
\end{proof}
\subsection{Proof of Theorem \ref{thm:hiai-umegaki}}
\begin{proof}[Proof of Theorem \ref{thm:hiai-umegaki}]
    Let $\Xi(a)=\sup_{x^{\ast}\in F(a)}\langle{x,x^{\ast}}\rangle$. If the claim were false, there would exist $\beta<\int_{A}\Xi(a)\mu(da)$ such that $\beta>\left\langle{x,\int_{A}g(a)\mu(da)}\right\rangle$ for each $g\in S^{1}(F)$.
    \par
    Let $(\Xi_{n})_{n=1}^{\infty}$ be a sequence of $\mathscr{A}$-measurable simple functions increasing to $\Xi$. Define a correspondence $G_{n}:A\longrightarrow 2^{E^{\ast}}$ by
    \begin{equation*}
        G_{n}(a)=F(a)\cap\left\{x^{\ast}:\langle{x,x^{\ast}}\rangle\geq\Xi_{n}(a)-\frac{1}{n}\right\}.
    \end{equation*}
    It is easy to see that $G_{n}(a)$ is closed and non-empty for each $a\in A$. We claim that $G_{n}$ is $\mathscr{A}$-measurable. Indeed, if $U\subseteq E^{\ast}$ is $\sigma(E^{\ast},E)$-closed,
    \begin{equation*}
        G^{-1}_{n}(U)=\bigcup_{\alpha\in\Xi_{n}(A)}F^{-1}\left(U\cap\left\{x^{\ast}:\langle{x,x^{\ast}}\rangle\geq\alpha-\frac{1}{n}\right\}\right)\cap\left\{\Xi_{n}=\alpha\right\}
    \end{equation*}
    which is $\mathscr{A}$-measurable, since $F$ is $\mathscr{A}$-measurable, and $U\cap\left\{x^{\ast}:\langle{x,x^{\ast}}\rangle\geq\alpha-\frac{1}{n}\right\}$ is $\sigma(E^{\ast},E)$-closed for each $\alpha$ (being an intersection of $\sigma(E^{\ast},E)$-closed sets), representing the above as a finite (indexed by the range of $\Xi_{n}(A)$) union of $\mathscr{A}$-measurable sets.
    \par
    Fix $n\in\mathbb{N}$. By the same argument as in the proof of Lemma \ref{lem:count-represent}, there exists an $\mathscr{A}$-measurable $h_{n}:A\longrightarrow E^{\ast}$ such that $h_{n}(a)\in G_{n}(a)$ for each $a\in A$. Thus, by letting $n$ be arbitrary, we may presume the existence of a sequence $(h_{n})_{n=1}^{\infty}\subseteq(E^{\ast})^{A}$ of $\mathscr{A}$-measurable functions such that $h_{n}(a)\in G_{n}(a)$ for each $a\in A$.
    \par
    Since $S^{1}(F)\neq\emptyset$ by assumption, we may fix $f_{0}\in S^{1}(F)$. Define $B^{n,m}=h_{n}^{-1}(mB^{\ast})\in\mathscr{A}$. Define $h_{n,m}=\mathbf{1}_{B^{n,m}}h_{n}+\mathbf{1}_{A\setminus B^{n,m}}f_{0}$. Clearly, $h_{n,m}\in S^{1}(F)$. Notice that
    \begin{equation}\label{eq:limiting-approx}
        \left\langle{x,\int_{A}}h_{n,m}(a)\mu(da)\right\rangle=\left\langle{x,\int_{B^{n,m}}}h_{n}(a)\mu(da)\right\rangle+\left\langle{x,\int_{A\setminus B^{n,m}}}f_{0}(a)\mu(da)\right\rangle
    \end{equation}
    \begin{equation*}
        \geq\int_{B^{n,m}}\left(\Xi_{n}(a)-\frac{1}{n}\right)\mu(da)+\left\langle{x,\int_{A\setminus B^{n,m}}}f_{0}(a)\mu(da)\right\rangle.
    \end{equation*}
    Taking $m\to\infty$ on the last expression in (\ref{eq:limiting-approx}) yields $\int_{A}\left(\Xi_{n}(a)-\frac{1}{n}\right)\mu(da)$.
    Thus, for any $\varepsilon>0$, there exists $f\in S^{1}(F)$ such that
    \begin{equation}\label{eq:make-small}
        \left\langle{x,\int_{A}}f(a)\mu(da)\right\rangle\geq\int_{A}\left(\Xi_{n}(a)-\frac{1}{n}\right)\mu(da)-\varepsilon.
    \end{equation}
    for all $n$.
    \par
    For some $n_{0}\in\mathbb{N}$ and small $\delta>0$, we have that $\beta<\int_{A}\Xi_{n}(a)\mu(da)-\delta$ for all $n\geq n_{0}$. Take $n_{1}\in\mathbb{N}$ with $\frac{1}{n_{1}}\leq\frac{\delta}{2\mu(A)}$. Using (\ref{eq:make-small}), take $f\in S^{1}(F)$ with
    \begin{equation*}
        \left\langle{x,\int_{A}}f(a)\mu(da)\right\rangle\geq\int_{A}\left(\Xi_{n}(a)-\frac{1}{n}\right)\mu(da)-\frac{\delta}{2}
    \end{equation*}
    for all $n$. Then, for any $n\geq n_{0}\vee n_{1}$,
    \begin{equation*}
        \beta<\int_{A}\Xi_{n}(a)\mu(da)-\delta\leq\int_{A}\left(\Xi_{n}(a)-\frac{1}{n}\right)\mu(da)-\frac{\delta}{2}\leq\left\langle{x,\int_{A}}f(a)\mu(da)\right\rangle
    \end{equation*}
    contradicting $\beta>\left\langle{x,\int_{A}}f(a)\mu(da)\right\rangle$.
\end{proof}
\section{Proof of Theorem \ref{thm:dual-rep-represent}}\label{sec:prf-of-thm-rep}
In this section, we prove Theorem \ref{thm:dual-rep-represent}. Various tools are employed, including results from Appendix \ref{sec:tech}, and some results about acceptance sets (see \S\ref{subsec:accept} below).
\subsection{Acceptance Sets}\label{subsec:accept}
Given a risk measure $\varrho$, the acceptance set $\mathfrak{A}(\varrho)$ is defined by
\begin{equation*}
    \mathfrak{A}(\varrho)=\{\mathcal{X}:\varrho(\mathcal{X})\leq0\}.
\end{equation*}
The Fatou property implies that $\mathfrak{A}(\varrho)$ is $\sigma(L^{\infty},L^{1})$-closed.
\subsubsection{Characterizing the Acceptance Set}\label{subsubsec:char-accept}
In this subsection, we provide a characterization of the acceptance set of the integral infimal convolution of $(\varrho_{a})_{a\in A}$, in terms of the closure of a certain Aumann integral.
\par
Recall the Aumann integral from Definition \ref{def:aumann-int} in Appendix \ref{sec:tech}, which we reproduce here in a slightly less abstract setting. Given a correspondence $F:A\longrightarrow 2^{L^{\infty}(\mathbb{P})}$, an integrable selector of $F$ is an $\mathscr{A}$-measurable Gelfand integrable function $(X_{a})_{a\in A}\in\left(L^{\infty}(\mathbb{P})\right)^{A}$ such that $X_{a}\in F(a)$ for $\mu$-a.e. $a\in A$. The set of all integrable selectors of $F$ is denoted $S^{1}(F)$. The Aumann integral $\int_{A}F(a)\mu(da)$ of $F$ is defined as
\begin{equation*}
    \int_{A}F(a)\mu(da)=\left\{\int_{A}X_{a}\mu(da):(X_{a})_{a\in A}\in S^{1}(F)\right\}.
\end{equation*}
\begin{theorem}\label{thm:accept-set-characterize}
    Suppose $\operatorname{\Box}_{a\in A}\varrho_{a}\mu(da)$ is globally finite. Then, the acceptance set $\mathfrak{A}\left(\operatorname{\Box}_{a\in A}\varrho_{a}\mu(da)\right)$ of $\operatorname{\Box}_{a\in A}\varrho_{a}\mu(da)$ is the $L^{\infty}(\mathbb{P})$-closure of the Aumann integral $\int_{A}\mathfrak{A}(\varrho_{a})\mu(da)$.
\end{theorem}
\begin{proof}
    We follow the same idea as the proof of (Theorem 4.1, \cite{felixfs}), replacing finite Minkowski sums with Aumann integrals.
    \par
    Clearly, $\int_{A}\mathfrak{A}(\varrho_{a})\mu(da)\subseteq\mathfrak{A}\left(\operatorname{\Box}_{a\in A}\varrho_{a}\mu(da)\right)$. Since the integral infimal convolution is monotone and cash additive, we may apply the same argument as (Lemma 4.3, \cite{stoch-fin}) to obtain that $\mathfrak{A}\left(\operatorname{\Box}_{a\in A}\varrho_{a}\mu(da)\right)$ is $L^{\infty}(\mathbb{P})$-closed, implying $\overline{\int_{A}\mathfrak{A}(\varrho_{a})\mu(da)}^{L^{\infty}}\subseteq\mathfrak{A}\left(\operatorname{\Box}_{a\in A}\varrho_{a}\mu(da)\right)$. Thus, it suffices to show the reverse inclusion.
    \par
    Let $\mathcal{X}\in\mathfrak{A}\left(\operatorname{\Box}_{a\in A}\varrho_{a}\mu(da)\right)$; denote $w=\left(\operatorname{\Box}_{a\in A}\varrho_{a}\mu(da)\right)(\mathcal{X})\leq0$. By cash additivity, $\left(\operatorname{\Box}_{a\in A}\varrho_{a}\mu(da)\right)\left(\mathcal{X}-w\right)=0$. Thus, there exists a sequence $\left((X^{n}_{a})_{a\in A}\right)_{n=1}^{\infty}\subseteq\mathbb{A}(\mathcal{X}-w)$ such that
    \begin{equation*}
        \lim_{n\to\infty}\int_{A}\varrho_{a}\left(X^{n}_{a}\right)\mu(da)=0.
    \end{equation*}
    Let $Y^{n}_{a}=X^{n}_{a}-\varrho_{a}(X^{n}_{a})$. Clearly, $(Y^{n}_{a})_{a\in A}\in\mathfrak{A}(\varrho_{a})$, implying that $\int_{A}Y^{n}_{a}\mu(da)\in\int_{A}\mathfrak{A}(\varrho_{a})\mu(da)$. Thus, since the $L^{\infty}(\mathbb{P})$-limit of $\left(\int_{A}Y^{n}_{a}\mu(da)\right)_{n=1}^{\infty}$ is $\mathcal{X}-w$, it follows that $\mathcal{X}-w\in\overline{\int_{A}\mathfrak{A}(\varrho_{a})\mu(da)}^{L^{\infty}}$. Since $w\leq0$, it follows that $\mathcal{X}\in\overline{\int_{A}\mathfrak{A}(\varrho_{a})\mu(da)}^{L^{\infty}}$, as desired.
\end{proof}
\subsubsection{Representing the Dual via Acceptance Sets}
In this subsection, we state a known result connecting acceptance sets to convex conjugates. This allows us to apply our results on the correspondence $a\longmapsto\mathfrak{A}(\varrho_{a})$ to dual representations.
\begin{lemma}\label{lem:dual-accept-set}
    Let $\varrho$ be any risk measure. Then, for any $\mathbb{Q}\in\mathscr{M}_{\mathbb{P}}$,
    \begin{equation*}
        \varrho^{\ast}(\mathbb{Q})=\sup_{\mathcal{X}\in\mathfrak{A}(\varrho)}\mathbb{E}^{\mathbb{Q}}(\mathcal{X}).
    \end{equation*}
\end{lemma}
\begin{proof}
    Fix $\mathbb{Q}\in\mathscr{M}_{\mathbb{P}}$; clearly, $\sup_{\mathcal{X}\in\mathfrak{A}(\varrho)}\mathbb{E}^{\mathbb{Q}}(\mathcal{X})\leq\varrho^{\ast}(\mathbb{Q})$. By cash additivity,
    \begin{equation*}
        \sup_{\mathcal{X}\in\mathfrak{A}(\varrho)}\mathbb{E}^{\mathbb{Q}}(\mathcal{X})\leq\varrho^{\ast}(\mathbb{Q})=\sup_{\mathcal{X}\in L^{\infty}(\mathbb{P})}\left(\mathbb{E}^{\mathbb{Q}}(\mathcal{X})-\varrho(\mathcal{X})\right)
    \end{equation*}
    \begin{equation*}
        =\sup_{\mathcal{X}\in L^{\infty}(\mathbb{P})}\left(\mathbb{E}^{\mathbb{Q}}(\mathcal{X}-\varrho(X))-\varrho(\mathcal{X}-\varrho(X))\right)=\sup_{\mathcal{X}\in\{\varrho=0\}}\mathbb{E}^{\mathbb{Q}}\left(\mathcal{X}\right)\leq\sup_{\mathcal{X}\in\mathfrak{A}(\varrho)}\mathbb{E}^{\mathbb{Q}}(\mathcal{X})
    \end{equation*}
    implying that $\sup_{\mathcal{X}\in\mathfrak{A}(\varrho)}\mathbb{E}^{\mathbb{Q}}(\mathcal{X})\leq\varrho^{\ast}(\mathbb{Q})\leq\sup_{\mathcal{X}\in\mathfrak{A}(\varrho)}\mathbb{E}^{\mathbb{Q}}(\mathcal{X})$, showing that $\varrho^{\ast}(\mathbb{Q})=\sup_{\mathcal{X}\in\mathfrak{A}(\varrho)}\mathbb{E}^{\mathbb{Q}}(\mathcal{X})$. Since $\mathbb{Q}\in\mathscr{M}_{\mathbb{P}}$ was arbitrary, this proves the claim.
\end{proof}
\subsubsection{Measurability of the Acceptance Set Correspondence}
In this subsection, we establish that the acceptance set correspondence $a\longmapsto\mathfrak{A}(\varrho_{a})$ is $\mathscr{A}$-measurable in the sense of Definition \ref{def:corr-measurable} from Appendix \ref{sec:tech}.
\begin{lemma}\label{lem:measurable-corr-accept}
    Let $U\subseteq L^{\infty}(\mathbb{P})$ be $\sigma(L^{\infty},L^{1})$-closed. Then
    \begin{equation*}
        \left\{a\in A:U\cap\mathfrak{A}(\varrho_{a})\neq\emptyset\right\}\in\mathscr{A}.
    \end{equation*}
\end{lemma}
\begin{proof}
    It is no loss of generality to assume that $U$ is bounded in $L^{\infty}(\mathbb{P})$, since one can write $U$ as a countable union of closed and $L^{\infty}(\mathbb{P})$-bounded sets. Furthermore, we may assume that $U\neq\emptyset$ (if $U=\emptyset$, the claim would be trivial).
    \par
    We claim that
    \begin{equation}\label{eq:sets-do-be-equal}
        \left\{a\in A:U\cap\mathfrak{A}(\varrho_{a})\neq\emptyset\right\}=\left\{a\in A:\inf_{\mathcal{Y}\in U}\varrho_{a}(\mathcal{Y})\leq0\right\}.
    \end{equation}
    Clearly, $\left\{a\in A:U\cap\mathfrak{A}(\varrho_{a})\neq\emptyset\right\}\subseteq\left\{a\in A:\inf_{\mathcal{Y}\in U}\varrho_{a}(\mathcal{Y})\leq0\right\}$. Thus, it suffices to show the reverse inclusion. If $\inf_{\mathcal{Y}\in U}\varrho_{a}(\mathcal{Y})\leq0$, there exists $(\mathcal{Y}^{n})_{n=1}^{\infty}\subseteq U$ such that
    \begin{equation*}
        \varrho_{a}\left(\mathcal{Y}^{n}\right)\leq\frac{1}{n}.
    \end{equation*}
    Using the Banach-Alaoglu theorem, $L^{\infty}(\mathbb{P})$-boundedness of $U$, and $\sigma(L^{\infty},L^{1})$-closedness of $U$, we may find a subsequence $(n_{k})_{k=1}^{\infty}$ such that $(\mathcal{Y}^{n_{k}})_{k=1}^{\infty}$ converges to some $\mathcal{Z}\in U$ in $\sigma(L^{\infty},L^{1})$. For each $n$, there exists $k_{0}$ such that $k\geq k_{0}$ implies $\mathcal{Y}^{n_{k}}\in\{\varrho_{a}\leq\frac{1}{n}\}$. The Fatou property implies the set $\left\{\varrho_{a}\leq\frac{1}{n}\right\}$ is $\sigma(L^{\infty},L^{1})$-closed, and we therefore have that $\mathcal{Z}\in\left\{\varrho_{a}\leq\frac{1}{n}\right\}$ for each $n$. Thus,
    \begin{equation*}
        \mathcal{Z}\in\bigcap_{n\in\mathbb{N}}\left\{\varrho_{a}\leq\frac{1}{n}\right\}=\{\varrho_{a}\leq0\}.
    \end{equation*}
    By the above argument, there exists $\mathcal{Z}\in U$ with $\varrho_{a}(\mathcal{Z})\leq0$, implying that $a\in\left\{b\in A:U\cap\mathfrak{A}(\varrho_{b})\neq\emptyset\right\}$, as desired.
    \par
    As a consequence of (\ref{eq:sets-do-be-equal}), it suffices to show that $a\longmapsto\inf_{\mathcal{Y}\in U}\varrho_{a}(\mathcal{Y})$ is $\mathscr{A}$-measurable. Let $V\subseteq U$ be a countable dense set for the topology $\tau_{L^{0}}$ of convergence in probability restricted to $U$ (such a set exists, since $(\Omega,\mathscr{F},\mathbb{P})$ is separable). We claim that
    \begin{equation}\label{eq:infs-equal-dense}
        \inf_{\mathcal{Y}\in U}\varrho_{a}(\mathcal{Y})=\inf_{\mathcal{Y}\in V}\varrho_{a}(\mathcal{Y}),
    \end{equation}
    for all $a\in A$, which would prove the claim, since $a\longmapsto\inf_{\mathcal{Y}\in U}\varrho_{a}(\mathcal{Y})$ would be a countable infimum of $\mathscr{A}$-measurable functions. Since $\varrho_{a}$ has the Lebesgue property, $U$ is $L^{\infty}(\mathbb{P})$-bounded, and $\overline{V}^{\tau_{L^{0}}}=U$, (\ref{eq:infs-equal-dense}) holds.
\end{proof}
\subsection{The Proof}
\begin{proof}[Proof of Theorem \ref{thm:dual-rep-represent}]
    Recall that
    \begin{equation*}
        \left(\operatorname{\Box}_{a\in A}\varrho_{a}\mu(da)\right)^{\ast}(\mathbb{Q})=\sup_{\mathcal{X}\in L^{\infty}(\mathbb{P})}\left(\mathbb{E}^{\mathbb{Q}}(\mathcal{X})-\left(\operatorname{\Box}_{a\in A}\varrho_{a}\mu(da)\right)(\mathcal{X})\right)
    \end{equation*}
    for each $\mathbb{Q}\in \mathscr{M}_{\mathbb{P}}$. By Lemma \ref{lem:dual-accept-set} and Theorem \ref{thm:accept-set-characterize},
    \begin{equation}\label{eq:phi-accept-int}
        \left(\operatorname{\Box}_{a\in A}\varrho_{a}\mu(da)\right)^{\ast}(\mathbb{Q})=\sup_{\mathcal{X}\in\overline{\int_{A}\mathfrak{A}(\varrho_{a})}^{L^{\infty}}}\mathbb{E}^{\mathbb{Q}}\left(\mathcal{X}\right).
    \end{equation}
    We claim that $S^{1}(F)\neq\emptyset$ ($S^{1}(F)$ is defined in \S\ref{subsubsec:char-accept}), where $F$ is the correspondence $F=\left(a\longmapsto\mathfrak{A}(\varrho_{a})\right)$. Define $(X_{a})_{a\in A}\in\left(L^{\infty}(\mathbb{P})\right)^{A}$ by setting
    \begin{equation*}
        X_{a}=-\varrho_{a}(0).
    \end{equation*}
    It is easy to see that $(X_{a})_{a\in A}$ is $\mathscr{A}$-measurable; furthermore, since $\int_{A}\vert{\varrho_{a}(0)}\vert\mu(da)<\infty$, $(X_{a})_{a\in A}$ is Gelfand integrable. For each $a\in A$, we have that
    \begin{equation*}
        \varrho_{a}(X_{a})=\varrho_{a}(-\varrho_{a}(0))=\varrho_{a}(0)+(-\varrho_{a}(0))=0\leq0
    \end{equation*}
    by cash additivity. Thus, $X_{a}\in F(a)$ for each $a\in A$. These facts together imply that $(X_{a})_{a\in A}\in S^{1}(F)$, showing that $S^{1}(F)\neq\emptyset$.
    \par
    By Lemma \ref{lem:measurable-corr-accept}, $F$ is $\mathscr{A}$-measurable in the sense of Definition \ref{def:corr-measurable} from Appendix \ref{sec:tech}. Thus, since $S^{1}(F)\neq\emptyset$, the preconditions for Theorem \ref{thm:hiai-umegaki} and Theorem \ref{thm:hiai-umegaki-dense} are met. Noting that the norm topology on $L^{\infty}(\mathbb{P})$ is finer than $\sigma(L^{\infty},L^{1})$, Theorem \ref{thm:hiai-umegaki-dense} and (\ref{eq:phi-accept-int}) imply that
    \begin{equation*}
        \left(\operatorname{\Box}_{a\in A}\varrho_{a}\mu(da)\right)^{\ast}(\mathbb{Q})=\int_{A}\sup_{\mathcal{X}\in F(a)}\mathbb{E}^{\mathbb{Q}}\left(\mathcal{X}\right)\mu(da),
    \end{equation*}
    where we note that $a\longmapsto\sup_{\mathcal{X}\in F(a)}\mathbb{E}^{\mathbb{Q}}\left(\mathcal{X}\right)$ is $\mathscr{A}$-measurable, by virtue of Lemma \ref{lem:sup-measurable}. By Lemma \ref{lem:dual-accept-set}, we have that $\varrho^{\ast}_{a}(\mathbb{Q})=\sup_{\mathcal{X}\in F(a)}\mathbb{E}^{\mathbb{Q}}\left(\mathcal{X}\right)$ for each $a\in A$, which implies that $a\longmapsto\varrho^{\ast}(\mathbb{Q})$ is $\mathscr{A}$-measurable, and that
    \begin{equation*}
        \left(\operatorname{\Box}_{a\in A}\varrho_{a}\mu(da)\right)^{\ast}(\mathbb{Q})=\int_{A}\varrho^{\ast}_{a}(\mathbb{Q})\mu(da),
    \end{equation*}
    as desired.
\end{proof}
\section{Proof of Theorem \ref{thm:attain-notattain}}\label{sec:prf-attain-notattain}
In this section, we prove the second part of Theorem \ref{thm:attain-notattain}, showing that under certain circumstances the risk sharing problem is not well-posed.
\subsection{A Separation Lemma}
For the proof of Theorem \ref{thm:attain-notattain}, it is necessary for $\mathcal{X}$ to be far away from random variables which are unaffected by a change in the inflation parameter $\gamma$. The following lemma ensures this holds in the weak-star topology $\sigma(L^{\infty},L^{1})$.
\begin{lemma}\label{lem:separate}
    There exists a $\sigma(L^{\infty},L^{1})$-neighborhood $U$ of $0$, such that
    \begin{equation*}
        \mathcal{X}\notin U+\overline{\mathrm{co}\left(\bigcup_{\gamma\in(\Gamma,\Gamma')}\bigcup_{\varepsilon>0}\left\{\widetilde{\varrho}_{\gamma}=\widetilde{\varrho}_{\gamma+\varepsilon}\right\}\right)}^{\sigma(L^{\infty},L^{1})}
    \end{equation*}
\end{lemma}
\begin{proof}
    Denote $D=\overline{\mathrm{co}\left(\bigcup_{\gamma\in(\Gamma,\Gamma')}\bigcup_{\varepsilon>0}\left\{\widetilde{\varrho}_{\gamma}=\widetilde{\varrho}_{\gamma+\varepsilon}\right\}\right)}^{\sigma(L^{\infty},L^{1})}$. Using the geometric Hahn-Banach theorem, noting that the singleton $\{\mathcal{X}\}\neq\emptyset$ is convex and $\sigma(L^{\infty},L^{1})$-compact, the set $D\neq\emptyset$ is convex and $\sigma(L^{\infty},L^{1})$-closed, and $\{\mathcal{X}\}\cap D=\emptyset$, we may find $\mathcal{Y}\in L^{1}(\mathbb{P})$ and $\delta>0$ such that
    \begin{equation}\label{eq:hb-sep}
        \mathbb{E}^{\mathbb{P}}\left(\mathcal{X}\mathcal{Y}\right)<\lambda-\delta
    \end{equation}
    where $\lambda=\inf_{\mathcal{Z}\in D}\mathbb{E}^{\mathbb{P}}\left(\mathcal{Z}\mathcal{Y}\right)$ (see pg. 65, \cite{tvs-schaef}). Define $U=\{\mathcal{Z}\in L^{\infty}(\mathbb{P}):\mathbb{E}^{\mathbb{P}}(\mathcal{Z}\mathcal{Y})>-\delta\}$, which is a $\sigma(L^{\infty},L^{1})$-open set containing $0$. It suffices to show that
    \begin{equation*}
        \mathcal{X}\notin U+D
    \end{equation*}
    For the sake of contradiction, suppose there existed $\mathcal{X}'\in U$ and $\mathcal{X}''\in D$ such that $\mathcal{X}=\mathcal{X}'+\mathcal{X}''$. Then $\mathbb{E}^{\mathbb{P}}(\mathcal{X}\mathcal{Y})>\lambda-\delta$, contradicting (\ref{eq:hb-sep}).
\end{proof}
\subsection{The Proof}
\begin{proof}[Proof of Theorem \ref{thm:attain-notattain}]
    We prove the second assertion, which is achieved using contradiction. Assume $(X_{a})_{a\in A}\in\mathbb{A}(\mathcal{X})$ is optimal. We claim that
    \begin{equation}\label{eq:meas-positive}
        \mu\left(\left\{a:\widetilde{\varrho}_{\gamma_{a}}(X_{a})>\widetilde{\varrho}_{\gamma}(X_{a})\right\}\right)>0
    \end{equation}
    for some $\gamma\in(\Gamma,\Gamma')$. Suppose for the sake of contradiction that $\mu\left(\left\{a:\widetilde{\varrho}_{\gamma_{a}}(X_{a})>\widetilde{\varrho}_{\gamma}(X_{a})\right\}\right)=0$ for all $\gamma\in(\Gamma,\Gamma')$. Decompose the complement as the disjoint union
    \begin{equation}\label{eq:disjoint-decomp}
        \left\{a:\widetilde{\varrho}_{\gamma_{a}}(X_{a})\leq\widetilde{\varrho}_{\gamma}(X_{a})\right\}=\left\{a:\widetilde{\varrho}_{\gamma_{a}}(X_{a})<\widetilde{\varrho}_{\gamma}(X_{a})\right\}\cup\left\{a:\widetilde{\varrho}_{\gamma_{a}}(X_{a})=\widetilde{\varrho}_{\gamma}(X_{a})\right\}.
    \end{equation}
    Notice that $\left\{a:\widetilde{\varrho}_{\gamma_{a}}(X_{a})<\widetilde{\varrho}_{\gamma}(X_{a})\right\}\subseteq\{a:\gamma_{a}\leq\gamma\}\downarrow H$ where $\mu(H)=0$ as $\gamma\downarrow\Gamma$, so that
    \begin{equation}\label{eq:measure-to-zero}
        \lim_{\gamma\downarrow\Gamma}\mu\left(\left\{a:\widetilde{\varrho}_{\gamma_{a}}(X_{a})<\widetilde{\varrho}_{\gamma}(X_{a})\right\}\right)=0.
    \end{equation}
    Take $\delta>0$ such that $\Gamma+\delta<\Gamma'$. By (\ref{eq:measure-to-zero}), $\left(\int_{\left\{b:\widetilde{\varrho}_{\gamma_{b}}(X_{b})<\widetilde{\varrho}_{\Gamma+\delta/n}(X_{b})\right\}}X_{a}\mu(da)\right)_{n=1}^{\infty}$ converges to zero in $\sigma(L^{\infty},L^{1})$. Thus, for large enough $n\in\mathbb{N}$ ($n\geq n_{0}$), we have that
    \begin{equation*}
    \int_{\left\{b:\widetilde{\varrho}_{\gamma_{b}}(X_{b})<\widetilde{\varrho}_{\Gamma+\delta/n}(X_{b})\right\}}X_{a}\mu(da)\in U.
    \end{equation*}
    where $U$ is from Lemma \ref{lem:separate}. Denote $D=\overline{\mathrm{co}\left(\bigcup_{\gamma'\in(\Gamma,\Gamma')}\bigcup_{\varepsilon>0}\left\{\widetilde{\varrho}_{\gamma'}=\widetilde{\varrho}_{\gamma'+\varepsilon}\right\}\right)}^{\sigma(L^{\infty},L^{1})}$. By the mean value theorem for Gelfand integrals (see pg. 431, \cite{aliprantis-inf-dim}),
    \begin{equation*}
        \int_{\left\{b:\widetilde{\varrho}_{\gamma_{b}}(X_{b})=\widetilde{\varrho}_{\gamma}(X_{b})\right\}}X_{a}\mu(da)\in\mu\left(\left\{b:\widetilde{\varrho}_{\gamma_{b}}(X_{b})=\widetilde{\varrho}_{\gamma}(X_{b})\right\}\right)D=D
    \end{equation*}
    if $\gamma\in(\Gamma,\Gamma')$. Thus, combining these two facts with the disjoint decomposition (\ref{eq:disjoint-decomp}) and the negation of (\ref{eq:meas-positive}), we have that
    \begin{equation*}
        \mathcal{X}=\int_{A}X_{a}\mu(da)\in U+D
    \end{equation*}
    contradicting assumption (b). Thus, (\ref{eq:meas-positive}) holds for $\gamma=\Gamma+\delta/n_{0}$.
    \par
    Let $B=\{a:\gamma_{a}>\gamma\}$; since $\left\{a:\widetilde{\varrho}_{\gamma_{a}}(X_{a})>\widetilde{\varrho}_{\gamma}(X_{a})\right\}\subseteq B$, $\mu(B)>0$, while since $\gamma\neq\Gamma$, $\mu(A\setminus B)>0$. Define $(Y_{a})_{a\in A}\in\mathbb{A}(\mathcal{X})$ by setting $Y_{a}=\mathbf{1}_{A\setminus B}(a)\left(X_{a}+\frac{1}{\mu(A\setminus B)}\int_{B}X_{b}\mu(db)\right)$. We have that,
    \begin{equation}\label{eq:strict-ineq}
        \int_{A}\varrho_{a}(X_{a})\mu(da)>\int_{A\setminus B}\varrho_{a}(X_{a})\mu(da)+\int_{B}\widetilde{\varrho}_{\gamma}(X_{a})\mu(da),
    \end{equation}
    since $\mu\left(\left\{a:\widetilde{\varrho}_{\gamma_{a}}(X_{a})>\widetilde{\varrho}_{\gamma}(X_{a})\right\}\right)>0$ and $\left\{a:\widetilde{\varrho}_{\gamma_{a}}(X_{a})>\widetilde{\varrho}_{\gamma}(X_{a})\right\}\subseteq B$. Using the Hahn-Banach theorem, one obtains the following Jensen-type inequality,
    \begin{equation*}
        \int_{B}\widetilde{\varrho}_{\gamma}(X_{a})\mu(da)\geq\widetilde{\varrho}_{\gamma}\left(\int_{B}X_{a}\mu(da)\right).
    \end{equation*}
    Combining the above inequality with (\ref{eq:strict-ineq}) and subadditivity of risk measures with dual representation (\ref{eq:dualsetrep}), one obtains that
    \begin{equation*}
        \int_{A}\varrho_{a}(X_{a})\mu(da)>\int_{A\setminus B}\varrho_{a}(X_{a})\mu(da)+\widetilde{\varrho}_{\gamma}\left(\int_{B}X_{a}\mu(da)\right)
    \end{equation*}
    \begin{equation*}
        =\int_{A\setminus B}\left(\varrho_{a}(X_{a})+\frac{1}{\mu(A\setminus B)}\widetilde{\varrho}_{\gamma}\left(\int_{B}X_{a}\mu(da)\right)\right)\mu(da)
    \end{equation*}
    \begin{equation*}
        \geq\int_{A\setminus B}\left(\varrho_{a}(X_{a})+\frac{1}{\mu(A\setminus B)}\varrho_{a}\left(\int_{B}X_{a}\mu(da)\right)\right)\mu(da)
    \end{equation*}
    \begin{equation*}
        =\int_{A\setminus B}\left(\varrho_{a}(X_{a})+\varrho_{a}\left(\frac{1}{\mu(A\setminus B)}\int_{B}X_{a}\mu(da)\right)\right)\mu(da)
    \end{equation*}
    \begin{equation*}
        \geq\int_{A\setminus B}\varrho_{a}\left(X_{a}+\frac{1}{\mu(A\setminus B)}\int_{B}X_{a}\mu(da)\right)\mu(da)=\int_{A}\varrho_{a}(Y_{a})\mu(da),
    \end{equation*}
    contradicting optimality of $(X_{a})_{a\in A}$.
\end{proof}
