	\section{The framework}
	We consider many-to-one matchings between doctors and hospitals. We denote by $H$ a finite set of hospitals. Each hospital $h \in H$ has a finite capacity, denoted by $\kappa_h$.

	We denote by $D$ a finite set of doctors. We assume that $D=M \cup F \cup S$ where $F,M,S$ are pairwise disjoint sets with $|M|=|F|$. Here, the doctors in $F$ and $M$ together form fixed couples. Also, the doctors in $S$ are those who are not part of any couple. We  denote the set of couples by $C=\{\{f_1,m_1\},\{f_2,m_2\},\ldots\}$ and a generic couple by $c=\{f,m\}$. We denote by $\lambda \notin H$, a dummy hospital which we use to represent a doctor being unemployed. 


	Throughout this paper, we assume $|H| \geq 2$, $|D|\geq 4$, $|C| \geq 1$, and $\kappa_h \geq 2$ for all $h \in H$ and $\kappa_{\lambda}=|D|$.

	For notational convenience, we do not always use braces for denoting singleton hospitals, doctors or couples.


	\subsection{Matching}

	\begin{definition}
		A matching $\mu$ is a correspondence from $H \cup \{\lambda\}$ to $D$ such that for all $h \in H$, $|\mu(h)| \leq \kappa_{h}$. Moreover $\mu(h_1) \cap \mu(h_2) = \emptyset$ for any $h_1,h_2 \in H$ with $h_1 \neq h_2$.
	\end{definition}

	For ease of notation, whenever $d \in \mu(h)$ for some $d \in D$ and $h \in H$,  we write  $\mu(d)=h$. We say that a doctor is matched with $\lambda$ to mean that the doctor is unemployed. More formally, if $d \notin \mu(h)$ for all $h \in H$, then  $\mu(d)=\lambda$. For a couple $c=\{f,m\} \in C$ and for hospitals $h,h' \in H \cup \{\lambda \}$, we write $\mu(c)=(h,h')$ to mean  $\mu(f)=h$ and $\mu(m)=h'$. 
	Further, for  a hospital $h \in H$ and a matching $\mu$, we say $h$ has $\kappa_h - |\mu(h)|$ vacant positions at $\mu$.

	\subsection{Preferences}
	In this section, we introduce the notion of preferences of doctors and hospitals, and present some restrictions on them. 

	For a set $X$, we denote by $\mathbb{L}(X)$ the set of linear orders on $X$, i.e., complete, reflexive, transitive, and antisymmetric binary relations over $X$. An element of $\mathbb{L}(X)$ is called a preference (over $X$). For any $i \in H \cup D \cup C$, $R_i$ denotes a preference of $i$ and $P_i$ denotes its strict part. Since a preference is antisymmetric $x R_i y$ implies either $x = y$ or $x P_i y$. We say $x$ is weakly preferred to $y$ to mean  $xR_iy$, and $x$ is (strictly) preferred to $y$ to mean $xP_iy$. For $P_i \in \mathbb{L}(X)$ and $k \leq |X|$, we define the $k$-th ranked element in $P_i$, denoted by $r_k(P_i)$, as follows:  $r_k(P_i)= x \in X$ if $|\{y \in X: yR_i x\}|=k$.

\subsubsection{Preferences of hospitals} 
For any hospital $h \in H$, let $D_h$ be the set of acceptable doctors. A preference of hospital $h$, denoted by $\bar{P}_h$, is a linear order over $D_h$. Thus, $\bar{P}_h \in \mathbb{L}(D_h)$. A hospital prefers to have any doctor from this set of acceptable doctors, over having a vacant spot. Similarly, a hospital prefers to have a vacant spot to having doctors which do not belong to the set of acceptable doctors. We assume that the dummy hospital $\lambda$ finds all doctors acceptable.	Thus, $D_{\lambda}=D$. Also, $\lambda$ is indifferent between all doctors.

	For any hospital $h \in H$, a preference $\bar{P}_h$ over individual doctors is extended  to a preference $P_h$ over feasible subsets of acceptable doctors $\{D' \subseteq D_h : |D'| \leq \kappa_h \}$. 

	\begin{definition}
		We say $P_h \in \mathbb{L}(\{D' \subseteq D_h : |D'| \leq \kappa_h \})$ is \emph{responsive} if	
		\begin{itemize}
			\item[(i)] for all $D' \subseteq D_h$ with $D' \neq \emptyset$ and $|D'| \leq \kappa_h$, $D' P_h \emptyset$.
			\item[(ii)]  for all $d,d' \in D_h$, $\{d\} R_h \{d'\}$ if and only if $d \bar{R}_h d'$, and

			\item[(iii)] for all $D',D'' \subseteq D_h$ with $|D'| < \kappa_h$, $|D''| < \kappa_h$ and all $d \in  D_h \setminus (D'\cup D'')$,  $(D' \cup \{d\}) P_h (D'' \cup \{d\})$ if and only if $D' P_h D''$.
		\end{itemize}

	\end{definition}

	Having define $P_h$ over all feasible subsets of acceptable doctors, we extend this preference over the set of all feasible subsets of doctors $\{D' \subseteq D: |D'| \leq \kappa_h \}$.

	\begin{definition}
	For all $D' \subseteq D$ such that $|D'| \leq \kappa_h$ and $D' \not\subset D_h$, we have $\emptyset P_h D'$.
	\end{definition}

		For notational convenience, for any hospital $h \in H$, any couple $c=\{f,m\} \in C$ and any doctor $d \in D \setminus \{f,m\}$, $d P_h c$ means $d P_h f$ and $d P_h m$.


	\subsubsection{Preferences of doctors and couples}
	A preference of a doctor $d \in D$, denoted by $P_d$, is an element of $\mathbb{L}(H \cup \{\lambda\})$.	A preference of a couple $c=\{f,m\} \in C$, denoted by $P_c$, is an element of $\mathbb{L}((H \cup \{\lambda\})^2)$.  We call a preference of a couple responsive if a unilateral improvement in the position of one member of the couple is beneficial for the couple.

	\begin{definition}\label{def1} Let $c=\{f,m\} \in C$ be a couple. Let $P_{f}$ be a preference of $f$ and $P_m$ be a preference of $m$. A preference $P_c \in \mathbb{L}({(H \cup \{\lambda\})}^2)$ of the couple $c$ is called responsive (with respect to $P_f$ and $P_m$) if for all $h,h_1,h_2 \in H \cup \{\lambda\}$, we have
		\begin{enumerate}
			\item[(i)] $(h_1,h)P_c(h_2,h)$ if and only if $h_1 P_f h_2$, and 
			\item[(ii)] $(h,h_1)P_c(h,h_2)$ if and only if $h_1 P_m h_2$.			 
		\end{enumerate}
	\end{definition}

For any $c=\{f,m\} \in C$, a responsive preference $P_c$ induces unique marginal preferences $P_f$ and $P_m$ for $f$ and $m$ respectively. 

	\subsubsection{Preference profiles and matching problems}
	 A preference profile is a collection of responsive preferences for all hospitals in $H$, all doctors in $D$ and all couples in $C$. Thus, a preference profile $P$ is a tuple of preferences $(\{P_d\}_{d\in D},\{P_c\}_{c \in C},\{P_h\}_{h \in H})$, where for all $d \in D$, $c \in C$ and  $h \in H$, $P_d$ is a preference of doctor $d$, $P_c$ is a responsive preference of couple $c$, and $P_h$ is a responsive preference of hospital $h$ over acceptable and feasible sets of doctors, respectively. Note that, for any hospital $h \in H$, $D_h$ is an inherent part of $P_h$. This means that a preference $P_h$ automatically specifies the acceptable set $D_h$ of the hospital.

	A matching problem is a tuple consisting of a set of hospitals with corresponding capacities, a set of doctors with its partition into $F$, $M$, $S$, and a corresponding preference profile.


	\subsection{Stability}
There are different notions of stability based on different types of permissible blocking coalitions.

	Let $\mu$ be a matching and $P$ be a preference profile. We say a hospital $h$ \emph{prefers} to have a set of doctors $D'$ (possibly empty) to a subset of doctors in $\mu(h)$  if there is $D'' \subseteq \mu(h)$ with $D' \cap D'' = \emptyset$ such that $\{(\mu(h) \setminus D'' )\cup D'\}P_{h}\mu(h)$. Similarly, we say a doctor $d$ (or a couple $c$) \emph{prefers} a hospital $h$ to $\mu(d)$ (or a pair of hospitals $(h,h')$ to $\mu(c)$)  if $h P_d \mu(h)$ (or $(h,h')P_c\mu(c)$). Note that if a hospital prefers a set of doctors to its assignment at $\mu$, then by definition, that hospital is not matched with any of those doctors  at $\mu$. Moreover, it could also be that $h$ has some unacceptable doctors $D''$ in $\mu(h)$, thus $h$ prefers $D'=\emptyset$ to $\mu(h)$. 

	Similarly, if a doctor (or a couple) prefers a hospital (or a pair of hospitals) to its assignment at $\mu$, then that doctor (or at least one member of that couple) is not matched with the hospital (or the corresponding hospital) at $\mu$. 

    Now, we define the notion of blocking. Note that, since $\lambda$ is indifferent between all sets of doctors, and $D_{\lambda}=D$, thus $\lambda$ always prefers to have any doctor than not having that doctor. First, we introduce the notion of blocking between a hospital and a doctor in $S$. 

	\begin{definition}
		Let $s \in S$, $h \in H \cup \{\lambda\}$ and let $\mu$ be a matching. Then $(h,s)$ \emph{blocks} $\mu$ if $h$ prefers $s$ to $\mu(h)$ and $s$ prefers $h$ to $\mu(s)$.
	\end{definition}


	Next, we define the notion of blocking between a pair of hospitals and a couple.

	\begin{definition}\label{def5}
		Let $\mu$ be a matching and let $c=\{f,m\} \in C$ and $(h_f,h_m) \in {(H \cup \{\lambda\})^2}$. Then, $((h_f,h_m),c)$ blocks $\mu$ if $c$ prefers $(h_f,h_m)$ to $\mu(c)$ and 
		\begin{enumerate}
			\item[(i)] if $h_f \neq h_m$ and $\mu(f) \neq h_f$, then $h_f$ prefers $f$ to $\mu(h_f)$, 
			\item[(ii)] if $h_f \neq h_m$ and $\mu(m) \neq h_m$, then $h_m$ prefers $m$ to $\mu(h_m)$, and
			\item[(iii)] if $h_f = h_m$, then $h_f$ prefers $\{f,m\}$ to $\mu(h_f)$.
		\end{enumerate}	

	\end{definition}


   It is worth mentioning that the blocking notion takes complementarity of a couple being accepted into account (by allowing the notion of a hospital
being interested in a couple) but it does not take the couple into account when accepting single doctors and possibly removing members of a couple. In other words, there is an asymmetry here.

We consider this asymmetry in our model since it is not practical for big institutions like hospitals to consider the possibility of losing a member of a couple while removing the other member. This is because this possibility depends on factors like which hospital the removed member will join, whether the couple prefers to be together in that hospital, etc. Clearly, such situations can only be modeled by using a farsighted notion of blocking, which would complicate the model considerably. 

     Thus, by allowing the notion of a hospital being interested in a couple, the blocking definition takes complementarity of a couple being accepted into account. However, the hospital does not take this into account while accepting single doctors at the cost of removing a member of the couple from the hospital. The asymmetry arising here is the main reason, why the results obtained in this chapter are different to the results obtained by choice function approach in many-to-many matchings. \footnote{See Konishi and \"{U}nver\cite{konishi2006groups}, Echenique and Oviedo\cite{echenique2006stability}, Hatfield and Kojima\cite{hatfield2010substitutes}, for notions of stability in many-to-many matchings.} 


	Whenever a matching $\mu$ is blocked by  $((h_f,\mu(m)),c)$  for some $c =\{f,m\} \in C$ and some $h_f \in H \cup \{\lambda\}$, for ease of presentation we say that $\mu$ is blocked  by $(h_f,f)$. Similarly we say that $\mu$ is blocked  by $(h_m,m)$ if $\mu$ is blocked by  $((\mu(f),h_m),c)$.


Our next remark follows from the responsiveness of couples' preferences and Definition \ref{def5}.

	\begin{remark}
		Let $\mu$ be a matching and $c=\{f,m\}$ be a couple. Suppose for some $x \in \{f,m\}$ and some hospital $h_x \in H$, we have $h_x P_x \mu(x)$ and $((\mu(h_x) \setminus d) \cup \{x\}) P_{h_x} \mu(h_x)$ for some $d \in \mu(h_x) \setminus \{f,m\}$, then $(h_x,x)$ blocks $\mu$. 
	\end{remark}	

	A matching is stable if it cannot be blocked by any blocking pair. More formally, we get the following definition.

	\begin{definition}
		A matching $\mu$ is stable, if 
		\begin{itemize}
			\item[(i)] for all $h \in H \cup {\lambda}$ and $s \in S$, $(h,s)$ does not block $\mu$,
			\item[(ii)] for all $(h_f,h_m) \in (H \cup {\lambda})^2$ and $c \in C$, $((h_f,h_m),c)$ does not block $\mu$, and
			\item[(iii)] for all $h \in H$, $(h,\emptyset)$ does not block $\mu(h)$, i.e., $h$ does not prefer $\emptyset$ to $\mu(h)$.
		\end{itemize} 
	\end{definition}

	Now, we define the concept of individual rationality. 
	\begin{definition}
		A matching $\mu$ is individually rational if 
		\begin{enumerate} 
			\item[(i)] for all $s \in S$, $\mu(s) R_s \lambda$,
			\item[(ii)] for all $c \in C$, $\mu(c) R_c (\lambda,\lambda)$, and 
			\item[(iii)] for all $h \in H$ and all $d \in \mu(h)$, $d \in D_h$. 
		\end{enumerate}
	\end{definition}	
	The next remark follows from the definition of stability. 
\begin{remark}
		Every stable matching is individually rational.
\end{remark}




	\subsection{Algorithm} 
	In this section we present a well-known algorithm called doctor proposing deferred acceptance algorithm (DPDA). This algorithm was introduced by Gale and Shapley\cite{gale1962college}. \footnote{See Knuth\cite{knuth1976stables}, Gusfield and Irving\cite{gusfield1989marriage}, Roth and Sotomayer\cite{roth1992two}, Aldershof and Carducci\cite{aldershof1996couple} for additional results on stable matching problem in two sided matching.} Our proofs for the  existence of stable matchings use a modification of DPDA. In what follows, we give a very short description of this algorithm. Take a profile $P$. Then, the DPDA algorithm at $P$ goes as follows. 

	\medskip
	\noindent \emph{DPDA}:  In step 1 of the algorithm, all doctors simultaneously propose to their most
	preferred hospitals. Each hospital $h \in H$  provisionally accepts the most preferred doctors according to $P_h$. If a hospital receives more than $\kappa_{h}$ proposals, then it rejects all the doctors which do not belong to its $\kappa_h$ most preferred doctors. In any
	step $k$, the unmatched doctors propose to their most preferred hospital
	from the remaining set of hospitals who have not rejected them in any of the earlier steps. In any step of DPDA, since any hospital $h \in H$ accepts the most preferred collection of doctors according to $P_h$, it may reject some doctors that it had provisionally accepted earlier.  Hospitals whose provisional list of accepted doctors is less than their maximum capacity can still add to their accepted
	list if they receive fresh proposals. Thus the algorithm terminates when each doctor is
	matched with some hospital or has been rejected by all acceptable hospitals.

	\begin{remark}
		Note that in DPDA, each individual doctor proposes according to his/her individual preference. Thus, couples' preferences do not play any role in this algorithm.
	\end{remark}

	It is well-known that the outcome of DPDA is optimal for doctors. That is, some doctor is worse off at every other stable matching. Moreover, by responsiveness and the structure of DPDA, it follows that the outcome of DPDA is individually rational. 


	The following remark follows directly from the definition of DPDA.

	\begin{remark}\label{ton}
		Let $\mu$ be the outcome of DPDA. Let $d \notin \mu(h)$ for some $d \in D$ and $h \in H$. Then, $h P_d \mu(d)$ implies $d' P_h d$ for all $d' \in \mu(h)$.
	\end{remark}

In the following lemmas, we show that the outcome of DPDA cannot be blocked by a hospital and a single doctor or by a pair of different hospitals and a couple. Some of these results are well known outcomes of DPDA, but we prove them nevertheless for the sake of completeness.

	\begin{lemma}\label{HS}
		The outcome of DPDA cannot be blocked by a pair $(h,s)$ for any $h \in H$ and any $s \in S$.
	\end{lemma}
	\begin{proofs}
		 Let $\mu$ be the outcome of DPDA. Assume for contradiction that $(h,s)$ blocks $\mu$ for some $h \in H$ and some $s \in S$. Since the outcome of DPDA is individually rational, $ s R_h \lambda$. Since $hP_s \mu(s)$, by the definition of DPDA and Remark \ref{ton}, either $s$ has not proposed to $h$ during the DPDA or  all the doctors in $\mu(h)$ are preferred to $s$ according to $P_h$. If $s$ has not proposed to $h$ during DPDA, then we have $\mu(s) P_s h$, a contradiction to the fact that $(h,s)$ blocks $\mu$. So, suppose $d P_h s$ for all $d \in \mu(h)$. Then, by responsiveness of hospitals' preferences, we have $\mu(h) P_h((\mu(h)\setminus \{d\})\cup s)$ for all $d \in \mu(h)$, and consequently, hospital $h$ will not block with $s$. This completes the proof of the lemma. 
	\end{proofs}


	\begin{lemma}\label{HC}
		The outcome of DPDA cannot be blocked by $((h_1,h_2),c)$ for any $h_1, h_2 \in H$ such that $h_1 \neq h_2$ and for any $c \in C$.
	\end{lemma}
	\begin{proofs}
		Let $\mu$ be the outcome of DPDA. Assume for contradiction that $\mu$ is blocked by $((h_1,h_2),c)$. Let $\mu(f)=h_f$ and $\mu(m)=h_m$. By the definition of a block,  $(h_1,h_2) P_c (h_f,h_m)$. 

		Suppose $h_f R_f h_1$ and $h_m R_m h_2$. Since  $(h_1,h_2) \neq (h_f,h_m)$, this means  $(h_f,h_m) P_c (h_1,h_2)$, a contradiction. 		
		Now, suppose $h_1 P_f h_f$ or $h_2 P_m h_m$. Without loss of generality, assume $h_2 P_m h_m$. Since the outcome of DPDA is individually rational, $h_2 \neq \lambda$. Because $h_2 P_m h_m$, by  Remark \ref{ton}, $m$ proposed to $h_2$ at some step of DPDA and got rejected. Since $h_1 \neq h_2$, by Lemma \ref{HS}, we have $\mu(h_2) P_{h_2}  ((\mu(h_2) \setminus \{d\}) \cup m)$ for all $d \in \mu(h_2)$. However, this contradicts the definition of a block.
	\end{proofs}

In what follows, we give a lemma which shows that the outcome of DPDA cannot be blocked by a pair of dummy hospitals and a couple.

\begin{lemma}\label{UC}
	The outcome of DPDA cannot be blocked by $((\lambda,\lambda),c)$ for any $c \in C$.
\end{lemma}
\begin{proofs}
	Let $\mu$ be the outcome of DPDA. Assume for contradiction that $\mu$ is blocked by $((\lambda,\lambda),c)$. Let$\mu(f)=h_f$ and $\mu(m)=h_m$. By the definition of block,  $(\lambda,\lambda)P_c(h_f,h_m)$. By responsiveness, this means  $\lambda P_x h_x $ for some $x \in \{f,m\}$. However, by the definition of DPDA, $\lambda P_x h_x$ means $x$ proposed to $\lambda$ before proposing to $h_x$ and got rejected. This is contradiction as, by our assumption, $\lambda$  cannot reject a doctor.
\end{proofs}

In the following lemmas, we give conditions when an outcome of DPDA cannot be blocked by a pair of same hospitals and a couple. 

\begin{lemma}\label{No1}
	Suppose $\mu$ is an outcome of DPDA. Then for any $h \in H$ and any $c=\{f,m\} \in C$,
	\begin{itemize}
		\item[(i)] $f P_h m$ and $h P_f \mu(f)$ implies $((h,h),c)$ cannot block $\mu$, and
		\item[(ii)] $m P_h f$ and $h P_m \mu(m)$ implies $((h,h),c)$ cannot block $\mu$.
	\end{itemize}
\end{lemma}
\begin{proofs}
	Assume without loss of generality that $f P_h m$ and $h P_f \mu(f)$. By the definition of DPDA, $f$ proposed to $h$ and got rejected. By Remark \ref{ton}, $d P_h f$ for all $d \in \mu(h)$. Because $f P_h m$,  $\{d,d'\} P_h \{f,m\}$ for all $d,d' \in \mu(h)$. This means $h$ cannot block $\mu$ with $c$. This completes the proof.
\end{proofs}

\begin{lemma}\label{No2}
		Suppose $\mu$ is an outcome of DPDA. Then for any $h \in H$ and any $c=\{f,m\} \in C$, $((h,h),c)$ cannot block $\mu$ if $h=\mu(x)$ for some $x \in \{f,m\}$
\end{lemma}
\begin{proofs}
	Without loss of generality, let $h=\mu(f)$. Let $((h,h),c)$ block $\mu$. 

	By the definition of a block, $(h,h)P_c(\mu(f),\mu(m))$. Thus, by responsiveness of couples' preferences, $h P^0_m h_m$. By the definition of DPDA, this means $m$ proposed to $h$ and got rejected. Since $f \in \mu(h)$, by Lemma \ref{HS} and the definition of block, we have $\mu(h) P_{h}  ((\mu(h) \setminus \{d\}) \cup m)$ for all $d \in \mu(h)$. This means $h$ will not block $\mu$ with $c$, which is a contradiction.
\end{proofs}

\begin{remark}\label{new1}
	If a doctor $d \in D$ and hospital $h \in H$ are each other's top ranked alternative, then trivially for a stable match, they must be matched to each other.
\end{remark}

