      \draw[fill] (.5,0) circle[radius=.05];


      \draw (-2,-.4) node {$g(b)$};
      \draw (-.5,-.4) node {$g(x)$};
                  \draw (.5,-.4) node {$g(y)$};

      \draw (2,-.4) node {$g(a)$};
      \draw[dashed,thick] (-2,0)--(-2,1)--(.5,1)--(.5,0);
