\section{Minimal Excludant of the Overlined Parts of an Overpartition}
\subsection{Generating Function of $\smexoverover{n}$}

\begin{proof}[Proof of Theorem \ref{gen2}]
Let $p^{\widehat{\mex}}(m,n)$ be the number of overpartitions $\pi$ of $n$ with $\mexoverover{\pi}=m.$  
Then we have the following double series $M(z,q)$ in which the coefficient of $z^mq^n$ is $p^{\widehat{\mex}}(m,n)$:

\begin{align*}
M(z,q)&:=\displaystyle\sum_{n=0}^\infty \displaystyle\sum_{m=1}^\infty p^{\widehat{\mex}}(m,n)z^mq^n\\
&=\displaystyle \sum_{m=1}^{\infty} z^{m}\cdot q^1\cdot q^2 \cdots \cdot q^{m} \cdot \frac{\displaystyle\prod_{n=m+1}^\infty (1+q^n)}  {\displaystyle\prod_{n=1}^\infty (1-q^n)}\\
&=\dfrac{(-q;q)_\infty}{(q;q)_\infty} \displaystyle \sum_{m=1}^{\infty}\dfrac{z^{m} \cdot q^{m \choose 2}}{{(-q;q)_m}}.
\end{align*}

%The product $q^1\cdot q^2 \cdots q^{m-1}$ represents the overlined parts $1,2,...,m-1$ while \[\frac{\displaystyle\prod_{n=m+1}^\infty (1+q^n)}  {\displaystyle\prod_{n=1}^\infty (1-q^n)}\]  is the generating function for the number of overpartitions of $n$ with overlined parts greater than $m$. Hence, the product 
%\[
%q^1\cdot q^2 \cdots \cdot q^{m-1} \cdot \frac{\displaystyle\prod_{n=m+1}^\infty (1+q^n)}  {\displaystyle\prod_{n=1}^\infty (1-q^n)}
%\]
%is the generating function for the number of overpartitions of $n$ with overlined parts $1,2,...,m-1$, but not $m$. Simplifying,
%\[M(z,q)= \dfrac{(-q;q)_\infty}{(q;q)_\infty} \displaystyle \sum_{m=1}^{\infty}\dfrac{z^{m} \cdot q^{m \choose 2}}{{(-q;q)_m}}.\]

\noindent Thus,
\begingroup
\allowdisplaybreaks
\begin{align*}
    \displaystyle \sum_{n \geq 0} \smexoverover{n} q^n &= \dfrac{\partial}{\partial z}\Big|_{z=1} M(z,q)\\
    &=\dfrac{(-q;q)_\infty}{(q;q)_\infty} \displaystyle\sum_{m=1}^{\infty} \dfrac{m \cdot q^{m \choose 2}}{{(-q;q)_m}}\\
     &=\overline{P}(q)\displaystyle\sum_{m=1}^{\infty} \dfrac{m \cdot q^{m \choose 2}}{{(-q;q)_m}}\\
      &=\overline{P}(q)\displaystyle\sum_{m=1}^{\infty} \dfrac{m \cdot q^{m \choose 2}}{{(-q;q)_{m-1}}}\cdot\dfrac{1}{1+q^m}\\
       &=\overline{P}(q)\displaystyle\sum_{m=1}^{\infty} \dfrac{m \cdot q^{m \choose 2}}{{(-q;q)_{m-1}}} \left(1-\dfrac{q^m}{1+q^m} \right)\\
        &=\overline{P}(q) \left[\displaystyle\sum_{m=1}^{\infty} \ \dfrac{m \cdot q^{m \choose 2}}{{(-q;q)_{m-1}}} - \dfrac{m \cdot q^{{m+1} \choose 2}}{{(-q;q)_m}}\right]\\
         &=\overline{P}(q)\left[\displaystyle\sum_{m=0}^{\infty} \ \dfrac{(m+1) \cdot q^{{m+1} \choose 2}}{{(-q;q)_{m}}} - \displaystyle\sum_{m=0}^{\infty}\dfrac{m \cdot q^{{m+1} \choose 2}}{{(-q;q)_m}}\right]\\
         &=\overline{P}(q)\displaystyle\sum_{m=0}^{\infty}\dfrac{ q^{{m+1} \choose 2}}{{(-q;q)_m}}\\
    &=\overline{P}(q)\sigma(q).
 \end{align*}
\endgroup
\end{proof}

