\subsection{Parity of $\smexoverover{n}$}
\begin{lemma}\label{overeven}
    The overpartition number $\overline{p}(n)$ is even for any positive integer n.
\end{lemma}
\begin{proof}
    Note that 
\[\overline{P}(q)=\displaystyle \sum_{n=1}^\infty \overline{p}(n)q^n =\dfrac{(-q;q)_\infty}{(q;q)_\infty} = \dfrac{(q^2;q^2)_\infty}{(q;q)^2_\infty} .\]
By the binomial theorem, $(q^2;q^2)_\infty \equiv (q;q)^2_\infty \Mod 2.$ This implies that $\overline{p}(n)$ is always even for all positive integers $n$.
\end{proof}



\begin{proof}[Proof of Theorem \ref{parity2}]
It was shown by Andrews et al. in \cite{Andrews2} that if $\sigma(q)=\sum_{n=0}^\infty S(n)q^n,$ then $S(n)$ is almost always zero. Hence, combining this with Lemma \ref{overeven} implies that $\smexoverover{n}$ is almost always even.
\end{proof}

