\subsection{Asymptotic Formula for $\smexoverover{n}$}

To derive an asymptotic formula for $\smexoverover{n}$, we use the following asymptotic result by Ingham \cite{ingham} about the coefficients of a power series.

\begin{proposition} \label{asymingham}
  Let $A(q)= \sum_{n=0}^{\infty} a(n)q^n$ be a power series with radius of convergence equal to 1. Assume that $\{a(n)\}$ is a weakly increasing sequence of nonnegative real numbers. If there are constants $\alpha, \beta \in \mathbb{R}$, and $C>0$ such that
\[A(e^{-t})\sim \alpha t^{\beta}e^{\frac{C}{t}}, \text{ as } t \rightarrow 0^{+} \] Then 

\[a(n) \sim \dfrac{\alpha}{2\sqrt{\pi}}\dfrac{C^{\frac{2\beta+1}{4}}}{n^{\frac{2\beta+3}{4}}}e^{2\sqrt{Cn}}, \text{ as } n \rightarrow \infty.\]
\end{proposition}

\begin{proof}[Proof of Theorem \ref{asym2}]
Note that $\{\smexoverover{n}\}$ is an increasing sequence of nonnegative real numbers, since $\{\overline{p}(n)\}$ is also an increasing sequence of nonnegative real numbers.\\

\noindent Let $A(q)=\dfrac{(-q;q)_\infty}{(q;q)_\infty}\sigma(q)$, where $a(n)=\smexoverover{n}$ as in Proposition \ref{asymingham}. From \cite{bhoria},
\begin{align}\dfrac{1}{(e^{-t}; e^{-t})_\infty} \sim \sqrt{\dfrac{t}{2\pi}} e^{\frac{\pi^2}{6t}} \text{ as } t \rightarrow 0^+. \label{1}
\end{align}
Moreover, we use the following identity of Euler
\begin{align}
(-q;q)_{\infty}=\dfrac{1}{(q;q^2)_\infty}=\dfrac{(q^2;q^2)_\infty}{(q;q)_\infty}.\label{2}
\end{align}


\noindent By (\ref{1}) and (\ref{2}), as $t \rightarrow 0^{+}$,
\[\dfrac{(-e^{-t};e^{-t})_\infty}{(e^{-t};e^{-t})_\infty} = \dfrac{(e^{-2t};e^{-2t})_\infty}{(e^{-t};e^{-t})^2_\infty}\sim \frac{\frac{t}{2\pi}  e^{\frac{2\pi^2}{6t}}}{\sqrt{\frac{2t}{2\pi}} e^{\frac{\pi^2}{12t}}}=\dfrac{\sqrt{t}}{2\sqrt{\pi}}e^{\frac{\pi^2}{4t}}.\] 
Moreover, from \cite{Zagier} (p.6), 
\[\sigma(e^{-t})=2-2t+5t^2-\dfrac{55}{3}t^3+\dfrac{1073}{12}t^4-\dfrac{32671}{60}t^5+\dfrac{286333}{72}t^6-\cdots.\]
Hence, as $t \rightarrow 0^{+}$,
\begin{align}
A(e^{-t}) \sim \dfrac{1}{\sqrt{\pi}}t^{1/2}e^{\frac{\pi^2}{4t}}. \label{3}
\end{align}

\noindent Take $\alpha=\frac{1}{\sqrt{\pi}}, \beta=\frac{1}{2}$ and $C=\frac{\pi^2}{4}$, by Proposition \ref{asymingham},
\[\smexoverover{n} \sim \dfrac{\frac{1}{\sqrt{\pi}}}{2\sqrt{\pi}} \dfrac{\left(\frac{\pi^2}{4}\right)^{1/2}}{n}e^{2\sqrt{\frac{\pi^2}{4}n}} = \dfrac{e^{\pi{\sqrt{n}}}}{4n}\]
as $n \rightarrow \infty$.
\end{proof}



