\noindent Hence, from (\ref{orig}), we have
\[
\displaystyle \sum_{n \geq 0} \smexover{n} q^n = \dfrac{1}{2} \displaystyle \sum_{n \geq 0} \smexover{n} q^n + \dfrac{(-q;q)_\infty}{(q;q)_\infty} \displaystyle\sum_{m=1}^{\infty} \dfrac{ 2^{m-2} \cdot q^{m \choose 2}}{(-q;q)_{m-1}}.\]

\noindent Thus,
\begin{align*}
\displaystyle \sum_{n \geq 0} \smexover{n} q^n &=\dfrac{(-q;q)_\infty}{(q;q)_\infty} \displaystyle\sum_{m=1}^{\infty} \dfrac{2\cdot 2^{m-2} \cdot q^{m \choose 2}}{(-q;q)_{m-1}}\\
&= \dfrac{(-q;q)_\infty}{(q;q)_\infty} \displaystyle\sum_{m=1}^{\infty} \dfrac{2^{m-1} \cdot q^{m \choose 2}}{(-q;q)_{m-1}}\\
&= \dfrac{(-q;q)_\infty}{(q;q)_\infty} \displaystyle\sum_{m=0}^{\infty} \dfrac{2^{m} \cdot q^{m+1 \choose 2}}{(-q;q)_{m}}.
\end{align*}
Now,
\begin{align*}
{}_1\phi_1(q;-q;q,-2q)&= \displaystyle \sum_{n=0}^\infty \dfrac{(q;q)_n}{(-q,q;q)_n} \left((-1)^nq^{n \choose 2}\right)(-2q)^n\\
&= \displaystyle \sum_{n=0}^\infty \dfrac{(q;q)_n}{(-q;q)_n(q;q)_n} \left((-1)^nq^{n \choose 2}\right)(-2q)^n\\
&= \displaystyle \sum_{n=0}^\infty \dfrac{1}{(-q;q)_n} \cdot2^nq^{n \choose 2}\cdot q^n\\
&= \displaystyle \sum_{n=0}^\infty \dfrac{2^n\cdot q^{{n+1} \choose 2}}{(-q;q)_n}.
\end{align*}

\noindent Therefore,
\[\displaystyle \sum_{n \geq 0} \smexover{n} q^n=\dfrac{(-q;q)_\infty}{(q;q)_\infty} \displaystyle\sum_{m=0}^{\infty} \dfrac{2^{m} \cdot q^{m+1 \choose 2}}{(-q;q)_{m}}=\overline{P}(q){}_1\phi_1(q;-q;q,-2q).\]
\end{proof}



