	\begin{figure*}[t!]\includegraphics[width=\textwidth]{figure-19.pdf}
	\caption{\label{fig:VcmDynamics} Temporal evolution of the dynamical variables: (a) the centre of mass velocity $V_{\mathrm{cm}}(t)$; (b) the order parameter $\Xi(t)$ which is given by the  product $V_{\mathrm{cm}}\,\mathbb{M}^{(\mathtt{1})}_{\ell=1}$; (c) the mass flux $\mathbb{M}^{(\mathtt{1})}_{\ell=1}(t)$, associated with the first spherical harmonic  mode; and (d)  the mass flux $\mathbb{M}^{(\mathtt{1})}_{\ell=2}(t)$ corresponding to the second spherical harmonic mode. The fluxes $\mathbb{M}^{(\mathtt{1})}_{\ell=1,2}\!$ are rescaled by $R^2/\gamma$, whilst the  velocity $V_{\mathrm{cm}}$ is measured in units of $\gamma/R$. Here, $\zeta=2$, $A=250$, $Q=-8000$, $\mathcal{K}=10$, and $\bar{\Phi}_0=3/5$.
