	%\renewcommand{\theequation}{B.\arabic{equation}}


	%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
	\subsection{Calculus of Moving Surfaces}
	%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

	The formulation of kinetic and kinematic relationships on a deformable membrane is much easier achieved by parameterizing the surface through a convected coordinate system $\varrho^\alpha$ with respect to a fixed reference system~$\xi^\alpha$, where the latter is depicted in Fig.~\ref{fig:A1}. Specifically, we identify by $\hspace{1pt}\hat{\!\itbf{R}}(\varrho^\alpha\hspace{-1pt},t)$ the current position at time $t$ of a material point that was located at
	\begin{equation}
		\hspace{1pt}\hat{\!\itbf{R}}(\varrho^\alpha\hspace{-1pt},\hspace{1pt}t_0)\hspace{-1pt} = \itbf{R}(\xi^\alpha),
	\end{equation} with the initial (reference) time $t_0\hspace{-1pt}\leq t$. In other words, we specify the fixed coordinates $\xi^\alpha$ as functions which depend on both the time and the convected coordinates $\varrho^\alpha$, subject to the condition that
	\begin{equation}
		\varrho^\alpha = \xi^\alpha(\varrho^\beta\hspace{-1pt},\hspace{1pt}t_0).
	\end{equation} In addition, we assume that these mappings between~$\varrho^\alpha$ and $\xi^\alpha$ are invertible, reflecting the notion that, at any fixed time $t$, a material point that is identified by constant $\varrho^\alpha$ can be uniquely associated with the local surface coordinates $\xi^\alpha$ (at time $t_0$). Thus, we write
	\begin{equation}
		\label{eqn:convected-fixed}
		\hat{\!\itbf{R}}(\varrho^\alpha\hspace{-1pt},\hspace{1pt}t)\hspace{-1pt} = \itbf{R}\!\left(\hspace{1pt}\xi^\beta\hspace{-1pt}(\varrho^\alpha\hspace{-1pt},t),\hspace{1pt}t\hspace{1pt}\right)\!.
	\end{equation}

	The velocity $\itbf{v}$ of a material point that lives solely on the surface is defined by the rate of change of the position vector $\hat{\!\itbf{R}}(\varrho^\alpha\hspace{-1pt},\hspace{1pt}t)\hspace{-1pt}$ at fixed $\varrho^\alpha$, namely
	\begin{equation}
		\itbf{v}=\left.\frac{\partial\hat{\!\hspace{1pt}\itbf{R}}}{\partial t}\right|_{\{\varrho^\beta\}} \!\!= \,\left.\frac{\partial\!\hspace{1pt}\itbf{R}}{\partial t}\right|_{\{\xi^\beta\}} \!+ \,\ed{\alpha}\!\left.\frac{\partial\xi^\alpha}{\partial t}\right|_{\{\varrho^\beta\}}.
	\end{equation} where the latter equality follows via the chain rule. Hereinafter, we define the tangential velocity components $v^\alpha$ as the rate of change of the fixed coordinates $\xi^\alpha$ for a given material point of constant  $\varrho^\alpha$, that is,
	\begin{equation}
		v^\alpha =\,\left.\frac{\partial\xi^\alpha}{\partial t}\right|_{\{\varrho^\beta\}}.
	\end{equation} On the other hand, the normal velocity is given by 
	\begin{equation}
		v = \nv\cdot\hspace{-1pt}\left.\frac{\partial\!\hspace{1pt}\itbf{R}}{\partial t}\right|_{\{\xi^\alpha\}}
	\end{equation} so that the surface points of constant $\xi^\alpha$ change only along the normal direction to the surface, without any loss of generality. Thus, the velocity $\itbf{v}$ can be written as
	\begin{equation}
		\label{eqn:velocity-decomposition}
		\itbf{v} = v \nv +v^\alpha\hspace{-1pt}\ed{\alpha}.
	\end{equation}

	Any scalar function $\phi(\xi^\alpha\hspace{-1pt},\hspace{1pt}t)$ that lives on the surface can also be written as a function in terms of the convected coordinates, say $\hat{\phi}(\varrho^\alpha\hspace{-1pt},\hspace{1pt}t)$, where we have that
	\begin{equation}
		\hat{\phi}(\varrho^\alpha\hspace{-1pt},\hspace{1pt}t) = \phi\!\left(\xi^\beta\hspace{-1pt}(\varrho^\alpha\hspace{-1pt},t),\hspace{1pt}t\right)\!.
	\end{equation} The material derivative of $\phi$ is simply the rate of change of $\hat{\phi}$ for a given material point of constant $\varrho^\alpha$, that is, 
	\begin{equation}
		\dot{\phi}=\frac{\mathrm{d}\phi}{\mathrm{d}t}=\left.\frac{\partial\hat{\phi}}{\partial t}\right|_{\{\varrho^\alpha\}}
	\end{equation} where the {\sl overdot} symbol denotes the material derivative of a function. By utilizing the chain rule, this leads to\vspace{3pt}
	\begin{equation}
		\dot{\phi} = \,\left.\frac{\partial\phi}{\partial t}\right|_{\{\xi^\beta\}} \!+ \,\phi_{,\alpha}\!\left.\frac{\partial\xi^\alpha}{\partial t}\right|_{\{\varrho^\beta\}} =\; \frac{\partial\phi}{\partial t} +v^\alpha\hspace{1pt}\phi_{,\alpha}.\vspace{3pt}
	\end{equation}

	Similarly, the material derivative of the in-plane basis vectors $\ed{\alpha}$ that are defined in Eq.~(\ref{eqn:tangent-vector}) can be expressed in terms of the convected coordinates, as follows:\vspace{3pt}
	\begin{equation}
		\dot{\!\itbf{e}}_{\alpha} = \frac{\partial}{\partial t}\!\left[\frac{\partial\!\hspace{1pt}\itbf{R}}{\partial\xi^\alpha}\right]_{\hspace{-0.5pt}\{\varrho^\beta\}}.\vspace{6pt}
	\end{equation} This could be further expressed in terms of $\hspace{1pt}\hat{\!\itbf{R}}(\varrho^\alpha\hspace{-1pt},\hspace{1pt}t)\hspace{-1pt}$ by using Eq.~(\ref{eqn:convected-fixed}), and by chain rule we find
	\begin{align}
		\dot{\!\itbf{e}}_{\alpha} &= \frac{\partial}{\partial t}\!\left[\frac{\partial\varrho^\gamma}{\partial\xi^\alpha}\,\frac{\partial\!\hspace{2.5pt}\hat{\!\itbf{R}}}{\partial\varrho^\gamma}\right]_{\hspace{-0.5pt}\{\varrho^\beta\}}\!\! =\; \frac{\partial\varrho^\gamma}{\partial\xi^\alpha}\frac{\partial}{\partial\varrho^\gamma}\!\left[\hspace{-1pt}\frac{\partial\!\hspace{2.5pt}\hat{\!\itbf{R}}}{\partial t}\right]_{\{\varrho^\beta\}}\notag\\[5pt]
		& = \frac{\partial\itbf{v}}{\partial\varrho^\gamma}\,\frac{\partial\varrho^\gamma}{\partial\xi^\alpha}\, = \frac{\partial\itbf{v}}{\partial\xi^\alpha} = \,{\itbf{v}}_{,\alpha}.
	\end{align} Moreover, this can be  decomposed into the local surface basis, \ie $\hspace{-1.0pt}\{\hspace{-0.25pt}\nv,\ed{\alpha}\}$, which yields
	\begin{equation}
		\label{eqn:dot-basis}
		\dot{\!\itbf{e}}_{\alpha}= \itbf{v}_{,\alpha} = \left(v^\beta_{;\alpha}-v\hspace{1pt} b_\alpha^\beta\right)\!\ed{\beta} + \left(v^\beta b_{\alpha\beta} + v_{,\alpha}\right)\!\nv,
	\end{equation} by employing the form of the velocity field in Eq.~(\ref{eqn:velocity-decomposition}), and by also using the Gauss--Weingarten equations.

	By applying the material derivative onto the orthogonality condition $\nv\cdot\ed{\alpha}=0$, we have $\ed{\alpha}\cdot\dot{\nv} = -\nv\cdot\dot{\itbf{e}}_\alpha$. As $\nv\cdot\dot{\nv} = 0$, the material derivative of the normal unit vector acts only within the tangent plane of the surface, and thus from Eq.~(\ref{eqn:dot-basis}) we obtain that
	\begin{equation}
		\label{eqn:dot-normal}
		\dot{\nv} = -\left(v^\beta\hspace{0.25pt}b^{\alpha}_\beta + v^{\hspace{0.5pt},\alpha}\right)\!\ed{\alpha}.
	\end{equation}

	The material derivatives in Eqs.~(\ref{eqn:dot-basis}) and (\ref{eqn:dot-normal}) allows us to determine the expression of the acceleration,
	\begin{align}
		\dot{\itbf{v}}\; =\; &\left[\frac{\partial v^\alpha}{\partial t}-\left(v^\beta\hspace{0.25pt}b^{\alpha}_\beta + v^{\hspace{0.5pt},\alpha}\right)\hspace{-1pt}v + \left(v_{;\beta}^{\alpha}-v\hspace{1pt} b_{\beta}^{\alpha}\right)\hspace{-1pt}v^\beta\right]\!\ed{\alpha}\notag\\[3pt]
		&\;+\;\left[\frac{\partial v}{\partial t} + \left(v^\beta b_{\alpha\beta} + v_{,\alpha}\right)v^\alpha\right]\!\nv,
	\end{align} as well as the explicit forms of the material derivatives of the metric tensor $g_{\alpha\beta}$ and the curvature tensor $b_{\alpha\beta}$, \ie
	\begin{align}
		\label{eqn:g-dot}
		\dot{g}_{\alpha\beta} &= v_{\beta;\alpha}+v_{\alpha;\beta} - 2v\hspace{1pt}b_{\alpha\beta},\quad\mathrm{and}\\[5pt]
		\label{eqn:b-dot}
		\dot{b}_{\alpha\beta} &=b_{\gamma\beta}\left(v_{;\alpha}^{\gamma} - v\hspace{1pt}b^{\gamma}_\alpha\right)+\left(v^\gamma\hspace{0.5pt}b_{\gamma\alpha}+v_{,\alpha}\right)_{;\beta},
	\end{align} respectively. The above expressions have been derived by applying the product rule of the material derivative, and by expanding out the definitions of $g_{\alpha\beta}$ and $b_{\alpha\beta}$ in terms of the local tangent basis and/or the normal. For instance, we have that $\dot{g}_{\alpha\beta} = \ed{\alpha}\cdot\dot{\itbf{e}}_\beta + \dot{\itbf{e}}_\alpha\cdot\ed{\beta}$, and then by using Eq.~(\ref{eqn:dot-basis}), we obtain the expression in Eq.~(\ref{eqn:g-dot}). In an analogous way, from Eq.~(\ref{eqn:curvature-tensor}), we can write that $\dot{b}_{\alpha\beta} = \nv\cdot\dot{\itbf{e}}_{\alpha\hspace{0.35pt},\hspace{0.15pt}\beta} + \dot{\nv}\cdot\itbf{e}_{\alpha\hspace{0.35pt},\hspace{0.15pt}\beta} = -\nv_{\hspace{0.35pt},\hspace{0.15pt}\beta}\cdot\dot{\itbf{e}}_{\alpha} -\dot{\nv}_{\hspace{0.35pt},\hspace{0.15pt}\beta}\cdot\itbf{e}_{\alpha}$, which readily leads to Eq.~(\ref{eqn:b-dot}) after some tedious algebra, by substituting the results in Eq.~(\ref{eqn:dot-basis}) and (\ref{eqn:dot-normal}).

