	%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
	\subsection{Integral and Transport Theorems}
	%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

	The area element $\mathrm{d}S$ of a surface that is parameterized by the fixed curvilinear coordinates $(\xi^1,\xi^2)$ is given by
	\begin{equation}
		\mathrm{d}S = \mathrm{d}\xi^1\mathrm{d}\xi^2\sqrt{g},
	\end{equation} where $g=\det[g_{\alpha\beta}]$, as previously defined in Eq.~(\ref{eqn:g-def}). This allows us to compute the total area of a surface $\mathcal{M}$ by integrating over the fixed internal coordinates $\xi^\alpha$, \ie
	\begin{equation}
		A = \!\int\limits_{\mathcal{M}\;\;}\!\mathrm{d}S\, = \iint\!\mathrm{d}\xi^1\mathrm{d}\xi^2\sqrt{g}\,.
	\end{equation} To determine the rate of change of area, we thus need to compute $\frac{\mathrm{d}}{\mathrm{d}t}\sqrt{g}$. We make use of Jacobi's formula that allows us to express the derivative of the determinant of the matrix $\left[g_{\alpha\beta}\right]$ in terms of its inverse, $\left[g_{\alpha\beta}\right]^{-1}$, as well as its derivative; namely, this reads
	\begin{equation}
		\frac{\mathrm{d}}{\mathrm{d}t}\det[g_{\alpha\beta}] = \det[g_{\alpha\beta}]\;\Tr\!\left\{\hspace{-1pt}\left[g_{\alpha\gamma}\right]^{-1}\!\frac{\mathrm{d}}{\mathrm{d}t}\left[g_{\gamma\beta}\right]\hspace{-1pt}\right\}\!,
	\end{equation} with $\Tr\hspace{-1pt}[\boldsymbol{\cdot}]$ denoting the trace of a matrix. In terms of our previous notation, this formula can be rewritten~as\vspace{-5pt}
	\begin{equation}
		\frac{1}{\sqrt{g}}\frac{\mathrm{d}(\sqrt{g})}{\mathrm{d}t} = \frac{1}{2}\,g^{\alpha\beta}\dot{g}_{\alpha\beta} = v^\alpha_{\,;\alpha} - 2vH = \Div\hspace{-1pt}(\itbf{v}),
	\end{equation} where the third and the forth equality follows by means of Eq.~(\ref{eqn:g-dot}) and Eq.~(\ref{eqn:div-surface-3D}), respectively. Hence,
	\begin{equation}
		\label{eqn:derivative-sqrt-g}
		\frac{\mathrm{d}}{\mathrm{d}t}\sqrt{g} = \Div\hspace{-1pt}(\itbf{v})\hspace{1pt}\sqrt{g},
	\end{equation} which implies that the rate of change of area is given by
	\begin{equation}
		\label{eqn:rate-change-area}
		\frac{\mathrm{d}A}{\mathrm{d}t} = \iint\!\mathrm{d}\xi^1\mathrm{d}\xi^2\,\frac{\mathrm{d}}{\mathrm{d}t}\sqrt{g} =  \!\int\limits_{\mathcal{M}\;\;}\!\Div\hspace{-1pt}(\itbf{v})\;\mathrm{d}S.
	\end{equation}

	The identity in Eq.~(\ref{eqn:derivative-sqrt-g}) could also be used to derive the so-called {\it Reynolds transport theorem}, that is,
	\begin{equation}
		\frac{\mathrm{d}}{\mathrm{d}t}\hspace{1pt}\int\limits_{\mathcal{S}\;\;}\!\itbf{T}\,\mathrm{d}S =  \!\int\limits_{\mathcal{S}\;\;}\!\mathrm{d}S\left[\itbf{T}\,\Div\hspace{-1pt}(\itbf{v})+\frac{\mathrm{d}\hspace{-1.25pt}\itbf{T}}{\mathrm{d}t}\hspace{1pt}\right]\!, 
	\end{equation} where $\mathcal{S}$ is an arbitrary surface patch, and $\itbf{T}$ can be any tensor field that is defined on the domain $\mathcal{S}$, \eg surface densities, or velocity fields that live on a membrane.

	Furthermore, the volume $V$ enclosed by an arbitrary closed (orientable) surface, say $\mathcal{M}$, can be obtained from the position vector $\itbf{R}$ as follows:
	\begin{equation}
		V=\!\iiint\!\mathrm{d}V\! = \frac{1}{3}\int\limits_{\mathcal{M}\,\;}\!\left(\nv\cdot\itbf{R}\right)\mathrm{d}S,
	\end{equation} where the latter is found by employing the vector calculus identity, $\bnabla\cdot\itbf{r} = 3$, with $\itbf{r}$ being any position vector, and lastly making use of the divergence theorem (by also noting that boundary of the volume $\partial V$ is trivially the same as the closed surface of the membrane~$\mathcal{M}$). 

	To find the rate of change of volume, we can simply apply the Reynolds transport theorem, which yields
	\begin{equation}
		\frac{\mathrm{d}V}{\mathrm{d}t} = \frac{1}{3}\int\limits_{\mathcal{M}\,\;}\!\Big\{ v + \itbf{R}\cdot\left[\dot{\nv} + \nv\hspace{1pt}\Div\hspace{-1pt}(\itbf{v})\right]\!\Big\}\,\mathrm{d}S,
	\end{equation} where the term in the square brackets can be expressed as: $\dot{\nv} + \nv\hspace{1pt}\Div\hspace{-1pt}(\itbf{v}) = -\big(v^\beta\hspace{0.25pt}b^{\alpha}_\beta + v^{\hspace{0.5pt},\alpha}\big)\hspace{-0.5pt}\ed{\alpha} + \big(v^\alpha_{\,;\alpha} -2Hv\big)\nv$. Notice that the term $\itbf{R}\cdot({v}^{\hspace{1pt},\alpha}\ed{\alpha})$ can be written in terms of a total derivative, namely
	\begin{equation}
		\itbf{R}\cdot({v}^{\hspace{1pt},\alpha}\ed{\alpha}) = \left[\hspace{0.5pt}v\hspace{1pt}(\ed{\alpha}\cdot\itbf{R})\hspace{0.5pt}\right]^{,\alpha} - 2\hspace{0.5pt}v\hspace{1pt}(1+ H \nv\cdot\itbf{R}),
	\end{equation} where Eq.~(\ref{eqn:curvature-tensor}) is used to derive the latter. Since $\mathcal{M}$ is a closed surface, we obtain that
	\begin{equation}
		\label{eqn:volume-eq-appex}
		\frac{\mathrm{d}V}{\mathrm{d}t} = \frac{1}{3}\int\limits_{\mathcal{M}\,\;}\!\Big\{3v + \itbf{R}\cdot\left[\nv\hspace{1pt}v^{\alpha}_{\,;\alpha} -v^\beta b^{\alpha}_\beta\ed{\alpha}\right]\!\Big\}\,\mathrm{d}S.
	\end{equation} By using the Gauss--Weingarten equation, $\nv_{;\beta} = -b^{\alpha}_{\beta}\ed{\alpha}$, the second term in the integrand of Eq.~(\ref{eqn:volume-eq-appex}) becomes
	\begin{equation}
		\itbf{R}\cdot\big[\nv\hspace{1pt}v^{\alpha}_{\,;\alpha}\hspace{-0.5pt}+v^\alpha\nv_{;\alpha}\big]\! =\hspace{-1pt} [\nv\cdot\itbf{R}\,v^\alpha]_{\hspace{0.5pt};\alpha},
	\end{equation} which is a total derivative that vanishes identically by integrating over the closed surface. Therefore, this leads to the following simple (and geometrically intuitive) result:
	\begin{equation}
		\frac{\mathrm{d}V}{\mathrm{d}t} = \int\limits_{\mathcal{M}\,\;}\!v\;\mathrm{d}S,
	\end{equation} that is, the rate of change of the volume $V$ is identical to the integrated value of the normal velocity over the total area of the membrane surface.

