\title[Log-ozone groups and centers of polynomial Poisson algebras]
{Log-ozone groups and centers of polynomial Poisson algebras}

\author{Kenneth Chan, Jason Gaddis, Robert Won, James J. Zhang}

\address{(Chan) Department of Mathematics, 
University of Washington, Box 354350, Seattle, Washington 98195, USA}
\email{kenhchan@math.washington.edu, ken.h.chan@gmail.com}

