The left Jost solution $f(k,x)$ is the solution to \eqref{1.1} satisfying the asymptotics as $x\to +\infty$ given by
\begin{equation}\label{2.10}
\begin{cases}
f(k,x)=e^{kx}\left[1+o(1)\right],\\
\noalign{\medskip}
f'(k,x)=k\,e^{kx}\left[1+o(1)\right],\\
\noalign{\medskip}
f''(k,x)=k^2\,e^{kx}\left[1+o(1)\right],
\end{cases}
\end{equation}
and its $k$-domain is given by $\overline{\Omega_1}.$ The left scattering coefficients $T_{\text{\rm{l}}}(k),$ $L(k),$ $M(k)$ are defined via the spacial
asymptotics of $f(k,x)$ as $x\to -\infty$ given by
\begin{equation}\label{2.11}
f(k,x)=\begin{cases}
e^{kx}\,T_{\text{\rm{l}}}(k)^{-1}[1+o(1)]+e^{zkx}L(k)\,T_{\text{\rm{l}}}(k)^{-1}[1+o(1)],\qquad k\in \mathcal L_1,\\
\noalign{\medskip}
e^{kx}\,T_{\text{\rm{l}}}(k)^{-1}[1+o(1)], \qquad k\in \Omega_1,\\
\noalign{\medskip}
e^{kx}\,T_{\text{\rm{l}}}(k)^{-1}[1+o(1)]+e^{z^2 kx}M(k)\,T_{\text{\rm{l}}}(k)^{-1}[1+o(1)], \qquad k\in \mathcal L_2,
\end{cases}
\end{equation}
where $\mathcal L_1$ and $\mathcal L_2$ are the directed half lines shown in Figure~\ref{figure2.1} corresponding to the upper and lower
boundaries of $\Omega_1,$ respectively. We note that $\mathcal L_1$ and $\mathcal L_2$ are parametrized, respectively, as
\begin{equation*}
%\label{2.12}
\mathcal L_1:=\{k\in\mathbb C: k=zs \text{\rm{ for }}  s\in[0,+\infty)\},
\end{equation*}
\begin{equation*}
%\label{2.13}
\mathcal L_2:=\{k\in\mathbb C: k=z^2s \text{\rm{ for }}  s\in[0,+\infty)\}.
\end{equation*}
The left transmission coefficient $T_{\text{\rm{l}}}(k)$ is defined on $\overline{\Omega_1},$ the left primary reflection coefficient $L(k)$ is defined
on $\mathcal L_1,$ and the left secondary reflection coefficient $M(k)$ is defined on $\mathcal L_2.$  

The right Jost solution $g(k,x)$ is the solution to \eqref{1.1} satisfying the spacial asymptotics as $x\to -\infty$ given by
\begin{equation}\label{2.14}
\begin{cases}
g(k,x)=e^{kx}\left[1+o(1)\right],\\
\noalign{\medskip}
g'(k,x)=k\,e^{kx}\left[1+o(1)\right],\\
\noalign{\medskip}
g''(k,x)=k^2\,e^{kx}\left[1+o(1)\right],
\end{cases}
\end{equation}
and its $k$-domain is given by $\overline{\Omega_3}.$ The right scattering coefficients $T_{\text{\rm{r}}}(k),$ $R(k),$ $N(k)$ are defined via the spacial
asymptotics of $g(k,x)$ as $x\to +\infty$ given by
\begin{equation}\label{2.15}
g(k,x)=\begin{cases}
e^{kx}\,T_{\text{\rm{r}}}(k)^{-1}[1+o(1)]+e^{zkx}R(k)\,T_{\text{\rm{r}}}(k)^{-1}[1+o(1)], \qquad k\in \mathcal L_3,\\
\noalign{\medskip}
e^{kx}\,T_{\text{\rm{r}}}(k)^{-1}[1+o(1)], \qquad k\in \Omega_3,\\
\noalign{\medskip}
e^{kx}\,T_{\text{\rm{r}}}(k)^{-1}[1+o(1)]+e^{z^2 kx}N(k)\,T_{\text{\rm{r}}}(k)^{-1}[1+o(1)],\qquad k\in \mathcal L_4,
\end{cases}
\end{equation}
where $\mathcal L_3$ and $\mathcal L_4$ are the directed half lines shown in Figure~\ref{figure2.1} corresponding to the lower and upper
boundaries of $\Omega_3.$ We remark that $\mathcal L_3$ and $\mathcal L_4$ have the respective parametric representations given by
\begin{equation*}
%\label{2.16}
\mathcal L_3:=\{k\in\mathbb C: k=-zs \text{\rm{ for }}  s\in[0,+\infty)\},
\end{equation*}
\begin{equation*}
%\label{2.17}
\mathcal L_4:=\{k\in\mathbb C: k=-z^2s \text{\rm{ for }}  s\in[0,+\infty)\}.
\end{equation*}
The right transmission coefficient $T_{\text{\rm{r}}}(k)$ is defined in $\overline{\Omega_3},$ the right primary reflection coefficient $R(k)$ is defined
on $\mathcal L_3,$ and the right secondary reflection coefficient $N(k)$ is defined on $\mathcal L_4.$ 

The basic solution $m(k,x)$ to \eqref{1.1} has the $k$-domain $\overline{\Omega_2},$ and it satisfies the spacial asymptotics as $x\to +\infty$ given by
\begin{equation}\label{2.18}
m(k,x)=\begin{cases}
\begin{aligned}
e^{kx}&\,T_{\text{\rm{l}}}(z^2k)^{-1}\,T_{\text{\rm{r}}}(zk)
[1+o(1)]\\
&-e^{z^2kx}M(k)\,T_{\text{\rm{l}}}(k)^{-1} \,T_{\text{\rm{r}}}(zk)
[1+o(1)], \qquad k\in \mathcal L_2,
\end{aligned}\\
\noalign{\medskip}
e^{kx}\,T_{\text{\rm{l}}}(z^2k)^{-1}\,T_{\text{\rm{r}}}(zk)[1+o(1)], \qquad k\in \Omega_2,\\
\noalign{\medskip}
e^{kx}\,T_{\text{\rm{l}}}(z^2k)^{-1}\,T_{\text{\rm{r}}}(zk)[1+o(1)],\qquad k\in \mathcal L_3,
\end{cases}
\end{equation}
and it satisfies the spacial asymptotics as $x\to -\infty$ given by
\begin{equation}\label{2.19}
m(k,x)=\begin{cases}
e^{kx}[1+o(1)], \qquad k\in \mathcal L_2,\\
\noalign{\medskip}
e^{kx}[1+o(1)],  \qquad k\in \Omega_2,\\
\noalign{\medskip}
e^{kx}[1+o(1)]-e^{zkx}R(k)\,T_{\text{\rm{r}}}(k)^{-1}\,T_{\text{\rm{r}}}(zk)[1+o(1)],\qquad k\in \mathcal L_3.
\end{cases}
\end{equation}
Similarly, the basic solution $n(k,x)$ to \eqref{1.1} has the $k$-domain $\overline{\Omega_4},$ and it satisfies the spacial asymptotics as $x\to +\infty$
given by
\begin{equation}\label{2.20}
n(k,x)=\begin{cases}
\begin{aligned}
e^{kx}&\,T_{\text{\rm{l}}}(zk)^{-1}\,T_{\text{\rm{r}}}(z^2k)[1+o(1)]\\
&-e^{zkx}L(k)\,T_{\text{\rm{l}}}(k)^{-1}\,T_{\text{\rm{r}}}(z^2k)[1+o(1)], \qquad k\in \mathcal L_1,
\end{aligned}\\
\noalign{\medskip}
e^{kx}\,T_{\text{\rm{l}}}(z k)^{-1}\,T_{\text{\rm{r}}}(z^2k)[1+o(1)],\qquad k\in \Omega_4,\\
\noalign{\medskip}
e^{kx}\,T_{\text{\rm{l}}}(z k)^{-1}\,T_{\text{\rm{r}}}(z^2k)[1+o(1)],\qquad k\in \mathcal L_4,
\end{cases}
\end{equation}
and it has the spacial asymptotics as $x\to -\infty$ given by
\begin{equation}\label{2.21}
n(k,x)=\begin{cases}
 e^{kx}[1+o(1)], \qquad k\in \mathcal L_1,\\
\noalign{\medskip}
e^{kx}[1+o(1)], \qquad k\in \Omega_4,\\
\noalign{\medskip}
e^{kx}[1+o(1)]
-e^{z^2 kx}N(k)\,T_{\text{\rm{r}}}(k)^{-1}\,T_{\text{\rm{r}}}(z^2k)[1+o(1)],\qquad k\in \mathcal L_4.
\end{cases}
\end{equation}
%We refer the reader to \cite{ACTU2025,T2024} for the properties of the four solutions

The large $k$-asymptotics of the basic solutions $f(k,x),$ $g(k,x),$ $m(k,x),$ and $n(k,x),$ respectively, are given by
\begin{equation}\label{2.22}
f(k,x)=e^{kx}\left[1+O\left(\ds\frac{1}{k}\right)\right], \qquad  k\to\infty  \text{\rm{ in }} \overline{\Omega_1},
\end{equation}
\begin{equation}\label{2.23}
g(k,x)=e^{kx}\left[1+O\left(\ds\frac{1}{k}\right)\right], \qquad  k\to\infty  \text{\rm{ in }} \overline{\Omega_3},
\end{equation}
\begin{equation}\label{2.24}
m(k,x)=e^{kx}\left[1+O\left(\ds\frac{1}{k}\right)\right], \qquad  k\to\infty  \text{\rm{ in }} \overline{\Omega_2},
\end{equation}
\begin{equation}\label{2.25}
n(k,x)=e^{kx}\left[1+O\left(\ds\frac{1}{k}\right)\right], \qquad  k\to\infty  \text{\rm{ in }} \overline{\Omega_4}.
\end{equation}
Using the four basic solutions $f(k,x),$ $g(k,x),$ $m(k,x),$ and $n(k,x),$ we can form a fundamental set of three solutions at each $k$-value in the
complex $k$-plane, as shown in Figure~\ref{figure2.2}.

